$script:ScriptsFolder = ((Join-Path $script:AlexRoot "Scripts").Trim().TrimEnd('\') + '\')
$script:ScriptsLog = ((Join-Path $script:AlexRoot "Log").Trim().TrimEnd('\') + '\')
