$script:BmsExePath = Join-Path $script:BmsRootPath "BMS.exe"
$script:BmsToBizerbaPath = Join-Path $script:BmsRootPath "toBizerba"
$script:BmsTerminalsPath = Join-Path $script:BmsRootPath "terminals"
$script:BizStoreCardGenericInputPath = "C:\bizstorecard\bizerba\_fileIO\generic_data\in"
$script:UltraVncFolder = "C:\Users\Administrator\Documents\UltraVNC"

# ---------------------------------------------------------------------------------------------------
# SQL login used by the scheduled backup / automation tasks
# ---------------------------------------------------------------------------------------------------
$script:BackupSqlUser = "Tecnica"
$script:BackupSqlPass = "TB`$upp0rT"

# ===================================================================================================
#                                 SECTION: Storeman Folder Detection
# ---------------------------------------------------------------------------------------------------
# Description:
#   Resolves $BasePath, the storeman folder every store task works against, in three levels:
#     1) the local SMB share "storeman", IF Office\Dbs\INFO_*901_WIN.INI has a KeyString and a
#        KeyValidDate no older than 14 days                                  -> Production
#     2) the first configured test root that exists (C:\Storeman, D:\Storeman) -> Test fallback
#     3) a scan of every fixed drive's top level for a *storeman* folder with a Startup.ini,
#        preferring one that is published as a share                        -> Drive-scan fallback
#   A share whose key is older than 14 days is the dedicated KEY EXPIRED state: store data is
#   usually still there, only a re-key is needed (the GUI says so instead of "test mode").
#
# Variables:
#   - $BasePath                       the resolved storeman folder
#   - $script:IsTestEnvironment       $true for every non-production result
#   - $script:StoremanSource          'Production' | 'Test fallback' | 'Drive-scan fallback'
#   - $script:StoremanSourceReason    plain-language reason (banner tooltip, log, status bar)
#   - $script:StoremanKeyStale        KEY EXPIRED state
#   - $script:StoremanKeyDate         the stale KeyValidDate (KEY EXPIRED only)
#
# Notes:
#   - tests\TBS_Maintenance_SelfTest.ps1 runs this block verbatim, from the '$BasePath = $null'
#     line to the 'Selected (storeman) folder' line - keep both marker lines.
# ===================================================================================================
$BasePath = $null
$testPath = $script:StoremanRoots | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -First 1
if (-not $testPath) { $testPath = $script:PrimaryStoremanRoot }

# ---------------------------------------------------------------------------
# Test-environment awareness: remember WHICH storeman source we ended up with,
# so the GUI (banner badge, status bar, log) can clearly show that we are NOT
# running against the production share.
# ---------------------------------------------------------------------------
$script:IsTestEnvironment = $false
$script:StoremanSource = 'Production'
$script:StoremanSourceReason = "SMB share 'storeman' with valid key"
# Dedicated KEY EXPIRED state: the share + store data exist, but KeyValidDate is
# older than 14 days. Distinct from plain test mode because store data (folder +
# database) is usually STILL available there - the GUI says "re-key required"
# instead of "tasks unavailable".
$script:StoremanKeyStale = $false
$script:StoremanKeyDate = $null

# 1) Try local SMB share "storeman"
$share = $null
try
{
	$share = Get-SmbShare -ErrorAction Stop | Where-Object { $_.Name -ieq 'storeman' } | Select-Object -First 1
}
catch { $share = $null }

if ($share -and -not [string]::IsNullOrWhiteSpace($share.Path))
{
	# Find INFO file in share path
	$infoFile = Get-ChildItem -Path (Join-Path $share.Path 'Office\Dbs') -Filter 'INFO_*901_WIN.INI' -ErrorAction SilentlyContinue | Select-Object -First 1
	if ($infoFile)
	{
		# Read KeyString + KeyValidDate (inline)
		$keyString = ""
		$keyValid = $null

		try
		{
			$txt = Get-Content -Path $infoFile.FullName -Raw -ErrorAction Stop

			$mKey = [regex]::Match($txt, '(?im)^\s*KeyString\s*=\s*(.+?)\s*$')
			if ($mKey.Success) { $keyString = ($mKey.Groups[1].Value).Trim() }

			$mDt = [regex]::Match($txt, '(?im)^\s*KeyValidDate\s*=\s*(\d{2}/\d{2}/\d{4})\s*$')
			if ($mDt.Success)
			{
				try { $keyValid = [datetime]::ParseExact($mDt.Groups[1].Value, 'MM/dd/yyyy', $null) }
				catch { $keyValid = $null }
			}
		}
		catch { }

		# Key requirements for SHARE:
		#   - KeyString present
		#   - KeyValidDate exists and is NOT older than 14 days
		$hasKeyString = -not [string]::IsNullOrWhiteSpace($keyString)
		$minDate = (Get-Date).Date.AddDays(-14)
		$keyWithinLimit = ($keyValid -is [datetime]) -and ($keyValid.Date -ge $minDate)

		if ($hasKeyString -and $keyWithinLimit)
		{
			$BasePath = $share.Path
		}
		else
		{
			$script:IsTestEnvironment = $true
			$script:StoremanSource = 'Test fallback'
			if ($hasKeyString -and ($keyValid -is [datetime]))
			{
				# Key exists but is older than 14 days -> dedicated KEY EXPIRED state
				$script:StoremanKeyStale = $true
				$script:StoremanKeyDate = $keyValid
				$script:StoremanSourceReason = "SMB share 'storeman' exists with store data present, but KeyValidDate ($($keyValid.ToString('MM/dd/yyyy'))) is older than 14 days - re-key required"
				Write-Warning "Share 'storeman' found but KeyValidDate ($($keyValid.ToString('MM/dd/yyyy'))) is older than 14 days - re-key required. Falling back to ${testPath}."
			}
			elseif (-not $hasKeyString)
			{
				$script:StoremanSourceReason = "SMB share 'storeman' exists but its KeyString is missing"
				Write-Warning "Share 'storeman' found but KeyString is missing. Falling back to ${testPath} for testing."
			}
			else
			{
				$script:StoremanSourceReason = "SMB share 'storeman' exists but KeyValidDate is missing or unreadable"
				Write-Warning "Share 'storeman' found but KeyValidDate is missing or unreadable. Falling back to ${testPath} for testing."
			}
		}
	}
	else
	{
		$script:IsTestEnvironment = $true
		$script:StoremanSource = 'Test fallback'
		$script:StoremanSourceReason = "SMB share 'storeman' exists but Office\Dbs\INFO_*901_WIN.INI is missing"
		Write-Warning "Share 'storeman' found but INFO file missing. Falling back to ${testPath} for testing."
	}
}
else
{
	$script:IsTestEnvironment = $true
	$script:StoremanSource = 'Test fallback'
	$script:StoremanSourceReason = "no 'storeman' SMB share on this machine"
	Write-Warning "Storeman share 'storeman' not found. Falling back to configured test roots / drive scan."
}

# 2) Testing fallback (configured roots) -> 3) drive-scan fallback (ported from MiniGhost)
if (-not $BasePath)
{
	if ($testPath -and (Test-Path -LiteralPath $testPath))
	{
		$BasePath = $testPath

		# Defensive: make sure the test-environment flag is set no matter which
		# fallback branch we took
		if (-not $script:IsTestEnvironment)
		{
			$script:IsTestEnvironment = $true
			$script:StoremanSource = 'Test fallback'
			$script:StoremanSourceReason = "no 'storeman' SMB share on this machine"
		}

		# Optional: warn if the testing path still doesn't have INFO
		$testInfo = Get-ChildItem -Path (Join-Path $BasePath 'Office\Dbs') -Filter 'INFO_*901_WIN.INI' -ErrorAction SilentlyContinue | Select-Object -First 1
		if (-not $testInfo)
		{
			Write-Warning "Testing fallback selected (${testPath}) but INFO_*901_WIN.INI was not found. Running with limited functionality."
		}
	}
	else
	{
		# 3) FINAL FALLBACK (MiniGhost logic): scan every fixed drive for any
		# *storeman* folder that contains a Startup.ini, preferring the one
		# actually published as an SMB share.
		$script:IsTestEnvironment = $true
		$script:StoremanSource = 'Drive-scan fallback'
		Write-Warning "No 'storeman' SMB share and no existing C:\Storeman / D:\Storeman test root. Scanning all fixed drives for a *storeman* folder..."

		$storemanDirs = @()
		$fixedDrives = Get-PSDrive -PSProvider FileSystem | Where-Object { $_.Free -gt 0 -and $_.Root -match '^[A-Z]:\\$' }
		foreach ($drive in $fixedDrives)
		{
			# Case-insensitive match for any *storeman* variation in directory name
			$dirs = Get-ChildItem -Path "$($drive.Root)" -Directory -ErrorAction SilentlyContinue |
			Where-Object { $_.Name -imatch 'storeman' } |
			ForEach-Object {
				$candidatePath = Join-Path $_.FullName '\'
				$files = Get-ChildItem -Path $candidatePath -Filter 'Startup.ini' -ErrorAction SilentlyContinue
				if ($files) { $_ }
			}
			if ($dirs) { $storemanDirs += $dirs }
		}

		$scanned = $null
		if ($storemanDirs.Count -gt 0)
		{
			# Prefer a path that is actually shared as a Windows share
			$shares = Get-SmbShare -ErrorAction SilentlyContinue
			foreach ($dir in $storemanDirs)
			{
				if ($shares.Path -contains $dir.FullName)
				{
					$scanned = $dir
					break
				}
			}
			if (-not $scanned) { $scanned = $storemanDirs[0] }
		}

		if ($scanned)
		{
			$BasePath = $scanned.FullName
			$script:StoremanSourceReason = "no 'storeman' SMB share and no test root - found '$BasePath' by drive scan (Startup.ini present)"
			Write-Warning "Storeman folder found by drive scan: '$BasePath'. Running in test/fallback mode."
		}
		else
		{
			# Last resort: primary test root, explicitly flagged as missing
			$BasePath = $testPath
			$script:StoremanSourceReason += "; test root '$BasePath' does not exist and no *storeman* folder found by drive scan"
			Write-Warning "Could not locate any storeman folder containing 'storeman\Startup.ini'. Running with limited functionality."
		}
	}
}

Write-Host "Selected (storeman) folder: '$BasePath'" -ForegroundColor Magenta

# ===================================================================================================
#                                    SECTION: Store Paths
# ---------------------------------------------------------------------------------------------------
# Description:
#   Derives the storeman sub-paths and INI file locations from the resolved $BasePath.
#
# Variables:
#   - $script:BasePath / $script:OfficePath   (+ unscoped copies: older code reads both forms)
#   - $LoadPath, $StartupIniPath, $SystemIniPath, $DbsPath, $TempDir
#   - $WinIniPath       first Office\Dbs\INFO_*901_WIN.INI       ($null if none)
#   - $SmsStartIniPath  first Office\Dbs\INFO_*901_SMSStart.ini  ($null if none)
#   - $StoresqlFilePath %TEMP%\Server_Database_Maintenance.sqi (Process_Server / scheduling)
#   - $script:LocalHost this machine's name
# ===================================================================================================

$script:BasePath = $BasePath
$script:FunctionResults['StoremanPath'] = $BasePath
$OfficePath = Join-Path $BasePath "Office"
$script:OfficePath = $OfficePath
$LoadPath = Join-Path $OfficePath "Load"
$StartupIniPath = Join-Path $BasePath "Startup.ini"
$SystemIniPath = Join-Path $OfficePath "system.ini"
$DbsPath = Join-Path $OfficePath "Dbs"
$TempDir = [System.IO.Path]::GetTempPath()

$WinIniPath = $null
$SmsStartIniPath = $null
if (Test-Path -LiteralPath $DbsPath)
{
	$WinIniMatch = Get-ChildItem -Path $DbsPath -Filter 'INFO_*901_WIN.INI' -ErrorAction SilentlyContinue | Select-Object -First 1
	if ($WinIniMatch) { $WinIniPath = $WinIniMatch.FullName }
	$SmsStartIniMatch = Get-ChildItem -Path $DbsPath -Filter 'INFO_*901_SMSStart.ini' -ErrorAction SilentlyContinue | Select-Object -First 1
	if ($SmsStartIniMatch) { $SmsStartIniPath = $SmsStartIniMatch.FullName }
}

$StoresqlFilePath = Join-Path $TempDir "Server_Database_Maintenance.sqi"

$script:LocalHost = $env:COMPUTERNAME

# ===================================================================================================
#                              FUNCTION: Delete_Files
# ---------------------------------------------------------------------------------------------------
# Description:
#   Deletes files/folders under a directory (recursively), optionally only those matching
#   name patterns and never those matching exclusion patterns. Runs synchronously (with log
#   lines) or as a background job so the caller is not held up.
#
# Parameters:
#   - Path           [string]: directory to delete from (required)
#   - SpecifiedFiles [string[]]: name patterns to delete (wildcards); all items when omitted
#   - Exclusions     [string[]]: name patterns to keep (wildcards)
#   - AsJob          [switch]: run the deletion as a background job
#
# Returns:
#   Number of items deleted (synchronous), or the Start-Job job (AsJob).
#
# Notes:
#   - Patterns match item NAMES at any depth (Get-ChildItem -Include/-Exclude): an excluded
#     folder name does not protect the files inside it.
# ===================================================================================================

function Delete_Files
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory, Position = 0, HelpMessage = "The directory path where files and folders will be deleted.")]
		[ValidateNotNullOrEmpty()]
		[string]$Path,
		[Parameter(HelpMessage = "Specific file/folder patterns to delete. Wildcards supported.")]
		[string[]]$SpecifiedFiles,
		[Parameter(HelpMessage = "Patterns to exclude from deletion. Wildcards supported.")]
		[string[]]$Exclusions,
		[Parameter(HelpMessage = "Run the deletion as a background job.")]
		[switch]$AsJob
	)

	# The deletion itself - shared by the job and the synchronous path.
	# Returns -1 when the path does not exist, else the number of items deleted.
	$deleteBlock = {
		param ($Path, $SpecifiedFiles, $Exclusions)

		$rp = Resolve-Path -LiteralPath $Path -ErrorAction SilentlyContinue
		if (-not $rp) { return -1 }

		$gciParams = @{ Path = (Join-Path $rp.Path '*'); Recurse = $true; Force = $true; ErrorAction = 'SilentlyContinue' }
		if ($SpecifiedFiles -and $SpecifiedFiles.Count -gt 0) { $gciParams['Include'] = $SpecifiedFiles }
		if ($Exclusions -and $Exclusions.Count -gt 0) { $gciParams['Exclude'] = $Exclusions }

		$deletedCount = 0
		foreach ($it in @(Get-ChildItem @gciParams))
		{
			try
			{
				Remove-Item -LiteralPath $it.FullName -Force -Recurse -ErrorAction Stop
				$deletedCount++
			}
			catch { }
		}
		return $deletedCount
	}

	if ($AsJob)
	{
		$jobName = "DeleteFilesJob_{0}" -f (($Path -replace '[^A-Za-z0-9_-]', '_').Trim('_'))
		return Start-Job -Name $jobName -ScriptBlock $deleteBlock -ArgumentList $Path, $SpecifiedFiles, $Exclusions
	}

	try
	{
		$deletedCount = & $deleteBlock $Path $SpecifiedFiles $Exclusions
	}
	catch
	{
		Write_Log "An error occurred during deletion. $_" "red"
		return 0
	}

	if ($deletedCount -lt 0)
	{
		Write_Log "The specified path '$Path' does not exist." "red"
		return 0
	}
	if ($deletedCount -eq 0) { Write_Log "No items matched in '$Path'." "yellow" }
	Write_Log "Total items deleted: $deletedCount" "blue"
	return $deletedCount
}

# ===================================================================================================
#                              FUNCTION: Download_NSSM
# ---------------------------------------------------------------------------------------------------
# Description:
#   Ensures nssm.exe exists before any function installs or manages services. Can start a
#   hidden worker and return immediately (Background), wait for completion (Wait), or
#   run synchronously. Always publishes the NSSM paths and writes a status log per run.
#   Returns a hashtable @{ Success; Path; Note; Error; Log } describing the outcome.
#
# Parameters:
#   - ToolsRoot            [string]: tools root, defaults to $script:ToolsDir
#   - ForceDownload        [switch]: redownload even if nssm.exe already exists
#   - Background           [switch]: start a hidden worker and return immediately
#   - Wait                 [switch]: block until nssm.exe appears (or timeout)
#   - WaitTimeoutSeconds   [int]: max wait when -Wait is used (default 120)
#   - WaitPollMilliseconds [int]: poll interval when -Wait is used (default 250)
#   - ThrowOnFail          [switch]: throw instead of returning a failure result
#
# Variables:
#   - $script:NssmDir / $script:NssmExe: published NSSM locations
#   - $script:NssmDownloadLog: Download_NSSM_LOG.txt under the script log folder
#
# Writes:
#   - <ToolsRoot>\NSSM\nssm.exe and the status log file
# ===================================================================================================

function Download_NSSM
{
	[CmdletBinding()]
	param (
		# Where tools live. Defaults to the centralized script path configuration.
		[string]$ToolsRoot = $script:ToolsDir,
		# Force redownload even if nssm.exe already exists
		[switch]$ForceDownload,
		# Start download in background and RETURN immediately (non-blocking)
		[switch]$Background,
		# Wait until NSSM exists (blocks only when requested)
		[switch]$Wait,
		# Max wait time when -Wait is used
		[int]$WaitTimeoutSeconds = 120,
		# Poll rate when -Wait is used
		[int]$WaitPollMilliseconds = 250,
		# If you want failures to throw
		[switch]$ThrowOnFail
	)

	# Single log path (overwrite each run)
	$script:NssmDownloadLog = Join-Path $script:ScriptsLog 'Download_NSSM_LOG.txt'

	# ------------------------------------------------------------------------------------------------
	# Target paths
	# ------------------------------------------------------------------------------------------------
	$script:NssmDir = Join-Path $ToolsRoot 'NSSM'
	$script:NssmExe = Join-Path $script:NssmDir 'nssm.exe'

	# Publish paths for other functions
	if (-not $script:FunctionResults) { $script:FunctionResults = @{ } }
	$script:FunctionResults['NssmDir'] = $script:NssmDir
	$script:FunctionResults['NssmExe'] = $script:NssmExe

	# Ensure tools folders exist
	try
	{
		if (-not (Test-Path $ToolsRoot)) { New-Item -Path $ToolsRoot -ItemType Directory -Force | Out-Null }
		if (-not (Test-Path $script:NssmDir)) { New-Item -Path $script:NssmDir -ItemType Directory -Force | Out-Null }
	}
	catch
	{
		if ($ThrowOnFail) { throw "Download_NSSM: Failed creating tools folder(s). $($_.Exception.Message)" }
		return @{ Success = $false; Path = $script:NssmExe; Note = 'Tools folder create failed'; Error = $_.Exception.Message; Log = $script:NssmDownloadLog }
	}

	# Fast return if already present and not forcing
	if (-not $ForceDownload -and (Test-Path $script:NssmExe))
	{
		return @{ Success = $true; Path = $script:NssmExe; Note = 'Already present'; Log = $script:NssmDownloadLog }
	}

	# ------------------------------------------------------------------------------------------------
	# Download worker (source: src\Resources\Workers\Download_NSSM_Worker.ps1) - runs inline or in a
	# background runspace; writes only to the status log (overwritten each run)
	# ------------------------------------------------------------------------------------------------
	$downloadScriptText = @'
# ---------------------------------------------------------------------------------------------------
# NSSM download worker - embedded at build time into Download_NSSM ($downloadScriptText).
#   Runs in a 1-thread runspace (Download_NSSM -Background) or inline. Tries the fawno GitHub
#   mirror, then nssm.cc (Invoke-WebRequest -> BITS -> WebClient per URL), extracts, picks the
#   win64/win32 binary, copies it to NssmExe and checks it is > 50 KB.
#   Returns @{ Success; Path; Note; [Error] }; every step goes to LogFile (overwritten per run).
# ---------------------------------------------------------------------------------------------------
param(
	[string]$ToolsRoot,
	[bool]$ForceDownload,
	[string]$NssmDir,
	[string]$NssmExe,
	[string]$LogFile
)

$ErrorActionPreference = "Stop"

# Log writer (scriptblock, not a function)
$logLine = {
	param([string]$Line)
	try
	{
		$ts = (Get-Date -Format "M/d/yyyy h:mm:ss tt")
		("[{0}] {1}" -f $ts, $Line) | Add-Content -Path $LogFile -Encoding UTF8
	}
	catch { }
}

# Overwrite log at start (latest results only)
try { "" | Set-Content -Path $LogFile -Encoding UTF8 -Force } catch { }

& $logLine "Worker start"
& $logLine ("ToolsRoot = {0}" -f $ToolsRoot)
& $logLine ("NssmDir   = {0}" -f $NssmDir)
& $logLine ("NssmExe   = {0}" -f $NssmExe)

try
{
	# Ensure dirs exist
	if (-not (Test-Path $ToolsRoot)) { New-Item -Path $ToolsRoot -ItemType Directory -Force | Out-Null }
	if (-not (Test-Path $NssmDir))   { New-Item -Path $NssmDir   -ItemType Directory -Force | Out-Null }

	# If already present and not forcing
	if (-not $ForceDownload -and (Test-Path $NssmExe))
	{
		& $logLine "Already present. Done."
		return @{ Success = $true; Path = $NssmExe; Note = 'Already present' }
	}

	# TLS 1.2
	try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch { }

	$is64 = [Environment]::Is64BitOperatingSystem

	# URLs (multiple sources)
	$urls = @()
	if ($is64) { $urls += "https://github.com/fawno/nssm.cc/releases/download/v2.24.1/nssm-v2.24.1-Win64.zip" }
	else       { $urls += "https://github.com/fawno/nssm.cc/releases/download/v2.24.1/nssm-v2.24.1-Win32.zip" }
	$urls += "https://nssm.cc/release/nssm-2.24.zip"
	$urls += "https://nssm.cc/ci/nssm-2.24-101-g897c7ad.zip"

	# Temp workspace
	$tempRoot = Join-Path $env:TEMP ("NSSM_" + [Guid]::NewGuid().ToString("N"))
	$tempZip  = Join-Path $tempRoot "nssm.zip"
	$tempOut  = Join-Path $tempRoot "out"
	New-Item -Path $tempRoot -ItemType Directory -Force | Out-Null
	New-Item -Path $tempOut  -ItemType Directory -Force | Out-Null

	$downloaded = $false
	$lastErr    = ""

	foreach ($u in $urls)
	{
		& $logLine ("Trying URL: {0}" -f $u)

		# wipe old zip
		try { if (Test-Path $tempZip) { Remove-Item -Path $tempZip -Force -ErrorAction SilentlyContinue } } catch { }

		# Method 1: Invoke-WebRequest (timeout)
		try
		{
			Invoke-WebRequest -Uri $u -OutFile $tempZip -UseBasicParsing -TimeoutSec 20 -ErrorAction Stop

			# IMPORTANT FIX: parentheses so "-and" is an operator
			if ((Test-Path $tempZip) -and ((Get-Item $tempZip).Length -gt 0))
			{
				$downloaded = $true
				& $logLine "Download OK via Invoke-WebRequest"
				break
			}
		}
		catch
		{
			$lastErr = $_.Exception.Message
			& $logLine ("Invoke-WebRequest failed: {0}" -f $lastErr)
		}

		# Method 2: BITS (if available)
		try
		{
			if (Get-Command Start-BitsTransfer -ErrorAction SilentlyContinue)
			{
				Start-BitsTransfer -Source $u -Destination $tempZip -Priority Foreground -ErrorAction Stop

				# IMPORTANT FIX: parentheses so "-and" is an operator
				if ((Test-Path $tempZip) -and ((Get-Item $tempZip).Length -gt 0))
				{
					$downloaded = $true
					& $logLine "Download OK via BITS"
					break
				}
			}
		}
		catch
		{
			$lastErr = $_.Exception.Message
			& $logLine ("BITS failed: {0}" -f $lastErr)
		}

		# Method 3: WebClient fallback
		try
		{
			$wc = New-Object System.Net.WebClient
			$wc.DownloadFile($u, $tempZip)

			# IMPORTANT FIX: parentheses so "-and" is an operator
			if ((Test-Path $tempZip) -and ((Get-Item $tempZip).Length -gt 0))
			{
				$downloaded = $true
				& $logLine "Download OK via WebClient"
				break
			}
		}
		catch
		{
			$lastErr = $_.Exception.Message
			& $logLine ("WebClient failed: {0}" -f $lastErr)
		}
	}

	if (-not $downloaded)
	{
		try { Remove-Item -Path $tempRoot -Recurse -Force -ErrorAction SilentlyContinue } catch { }
		& $logLine ("RESULT: FAILED - Download failed from all sources. Last error: {0}" -f $lastErr)
		return @{ Success = $false; Path = $NssmExe; Note = 'Download failed'; Error = $lastErr }
	}

	# Unblock zip
	try { Unblock-File -Path $tempZip -ErrorAction SilentlyContinue } catch { }

	# Extract
	$extracted = $false
	try
	{
		Expand-Archive -Path $tempZip -DestinationPath $tempOut -Force -ErrorAction Stop
		$extracted = $true
		& $logLine "Extract OK via Expand-Archive"
	}
	catch
	{
		try
		{
			Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
			[System.IO.Compression.ZipFile]::ExtractToDirectory($tempZip, $tempOut)
			$extracted = $true
			& $logLine "Extract OK via ZipFile"
		}
		catch
		{
			$extracted = $false
			& $logLine ("Extract failed: {0}" -f $_.Exception.Message)
		}
	}

	if (-not $extracted)
	{
		try { Remove-Item -Path $tempRoot -Recurse -Force -ErrorAction SilentlyContinue } catch { }
		& $logLine "RESULT: FAILED - Extraction failed."
		return @{ Success = $false; Path = $NssmExe; Note = 'Extraction failed' }
	}

	# Find nssm.exe
	$exeCandidates = Get-ChildItem -Path $tempOut -Recurse -Filter "nssm.exe" -File -ErrorAction SilentlyContinue
	if (-not $exeCandidates -or $exeCandidates.Count -eq 0)
	{
		try { Remove-Item -Path $tempRoot -Recurse -Force -ErrorAction SilentlyContinue } catch { }
		& $logLine "RESULT: FAILED - nssm.exe not found in extracted content."
		return @{ Success = $false; Path = $NssmExe; Note = 'nssm.exe not found' }
	}

	# Choose proper binary
	$chosen = $null
	if ($is64)
	{
		$chosen = $exeCandidates | Where-Object { $_.FullName -match "(\\|/)(win64|x64|amd64)(\\|/)" } | Select-Object -First 1
		if (-not $chosen) { $chosen = $exeCandidates | Select-Object -First 1 }
	}
	else
	{
		$chosen = $exeCandidates | Where-Object { $_.FullName -match "(\\|/)(win32|x86|i386)(\\|/)" } | Select-Object -First 1
		if (-not $chosen) { $chosen = $exeCandidates | Select-Object -First 1 }
	}

	if (-not $chosen -or -not (Test-Path $chosen.FullName))
	{
		try { Remove-Item -Path $tempRoot -Recurse -Force -ErrorAction SilentlyContinue } catch { }
		& $logLine "RESULT: FAILED - Could not select a valid nssm.exe candidate."
		return @{ Success = $false; Path = $NssmExe; Note = 'Selection failed' }
	}

	& $logLine ("Selected: {0}" -f $chosen.FullName)

	# Copy to stable location
	Copy-Item -Path $chosen.FullName -Destination $NssmExe -Force -ErrorAction Stop

	# Validate
	if (-not (Test-Path $NssmExe) -or ((Get-Item $NssmExe).Length -lt 50KB))
	{
		try { Remove-Item -Path $tempRoot -Recurse -Force -ErrorAction SilentlyContinue } catch { }
		& $logLine ("RESULT: FAILED - Validation failed after copy to '{0}'." -f $NssmExe)
		return @{ Success = $false; Path = $NssmExe; Note = 'Validation failed' }
	}

	# Cleanup
	try { Remove-Item -Path $tempRoot -Recurse -Force -ErrorAction SilentlyContinue } catch { }

	& $logLine ("RESULT: SUCCESS - NSSM ready at {0}" -f $NssmExe)
	return @{ Success = $true; Path = $NssmExe; Note = 'Downloaded/Updated' }
}
catch
{
	& $logLine ("RESULT: FAILED - Unhandled exception: {0}" -f $_.Exception.Message)
	return @{ Success = $false; Path = $NssmExe; Note = 'Exception'; Error = $_.Exception.Message }
}
'@

	# ------------------------------------------------------------------------------------------------
	# Background job (in-process runspace) - avoids hidden spawned PowerShell that AV hates
	# ------------------------------------------------------------------------------------------------
	if ($Background)
	{
		# If a job is already running, don't start another
		if ($script:NssmDownloadJob -and $script:NssmDownloadJob.Handle -and (-not $script:NssmDownloadJob.Handle.IsCompleted))
		{
			return @{ Success = $true; Path = $script:NssmExe; Note = 'Already downloading in background'; Log = $script:NssmDownloadLog }
		}

		try
		{
			# Create a 1-thread runspace pool
			$pool = [RunspaceFactory]::CreateRunspacePool(1, 1)
			$pool.ApartmentState = 'MTA'
			$pool.ThreadOptions = 'ReuseThread'
			$pool.Open()

			$ps = [PowerShell]::Create()
			$ps.RunspacePool = $pool

			$null = $ps.AddScript($downloadScriptText)
			$null = $ps.AddArgument($ToolsRoot)
			$null = $ps.AddArgument([bool]$ForceDownload.IsPresent)
			$null = $ps.AddArgument($script:NssmDir)
			$null = $ps.AddArgument($script:NssmExe)
			$null = $ps.AddArgument($script:NssmDownloadLog)

			$handle = $ps.BeginInvoke()

			# Keep a handle so we can wait later if needed
			$script:NssmDownloadJob = @{
				PS	    = $ps
				Pool    = $pool
				Handle  = $handle
				Started = Get-Date
				Log	    = $script:NssmDownloadLog
				Exe	    = $script:NssmExe
			}

			# Return immediately unless -Wait is also requested
			if (-not $Wait)
			{
				return @{ Success = $true; Path = $script:NssmExe; Note = 'Started background download'; Log = $script:NssmDownloadLog }
			}
		}
		catch
		{
			if ($ThrowOnFail) { throw "Download_NSSM: Failed to start background runspace. $($_.Exception.Message)" }
			return @{ Success = $false; Path = $script:NssmExe; Note = 'Background start failed'; Error = $_.Exception.Message; Log = $script:NssmDownloadLog }
		}
	}

	# ------------------------------------------------------------------------------------------------
	# Wait mode (only blocks when asked). Waiting only makes sense while a background download
	# runs - without one, fall through to the synchronous download below instead of waiting
	# for a file nobody is fetching.
	# ------------------------------------------------------------------------------------------------
	$bgRunning = ($script:NssmDownloadJob -and $script:NssmDownloadJob.Handle -and -not $script:NssmDownloadJob.Handle.IsCompleted)
	if ($Wait -and $bgRunning)
	{
		# Wait for the download itself to finish (not just for the file to appear - it may still
		# be copying), keeping the window responsive.
		$job = $script:NssmDownloadJob
		$deadline = (Get-Date).AddSeconds($WaitTimeoutSeconds)
		while ((Get-Date) -lt $deadline -and -not $job.Handle.IsCompleted)
		{
			try { [System.Windows.Forms.Application]::DoEvents() }
			catch { }
			Start-Sleep -Milliseconds $WaitPollMilliseconds
		}

		if (-not $job.Handle.IsCompleted)
		{
			if ($ThrowOnFail) { throw "Download_NSSM: Timed out waiting for NSSM. Check log: $script:NssmDownloadLog" }
			return @{ Success = $false; Path = $script:NssmExe; Note = 'Timed out waiting for NSSM'; Log = $script:NssmDownloadLog }
		}

		$jobResult = $null
		try { $jobResult = @($job.PS.EndInvoke($job.Handle)) | Select-Object -Last 1 }
		catch { }
		try { $job.PS.Dispose(); $job.Pool.Close(); $job.Pool.Dispose() }
		catch { }
		$script:NssmDownloadJob = $null

		if (Test-Path -LiteralPath $script:NssmExe)
		{
			return @{ Success = $true; Path = $script:NssmExe; Note = 'NSSM ready'; Log = $script:NssmDownloadLog }
		}
		$why = if ($jobResult -and $jobResult.Note) { [string]$jobResult.Note } else { 'Download failed' }
		if ($ThrowOnFail) { throw "Download_NSSM: $why. Check log: $script:NssmDownloadLog" }
		return @{ Success = $false; Path = $script:NssmExe; Note = $why; Log = $script:NssmDownloadLog }
	}

	# ------------------------------------------------------------------------------------------------
	# Synchronous (blocking): no -Background, or -Wait with no background download running
	# ------------------------------------------------------------------------------------------------
	try
	{
		$sb = [ScriptBlock]::Create($downloadScriptText)
		$result = & $sb $ToolsRoot ([bool]$ForceDownload.IsPresent) $script:NssmDir $script:NssmExe $script:NssmDownloadLog

		if ($result -and $result.Success)
		{
			return @{ Success = $true; Path = $script:NssmExe; Note = $result.Note; Log = $script:NssmDownloadLog }
		}

		if ($ThrowOnFail) { throw "Download_NSSM: Failed. Check log: $script:NssmDownloadLog" }
		return @{ Success = $false; Path = $script:NssmExe; Note = 'Failed'; Log = $script:NssmDownloadLog }
	}
	catch
	{
		if ($ThrowOnFail) { throw "Download_NSSM: Exception. $($_.Exception.Message). Log: $script:NssmDownloadLog" }
		return @{ Success = $false; Path = $script:NssmExe; Note = 'Exception'; Error = $_.Exception.Message; Log = $script:NssmDownloadLog }
	}
}

# ===================================================================================================
#                              FUNCTION: Ensure_MailslotSender_Type
# ---------------------------------------------------------------------------------------------------
# Description:
#   Loads the C# MailslotSender type (kernel32 CreateFile/WriteFile) used for direct Windows
#   mailslot messaging. Idempotent: a PSTypeName guard makes repeat calls no-ops, and it is a
#   function (not a bare top-level block) so background jobs can load it too.
#
# Notes:
#   - Called once at script top; any job that receives its body can call it as well.
#   - Exposes [MailslotSender]::SendMailslotCommand(mailslotName, command).
# ===================================================================================================

function Ensure_MailslotSender_Type
{
	if (-not ([System.Management.Automation.PSTypeName]'MailslotSender').Type)
	{
		Add-Type -TypeDefinition @"
using System;
using System.Text;
using System.Runtime.InteropServices;

public class MailslotSender {
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Auto)]
    public static extern IntPtr CreateFile(
        string lpFileName,
        uint dwDesiredAccess,
        uint dwShareMode,
        IntPtr lpSecurityAttributes,
        uint dwCreationDisposition,
        uint dwFlagsAndAttributes,
        IntPtr hTemplateFile
    );

    [DllImport("kernel32.dll", SetLastError=true)]
    public static extern bool WriteFile(
        IntPtr hFile,
        byte[] lpBuffer,
        uint nNumberOfBytesToWrite,
        out uint lpNumberOfBytesWritten,
        IntPtr lpOverlapped
    );
        
    [DllImport("kernel32.dll")]
    public static extern bool CloseHandle(IntPtr hObject);

    public static bool SendMailslotCommand(string mailslotName, string command) {
        const uint GENERIC_WRITE = 0x40000000;
        const uint FILE_SHARE_READ = 0x00000001;
        const uint OPEN_EXISTING = 3;

        IntPtr hFile = CreateFile(mailslotName, GENERIC_WRITE, FILE_SHARE_READ, IntPtr.Zero, OPEN_EXISTING, 0, IntPtr.Zero);
        if (hFile == new IntPtr(-1)) {
            return false;
        }

        byte[] data = Encoding.ASCII.GetBytes(command);
        uint bytesWritten;
        bool success = WriteFile(hFile, data, (uint)data.Length, out bytesWritten, IntPtr.Zero);
        CloseHandle(hFile);
        return success;
    }
}
"@
	}
}

# ===================================================================================================
#                              FUNCTION: Get_Background_Function_Job_Result
# ---------------------------------------------------------------------------------------------------
# Description:
#   Polls a job created by Start_Background_Function_Job. Returns $null while the job is still
#   running. When it has finished, receives the result (before removing the job), merges the
#   job's FunctionResults and ExtraVars back into the live script scope and returns the
#   result object. Safe to call repeatedly.
#
# Parameters:
#   - Job  [Job]: the job object returned by Start_Background_Function_Job
#
# Variables:
#   - $script:BgfJobs: the job's registry entry is removed on completion
#
# Returns:
#   The job result object (Success/FunctionResults/ExtraVars/Error), or $null.
# ===================================================================================================

function Get_Background_Function_Job_Result
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[System.Management.Automation.Job]$Job
	)

	if (-not $Job) { return $null }
	if ($Job.State -in @('Running', 'NotStarted')) { return $null }

	$result = $null
	try { $result = @(Receive-Job -Job $Job -ErrorAction SilentlyContinue) | Select-Object -Last 1 } catch { }
	try { Remove-Job -Job $Job -Force -ErrorAction SilentlyContinue | Out-Null } catch { }

	if ($result)
	{
		if ($result.FunctionResults)
		{
			if (-not $script:FunctionResults) { $script:FunctionResults = @{} }
			foreach ($k in @($result.FunctionResults.Keys))
			{
				$script:FunctionResults[$k] = $result.FunctionResults[$k]
			}
		}
		if ($result.ExtraVars)
		{
			foreach ($k in @($result.ExtraVars.Keys))
			{
				Set-Variable -Scope Script -Name $k -Value $result.ExtraVars[$k] -Force
			}
		}
	}

	if ($script:BgfJobs -and $script:BgfJobs.ContainsKey($Job.Id))
	{
		$script:BgfJobs.Remove($Job.Id)
	}
	return $result
}

# ===================================================================================================
#                              FUNCTION: Normalize_Sql_ConnectionString
# ---------------------------------------------------------------------------------------------------
# Description:
#   Turns a stored connection string (or the Server/Database/User/Pwd parts) into one clean
#   SqlClient connection string. Treats 'N/A' placeholders as empty and always adds
#   TrustServerCertificate=True so older Windows builds can reach newer SQL servers.
#
# Parameters:
#   - RawConnectionString  [any]: value from FunctionResults (string, hashtable or object with .ConnectionString)
#   - Server               [string]: SQL server name (used when no usable connection string is stored)
#   - Database             [string]: database name (used when no usable connection string is stored)
#   - SqlUser              [string]: SQL login (used with Server/Database)
#   - SqlPwd               [string]: SQL login password (used with Server/Database)
#
# Returns:
#   The normalized connection string, or $null when nothing usable was given.
# ===================================================================================================

function Normalize_Sql_ConnectionString
{
	param (
		[Parameter(Mandatory = $false)]
		$RawConnectionString,
		[string]$Server,
		[string]$Database,
		[string]$SqlUser,
		[string]$SqlPwd
	)

	$connStr = $null
	try
	{
		if ($RawConnectionString -is [hashtable] -and $RawConnectionString.ContainsKey('ConnectionString'))
		{
			$connStr = [string]$RawConnectionString['ConnectionString']
		}
		elseif ($null -ne $RawConnectionString -and $RawConnectionString.PSObject -and $RawConnectionString.PSObject.Properties['ConnectionString'])
		{
			$connStr = [string]$RawConnectionString.ConnectionString
		}
		else
		{
			$connStr = [string]$RawConnectionString
		}
	}
	catch
	{
		try { $connStr = [string]$RawConnectionString } catch { $connStr = $null }
	}

	if (-not [string]::IsNullOrWhiteSpace($connStr))
	{
		$connStr = $connStr.Trim().Trim('"')
		if ($connStr -match '^\s*ConnectionString\s*=\s*(.+?)\s*$')
		{
			$connStr = $matches[1].Trim()
		}
	}

	if ([string]::IsNullOrWhiteSpace($connStr) -or $connStr -eq 'N/A' -or $connStr -eq 'System.Collections.Hashtable')
	{
		$connStr = $null
	}

	# Treat the 'N/A' placeholder the same as empty - otherwise this builds a
	# real connection string pointing at a SQL server literally named "N/A",
	# and every caller pays a full DNS/connect timeout (~15s at startup).
	$serverNorm = $Server
	$databaseNorm = $Database
	try
	{
		if ([string]$Server -eq 'N/A' -or [string]$Server -eq 'System.Collections.Hashtable') { $serverNorm = '' }
		if ([string]$Database -eq 'N/A' -or [string]$Database -eq 'System.Collections.Hashtable') { $databaseNorm = '' }
	}
	catch { }

	if (-not $connStr -and -not [string]::IsNullOrWhiteSpace($serverNorm) -and -not [string]::IsNullOrWhiteSpace($databaseNorm))
	{
		if (-not [string]::IsNullOrWhiteSpace($SqlUser) -and -not [string]::IsNullOrWhiteSpace($SqlPwd))
		{
			$connStr = "Server=${serverNorm};Database=${databaseNorm};User ID=$SqlUser;Password=$SqlPwd;TrustServerCertificate=True;"
		}
		else
		{
			$connStr = "Server=${serverNorm};Database=${databaseNorm};Integrated Security=SSPI;TrustServerCertificate=True;"
		}
	}

	# Append TrustServerCertificate=True when it is not set. Plain text on purpose: a
	# SqlConnectionStringBuilder would rewrite Server=/Database= to Data Source=/Initial Catalog=
	# (callers parse those), and PowerShell treats the builder as a dictionary, so
	# '$csb.ConnectionString = ...' throws instead of loading (setting a builder property needs
	# '$csb.PSBase.<Property> = ...') - before v2.7.0 that made this step a silent no-op.
	if (-not [string]::IsNullOrWhiteSpace($connStr) -and $connStr -notmatch '(?i)(^|;)\s*TrustServerCertificate\s*=')
	{
		$connStr = $connStr.TrimEnd().TrimEnd(';') + ';TrustServerCertificate=True;'
	}

	return $connStr
}

# ===================================================================================================
#                              FUNCTION: Select-FolderOrDefault
# ---------------------------------------------------------------------------------------------------
# Description:
#   Opens a folder picker (FolderBrowserDialog) pre-set to a starting folder and returns the
#   folder the user chose; if the user cancels it returns $null so the caller keeps its default.
#   Shared helper for the Local DB / Storeman ZIP / Lane DB backup schedulers' "Backup folder"
#   option, so the backup can be saved to the default location or a location of choice.
#
# Parameters:
#   - initialPath: folder the picker opens at (usually the default backup root)
#   - description: prompt text shown at the top of the picker
#
# Returns:
#   The chosen folder path, or $null if the user cancelled.
# ===================================================================================================

function Select-FolderOrDefault
{
	param
	(
		[string]$initialPath = "",
		[string]$description = "Choose a folder"
	)

	Add-Type -AssemblyName System.Windows.Forms
	$fd = New-Object System.Windows.Forms.FolderBrowserDialog
	$fd.Description = $description
	$fd.ShowNewFolderButton = $true
	if ($initialPath -and (Test-Path -LiteralPath $initialPath)) { $fd.SelectedPath = $initialPath }

	try
	{
		$res = $fd.ShowDialog()
		if ($res -eq [System.Windows.Forms.DialogResult]::OK -and $fd.SelectedPath) { return $fd.SelectedPath }
		return $null
	}
	finally { $fd.Dispose() }
}

# ===================================================================================================
#                              FUNCTION: Start_Background_Function_Job
# ---------------------------------------------------------------------------------------------------
# Description:
#   The one background-job builder for this script (v2.6.9). Runs a script function in a
#   background job without blocking the UI thread. The job receives the function code,
#   Write_Log, any dependent functions, a copy of the FunctionResults bag and seed variables,
#   and its results are merged back into the live script scope when it finishes.
#
# Parameters:
#   - FunctionName     [string]: function to run in the job (required)
#   - Label            [string]: shown in the status bar / logged while the job runs
#   - CallArgs         [hashtable]: named arguments splatted onto the function call
#   - SeedVars         [hashtable]: script variables the function reads (name -> value)
#   - ReturnVarNames   [string[]]: script variables the function writes back (names only)
#   - DependentBodies  [hashtable]: extra functions the target calls (name -> body text)
#   - OnComplete       [scriptblock]: run on the UI thread when the job completes
#   - NotifyOnComplete [switch]: box line when the job ends without a result
#
# Variables:
#   - $script:BgfJobs: registry of running jobs for the shared reaper timer
#
# Returns:
#   The Start-Job job object, or $null if the function was not found.
# ===================================================================================================

function Start_Background_Function_Job
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[string]$FunctionName,
		# shown in the status bar / logged while the job runs
		[string]$Label = '',
		# named arguments splatted onto the function call, e.g. @{ RefreshCache = $true }
		[hashtable]$CallArgs = @{},
		# extra script variables the function reads (name -> value), e.g. @{ SetupFiles = $script:SetupFiles }
		[hashtable]$SeedVars = @{},
		# script variables the function WRITES that must be handed back to the
		# main session (names only), e.g. @('LaneSQLScript', 'ServerSQLScript')
		[string[]]$ReturnVarNames = @(),
		# extra functions the target calls internally (name -> body text).
		# Write_Log is always passed, so the job can log like the main session.
		[hashtable]$DependentBodies = @{},
		# scriptblock run on the UI thread when the job completes; it receives
		# the result object (possibly $null). Used by warmup steps that must
		# hydrate state from the warm cache after the job's network work.
		[scriptblock]$OnComplete = $null,
		# mark the job as one whose abnormal finish ("ended without a result")
		# is worth a line in the log BOX. Normal success lines always go to the
		# file log only - the status bar covers progress, the box sees failures.
		[switch]$NotifyOnComplete
	)

	if (-not $CallArgs) { $CallArgs = @{} }
	if (-not $SeedVars) { $SeedVars = @{} }
	if (-not $ReturnVarNames) { $ReturnVarNames = @() }
	if (-not $DependentBodies) { $DependentBodies = @{} }
	if (-not $script:BgfJobs) { $script:BgfJobs = @{} }

	# NOTE: use Get-Command, NOT ${function:$FunctionName} - the variable-drive
	# syntax with a dynamic name does not resolve from inside a function body
	# under Windows PowerShell 5.1 (only literal names work there).
	$fnCmd = $null
	try { $fnCmd = Get-Command -Name $FunctionName -CommandType Function -ErrorAction SilentlyContinue } catch { }
	if (-not $fnCmd)
	{
		# NOTE: Out-Null keeps the return value clean even if a Write_Log
		# variant ever writes to the pipeline.
		try { Write_Log ("Start_Background_Function_Job: function '{0}' not found, cannot start job" -f $FunctionName) 'red' | Out-Null } catch { }
		return $null
	}
	$fnBody = $fnCmd.ScriptBlock.ToString()

	# Copy the results bag - the job must never mutate the live one. UI objects (the LogBox
	# entry, timers) are left out: they cannot be used in another runspace, serialising a
	# WinForms control into the job is slow, and the deserialised copy would be merged back
	# over the live entry when the job completes.
	$seedResults = @{}
	if ($script:FunctionResults)
	{
		foreach ($k in @($script:FunctionResults.Keys))
		{
			$v = $script:FunctionResults[$k]
			if ($v -is [System.ComponentModel.Component]) { continue }
			$seedResults[$k] = $v
		}
	}

	# Standard context every job needs so its Write_Log can find the file-log
	# folder and honour test mode. Callers do not have to remember this.
	$autoSeed = @{
		ScriptsLog        = $script:ScriptsLog
		IsTestEnvironment = $script:IsTestEnvironment
	}

	$job = Start-Job -Name ('bgf_' + $FunctionName) -ScriptBlock {
		param (
			[string]$FnName,
			[string]$FnBody,
			[hashtable]$Deps,
			[hashtable]$SeedResults,
			[hashtable]$SeedVars,
			[hashtable]$CallArgs,
			[string[]]$ReturnVarNames,
			[string]$WriteLogBody,
			[hashtable]$AutoSeed
		)

		Add-Type -AssemblyName System.Windows.Forms 2>$null
		Add-Type -AssemblyName System.Drawing 2>$null

		Set-Item -Path function:Write_Log -Value ([scriptblock]::Create($WriteLogBody))
		foreach ($depName in @($Deps.Keys))
		{
			Set-Item -Path ('function:' + $depName) -Value ([scriptblock]::Create($Deps[$depName]))
		}
		Set-Item -Path ('function:' + $FnName) -Value ([scriptblock]::Create($FnBody))

		$script:FunctionResults = @{ }
		foreach ($k in @($SeedResults.Keys)) { $script:FunctionResults[$k] = $SeedResults[$k] }
		foreach ($k in @($SeedVars.Keys))
		{
			Set-Variable -Scope Script -Name $k -Value $SeedVars[$k]
		}
		foreach ($k in @($AutoSeed.Keys))
		{
			if (-not (Get-Variable -Scope Script -Name $k -ValueOnly -ErrorAction SilentlyContinue))
			{
				Set-Variable -Scope Script -Name $k -Value $AutoSeed[$k]
			}
		}

		try
		{
			& (Get-Item -Path ('function:' + $FnName)) @CallArgs
			$extraVars = @{}
			foreach ($vn in $ReturnVarNames)
			{
				$vv = Get-Variable -Scope Script -Name $vn -ValueOnly -ErrorAction SilentlyContinue
				if ($null -ne $vv) { $extraVars[$vn] = $vv }
			}
			[pscustomobject]@{
				Success         = $true
				FunctionResults = $script:FunctionResults
				ExtraVars       = $extraVars
				Error           = $null
			}
		}
		catch
		{
			[pscustomobject]@{
				Success         = $false
				FunctionResults = $script:FunctionResults
				ExtraVars       = @{}
				Error           = $_.Exception.Message
			}
		}
	} -ArgumentList @(
		$FunctionName,
		$fnBody,
		$DependentBodies,
		$seedResults,
		$SeedVars,
		$CallArgs,
		$ReturnVarNames,
		${function:Write_Log}.ToString(),
		$autoSeed
	)

	if (-not $job)
	{
		Write_Log ("Start_Background_Function_Job: failed to start job for '{0}'" -f $FunctionName) 'red'
		return $null
	}

	$script:BgfJobs[$job.Id] = @{
		Job              = $job
		Label            = $Label
		Started          = Get-Date
		OnComplete       = $OnComplete
		NotifyOnComplete = [bool]$NotifyOnComplete
	}

	# v2.6.9: ONE shared reaper polls every background FUNCTION job on the
	# UI thread (1s tick), merges finished results and fires the job's
	# OnComplete callback (warmup hydration) or a one-line completion notice.
	# In hosts without a message pump (e.g. the selftest's child process) it
	# simply never ticks, and callers may poll Get_Background_Function_Job_Result
	# directly instead.
	# NOTE: the other timers in this script (ScaleCredReaper, VncExportReaper,
	# RemoteMachineInfoReaper, StartupScaleCredTimer, svcTimer) each manage an
	# INLINE job pool with local-variable closures and specialized collect
	# logic; they deliberately do not go through this engine. Migrating them
	# would mean restructuring those functions into the worker pattern -
	# considered and deferred (no performance gain, real regression risk).
	try
	{
		if (-not $script:BgfJobReaper)
		{
			$script:BgfJobReaper = New-Object System.Windows.Forms.Timer
			$script:BgfJobReaper.Interval = 1000
			$script:BgfJobReaper.Add_Tick({
					try
					{
						if (-not $script:BgfJobs -or $script:BgfJobs.Count -eq 0) { return }
						foreach ($key in @($script:BgfJobs.Keys))
						{
							$entry = $script:BgfJobs[$key]
							if (-not $entry -or -not $entry.Job) { continue }
							if ($entry.Job.State -in @('Running', 'NotStarted')) { continue }

							$result = $null
							try { $result = Get_Background_Function_Job_Result -Job $entry.Job } catch { }

							$secs = 0
							try { $secs = ((Get-Date) - $entry.Started).TotalSeconds } catch { }
							if ($result)
							{
								if ($result.Success)
								{
									# v2.6.9: success notices go to the FILE LOG ONLY (-FileOnly).
									# The status bar already shows what the app is doing in the
									# background, so the box stays quiet on success and only
									# sees failures (user preference).
									Write_Log ("Background job '{0}' finished in {1:N1}s" -f $entry.Label, $secs) 'blue' -FileOnly
								}
								else
								{
									Write_Log ("Background job '{0}' failed: {1}" -f $entry.Label, $result.Error) 'red'
								}
							}
							elseif ($entry.NotifyOnComplete)
							{
								Write_Log ("Background job '{0}' ended without a result" -f $entry.Label) 'yellow'
							}

							if ($entry.OnComplete)
							{
								try { & $entry.OnComplete $result } catch { }
							}
						}
					}
					catch { }
			})
			$script:BgfJobReaper.Start()
		}
	}
	catch { }
	return $job
}

# ===================================================================================================
#                              FUNCTION: Write_Log
# ---------------------------------------------------------------------------------------------------
# Description:
#   The single logging entry point of this script. Writes a line to the GUI log box (colored),
#   to the console while the box does not exist yet, and to the daily file log. Handles
#   cross-thread updates, test-mode rewording and repeat suppression.
#
# Parameters:
#   - Message          [string]: the line to log (required)
#   - Color            [any]: color name or System.Drawing.Color (default Black)
#   - IncludeTimestamp [switch]: prefix the line with a timestamp (off by default)
#   - Raw              [switch]: skip the presentation layer (severity tags, rewording,
#                                repeat suppression) - the startup summary formats itself
#   - FileOnly         [switch]: file log only - skip the box and the console (v2.6.9)
#
# Variables:
#   - $logBox / $script:LogBox / $global:LogBox / FunctionResults['LogBox']: the log control,
#     first valid one wins (GUI\05_Log_Area publishes all of them)
#   - $script:ScriptsLog: folder of the daily file log TBS_Maintenance_<yyyy-MM-dd>.log
#   - $script:IsTestEnvironment: enables the friendly test-mode rewording
#   - $script:LogSeen: line -> last time written (120 s repeat suppression)
#   - $script:WriteLogColors / $script:WriteLogFriendly: lookup tables, built on first use
#
# Notes:
#   - Shipped into background jobs as text (Start_Background_Function_Job), so it must stay
#     self-contained: everything it needs is created lazily inside it.
#   - File-log line format "HH:mm:ss [TAG] message" is checked by the self-test (section G).
# ===================================================================================================

function Write_Log
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[string]$Message,
		[Parameter(Mandatory = $false)]
		$Color = "Black",
		[Parameter(Mandatory = $false)]
		[switch]$IncludeTimestamp = $false,
		[Parameter(Mandatory = $false)]
		[switch]$Raw,
		[Parameter(Mandatory = $false)]
		[switch]$FileOnly
	)

	# ----------------------------------------------------------------------------------------------
	# Lookup tables (built once per session / job)
	# ----------------------------------------------------------------------------------------------
	if (-not $script:WriteLogColors)
	{
		$script:WriteLogColors = @{
			green   = @([System.Drawing.Color]::Green, 'Green', '[ OK ] ')
			red     = @([System.Drawing.Color]::Red, 'Red', '[FAIL] ')
			yellow  = @([System.Drawing.Color]::Goldenrod, 'Yellow', '[WARN] ')
			orange  = @([System.Drawing.Color]::Orange, 'Yellow', '[WARN] ')
			blue    = @([System.Drawing.Color]::DodgerBlue, 'Cyan', '[INFO] ')
			cyan    = @([System.Drawing.Color]::Cyan, 'Cyan', '[INFO] ')
			magenta = @([System.Drawing.Color]::Magenta, 'Magenta', '')
			gray    = @([System.Drawing.Color]::Gray, 'Gray', '')
			grey    = @([System.Drawing.Color]::Gray, 'Gray', '')
			white   = @([System.Drawing.Color]::White, 'White', '')
		}
		# Expected conditions in test mode (no storeman folder / store database): reworded
		# into calm explanations. In production the original text is kept - there these
		# conditions are real problems.
		# (hashtables, not nested arrays: @( @(a,b) <newline> @(c,d) ) flattens into one list)
		$script:WriteLogFriendly = @(
			@{ P = '^Startup\.ini path not provided'; T = 'Store config (Startup.ini) not found on this machine. Continuing without store/terminal details - expected in test mode.' }
			@{ P = '^WIN\.INI is unresolved'; T = 'Store info file (WIN.INI) not found. Continuing without store details - expected in test mode.' }
			@{ P = '^(No INFO_\*_WIN\.INI|No store info file)'; T = 'Store info file (INFO_*_WIN.INI) not found - expected in test mode.' }
			@{ P = '^Failed to retrieve counts from the database'; T = 'Store database is not reachable - expected in test mode. Lane/scale info will come from local files where available.' }
			@{ P = '\(Urgent Messages\) does not exist\.'; T = 'Urgent messages folder not found - expected in test mode (no storeman folder).' }
		)
	}

	# ----------------------------------------------------------------------------------------------
	# Colour: a System.Drawing.Color as given, or one of the names above (anything else = black)
	# ----------------------------------------------------------------------------------------------
	$colorName = ''
	if ($Color -is [System.Drawing.Color])
	{
		$selColor = $Color
	}
	else
	{
		$colorName = ([string]$Color).Trim().ToLower()
		$entry = $script:WriteLogColors[$colorName]
		$selColor = if ($entry) { $entry[0] } else { [System.Drawing.Color]::Black }
	}

	# ----------------------------------------------------------------------------------------------
	# Presentation layer (v2.6.8) - calmer, easier-to-read output (skipped with -Raw):
	#   1) test mode: known expected conditions are reworded (shown orange)
	#   2) raw .NET exception dumps are squashed to their message (~200 chars)
	#   3) a severity tag by colour: [ OK ] / [WARN] / [FAIL] / [INFO]
	#   4) identical lines are suppressed for 120 s (stops per-lane repeat spam)
	# ----------------------------------------------------------------------------------------------
	if (-not $Raw)
	{
		if ($script:IsTestEnvironment)
		{
			foreach ($fm in $script:WriteLogFriendly)
			{
				if ($Message -match $fm.P)
				{
					$Message = $fm.T
					$selColor = [System.Drawing.Color]::Orange
					break
				}
			}
		}

		if ($Message -match 'Exception calling "[^"]*" with "\d+" argument\(s\): "(.*)"')
		{
			$inner = $matches[1]
			if ($inner.Length -gt 200)
			{
				$cut = $inner.Substring(0, 200)
				$sp = $cut.LastIndexOf(' ')
				if ($sp -gt 120) { $cut = $cut.Substring(0, $sp) }
				$inner = $cut + '...'
			}
			$pre = $Message.Substring(0, $Message.IndexOf('Exception calling', [System.StringComparison]::Ordinal)).TrimEnd().TrimEnd(':').TrimEnd()
			$Message = if ($pre) { "${pre}: $inner" } else { $inner }
		}
		elseif ($Message.Length -gt 300)
		{
			$cut = $Message.Substring(0, 300)
			$sp = $cut.LastIndexOf(' ')
			if ($sp -gt 200) { $cut = $cut.Substring(0, $sp) }
			$Message = $cut + '...'
		}

		# Tag from the final colour (explicit -eq tests: switch() does not match Color values)
		$tag = ''
		if ($selColor -eq [System.Drawing.Color]::Green) { $tag = '[ OK ] ' }
		elseif ($selColor -eq [System.Drawing.Color]::Orange -or $selColor -eq [System.Drawing.Color]::Goldenrod) { $tag = '[WARN] ' }
		elseif ($selColor -eq [System.Drawing.Color]::Red) { $tag = '[FAIL] ' }
		elseif ($selColor -eq [System.Drawing.Color]::DodgerBlue -or $selColor -eq [System.Drawing.Color]::Cyan) { $tag = '[INFO] ' }

		if (-not $script:LogSeen) { $script:LogSeen = @{ } }
		if ($script:LogSeen.Count -gt 400) { $script:LogSeen.Clear() }
		$lineKey = $tag + $Message
		$nowT = [datetime]::Now
		if ($script:LogSeen.ContainsKey($lineKey) -and ($nowT - $script:LogSeen[$lineKey]).TotalSeconds -lt 120) { return }
		$script:LogSeen[$lineKey] = $nowT

		$Message = $tag + $Message
	}

	$fullMessage = if ($IncludeTimestamp) { "[{0:yyyy-MM-dd HH:mm:ss}] {1}" -f [datetime]::Now, $Message } else { $Message }

	# ----------------------------------------------------------------------------------------------
	# File log (v2.6.9): every line (shown or -FileOnly) is appended to
	#   <ScriptsLog>\TBS_Maintenance_<yyyy-MM-dd>.log
	# ReadWrite sharing because background jobs append at the same time. Silent on failure -
	# logging must never break maintenance work.
	# ----------------------------------------------------------------------------------------------
	try
	{
		$now = [datetime]::Now
		$logToday = $now.ToString('yyyy-MM-dd')
		if ($script:LogFileLogDate -ne $logToday)
		{
			$script:LogFileLogDate = $logToday
			$script:LogFileLogPath = Join-Path $script:ScriptsLog ("TBS_Maintenance_" + $logToday + ".log")
		}
		$logStream = [System.IO.File]::Open($script:LogFileLogPath, [System.IO.FileMode]::Append, [System.IO.FileAccess]::Write, [System.IO.FileShare]::ReadWrite)
		$logWriter = New-Object System.IO.StreamWriter($logStream)
		$logWriter.WriteLine($now.ToString('HH:mm:ss') + " " + $fullMessage)
		$logWriter.Close()
	}
	catch { }

	if ($FileOnly) { return }

	# ----------------------------------------------------------------------------------------------
	# Log box (cross-thread aware)
	# ----------------------------------------------------------------------------------------------
	$lb = $null
	foreach ($candidate in @($logBox, $script:LogBox, $global:LogBox))
	{
		if ($candidate -is [System.Windows.Forms.RichTextBox] -and -not $candidate.IsDisposed) { $lb = $candidate; break }
	}
	if (-not $lb -and $script:FunctionResults -and $script:FunctionResults.ContainsKey('LogBox'))
	{
		$tmp = $script:FunctionResults['LogBox']
		if ($tmp -is [System.Windows.Forms.RichTextBox] -and -not $tmp.IsDisposed) { $lb = $tmp }
	}

	if ($lb)
	{
		$uiWrite = {
			param ($rtb, $text, $color)
			try
			{
				if (-not $rtb -or $rtb.IsDisposed) { return }
				$rtb.SelectionStart = $rtb.TextLength
				$rtb.SelectionLength = 0
				$rtb.SelectionColor = $color
				$rtb.AppendText($text + "`r`n")
				$rtb.SelectionColor = $rtb.ForeColor
				$rtb.SelectionStart = $rtb.TextLength
				$rtb.ScrollToCaret()
			}
			catch { }
		}
		try
		{
			# BeginInvoke from other threads (never blocks, safe while closing)
			if ($lb.InvokeRequired) { [void]$lb.BeginInvoke($uiWrite, @($lb, $fullMessage, $selColor)) }
			else { & $uiWrite $lb $fullMessage $selColor }
			return
		}
		catch { }
	}

	# ----------------------------------------------------------------------------------------------
	# Console (before the log box exists, or if the box write failed)
	# ----------------------------------------------------------------------------------------------
	try
	{
		$entry = $script:WriteLogColors[$colorName]
		$consoleColor = if ($entry) { $entry[1] } else { 'White' }
		Write-Host $fullMessage -ForegroundColor $consoleColor
	}
	catch { }
}

# ===================================================================================================
#                              FUNCTION: Generate_SQL_Scripts
# ---------------------------------------------------------------------------------------------------
# Description:
#   Generates the SQL setup/maintenance scripts for lanes and the store server (memory
#   configuration, SQL user, schedules) from the current script variables. The five scripts are
#   held in $script: variables for the in-process consumers; nothing is written to disk.
#
# Parameters:
#   - StoreNumber  [string]: store number (normalized to 3 digits)
#
# Variables:
#   - $script:FunctionResults: reads ConnectionString/DBSERVER/DBNAME
#   - Writes $script:LaneSQLScript, $script:LaneSQLFiltered, $script:LaneSQLScript_Mailslot,
#     $script:ServerSQLScript and $script:ScheduleServerScript for the maintenance schedulers
# ===================================================================================================

function Generate_SQL_Scripts
{
	param (
		[string]$StoreNumber
	)

	if (-not $script:FunctionResults) { $script:FunctionResults = @{ } }

	# Normalize store number (existing behavior preserved: 3-digit format)
	if (-not [string]::IsNullOrWhiteSpace($StoreNumber) -and $StoreNumber -match '^\d+$')
	{
		$StoreNumber = ([int]$StoreNumber).ToString('000')
	}
	elseif (-not [string]::IsNullOrWhiteSpace($StoreNumber))
	{
		$StoreNumber = $StoreNumber.PadLeft(3, '0')
	}

	if (-not $script:FunctionResults.ContainsKey('ConnectionString'))
	{
		Write_Log "Failed to retrieve the connection string." "red"
		return
	}


	# ------------------------------------------------------------------------------------------------
	# Build scripts from CURRENT variables every time so the $script: content variables
	# always reflect the live connection/store context for the maintenance consumers.
	# ------------------------------------------------------------------------------------------------
	$ConnectionString = $script:FunctionResults['ConnectionString']
	$defaultStoreDbName = "STORESQL"
	$defaultLaneDbName = "LANESQL"
	$dbServer = $script:FunctionResults['DBSERVER']

	if ($script:FunctionResults.ContainsKey('DBNAME') -and -not [string]::IsNullOrWhiteSpace($script:FunctionResults['DBNAME']))
	{
		$storeDbName = $script:FunctionResults['DBNAME']
	}
	else
	{
		Write_Log "No 'DBNAME' in FunctionResults. Defaulting to '$defaultStoreDbName'." "yellow"
		$storeDbName = $defaultStoreDbName
	}

	$laneDbName = $defaultLaneDbName

	# ------------------ Lane script ------------------
	$LaneSQLScript = @"
/* Set a long timeout so the entire script runs */
@WIZRPL(DBASE_TIMEOUT=E);

/* Set memory configuration */
EXEC sp_configure 'show advanced options', 1;
RECONFIGURE;
EXEC sp_configure 'max server memory (MB)', 1024;
RECONFIGURE;
EXEC sp_configure 'show advanced options', 0;
RECONFIGURE;

/* Create "$BackupSqlUser" user in the database */
IF NOT EXISTS (SELECT 1 FROM sys.server_principals WHERE name = '$BackupSqlUser')
    CREATE LOGIN [$BackupSqlUser] WITH PASSWORD = '$BackupSqlPass', CHECK_POLICY = OFF;
IF NOT EXISTS (SELECT 1 FROM sys.database_principals WHERE name = '$BackupSqlUser')
    CREATE USER [$BackupSqlUser] FOR LOGIN [$BackupSqlUser];
IF IS_ROLEMEMBER('db_owner', '$BackupSqlUser') = 0
    EXEC sp_addrolemember 'db_owner', '$BackupSqlUser';

/* Truncate unnecessary tables */
IF OBJECT_ID('COST_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('COST_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE COST_REV;
IF OBJECT_ID('POS_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('POS_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE POS_REV;
IF OBJECT_ID('OBJ_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('OBJ_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE OBJ_REV;
IF OBJECT_ID('PRICE_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('PRICE_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE PRICE_REV;
IF OBJECT_ID('REV_HDR', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('REV_HDR', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE REV_HDR;
IF OBJECT_ID('SAL_REG_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_REG_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_REG_SAV;
IF OBJECT_ID('SAL_HDR_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_HDR_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_HDR_SAV;
IF OBJECT_ID('SAL_TTL_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_TTL_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_TTL_SAV;
IF OBJECT_ID('SAL_DET_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_DET_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_DET_SAV;

/* Truncate PRICE_EVENT table for records older than 7 days */
IF OBJECT_ID('PRICE_EVENT','U') IS NOT NULL AND HAS_PERMS_BY_NAME('PRICE_EVENT','OBJECT','DELETE') = 1 DELETE FROM PRICE_EVENT WHERE F254 < DATEADD(DAY,-7,GETDATE());

/* Drop specific tables older than 30 days */
DECLARE @cmd varchar(4000) 
DECLARE cmds CURSOR FOR 
SELECT 'drop table [' + name + ']' 
FROM sys.tables 
WHERE (name LIKE 'TMP_%' OR name LIKE 'MSVHOST%' OR name LIKE 'MMPHOST%' OR name LIKE 'M$StoreNumber%' OR name LIKE 'R$StoreNumber%') 
OPEN cmds 
WHILE 1 = 1 
BEGIN 
FETCH cmds INTO @cmd 
IF @@fetch_status != 0 BREAK 
EXEC(@cmd) 
END 
CLOSE cmds; 
DEALLOCATE cmds;

/* Cleaning HEADER_SAV */
IF OBJECT_ID('HEADER_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('HEADER_SAV', 'OBJECT', 'DELETE') = 1 
    DELETE FROM HEADER_SAV 
    WHERE (F903 = 'SVHOST' OR F903 = 'MPHOST' OR F903 = CONCAT('M', '$StoreNumber', '901')) 
    AND (DATEDIFF(DAY, F907, GETDATE()) > 30 OR DATEDIFF(DAY, F909, GETDATE()) > 30);

/* Delete bad SMS items */
@dbEXEC(DELETE FROM OBJ_TAB WHERE F01='0020000000000') 
@dbEXEC(DELETE FROM OBJ_TAB WHERE F01 LIKE '% %') 
@dbEXEC(DELETE FROM OBJ_TAB WHERE LEN(F01)<>13) 
@dbEXEC(DELETE FROM OBJ_TAB WHERE SUBSTRING(F01,1,3) = '002' AND SUBSTRING(F01,9,5) > '00000') 
@dbEXEC(DELETE FROM OBJ_TAB WHERE SUBSTRING(F01,1,3) = '002' AND ISNUMERIC(SUBSTRING(F01,4,5))=0 AND SUBSTRING(F01,9,5) = '00000') 
@dbEXEC(DELETE FROM POS_TAB WHERE F01 NOT IN (SELECT F01 FROM OBJ_TAB)) 
@dbEXEC(DELETE FROM PRICE_TAB WHERE F01 NOT IN (SELECT F01 FROM OBJ_TAB)) 
@dbEXEC(DELETE FROM COST_TAB WHERE F01 NOT IN (SELECT F01 FROM OBJ_TAB)) 
@dbEXEC(DELETE FROM SCL_TAB WHERE F01 NOT IN (SELECT F01 FROM OBJ_TAB)) 
@dbEXEC(DELETE FROM SCL_TAB WHERE SUBSTRING(F01,1,3) <> '002') 
@dbEXEC(DELETE FROM SCL_TAB WHERE SUBSTRING(F01,1,3) = '002' AND SUBSTRING(F01,9,5) > '00000') 
@dbEXEC(UPDATE SCL_TAB SET SCL_TAB.F267 = SCL_TXT.F267 FROM SCL_TAB SCL JOIN SCL_TXT_TAB SCL_TXT ON (SCL.F01=CONCAT('002',FORMAT(SCL_TXT.F267,'00000'),'00000'))) 
@dbEXEC(UPDATE SCL_TAB SET SCL_TAB.F268 = SCL_NUT.F268 FROM SCL_TAB SCL JOIN SCL_NUT_TAB SCL_NUT ON (SCL.F01=CONCAT('002',FORMAT(SCL_NUT.F268,'00000'),'00000'))) 
@dbEXEC(DELETE FROM SCL_TXT_TAB WHERE F267 NOT IN (SELECT F267 FROM SCL_TAB)) 
@dbEXEC(DELETE FROM SCL_NUT_TAB WHERE F268 NOT IN (SELECT F268 FROM SCL_TAB)) 
@dbEXEC(UPDATE SCL_TAB SET F267 = NULL WHERE F01 NOT IN (SELECT CONCAT('002',FORMAT(F267,'00000'),'00000') FROM SCL_TXT_TAB)) 
@dbEXEC(UPDATE SCL_TAB SET F268 = NULL WHERE F01 NOT IN (SELECT CONCAT('002',FORMAT(F268,'00000'),'00000') FROM SCL_NUT_TAB)) 
@dbEXEC(UPDATE SCL_TXT_TAB SET SCL_TXT_TAB.F04 = POS.F04 FROM SCL_TXT_TAB SCL_TXT JOIN POS_TAB POS ON (POS.F01=CONCAT('002',FORMAT(SCL_TXT.F267,'00000'),'00000')) WHERE ISNUMERIC(SCL_TXT.F04)=0) 
@dbEXEC(UPDATE SCL_TAB SET F256 = REPLACE(REPLACE(REPLACE(F256, CHAR(13),' '), CHAR(10),' '), CHAR(9),' ')) 
@dbEXEC(UPDATE SCL_TAB SET F1952 = REPLACE(REPLACE(REPLACE(F1952, CHAR(13),' '), CHAR(10),' '), CHAR(9),' ')) 
@dbEXEC(UPDATE SCL_TAB SET F2581 = REPLACE(REPLACE(REPLACE(F2581, CHAR(13),' '), CHAR(10),' '), CHAR(9),' ')) 
@dbEXEC(UPDATE SCL_TAB SET F2582 = REPLACE(REPLACE(REPLACE(F2582, CHAR(13),' '), CHAR(10),' '), CHAR(9),' ')) 
@dbEXEC(UPDATE SCL_TXT_TAB SET F297 = REPLACE(REPLACE(REPLACE(F297, CHAR(13),' '), CHAR(10),' '), CHAR(9),' '))

/* Delete batches older than 7 days from the lane */
DELETE FROM Header_bat WHERE F909 < DATEADD(day, -7, GETDATE());
DELETE FROM Header_dct WHERE F909 < DATEADD(day, -7, GETDATE());
DELETE FROM Header_old WHERE F909 < DATEADD(day, -7, GETDATE());
DELETE FROM Header_sav WHERE F909 < DATEADD(day, -7, GETDATE());

/* Rebuild indexes and update database statistics */
EXEC sp_MSforeachtable 'ALTER INDEX ALL ON ? REBUILD'
EXEC sp_MSforeachtable 'UPDATE STATISTICS ? WITH FULLSCAN'

/* Shrink the main database file */
DBCC SHRINKFILE ($laneDbName)

/* Shrink the database log file */
DBCC SHRINKFILE (${laneDbName}_Log)

/* Restrict the indefinite log file growth */
ALTER DATABASE $laneDbName SET RECOVERY SIMPLE

/* Clear the long database timeout */
@WIZCLR(DBASE_TIMEOUT);
"@

	$script:LaneSQLScript = $LaneSQLScript

	# ------------------ Filtered lane script ------------------
	$ServerMemoryConfig = @"
DECLARE @Memory25PercentMB BIGINT;
SELECT @Memory25PercentMB = (total_physical_memory_kb / 1024) * 25 / 100
FROM sys.dm_os_sys_memory;
EXEC sp_configure 'show advanced options', 1;
RECONFIGURE;
EXEC sp_configure 'max server memory (MB)', @Memory25PercentMB;
RECONFIGURE;
EXEC sp_configure 'show advanced options', 0;
RECONFIGURE;
"@

	$sectionPattern = '(?s)/\*\s*(?<SectionName>[^*/]+?)\s*\*/\s*(?<SQLCommands>(?:.(?!/\*)|.)*?)(?=(/\*|$))'
	$sectionsToSkip = @(
		'Set a long timeout so the entire script runs',
		'Clear the long database timeout'
	)

	$LaneSQLFiltered = ""
	# (not $matches - that is PowerShell's automatic -match result variable)
	$sectionMatches = [regex]::Matches($LaneSQLScript, $sectionPattern)

	foreach ($match in $sectionMatches)
	{
		$sectionName = $match.Groups['SectionName'].Value.Trim()
		$sqlCommands = $match.Groups['SQLCommands'].Value.Trim()

		if ($sectionsToSkip -contains $sectionName)
		{
			continue
		}
		elseif ($sectionName -eq 'Set memory configuration')
		{
			$LaneSQLFiltered += "/* $sectionName */`r`n$ServerMemoryConfig`r`n`r`n"
		}
		else
		{
			$sqlCommands = $sqlCommands -replace '@dbEXEC\((?:\"(.*)\"|(.*))\)', '$1$2'
			$LaneSQLFiltered += "/* $sectionName */`r`n$sqlCommands`r`n`r`n"
		}
	}

	$script:LaneSQLFiltered = $LaneSQLFiltered

	# ------------------ Mailslot-friendly lane script ------------------
	$lines = $script:LaneSQLScript -split "`r?`n"
	$macroPattern = '^\s*(@|/|\*)'

	$fixedLines = foreach ($line in $lines)
	{
		if ($line -match $macroPattern -or [string]::IsNullOrWhiteSpace($line))
		{
			$line
		}
		else
		{
			"@EXEC($line)"
		}
	}

	$script:LaneSQLScript_Mailslot = ($fixedLines -join "`r`n")

	# ------------------ Server script ------------------
	$ServerSQLScript = @"
/* Set memory configuration */
DECLARE @Memory25PercentMB BIGINT;
SELECT @Memory25PercentMB = (total_physical_memory_kb / 1024) * 25 / 100
FROM sys.dm_os_sys_memory;
EXEC sp_configure 'show advanced options', 1;
RECONFIGURE;
EXEC sp_configure 'max server memory (MB)', @Memory25PercentMB;
RECONFIGURE;
EXEC sp_configure 'show advanced options', 0;
RECONFIGURE;

/* Create "$BackupSqlUser" user in the database */
IF NOT EXISTS (SELECT 1 FROM sys.server_principals WHERE name = '$BackupSqlUser')
    CREATE LOGIN [$BackupSqlUser] WITH PASSWORD = '$BackupSqlPass', CHECK_POLICY = OFF;
IF NOT EXISTS (SELECT 1 FROM sys.database_principals WHERE name = '$BackupSqlUser')
    CREATE USER [$BackupSqlUser] FOR LOGIN [$BackupSqlUser];
IF IS_ROLEMEMBER('db_owner', '$BackupSqlUser') = 0
    EXEC sp_addrolemember 'db_owner', '$BackupSqlUser';

/* Create-Refresh ScaleCommApp Triggers */
IF OBJECT_ID('dbo.TBS_ITM_SMAppUPDATED', 'U') IS NULL
BEGIN
    CREATE TABLE dbo.TBS_ITM_SMAppUPDATED (
        Id INT IDENTITY(1,1) PRIMARY KEY,
        CodeF01 VARCHAR(13) NULL,
        Sent BIT NOT NULL DEFAULT 0,
        SentAt DATETIME NOT NULL DEFAULT GETDATE()
    );
END

IF EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.TBS_ITM_SMAppUPDATED') AND name = 'IDX_TBS_ITM_SMAppUPDATED_CodeF01')
    DROP INDEX IDX_TBS_ITM_SMAppUPDATED_CodeF01 ON dbo.TBS_ITM_SMAppUPDATED;
IF EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.TBS_ITM_SMAppUPDATED') AND name = 'IDX_TBS_ITM_SMAppUPDATED_Sent')
    DROP INDEX IDX_TBS_ITM_SMAppUPDATED_Sent ON dbo.TBS_ITM_SMAppUPDATED;
IF EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.TBS_ITM_SMAppUPDATED') AND name = 'IDX_TBS_ITM_SMAppUPDATED_SentAt')
    DROP INDEX IDX_TBS_ITM_SMAppUPDATED_SentAt ON dbo.TBS_ITM_SMAppUPDATED;

IF OBJECT_ID('dbo.SMApp_UpdateOBJ', 'TR') IS NOT NULL
    DROP TRIGGER dbo.SMApp_UpdateOBJ
GO
IF OBJECT_ID('dbo.SMApp_UpdatePOS', 'TR') IS NOT NULL
    DROP TRIGGER dbo.SMApp_UpdatePOS
GO
IF OBJECT_ID('dbo.SMApp_UpdatePrice', 'TR') IS NOT NULL
    DROP TRIGGER dbo.SMApp_UpdatePrice
GO
IF OBJECT_ID('dbo.SMApp_UpdateSCL_TXT', 'TR') IS NOT NULL
    DROP TRIGGER dbo.SMApp_UpdateSCL_TXT
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [dbo].[SMApp_UpdateOBJ]
   ON  [dbo].[OBJ_TAB]
   AFTER INSERT,UPDATE
AS 
BEGIN
       SET NOCOUNT ON;

	INSERT INTO dbo.TBS_ITM_SMAppUPDATED (CodeF01,Sent,SentAt)
	SELECT F01,0, GETDATE() FROM inserted WHERE SUBSTRING(F01,1,3) = '002' AND ISNUMERIC(SUBSTRING(F01,4,5))=1 AND SUBSTRING(F01,9,5) = '00000'
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [dbo].[SMApp_UpdatePOS]
   ON  [dbo].[POS_TAB]
   AFTER INSERT,UPDATE
AS 
BEGIN
		SET NOCOUNT ON;
		INSERT INTO dbo.TBS_ITM_SMAppUPDATED (CodeF01,Sent,SentAt)
		SELECT F01,0, GETDATE() FROM inserted WHERE SUBSTRING(F01,1,3) = '002' AND ISNUMERIC(SUBSTRING(F01,4,5))=1 AND SUBSTRING(F01,9,5) = '00000' 
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [dbo].[SMApp_UpdatePrice]
   ON  [dbo].[PRICE_TAB]
   AFTER INSERT,UPDATE
AS 
BEGIN
		SET NOCOUNT ON;
		INSERT INTO dbo.TBS_ITM_SMAppUPDATED (CodeF01,Sent,SentAt)
		SELECT F01,0, GETDATE() FROM inserted WHERE SUBSTRING(F01,1,3) = '002' AND ISNUMERIC(SUBSTRING(F01,4,5))=1 AND SUBSTRING(F01,9,5) = '00000' 
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [dbo].[SMApp_UpdateSCL_TXT]
ON [dbo].[SCL_TXT_TAB]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    INSERT INTO dbo.TBS_ITM_SMAppUPDATED (CodeF01, Sent, SentAt)
    SELECT
        '002' + RIGHT('00000' + CONVERT(varchar(5), inserted.F267), 5) + '00000',
        0,
        GETDATE()
    FROM inserted
    JOIN dbo.OBJ_TAB
        ON '002' + RIGHT('00000' + CONVERT(varchar(5), inserted.F267), 5) + '00000' = OBJ_TAB.F01
    WHERE SUBSTRING(OBJ_TAB.F01,1,3) = '002'
      AND ISNUMERIC(SUBSTRING(OBJ_TAB.F01,4,5)) = 1
      AND SUBSTRING(OBJ_TAB.F01,9,5) = '00000';
END
GO

CREATE INDEX IDX_TBS_ITM_SMAppUPDATED_CodeF01 ON dbo.TBS_ITM_SMAppUPDATED (CodeF01);
CREATE INDEX IDX_TBS_ITM_SMAppUPDATED_Sent ON dbo.TBS_ITM_SMAppUPDATED (Sent);
CREATE INDEX IDX_TBS_ITM_SMAppUPDATED_SentAt ON dbo.TBS_ITM_SMAppUPDATED (SentAt);
GO

/* Truncate unnecessary tables */
IF OBJECT_ID('COST_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('COST_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE COST_REV;
IF OBJECT_ID('POS_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('POS_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE POS_REV;
IF OBJECT_ID('OBJ_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('OBJ_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE OBJ_REV;
IF OBJECT_ID('PRICE_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('PRICE_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE PRICE_REV;
IF OBJECT_ID('REV_HDR', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('REV_HDR', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE REV_HDR;
IF OBJECT_ID('SAL_REG_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_REG_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_REG_SAV;
IF OBJECT_ID('SAL_HDR_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_HDR_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_HDR_SAV;
IF OBJECT_ID('SAL_TTL_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_TTL_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_TTL_SAV;
IF OBJECT_ID('SAL_DET_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_DET_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_DET_SAV;

/* Delete bad SMS items */
DELETE FROM OBJ_TAB WHERE F01='0020000000000';
DELETE FROM OBJ_TAB WHERE F01 LIKE '% %';
DELETE FROM OBJ_TAB WHERE LEN(F01)<>13;
DELETE FROM OBJ_TAB WHERE SUBSTRING(F01,1,3) = '002' AND SUBSTRING(F01,9,5) > '00000';
DELETE FROM OBJ_TAB WHERE SUBSTRING(F01,1,3) = '002' AND ISNUMERIC(SUBSTRING(F01,4,5))=0 AND SUBSTRING(F01,9,5) = '00000';
DELETE FROM POS_TAB WHERE F01 NOT IN (SELECT F01 FROM OBJ_TAB);
DELETE FROM PRICE_TAB WHERE F01 NOT IN (SELECT F01 FROM OBJ_TAB);
DELETE FROM COST_TAB WHERE F01 NOT IN (SELECT F01 FROM OBJ_TAB);
DELETE FROM SCL_TAB WHERE F01 NOT IN (SELECT F01 FROM OBJ_TAB);
DELETE FROM SCL_TAB WHERE SUBSTRING(F01,1,3) <> '002';
DELETE FROM SCL_TAB WHERE SUBSTRING(F01,1,3) = '002' AND SUBSTRING(F01,9,5) > '00000';
UPDATE SCL_TAB SET SCL_TAB.F267 = SCL_TXT.F267 ,SCL_TAB.F1001=1 FROM SCL_TAB SCL JOIN SCL_TXT_TAB SCL_TXT ON (SCL.F01=CONCAT('002',FORMAT(SCL_TXT.F267,'00000'),'00000'));
UPDATE SCL_TAB SET SCL_TAB.F268 = SCL_NUT.F268 ,SCL_TAB.F1001=1 FROM SCL_TAB SCL JOIN SCL_NUT_TAB SCL_NUT ON (SCL.F01=CONCAT('002',FORMAT(SCL_NUT.F268,'00000'),'00000'));
DELETE FROM SCL_TXT_TAB WHERE F267 NOT IN (SELECT F267 FROM SCL_TAB);
DELETE FROM SCL_NUT_TAB WHERE F268 NOT IN (SELECT F268 FROM SCL_TAB);
UPDATE SCL_TAB SET F267 = NULL, F1001 = 1 WHERE F01 NOT IN (SELECT CONCAT('002',FORMAT(F267,'00000'),'00000') FROM SCL_TXT_TAB);
UPDATE SCL_TAB SET F268 = NULL, F1001 = 1 WHERE F01 NOT IN (SELECT CONCAT('002',FORMAT(F268,'00000'),'00000') FROM SCL_NUT_TAB);
UPDATE SCL_TXT_TAB SET SCL_TXT_TAB.F04 = POS.F04, SCL_TXT_TAB.F1001=1 FROM SCL_TXT_TAB SCL_TXT JOIN POS_TAB POS ON (POS.F01=CONCAT('002',FORMAT(SCL_TXT.F267,'00000'),'00000')) WHERE ISNUMERIC(SCL_TXT.F04)=0;
UPDATE SCL_TAB SET F256 = REPLACE(REPLACE(REPLACE(F256, CHAR(13),' '), CHAR(10),' '), CHAR(9),' ');
UPDATE SCL_TAB SET F1952 = REPLACE(REPLACE(REPLACE(F1952, CHAR(13),' '), CHAR(10),' '), CHAR(9),' ');
UPDATE SCL_TAB SET F2581 = REPLACE(REPLACE(REPLACE(F2581, CHAR(13),' '), CHAR(10),' '), CHAR(9),' ');
UPDATE SCL_TAB SET F2582 = REPLACE(REPLACE(REPLACE(F2582, CHAR(13),' '), CHAR(10),' '), CHAR(9),' ');
UPDATE SCL_TXT_TAB SET F297 = REPLACE(REPLACE(REPLACE(F297, CHAR(13),' '), CHAR(10),' '), CHAR(9),' ');

/* Truncate PRICE_EVENT table for records older than 7 days */
IF OBJECT_ID('PRICE_EVENT','U') IS NOT NULL AND HAS_PERMS_BY_NAME('PRICE_EVENT','OBJECT','DELETE') = 1 DELETE FROM PRICE_EVENT WHERE F254 < DATEADD(DAY,-7,GETDATE());

/* Drop specific tables older than 30 days */
DECLARE @cmd varchar(4000);
DECLARE cmds CURSOR FOR
SELECT 'drop table [' + name + ']'
FROM sys.tables
WHERE (name LIKE 'TMP_%' OR name LIKE 'MSVHOST%' OR name LIKE 'MMPHOST%' OR name LIKE 'M$StoreNumber%' OR name LIKE 'R$StoreNumber%') AND DATEDIFF(DAY, create_date, GETDATE()) > 30;
OPEN cmds;
WHILE 1 = 1
BEGIN
    FETCH cmds INTO @cmd;
    IF @@fetch_status != 0 BREAK;
    EXEC(@cmd);
END;
CLOSE cmds;
DEALLOCATE cmds;

/* Rebuild indexes and update database statistics */
EXEC sp_MSforeachtable 'ALTER INDEX ALL ON ? REBUILD';
EXEC sp_MSforeachtable 'UPDATE STATISTICS ? WITH FULLSCAN';

/* Set DB to highest compatibility level supported by this SQL Server version */
DECLARE @ProductVersion varchar(128), @MajorVersion int, @CompatLevel int, @sql nvarchar(4000);
SET @ProductVersion = CONVERT(varchar(128), SERVERPROPERTY('ProductVersion'));
SET @MajorVersion = CONVERT(int, LEFT(@ProductVersion, CHARINDEX('.', @ProductVersion + '.') - 1));
SET @CompatLevel = CASE @MajorVersion WHEN 17 THEN 170 WHEN 16 THEN 160 WHEN 15 THEN 150 WHEN 14 THEN 140 WHEN 13 THEN 130 WHEN 12 THEN 120 WHEN 11 THEN 110 WHEN 10 THEN 100 WHEN 9 THEN 90 ELSE NULL END;
IF @CompatLevel IS NOT NULL
BEGIN
    SET @sql = N'ALTER DATABASE ' + QUOTENAME(N'$storeDbName') + N' SET COMPATIBILITY_LEVEL = ' + CONVERT(varchar(3), @CompatLevel);
    EXEC(@sql);
END

/* Shrink the main database file */
DBCC SHRINKFILE ($storeDbName);

/* Shrink the database log file */
DBCC SHRINKFILE (${storeDbName}_Log);

/* Restrict the indefinite log file growth */
ALTER DATABASE $storeDbName SET RECOVERY SIMPLE;
"@

	$script:ServerSQLScript = $ServerSQLScript

	# ------------------ Scheduled maintenance server script ------------------
	$ScheduleServerScript = @"
/* Set a long timeout so the entire script runs */
@WIZRPL(DBASE_TIMEOUT=E);

/* Set memory configuration */
EXEC sp_configure 'show advanced options', 1;
RECONFIGURE;
EXEC sp_configure 'max server memory (MB)', 8192;
RECONFIGURE;
EXEC sp_configure 'show advanced options', 0;
RECONFIGURE;

/* Truncate unnecessary tables */
IF OBJECT_ID('COST_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('COST_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE COST_REV;
IF OBJECT_ID('POS_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('POS_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE POS_REV;
IF OBJECT_ID('OBJ_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('OBJ_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE OBJ_REV;
IF OBJECT_ID('PRICE_REV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('PRICE_REV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE PRICE_REV;
IF OBJECT_ID('REV_HDR', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('REV_HDR', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE REV_HDR;
IF OBJECT_ID('SAL_REG_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_REG_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_REG_SAV;
IF OBJECT_ID('SAL_HDR_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_HDR_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_HDR_SAV;
IF OBJECT_ID('SAL_TTL_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_TTL_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_TTL_SAV;
IF OBJECT_ID('SAL_DET_SAV', 'U') IS NOT NULL AND HAS_PERMS_BY_NAME('SAL_DET_SAV', 'OBJECT', 'ALTER') = 1 TRUNCATE TABLE SAL_DET_SAV;

/* Drop specific tables older than 30 days */
DECLARE @cmd varchar(4000) 
DECLARE cmds CURSOR FOR 
SELECT 'drop table [' + name + ']' 
FROM sys.tables 
WHERE (name LIKE 'TMP_%' OR name LIKE 'MSVHOST%' OR name LIKE 'MMPHOST%' OR name LIKE 'M$StoreNumber%' OR name LIKE 'R$StoreNumber%') 
OPEN cmds 
WHILE 1 = 1 
BEGIN 
FETCH cmds INTO @cmd 
IF @@fetch_status != 0 BREAK 
EXEC(@cmd) 
END 
CLOSE cmds; 
DEALLOCATE cmds;

/* Shrink database and log files */
EXEC sp_MSforeachtable 'ALTER INDEX ALL ON ? REBUILD'
EXEC sp_MSforeachtable 'UPDATE STATISTICS ? WITH FULLSCAN'
DBCC SHRINKFILE ($storeDbName)
DBCC SHRINKFILE (${storeDbName}_Log)
ALTER DATABASE $storeDbName SET RECOVERY SIMPLE

/* Clear the long database timeout */
@WIZCLR(DBASE_TIMEOUT);
"@

	$script:ScheduleServerScript = $ScheduleServerScript


}

# ===================================================================================================
#                              FUNCTION: Get_All_Lanes_Database_Info
# ---------------------------------------------------------------------------------------------------
# Description:
#   Collects per-lane SQL details (machine name, DB server, DB name) for every lane of the
#   store. Uses in-memory results first, then the per-function cache file, and only queries
#   the lanes when both are missing or -RefreshCache is set. With -LaneNumber it returns
#   that lane's info object.
#
# Parameters:
#   - LaneNumber   [string]: return only this lane's data (3-digit, padded)
#   - RefreshCache [switch]: force re-query and cache rewrite
#
# Variables:
#   - $script:FunctionResults['LaneDatabaseInfo']: per-lane info bucket (output)
#   - $script:FunctionResults['LaneNumToMachineName']: lane -> machine map (input)
#
# Returns:
#   The requested lane's info object; nothing for a full-store refresh.
#
# Writes:
#   - Setup_Files\Get_All_Lanes_Database_Info.txt (JSON cache, ordered by lane number)
# ===================================================================================================

function Get_All_Lanes_Database_Info
{
	param (
		[string]$LaneNumber,
		[switch]$RefreshCache
	)

	# Ensure bucket exists (unchanged behavior)
	if (-not $script:FunctionResults.ContainsKey('LaneDatabaseInfo'))
	{
		$script:FunctionResults['LaneDatabaseInfo'] = @{ }
	}
	$LaneDatabaseInfo = $script:FunctionResults['LaneDatabaseInfo']

	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	if (-not $LaneNumToMachineName) { return $null }

	# Guard against null OfficePath causing Join-Path errors (fast fail, no guessing)
	if ([string]::IsNullOrWhiteSpace($OfficePath)) { return $null }

	# ------------------------------------------------------------------------------------------------
	# Per-function cache file (only run queries if memory/file data is missing or -RefreshCache is used)
	# ------------------------------------------------------------------------------------------------
	$CachePath = Join-Path $script:SetupFiles 'Get_All_Lanes_Database_Info.txt'

	# Normalize LaneNumber if provided (keep it simple + safe)
	$RequestedLane = $null
	if ($LaneNumber)
	{
		$digits = ($LaneNumber -replace '[^\d]', '')
		if ($digits) { $RequestedLane = $digits.PadLeft(3, '0') }
	}

	if (-not $RefreshCache)
	{
		# Reuse in-memory data first
		if ($RequestedLane -and $LaneDatabaseInfo.ContainsKey($RequestedLane))
		{
			return $LaneDatabaseInfo[$RequestedLane]
		}
		if ((-not $RequestedLane) -and $LaneDatabaseInfo.Count -gt 0)
		{
			return
		}

		# Reuse file cache if present
		if ($CachePath -and (Test-Path $CachePath))
		{
			try
			{
				$raw = Get-Content -LiteralPath $CachePath -Raw -ErrorAction Stop
				if (-not [string]::IsNullOrWhiteSpace($raw))
				{
					$cacheObj = $raw | ConvertFrom-Json -ErrorAction Stop
					if ($cacheObj -and $cacheObj.PSObject.Properties.Name -contains 'LaneDatabaseInfo' -and $cacheObj.LaneDatabaseInfo)
					{
						foreach ($p in $cacheObj.LaneDatabaseInfo.PSObject.Properties)
						{
							if (-not $LaneDatabaseInfo.ContainsKey($p.Name))
							{
								# Same shape as a fresh lookup (hashtable): callers index it as
								# $info['TcpConnStr'], which returns nothing on a PSCustomObject
								$laneHash = @{ }
								if ($p.Value -and $p.Value.PSObject) { foreach ($q in $p.Value.PSObject.Properties) { $laneHash[$q.Name] = $q.Value } }
								# Caches written before v2.7.0 lack TrustServerCertificate
								foreach ($k in @('ConnectionString', 'NamedPipesConnStr', 'TcpConnStr'))
								{
									if ($laneHash[$k] -and $laneHash[$k] -notmatch '(?i)TrustServerCertificate') { $laneHash[$k] = ([string]$laneHash[$k]).TrimEnd(';') + ';TrustServerCertificate=True;' }
								}
								$LaneDatabaseInfo[$p.Name] = $laneHash
							}
						}
					}
				}
			}
			catch { }

			if ($RequestedLane)
			{
				if ($LaneDatabaseInfo.ContainsKey($RequestedLane)) { return $LaneDatabaseInfo[$RequestedLane] }
			}
			elseif ($LaneDatabaseInfo.Count -gt 0)
			{
				return
			}
		}
	}

	# ------------------------------------------------------------------------------------------------
	# Memory/file cache is missing/unreadable, or caller requested -RefreshCache => query lanes ONCE, then write file
	# ------------------------------------------------------------------------------------------------
	$lanesToProcess = @()

	# Always build a full cache when missing
	$lanesToProcess += $LaneNumToMachineName.Keys

	# Ensure requested lane is included even if it would normally be skipped in "full mode"
	if ($RequestedLane) { $lanesToProcess = @($RequestedLane) + $lanesToProcess }

	# De-dupe + keep only numeric 3-digit lanes
	$lanesToProcess = $lanesToProcess | ForEach-Object {
		$d = ($_.ToString() -replace '[^\d]', '')
		if ($d) { $d.PadLeft(3, '0') }
	} | Where-Object { $_ } | Select-Object -Unique

	$changed = $false

	foreach ($laneNumber in $lanesToProcess)
	{
		# If cached already in memory, skip
		if ($LaneDatabaseInfo.ContainsKey($laneNumber)) { continue }

		# 8xx (scales) and 9xx (server / backoffices) are not lanes - unless explicitly requested
		if ($laneNumber -ne $RequestedLane -and $laneNumber -match '^(8|9)') { continue }

		$machineName = $LaneNumToMachineName[$laneNumber]
		if (-not $machineName) { continue }

		# ---------- 1. Try LOCAL Startup file (INI\STARTUP.###) ----------
		$startupLocalPath = Join-Path $OfficePath "INI\STARTUP.$($laneNumber.PadLeft(3, '0'))"
		$startupIniPath = $null
		$content = $null
		$source = $null

		if (Test-Path $startupLocalPath)
		{
			try
			{
				$content = Get-Content -Path $startupLocalPath -ErrorAction Stop
				$source = "local"
			}
			catch { $content = $null }
		}

		# ---------- 2. Fallback: Try REMOTE Startup.ini ----------
		if (-not $content)
		{
			$startupIniPath = "\\$machineName\storeman\Startup.ini"
			$remoteShareReachable = $false
			$tcpClient = New-Object System.Net.Sockets.TcpClient
			try
			{
				$asyncResult = $tcpClient.BeginConnect($machineName, 445, $null, $null)
				if ($asyncResult.AsyncWaitHandle.WaitOne(1500))
				{
					$tcpClient.EndConnect($asyncResult)
					$remoteShareReachable = $true
				}
			}
			catch { $remoteShareReachable = $false }
			finally { $tcpClient.Dispose() }

			if ($remoteShareReachable -and (Test-Path $startupIniPath))
			{
				try
				{
					$content = Get-Content -Path $startupIniPath -ErrorAction Stop
					$source = "remote"
				}
				catch { $content = $null }
			}
		}

		if (-not $content) { continue }

		# First line only: a second DBNAME= line would turn the value into an array
		$dbNameLine = $content | Where-Object { $_ -match '^DBNAME=' } | Select-Object -First 1
		$dbServerLine = $content | Where-Object { $_ -match '^DBSERVER=' } | Select-Object -First 1

		if ($dbNameLine)
		{
			$dbName = ($dbNameLine -replace '^DBNAME=', '').Trim()
		}
		else
		{
			continue
		}

		if ($dbServerLine)
		{
			$dbServerRaw = ($dbServerLine -replace '^DBSERVER=', '').Trim()
		}
		else
		{
			$dbServerRaw = ""
		}

		# -------------- PATCH: Remove trailing backslash unless a named instance is present --------------
		if ($dbServerRaw -match '^[^\\]+\\$')
		{
			$dbServerRaw = $dbServerRaw.TrimEnd('\')
		}
		# PATCH: If (LOCAL) or localhost (any case), replace with actual machine name
		if ($dbServerRaw -match '^(?i)\(LOCAL\)$' -or $dbServerRaw -match '^(?i)localhost$' -or $dbServerRaw -eq "")
		{
			$dbServer = $machineName
		}
		else
		{
			$dbServer = $dbServerRaw
		}
		# END PATCH --------------------------------------------------------------------------------------

		# Parse instance name for Named Pipes/TCP logic
		$serverName = $dbServer
		$instanceName = $null
		if ($dbServer -match '\\')
		{
			$parts = $dbServer -split '\\'
			$serverName = $parts[0]
			$instanceName = $parts[1]
		}
		elseif ($dbServer -match ',')
		{
			$serverName = $dbServer
			$instanceName = $null
		}
		else
		{
			$serverName = $dbServer
			$instanceName = $null
		}

		# Build connection strings
		if ($instanceName -and $instanceName.ToUpper() -ne "MSSQLSERVER")
		{
			$namedPipes = "np:\\$serverName\pipe\MSSQL`$$instanceName\sql\query"
			$tcpServer = "$serverName\$instanceName"
		}
		else
		{
			$namedPipes = "np:\\$serverName\pipe\sql\query"
			$tcpServer = $serverName
		}

		# TrustServerCertificate: SqlServer module 22+ encrypts by default and the lanes use
		# self-signed certificates, so without it every Invoke-Sqlcmd to a lane is refused
		$tcpConnStr = "Server=$tcpServer;Database=$dbName;Integrated Security=True;TrustServerCertificate=True;"
		$namedPipesConnStr = "Server=$namedPipes;Database=$dbName;Integrated Security=True;TrustServerCertificate=True;"
		$simpleConnStr = "Server=$dbServer;Database=$dbName;Integrated Security=True;TrustServerCertificate=True;"

		$laneInfo = @{
			'MachineName'	    = $machineName
			'DBName'		    = $dbName
			'DBServer'		    = $dbServer
			'ServerName'	    = $serverName
			'InstanceName'	    = $instanceName
			'NamedPipes'	    = $namedPipes
			'TcpServer'		    = $tcpServer
			'ConnectionString'  = $simpleConnStr
			'NamedPipesConnStr' = $namedPipesConnStr
			'TcpConnStr'	    = $tcpConnStr
			'Source'		    = $source
		}

		$LaneDatabaseInfo[$laneNumber] = $laneInfo
		$changed = $true
	}

	# ------------------------------------------------------------------------------------------------
	# Write cache ONCE (only if we found anything new)
	#   IMPORTANT: Write LaneDatabaseInfo ordered by lane number for clean file output.
	# ------------------------------------------------------------------------------------------------
	if ($CachePath -and $changed)
	{
		try
		{
			# Build an ORDERED view for file output only (keep in-memory as normal hashtable for .ContainsKey())
			$orderedLaneDb = [ordered]@{ }
			$sortedLaneKeys = @($LaneDatabaseInfo.Keys) | Sort-Object { [int]($_) }
			foreach ($k in $sortedLaneKeys)
			{
				$orderedLaneDb[$k] = $LaneDatabaseInfo[$k]
			}

			$cacheOut = [pscustomobject]@{
				LastUpdated = (Get-Date).ToString('o')
				LaneDatabaseInfo = $orderedLaneDb
			}

			($cacheOut | ConvertTo-Json -Depth 12) | Set-Content -LiteralPath $CachePath -Encoding UTF8 -Force
		}
		catch { }
	}

	# Return behavior (same intent as original):
	if ($RequestedLane)
	{
		if ($LaneDatabaseInfo.ContainsKey($RequestedLane)) { return $LaneDatabaseInfo[$RequestedLane] }
		return $null
	}
}

# ===================================================================================================
#                              FUNCTION: Get_Store_And_Database_Info
# ---------------------------------------------------------------------------------------------------
# Description:
#   Reads store identity and SQL connection details (store name, address, SMS version, key
#   number, DB server, database, connection string) from the Storeman INI files, preferring
#   in-memory results, then the cache file; re-parses only when missing or -RefreshCache.
#
# Parameters:
#   - WinIniPath      [string]: path to INFO_*901_WIN.INI
#   - SmsStartIniPath [string]: path to INFO_*901_SMSStart.ini
#   - StartupIniPath  [string]: path to the Storeman Startup.ini
#   - SystemIniPath   [string]: path to the Storeman system.ini
#   - RefreshCache    [switch]: force re-parse and cache rewrite
#
# Variables:
#   - $script:FunctionResults: receives StoreNumber, DBSERVER, DBNAME, ConnectionString,
#     SMSVersionFull, SqlModuleName and friends
#
# Writes:
#   - Setup_Files\Get_Store_And_Database_Info.txt (JSON cache)
#
# Notes:
#   - The SQL module is detected only when the store data is (re)parsed - a cache hit keeps the
#     cached SqlModuleName (Get-Module -ListAvailable is slow).
#   - Updates the GUI labels even on a cache hit (finally block).
#   - StoreNumber / Terminal are 3-digit padded when numeric (1 -> 001).
# ===================================================================================================

function Get_Store_And_Database_Info
{
	param (
		[string]$WinIniPath,
		[string]$SmsStartIniPath,
		[string]$StartupIniPath,
		[string]$SystemIniPath,
		[switch]$RefreshCache
	)

	# ------------------------------------------------------------------------------------------------
	# Cache (per-function file) - only re-run if memory/file data is missing/unreadable or -RefreshCache is used
	# ------------------------------------------------------------------------------------------------
	$CachePath = Join-Path $script:SetupFiles 'Get_Store_And_Database_Info.txt'
	$fields = @(
		'StoreNumber', 'StoreName', 'CompanyName', 'Terminal', 'Address', 'City', 'State',
		'SMSVersionFull', 'StampDate', 'StampTime', 'KeyNumber',
		'DBSERVER', 'DBNAME', 'ConnectionString', 'ResolvedWinIniPath'
	)

	if (-not $script:FunctionResults) { $script:FunctionResults = @{ } }

	# try/finally: the GUI labels update even when a cache hit returns early
	try
	{
		$availableSqlModule = $null
		try
		{
			if (
				$script:FunctionResults.ContainsKey('SqlModuleName') -and
				-not [string]::IsNullOrWhiteSpace([string]$script:FunctionResults['SqlModuleName']) -and
				([string]$script:FunctionResults['SqlModuleName'] -ne 'N/A')
			)
			{
				$availableSqlModule = [string]$script:FunctionResults['SqlModuleName']
			}
		}
		catch { $availableSqlModule = $null }

		if (-not $RefreshCache)
		{
			# Reuse in-memory values if they are already populated for this launch
			$hasInMemoryResults = $true
			foreach ($field in @('StoreNumber', 'StoreName', 'DBSERVER', 'DBNAME', 'ConnectionString', 'SMSVersionFull'))
			{
				if (
					-not $script:FunctionResults.ContainsKey($field) -or
					[string]::IsNullOrWhiteSpace([string]$script:FunctionResults[$field]) -or
					([string]$script:FunctionResults[$field] -eq 'N/A')
				)
				{
					$hasInMemoryResults = $false
					break
				}
			}
			if ($hasInMemoryResults)
			{
				return
			}

			# Reuse file cache if present
			if ($CachePath -and (Test-Path $CachePath))
			{
				try
				{
					$raw = Get-Content -LiteralPath $CachePath -Raw -ErrorAction Stop
					if (-not [string]::IsNullOrWhiteSpace($raw))
					{
						$cache = $raw | ConvertFrom-Json -ErrorAction Stop
						if ($cache -and $cache.Results)
						{
							foreach ($p in $cache.Results.PSObject.Properties)
							{
								$script:FunctionResults[$p.Name] = $p.Value
							}
							return
						}
					}
				}
				catch { }
			}
		}

		if ([string]::IsNullOrWhiteSpace($availableSqlModule) -or $availableSqlModule -eq 'N/A')
		{
			try
			{
				$loadedSqlModule = Get-Module SqlServer, SQLPS | Select-Object -First 1
				if ($loadedSqlModule) { $availableSqlModule = [string]$loadedSqlModule.Name }
			}
			catch { }
		}
		if ([string]::IsNullOrWhiteSpace($availableSqlModule) -or $availableSqlModule -eq 'N/A')
		{
			try
			{
				if (Get-Module -ListAvailable -Name SqlServer | Select-Object -First 1) { $availableSqlModule = "SqlServer" }
				elseif (Get-Module -ListAvailable -Name SQLPS | Select-Object -First 1) { $availableSqlModule = "SQLPS" }
				else { $availableSqlModule = "None" }
			}
			catch
			{
				$availableSqlModule = if ($availableSqlModule) { $availableSqlModule }
				else { "None" }
			}
		}
		$script:FunctionResults['SqlModuleName'] = $availableSqlModule

		# ------------------------------------------------------------------------------------------------
		# Initialize results with N/A for every expected property (+ resolved WIN.INI path)
		# ------------------------------------------------------------------------------------------------
		foreach ($f in $fields) { $script:FunctionResults[$f] = 'N/A' }

		# ==================================================================================================
		# Parse Startup.ini first to learn STORE and TER and to derive likely DBs folder(s)
		# ==================================================================================================
		$startupStore = $null
		$startupTer = $null
		$probableDbsRoots = @()

		if ($StartupIniPath -and (Test-Path $StartupIniPath))
		{
			try
			{
				foreach ($line in Get-Content -LiteralPath $StartupIniPath)
				{
					$t = $line.Trim()
					if ($t.StartsWith(';')) { continue }

					if ($t -match '^\s*STORE\s*=\s*(\d+)\s*$')
					{
						$startupStore = ([int]$Matches[1]).ToString('000')
					}
					elseif ($t -match '^\s*TER\s*=\s*(\d+)\s*$')
					{
						$startupTer = ([int]$Matches[1]).ToString('000')
					}
				}

				if ($startupStore)
				{
					$script:FunctionResults['StoreNumber'] = $startupStore
					if ($startupTer) { $script:FunctionResults['Terminal'] = $startupTer }
				}
				else
				{
					Write_Log "STORE= not found in Startup.ini. Will still attempt WIN.INI path resolution." "yellow"
				}

				$storemanRoot = Split-Path -Path $StartupIniPath -Parent
				if ($storemanRoot)
				{
					$derivedOffice = Join-Path $storemanRoot 'office'
					$derivedDbs = Join-Path $derivedOffice 'dbs'
					if (Test-Path $derivedDbs) { $probableDbsRoots += $derivedDbs }
				}
			}
			catch
			{
				Write_Log "Error parsing Startup.ini: $($_.Exception.Message)" "red"
			}
		}
		else
		{
			Write_Log "Startup.ini path not provided or not found. Skipping STORE/TER pre-resolution." "yellow"
		}

		foreach ($fallback in $script:StoremanOfficeDbsFallbacks)
		{
			if (Test-Path -LiteralPath $fallback) { $probableDbsRoots += $fallback }
		}
		$probableDbsRoots = $probableDbsRoots | Sort-Object -Unique

		# ==================================================================================================
		# Resolve correct INFO_*_WIN.INI matching Startup.ini STORE/TER
		# ==================================================================================================
		$resolvedWinIni = $null
		$needResolve = $true

		if ($WinIniPath -and (Test-Path $WinIniPath))
		{
			$name = [System.IO.Path]::GetFileName($WinIniPath)
			if ($name -match '^INFO_(\d{3})(\d{3})_WIN\.INI$')
			{
				$suppliedStore = $Matches[1]
				$suppliedTer = $Matches[2]
				$storeOk = -not $startupStore -or ($suppliedStore -eq $startupStore)
				$terOk = -not $startupTer -or ($suppliedTer -eq $startupTer)
				if ($storeOk -and $terOk)
				{
					$resolvedWinIni = $WinIniPath
					$needResolve = $false
				}
				else
				{
					Write_Log "Provided WIN.INI '$name' does not coincide with Startup.ini (STORE=$startupStore TER=$startupTer). Will search for the correct one." "yellow"
				}
			}
			else
			{
				Write_Log "Provided WIN.INI name '$name' does not match expected pattern 'INFO_SSSLLL_WIN.INI'. Will search for the correct one." "yellow"
			}
		}

		if ($needResolve -and $probableDbsRoots.Count -gt 0)
		{
			try
			{
				$candidates = foreach ($root in $probableDbsRoots)
				{
					Get-ChildItem -LiteralPath $root -Filter 'INFO_*_WIN.INI' -File -ErrorAction SilentlyContinue
				}

				$scored = @(
					foreach ($f in $candidates)
					{
						$m = [System.Text.RegularExpressions.Regex]::Match($f.Name, '^INFO_(\d{3})(\d{3})_WIN\.INI$')
						if (-not $m.Success) { continue }

						$s = $m.Groups[1].Value
						$t = $m.Groups[2].Value

						$score = 0
						if ($startupStore -and $s -eq $startupStore) { $score += 10 }
						if ($startupTer -and $t -eq $startupTer) { $score += 5 }
						if (-not $startupTer -and $t -eq '901') { $score += 3 }

						[PSCustomObject]@{
							File  = $f
							Store = $s
							Ter   = $t
							Score = $score
							Age   = $f.LastWriteTimeUtc
						}
					}
				) | Sort-Object -Property @{ Expression = 'Score'; Descending = $true }, @{ Expression = 'Age'; Descending = $true }

				if ($scored -and $scored[0].Score -gt 0)
				{
					$resolvedWinIni = $scored[0].File.FullName
				}
				elseif ($scored)
				{
					$resolvedWinIni = ($scored | Sort-Object -Property Age -Descending | Select-Object -First 1).File.FullName
				}
				else
				{
					Write_Log "No INFO_*_WIN.INI candidates found under: $($probableDbsRoots -join '; ')" "red"
				}
			}
			catch
			{
				Write_Log "Error while resolving WIN.INI: $($_.Exception.Message)" "red"
			}
		}

		if ($resolvedWinIni)
		{
			$WinIniPath = $resolvedWinIni
			$script:FunctionResults['ResolvedWinIniPath'] = $resolvedWinIni
		}
		else
		{
			if (-not ($WinIniPath -and (Test-Path $WinIniPath)))
			{
				Write_Log "WIN.INI is unresolved; continuing without store metadata from WIN.INI." "red"
			}
			else
			{
				$script:FunctionResults['ResolvedWinIniPath'] = $WinIniPath
				Write_Log "Proceeding with provided WIN.INI (unvalidated): $WinIniPath" "yellow"
			}
		}

		# ------------------------------------------------------------------------------------------------
		# Extract Store Info from WIN.INI
		# ------------------------------------------------------------------------------------------------
		if ($WinIniPath -and (Test-Path $WinIniPath))
		{
			$currentSection = ""
			foreach ($line in Get-Content -LiteralPath $WinIniPath)
			{
				$trimmed = $line.Trim()
				if ($trimmed -match '^\[(.+)\]$') { $currentSection = $Matches[1]; continue }
				if ($trimmed -notmatch "=" -or $trimmed.StartsWith(";")) { continue }

				$parts = $trimmed -split "=", 2
				$key = $parts[0].Trim()
				$value = $parts[1].Trim()

				switch ($currentSection)
				{
					"ORIGIN" {
						if ($key -ieq "StampDate") { $script:FunctionResults['StampDate'] = $value }
						if ($key -ieq "StampTime") { $script:FunctionResults['StampTime'] = $value }
					}
					"SYSTEM" {
						if ($key -ieq "CompanyName") { $script:FunctionResults['CompanyName'] = $value }
						if ($key -ieq "Store") { $script:FunctionResults['StoreNumber'] = if ($value -match '^\d+$') { ([int]$value).ToString('000') } else { $value } }
						if ($key -ieq "Terminal") { $script:FunctionResults['Terminal'] = if ($value -match '^\d+$') { ([int]$value).ToString('000') } else { $value } }
					}
					"STOREDETAIL" {
						if ($key -ieq "Name") { $script:FunctionResults['StoreName'] = $value }
						if ($key -ieq "Address") { $script:FunctionResults['Address'] = $value }
						if ($key -ieq "City") { $script:FunctionResults['City'] = $value }
						if ($key -ieq "State") { $script:FunctionResults['State'] = $value }
					}
					"KEY" {
						if ($key -ieq "KeyNumber") { $script:FunctionResults['KeyNumber'] = $value }
					}
					"Versions" {
						if ($key -ieq "VersionIni") { $script:FunctionResults['SMSVersionFull'] = $value }
					}
				}
			}
		}
		else
		{
			if ([string]::IsNullOrWhiteSpace($WinIniPath))
			{
				Write_Log "No store info file (INFO_*_WIN.INI) found - no storeman folder detected on this machine." "red"
			}
			else
			{
				Write_Log "No store info file (INFO_*_WIN.INI) found at $WinIniPath" "red"
			}
		}

		# ------------------------------------------------------------------------------------------------
		# Fallback: StoreName from system.ini ([SMS] Name=...)
		# ------------------------------------------------------------------------------------------------
		if (
			($script:FunctionResults['StoreName'] -eq 'N/A' -or [string]::IsNullOrWhiteSpace($script:FunctionResults['StoreName'])) -and
			$SystemIniPath -and (Test-Path $SystemIniPath)
		)
		{
			$inSMSSection = $false
			foreach ($line in Get-Content -LiteralPath $SystemIniPath)
			{
				$trimmed = $line.Trim()
				if ($trimmed -match '^\[SMS\]$') { $inSMSSection = $true; continue }
				if ($inSMSSection)
				{
					if ($trimmed -match '^\[.+\]$') { break }
					if ($trimmed -match '^\s*Name\s*=(.*)$')
					{
						$storeNameBackup = $Matches[1].Trim()
						if ($storeNameBackup) { $script:FunctionResults['StoreName'] = $storeNameBackup; break }
					}
				}
			}
		}

		# ------------------------------------------------------------------------------------------------
		# Extract SQL Server/Database from SMSStart INI
		# ------------------------------------------------------------------------------------------------
		$dbServer = $null
		$dbName = $null

		if ($SmsStartIniPath -and (Test-Path $SmsStartIniPath))
		{
			foreach ($line in Get-Content -LiteralPath $SmsStartIniPath)
			{
				$trimmed = $line.Trim()
				if ($trimmed -notmatch "=" -or $trimmed.StartsWith(";")) { continue }
				$parts = $trimmed -split "=", 2
				$key = $parts[0].Trim()
				$value = $parts[1].Trim()
				if (-not $dbServer -and $key -match 'ServerName') { $dbServer = $value }
				if (-not $dbName -and $key -match 'DatabaseName') { $dbName = $value }
				if ($dbServer -and $dbName) { break }
			}
		}

		# ------------------------------------------------------------------------------------------------
		# Fallback: Startup.ini for DBSERVER/DBNAME
		# ------------------------------------------------------------------------------------------------
		if ((!$dbServer -or !$dbName) -and $StartupIniPath -and (Test-Path $StartupIniPath))
		{
			foreach ($line in Get-Content -LiteralPath $StartupIniPath)
			{
				$trimmed = $line.Trim()
				if ($trimmed -notmatch "=" -or $trimmed.StartsWith(";")) { continue }
				$parts = $trimmed -split "=", 2
				$key = $parts[0].Trim()
				$value = $parts[1].Trim()
				if (-not $dbServer -and $key -match '^DBSERVER$') { $dbServer = $value }
				if (-not $dbName -and $key -match '^DBNAME$') { $dbName = $value }
				if ($dbServer -and $dbName) { break }
			}
			if (-not $dbServer) { $dbServer = "localhost" }
			if (-not $dbName) { $dbName = "STORESQL" }
		}

		# ------------------------------------------------------------------------------------------------
		# Finalize connection string
		# ------------------------------------------------------------------------------------------------
		if ($dbServer -and $dbName)
		{
			$script:FunctionResults['DBSERVER'] = $dbServer
			$script:FunctionResults['DBNAME'] = $dbName
			$script:FunctionResults['ConnectionString'] =
			"Server=$dbServer;Database=$dbName;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;Connect Timeout=5;Application Name=TBS_Maintenance_Script"
		}

		# ------------------------------------------------------------------------------------------------
		# Cache write (store EVERYTHING this function collects)
		# ------------------------------------------------------------------------------------------------
		if ($CachePath)
		{
			try
			{
				$results = [ordered]@{ }
				foreach ($k in ($fields + 'SqlModuleName'))
				{
					$v = $script:FunctionResults[$k]
					if ($null -eq $v -or ($v -is [string] -and [string]::IsNullOrWhiteSpace($v))) { $v = 'N/A' }
					$results[$k] = $v
				}

				$cacheOut = [ordered]@{
					LastUpdated = (Get-Date).ToString('o')
					StoreNumber = $script:FunctionResults['StoreNumber']
					Results	    = $results
				}

				($cacheOut | ConvertTo-Json -Depth 8) | Set-Content -LiteralPath $CachePath -Encoding UTF8 -Force
			}
			catch { }
		}
	}
	finally
	{
		# ------------------------------------------------------------------------------------------------
		# GUI label updates (optional)
		# ------------------------------------------------------------------------------------------------
		# Runs even after an early return on a cache hit; safe without a form (background jobs).
		try
		{
			$anyLabelChanged = $false

			if ($null -ne $storeNumberLabel)
			{
				$storeNumberLabel.Text = "Store Number: $($script:FunctionResults['StoreNumber'])"
				$anyLabelChanged = $true
			}
			if ($null -ne $storeNameLabel)
			{
				$storeNameLabel.Text = "Store Name: $($script:FunctionResults['StoreName'])"
				$anyLabelChanged = $true
			}
			if ($null -ne $bannerDateLabel)
			{
				try
				{
					$bn = $script:FunctionResults['StoreNumber']
					$bnm = $script:FunctionResults['StoreName']
					if ($bn -and "$bn" -ne 'N/A' -and -not [string]::IsNullOrWhiteSpace("$bn"))
					{
						if ($bnm -and "$bnm" -ne 'N/A' -and -not [string]::IsNullOrWhiteSpace("$bnm"))
						{
						$bnmShort = "$bnm"
						if ($bnmShort.Length -gt 26) { $bnmShort = $bnmShort.Substring(0, 25).TrimEnd() + '...' }
						$bannerDateLabel.Text = "Store $bn  -  $bnmShort"
						}
						else { $bannerDateLabel.Text = "Store $bn" }
					}
					else
					{
					$bannerDateLabel.Text = "Store Maintenance Console"
					}
					$anyLabelChanged = $true
					try { if ($layoutBanner) { & $layoutBanner } } catch { }
				}
				catch { }
			}
			if ($null -ne $smsVersionLabel)
			{
				$smsVersionLabel.Text = "SMS Version: $($script:FunctionResults['SMSVersionFull'])"
				$anyLabelChanged = $true
			}

			if ($anyLabelChanged)
			{
				if ($null -ne $form) { $form.Refresh() }
				try { [System.Windows.Forms.Application]::DoEvents() }
				catch { }
			}
		}
		catch { }
	}
}

# ===================================================================================================
#                              FUNCTION: Get_Table_Aliases
# ---------------------------------------------------------------------------------------------------
# Description:
#   Returns a hashtable mapping SQL table aliases to table names. Uses a hardcoded mapping
#   when the SMS version is in the supported range, otherwise scans the Office Load
#   *_Load.sql files dynamically. Cached in memory for the launch and in a small file.
#
# Parameters:
#   - RefreshCache  [switch]: ignore in-memory/file cache and rebuild
#
# Variables:
#   - $script:FunctionResults['Get_Table_Aliases']: @{ Aliases; AliasHash; TableHash }
#   - $script:FunctionResults['SMSVersionFull']: decides static vs dynamic mode
#   - $LoadPath / $OfficePath: location of the Load SQL files (dynamic mode)
#
# Returns:
#   Hashtable alias -> table name.
#
# Writes:
#   - Setup_Files\Get_Table_Aliases.txt (JSON cache: mode, SMS version, Load-file signature,
#     AliasHash + TableHash). The file cache is reused only while the SMS version and (dynamic
#     mode) the *_Load.sql signature still match.
# ===================================================================================================

function Get_Table_Aliases
{
	param (
		[switch]$RefreshCache
	)

	$CachePath = Join-Path $script:SetupFiles 'Get_Table_Aliases.txt'

	# PSCustomObject (from JSON) -> hashtable, so .ContainsKey() works for the callers
	$toHash = {
		param ($o)
		$h = @{ }
		if ($o -is [hashtable]) { return $o }
		if ($o -and $o.PSObject -and $o.PSObject.Properties) { foreach ($p in $o.PSObject.Properties) { $h[$p.Name] = $p.Value } }
		return $h
	}
	$publish = {
		param ($AliasHash, $TableHash)
		$script:FunctionResults['Get_Table_Aliases'] = @{ Aliases = @(); AliasHash = $AliasHash; TableHash = $TableHash }
		return $AliasHash
	}

	# ------------------------------------------------------------------------------------------------
	# 1. In-memory (this launch)
	# ------------------------------------------------------------------------------------------------
	if (-not $RefreshCache)
	{
		try
		{
			$aliasData = $script:FunctionResults['Get_Table_Aliases']
			if ($aliasData -and $aliasData.AliasHash)
			{
				if ($aliasData.AliasHash -is [hashtable]) { return $aliasData.AliasHash }
				return (& $publish (& $toHash $aliasData.AliasHash) (& $toHash $aliasData.TableHash))
			}
		}
		catch { }
	}

	# ------------------------------------------------------------------------------------------------
	# SMS version -> static (supported range) or dynamic mode
	# ------------------------------------------------------------------------------------------------
	$MinSupportedSMSVersion = "3.3.0.0"
	$MaxSupportedSMSVersion = "3.6.1.8"

	$SMSVersion = "0.0.0.0"
	if ([string]$script:FunctionResults['SMSVersionFull'] -match '([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)') { $SMSVersion = $Matches[1] }
	$versionKnown = ($SMSVersion -ne "0.0.0.0")

	$versionInRange = $false
	try
	{
		$vTest = [version]$SMSVersion
		$versionInRange = ($vTest -ge [version]$MinSupportedSMSVersion -and $vTest -le [version]$MaxSupportedSMSVersion)
	}
	catch { $versionInRange = $false }

	if ([string]::IsNullOrWhiteSpace($LoadPath))
	{
		try { if ($OfficePath -and (Test-Path -LiteralPath $OfficePath)) { $LoadPath = Join-Path $OfficePath 'Load' } }
		catch { }
	}

	# Signature of the *_Load.sql files (dynamic mode cache validation)
	$getLoadSignature = {
		try
		{
			if (-not $LoadPath -or -not (Test-Path -LiteralPath $LoadPath)) { return $null }
			$files = @(Get-ChildItem -LiteralPath $LoadPath -Recurse -Filter '*_Load.sql' -File -ErrorAction SilentlyContinue)
			$newest = $null
			$total = [int64]0
			foreach ($f in $files)
			{
				if (-not $newest -or $f.LastWriteTimeUtc -gt $newest) { $newest = $f.LastWriteTimeUtc }
				$total += $f.Length
			}
			return [pscustomobject]@{
				Root       = [string]$LoadPath
				FileCount  = [int]$files.Count
				NewestUtc  = if ($newest) { $newest.ToString('o') } else { "" }
				TotalBytes = [int64]$total
			}
		}
		catch { return $null }
	}

	# ------------------------------------------------------------------------------------------------
	# 2. File cache (only while it still describes this store's SMS version / Load files)
	# ------------------------------------------------------------------------------------------------
	if ((-not $RefreshCache) -and (Test-Path -LiteralPath $CachePath))
	{
		try
		{
			$raw = Get-Content -LiteralPath $CachePath -Raw -ErrorAction Stop
			$cacheObj = $null
			if (-not [string]::IsNullOrWhiteSpace($raw)) { $cacheObj = $raw | ConvertFrom-Json -ErrorAction Stop }
			if ($cacheObj -and $cacheObj.Results)
			{
				$cacheValid = $true
				# A known SMS version that differs from the cached one means an upgrade: rebuild
				if ($versionKnown -and $cacheObj.SMSVersion -and ([string]$cacheObj.SMSVersion -ne $SMSVersion)) { $cacheValid = $false }
				if ($cacheValid -and [string]$cacheObj.Mode -eq 'Dynamic' -and $cacheObj.LoadSignature)
				{
					$sig = & $getLoadSignature
					if ($sig -and (
							[int]$cacheObj.LoadSignature.FileCount -ne $sig.FileCount -or
							[string]$cacheObj.LoadSignature.NewestUtc -ne $sig.NewestUtc -or
							[int64]$cacheObj.LoadSignature.TotalBytes -ne $sig.TotalBytes))
					{
						$cacheValid = $false
					}
				}
				if ($cacheValid)
				{
					return (& $publish (& $toHash $cacheObj.Results.AliasHash) (& $toHash $cacheObj.Results.TableHash))
				}
			}
		}
		catch
		{
			# unreadable cache: rebuild
		}
	}

	$writeCache = {
		param ([string]$Mode, $Signature, $AliasHash, $TableHash)
		try
		{
			$cacheOut = [pscustomobject]@{
				LastUpdated   = (Get-Date).ToString('o')
				SMSVersion    = $SMSVersion
				Mode          = $Mode
				LoadSignature = $Signature
				Results       = [pscustomobject]@{
					AliasHash = [pscustomobject]$AliasHash
					TableHash = [pscustomobject]$TableHash
				}
			}
			($cacheOut | ConvertTo-Json -Depth 8) | Set-Content -LiteralPath $CachePath -Encoding UTF8 -Force
		}
		catch { }
	}

	# ------------------------------------------------------------------------------------------------
	# 3a. Static mode (supported SMS range): hardcoded alias -> table map
	# ------------------------------------------------------------------------------------------------
	if ($versionInRange)
	{
		$AliasToTable = @{
			'ALT'      = 'ALT_TAB'
			'BIO'      = 'BIO_TAB'
			'BTL'      = 'BTL_TAB'
			'CAT'      = 'CAT_TAB'
			'CFG'      = 'CFG_TAB'
			'CLF'      = 'CLF_TAB'
			'CLF_SDP'  = 'CLF_SDP_TAB'
			'CLG'      = 'CLG_TAB'
			'CLK'      = 'CLK_TAB'
			'CLL'      = 'CLL_TAB'
			'CLR'      = 'CLR_TAB'
			'CLT'      = 'CLT_TAB'
			'CLT_ITM'  = 'CLT_ITM_TAB'
			'COST'     = 'COST_TAB'
			'CPN'      = 'CPN_TAB'
			'DELV'     = 'DELV_TAB'
			'DEPT'     = 'DEPT_TAB'
			'DSD'      = 'DSD_TAB'
			'ECL'      = 'ECL_TAB'
			'FAM'      = 'FAM_TAB'
			'KIT'      = 'KIT_TAB'
			'LOC'      = 'LOC_TAB'
			'LVL'      = 'LVL_TAB'
			'MIX'      = 'MIX_TAB'
			'MOD'      = 'MOD_TAB'
			'OBJ'      = 'OBJ_TAB'
			'POS'      = 'POS_TAB'
			'PRICE'    = 'PRICE_TAB'
			'PUB'      = 'PUB_TAB'
			'RES'      = 'RES_TAB'
			'ROUTE'    = 'ROUTE_TAB'
			'RPC'      = 'RPC_TAB'
			'SCAL_ITM' = 'SCL_TAB'
			'SCAL_NUT' = 'SCL_NUT_TAB'
			'SCAL_TXT' = 'SCL_TXT_TAB'
			'SDP'      = 'SDP_TAB'
			'STD'      = 'STD_TAB'
			'TAR'      = 'TAR_TAB'
			'UNT'      = 'UNT_TAB'
			'VENDOR'   = 'VENDOR_TAB'
		}
		$TableToAlias = @{ }
		foreach ($k in $AliasToTable.Keys) { $TableToAlias[$AliasToTable[$k]] = $k }

		& $writeCache 'Static' $null $AliasToTable $TableToAlias
		return (& $publish $AliasToTable $TableToAlias)
	}

	# ------------------------------------------------------------------------------------------------
	# 3b. Dynamic mode (SMS version outside the supported range): read @CREATE lines from the
	#     <TABLE>_Load.sql files, e.g.  @CREATE('OBJ_TAB', 'OBJ');
	# ------------------------------------------------------------------------------------------------
	Write-Host "SMS Version $SMSVersion is outside supported range ($MinSupportedSMSVersion - $MaxSupportedSMSVersion). Scanning SQL files for table/alias map..." -ForegroundColor Yellow

	if (-not $LoadPath -or -not (Test-Path -LiteralPath $LoadPath))
	{
		Write-Warning "LoadPath is not available; cannot scan *_Load.sql files. Returning empty hashtable."
		return (& $publish @{ } @{ })
	}

	$BaseTables = @(
		'OBJ', 'POS', 'PRICE', 'COST', 'DSD', 'KIT', 'LOC', 'ALT', 'ECL',
		'SCL', 'SCL_TXT', 'SCL_NUT', 'DEPT', 'SDP', 'CAT', 'RPC', 'FAM',
		'CPN', 'PUB', 'BIO', 'CLK', 'LVL', 'MIX', 'BTL', 'TAR', 'UNT',
		'RES', 'ROUTE', 'VENDOR', 'DELV', 'CLT', 'CLG', 'CLF', 'CLR',
		'CLL', 'CLT_ITM', 'CLF_SDP', 'STD', 'CFG', 'MOD'
	)
	$loadFileNames = @{ }
	foreach ($bt in $BaseTables) { $loadFileNames["${bt}_Load.sql"] = $true }

	$tablesPattern = ($BaseTables | Sort-Object Length -Descending | ForEach-Object { [regex]::Escape($_) }) -join '|'
	$regex = [regex]::new("^\s*@CREATE\s*\(\s*['""]?(?<Table>($tablesPattern)(_[A-Z]+))?['""]?\s*,\s*['""]?(?<Alias>[\w-]+)['""]?\s*\);", [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)

	$AliasToTableLive = @{ }
	$TableToAliasLive = @{ }
	foreach ($file in @(Get-ChildItem -LiteralPath $LoadPath -Recurse -Filter '*_Load.sql' -File -ErrorAction SilentlyContinue))
	{
		if (-not $loadFileNames.ContainsKey($file.Name)) { continue }
		foreach ($line in @(Get-Content -LiteralPath $file.FullName -ErrorAction SilentlyContinue))
		{
			$lineClean = $line -replace '--.*', '' -replace '/\*.*?\*/', ''
			if ($lineClean -notmatch '@CREATE') { continue }
			$match = $regex.Match($lineClean)
			if ($match.Success -and $match.Groups['Table'].Value -and $match.Groups['Alias'].Value)
			{
				$AliasToTableLive[$match.Groups['Alias'].Value] = $match.Groups['Table'].Value
				$TableToAliasLive[$match.Groups['Table'].Value] = $match.Groups['Alias'].Value
			}
		}
	}
	if ($AliasToTableLive.Count -eq 0) { Write-Warning "No table-alias pairs detected. Using empty hashtable." }

	& $writeCache 'Dynamic' (& $getLoadSignature) $AliasToTableLive $TableToAliasLive
	return (& $publish $AliasToTableLive $TableToAliasLive)
}

# ===================================================================================================
#                              FUNCTION: Insert_Test_Item
# ---------------------------------------------------------------------------------------------------
# Description:
#   Inserts a deterministic test item into the store database: picks one of three test PLUs,
#   deletes any existing rows for it, then inserts fixed rows into SCL_TAB, OBJ_TAB, POS_TAB,
#   PRICE_TAB and SCL_TXT_TAB. Uses Invoke-Sqlcmd with the connection string from
#   Get_Store_And_Database_Info, falling back to -ServerInstance/-Database.
#
# Parameters:
#   - ConnectionString         [string]: defaults to the FunctionResults connection string
#   - Silent                   [switch]: suppress Write_Log output
#   - QueryTimeoutSeconds      [int]: SQL query timeout in seconds (default 15)
#   - ConnectionTimeoutSeconds [int]: SQL connect timeout in seconds (default 5)
#
# Variables:
#   - $script:FunctionResults: reads ConnectionString, DBSERVER, DBNAME, SqlModuleName
#
# Writes:
#   - store database (SCL_TAB, OBJ_TAB, POS_TAB, PRICE_TAB, SCL_TXT_TAB)
# ===================================================================================================

function Insert_Test_Item
{
	[CmdletBinding()]
	param (
		# If omitted, we use the ConnectionString assembled by Get_Store_And_Database_Info.
		[string]$ConnectionString = $script:FunctionResults['ConnectionString'],
		[switch]$Silent,
		[int]$QueryTimeoutSeconds = 15,
		[int]$ConnectionTimeoutSeconds = 5
	)

	$writeLog = {
		param (
			[string]$Message,
			[string]$Color = "white"
		)
		if (-not $Silent) { Write_Log $Message $Color }
	}

	if ($ConnectionString)
	{
		try
		{
			$csb = New-Object System.Data.SqlClient.SqlConnectionStringBuilder $ConnectionString
			$csb.PSBase.ConnectTimeout = $ConnectionTimeoutSeconds
			$ConnectionString = $csb.ConnectionString
		}
		catch
		{
			if ($ConnectionString -notmatch '(?i)\bConnect\s*Timeout\s*=')
			{
				$ConnectionString = $ConnectionString.Trim().TrimEnd(';') + ";Connect Timeout=$ConnectionTimeoutSeconds"
			}
		}
	}

	# ----------------------------------------------------------------------------------------------
	# Guard: Need connection context from Get_Store_And_Database_Info
	# (DBSERVER/DBNAME and/or ConnectionString should be available)
	# ----------------------------------------------------------------------------------------------
	if (-not $ConnectionString -and
		(-not $script:FunctionResults['DBSERVER'] -or -not $script:FunctionResults['DBNAME']))
	{
		& $writeLog "Insert_Test_Item: No ConnectionString nor DBSERVER/DBNAME available. Run Get_Store_And_Database_Info first." "red"
		return
	}

	& $writeLog "`r`n==================== Starting Insert_Test_Item ====================`r`n" "blue"

	# ----------------------------------------------------------------------------------------------
	# Ensure Invoke-Sqlcmd is available (prefer SqlServer, fallback to SQLPS)
	# We honor the detection already done in Get_Store_And_Database_Info.
	# ----------------------------------------------------------------------------------------------
	$sqlModule = $script:FunctionResults['SqlModuleName']
	if (-not (Get-Command Invoke-Sqlcmd -ErrorAction SilentlyContinue))
	{
		try
		{
			if ($sqlModule -eq 'SqlServer')
			{
				Import-Module SqlServer -ErrorAction Stop
			}
			elseif ($sqlModule -eq 'SQLPS')
			{
				Import-Module SQLPS -DisableNameChecking -ErrorAction Stop
			}
		}
		catch
		{
			# If import fails, we'll check again below; if still missing, we abort.
		}
	}

	if (-not (Get-Command Invoke-Sqlcmd -ErrorAction SilentlyContinue))
	{
		& $writeLog "Insert_Test_Item: Invoke-Sqlcmd not available (SqlServer/SQLPS modules not loaded/installed)." "red"
		& $writeLog "`r`n==================== Insert_Test_Item Aborted (No SQL Module) ====================`r`n" "blue"
		return
	}

	$invokeSqlcmdCommand = $null
	$supportsConnTimeout = $false
	try
	{
		$invokeSqlcmdCommand = Get-Command Invoke-Sqlcmd -ErrorAction Stop
		if ($invokeSqlcmdCommand -and $invokeSqlcmdCommand.Parameters)
		{
			$supportsConnTimeout = $invokeSqlcmdCommand.Parameters.ContainsKey('ConnectionTimeout')
		}
	}
	catch { }

	# ----------------------------------------------------------------------------------------------
	# Decide primary vs. fallback path:
	#   - If SqlServer module is detected, we ATTEMPT -ConnectionString (modern path).
	#   - Otherwise (SQLPS/None), we go straight to fallback (-ServerInstance/-Database).
	#   - Even with SqlServer, if the probe SELECT 1 fails, we flip to fallback.
	# ----------------------------------------------------------------------------------------------
	$useConnectionString = $false # Default to fallback unless we validate modern path
	$fallbackParams = @{ } # Will be used with -ServerInstance/-Database

	# Pull server/database from FunctionResults (preferred over parsing)
	$serverInstanceFromInfo = $script:FunctionResults['DBSERVER']
	$databaseFromInfo = $script:FunctionResults['DBNAME']

	# Compose fallback param set from known values
	if ($serverInstanceFromInfo) { $fallbackParams['ServerInstance'] = $serverInstanceFromInfo }
	if ($databaseFromInfo) { $fallbackParams['Database'] = $databaseFromInfo }

	# If we have SqlServer module, try modern path first.
	if ($sqlModule -eq 'SqlServer' -and $ConnectionString)
	{
		try
		{
			Invoke-Sqlcmd -ConnectionString $ConnectionString -Query "SELECT 1" -QueryTimeout $QueryTimeoutSeconds -ErrorAction Stop | Out-Null
			$useConnectionString = $true
			& $writeLog "SQL connectivity via -ConnectionString verified (SqlServer module)." "green"
		}
		catch
		{
			& $writeLog "Modern path (-ConnectionString) failed: $($_.Exception.Message)`r`nFalling back to -ServerInstance/-Database..." "yellow"
			$useConnectionString = $false
		}
	}
	else
	{
		# Either SQLPS or no module indicated from detection - use fallback path.
		$useConnectionString = $false
	}

	# If planning to use fallback, validate it can connect
	if (-not $useConnectionString)
	{
		# If DBSERVER/DBNAME were missing, try to salvage from the connection string
		if (-not $fallbackParams['ServerInstance'] -or -not $fallbackParams['Database'])
		{
			# Last-resort: parse minimal fields from ConnectionString (only if needed)
			if ($ConnectionString -match '(?i)(?:Data\s*Source|Server)\s*=\s*([^;]+)')
			{
				$fallbackParams['ServerInstance'] = $matches[1].Trim()
			}
			if ($ConnectionString -match '(?i)(?:Initial\s*Catalog|Database)\s*=\s*([^;]+)')
			{
				$fallbackParams['Database'] = $matches[1].Trim()
			}
		}

		try
		{
			$fallbackProbeParams = $fallbackParams.Clone()
			$fallbackProbeParams['Query'] = 'SELECT 1'
			$fallbackProbeParams['QueryTimeout'] = $QueryTimeoutSeconds
			$fallbackProbeParams['ErrorAction'] = 'Stop'
			if ($supportsConnTimeout) { $fallbackProbeParams['ConnectionTimeout'] = $ConnectionTimeoutSeconds }
			Invoke-Sqlcmd @fallbackProbeParams | Out-Null
			$dbTxt = if ($fallbackParams['Database']) { " (DB=$($fallbackParams['Database']))" }
			else { "" }
			& $writeLog "SQL connectivity via fallback -ServerInstance verified: $($fallbackParams['ServerInstance'])$dbTxt" "green"
		}
		catch
		{
			& $writeLog "Fallback (-ServerInstance/-Database) failed: $($_.Exception.Message)" "red"
			& $writeLog "`r`n==================== Insert_Test_Item Aborted (No Connectivity) ====================`r`n" "blue"
			return
		}
	}

	# ----------------------------------------------------------------------------------------------
	# SQL runner for every query below (connection-string or -ServerInstance path, chosen above)
	# ----------------------------------------------------------------------------------------------
	$RunSql = {
		param ([Parameter(Mandatory = $true)]
			[string]$Query)
		if ($useConnectionString)
		{
			return Invoke-Sqlcmd -ConnectionString $ConnectionString -Query $Query -QueryTimeout $QueryTimeoutSeconds -ErrorAction Stop
		}
		else
		{
			$p = $fallbackParams.Clone()
			$p['Query'] = $Query
			$p['QueryTimeout'] = $QueryTimeoutSeconds
			$p['ErrorAction'] = 'Stop'
			if ($supportsConnTimeout) { $p['ConnectionTimeout'] = $ConnectionTimeoutSeconds }
			return Invoke-Sqlcmd @p
		}
	}

	# ----------------------------------------------------------------------------------------------
	# Choose the test PLU: the first candidate that is unused or already a test item
	# (description contains "test" / "tecnica"). A candidate whose lookup FAILS is skipped -
	# never assume a PLU is free when we could not check it (it may be a real item).
	# ----------------------------------------------------------------------------------------------
	$now = Get-Date
	$nowFull = $now.ToString("yyyy-MM-dd HH:mm:ss.fff")
	$nowDate = $now.ToString("yyyy-MM-dd 00:00:00.000")

	$PLU = $null
	$TestF267 = $null
	foreach ($candidate in @(
			@{ Plu = '0020077700000'; F267 = 777; Kind = 'preferred' },
			@{ Plu = '0020777700000'; F267 = 7777; Kind = 'alternative' },
			@{ Plu = '0027777700000'; F267 = 77777; Kind = 'fallback' }))
	{
		try
		{
			$pos = & $RunSql "SELECT F02 FROM POS_TAB WHERE F01 = '$($candidate.Plu)'"
			$obj = & $RunSql "SELECT F29 FROM OBJ_TAB WHERE F01 = '$($candidate.Plu)'"
			$posDesc = if ($pos) { [string]$pos.F02 } else { "" }
			$objDesc = if ($obj) { [string]$obj.F29 } else { "" }
			$usable = ($posDesc -match '(?i)test|tecnica') -or ($objDesc -match '(?i)test|tecnica') -or
				([string]::IsNullOrWhiteSpace($posDesc) -and [string]::IsNullOrWhiteSpace($objDesc))
		}
		catch
		{
			& $writeLog ("Could not check PLU {0}: {1} - skipping it." -f $candidate.Plu, $_.Exception.Message) "yellow"
			$usable = $false
		}
		if ($usable)
		{
			$PLU = $candidate.Plu
			$TestF267 = $candidate.F267
			& $writeLog ("Using {0} PLU: {1} with F267: {2}" -f $candidate.Kind, $PLU, $TestF267) "green"
			break
		}
	}
	$doInsert = [bool]$PLU

	if ($doInsert -and $PLU)
	{
		& $writeLog "Deleting existing records for PLU: $PLU and F267: $TestF267" "yellow"

		# --- Delete old rows for the chosen PLU/F267 so the inserts are deterministic. The scale
		#     text row is only removed when no other item uses that F267 (it could be a real one).
		$deleteQueries = @(
			"DELETE FROM SCL_TAB     WHERE F01 = '$PLU'",
			"DELETE FROM OBJ_TAB     WHERE F01 = '$PLU'",
			"DELETE FROM POS_TAB     WHERE F01 = '$PLU'",
			"DELETE FROM PRICE_TAB   WHERE F01 = '$PLU'",
			"DELETE FROM SCL_TXT_TAB WHERE F267 = $TestF267 AND F267 NOT IN (SELECT F267 FROM SCL_TAB WHERE F01 <> '$PLU' AND F267 IS NOT NULL)"
		)
		foreach ($q in $deleteQueries)
		{
			try { & $RunSql $q | Out-Null }
			catch { & $writeLog "Error during deletion: $($_.Exception.Message)" "red" }
		}

		# --- SCL_TAB
		& $writeLog "Inserting into SCL_TAB..." "yellow"
		try
		{
			& $RunSql @"
INSERT INTO SCL_TAB (F01, F1000, F902, F1001, F253, F258, F264, F267, F1952, F1964, F2581, F2582)
VALUES
('$PLU', 'PAL', 'MANUAL', 1, '$nowFull', 10, 7, $TestF267, 'Test Descriptor 2', '001', 'Test Descriptor 3', 'Test Descriptor 4')
"@ | Out-Null
			& $writeLog "SCL_TAB insertion successful" "green"
		}
		catch { & $writeLog "Error inserting into SCL_TAB: $($_.Exception.Message)" "red" }

		# --- OBJ_TAB
		& $writeLog "Inserting into OBJ_TAB..." "yellow"
		try
		{
			$F29 = 'Tecnica Test Item'
			if ($F29.Length -gt 60) { $F29 = $F29.Substring(0, 60) }
			& $RunSql @"
INSERT INTO OBJ_TAB (F01, F902, F1001, F21, F29, F270, F1118, F1959)
VALUES
('$PLU', '00001153', 0, 1, '$F29', 123.45, '001', '001')
"@ | Out-Null
			& $writeLog "OBJ_TAB insertion successful" "green"
		}
		catch { & $writeLog "Error inserting into OBJ_TAB: $($_.Exception.Message)" "red" }

		# --- POS_TAB
		& $writeLog "Inserting into POS_TAB..." "yellow"
		try
		{
			& $RunSql @"
INSERT INTO POS_TAB (F01, F1000, F902, F1001, F02, F09, F79, F80, F82, F104, F115, F176, F178, F217, F1964, F2119)
VALUES
('$PLU', 'PAL', 'MANUAL', 0, 'Tecnica Test Item', '$nowDate', '1', '1', '1', '0', '0', '1', '1', 1.0, '001', '1')
"@ | Out-Null
			& $writeLog "POS_TAB insertion successful" "green"
		}
		catch { & $writeLog "Error inserting into POS_TAB: $($_.Exception.Message)" "red" }

		# --- PRICE_TAB
		& $writeLog "Inserting into PRICE_TAB..." "yellow"
		try
		{
			& $RunSql @"
INSERT INTO PRICE_TAB (F01, F1000, F126, F902, F1001, F21, F30, F31, F113, F1006, F1007, F1008, F1009, F1803)
VALUES
('$PLU', 'PAL', 1, 'MANUAL', 0, 1, 777.77, 1, 'REG', 1, 777.77, '$nowDate', '1858', 1.0)
"@ | Out-Null
			& $writeLog "PRICE_TAB insertion successful" "green"
		}
		catch { & $writeLog "Error inserting into PRICE_TAB: $($_.Exception.Message)" "red" }

		# --- SCL_TXT_TAB
		& $writeLog "Inserting into SCL_TXT_TAB..." "yellow"
		try
		{
			& $RunSql @"
INSERT INTO SCL_TXT_TAB (F267, F1000, F253, F297, F902, F1001, F1836)
VALUES
($TestF267, 'PAL', '$nowFull', 'Ingredients Test', 'MANUAL', 0, 'Tecnica Test Item')
"@ | Out-Null
			& $writeLog "SCL_TXT_TAB insertion successful" "green"
		}
		catch { & $writeLog "Error inserting into SCL_TXT_TAB: $($_.Exception.Message)" "red" }

		& $writeLog "`r`n==================== Insert_Test_Item Completed ====================`r`n" "blue"
	}
	else
	{
		& $writeLog "`r`n==================== Insert_Test_Item Completed (No Data) ====================`r`n" "blue"
	}
}

# ===================================================================================================
#                              FUNCTION: Install_FUNCTIONS_Into_SMS
# ---------------------------------------------------------------------------------------------------
# Description:
#   Installs the SMS deploy artifacts into the Office folder: DEPLOY_SYS.sql (with the
#   "Multiple Functions" menu entry) and DEPLOY_MULTI_FCT.sqm (CSV / ranges like 123,234,300-305).
#   Both files are written as ANSI (Windows-1252), CRLF line endings, no BOM.
#
# Parameters:
#   - StoreNumber  [string]: kept for signature compatibility (not used in content)
#   - OfficePath   [string]: Office folder (default: $script:OfficePath, else <BasePath>\Office)
#   - Silent       [switch]: suppress Write_Log output
#
# Writes:
#   - <OfficePath>\DEPLOY_SYS.sql and <OfficePath>\DEPLOY_MULTI_FCT.sqm
# ===================================================================================================

function Install_FUNCTIONS_Into_SMS
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $false)]
		[string]$StoreNumber,
		[Parameter(Mandatory = $false)]
		[string]$OfficePath,
		[switch]$Silent
	)

	$writeLog = {
		param (
			[string]$Message,
			[string]$Color = "white"
		)
		if (-not $Silent) { Write_Log $Message $Color }
	}

	& $writeLog "`r`n==================== Starting Install_FUNCTIONS_Into_SMS ====================`r`n" "blue"

	# Registered-sign macro marker (U+00AE) built from its code point so this source stays ASCII;
	# the files are written as Windows-1252, where it is the single byte 0xAE SMS expects.
	$reg = [char]0x00AE

	# --------------------------------------------------------------------------------------------------------------
	# Resolve/validate OfficePath (prefer explicit param; fallback to common script-scoped variables)
	# --------------------------------------------------------------------------------------------------------------
	if (-not $OfficePath -or [string]::IsNullOrWhiteSpace($OfficePath))
	{
		# (the storeman ROOT is not the Office folder - before v2.7.0 this fell back to BasePath itself)
		if ($script:OfficePath) { $OfficePath = $script:OfficePath }
		elseif ($script:BasePath) { $OfficePath = Join-Path $script:BasePath 'Office' }
	}
	if (-not $OfficePath -or -not (Test-Path -LiteralPath $OfficePath))
	{
		& $writeLog "Office path not found or not provided: '$OfficePath'." "red"
		return
	}

	# --- Destination paths ---
	$DeploySysPath = Join-Path -Path $OfficePath -ChildPath "DEPLOY_SYS.sql"
	$DeployMultiFctPath = Join-Path -Path $OfficePath -ChildPath "DEPLOY_MULTI_FCT.sqm"

	# --- Encoding: ANSI (Windows-1252), no BOM ---
	$ansi = [System.Text.Encoding]::GetEncoding(1252)

	# ===============================================================================================================
	#                                             DEPLOY_SYS.sql (ALWAYS includes "Multiple Functions")
	# ===============================================================================================================
	$DeploySysContent = @"
@FMT(CMP,@dbHot(FINDFIRST,UD_DEPLOY_SYS.SQL)=,$($reg)WIZRPL(UD_RUN=0));
@FMT(CMP,@WIZGET(UD_RUN)=,'$($reg)EXEC(SQL=UD_DEPLOY_SYS)$($reg)FMT(CHR,27)');

@FMT(CMP,@TOOLS(MESSAGEDLG,"!TO KEEP THE LANE'S REFERENCE SAMPLE UP TO DATE YOU SHOULD USE THE "REFERENCE SAMPLE MECHANISM". DO YOU WANT TO CONTINUE?",,NO,YES)=1,'$($reg)FMT(CHR,27)');

@EXEC(INI=HOST_OFFICE[DEPLOY_SYS]);

@WIZRPL(STYLE=SIL);
@WIZRPL(TARGET_FILTER=@DbHot(INI,APPLICATION.INI,DEPLOY_TARGET,HOST_OFFICE));

@EXEC(sqi=USERB_DEPLOY_SYS);

@WIZINIT;
@WIZMENU(ONESQM=What do you want to send,
    Functions (NEW)=DEPLOY_MULTI_FCT,
    Function link=fcz_load,
    Totalizer=tlz_load,
    Drill down pages=dril_page_load,
    Drill down files=dril_file_load,
    All system=ALL);
@WIZDISPLAY;

@WIZINIT;
@WIZTARGET(TARGET=,@FMT(CMP,"@DbHot(INI,APPLICATION.INI,DEPLOY_TARGET,HOST_OFFICE)=","
SELECT F1000,F1018 FROM STO_TAB WHERE F1181=1 ORDER BY F1000","
SELECT DISTINCT STO.F1000,STO.F1018 
FROM LNK_TAB LN2 JOIN LNK_TAB LNK ON LN2.F1056=LNK.F1056 AND LN2.F1057=LNK.F1057
JOIN STO_TAB STO ON STO.F1000=LNK.F1000 
WHERE STO.F1181='1' AND LN2.F1000='@DbHot(INI,APPLICATION.INI,DEPLOY_TARGET,HOST_OFFICE)'
ORDER BY STO.F1000"));
@WIZDISPLAY;

@FMT(CMP,@dbSelect(select distinct 1 from lnk_tab where F1000='@Wizget(Target)' and f1056='999')=,,"$($reg)EXEC(msg=!*****_can_not_deploy_system_tables_to_a_host_****);$($reg)FMT(CHR,27);")

@WIZINIT;
@WIZMENU(ACTION=Action on the target database,Add or replace=ADDRPL,Add only=ADD,Replace only=UPDATE,Clean and load=LOAD);
@WIZDISPLAY;

/* SEND ONLY ONE / MULTI / OR OTHERS */

@FMT(CMP,@wizget(ONESQM)=tlz_load,$($reg)EXEC(SQM=tlz_load));
@FMT(CMP,@wizget(ONESQM)=fcz_load,$($reg)EXEC(SQM=fcz_load));
@FMT(CMP,@wizget(ONESQM)=fct_load,$($reg)EXEC(SQM=fct_load));
@FMT(CMP,@wizget(ONESQM)=dril_file_load,$($reg)EXEC(SQM=DRIL_FILE_LOAD));
@FMT(CMP,@wizget(ONESQM)=dril_page_load,$($reg)EXEC(SQM=DRIL_PAGE_LOAD));
@FMT(CMP,@wizget(ONESQM)=DEPLOY_MULTI_FCT,$($reg)EXEC(SQM=DEPLOY_MULTI_FCT));

@FMT(CMP,@WIZGET(ONESQM)=ALL,,'$($reg)EXEC(SQM=exe_activate_accept_sys)$($reg)fmt(chr,27)');

@FMT(CMP,@wizget(tlz_load)=0,,$($reg)EXEC(SQM=tlz_load));
@FMT(CMP,@wizget(fcz_load)=0,,$($reg)EXEC(SQM=fcz_load));
@FMT(CMP,@wizget(fct_load)=0,,$($reg)EXEC(SQM=fct_load));
@FMT(CMP,@wizget(DRIL_FILE_LOAD)=0,,$($reg)EXEC(SQM=DRIL_FILE_LOAD));
@FMT(CMP,@wizget(DRIL_PAGE_LOAD)=0,,$($reg)EXEC(SQM=DRIL_PAGE_LOAD));
@FMT(CMP,@wizget(DEPLOY_MULTI_FCT)=0,,$($reg)EXEC(SQM=DEPLOY_MULTI_FCT));

@FMT(CMP,@wizget(exe_activate_accept_all)=0,,$($reg)EXEC(SQM=exe_activate_accept_sys));
@FMT(CMP,@wizget(exe_refresh_menu)=1,$($reg)EXEC(SQM=exe_refresh_menu));

@EXEC(sqi=USERE_DEPLOY_SYS);
"@

	# ===============================================================================================================
	#                                      DEPLOY_MULTI_FCT.sqm (template)
	#   Supports CSV and ranges (e.g., 123,234,300-305).
	# ===============================================================================================================
	$DeployMultiFctContent = @"
INSERT INTO HEADER_DCT VALUES
('HC','00000001','001901','001001',,,1997001,0000,1997001,0001,,'LOAD','CREATE DCT',,,,,,'1/1.0','V1.0',,);

CREATE TABLE FCT_DCT(@MAP_FROM_QUERY);

INSERT INTO HEADER_DCT VALUES
('HM','00000001','001901','001001',,,1997001,0000,1997001,0001,,'@WIZGET(ACTION)','@WIZGET(ACTION) SELECTED FUNCTIONS',,,,,,'1/1.0','V1.0','F1063',);

CREATE VIEW FCT_CHG AS SELECT @FIELDS_FROM_QUERY FROM FCT_DCT;

INSERT INTO FCT_CHG VALUES

/* EXTRACT SECTION */

@DBHOT(HOT_WIZ,PARAMTOLINE,PARAMSAV_DEPLOY_MULTI_FCT);
@FMT(CMP,'@WIZGET(TARGET)<>','$($reg)WIZRPL(TARGET_FILTER=@WIZGET(TARGET))');

@WIZINIT;
@WIZEDIT(FCT_LIST=Type ''ALL'' to deploy all functions,'Function IDs/ranges (122,129;122-129)');
@WIZDISPLAY;

@WIZINIT;
@WIZTARGET(TARGET_FILTER=,@FMT(CMP,"@DbHot(INI,APPLICATION.INI,DEPLOY_TARGET,HOST_OFFICE)=","
SELECT F1000,F1018 FROM STO_TAB WHERE F1181=1","
SELECT DISTINCT STO.F1000,STO.F1018
FROM LNK_TAB LN2 JOIN LNK_TAB LNK ON LN2.F1056=LNK.F1056 AND LN2.F1057=LNK.F1057
JOIN STO_TAB STO ON STO.F1000=LNK.F1000
WHERE STO.F1181='1' AND LN2.F1000='@DbHot(INI,APPLICATION.INI,DEPLOY_TARGET,HOST_OFFICE)'"));
@WIZDISPLAY;

@WIZINIT;
@WIZMENU(ACTION=Action on the target database,Add or replace=ADDRPL,Add only=ADD,Replace only=UPDATE,Create and load=LOAD);
@WIZDISPLAY;

@WIZSET(STYLE=SIL);
@WIZCLR(TARGET);
@WIZSET(FORCE_F1000=@F1056);

@dbEXEC(SET ANSI_NULLS ON)
@dbEXEC(SET QUOTED_IDENTIFIER ON)
@dbEXEC(SET ANSI_PADDING ON)
@dbEXEC(SET ANSI_WARNINGS ON)
@dbEXEC(SET CONCAT_NULL_YIELDS_NULL ON)
@dbEXEC(SET NUMERIC_ROUNDABORT OFF)
@dbEXEC(SET ARITHABORT ON)

@MAP_DEPLOY
SELECT FCT.F1056,FCT.F1056+FCT.F1057 AS F1000,@dbFld(FCT_TAB,FCT.,F1000) FROM
    (SELECT LNI.F1056,LNI.F1057,FCT.*,ROW_NUMBER() OVER (PARTITION BY FCT.F1063,LNI.F1056,LNI.F1057 ORDER BY CASE WHEN FCT.F1000='PAL' THEN 1 ELSE 2 END DESC) AS F1301
    FROM FCT_TAB FCT
    JOIN LNK_TAB LNI ON FCT.F1000=LNI.F1000
    JOIN LNK_TAB LNO ON LNI.F1056=LNO.F1056 AND LNI.F1057=LNO.F1057
    WHERE LNO.F1000='@WIZGET(TARGET_FILTER)' AND (
          UPPER(LTRIM(RTRIM('@WIZGET(FCT_LIST)'))) = 'ALL'
          OR EXISTS
          (
            SELECT 1
            FROM
            (
              SELECT
                CASE WHEN CHARINDEX('-',token)=0 AND token IS NOT NULL AND PATINDEX('%[^0-9]%',token)=0 THEN TRY_CAST(token AS INT) ELSE NULL END AS SingleNum,
                CASE WHEN CHARINDEX('-',token)>0 AND PATINDEX('%[^0-9]%',LEFT(token,CHARINDEX('-',token)-1))=0 AND PATINDEX('%[^0-9]%',SUBSTRING(token,CHARINDEX('-',token)+1,8000))=0 THEN TRY_CAST(LEFT(token,CHARINDEX('-',token)-1) AS INT) ELSE NULL END AS StartNum,
                CASE WHEN CHARINDEX('-',token)>0 AND PATINDEX('%[^0-9]%',LEFT(token,CHARINDEX('-',token)-1))=0 AND PATINDEX('%[^0-9]%',SUBSTRING(token,CHARINDEX('-',token)+1,8000))=0 THEN TRY_CAST(SUBSTRING(token,CHARINDEX('-',token)+1,8000) AS INT) ELSE NULL END AS EndNum
              FROM
              (
                SELECT T.N.value('.','nvarchar(100)') AS token
                FROM
                (
                  SELECT CAST('<i>'+REPLACE(REPLACE(REPLACE(REPLACE('@WIZGET(FCT_LIST)',CHAR(13),''),CHAR(10),''),' ',''),',','</i><i>')+'</i>' AS XML) AS xdoc
                ) X
                CROSS APPLY xdoc.nodes('/i') AS T(N)
              ) S
              WHERE ISNULL(token,'')<>''
            ) FF
            WHERE
                   (FF.SingleNum IS NOT NULL AND FCT.F1063 IS NOT NULL AND ISNUMERIC(CONVERT(VARCHAR(50),FCT.F1063))=1 AND CAST(CONVERT(VARCHAR(50),FCT.F1063) AS INT)=FF.SingleNum)
                OR (FF.StartNum IS NOT NULL AND FF.EndNum IS NOT NULL AND FF.EndNum>=FF.StartNum AND FCT.F1063 IS NOT NULL AND ISNUMERIC(CONVERT(VARCHAR(50),FCT.F1063))=1 AND CAST(CONVERT(VARCHAR(50),FCT.F1063) AS INT) BETWEEN FF.StartNum AND FF.EndNum)
          )
        )
    ) FCT
WHERE FCT.F1301=1
ORDER BY F1000,F1063;

/* RESTORE INITITAL PARAMETER POOL */
@WIZRESET;
@DBHOT(HOT_WIZ,LINETOPARAM,PARAMSAV_DEPLOY_MULTI_FCT);
@DBHOT(HOT_WIZ,CLR,PARAMSAV_DEPLOY_MULTI_FCT);
"@

	# ===============================================================================================================
	#                                                  WRITE FILES
	#   normalize to CRLF -> write ANSI (no BOM) -> clear read-only/hidden attributes -> log
	# ===============================================================================================================

	# -- DEPLOY_SYS.sql --
	try
	{
		$norm = [regex]::Replace($DeploySysContent, "(`r)?`n", "`r`n") # normalize to CRLF
		[System.IO.File]::WriteAllText($DeploySysPath, $norm, $ansi) # write as ANSI, no BOM
		Set-ItemProperty -LiteralPath $DeploySysPath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
		& $writeLog "Updated 'DEPLOY_SYS.sql' in '$OfficePath'." "green"
	}
	catch
	{
		& $writeLog "Failed to write 'DEPLOY_SYS.sql'. Error: $_" "red"
	}

	# -- DEPLOY_MULTI_FCT.sqm --
	try
	{
		$norm = [regex]::Replace($DeployMultiFctContent, "(`r)?`n", "`r`n") # normalize to CRLF
		[System.IO.File]::WriteAllText($DeployMultiFctPath, $norm, $ansi) # write as ANSI, no BOM
		Set-ItemProperty -LiteralPath $DeployMultiFctPath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
		& $writeLog "Wrote 'DEPLOY_MULTI_FCT.sqm' (All + CSV + ranges) to '$OfficePath'." "green"
	}
	catch
	{
		& $writeLog "Failed to write 'DEPLOY_MULTI_FCT.sqm'. Error: $_" "red"
	}

	& $writeLog "`r`n==================== Install_FUNCTIONS_Into_SMS Completed ====================`r`n" "blue"
}

# ===================================================================================================
#                              FUNCTION: Retrieve_Nodes
# ---------------------------------------------------------------------------------------------------
# Description:
#   Finds the store's lanes, scales, server and backoffices and builds every lookup map the
#   rest of the script uses (lane number -> machine, scale code -> IP info, ...). Sources, in
#   order: the store database (TER_TAB + TBS_SCL_ver520), else Office\Load\Ter_Load.sql; TER
#   scales are enriched from XchScale\XchNodes.ini. Results are cached per store, the GUI
#   count labels are updated, and the nodes object is returned.
#
# Parameters:
#   - StoreNumber  [string]: store to count (required)
#   - RefreshCache [switch]: ignore the in-memory / file cache and rediscover
#
# Variables:
#   - $script:FunctionResults: receives Nodes, every map listed in $resultNames below and the
#     NumberOfLanes/Servers/Backoffices/Scales counts
#   - Reads $OfficePath, $LoadPath, $script:BasePath, FunctionResults DBSERVER / DBNAME /
#     ConnectionString / SqlModuleName / StoremanPath
#
# Writes:
#   - Setup_Files\Retrieve_Nodes.txt (JSON cache; CacheSchemaVersion must match to be used)
#
# Returns:
#   PSCustomObject with all counts and the lane/scale/backoffice maps.
#
# Notes:
#   - Node rules (TER_TAB / Ter_Load rows): 0xx (or a \\machine\ path) = lane, 8xx with an
#     XchScale.exe path = TER scale, 901 '@machine' = server, 902-998 '@machine' = backoffice.
#   - TBS scales keep their original ScaleCode; a TER scale with the same IP as a TBS scale
#     is dropped (the TBS row wins and inherits the TER path/port details).
#   - Run as a background job at startup (warmup): keep it free of GUI-only dependencies
#     (the label updates are skipped when the labels do not exist).
# ===================================================================================================

function Retrieve_Nodes
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[switch]$RefreshCache
	)

	# Bump when the shape of the cached results changes (10: TBS scales keep their original
	# ScaleCode and are never normalised to 80X)
	$CacheSchemaVersion = 10
	$CachePath = Join-Path $script:SetupFiles 'Retrieve_Nodes.txt'

	# ------------------------------------------------------------------------------------------------
	# What this function publishes. FunctionResults keys = local variable names.
	# ------------------------------------------------------------------------------------------------
	# Nodes object properties, in order
	$nodeNames = @(
		'NumberOfLanes', 'NumberOfServers', 'NumberOfBackoffices', 'NumberOfScales',
		'LaneMachineNames', 'LaneNumToMachineName', 'LaneMachineLabels', 'LaneMachinePath', 'LaneMachineToServerPath',
		'ScaleCodes', 'ScaleLabels', 'ScaleExePaths', 'ScaleCodeToIPInfo', 'ScaleNameToCode', 'ScaleCodeToPath', 'ScaleNameToPath',
		'ScaleCodeToName', 'ScaleCodeToSection', 'ScaleCodeToBrand', 'ScaleCodeToModel', 'ScaleCodeToLocation',
		'ScaleCodeToIPNetwork', 'ScaleCodeToIPDevice', 'ScaleCodeToFullIP', 'ScaleCodeToPortRaw', 'ScaleCodeToTcpPort',
		'ScaleCodeToBaseMode', 'ScaleCodeToType', 'ScaleCodeToBaud', 'ScaleCodeToSub', 'ScaleCodeToPlumDir',
		'BackofficeNumToMachineName', 'BackofficeNumToLabel', 'BackofficeNumToPath',
		'ServerMachineName', 'ServerLabel', 'ServerPath', 'WindowsScales'
	)
	# Published to FunctionResults (the node properties plus the reverse maps)
	$resultNames = $nodeNames + @('MachineNameToLaneNum', 'MachineNameToBackofficeNum', 'MachineNameToBackofficePath')
	# Hashtable maps (cache: JSON object <-> hashtable)
	$mapNames = @($resultNames | Where-Object { $_ -notmatch '^(NumberOf|ServerMachineName$|ServerLabel$|ServerPath$|LaneMachineNames$|ScaleCodes$)' })
	# Scale fields that also get their own ScaleCodeTo<Field> map (only when set)
	$scaleFieldMaps = @(
		@('Section', 'ScaleCodeToSection'), @('ScaleBrand', 'ScaleCodeToBrand'), @('ScaleModel', 'ScaleCodeToModel'),
		@('ScaleLocation', 'ScaleCodeToLocation'), @('IPNetwork', 'ScaleCodeToIPNetwork'), @('IPDevice', 'ScaleCodeToIPDevice'),
		@('FullIP', 'ScaleCodeToFullIP'), @('PortRaw', 'ScaleCodeToPortRaw'), @('TcpPort', 'ScaleCodeToTcpPort'),
		@('BaseMode', 'ScaleCodeToBaseMode'), @('Type', 'ScaleCodeToType'), @('Baud', 'ScaleCodeToBaud'),
		@('Sub', 'ScaleCodeToSub'), @('PlumDir', 'ScaleCodeToPlumDir')
	)

	# Count labels (GUI only; absent in background jobs)
	$updateLabels = {
		param ($Servers, $Backoffices, $Lanes, $Scales)
		if ($null -ne $NodesBackoffices) { $NodesBackoffices.Text = "Number of Backoffices: $Backoffices" }
		if ($null -ne $NodesStore) { $NodesStore.Text = "Number of Lanes: $Lanes" }
		if ($null -ne $scalesLabel) { $scalesLabel.Text = "Number of Scales: $Scales" }
		if ($null -ne $form) { $form.Refresh() }
	}

	# Builds $Nodes from the local variables and publishes everything (dot-sourced: runs in
	# this function's scope)
	$publish = {
		$nodeProps = [ordered]@{ }
		foreach ($n in $nodeNames) { $nodeProps[$n] = Get-Variable -Name $n -ValueOnly }
		$Nodes = [PSCustomObject]$nodeProps
		foreach ($n in $resultNames) { $script:FunctionResults[$n] = Get-Variable -Name $n -ValueOnly }
		$script:FunctionResults['Nodes'] = $Nodes
		$script:FunctionResults['XchNodesIniPathsUsed'] = @($XchNodesIniPathsUsed | Select-Object -Unique)
		& $updateLabels $NumberOfServers $NumberOfBackoffices $NumberOfLanes $NumberOfScales
	}

	# Store number as used for the cache match (3 digits, 4+ digit stores keep theirs)
	$normalizeStore = {
		param ([string]$Value)
		$digits = ([string]$Value -replace '[^\d]', '')
		if (-not $digits) { return $Value }
		try
		{
			if ($digits.Length -le 3) { return ([int]$digits).ToString('000') }
			return ([int]$digits).ToString('0000')
		}
		catch { return $Value }
	}
	$StoreNumberNorm = & $normalizeStore $StoreNumber

	# ------------------------------------------------------------------------------------------------
	# 0a. In-memory results for this store (this launch already discovered them)
	# ------------------------------------------------------------------------------------------------
	if (-not $RefreshCache)
	{
		try
		{
			$existingStoreNorm = & $normalizeStore ([string]$script:FunctionResults['StoreNumber'])
			if ($script:FunctionResults['Nodes'] -and ($existingStoreNorm -eq $StoreNumberNorm) -and $script:FunctionResults['LaneNumToMachineName'])
			{
				& $updateLabels $script:FunctionResults['NumberOfServers'] $script:FunctionResults['NumberOfBackoffices'] $script:FunctionResults['NumberOfLanes'] $script:FunctionResults['NumberOfScales']
				return $script:FunctionResults['Nodes']
			}
		}
		catch { }
	}

	# ------------------------------------------------------------------------------------------------
	# 0b. File cache for this store
	# ------------------------------------------------------------------------------------------------
	if ((-not $RefreshCache) -and (Test-Path -LiteralPath $CachePath))
	{
		try
		{
			$raw = Get-Content -LiteralPath $CachePath -Raw -ErrorAction Stop
			$cacheObj = $null
			if (-not [string]::IsNullOrWhiteSpace($raw)) { $cacheObj = $raw | ConvertFrom-Json -ErrorAction Stop }
			if ($cacheObj -and $cacheObj.Results -and $cacheObj.CacheSchemaVersion -and
				([int]$cacheObj.CacheSchemaVersion -eq $CacheSchemaVersion) -and
				$cacheObj.StoreNumber -and ($cacheObj.StoreNumber.ToString() -eq $StoreNumberNorm))
			{
				$r = $cacheObj.Results
				foreach ($n in $mapNames)
				{
					$h = @{ }
					$o = $r.$n
					if ($o -and $o.PSObject -and $o.PSObject.Properties) { foreach ($p in $o.PSObject.Properties) { $h[$p.Name] = $p.Value } }
					Set-Variable -Name $n -Value $h
				}
				$NumberOfLanes = [int]$r.NumberOfLanes
				$NumberOfServers = [int]$r.NumberOfServers
				$NumberOfBackoffices = [int]$r.NumberOfBackoffices
				$NumberOfScales = [int]$r.NumberOfScales
				$LaneMachineNames = @($r.LaneMachineNames)
				$ScaleCodes = @($r.ScaleCodes)
				$ServerMachineName = $r.ServerMachineName
				$ServerLabel = $r.ServerLabel
				$ServerPath = $r.ServerPath
				$XchNodesIniPathsUsed = @()
				if ($r.PSObject.Properties.Name -contains 'XchNodesIniPathsUsed') { $XchNodesIniPathsUsed = @($r.XchNodesIniPathsUsed) }

				. $publish
				return $Nodes
			}
		}
		catch
		{
			# unreadable / old cache: discover again below
		}
	}

	# ====================================================================================
	# DISCOVERY - start empty
	# ====================================================================================
	foreach ($n in $mapNames) { Set-Variable -Name $n -Value @{ } }
	$LaneMachineNames = @()
	$ScaleCodes = @()
	$ServerMachineName = $null
	$ServerLabel = $null
	$ServerPath = $null
	$NumberOfLanes = 0
	$NumberOfServers = 0
	$NumberOfBackoffices = 0
	$NumberOfScales = 0

	# TER scales are grouped by their 80X terminal; TBS scales keep the ScaleCode stored in
	# TBS_SCL_ver520.
	$TerScaleBy80X = @{ }
	$TbsScaleRows = New-Object System.Collections.ArrayList

	# Classify one TER_TAB / Ter_Load row (dot-sourced: updates this function's variables)
	$addTerRow = {
		param ([string]$terminal, [string]$label, [string]$path, [string]$hostPath)

		if (($terminal -match '^0\d\d$' -or $path -match '^\\\\[^\\]+\\') -and $terminal -notmatch '^8' -and $terminal -notmatch '^9')
		{
			# Lane
			$machineName = if ($path -match '\\\\([^\\]+)\\') { $matches[1] } else { $terminal }
			$LaneMachineNames += $machineName
			if ($terminal -match '^0\d\d$') { $LaneNumToMachineName[$terminal] = $machineName }
			$LaneMachineLabels[$machineName] = $label
			$LaneMachinePath[$machineName] = $path
			$LaneMachineToServerPath[$machineName] = $hostPath
		}
		elseif ($terminal -match '^8\d\d$' -and $path -match '(?i)XchScale\\XchScale\.exe$')
		{
			# TER scale (one entry per 80X terminal; later rows only fill gaps)
			if (-not $TerScaleBy80X.ContainsKey($terminal))
			{
				$TerScaleBy80X[$terminal] = [PSCustomObject]@{
					Code          = $terminal
					ScaleCode     = $terminal
					BaseScaleCode = $terminal
					Label         = $label
					ScaleName     = $label
					Path          = $path
					HostPath      = $hostPath
					ScaleBrand    = $null
					Scalevendor   = $null
					ScaleModel    = $null
					ScaleLocation = $null
					IPNetwork     = $null
					IPDevice      = $null
					FullIP        = $null
					PortRaw       = $null
					TcpPort       = $null
					Section       = $null
					BaseMode      = $null
					Type          = $null
					Baud          = $null
					Sub           = $null
					PlumDir       = $null
					Active        = $null
					Source        = 'TER'
				}
			}
			else
			{
				$existingTer = $TerScaleBy80X[$terminal]
				if ([string]::IsNullOrWhiteSpace([string]$existingTer.Label) -and $label) { $existingTer.Label = $label }
				if ([string]::IsNullOrWhiteSpace([string]$existingTer.ScaleName) -and $label) { $existingTer.ScaleName = $label }
				if ([string]::IsNullOrWhiteSpace([string]$existingTer.Path) -and $path) { $existingTer.Path = $path }
				if ([string]::IsNullOrWhiteSpace([string]$existingTer.HostPath) -and $hostPath) { $existingTer.HostPath = $hostPath }
			}
		}
		elseif ($terminal -eq '901' -and $path -match '^@[^@]+$')
		{
			# Store server
			$ServerMachineName = $path -replace '^@', ''
			$ServerLabel = $label
			$ServerPath = $path
		}
		elseif ($terminal -match '^9(0[2-9]|[1-8]\d|9[0-8])$' -and $path -match '^@[^@]+$')
		{
			# Backoffice
			$BackofficeNumToMachineName[$terminal] = $path -replace '^@', ''
			$BackofficeNumToLabel[$terminal] = $label
			$BackofficeNumToPath[$terminal] = $path
		}
	}

	$TerLoadSqlPath = $null
	if (-not [string]::IsNullOrWhiteSpace($LoadPath)) { $TerLoadSqlPath = Join-Path $LoadPath 'Ter_Load.sql' }

	# ====================================================================================
	# XchNodes.ini candidates: <storeman>\XchScale (+ one or two folder levels below)
	# ====================================================================================
	$XchSearchRoots = @()
	foreach ($rootCandidate in @([string]$script:FunctionResults['StoremanPath'], [string]$script:BasePath))
	{
		if (-not [string]::IsNullOrWhiteSpace($rootCandidate)) { $XchSearchRoots += [System.IO.Path]::Combine($rootCandidate.Trim().TrimEnd('\'), 'XchScale') }
	}
	if (-not [string]::IsNullOrWhiteSpace($OfficePath))
	{
		try
		{
			$officeTrimmed = ([string]$OfficePath).Trim().TrimEnd('\')
			if ((Split-Path -Path $officeTrimmed -Leaf) -ieq 'Office')
			{
				$storemanRoot = Split-Path -Path $officeTrimmed -Parent
				if (-not [string]::IsNullOrWhiteSpace($storemanRoot)) { $XchSearchRoots += [System.IO.Path]::Combine($storemanRoot.TrimEnd('\'), 'XchScale') }
			}
			$XchSearchRoots += [System.IO.Path]::Combine($officeTrimmed, 'XchScale')
		}
		catch { }
	}

	$XchNodesIniCandidates = New-Object System.Collections.Generic.List[string]
	$seenIni = @{ }
	$addIni = {
		param ([string]$IniPath)
		if ([System.IO.File]::Exists($IniPath) -and -not $seenIni.ContainsKey($IniPath.Trim().ToLowerInvariant()))
		{
			$seenIni[$IniPath.Trim().ToLowerInvariant()] = $true
			$XchNodesIniCandidates.Add($IniPath)
		}
	}
	$seenRoots = @{ }
	foreach ($root in $XchSearchRoots)
	{
		$rootPath = ([string]$root).Trim().Trim('"')
		if ([string]::IsNullOrWhiteSpace($rootPath) -or $seenRoots.ContainsKey($rootPath.ToLowerInvariant())) { continue }
		$seenRoots[$rootPath.ToLowerInvariant()] = $true
		try
		{
			if (-not (Test-Path -LiteralPath $rootPath -PathType Container)) { continue }
			& $addIni ([System.IO.Path]::Combine($rootPath, 'XchNodes.ini'))

			# Bounded search (some stores have very large XchScale trees): children, then
			# grandchildren only if nothing was found yet
			$childDirs = @(Get-ChildItem -LiteralPath $rootPath -Directory -ErrorAction SilentlyContinue)
			foreach ($childDir in $childDirs) { & $addIni ([System.IO.Path]::Combine([string]$childDir.FullName, 'XchNodes.ini')) }
			if ($XchNodesIniCandidates.Count -eq 0)
			{
				foreach ($childDir in $childDirs)
				{
					foreach ($grandChildDir in @(Get-ChildItem -LiteralPath $childDir.FullName -Directory -ErrorAction SilentlyContinue))
					{
						& $addIni ([System.IO.Path]::Combine([string]$grandChildDir.FullName, 'XchNodes.ini'))
					}
				}
			}
		}
		catch { }
	}

	# ====================================================================================
	# 1. PRIMARY: STORE DATABASE (TER_TAB, TBS_SCL_ver520)
	# ====================================================================================
	$server = $script:FunctionResults['DBSERVER']
	$database = $script:FunctionResults['DBNAME']
	$ConnectionString = Normalize_Sql_ConnectionString -RawConnectionString $script:FunctionResults['ConnectionString'] -Server $server -Database $database -SqlUser $script:FunctionResults['SQL_UserID'] -SqlPwd $script:FunctionResults['SQL_UserPwd']
	$NodesFromDatabase = $false
	$SqlModule = $script:FunctionResults['SqlModuleName']

	if (-not $SqlModule -or $SqlModule -eq 'None')
	{
		Write_Log "SQL PowerShell module not installed - using the built-in SQL client for node info." "yellow"
	}

	# The lane query filters on this store (TER_TAB.F1056); without a known store number the
	# connection is a placeholder target and would only burn ~15 s on timeouts.
	$hasUsableStoreNumber = (([string]$StoreNumber -replace '[^\d]', '').Length -gt 0)
	if ($ConnectionString -and -not $hasUsableStoreNumber)
	{
		Write_Log "Store number unknown - skipping the store database lookup (no store to query against). Using local files instead." "yellow"
	}

	if ($ConnectionString -and $hasUsableStoreNumber)
	{
		try
		{
			if ($SqlModule -and $SqlModule -ne 'None') { Import-Module $SqlModule -ErrorAction SilentlyContinue | Out-Null }
		}
		catch { }
		$invokeSqlCmd = Get-Command Invoke-Sqlcmd -ErrorAction SilentlyContinue
		$supportsConnStr = $false
		$supportsConnTimeout = $false
		$startupQueryTimeoutSeconds = 10
		$startupConnectionTimeoutSeconds = 5
		$startupConnectionString = $ConnectionString
		if ($invokeSqlCmd)
		{
			$supportsConnStr = $invokeSqlCmd.Parameters.ContainsKey('ConnectionString')
			$supportsConnTimeout = $invokeSqlCmd.Parameters.ContainsKey('ConnectionTimeout')
		}
		elseif ($SqlModule -and $SqlModule -ne 'None')
		{
			Write_Log "SQL module '$SqlModule' not available on this machine - using the built-in SQL client." "yellow"
		}
		else
		{
			Write_Log "SQL module not available on this machine - using the built-in SQL client." "yellow"
		}

		# Invoke-Sqlcmd when available, else SqlClient (returns rows either way)
		$invokeStartupQuery = {
			param ([string]$Query, [int]$QueryTimeout = 10)

			if ($invokeSqlCmd)
			{
				if ($supportsConnStr) { return (& $invokeSqlCmd -ConnectionString $startupConnectionString -Query $Query -QueryTimeout $QueryTimeout -ErrorAction Stop) }
				if ($supportsConnTimeout) { return (& $invokeSqlCmd -ServerInstance $server -Database $database -Query $Query -QueryTimeout $QueryTimeout -ConnectionTimeout $startupConnectionTimeoutSeconds -ErrorAction Stop) }
				return (& $invokeSqlCmd -ServerInstance $server -Database $database -Query $Query -QueryTimeout $QueryTimeout -ErrorAction Stop)
			}

			$dt = New-Object System.Data.DataTable
			$cn = New-Object System.Data.SqlClient.SqlConnection $startupConnectionString
			try
			{
				$cn.Open()
				$cmd = $cn.CreateCommand()
				$cmd.CommandText = $Query
				$cmd.CommandTimeout = $QueryTimeout
				$da = New-Object System.Data.SqlClient.SqlDataAdapter $cmd
				[void]$da.Fill($dt)
			}
			finally
			{
				try { if ($cn) { $cn.Close() } } catch { }
				try { if ($cn) { $cn.Dispose() } } catch { }
			}
			return $dt
		}

		# Short connect timeout for the startup queries
		if (-not [string]::IsNullOrWhiteSpace($startupConnectionString))
		{
			try
			{
				$csb = New-Object System.Data.SqlClient.SqlConnectionStringBuilder $startupConnectionString
				$csb.PSBase.ConnectTimeout = $startupConnectionTimeoutSeconds
				$startupConnectionString = $csb.ConnectionString
			}
			catch
			{
				if ($startupConnectionString -notmatch '(?i)\bConnect\s*Timeout\s*=')
				{
					$startupConnectionString = $startupConnectionString.Trim().TrimEnd(';') + ";Connect Timeout=$startupConnectionTimeoutSeconds"
				}
			}
		}

		$NodesFromDatabase = $true
		$safeStoreNumber = ($StoreNumber -replace '[^\d]', '')
		if ($safeStoreNumber.Length -le 3) { $safeStoreNumber = ([int]$safeStoreNumber).ToString('000') }
		else { $safeStoreNumber = ([int]$safeStoreNumber).ToString('0000') }
		try
		{
			$terTabResult = & $invokeStartupQuery "SELECT F1057, F1058, F1125, F1169 FROM TER_TAB WHERE F1056 = '$safeStoreNumber'" $startupQueryTimeoutSeconds
			foreach ($row in $terTabResult)
			{
				. $addTerRow ([string]$row.F1057) ([string]$row.F1058) ([string]$row.F1125) ([string]$row.F1169)
			}

			$tbsSclScalesResult = $null
			try
			{
				$tbsSclScalesResult = & $invokeStartupQuery "SELECT ScaleCode, ScaleName, ScaleLocation, IPNetwork, IPDevice, Active, ScaleBrand, ScaleModel FROM TBS_SCL_ver520 WHERE Active = 'Y'" $startupQueryTimeoutSeconds
			}
			catch
			{
				# A store without the TBS scale table simply has no TBS scales
				if ($_.Exception.Message -notmatch "Invalid object name 'TBS_SCL_ver520'") { throw }
			}

			# Column value as string, $null when empty / DBNull
			$col = {
				param ($v)
				if ([string]::IsNullOrWhiteSpace([string]$v)) { return $null }
				return [string]$v
			}
			$tbsRowOrdinal = 0
			foreach ($row in @($tbsSclScalesResult))
			{
				if ($null -eq $row) { continue }
				$tbsRowOrdinal++
				$rawScaleCode = ([string]$row.ScaleCode).Trim()
				if ([string]::IsNullOrWhiteSpace($rawScaleCode)) { continue }

				$tbsScaleName = & $col $row.ScaleName
				$tbsIPNetwork = & $col $row.IPNetwork
				if ($tbsIPNetwork) { $tbsIPNetwork = $tbsIPNetwork.Trim() }
				$tbsIPDevice = & $col $row.IPDevice
				if ($tbsIPDevice) { $tbsIPDevice = $tbsIPDevice.Trim() }
				$tbsBrand = & $col $row.ScaleBrand
				$tbsLabel = if ($tbsScaleName) { $tbsScaleName } else { "Scale $rawScaleCode" }

				$null = $TbsScaleRows.Add([PSCustomObject]@{
						RawScaleCode  = $rawScaleCode
						TbsRowOrdinal = $tbsRowOrdinal
						ScaleCode     = $rawScaleCode
						BaseScaleCode = $rawScaleCode
						Label         = $tbsLabel
						ScaleName     = $tbsLabel
						Path          = $null
						HostPath      = $null
						ScaleBrand    = $tbsBrand
						Scalevendor   = $tbsBrand
						ScaleModel    = & $col $row.ScaleModel
						ScaleLocation = & $col $row.ScaleLocation
						IPNetwork     = $tbsIPNetwork
						IPDevice      = $tbsIPDevice
						FullIP        = if ($tbsIPNetwork -or $tbsIPDevice) { "$tbsIPNetwork$tbsIPDevice" } else { $null }
						PortRaw       = $null
						TcpPort       = $null
						Section       = $null
						BaseMode      = $null
						Type          = $null
						Baud          = $null
						Sub           = $null
						PlumDir       = $null
						Active        = & $col $row.Active
						Source        = 'TBS'
					})
			}
		}
		catch
		{
			Write_Log "Failed to retrieve counts from the database: $_" "yellow"
			$NodesFromDatabase = $false
		}
	}

	# ====================================================================================
	# 2. FALLBACK: Office\Load\Ter_Load.sql
	# ====================================================================================
	if ((-not $NodesFromDatabase) -and $TerLoadSqlPath -and (Test-Path -LiteralPath $TerLoadSqlPath))
	{
		Write_Log "Using Ter_Load.sql as backup for TER_TAB information." "yellow"
		$content = Get-Content -LiteralPath $TerLoadSqlPath -Raw
		if ($content -match 'INSERT INTO Ter_Load VALUES\s*(.*);' -or $content -match 'INSERT INTO Ter_Load VALUES\s*(.*)')
		{
			foreach ($value in ($matches[1] -split '\),\s*\(' | ForEach-Object { $_.Trim('() ') }))
			{
				$fields = @($value -split "',\s*'" | ForEach-Object { $_.Trim("'") })
				if ($fields.Count -ge 5 -and $fields[0] -eq $StoreNumber)
				{
					. $addTerRow ([string]$fields[1]) ([string]$fields[2]) ([string]$fields[3]) ([string]$fields[4])
				}
			}
		}
	}

	# ====================================================================================
	# 2.5 ENRICH TER 80X SCALES FROM XchNodes.ini (best section per scale wins)
	# ====================================================================================
	$XchNodesIniPathsUsed = @()
	if ($TerScaleBy80X.Count -gt 0 -and $XchNodesIniCandidates.Count -gt 0)
	{
		$AllowedScaleCodeSet = @{ }
		foreach ($allowedCode in @($TerScaleBy80X.Keys | Where-Object { $_ -match '^8\d\d$' })) { $AllowedScaleCodeSet[$allowedCode] = $true }

		# Section names are <store><terminal>, e.g. 001801 or 0001801
		$storeSectionPrefixes = @()
		$storeDigits = ($StoreNumber -replace '[^\d]', '')
		if ($storeDigits)
		{
			try { $storeSectionPrefixes += ([int]$storeDigits).ToString('000'); $storeSectionPrefixes += ([int]$storeDigits).ToString('0000') }
			catch { }
			$storeSectionPrefixes += $storeDigits
			$storeSectionPrefixes = @($storeSectionPrefixes | Select-Object -Unique)
		}

		$BestXchByBaseScaleCode = @{ }
		$sourceRank = 0
		foreach ($candidateIni in @($XchNodesIniCandidates | Select-Object -Unique))
		{
			$sourceRank++
			$XchNodesIniPathsUsed += $candidateIni
			try
			{
				$iniRaw = Get-Content -LiteralPath $candidateIni -Raw -ErrorAction Stop
				foreach ($sectionMatch in [regex]::Matches($iniRaw, '(?ms)^\[(?<name>[^\]]+)\]\s*(?<body>.*?)(?=^\[|\z)'))
				{
					$sectionKey = [string]$sectionMatch.Groups['name'].Value.Trim()
					if ([string]::IsNullOrWhiteSpace($sectionKey)) { continue }

					$currentMap = @{ }
					foreach ($bodyLine in ([string]$sectionMatch.Groups['body'].Value -split "`r?`n"))
					{
						$bodyTrim = $bodyLine.Trim()
						if ([string]::IsNullOrWhiteSpace($bodyTrim) -or $bodyTrim -match '^[;#]') { continue }
						if ($bodyTrim -match '^\s*([^=]+?)\s*=\s*(.*)\s*$') { $currentMap[$matches[1].Trim()] = $matches[2] }
					}
					$get = { param ($k) if ($currentMap.ContainsKey($k)) { [string]$currentMap[$k] } else { $null } }

					$sectionTerminal = $null
					if ($sectionKey -match '(\d{3})$' -and $matches[1] -match '^8\d\d$') { $sectionTerminal = $matches[1] }

					# NUMBER=1 -> 801, NUMBER=801 -> 801
					$numberRaw = & $get 'NUMBER'
					if ($numberRaw) { $numberRaw = $numberRaw.Trim() }
					$scaleCodeFromNumber = $null
					if ($numberRaw -match '^\d+$')
					{
						try
						{
							$n = [int]$numberRaw
							if ($n -ge 0 -and $n -le 99) { $scaleCodeFromNumber = ('8{0:00}' -f $n) }
							elseif ($n -ge 800 -and $n -le 899) { $scaleCodeFromNumber = ('{0:000}' -f $n) }
						}
						catch { }
					}

					# Match rank: 0 = <store><terminal> section, 1 = terminal suffix only, 2 = NUMBER
					$matchedScaleCode = $null
					$matchRank = 99
					if ($sectionTerminal -and $AllowedScaleCodeSet.ContainsKey($sectionTerminal))
					{
						$matchedScaleCode = $sectionTerminal
						$matchRank = 1
						foreach ($prefix in $storeSectionPrefixes) { if ($sectionKey -ieq "$prefix$sectionTerminal") { $matchRank = 0; break } }
					}
					elseif ($scaleCodeFromNumber -and $AllowedScaleCodeSet.ContainsKey($scaleCodeFromNumber))
					{
						$matchedScaleCode = $scaleCodeFromNumber
						$matchRank = 2
					}
					if (-not $matchedScaleCode) { continue }

					# Port=IP 192.168.1.50:3001 -> FullIP / TcpPort / IPNetwork + IPDevice
					$portRaw = & $get 'Port'
					$tcpPort = $null
					$fullIP = $null
					$ipNetwork = $null
					$ipDevice = $null
					if (-not [string]::IsNullOrWhiteSpace($portRaw))
					{
						$portValue = ($portRaw -replace '(?i)^\s*IP\s*', '').Trim()
						if ($portValue -match '^\s*([^:]+?)\s*:(\d+)\s*$')
						{
							$fullIP = $matches[1].Trim()
							$tcpPort = $matches[2].Trim()
						}
						else { $fullIP = $portValue }

						if ($fullIP -match '^\d{1,3}(?:\.\d{1,3}){3}$')
						{
							$lastDot = $fullIP.LastIndexOf('.')
							$ipNetwork = $fullIP.Substring(0, $lastDot + 1)
							$ipDevice = $fullIP.Substring($lastDot + 1)
						}
					}

					$completeness = 0
					if ($fullIP) { $completeness += 10 }
					if (-not [string]::IsNullOrWhiteSpace((& $get 'Scalevendor'))) { $completeness += 5 }
					if (-not [string]::IsNullOrWhiteSpace((& $get 'ScaleModel'))) { $completeness += 5 }
					if ($portRaw) { $completeness += 3 }
					foreach ($k in 'Baud', 'Type', 'BaseMode') { if (-not [string]::IsNullOrWhiteSpace((& $get $k))) { $completeness += 1 } }

					$entryObj = [PSCustomObject]@{
						SourceRank   = $sourceRank
						MatchRank    = $matchRank
						Completeness = $completeness
						Section      = $sectionKey
						BaseMode     = & $get 'BaseMode'
						Type         = & $get 'Type'
						ScaleBrand   = & $get 'Scalevendor'
						ScaleModel   = & $get 'ScaleModel'
						Baud         = & $get 'Baud'
						PortRaw      = $portRaw
						TcpPort      = $tcpPort
						IPNetwork    = $ipNetwork
						IPDevice     = $ipDevice
						FullIP       = $fullIP
						Sub          = & $get 'Sub'
						PlumDir      = & $get 'PlumDir'
					}

					# Keep the best section: lower MatchRank, then more complete, then earlier file
					$existingXch = $BestXchByBaseScaleCode[$matchedScaleCode]
					if (-not $existingXch -or
						$entryObj.MatchRank -lt $existingXch.MatchRank -or
						($entryObj.MatchRank -eq $existingXch.MatchRank -and $entryObj.Completeness -gt $existingXch.Completeness) -or
						($entryObj.MatchRank -eq $existingXch.MatchRank -and $entryObj.Completeness -eq $existingXch.Completeness -and $entryObj.SourceRank -lt $existingXch.SourceRank))
					{
						$BestXchByBaseScaleCode[$matchedScaleCode] = $entryObj
					}
				}
			}
			catch
			{
				Write_Log "Failed to read XchNodes.ini '$candidateIni': $_" "yellow"
			}
		}

		# Fill the TER scales' empty fields from their best XchNodes section
		foreach ($terCode in @($TerScaleBy80X.Keys))
		{
			$xchEntry = $BestXchByBaseScaleCode[$terCode]
			$terEntry = $TerScaleBy80X[$terCode]
			if (-not $xchEntry -or -not $terEntry) { continue }
			foreach ($field in 'IPNetwork', 'IPDevice', 'FullIP', 'PortRaw', 'TcpPort', 'Section', 'BaseMode', 'Type', 'Baud', 'Sub', 'PlumDir', 'ScaleModel')
			{
				if ([string]::IsNullOrWhiteSpace([string]$terEntry.$field) -and $xchEntry.$field) { $terEntry.$field = [string]$xchEntry.$field }
			}
			if ([string]::IsNullOrWhiteSpace([string]$terEntry.ScaleBrand) -and $xchEntry.ScaleBrand)
			{
				$terEntry.ScaleBrand = [string]$xchEntry.ScaleBrand
				$terEntry.Scalevendor = [string]$xchEntry.ScaleBrand
			}
		}
	}

	# ====================================================================================
	# 2.75 DROP TER SCALES THAT ARE ALSO A TBS SCALE (same IP) - the TBS row wins
	# ====================================================================================
	$normalizedIp = {
		param ($e)
		if (-not [string]::IsNullOrWhiteSpace([string]$e.FullIP)) { return ([string]$e.FullIP).Trim().ToLowerInvariant() }
		if (-not [string]::IsNullOrWhiteSpace([string]$e.IPNetwork) -or -not [string]::IsNullOrWhiteSpace([string]$e.IPDevice))
		{
			return ("$([string]$e.IPNetwork)$([string]$e.IPDevice)").Trim().ToLowerInvariant()
		}
		return $null
	}
	$TbsByNormalizedIp = @{ }
	foreach ($tbsEntry in @($TbsScaleRows))
	{
		$ip = & $normalizedIp $tbsEntry
		if ($ip -and -not $TbsByNormalizedIp.ContainsKey($ip)) { $TbsByNormalizedIp[$ip] = $tbsEntry }
	}

	$FinalTerBy80X = @{ }
	foreach ($terCode in @($TerScaleBy80X.Keys | Sort-Object { [int]$_ }))
	{
		$terEntry = $TerScaleBy80X[$terCode]
		$ip = & $normalizedIp $terEntry
		if ($ip -and $TbsByNormalizedIp.ContainsKey($ip))
		{
			$matchingTbsRow = $TbsByNormalizedIp[$ip]
			foreach ($field in 'Path', 'HostPath', 'PortRaw', 'TcpPort', 'Section', 'BaseMode', 'Type', 'Baud', 'Sub', 'PlumDir')
			{
				if ([string]::IsNullOrWhiteSpace([string]$matchingTbsRow.$field) -and $terEntry.$field) { $matchingTbsRow.$field = [string]$terEntry.$field }
			}
			continue
		}
		$FinalTerBy80X[$terCode] = $terEntry
	}

	# ====================================================================================
	# 2.9 FINAL SCALE KEYS AND MAPS (TER by 80X first, then TBS by original ScaleCode)
	# ====================================================================================
	$addScale = {
		param ([string]$finalKey, $entry, [string]$source)

		$finalObj = [PSCustomObject]@{
			Code          = $finalKey
			ScaleCode     = $finalKey
			BaseScaleCode = $entry.BaseScaleCode
			Label         = $entry.Label
			ScaleName     = $entry.ScaleName
			Path          = $entry.Path
			HostPath      = $entry.HostPath
			ScaleBrand    = $entry.ScaleBrand
			Scalevendor   = if ($entry.Scalevendor) { $entry.Scalevendor } else { $entry.ScaleBrand }
			ScaleModel    = $entry.ScaleModel
			ScaleLocation = $entry.ScaleLocation
			IPNetwork     = $entry.IPNetwork
			IPDevice      = $entry.IPDevice
			FullIP        = $entry.FullIP
			PortRaw       = $entry.PortRaw
			TcpPort       = $entry.TcpPort
			Section       = $entry.Section
			BaseMode      = $entry.BaseMode
			Type          = $entry.Type
			Baud          = $entry.Baud
			Sub           = $entry.Sub
			PlumDir       = $entry.PlumDir
			Active        = $entry.Active
			Source        = $source
		}

		$ScaleCodes += $finalKey
		$ScaleCodeToIPInfo[$finalKey] = $finalObj
		$ScaleLabels[$finalKey] = $finalObj.Label
		$ScaleExePaths[$finalKey] = $finalObj.Path
		$ScaleCodeToPath[$finalKey] = $finalObj.Path
		if ($finalObj.ScaleName)
		{
			$ScaleNameToCode[$finalObj.ScaleName] = $finalKey
			$ScaleNameToPath[$finalObj.ScaleName] = $finalObj.Path
			$ScaleCodeToName[$finalKey] = $finalObj.ScaleName
		}
		foreach ($fm in $scaleFieldMaps)
		{
			$fv = $finalObj.($fm[0])
			if ($fv) { (Get-Variable -Name $fm[1] -ValueOnly)[$finalKey] = $fv }
		}
	}

	foreach ($terCode in @($FinalTerBy80X.Keys | Sort-Object { [int]$_ }))
	{
		. $addScale ([string]$terCode) $FinalTerBy80X[$terCode] 'TER'
	}

	# A TBS ScaleCode that collides with an existing key gets a _TBS<n> suffix
	$TbsKeyCounts = @{ }
	foreach ($tbsEntry in @($TbsScaleRows))
	{
		$rawKey = [string]$tbsEntry.RawScaleCode
		if ([string]::IsNullOrWhiteSpace($rawKey)) { continue }
		$finalKey = $rawKey
		if (-not $TbsKeyCounts.ContainsKey($rawKey)) { $TbsKeyCounts[$rawKey] = 1 }
		while ($ScaleCodeToIPInfo.ContainsKey($finalKey))
		{
			$TbsKeyCounts[$rawKey]++
			$finalKey = "{0}_TBS{1}" -f $rawKey, $TbsKeyCounts[$rawKey]
		}
		. $addScale $finalKey $tbsEntry 'TBS'
	}

	# ====================================================================================
	# 3. REVERSE MAPS, COUNTS, BIZERBA (WINDOWS) SCALES
	# ====================================================================================
	foreach ($kv in @($LaneNumToMachineName.GetEnumerator())) { $MachineNameToLaneNum[$kv.Value] = $kv.Key }
	foreach ($kv in @($BackofficeNumToMachineName.GetEnumerator()))
	{
		$MachineNameToBackofficeNum[$kv.Value] = $kv.Key
		if ($BackofficeNumToPath.ContainsKey($kv.Key)) { $MachineNameToBackofficePath[$kv.Value] = $BackofficeNumToPath[$kv.Key] }
	}

	$NumberOfLanes = $LaneMachineNames.Count
	$NumberOfServers = if ($ServerMachineName) { 1 } else { 0 }
	$NumberOfBackoffices = $BackofficeNumToMachineName.Count
	$NumberOfScales = $ScaleCodes.Count

	# Bizerba scales run Windows (C$ shares, credentials, file deployment)
	foreach ($code in @($ScaleCodeToIPInfo.Keys))
	{
		$scale = $ScaleCodeToIPInfo[$code]
		foreach ($field in 'ScaleBrand', 'Scalevendor', 'ScaleModel', 'ScaleName', 'Label')
		{
			if ($scale.$field -and ([string]$scale.$field -match '(?i)bizerba')) { $WindowsScales[$code] = $scale; break }
		}
	}

	. $publish

	# ====================================================================================
	# 4. CACHE WRITE (keys sorted so the file is readable and stable)
	# ====================================================================================
	try
	{
		$numKey = { [double]((([string]$_.Key) -replace '[^\d]', '0')) }
		$sortMap = {
			param ($Map, [object[]]$SortBy)
			$o = [ordered]@{ }
			foreach ($kv in @($Map.GetEnumerator() | Sort-Object $SortBy)) { $o[$kv.Key] = $kv.Value }
			return $o
		}

		$out = [ordered]@{ }
		foreach ($n in $mapNames) { $out[$n] = & $sortMap (Get-Variable -Name $n -ValueOnly) @($numKey, { $_.Key }) }

		# Lanes: only 3-digit lane numbers; the per-machine maps follow the lane order
		$sortedLaneNums = @($LaneNumToMachineName.Keys | Where-Object { $_ -match '^\d{3}$' } | Sort-Object { [int]$_ })
		$out['LaneNumToMachineName'] = [ordered]@{ }
		foreach ($k in 'LaneMachineLabels', 'LaneMachinePath', 'LaneMachineToServerPath') { $out[$k] = [ordered]@{ } }
		foreach ($ln in $sortedLaneNums)
		{
			$m = $LaneNumToMachineName[$ln]
			$out['LaneNumToMachineName'][$ln] = $m
			if (-not $m) { continue }
			foreach ($k in 'LaneMachineLabels', 'LaneMachinePath', 'LaneMachineToServerPath')
			{
				$src = Get-Variable -Name $k -ValueOnly
				if ($src.ContainsKey($m)) { $out[$k][$m] = $src[$m] }
			}
		}
		$byValueThenKey = @({ [double]((([string]$_.Value) -replace '[^\d]', '0')) }, { $_.Key })
		$out['MachineNameToLaneNum'] = & $sortMap $MachineNameToLaneNum $byValueThenKey
		$out['MachineNameToBackofficeNum'] = & $sortMap $MachineNameToBackofficeNum $byValueThenKey
		$out['ScaleNameToCode'] = & $sortMap $ScaleNameToCode @({ $_.Value }, { $_.Key })
		$out['ScaleNameToPath'] = & $sortMap $ScaleNameToPath @({ $_.Key })
		$out['MachineNameToBackofficePath'] = & $sortMap $MachineNameToBackofficePath @({ $_.Key })

		$outLaneMachineNames = @($LaneMachineNames)
		if ($outLaneMachineNames.Count -gt 0 -and $MachineNameToLaneNum.Count -gt 0)
		{
			$outLaneMachineNames = @($outLaneMachineNames | Sort-Object { [double](([string]$MachineNameToLaneNum[$_]) -replace '[^\d]', '0') }, { $_ })
		}

		$results = [ordered]@{
			NumberOfLanes       = $NumberOfLanes
			NumberOfServers     = $NumberOfServers
			NumberOfBackoffices = $NumberOfBackoffices
			NumberOfScales      = $NumberOfScales
			LaneMachineNames    = $outLaneMachineNames
			ScaleCodes          = @($ScaleCodes | Sort-Object { [double](([string]$_) -replace '[^\d]', '0') }, { $_ })
			ServerMachineName   = $ServerMachineName
			ServerLabel         = $ServerLabel
			ServerPath          = $ServerPath
		}
		foreach ($n in $mapNames) { $results[$n] = $out[$n] }
		$results['XchNodesIniPathsUsed'] = @($XchNodesIniPathsUsed | Select-Object -Unique)

		$cacheOut = [ordered]@{
			LastUpdated        = (Get-Date).ToString('o')
			CacheSchemaVersion = $CacheSchemaVersion
			StoreNumber        = $StoreNumberNorm
			Results            = $results
		}
		($cacheOut | ConvertTo-Json -Depth 16) | Set-Content -LiteralPath $CachePath -Encoding UTF8 -Force
	}
	catch { }

	return $Nodes
}

# ===================================================================================================
#                              FUNCTION: Start_Lane_Protocol_Jobs
# ---------------------------------------------------------------------------------------------------
# Description:
#   Starts the lane SQL protocol background loop: a UI-thread timer probes every lane's SQL
#   protocol (TCP -> Named Pipes -> else File, Offline when unreachable) once a minute in a
#   runspace pool, and keeps the results in $script:LaneProtocols + Protocol_Results.txt.
#   Lanes that end up on File get a one-shot "enable SQL protocols" task scheduled on the lane
#   (Ensure_SQL_Enable_Scheduled_Task_For_File_Lane, run in a hidden helper process).
#   Call once after node discovery; it returns immediately. A second call only updates the
#   lane map - the running loop picks it up on its next scan.
#
# Parameters:
#   - LaneNumToMachineName  [hashtable]: LaneNumber => MachineName
#   - SqlModuleName         [string]: not used (kept so existing callers keep working)
#
# Variables:
#   - $script:LaneProtocols                  lane number / raw key / machine name => protocol
#   - $script:ProtocolResults                @( [pscustomobject]@{ Lane; Protocol } ) sorted on write
#   - $script:ProtocolResultsFile            Protocol_Results.txt (warm start + persistence)
#   - $script:LaneProtocolJobs               lane => @{ PS; Handle; Started } in-flight probes
#   - $script:LaneProtocolPool               runspace pool (rebuilt when a probe hangs)
#   - $script:LaneProtocolLaneMap            the lane map the loop scans
#   - $script:LaneProtocolStop               set by FormClosing to stop the loop
#   - $script:LaneSqlProtocolEnableJobs      lane => helper process scheduling the SQL enable task
#   - $script:LaneSqlProtocolEnableTaskState lane => last scheduling result
#   - $script:LaneProtocolHelpers            the loop's helper scriptblocks (see Notes)
#
# Notes:
#   - The timer handler and its helpers are plain scriptblocks kept in $script: variables.
#     Do NOT use .GetNewClosure() here: a closure runs in its own module scope, so every
#     $script: variable inside it is a different, empty variable (v2.6.7 - v2.6.9 lost all
#     lane probing that way).
#   - Double-start guarded via $script:protocolTimer.
# ===================================================================================================

function Start_Lane_Protocol_Jobs
{
	param (
		[hashtable]$LaneNumToMachineName,
		[string]$SqlModuleName
	)

	try { Add-Type -AssemblyName System.Windows.Forms 2>$null }
	catch { }
	try { Add-Type -AssemblyName System.Data 2>$null }
	catch { }

	# ---------- paths ----------
	$script:ProtocolResultsFile = Join-Path $script:SetupFiles 'Protocol_Results.txt'
	$resultsDir = [System.IO.Path]::GetDirectoryName($script:ProtocolResultsFile)
	if (-not (Test-Path -LiteralPath $resultsDir)) { $null = New-Item -Path $resultsDir -ItemType Directory -Force }
	if (-not (Test-Path -LiteralPath $script:ProtocolResultsFile)) { $null = New-Item -Path $script:ProtocolResultsFile -ItemType File -Force }

	# ---------- state ----------
	if (-not $script:FunctionResults) { $script:FunctionResults = @{ } }
	if (-not $script:LaneProtocols) { $script:LaneProtocols = @{ } }
	if (-not $script:ProtocolResults) { $script:ProtocolResults = @() }
	if (-not $script:LaneProtocolJobs) { $script:LaneProtocolJobs = @{ } }
	if (-not $script:LaneProtocolJobTimeoutSeconds -or $script:LaneProtocolJobTimeoutSeconds -lt 20) { $script:LaneProtocolJobTimeoutSeconds = 20 }
	if (-not $script:LaneSqlProtocolEnableTaskState) { $script:LaneSqlProtocolEnableTaskState = @{ } }
	if (-not $script:LaneSqlProtocolEnableJobs) { $script:LaneSqlProtocolEnableJobs = @{ } }
	if (-not $LaneNumToMachineName) { $LaneNumToMachineName = @{ } }
	$script:LaneProtocolLaneMap = $LaneNumToMachineName
	$script:LaneProtocolStop = $false

	if ($script:protocolTimer) { return }

	# ---------- helpers (plain scriptblocks in script scope - see Notes) ----------
	$script:LaneProtocolHelpers = @{
		# Any value -> [datetime] or $null
		ToDate           = {
			param ($Value)
			if ($null -eq $Value) { return $null }
			if ($Value -is [datetime]) { return [datetime]$Value }
			if ($Value -is [datetimeoffset]) { return ([datetimeoffset]$Value).LocalDateTime }
			if ($Value -is [string])
			{
				$parsed = [datetime]::MinValue
				if (-not [string]::IsNullOrWhiteSpace($Value) -and [datetime]::TryParse($Value, [ref]$parsed)) { return $parsed }
				return $null
			}
			try { return [datetime]$Value }
			catch { return $null }
		}

		# Record one lane's protocol under every key consumers look it up by; returns the machine name
		SetProtocol      = {
			param ([string]$LaneNum, [string]$RawLane, [string]$Protocol)
			$script:LaneProtocols[$LaneNum] = $Protocol
			if ($RawLane) { $script:LaneProtocols[$RawLane] = $Protocol }
			$mn = $null
			if ($script:LaneProtocolLaneMap) { $mn = $script:LaneProtocolLaneMap[$LaneNum] }
			if ($mn) { $script:LaneProtocols[[string]$mn] = $Protocol }
			$script:ProtocolResults = @(@($script:ProtocolResults | Where-Object { $_.Lane -ne $LaneNum }) +
				[pscustomobject]@{ Lane = $LaneNum; Protocol = $Protocol })
			return $mn
		}

		NewPool          = {
			$iss = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
			$pool = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspacePool(1, [Math]::Max(8, [Environment]::ProcessorCount * 2), $iss, $Host)
			try { $pool.ApartmentState = 'MTA' }
			catch { }
			$pool.Open()
			return $pool
		}

		# Next StartTime (default 04:15) occurrence
		NextSqlEnableRun = {
			$next = (Get-Date).Date.AddHours(4).AddMinutes(15)
			if ((Get-Date) -ge $next) { $next = $next.AddDays(1) }
			return $next
		}

		# File-protocol lane: schedule the SQL enable task on it from a hidden helper process
		StartSqlEnable   = {
			param ([string]$LaneNumber, [string]$MachineName)
			if ([string]::IsNullOrWhiteSpace($LaneNumber) -or [string]::IsNullOrWhiteSpace($MachineName)) { return }

			$laneKey = $LaneNumber.PadLeft(3, '0')
			$running = $script:LaneSqlProtocolEnableJobs[$laneKey]
			if ($running -and $running.Process -and -not $running.Process.HasExited) { return }

			# The lane is rescanned every minute - re-check a lane at most every 15 minutes
			$state = $script:LaneSqlProtocolEnableTaskState[$laneKey]
			if ($state -and ($state.LastChecked -is [datetime]) -and ((Get-Date) - $state.LastChecked).TotalMinutes -lt 15) { return }

			$scheduledDate = & $script:LaneProtocolHelpers.NextSqlEnableRun
			$fnBody = ${function:Ensure_SQL_Enable_Scheduled_Task_For_File_Lane}
			if (-not $fnBody)
			{
				$script:LaneSqlProtocolEnableTaskState[$laneKey] = [pscustomobject]@{ TaskPresent = $false; LastChecked = Get-Date; ScheduledFor = $scheduledDate; MachineName = $MachineName; LastResult = 'NoFunction' }
				return
			}

			# The helper process gets the function from memory (works for .ps1, .exe and irm|iex
			# launches alike) plus a Write_Log shim that prints to stdout, so the reason for a
			# failure comes back through the redirected output file.
			$launcherScriptPath = Join-Path $script:SetupFiles ("LaneSqlEnableLauncher_{0}.ps1" -f $laneKey)
			$launcherOutPath = Join-Path $script:SetupFiles ("LaneSqlEnableLauncher_{0}.out.txt" -f $laneKey)
			$launcherScript = (@(
					'param([string]$LaneNumber, [string]$MachineName, [string]$TcpPort = ''1433'', [string]$StartTime = ''04:15'')'
					'function Write_Log { param([string]$Message, $Color = ''Black'') Write-Host $Message }'
					'function Ensure_SQL_Enable_Scheduled_Task_For_File_Lane'
					'{'
					$fnBody.ToString()
					'}'
					'$ok = $false'
					'try { $ok = [bool](Ensure_SQL_Enable_Scheduled_Task_For_File_Lane -LaneNumber $LaneNumber -MachineName $MachineName -TcpPort $TcpPort -StartTime $StartTime) }'
					'catch { Write-Host ("ERROR: " + $_.Exception.Message) }'
					'if ($ok) { exit 0 } else { exit 1 }'
				) -join "`r`n")

			try
			{
				Set-Content -LiteralPath $launcherScriptPath -Value $launcherScript -Encoding UTF8 -Force -ErrorAction Stop
				$argList = @(
					'-NoProfile', '-ExecutionPolicy', 'Bypass',
					'-File', ('"{0}"' -f $launcherScriptPath),
					'-LaneNumber', $laneKey,
					'-MachineName', $MachineName,
					'-TcpPort', '1433',
					'-StartTime', '04:15'
				)
				$proc = Start-Process -FilePath 'powershell.exe' -ArgumentList $argList -WindowStyle Hidden -PassThru `
					-RedirectStandardOutput $launcherOutPath -ErrorAction Stop
			}
			catch
			{
				try { Remove-Item -LiteralPath $launcherScriptPath -Force -ErrorAction SilentlyContinue }
				catch { }
				$script:LaneSqlProtocolEnableTaskState[$laneKey] = [pscustomobject]@{ TaskPresent = $false; LastChecked = Get-Date; ScheduledFor = $scheduledDate; MachineName = $MachineName; LastResult = 'LaunchFailed' }
				return
			}

			$script:LaneSqlProtocolEnableJobs[$laneKey] = [pscustomobject]@{
				Process      = $proc
				ScriptPath   = $launcherScriptPath
				OutputPath   = $launcherOutPath
				Started      = Get-Date
				MachineName  = $MachineName
				ScheduledFor = $scheduledDate
			}
		}

		# Collect finished helper processes; log only when a lane's result changes
		HarvestSqlEnable = {
			if (-not $script:LaneSqlProtocolEnableJobs -or $script:LaneSqlProtocolEnableJobs.Count -eq 0) { return }
			foreach ($laneKey in @($script:LaneSqlProtocolEnableJobs.Keys))
			{
				$st = $script:LaneSqlProtocolEnableJobs[$laneKey]
				if (-not $st) { continue }
				$proc = $st.Process
				if ($proc)
				{
					try { if (-not $proc.HasExited) { continue } }
					catch { continue }
				}

				$success = $false
				try { $success = ($proc -and $proc.ExitCode -eq 0) }
				catch { $success = $false }
				$reason = ''
				try
				{
					if ($st.OutputPath -and (Test-Path -LiteralPath $st.OutputPath))
					{
						$reason = [string](@(Get-Content -LiteralPath $st.OutputPath -ErrorAction Stop | Where-Object { $_.Trim() }) | Select-Object -Last 1)
					}
				}
				catch { }
				foreach ($tmp in @($st.ScriptPath, $st.OutputPath))
				{
					try { if ($tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } }
					catch { }
				}
				[void]$script:LaneSqlProtocolEnableJobs.Remove($laneKey)

				$result = if ($success) { 'Scheduled' } else { 'Failed' }
				$previous = $script:LaneSqlProtocolEnableTaskState[$laneKey]
				$changedResult = (-not $previous) -or ([string]$previous.LastResult -ne $result)
				$script:LaneSqlProtocolEnableTaskState[$laneKey] = [pscustomobject]@{
					TaskPresent  = $success
					LastChecked  = Get-Date
					ScheduledFor = $st.ScheduledFor
					MachineName  = [string]$st.MachineName
					LastResult   = $result
				}

				if ($changedResult)
				{
					try
					{
						if ($success)
						{
							Write_Log ("Lane {0} ({1}) is on the SQL File protocol - SQL protocol enable scheduled for {2:MM/dd/yyyy HH:mm}." -f $laneKey, $st.MachineName, $st.ScheduledFor) 'green'
						}
						else
						{
							$why = if ($reason) { $reason } else { 'no details' }
							Write_Log ("Lane {0} ({1}) is on the SQL File protocol - could not schedule the SQL protocol enable: {2}" -f $laneKey, $st.MachineName, $why) 'red'
						}
					}
					catch { }
				}
			}
		}
	}

	# ---------- warm from file (best effort) ----------
	try
	{
		foreach ($line in @(Get-Content -LiteralPath $script:ProtocolResultsFile -ErrorAction SilentlyContinue))
		{
			if ($line -match '^\s*([^,]+),\s*([^,]+)\s*$')
			{
				$laneRaw = $matches[1].Trim()
				$laneNum = ($laneRaw -replace '[^\d]', '').PadLeft(3, '0')
				$null = & $script:LaneProtocolHelpers.SetProtocol $laneNum $laneRaw $matches[2].Trim()
			}
		}
	}
	catch { }

	if (-not $script:LaneProtocolPool) { $script:LaneProtocolPool = & $script:LaneProtocolHelpers.NewPool }

	# Probe worker (runs in the pool; source: src\Resources\Workers\Lane_Protocol_Probe.ps1)
	$script:LaneProtocolWorker = @'
# ---------------------------------------------------------------------------------------------------
# Lane SQL protocol probe - runspace worker for Start_Lane_Protocol_Jobs.
#   Embedded at build time into $script:LaneProtocolWorker; runs in the lane-protocol runspace pool
#   (no access to the main script's variables or functions).
#   Ping (700 ms) -> Offline when unreachable; then SQL login over tcp: -> 'TCP', over np: ->
#   'Named Pipes', else 'File' (the lane only works through the SQI file drop).
# ---------------------------------------------------------------------------------------------------
param([string]$machine, [string]$lane)

Add-Type -AssemblyName System.Data 2>$null
Add-Type -AssemblyName System 2>$null

$protocol = 'File'
$reachable = $true

if (-not [string]::IsNullOrWhiteSpace($machine))
{
	$machineNorm = [string]$machine
	$isLocalMachine = $false
	try
	{
		if ($machineNorm -match '^(?i)(localhost|\.|\(local\))$' -or $machineNorm -ieq $env:COMPUTERNAME) { $isLocalMachine = $true }
	}
	catch { }

	if (-not $isLocalMachine)
	{
		$reachable = $false
		try
		{
			$ping = New-Object System.Net.NetworkInformation.Ping
			$reply = $ping.Send($machineNorm, 700)
			if ($reply -and $reply.Status -eq [System.Net.NetworkInformation.IPStatus]::Success) { $reachable = $true }
		}
		catch { }
	}
}

if (-not $reachable)
{
	[PSCustomObject]@{ Lane = $lane; Protocol = 'Offline' }
	return
}

foreach ($probe in @(@{ Prefix = 'tcp'; Name = 'TCP' }, @{ Prefix = 'np'; Name = 'Named Pipes' }))
{
	$cn = $null
	try
	{
		$cs = "Data Source=$($probe.Prefix):$machine;Initial Catalog=master;Integrated Security=True;Connect Timeout=1"
		$cn = New-Object System.Data.SqlClient.SqlConnection $cs
		$cn.Open()
		$protocol = $probe.Name
	}
	catch { }
	finally
	{
		try { if ($cn) { $cn.Close() } } catch { }
		try { if ($cn) { $cn.Dispose() } } catch { }
	}
	if ($protocol -ne 'File') { break }
}

[PSCustomObject]@{ Lane = $lane; Protocol = $protocol }
'@

	if (-not $script:LaneProtocolLastRun) { $script:LaneProtocolLastRun = (Get-Date).AddYears(-10) }

	# ---------- timer (UI thread) ----------
	$script:protocolTimer = New-Object System.Windows.Forms.Timer
	$script:protocolTimer.Interval = 1000
	$script:protocolTimer.add_Tick({
			if ($script:LaneProtocolStop) { return }
			$h = $script:LaneProtocolHelpers

			# 0) finished SQL-enable helper processes
			try { & $h.HarvestSqlEnable }
			catch { }

			# 1) finished / hung probes
			$changed = $false
			$stale = $false
			foreach ($laneKey in @($script:LaneProtocolJobs.Keys))
			{
				$st = $script:LaneProtocolJobs[$laneKey]
				if (-not $st) { continue }

				$started = & $h.ToDate $st.Started
				$timedOut = ($null -ne $st.Started)   # an unreadable start time counts as hung
				if ($started)
				{
					try { $timedOut = (((Get-Date) - $started).TotalSeconds -ge $script:LaneProtocolJobTimeoutSeconds) }
					catch { $timedOut = $true }
				}

				if ($timedOut)
				{
					# A probe that hangs this long means the lane is unusable right now
					$laneNum = ($laneKey -replace '[^\d]', '').PadLeft(3, '0')
					$null = & $h.SetProtocol $laneNum $laneKey 'Offline'
					$changed = $true
					$stale = $true
					continue
				}

				if ($st.Handle -and $st.Handle.IsCompleted)
				{
					$resultList = $null
					try { $resultList = $st.PS.EndInvoke($st.Handle) }
					catch { $resultList = $null }
					try { if ($st.PS) { $st.PS.Dispose() } }
					catch { }
					[void]$script:LaneProtocolJobs.Remove($laneKey)

					$result = $null
					if ($resultList -and $resultList.Count -ge 1) { $result = $resultList[0] }
					if (-not $result) { $result = [pscustomobject]@{ Lane = $laneKey; Protocol = 'Offline' } }

					$rawLane = [string]$result.Lane
					$laneNum = ($rawLane -replace '[^\d]', '').PadLeft(3, '0')
					$proto = [string]$result.Protocol
					if ([string]::IsNullOrWhiteSpace($proto)) { $proto = 'File' }

					$mn = & $h.SetProtocol $laneNum $rawLane $proto
					if ($proto -eq 'File' -and -not [string]::IsNullOrWhiteSpace($mn))
					{
						try { & $h.StartSqlEnable $laneNum ([string]$mn) }
						catch { }
					}
					elseif ($script:LaneSqlProtocolEnableTaskState.ContainsKey($laneNum))
					{
						# The lane answers on TCP / Named Pipes now - nothing to schedule any more
						[void]$script:LaneSqlProtocolEnableTaskState.Remove($laneNum)
					}
					$changed = $true
				}
			}

			# 1b) a hung probe: drop every in-flight probe and rebuild the pool so it cannot wedge the loop
			if ($stale)
			{
				foreach ($st in @($script:LaneProtocolJobs.Values))
				{
					try { if ($st -and $st.PS) { $st.PS.Dispose() } }
					catch { }
				}
				$script:LaneProtocolJobs = @{ }
				try
				{
					if ($script:LaneProtocolPool)
					{
						$script:LaneProtocolPool.Close()
						$script:LaneProtocolPool.Dispose()
					}
				}
				catch { }
				$script:LaneProtocolPool = & $h.NewPool
				$script:LaneProtocolLastRun = Get-Date
			}

			# 2) persist when something changed
			if ($changed)
			{
				try
				{
					$lines = foreach ($r in ($script:ProtocolResults | Sort-Object { ($_.Lane -replace '[^\d]', '') -as [int] })) { '{0},{1}' -f $r.Lane, $r.Protocol }
					[System.IO.File]::WriteAllLines($script:ProtocolResultsFile, [string[]]@($lines), [System.Text.Encoding]::UTF8)
				}
				catch { }
			}

			# 3) new scan every 60 s, only when no probe is in flight
			if ($script:LaneProtocolJobs.Count -gt 0) { return }
			$lastRun = & $h.ToDate $script:LaneProtocolLastRun
			if ($lastRun -and ((Get-Date) - $lastRun).TotalSeconds -lt 60) { return }
			$script:LaneProtocolLastRun = Get-Date

			$laneMap = $script:LaneProtocolLaneMap
			if (-not $laneMap) { return }
			foreach ($k in @($laneMap.Keys))
			{
				$numStr = ([string]$k -replace '[^\d]', '')
				if (-not $numStr) { continue }
				$machine = $laneMap[$k]
				if ([string]::IsNullOrWhiteSpace($machine)) { continue }
				$laneNum = $numStr.PadLeft(3, '0')

				$ps = [System.Management.Automation.PowerShell]::Create()
				$ps.RunspacePool = $script:LaneProtocolPool
				$null = $ps.AddScript($script:LaneProtocolWorker).AddArgument([string]$machine).AddArgument([string]$laneNum)
				$script:LaneProtocolJobs[$laneNum] = @{ PS = $ps; Handle = $ps.BeginInvoke(); Started = Get-Date }
			}
		})

	$script:protocolTimer.Start()
}

# ===================================================================================================
#                              FUNCTION: Clear_XE_Folder
# ---------------------------------------------------------------------------------------------------
# Description:
#   Keeps the lane XE (urgent messages) folder clean. At startup it deletes everything except
#   valid S*.??? health files (also clearing old FATAL* errors), then starts a background
#   watcher job that keeps newly arriving FATAL* files and deletes everything else except
#   current health files on a regular sweep.
#
# Parameters:
#   - FolderPath           [string]: XE folder (default <OfficePath>\XE<Store>901)
#   - SweepIntervalSeconds [int]: periodic sweep interval in seconds, 2-3600 (default 30)
#   - HealthMaxAgeDays     [int]: max age in days of health files kept, 1-3650 (default 30)
#
# Returns:
#   The watcher job when started; $null if the folder is missing or the job fails.
#
# Writes:
#   - Deletes files under the XE folder (everything except valid health files)
# ===================================================================================================

function Clear_XE_Folder
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $false)]
		[string]$FolderPath = "$OfficePath\XE${StoreNumber}901",
		[Parameter(Mandatory = $false)]
		[ValidateRange(2, 3600)]
		[int]$SweepIntervalSeconds = 30,
		[Parameter(Mandatory = $false)]
		[ValidateRange(1, 3650)]
		[int]$HealthMaxAgeDays = 30
	)

	# ------------------------------------------------------------------------------------------------
	# 0) Validate folder exists
	# ------------------------------------------------------------------------------------------------
	if (-not (Test-Path -LiteralPath $FolderPath))
	{
		Write_Log "Folder '$FolderPath' (Urgent Messages) does not exist." "red"
		return $null
	}

	# ------------------------------------------------------------------------------------------------
	# 1) STARTUP CLEANUP
	#    - Deletes EVERYTHING except valid S*.??? health files (FATAL* old errors too)
	# ------------------------------------------------------------------------------------------------
	# A file worth keeping: a current lane health report ("This application is not running")
	# for this store, S*.<lane> named after the lane in its From: line, newer than HealthMaxAgeDays.
	# Shared by the startup cleanup and the watcher job (passed to it as text).
	$isHealthFile = {
		param ($Item, [string]$StoreNumber, [int]$HealthMaxAgeDays)
		if ($Item.PSIsContainer -or $Item.Name -notmatch '^S.*\.\w{3}$') { return $false }
		if (((Get-Date) - $Item.LastWriteTime).TotalDays -gt $HealthMaxAgeDays) { return $false }
		$content = $null
		try { $content = Get-Content -LiteralPath $Item.FullName -ErrorAction Stop }
		catch { return $false }
		if (-not $content) { return $false }
		$fromLine = $content | Where-Object { $_ -like 'From:*' } | Select-Object -First 1
		$subjectLine = $content | Where-Object { $_ -like 'Subject:*' } | Select-Object -First 1
		$msgLine = $content | Where-Object { $_ -like 'MSG:*' } | Select-Object -First 1
		$lastStatusLine = $content | Where-Object { $_ -like 'Last recorded status:*' } | Select-Object -First 1
		if ($fromLine -notmatch 'From:\s*(\d{3})(\d{3})') { return $false }
		$fileStoreNumber = $Matches[1]
		$fileLaneNumber = $Matches[2]
		return ($fileStoreNumber -eq $StoreNumber -and
			$Item.Name -match '^S.*\.(\d{3})$' -and $fileLaneNumber -eq $Matches[1] -and
			$subjectLine -match 'Subject:\s*Health' -and
			$msgLine -match 'MSG:\s*This application is not running\.' -and
			$lastStatusLine -match 'Last recorded status:\s*[\d\s:,-]+TRANS,(\d+)')
	}

	try
	{
		$items = Get-ChildItem -LiteralPath $FolderPath -Recurse -Force -ErrorAction SilentlyContinue |
		Where-Object { ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0 }

		foreach ($item in $items)
		{
			# Startup mode: FATAL* (old errors) and folders go too
			$keep = ($item.Name -notlike 'FATAL*') -and (& $isHealthFile $item $StoreNumber $HealthMaxAgeDays)
			if ($keep) { continue }
			for ($i = 0; $i -lt 8; $i++)
			{
				try
				{
					if (Test-Path -LiteralPath $item.FullName) { Remove-Item -LiteralPath $item.FullName -Force -Recurse -ErrorAction Stop }
					break
				}
				catch { Start-Sleep -Milliseconds 150 }
			}
		}
	}
	catch
	{
		Write_Log "An error occurred during startup cleaning of '$FolderPath': $_" "red"
	}
	# ------------------------------------------------------------------------------------------------
	# 2) MONITOR (FileSystemWatcher in a background job)
	#    - Keeps NEW FATAL* while running
	#    - Deletes everything else except valid health files
	# ------------------------------------------------------------------------------------------------
	try
	{
		$jobName = "XEWatcherJob_$StoreNumber"

		# Replace any existing watcher job
		$existing = Get-Job | Where-Object { $_.Name -eq $jobName } # -Name on a missing job records an error
		if ($existing)
		{
			try { Stop-Job -Job $existing -Force -ErrorAction SilentlyContinue | Out-Null }
			catch { }
			try { Remove-Job -Job $existing -Force -ErrorAction SilentlyContinue | Out-Null }
			catch { }
		}

		$job = Start-Job -Name $jobName -ArgumentList $FolderPath, $StoreNumber, $HealthMaxAgeDays, $SweepIntervalSeconds, $isHealthFile.ToString() -ScriptBlock {
			param (
				[string]$FolderPath,
				[string]$StoreNumber,
				[int]$HealthMaxAgeDays,
				[int]$SweepIntervalSeconds,
				[string]$IsHealthFileText
			)
			$IsHealthFile = [scriptblock]::Create($IsHealthFileText)

			$ErrorActionPreference = 'SilentlyContinue'

			# --- Watcher object ---
			$fsw = New-Object System.IO.FileSystemWatcher
			$fsw.Path = $FolderPath
			$fsw.IncludeSubdirectories = $true
			$fsw.NotifyFilter = [IO.NotifyFilters]'FileName, DirectoryName, LastWrite, CreationTime'

			# --- Shared processor (MONITOR MODE: keep FATAL*) ---
			$ProcessPath = {
				param ([string]$Path)

				if (-not $Path) { return }

				# Retry Get-Item because events can fire before writer finishes.
				$item = $null
				for ($t = 0; $t -lt 8; $t++)
				{
					try
					{
						if (-not (Test-Path -LiteralPath $Path)) { return }
						$item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
						break
					}
					catch { Start-Sleep -Milliseconds 120 }
				}
				if (-not $item) { return }

				# Keep NEW FATAL* while running
				if ($item.Name -like 'FATAL*') { return }

				# Skip reparse points
				if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { return }

				$keep = & $IsHealthFile $item $StoreNumber $HealthMaxAgeDays

				if (-not $keep)
				{
					for ($i = 0; $i -lt 8; $i++)
					{
						try
						{
							if (Test-Path -LiteralPath $item.FullName)
							{
								Remove-Item -LiteralPath $item.FullName -Force -Recurse -ErrorAction Stop
							}
							break
						}
						catch { Start-Sleep -Milliseconds 150 }
					}
				}
			}

			# Register events (no -Action) and consume them with Wait-Event (best in jobs)
			$createdId = "XE_Created_$StoreNumber"
			$changedId = "XE_Changed_$StoreNumber"
			$renamedId = "XE_Renamed_$StoreNumber"

			Register-ObjectEvent -InputObject $fsw -EventName Created -SourceIdentifier $createdId | Out-Null
			Register-ObjectEvent -InputObject $fsw -EventName Changed -SourceIdentifier $changedId | Out-Null
			Register-ObjectEvent -InputObject $fsw -EventName Renamed -SourceIdentifier $renamedId | Out-Null

			$fsw.EnableRaisingEvents = $true
			$nextSweep = (Get-Date).AddSeconds($SweepIntervalSeconds)

			while ($true)
			{
				# Wait briefly for an event
				$e = Wait-Event -Timeout 1

				if ($e)
				{
					try
					{
						$path = $e.SourceEventArgs.FullPath
						& $ProcessPath -Path $path
					}
					catch { }
					finally
					{
						# Always remove handled event from queue
						try { Remove-Event -EventIdentifier $e.EventIdentifier -ErrorAction SilentlyContinue }
						catch { }
					}

					# Drain burst
					while ($true)
					{
						$e2 = Wait-Event -Timeout 0
						if (-not $e2) { break }
						try
						{
							$path2 = $e2.SourceEventArgs.FullPath
							& $ProcessPath -Path $path2
						}
						catch { }
						finally
						{
							try { Remove-Event -EventIdentifier $e2.EventIdentifier -ErrorAction SilentlyContinue }
							catch { }
						}
					}
				}

				# Periodic sweep fallback
				if ((Get-Date) -ge $nextSweep)
				{
					$nextSweep = (Get-Date).AddSeconds($SweepIntervalSeconds)

					try
					{
						if (Test-Path -LiteralPath $FolderPath)
						{
							Get-ChildItem -LiteralPath $FolderPath -Recurse -Force -ErrorAction SilentlyContinue |
							Where-Object { ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0 } |
							ForEach-Object { & $ProcessPath -Path $_.FullName }
						}
					}
					catch { }
				}
			}
		}

		return $job
	}
	catch
	{
		Write_Log "Failed to start XE watcher job: $_" "red"
		return $null
	}
}

# ===================================================================================================
#                              FUNCTION: Export_VNC_Files_For_All_Nodes
# ---------------------------------------------------------------------------------------------------
# Description:
#   Generates UltraVNC (.vnc) connection files for every lane, scale, and backoffice discovered
#   in the store, saved under Desktop\Lanes, Desktop\Scales, Desktop\Backoffices. Default VNC
#   password is 4330df922eb03b6e (UltraVNC encrypted form) unless a per-machine password is
#   available; Ishida scales also get an Ishida_Wrapper_#.vnc. Scales with missing IP info are
#   skipped and logged.
#
# Parameters:
#   - LaneNumToMachineName       [hashtable] (required): LaneNumber => MachineName
#   - ScaleCodeToIPInfo          [hashtable] (required): ScaleCode => scale object (with IP)
#   - BackofficeNumToMachineName [hashtable] (required): BackofficeTerminal => MachineName
#   - AllVNCPasswords            [hashtable]: MachineName => VNC password
#   - RunInBackground            [switch]: run as a background job
#   - SilentBackground           [switch]: suppress log window output
#   - InternalBackgroundJob      [switch]: internal flag - already inside a background job
# ===================================================================================================

function Export_VNC_Files_For_All_Nodes
{
	param (
		[Parameter(Mandatory = $true)]
		[hashtable]$LaneNumToMachineName,
		[Parameter(Mandatory = $true)]
		[hashtable]$ScaleCodeToIPInfo,
		[Parameter(Mandatory = $true)]
		[hashtable]$BackofficeNumToMachineName,
		[Parameter(Mandatory = $false)]
		[hashtable]$AllVNCPasswords,
		[Parameter(Mandatory = $false)]
		[switch]$RunInBackground,
		[Parameter(Mandatory = $false)]
		[switch]$SilentBackground,
		[Parameter(Mandatory = $false)]
		[switch]$InternalBackgroundJob
	)

	$log = {
		param (
			[string]$Message,
			[string]$Color = "Black"
		)

		if (-not $SilentBackground)
		{
			Write_Log $Message $Color
		}
	}

	$validLaneMap = @{ }
	if ($LaneNumToMachineName)
	{
		foreach ($kv in $LaneNumToMachineName.GetEnumerator())
		{
			$machineName = [string]$kv.Value
			if (-not [string]::IsNullOrWhiteSpace($machineName))
			{
				$validLaneMap[[string]$kv.Key] = $machineName.Trim()
			}
		}
	}

	$validScaleMap = @{ }
	if ($ScaleCodeToIPInfo)
	{
		foreach ($kv in $ScaleCodeToIPInfo.GetEnumerator())
		{
			$scaleObj = $kv.Value
			$ip = $null
			if ($null -ne $scaleObj)
			{
				if (($scaleObj.PSObject.Properties.Name -contains 'FullIP') -and -not [string]::IsNullOrWhiteSpace([string]$scaleObj.FullIP))
				{
					$ip = [string]$scaleObj.FullIP
				}
				elseif (
					($scaleObj.PSObject.Properties.Name -contains 'IPNetwork') -and
					($scaleObj.PSObject.Properties.Name -contains 'IPDevice') -and
					-not [string]::IsNullOrWhiteSpace([string]$scaleObj.IPNetwork) -and
					-not [string]::IsNullOrWhiteSpace([string]$scaleObj.IPDevice)
				)
				{
					$ip = "$($scaleObj.IPNetwork)$($scaleObj.IPDevice)"
				}
			}

			if (-not [string]::IsNullOrWhiteSpace($ip))
			{
				$validScaleMap[[string]$kv.Key] = $scaleObj
			}
		}
	}

	$validBackofficeMap = @{ }
	if ($BackofficeNumToMachineName)
	{
		foreach ($kv in $BackofficeNumToMachineName.GetEnumerator())
		{
			$machineName = [string]$kv.Value
			if (-not [string]::IsNullOrWhiteSpace($machineName))
			{
				$validBackofficeMap[[string]$kv.Key] = $machineName.Trim()
			}
		}
	}

	$LaneNumToMachineName = $validLaneMap
	$ScaleCodeToIPInfo = $validScaleMap
	$BackofficeNumToMachineName = $validBackofficeMap

	if ($RunInBackground -and -not $InternalBackgroundJob)
	{
		$hasAnyNodes = (
			($LaneNumToMachineName -and $LaneNumToMachineName.Count -gt 0) -or
			($ScaleCodeToIPInfo -and $ScaleCodeToIPInfo.Count -gt 0) -or
			($BackofficeNumToMachineName -and $BackofficeNumToMachineName.Count -gt 0)
		)

		if (-not $hasAnyNodes) { return }

		if (
			$script:VncExportTask -and
			$script:VncExportTask.Job -and
			$script:VncExportTask.Job.State -in @('Running', 'NotStarted')
		)
		{
			return
		}

		try
		{
			$writeLogDefinition = 'param([string]$Message, $Color, [switch]$IncludeTimestamp)'
			$getAllVncPasswordsDefinition = ${function:Get_All_VNC_Passwords}.ToString()
			$exportVncDefinition = ${function:Export_VNC_Files_For_All_Nodes}.ToString()
			# Get_All_VNC_Passwords probes the nodes with Test-Hosts_Parallel - the job needs it too
			# (missing before v2.7.0: the background export failed whenever it had to look up passwords)
			$testHostsDefinition = ${function:Test-Hosts_Parallel}.ToString()

			$job = Start-Job -Name 'VNCExportJob' -ScriptBlock {
				param (
					[string]$WriteLogDefinition,
					[string]$GetAllVncPasswordsDefinition,
					[string]$ExportVncDefinition,
					[string]$TestHostsDefinition,
					[hashtable]$LaneMap,
					[hashtable]$ScaleMap,
					[hashtable]$BackofficeMap,
					[hashtable]$AllVncPasswords,
					[string]$UltraVncFolder,
					[int]$AnsiCodePage
				)

				Add-Type -AssemblyName System.Windows.Forms 2>$null
				Add-Type -AssemblyName System.Drawing 2>$null

				Set-Item -Path function:Write_Log -Value ([scriptblock]::Create($WriteLogDefinition))
				Set-Item -Path function:Get_All_VNC_Passwords -Value ([scriptblock]::Create($GetAllVncPasswordsDefinition))
				Set-Item -Path function:Export_VNC_Files_For_All_Nodes -Value ([scriptblock]::Create($ExportVncDefinition))
				Set-Item -Path function:Test-Hosts_Parallel -Value ([scriptblock]::Create($TestHostsDefinition))

				$script:UltraVncFolder = $UltraVncFolder
				$script:ansiPcEncoding = [System.Text.Encoding]::GetEncoding($AnsiCodePage)
				$script:FunctionResults = @{ }

				try
				{
					Export_VNC_Files_For_All_Nodes `
												   -LaneNumToMachineName $LaneMap `
												   -ScaleCodeToIPInfo $ScaleMap `
												   -BackofficeNumToMachineName $BackofficeMap `
												   -AllVNCPasswords $AllVncPasswords `
												   -SilentBackground `
												   -InternalBackgroundJob

					$passwordCache = $null
					if ($script:FunctionResults.ContainsKey('AllVNCPasswords'))
					{
						$passwordCache = $script:FunctionResults['AllVNCPasswords']
					}

					[pscustomobject]@{
						Success		    = $true
						AllVNCPasswords = $passwordCache
						Error		    = $null
					}
				}
				catch
				{
					[pscustomobject]@{
						Success		    = $false
						AllVNCPasswords = $null
						Error		    = $_.Exception.Message
					}
				}
			} -ArgumentList @(
				$writeLogDefinition,
				$getAllVncPasswordsDefinition,
				$exportVncDefinition,
				$testHostsDefinition,
				$LaneNumToMachineName,
				$ScaleCodeToIPInfo,
				$BackofficeNumToMachineName,
				$AllVNCPasswords,
				$script:UltraVncFolder,
				1252
			)

			$script:VncExportTask = @{
				Job	    = $job
				Started = Get-Date
			}

			if (-not $script:VncExportReaper)
			{
				$script:VncExportReaper = New-Object System.Windows.Forms.Timer
				$script:VncExportReaper.Interval = 1000
				$script:VncExportReaper.Add_Tick({
						if (-not $script:VncExportTask)
						{
							try
							{
								if ($script:VncExportReaper)
								{
									$script:VncExportReaper.Stop()
									$script:VncExportReaper.Dispose()
									$script:VncExportReaper = $null
								}
							}
							catch { }
							return
						}

						$taskState = $script:VncExportTask
						if (-not $taskState.Job -or $taskState.Job.State -in @('Running', 'NotStarted')) { return }

						$result = $null
						try { $result = Receive-Job -Job $taskState.Job -ErrorAction SilentlyContinue }
						catch { }
						try { Remove-Job -Job $taskState.Job -Force -ErrorAction SilentlyContinue | Out-Null }
						catch { }

						$resultObj = $null
						if ($result)
						{
							$resultObj = @($result) | Select-Object -Last 1
						}

						if (
							$resultObj -and
							$resultObj.Success -and
							$resultObj.AllVNCPasswords -and
							($resultObj.AllVNCPasswords -is [hashtable]) -and
							$resultObj.AllVNCPasswords.Count -gt 0
						)
						{
							$script:FunctionResults['AllVNCPasswords'] = $resultObj.AllVNCPasswords
						}

						$script:VncExportTask = $null

						try
						{
							if ($script:VncExportReaper)
							{
								$script:VncExportReaper.Stop()
								$script:VncExportReaper.Dispose()
								$script:VncExportReaper = $null
							}
						}
						catch { }
					})
			}

			$script:VncExportReaper.Start()
		}
		catch
		{
			try { if ($job) { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue | Out-Null } }
			catch { }
			$script:VncExportTask = $null
		}

		return
	}

	& $log "`r`n==================== Starting Export_VNCFiles_ForAllNodes ====================`r`n" "blue"
	$DefaultVNCPassword = "4330df922eb03b6e"
	$desktop = [Environment]::GetFolderPath("Desktop")
	$lanesDir = Join-Path $desktop "Lanes"
	$scalesDir = Join-Path $desktop "Scales"
	$backofficesDir = Join-Path $desktop "BackOffices"
	$hasLaneNodes = ($LaneNumToMachineName -and $LaneNumToMachineName.Count -gt 0)
	$hasScaleNodes = ($ScaleCodeToIPInfo -and $ScaleCodeToIPInfo.Count -gt 0)
	$hasBackofficeNodes = ($BackofficeNumToMachineName -and $BackofficeNumToMachineName.Count -gt 0)

	if (-not ($hasLaneNodes -or $hasScaleNodes -or $hasBackofficeNodes))
	{
		& $log "No lanes, scales, or backoffices were found. Nothing to export." "yellow"
		& $log "`r`n==================== Export_VNCFiles_ForAllNodes Completed ====================" "blue"
		return
	}

	# ---- If passwords not provided, scan them ----
	if (-not $AllVNCPasswords -or $AllVNCPasswords.Count -eq 0)
	{
		& $log "Gathering VNC passwords for all machines`r`n" "magenta"
		$AllVNCPasswords = Get_All_VNC_Passwords -LaneNumToMachineName $LaneNumToMachineName -ScaleCodeToIPInfo $ScaleCodeToIPInfo -BackofficeNumToMachineName $BackofficeNumToMachineName
	}

	# --- Shared VNC file content with token ---
	$vncTemplate = @"
[connection]
host=%%HOST%%
port=5900
proxyhost=
proxyport=0
password=%%PASSWORD%%
[options]
use_encoding_0=1
use_encoding_1=1
use_encoding_2=1
use_encoding_3=0
use_encoding_4=1
use_encoding_5=1
use_encoding_6=1
use_encoding_7=1
use_encoding_8=1
use_encoding_9=1
use_encoding_10=1
use_encoding_11=0
use_encoding_12=0
use_encoding_13=0
use_encoding_14=0
use_encoding_15=0
use_encoding_16=1
use_encoding_17=1
use_encoding_18=1
use_encoding_19=1
use_encoding_20=0
use_encoding_21=0
use_encoding_22=0
use_encoding_23=0
use_encoding_24=0
use_encoding_25=1
use_encoding_26=1
use_encoding_27=1
use_encoding_28=0
use_encoding_29=1
preferred_encoding=10
restricted=0
AllowUntrustedServers=0
viewonly=0
nostatus=0
nohotkeys=0
showtoolbar=1
fullscreen=0
SavePos=0
SaveSize=0
GNOME=0
directx=0
autoDetect=0
8bit=0
shared=1
swapmouse=0
belldeiconify=0
BlockSameMouse=0
emulate3=1
JapKeyboard=0
emulate3timeout=100
emulate3fuzz=4
disableclipboard=0
localcursor=1
Scaling=0
AutoScaling=1
AutoScalingEven=0
AutoScalingLimit=0
scale_num=1
scale_den=1
cursorshape=1
noremotecursor=0
compresslevel=6
quality=8
ServerScale=1
Reconnect=3
EnableCache=0
EnableZstd=1
QuickOption=1
UseDSMPlugin=0
UseProxy=0
sponsor=0
allowMonitorSpanning=0
ChangeServerRes=0
extendDisplay=0
showExtend=0
use_virt=0
useAllMonitors=0
requestedWidth=0
requestedHeight=0
DSMPlugin=NoPlugin
folder=$script:UltraVncFolder
prefix=vnc_
imageFormat=.jpeg
InfoMsg=
AutoReconnect=3
ExitCheck=0
FileTransferTimeout=30
ListenPort=5500
KeepAliveInterval=5
ThrottleMouse=0
AutoAcceptIncoming=0
AutoAcceptNoDSM=0
RequireEncryption=0
PreemptiveUpdates=0
"@

	$resolveVncPassword = {
		param (
			[string]$LookupKey
		)

		if (
			$AllVNCPasswords -and
			-not [string]::IsNullOrWhiteSpace($LookupKey) -and
			$AllVNCPasswords.ContainsKey($LookupKey) -and
			-not [string]::IsNullOrWhiteSpace([string]$AllVNCPasswords[$LookupKey])
		)
		{
			return [string]$AllVNCPasswords[$LookupKey]
		}

		return $DefaultVNCPassword
	}

	$writeExports = {
		param (
			[System.Collections.ArrayList]$Exports,
			[string]$TargetDir,
			[string]$CategoryLabel
		)

		if (-not $Exports -or $Exports.Count -eq 0)
		{
			& $log "No $CategoryLabel VNC files to export. Skipping folder creation.`r`n" "gray"
			return 0
		}

		[void][System.IO.Directory]::CreateDirectory($TargetDir)

		foreach ($item in $Exports)
		{
			$content = $vncTemplate.Replace('%%HOST%%', $item.Host).Replace('%%PASSWORD%%', $item.Password)
			if ($item.AllowUntrustedServers)
			{
				$content = $content -replace 'AllowUntrustedServers=0', 'AllowUntrustedServers=1'
			}

			[System.IO.File]::WriteAllText($item.FilePath, $content, $script:ansiPcEncoding)
			& $log "Created: $($item.FilePath)" "green"
		}

		& $log "$($Exports.Count) $CategoryLabel VNC files written to $TargetDir`r`n" "blue"
		return $Exports.Count
	}

	# ---- Lanes ---- #
	& $log "-------------------- Exporting Lane VNC Files --------------------" "blue"
	$laneExports = New-Object System.Collections.ArrayList
	$dedupedLanes = @{ }
	foreach ($kv in $LaneNumToMachineName.GetEnumerator())
	{
		$machineName = [string]$kv.Value
		if ([string]::IsNullOrWhiteSpace($machineName)) { continue }

		# Only write one file per machine name
		$machineKey = $machineName.Trim().ToLowerInvariant()
		if (-not $dedupedLanes.ContainsKey($machineKey))
		{
			$dedupedLanes[$machineKey] = $true
			if ($machineName.ToUpper() -match '^(POS|SCO)\d+$')
			{
				$fileName = "$($machineName.ToUpper()).vnc"
			}
			else
			{
				$fileName = "Lane_$($kv.Key).vnc"
			}

			[void]$laneExports.Add([pscustomobject]@{
					FilePath = [System.IO.Path]::Combine($lanesDir, $fileName)
					Host	 = $machineName
					Password = (& $resolveVncPassword $machineName)
					AllowUntrustedServers = $false
				})
		}
	}
	$laneCount = & $writeExports $laneExports $lanesDir 'lane'

	# ---- Scales ---- #
	& $log "-------------------- Exporting Scale VNC Files --------------------" "blue"
	$scaleExports = New-Object System.Collections.ArrayList
	$dedupedScales = @{ }
	foreach ($kv in $ScaleCodeToIPInfo.GetEnumerator())
	{
		$scaleObj = $kv.Value
		# Make sure to dedupe by IP address
		$ip = if ($scaleObj.FullIP) { $scaleObj.FullIP }
		elseif ($scaleObj.IPNetwork -and $scaleObj.IPDevice) { "$($scaleObj.IPNetwork)$($scaleObj.IPDevice)" }
		else { $null }
		if ($ip)
		{
			$ipKey = $ip.Trim().ToLowerInvariant()
			if ($dedupedScales.ContainsKey($ipKey)) { continue }
			$dedupedScales[$ipKey] = $true

			$octets = $ip -split '\.'
			$lastOctet = $octets[-1]
			$brandRaw = ($scaleObj.ScaleBrand -as [string]).Trim()
			$model = ($scaleObj.ScaleModel -as [string]).Trim()
			$brand = if ($brandRaw)
			{
				($brandRaw -split ' ' | ForEach-Object {
						if ($_.Length -gt 0) { $_.Substring(0, 1).ToUpper() + $_.Substring(1).ToLower() }
						else { $_ }
					}) -join ' '
			}
			else { "" }
			if ($brand -and $model)
			{
				$fileName = "$brand($model)_${lastOctet}.vnc"
			}
			elseif ($brand)
			{
				$fileName = "$brand(Unknown)_${lastOctet}.vnc"
			}
			else
			{
				$fileName = "Scale_${lastOctet}.vnc"
			}

			[void]$scaleExports.Add([pscustomobject]@{
					FilePath = [System.IO.Path]::Combine($scalesDir, $fileName)
					Host	 = $ip
					Password = (& $resolveVncPassword $ip)
					AllowUntrustedServers = ($brand -like '*Ishida*')
				})
		}
	}
	$scaleCount = & $writeExports $scaleExports $scalesDir 'scale'

	# ---- Backoffices ---- #
	& $log "-------------------- Exporting Backoffice VNC Files --------------------" "blue"
	$boExports = New-Object System.Collections.ArrayList
	$dedupedBOs = @{ }
	foreach ($kv in $BackofficeNumToMachineName.GetEnumerator())
	{
		$boName = [string]$kv.Value
		$terminal = $kv.Key
		if ([string]::IsNullOrWhiteSpace($boName)) { continue }

		$boKey = $boName.Trim().ToLowerInvariant()
		if (-not $dedupedBOs.ContainsKey($boKey))
		{
			$dedupedBOs[$boKey] = $true
			$fileName = "Backoffice_${terminal}.vnc"

			[void]$boExports.Add([pscustomobject]@{
					FilePath = [System.IO.Path]::Combine($backofficesDir, $fileName)
					Host	 = $boName
					Password = (& $resolveVncPassword $boName)
					AllowUntrustedServers = $false
				})
		}
	}
	$boCount = & $writeExports $boExports $backofficesDir 'backoffice'

	& $log "VNC file export complete!" "green"
	& $log "`r`n==================== Export_VNCFiles_ForAllNodes Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Get_All_VNC_Passwords
# ---------------------------------------------------------------------------------------------------
# Description:
#   Scans all lanes, backoffices and scales for the UltraVNC configuration file (UltraVNC.ini,
#   any case) in the standard install locations, extracts the encrypted VNC password and
#   returns a machine-name -> password hashtable. Uses a fixed default password for nodes
#   where no UltraVNC.ini can be read.
#
# Parameters:
#   - LaneNumToMachineName       [hashtable]: lane number -> machine name
#   - ScaleCodeToIPInfo          [hashtable]: scale code -> scale info object
#   - BackofficeNumToMachineName [hashtable]: backoffice number -> machine name
#
# Variables:
#   - $script:DefaultVNCPassword: fixed default for stock-password nodes (e.g. Ishida)
#
# Returns:
#   Hashtable MachineName => encrypted password (or $null when not found).
#
# Writes:
#   - $script:FunctionResults['AllVNCPasswords']
# ===================================================================================================

function Get_All_VNC_Passwords
{
	param (
		[Parameter(Mandatory = $false)]
		[hashtable]$LaneNumToMachineName,
		[Parameter(Mandatory = $false)]
		[hashtable]$ScaleCodeToIPInfo,
		[Parameter(Mandatory = $false)]
		[hashtable]$BackofficeNumToMachineName
	)

	# Default VNC password for lanes, backoffices, and scales with fixed passwords (e.g., Ishida)
	$DefaultVNCPassword = "4330df922eb03b6e"
	$script:DefaultVNCPassword = $DefaultVNCPassword

	$uvncFolders = @(
		"C$\Program Files\uvnc bvba\UltraVNC",
		"C$\Program Files (x86)\uvnc bvba\UltraVNC"
	)
	$AllVNCPasswords = @{ }

	# 1. Build main node list and tag brands for scales
	$NodeList = @()
	$BizerbaScales = @()
	if ($LaneNumToMachineName) { $NodeList += $LaneNumToMachineName.Values | Where-Object { $_ } }
	if ($ScaleCodeToIPInfo)
	{
		$uniqueScaleObjs = @{ }
		foreach ($kv in $ScaleCodeToIPInfo.GetEnumerator())
		{
			$scaleObj = $kv.Value
			# Compute a unique identifier, e.g., IP or some combination
			$ip = $null
			if ($scaleObj.FullIP) { $ip = $scaleObj.FullIP }
			elseif ($scaleObj.IPNetwork -and $scaleObj.IPDevice) { $ip = "$($scaleObj.IPNetwork)$($scaleObj.IPDevice)" }
			# Add only once!
			if ($ip -and -not $uniqueScaleObjs.ContainsKey($ip))
			{
				$uniqueScaleObjs[$ip] = $scaleObj
			}
		}
		foreach ($ip in $uniqueScaleObjs.Keys)
		{
			$scaleObj = $uniqueScaleObjs[$ip]
			$ip = $null
			$isIshida = $false
			$isBizerba = $false
			if ($scaleObj -is [string]) { $ip = $scaleObj }
			elseif ($null -ne $scaleObj)
			{
				if (($scaleObj.PSObject.Properties.Name -contains "ScaleBrand") -and ($scaleObj.ScaleBrand -match "Ishida"))
				{
					$isIshida = $true
				}
				if (($scaleObj.PSObject.Properties.Name -contains "ScaleBrand") -and ($scaleObj.ScaleBrand -match "BIZERBA"))
				{
					$isBizerba = $true
				}
				if ($scaleObj.PSObject.Properties.Name -contains "FullIP" -and $scaleObj.FullIP)
				{
					$ip = $scaleObj.FullIP
				}
				elseif (($scaleObj.PSObject.Properties.Name -contains "IPNetwork") -and ($scaleObj.PSObject.Properties.Name -contains "IPDevice") -and $scaleObj.IPNetwork -and $scaleObj.IPDevice)
				{
					$ip = "$($scaleObj.IPNetwork)$($scaleObj.IPDevice)"
				}
			}
			if ($ip)
			{
				if ($isIshida)
				{
					Write_Log "Ishida scale [$ip] will use default VNC password.`r`n" "yellow"
					$AllVNCPasswords[$ip] = $DefaultVNCPassword
					continue
				}
				if ($isBizerba) { $BizerbaScales += @{ Host = $ip; Obj = $scaleObj }; continue }
				$NodeList += $ip
			}
		}
	}
	if ($BackofficeNumToMachineName) { $NodeList += $BackofficeNumToMachineName.Values | Where-Object { $_ } }
	$NodeList = $NodeList | Sort-Object -Unique

	if (($NodeList.Count -eq 0) -and ($BizerbaScales.Count -eq 0)) { throw "No machines provided for password extraction." }

	# 2. Ping regular nodes first (v2.6.9: parallel probe with a concurrency
	# cap - the old serial Test-Connection loop could block for minutes when
	# several nodes were down)
	$onlineProbe = @{}
	if ($NodeList.Count -gt 0) { $onlineProbe = Test-Hosts_Parallel -Targets $NodeList }
	$OnlineNodes = @()
	foreach ($node in $NodeList)
	{
		if ($onlineProbe[$node] -eq 'OK')
		{
			$OnlineNodes += $node
		}
		else
		{
			$AllVNCPasswords[$node] = $null
		}
	}

	# 3. Start jobs for online regular nodes
	$jobs = @()
	$MaxConcurrentJobs = 20 # Increased for faster processing

	foreach ($machineName in $OnlineNodes)
	{
		while ($jobs.Count -ge $MaxConcurrentJobs)
		{
			$done = Wait-Job -Job $jobs -Any -Timeout 10
			if ($done)
			{
				# Receive BEFORE removing: Remove-Job on a finished job discards
				# its output, which silently dropped these machines' VNC passwords.
				# -Any returns ONE job per wait, so only the reported jobs are
				# processed here; everything else stays in the pool for the
				# final Wait-Job/collect below (filtering by state here also
				# dropped jobs that finished between waits).
				$processedIds = @($done | ForEach-Object { $_.Id })
				foreach ($j in @($done))
				{
					$doneResult = Receive-Job $j
					if ($doneResult -and $doneResult.Machine) { $AllVNCPasswords[$doneResult.Machine] = $doneResult.Password }
					Remove-Job $j -Force
				}
				$jobs = @($jobs | Where-Object { $processedIds -notcontains $_.Id })
			}
		}
		$jobs += Start-Job -Name ("GetAllVNCPasswords_{0}" -f $machineName) -ArgumentList $machineName, $uvncFolders -ScriptBlock {
			param ($machineName,
				$uvncFolders)
			$password = $null
			foreach ($folder in $uvncFolders)
			{
				try
				{
					$iniFiles = Invoke-Command -ComputerName $machineName -TimeoutSec 30 -ScriptBlock {
						param ($dir)
						if (Test-Path $dir)
						{
							Get-ChildItem -Path $dir -Filter "*.ini" -File | ForEach-Object {
								if ($_.Name.ToLower() -eq "ultravnc.ini")
								{
									$_.FullName
								}
							}
						}
					} -ArgumentList ("C:\" + $folder.Substring(3)) -ErrorAction Stop
					foreach ($iniFile in $iniFiles)
					{
						$content = Invoke-Command -ComputerName $machineName -TimeoutSec 30 -ScriptBlock {
							param ($path)
							if (Test-Path $path)
							{
								Get-Content $path -ErrorAction Stop
							}
						} -ArgumentList $iniFile -ErrorAction Stop
						foreach ($line in $content)
						{
							if ($line -match '^\s*passwd\s*=\s*([0-9A-Fa-f]+)')
							{
								$password = $matches[1]
								break
							}
						}
						if ($password) { break }
					}
				}
				catch
				{
					try
					{
						$remotePath = "\\$machineName\$folder"
						if (Test-Path $remotePath -ErrorAction SilentlyContinue)
						{
							$iniFiles = Get-ChildItem -Path $remotePath -Filter "*.ini" -File -ErrorAction SilentlyContinue | Where-Object {
								$_.Name.ToLower() -eq "ultravnc.ini"
							}
							foreach ($iniFile in $iniFiles)
							{
								$content = Get-Content $iniFile.FullName -ErrorAction Stop
								foreach ($line in $content)
								{
									if ($line -match '^\s*passwd\s*=\s*([0-9A-Fa-f]+)')
									{
										$password = $matches[1]
										break
									}
								}
								if ($password) { break }
							}
						}
					}
					catch { continue }
				}
				if ($password) { break }
			}
			return @{ Machine = $machineName; Password = $password }
		}
	}

	# Only wait if there is anything to wait for: when the throttle loop above
	# has already drained all jobs, $jobs is empty/null and Wait-Job throws a
	# parameter validation error.
	if (@($jobs).Count -gt 0)
	{
		$null = Wait-Job -Job $jobs -Timeout 120
		foreach ($j in @($jobs))
		{
			if ($j.State -ne 'Completed') { Stop-Job -Job $j -ErrorAction SilentlyContinue }
		}
	}

	foreach ($j in $jobs)
	{
		$result = Receive-Job $j
		if ($result -and $result.Machine)
		{
			$AllVNCPasswords[$result.Machine] = $result.Password
		}
		Remove-Job $j -Force
	}

	# 4. Handle Bizerba scales (using cmdkey/bizuser logic, serially)
	foreach ($b in $BizerbaScales)
	{
		$scaleHost = $b.Host
		$uvncIniRelativePaths = @(
			"Program Files\uvnc bvba\UltraVNC\ultravnc.ini",
			"Program Files (x86)\uvnc bvba\UltraVNC\ultravnc.ini"
		)
		$passwords = @("bizerba", "biyerba")
		$username = "bizuser"
		$password = $null
		$fullIniPath = $null

		# Ping check first
		if (-not (Test-Connection -ComputerName $scaleHost -Count 1 -Quiet -ErrorAction SilentlyContinue))
		{
			$AllVNCPasswords[$scaleHost] = $null
			continue
		}

		foreach ($uvncIniRel in $uvncIniRelativePaths)
		{
			foreach ($pw in $passwords)
			{
				# Clear any lingering share session, but keep the persisted credential manager entry.
				try { $null = & net.exe use "\\$scaleHost\c$" '/delete' '/y' 2>$null }
				catch { }
				cmdkey /add:$scaleHost /user:$username /pass:$pw | Out-Null
				$shareIniPath = "\\$scaleHost\c$\$uvncIniRel"
				if (Test-Path $shareIniPath -ErrorAction SilentlyContinue)
				{
					try
					{
						$content = Get-Content $shareIniPath -ErrorAction Stop
						foreach ($line in $content)
						{
							if ($line -match '^\s*passwd\s*=\s*([0-9A-Fa-f]+)')
							{
								$password = $matches[1]
								$fullIniPath = $shareIniPath
								break
							}
						}
					}
					catch { }
				}
				# Drop any temporary SMB session, but do not delete the saved credential.
				try { $null = & net.exe use "\\$scaleHost\c$" '/delete' '/y' 2>$null }
				catch { }
				if ($password) { break }
			}
			if ($password) { break }
		}
		$AllVNCPasswords[$scaleHost] = $password
	}
	$script:FunctionResults['AllVNCPasswords'] = $AllVNCPasswords
	return $AllVNCPasswords
}

# ===================================================================================================
#                              FUNCTION: Get_Remote_Machine_Info
# ---------------------------------------------------------------------------------------------------
# Description:
#   Collects hardware/software info from selected lanes, scales and backoffices: runs
#   concurrent WMI/CIM probes (plus an optional registry read via REG.EXE) per node, with an
#   INI-based fallback for lanes/backoffices. Writes per-group info files and populates
#   $script:LaneHardwareInfo / $script:ScaleHardwareInfo / $script:BackofficeHardwareInfo.
#
# Parameters:
#   - RunInBackground       [switch]: run as a background job
#   - SilentBackground      [switch]: background mode without box logging
#   - InternalBackgroundJob [switch]: called from inside the background job itself
#   - UseAllAvailableNodes  [switch]: probe every discovered node (skip the selection form)
#   - SelectedLanes / SelectedScales / SelectedBackoffices [object[]]: pre-selected nodes
#
# Variables:
#   - $script:FunctionResults: lane/scale/backoffice maps and StoreNumber (input)
#
# Writes:
#   - Info text files under Desktop\Lanes, Desktop\Scales and Desktop\BackOffices
#
# Notes:
#   - Requires admin rights on the remote machines for WMI/CIM/REG/SC operations.
# ===================================================================================================

function Get_Remote_Machine_Info
{
	param (
		[switch]$RunInBackground,
		[switch]$SilentBackground,
		[switch]$InternalBackgroundJob,
		[switch]$UseAllAvailableNodes,
		[object[]]$SelectedLanes,
		[object[]]$SelectedScales,
		[object[]]$SelectedBackoffices
	)

	$log = {
		param (
			[string]$Message,
			$Color
		)
		if (-not $SilentBackground)
		{
			Write_Log $Message $Color
		}
	}

	& $log "`r`n==================== Starting Get_Remote_Machine_Info ====================`r`n" "blue"

	# --------------------------- Tunables ---------------------------
	$maxConcurrentJobs = 10
	$wmiTimeoutSeconds = 5
	$cimTimeoutSeconds = 10
	$regTimeoutSeconds = 30
	$usePSRemotingFallback = $false # set $true to try PS-Session registry read before REG.EXE

	# --------------------------- Outputs (reset) ---------------------------
	$script:LaneHardwareInfo = $null
	$script:ScaleHardwareInfo = $null
	$script:BackofficeHardwareInfo = $null

	# --------------------------- Inputs from your environment ---------------------------
	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	$ScaleCodeToIPInfo = $script:FunctionResults['ScaleCodeToIPInfo']
	$BackofficeNumToMachineName = $script:FunctionResults['BackofficeNumToMachineName']
	$StoreNumber = $script:FunctionResults['StoreNumber']
	$DbsPath = $script:DbsPath

	# --------------------------- Keep only discovered/usable nodes ---------------------------
	$availableLaneNodes = @{ }
	if ($LaneNumToMachineName)
	{
		foreach ($kv in $LaneNumToMachineName.GetEnumerator())
		{
			$machineName = [string]$kv.Value
			if (-not [string]::IsNullOrWhiteSpace($machineName))
			{
				$availableLaneNodes[[string]$kv.Key] = $machineName.Trim()
			}
		}
	}

	$availableScaleNodes = @{ }
	if ($ScaleCodeToIPInfo)
	{
		foreach ($kv in $ScaleCodeToIPInfo.GetEnumerator())
		{
			$scaleObj = $kv.Value
			$scaleIp = $null
			if ($null -ne $scaleObj)
			{
				if (($scaleObj.PSObject.Properties.Name -contains 'FullIP') -and -not [string]::IsNullOrWhiteSpace([string]$scaleObj.FullIP))
				{
					$scaleIp = [string]$scaleObj.FullIP
				}
				elseif (
					($scaleObj.PSObject.Properties.Name -contains 'IPNetwork') -and
					($scaleObj.PSObject.Properties.Name -contains 'IPDevice') -and
					-not [string]::IsNullOrWhiteSpace([string]$scaleObj.IPNetwork) -and
					-not [string]::IsNullOrWhiteSpace([string]$scaleObj.IPDevice)
				)
				{
					$scaleIp = "$($scaleObj.IPNetwork)$($scaleObj.IPDevice)"
				}
			}

			if (-not [string]::IsNullOrWhiteSpace($scaleIp))
			{
				$availableScaleNodes[[string]$kv.Key] = $scaleObj
			}
		}
	}

	$availableBackofficeNodes = @{ }
	if ($BackofficeNumToMachineName)
	{
		foreach ($kv in $BackofficeNumToMachineName.GetEnumerator())
		{
			$machineName = [string]$kv.Value
			if (-not [string]::IsNullOrWhiteSpace($machineName))
			{
				$availableBackofficeNodes[[string]$kv.Key] = $machineName.Trim()
			}
		}
	}

	$LaneNumToMachineName = $availableLaneNodes
	$ScaleCodeToIPInfo = $availableScaleNodes
	$BackofficeNumToMachineName = $availableBackofficeNodes

	$selectedLanes = @($SelectedLanes)
	$selectedScales = @($SelectedScales)
	$selectedBOs = @($SelectedBackoffices)

	if ($UseAllAvailableNodes -and
		(-not $selectedLanes -or $selectedLanes.Count -eq 0) -and
		(-not $selectedScales -or $selectedScales.Count -eq 0) -and
		(-not $selectedBOs -or $selectedBOs.Count -eq 0))
	{
		$selectedLanes = @()
		$selectedScales = @()
		$selectedBOs = @()

		if ($LaneNumToMachineName) { $selectedLanes = @($LaneNumToMachineName.Keys | Sort-Object) }
		if ($ScaleCodeToIPInfo) { $selectedScales = @($ScaleCodeToIPInfo.Keys | Sort-Object) }
		if ($BackofficeNumToMachineName) { $selectedBOs = @($BackofficeNumToMachineName.Keys | Sort-Object) }
	}

	if ((-not $UseAllAvailableNodes) -and
		(-not $selectedLanes -or $selectedLanes.Count -eq 0) -and
		(-not $selectedScales -or $selectedScales.Count -eq 0) -and
		(-not $selectedBOs -or $selectedBOs.Count -eq 0))
	{
		# --------------------------- Let user pick nodes ---------------------------
		$nodeSelection = Show_Node_Selection_Form -StoreNumber $StoreNumber `
												  -NodeTypes @("Lane", "Scale", "Backoffice") `
												  -Title "Select Nodes to Pull Hardware Info"

		if (-not $nodeSelection)
		{
			& $log "Get_Remote_Machine_Info cancelled by user." "yellow"
			& $log "==================== Get_Remote_Machine_Info Completed ====================" "blue"
			return $false
		}

		$selectedLanes = @($nodeSelection.Lanes)
		$selectedScales = @($nodeSelection.Scales)
		$selectedBOs = @($nodeSelection.Backoffices)
	}

	if ((-not $selectedLanes -or $selectedLanes.Count -eq 0) -and
		(-not $selectedScales -or $selectedScales.Count -eq 0) -and
		(-not $selectedBOs -or $selectedBOs.Count -eq 0))
	{
		& $log "No nodes selected. Operation aborted." "yellow"
		& $log "==================== Get_Remote_Machine_Info Completed ====================" "blue"
		return $false
	}

	if ($RunInBackground -and -not $InternalBackgroundJob)
	{
		if (
			$script:RemoteMachineInfoTask -and
			$script:RemoteMachineInfoTask.Job -and
			$script:RemoteMachineInfoTask.Job.State -in @('Running', 'NotStarted')
		)
		{
			& $log "Remote machine info export is already running in the background." "yellow"
			return $true
		}

		$job = $null
		try
		{
			$getRemoteMachineInfoDefinition = ${function:Get_Remote_Machine_Info}.ToString()
			$writeLogDefinition = 'param([string]$Message, $Color, [switch]$IncludeTimestamp)'

			$job = Start-Job -Name 'RemoteMachineInfoJob' -ScriptBlock {
				param (
					[string]$GetRemoteMachineInfoDefinition,
					[string]$WriteLogDefinition,
					[hashtable]$LaneMap,
					[hashtable]$ScaleMap,
					[hashtable]$BackofficeMap,
					[string]$StoreNumber,
					[string]$DbsPath,
					[bool]$SilentBackgroundMode,
					[object[]]$SelectedLanes,
					[object[]]$SelectedScales,
					[object[]]$SelectedBackoffices
				)

				Set-Item -Path function:Write_Log -Value ([scriptblock]::Create($WriteLogDefinition))
				Set-Item -Path function:Get_Remote_Machine_Info -Value ([scriptblock]::Create($GetRemoteMachineInfoDefinition))

				$script:FunctionResults = @{
					LaneNumToMachineName	   = $LaneMap
					ScaleCodeToIPInfo		   = $ScaleMap
					BackofficeNumToMachineName = $BackofficeMap
					StoreNumber			       = $StoreNumber
				}
				$script:DbsPath = $DbsPath

				try
				{
					Get_Remote_Machine_Info `
											-SelectedLanes $SelectedLanes `
											-SelectedScales $SelectedScales `
											-SelectedBackoffices $SelectedBackoffices `
											-InternalBackgroundJob `
											-SilentBackground:$SilentBackgroundMode | Out-Null

					[pscustomobject]@{
						Success			       = $true
						LaneHardwareInfo	   = $script:LaneHardwareInfo
						ScaleHardwareInfo	   = $script:ScaleHardwareInfo
						BackofficeHardwareInfo = $script:BackofficeHardwareInfo
						Error				   = $null
					}
				}
				catch
				{
					[pscustomobject]@{
						Success			       = $false
						LaneHardwareInfo	   = $null
						ScaleHardwareInfo	   = $null
						BackofficeHardwareInfo = $null
						Error				   = $_.Exception.Message
					}
				}
			} -ArgumentList @(
				$getRemoteMachineInfoDefinition,
				$writeLogDefinition,
				$LaneNumToMachineName,
				$ScaleCodeToIPInfo,
				$BackofficeNumToMachineName,
				$StoreNumber,
				$DbsPath,
				([bool]$SilentBackground),
				$selectedLanes,
				$selectedScales,
				$selectedBOs
			)

			$script:RemoteMachineInfoTask = @{
				Job	    = $job
				Started = Get-Date
				Silent  = [bool]$SilentBackground
			}

			if (-not $script:RemoteMachineInfoReaper)
			{
				$script:RemoteMachineInfoReaper = New-Object System.Windows.Forms.Timer
				$script:RemoteMachineInfoReaper.Interval = 1000
				$script:RemoteMachineInfoReaper.Add_Tick({
						if (-not $script:RemoteMachineInfoTask)
						{
							try
							{
								if ($script:RemoteMachineInfoReaper)
								{
									$script:RemoteMachineInfoReaper.Stop()
									$script:RemoteMachineInfoReaper.Dispose()
									$script:RemoteMachineInfoReaper = $null
								}
							}
							catch { }
							return
						}

						$taskState = $script:RemoteMachineInfoTask
						if (-not $taskState.Job -or $taskState.Job.State -in @('Running', 'NotStarted')) { return }

						$result = $null
						try { $result = Receive-Job -Job $taskState.Job -ErrorAction SilentlyContinue }
						catch { }
						try { Remove-Job -Job $taskState.Job -Force -ErrorAction SilentlyContinue | Out-Null }
						catch { }

						$resultObj = $null
						if ($result)
						{
							$resultObj = @($result) | Select-Object -Last 1
						}

						if ($resultObj -and $resultObj.Success)
						{
							$script:LaneHardwareInfo = $resultObj.LaneHardwareInfo
							$script:ScaleHardwareInfo = $resultObj.ScaleHardwareInfo
							$script:BackofficeHardwareInfo = $resultObj.BackofficeHardwareInfo
							if (-not $taskState.Silent)
							{
								Write_Log "Remote machine info export completed in background." "green"
							}
						}
						elseif (-not $taskState.Silent)
						{
							$errText = if ($resultObj -and $resultObj.Error) { $resultObj.Error }
							else { "Unknown error." }
							Write_Log "Remote machine info export failed in background: $errText" "red"
						}

						$script:RemoteMachineInfoTask = $null

						try
						{
							if ($script:RemoteMachineInfoReaper)
							{
								$script:RemoteMachineInfoReaper.Stop()
								$script:RemoteMachineInfoReaper.Dispose()
								$script:RemoteMachineInfoReaper = $null
							}
						}
						catch { }
					})
			}

			if (-not $SilentBackground)
			{
				& $log "Remote machine info export started in background." "yellow"
			}

			$script:RemoteMachineInfoReaper.Start()
		}
		catch
		{
			try { if ($job) { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue | Out-Null } }
			catch { }
			$script:RemoteMachineInfoTask = $null
			& $log "Failed to start remote machine info export in background: $_" "red"
			return $false
		}

		return $true
	}

	# --------------------------- Output folders ---------------------------
	$desktop = [Environment]::GetFolderPath("Desktop")
	$lanesDir = Join-Path $desktop "Lanes"
	$scalesDir = Join-Path $desktop "Scales"
	$backofficesDir = Join-Path $desktop "BackOffices"

	# --------------------------- Process 3 categories uniformly ---------------------------
	foreach ($section in @(
			@{ Name = 'Lanes'; Selected = $selectedLanes; Dir = $lanesDir; ScriptVar = 'LaneHardwareInfo'; InfoLinesVar = 'LaneInfoLines'; ResultsVar = 'LaneResults'; FileName = 'Lanes_Info.txt' },
			@{ Name = 'Scales'; Selected = $selectedScales; Dir = $scalesDir; ScriptVar = 'ScaleHardwareInfo'; InfoLinesVar = 'ScaleInfoLines'; ResultsVar = 'ScaleResults'; FileName = 'Scales_Info.txt' },
			@{ Name = 'BackOffices'; Selected = $selectedBOs; Dir = $backofficesDir; ScriptVar = 'BackofficeHardwareInfo'; InfoLinesVar = 'BOInfoLines'; ResultsVar = 'BOResults'; FileName = 'Backoffices_Info.txt' }
		))
	{
		if (-not $section.Selected -or $section.Selected.Count -eq 0) { continue }

		& $log "Processing $($section.Name) nodes..." "yellow"
		Set-Variable -Name $($section.ResultsVar) -Value @{ }
		Set-Variable -Name $($section.InfoLinesVar) -Value @()

		$jobs = @()
		$pending = @{ }

		# Turn one finished node job into its info-file line + results entry, then drop the job
		# (dot-sourced: updates this function's variables)
		$collectNodeJob = {
			param ($j)
			$remoteName = $pending[$j.Id]
			$result = Receive-Job $j 2>$null
			$info = $result.Info

			$line = "Machine Name: $remoteName |"
			if ($info.Success)
			{
				$line += " Manufacturer: $($info.SystemManufacturer) | Model: $($info.SystemProductName) | CPU: $($info.CPU)"
				if ($null -ne $info.RAM) { $line += " | RAM: $($info.RAM) GB" }
				if ($info.OSInfo) { $line += " | OS: $($info.OSInfo)" }
				& $log "Processed $remoteName ($($section.Name)): Success [$($info.Method)]" "green"
			}
			elseif ($info.Error)
			{
				$line += " [Hardware info unavailable] Error: $($info.Error)"
				& $log "Processed $remoteName ($($section.Name)): Error [$($info.Method)] - $($info.Error)" "red"
			}
			else
			{
				$line += " [No hardware info found]"
				& $log "Processed $remoteName ($($section.Name)): No info [$($info.Method)]" "yellow"
			}
			$biosText = if ($info.BIOS) { $info.BIOS } else { "Unknown" }
			$line += " | BIOS: $biosText | Method: $($info.Method)"

			Set-Variable -Name $section.InfoLinesVar -Value (@(Get-Variable -Name $section.InfoLinesVar -ValueOnly) + $line)
			(Get-Variable -Name $section.ResultsVar -ValueOnly)[$remoteName] = $info

			Stop-Job $j -ErrorAction SilentlyContinue
			Remove-Job $j -Force -ErrorAction SilentlyContinue
			$jobs = @($jobs | Where-Object { $_.Id -ne $j.Id })
			[void]$pending.Remove($j.Id)
		}

		foreach ($sel in $section.Selected)
		{
			# -------- Canonical per-node identity: $NodeNumber (code) + $NodeName (machine/IP) --------
			$NodeNumber = $null
			$NodeName = $null

			if ($section.Name -eq 'Lanes')
			{
				if ($sel.PSObject.Properties.Name -contains 'LaneNumber' -and $sel.LaneNumber)
				{
					$NodeNumber = "{0:D3}" -f [int]$sel.LaneNumber
				}
				else { $NodeNumber = "$sel" }
				$NodeName = $LaneNumToMachineName[$NodeNumber]
			}
			elseif ($section.Name -eq 'Scales')
			{
				$NodeNumber = "$sel"
				if ($ScaleCodeToIPInfo.ContainsKey($NodeNumber) -and
					$ScaleCodeToIPInfo[$NodeNumber].PSObject.Properties.Name -contains 'FullIP')
				{
					$NodeName = $ScaleCodeToIPInfo[$NodeNumber].FullIP
				}
			}
			elseif ($section.Name -eq 'BackOffices')
			{
				if ($sel.PSObject.Properties.Name -contains 'BONumber' -and $sel.BONumber)
				{
					$NodeNumber = "{0:D3}" -f [int]$sel.BONumber
				}
				else { $NodeNumber = "$sel" }
				$NodeName = $BackofficeNumToMachineName[$NodeNumber]
			}

			if (-not $NodeName)
			{
				& $log "Skipping $($section.Name) $NodeNumber (no NodeName/mapping found)" "red"
				continue
			}

			# -------- Optional INI path (used to augment fields) --------
			$iniPattern = "INFO_${StoreNumber}${NodeNumber}_SMSStart.ini"
			if ($section.Name -eq 'Lanes') { $iniPath = Join-Path "\\$NodeName\storeman\office\dbs" $iniPattern }
			elseif ($section.Name -eq 'BackOffices') { $iniPath = Join-Path $DbsPath                         $iniPattern }
			else { $iniPath = $null }

			# -------- Per-node job (throttled outside) --------
			$job = Start-Job -Name ("RemoteMachineInfo_Node_{0}" -f $NodeName) -ArgumentList $NodeName, $NodeNumber, $iniPath, $wmiTimeoutSeconds, $cimTimeoutSeconds, $regTimeoutSeconds, $usePSRemotingFallback `
							 -ScriptBlock {
				param (
					$NodeName,
					$NodeNumber,
					$iniPath,
					$wmiTimeoutSeconds,
					$cimTimeoutSeconds,
					$regTimeoutSeconds,
					$usePSRemotingFallback
				)

				# --- 0) Result object scaffold ---
				$info = [PSCustomObject]@{
					Success			    = $false
					SystemManufacturer  = $null
					SystemProductName   = $null
					CPU				    = $null
					RAM				    = $null
					OSInfo			    = $null
					BIOS			    = $null
					Method			    = $null
					Error			    = $null
					MachineNameOverride = $null
				}

				# --- 1) WMI (fast) ---
				if (-not (Test-Connection -ComputerName $NodeName -Count 1 -Quiet -ErrorAction SilentlyContinue))
				{
					$info.Error = "Offline or unreachable."
					$info.Method = "Offline"
				}
				else
				{
					$wmiJob = Start-Job -Name ("RemoteMachineInfo_WMI_{0}" -f $NodeName) -ScriptBlock {
						param ($NodeName)
						try
						{
							$sys = Get-WmiObject -Class Win32_ComputerSystem -ComputerName $NodeName -ErrorAction SilentlyContinue
							$cpu = Get-WmiObject -Class Win32_Processor -ComputerName $NodeName -ErrorAction SilentlyContinue | Select-Object -First 1
							$os = Get-WmiObject -Class Win32_OperatingSystem -ComputerName $NodeName -ErrorAction SilentlyContinue

							# BIOS
							$biosVerOut = $null
							try
							{
								$bios = Get-WmiObject -Class Win32_BIOS -ComputerName $NodeName -ErrorAction SilentlyContinue
								if ($bios)
								{
									if ($bios.SMBIOSBIOSVersion) { $biosVerOut = $bios.SMBIOSBIOSVersion }
									elseif ($bios.BIOSVersion) { $biosVerOut = ($bios.BIOSVersion | Where-Object { $_ } | Select-Object -First 1) }
									elseif ($bios.Version) { $biosVerOut = $bios.Version }
									if ($bios.ReleaseDate)
									{
										try
										{
											$dt = [System.Management.ManagementDateTimeConverter]::ToDateTime($bios.ReleaseDate)
											if ($dt)
											{
												if ($biosVerOut) { $biosVerOut = "$biosVerOut ($($dt.ToString('yyyy-MM-dd')))" }
												else { $biosVerOut = $dt.ToString('yyyy-MM-dd') }
											}
										}
										catch { }
									}
								}
							}
							catch { }

							if ($sys -and $sys.Manufacturer -and $sys.Model)
							{
								[PSCustomObject]@{
									SystemManufacturer = $sys.Manufacturer
									SystemProductName  = $sys.Model
									CPU			       = $cpu.Name
									RAM			       = [math]::Round($sys.TotalPhysicalMemory / 1GB, 1)
									OSInfo			   = "$($os.Caption) ($($os.Version))"
									BIOS			   = $biosVerOut
									Method			   = "WMI"
								}
							}
							else { $null }
						}
						catch { $null }
					} -ArgumentList $NodeName

					if (Wait-Job $wmiJob -Timeout $wmiTimeoutSeconds)
					{
						$wmiResult = Receive-Job $wmiJob 2>$null
						Remove-Job  $wmiJob -Force -ErrorAction SilentlyContinue
					}
					else
					{
						Stop-Job    $wmiJob -ErrorAction SilentlyContinue
						Remove-Job  $wmiJob -Force -ErrorAction SilentlyContinue
						$wmiResult = $null
					}

					if ($wmiResult -and $wmiResult.SystemManufacturer -and $wmiResult.SystemProductName)
					{
						$info.SystemManufacturer = $wmiResult.SystemManufacturer
						$info.SystemProductName = $wmiResult.SystemProductName
						$info.CPU = $wmiResult.CPU
						$info.RAM = $wmiResult.RAM
						$info.OSInfo = $wmiResult.OSInfo
						if ($wmiResult.BIOS) { $info.BIOS = $wmiResult.BIOS }
						$info.Method = "WMI"
						$info.Success = $true
					}
					else
					{
						$info.Error = "WMI failed (access issue or null)"
					}
				}

				# --- 2) CIM (if WMI failed) ---
				if (-not $info.Success)
				{
					$cimJob = Start-Job -Name ("RemoteMachineInfo_CIM_{0}" -f $NodeName) -ScriptBlock {
						param ($NodeName)
						try
						{
							$session = New-CimSession -ComputerName $NodeName -ErrorAction SilentlyContinue
							if ($session)
							{
								$sys = Get-CimInstance -CimSession $session -ClassName Win32_ComputerSystem  2>$null
								$cpu = Get-CimInstance -CimSession $session -ClassName Win32_Processor       2>$null | Select-Object -First 1
								$os = Get-CimInstance -CimSession $session -ClassName Win32_OperatingSystem  2>$null

								# BIOS
								$biosVerOut = $null
								try
								{
									$bios = Get-CimInstance -CimSession $session -ClassName Win32_BIOS 2>$null
									if ($bios)
									{
										if ($bios.SMBIOSBIOSVersion) { $biosVerOut = $bios.SMBIOSBIOSVersion }
										elseif ($bios.BIOSVersion) { $biosVerOut = ($bios.BIOSVersion | Where-Object { $_ } | Select-Object -First 1) }
										elseif ($bios.Version) { $biosVerOut = $bios.Version }
										if ($bios.ReleaseDate)
										{
											try
											{
												$dt = [System.Management.ManagementDateTimeConverter]::ToDateTime($bios.ReleaseDate)
												if ($dt)
												{
													if ($biosVerOut) { $biosVerOut = "$biosVerOut ($($dt.ToString('yyyy-MM-dd')))" }
													else { $biosVerOut = $dt.ToString('yyyy-MM-dd') }
												}
											}
											catch { }
										}
									}
								}
								catch { }

								Remove-CimSession $session 2>$null
								if ($sys -and $sys.Manufacturer -and $sys.Model)
								{
									[PSCustomObject]@{
										SystemManufacturer = $sys.Manufacturer
										SystemProductName  = $sys.Model
										CPU			       = $cpu.Name
										RAM			       = [math]::Round($sys.TotalPhysicalMemory / 1GB, 1)
										OSInfo			   = "$($os.Caption) ($($os.Version))"
										BIOS			   = $biosVerOut
										Method			   = "CIM"
									}
								}
								else { $null }
							}
							else { $null }
						}
						catch { $null }
					} -ArgumentList $NodeName

					if (Wait-Job $cimJob -Timeout $cimTimeoutSeconds)
					{
						$cimResult = Receive-Job $cimJob 2>$null
						Remove-Job  $cimJob -Force -ErrorAction SilentlyContinue
					}
					else
					{
						Stop-Job    $cimJob -ErrorAction SilentlyContinue
						Remove-Job  $cimJob -Force -ErrorAction SilentlyContinue
						$cimResult = $null
					}

					if ($cimResult -and $cimResult.SystemManufacturer -and $cimResult.SystemProductName)
					{
						$info.SystemManufacturer = $cimResult.SystemManufacturer
						$info.SystemProductName = $cimResult.SystemProductName
						$info.CPU = $cimResult.CPU
						$info.RAM = $cimResult.RAM
						$info.OSInfo = $cimResult.OSInfo
						if ($cimResult.BIOS) { $info.BIOS = $cimResult.BIOS }
						$info.Method = "CIM"
						$info.Success = $true
					}
					else
					{
						$info.Error = "CIM failed (access issue or null)"
					}
				}

				# --- 3) PS-Remoting Registry (optional middle step) ---
				if (-not $info.Success -and $usePSRemotingFallback)
				{
					$regResult = $null
					try
					{
						$sessionOption = New-PSSessionOption -ConnectionTimeout 15000 -OpenTimeout 15000
						$session = New-PSSession -ComputerName $NodeName -SessionOption $sessionOption -ErrorAction SilentlyContinue
						if ($session)
						{
							$regResult = Invoke-Command -Session $session -TimeoutSec 30 -ScriptBlock {
								$out = [PSCustomObject]@{
									SystemManufacturer = $null
									SystemProductName  = $null
									CPU			       = $null
									OSInfo			   = $null
									BIOS			   = $null
									Success		       = $false
									Error			   = $null
									Method			   = 'REG(PSRemoting)'
								}
								try
								{
									$manuf = Get-ItemProperty 'HKLM:\HARDWARE\DESCRIPTION\System\BIOS' -Name SystemManufacturer -ErrorAction SilentlyContinue
									$prod = Get-ItemProperty 'HKLM:\HARDWARE\DESCRIPTION\System\BIOS' -Name SystemProductName -ErrorAction SilentlyContinue
									$cpu = Get-ItemProperty 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' -Name ProcessorNameString -ErrorAction SilentlyContinue
									$os = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue

									# BIOS pieces
									$biosVendor = (Get-ItemProperty 'HKLM:\HARDWARE\DESCRIPTION\System\BIOS' -Name BIOSVendor -ErrorAction SilentlyContinue).BIOSVendor
									$biosVerStr = (Get-ItemProperty 'HKLM:\HARDWARE\DESCRIPTION\System\BIOS' -Name BIOSVersion -ErrorAction SilentlyContinue).BIOSVersion
									if (-not $biosVerStr)
									{
										$biosVerStr = (Get-ItemProperty 'HKLM:\HARDWARE\DESCRIPTION\System\BIOS' -Name SystemBiosVersion -ErrorAction SilentlyContinue).SystemBiosVersion
									}
									$biosDate = (Get-ItemProperty 'HKLM:\HARDWARE\DESCRIPTION\System\BIOS' -Name BIOSReleaseDate -ErrorAction SilentlyContinue).BIOSReleaseDate

									# Build OSInfo
									$osInfo = $null
									if ($os -and $os.ProductName) { $osInfo = $os.ProductName }
									if ($os -and $os.DisplayVersion)
									{
										if ($osInfo) { $osInfo = "$osInfo ($($os.DisplayVersion))" }
										else { $osInfo = $os.DisplayVersion }
									}
									elseif ($os -and $os.CurrentBuild)
									{
										if ($osInfo) { $osInfo = "$osInfo (Build $($os.CurrentBuild))" }
										else { $osInfo = "Build $($os.CurrentBuild)" }
									}

									# BIOS assemble
									$biosOut = $null
									if ($biosVendor -and $biosVerStr) { $biosOut = "$biosVendor $biosVerStr" }
									elseif ($biosVerStr) { $biosOut = $biosVerStr }
									elseif ($biosVendor) { $biosOut = $biosVendor }
									if ($biosDate)
									{
										if ($biosOut) { $biosOut = "$biosOut ($biosDate)" }
										else { $biosOut = $biosDate }
									}

									$out.SystemManufacturer = $manuf.SystemManufacturer
									$out.SystemProductName = $prod.SystemProductName
									$out.CPU = $cpu.ProcessorNameString
									$out.OSInfo = $osInfo
									$out.BIOS = $biosOut
									$out.Success = $true
								}
								catch { $out.Error = $_.Exception.Message }
								return $out
							} 2>$null
							Remove-PSSession $session -ErrorAction SilentlyContinue
						}
					}
					catch
					{
						if ($session) { Remove-PSSession $session -ErrorAction SilentlyContinue }
						$regResult = [PSCustomObject]@{
							SystemManufacturer = $null
							SystemProductName  = $null
							CPU			       = $null
							OSInfo			   = $null
							BIOS			   = $null
							Success		       = $false
							Error			   = "PS-Remoting registry query failed"
							Method			   = 'REG(PSRemoting)'
						}
					}

					if ($regResult -and $regResult.Success)
					{
						if (-not $info.SystemManufacturer) { $info.SystemManufacturer = $regResult.SystemManufacturer }
						if (-not $info.SystemProductName) { $info.SystemProductName = $regResult.SystemProductName }
						if (-not $info.CPU) { $info.CPU = $regResult.CPU }
						if (-not $info.OSInfo) { $info.OSInfo = $regResult.OSInfo }
						if (-not $info.BIOS -and $regResult.BIOS) { $info.BIOS = $regResult.BIOS }
						$info.Method = $regResult.Method
						$info.Success = $true
						$info.Error = $null
					}
					elseif (-not $info.Error)
					{
						if ($regResult) { $info.Error = $regResult.Error; $info.Method = 'REG(PSRemoting)' }
					}
				}

				# --- 4) REG.EXE (starts RemoteRegistry if needed, then restores) ---
				if (-not $info.Success)
				{
					$wasRunning = $false
					$wasDisabled = $false
					try
					{
						$state = sc.exe "\\$NodeName" query RemoteRegistry 2>$null | Select-String 'STATE'
						$start = sc.exe "\\$NodeName" qc    RemoteRegistry 2>$null | Select-String 'START_TYPE'
						if ($state -and $state.Line -match 'RUNNING') { $wasRunning = $true }
						if ($start -and $start.Line -match 'DISABLED') { $wasDisabled = $true }
						if ($wasDisabled) { sc.exe "\\$NodeName" config RemoteRegistry start= demand 2>$null | Out-Null }
						if (-not $wasRunning) { sc.exe "\\$NodeName" start  RemoteRegistry 2>$null | Out-Null }

						# tiny inline getter: returns only the DATA (no "REG_SZ")
						$getVal = {
							param ($hive,
								$path,
								$name)
							$patternName = [regex]::Escape($name)
							$raw = reg.exe QUERY "\\$NodeName\$hive\$path" /v $name 2>$null
							if (-not $raw) { return $null }
							$line = $raw | Select-String -Pattern "^\s*$patternName\s+REG_\w+\s+.+$" | Select-Object -First 1
							if (-not $line) { return $null }
							$data = $line.Line -replace "^\s*$patternName\s+REG_\w+\s+", ""
							$data.Trim()
						}

						$manuf = & $getVal 'HKLM' 'HARDWARE\DESCRIPTION\System\BIOS'               'SystemManufacturer'
						$prod = & $getVal 'HKLM' 'HARDWARE\DESCRIPTION\System\BIOS'               'SystemProductName'
						$cpu = & $getVal 'HKLM' 'HARDWARE\DESCRIPTION\System\CentralProcessor\0' 'ProcessorNameString'
						$osN = & $getVal 'HKLM' 'SOFTWARE\Microsoft\Windows NT\CurrentVersion'   'ProductName'
						$osB = & $getVal 'HKLM' 'SOFTWARE\Microsoft\Windows NT\CurrentVersion'   'DisplayVersion'
						$osV = & $getVal 'HKLM' 'SOFTWARE\Microsoft\Windows NT\CurrentVersion'   'CurrentBuild'

						# BIOS from REG.EXE
						$biosVendor = & $getVal 'HKLM' 'HARDWARE\DESCRIPTION\System\BIOS' 'BIOSVendor'
						$biosVerStr = & $getVal 'HKLM' 'HARDWARE\DESCRIPTION\System\BIOS' 'BIOSVersion'
						if (-not $biosVerStr)
						{
							$biosVerStr = & $getVal 'HKLM' 'HARDWARE\DESCRIPTION\System\BIOS' 'SystemBiosVersion'
						}
						$biosDate = & $getVal 'HKLM' 'HARDWARE\DESCRIPTION\System\BIOS' 'BIOSReleaseDate'
						if ($biosVerStr)
						{
							$biosVerStr = $biosVerStr -replace '\x00', ' '
							$biosVerStr = ($biosVerStr -split '\s{2,}' | Where-Object { $_ }) -join ' '
							$biosVerStr = $biosVerStr.Trim()
						}
						$biosOut = $null
						if ($biosVendor -and $biosVerStr) { $biosOut = "$biosVendor $biosVerStr" }
						elseif ($biosVerStr) { $biosOut = $biosVerStr }
						elseif ($biosVendor) { $biosOut = $biosVendor }
						if ($biosDate)
						{
							if ($biosOut) { $biosOut = "$biosOut ($biosDate)" }
							else { $biosOut = $biosDate }
						}

						# If CurrentBuild came as "0x... (7601)" keep the number in parentheses
						if ($osV -and $osV -match '\((\d+)\)') { $osV = $matches[1] }

						# build a clean OS string
						$osInfo = $null
						if ($osN) { $osInfo = $osN }
						if ($osB)
						{
							if ($osInfo) { $osInfo = "$osInfo ($osB)" }
							else { $osInfo = $osB }
						}
						elseif ($osV)
						{
							if ($osInfo) { $osInfo = "$osInfo (Build $osV)" }
							else { $osInfo = "Build $osV" }
						}

						if ($manuf -or $prod -or $cpu -or $osInfo -or $biosOut)
						{
							if (-not $info.SystemManufacturer) { $info.SystemManufacturer = $manuf }
							if (-not $info.SystemProductName) { $info.SystemProductName = $prod }
							if (-not $info.CPU) { $info.CPU = $cpu }
							if (-not $info.OSInfo) { $info.OSInfo = $osInfo }
							if (-not $info.BIOS -and $biosOut) { $info.BIOS = $biosOut }
							$info.Method = "REG.EXE"
							$info.Success = $true
							$info.Error = $null
						}
						else
						{
							$info.Method = "REG.EXE"
							$info.Success = $false
							$info.Error = "REG queries returned no data"
						}
					}
					catch
					{
						$info.Method = "REG.EXE"
						$info.Success = $false
						$info.Error = "REG queries failed"
					}
					finally
					{
						try
						{
							if (-not $wasRunning) { sc.exe "\\$NodeName" stop RemoteRegistry 2>$null | Out-Null }
							if ($wasDisabled) { sc.exe "\\$NodeName" config RemoteRegistry start= disabled 2>$null | Out-Null }
						}
						catch { }
					}
				}

				# --- 5) INI augmentation (optional; fills gaps if any fields still null) ---
				$returnInfo = [PSCustomObject]@{
					Machine    = $NodeName
					NodeNumber = $NodeNumber
					Info	   = $info
					IniFound   = $false
					IniPath    = $null
				}
				try
				{
					if ($iniPath)
					{
						$iniFolder = Split-Path $iniPath -Parent
						$iniLeaf = Split-Path $iniPath -Leaf
						$iniFile = Get-ChildItem -Path $iniFolder -Filter $iniLeaf -ErrorAction SilentlyContinue |
						Sort-Object LastWriteTime -Descending |
						Select-Object -First 1
						if ($iniFile -and (Test-Path $iniFile.FullName))
						{
							$returnInfo.IniFound = $true
							$returnInfo.IniPath = $iniFile.FullName
							$iniLines = Get-Content $iniFile.FullName -Encoding UTF8 -ErrorAction SilentlyContinue

							# tiny parser
							$sections = @{ }
							$curSec = ""
							foreach ($line in $iniLines)
							{
								if ($line -match '^\[(.+)\]$')
								{
									$curSec = $matches[1]; $sections[$curSec] = @{ }
								}
								elseif ($line -match '^\s*([^=]+?)\s*=\s*(.*)$' -and $curSec)
								{
									$sections[$curSec][$matches[1].Trim()] = $matches[2].Trim()
								}
							}
							if (-not $info.CPU -and $sections.ContainsKey('PROCESSOR') -and $sections['PROCESSOR'].ContainsKey('Cores'))
							{
								$cores = $sections['PROCESSOR']['Cores']
								$arch = $sections['PROCESSOR']['Architecture']
								if ($arch) { $info.CPU = "$cores cores ($arch)" }
								else { $info.CPU = "$cores cores" }
							}
							if ($info.RAM -eq $null -and $sections.ContainsKey('Memory') -and $sections['Memory'].ContainsKey('PhysicalMemory'))
							{
								$ramMb = $sections['Memory']['PhysicalMemory']
								if ($ramMb -match '^\d+$') { $info.RAM = [math]::Round([double]$ramMb/1024, 1) }
								else { $info.RAM = $ramMb }
							}
							if (-not $info.OSInfo -and $sections.ContainsKey('OperatingSystem') -and $sections['OperatingSystem'].ContainsKey('ProductName'))
							{
								$info.OSInfo = $sections['OperatingSystem']['ProductName']
							}
						}
					}
				}
				catch { }

				return $returnInfo
			}

			$jobs = @($jobs) + $job
			$pending[$job.Id] = $NodeName

			# Throttle: wait for a slot (a job that does not finish within 60 s is collected in the drain below)
			while ($jobs.Count -ge $maxConcurrentJobs)
			{
				$done = Wait-Job -Job $jobs -Any -Timeout 60
				if (-not $done) { break }
				foreach ($j in @($done)) { . $collectNodeJob $j }
			}
		} # end foreach selected

		# Drain remaining jobs
		if ($jobs.Count -gt 0)
		{
			Wait-Job -Job $jobs -Timeout 60 | Out-Null
			foreach ($j in @($jobs)) { . $collectNodeJob $j }
		}

		# Write file (stable sorting: IPs zero-padded; otherwise lexical)
		$infolines = Get-Variable -Name $($section.InfoLinesVar) -ValueOnly
		if ($infolines.Count)
		{
			[void][System.IO.Directory]::CreateDirectory($section.Dir)

			$sortedLines = $infolines | Sort-Object {
				if ($_ -match "^Machine Name: ([^|]+)")
				{
					$name = $matches[1].Trim()
					if ($name -match '^\d{1,3}(\.\d{1,3}){3}$')
					{
						$oct = $name -split '\.'
						'{0:D3}.{1:D3}.{2:D3}.{3:D3}' -f [int]$oct[0], [int]$oct[1], [int]$oct[2], [int]$oct[3]
					}
					else { $name }
				}
				else { $_ }
			}
			$filePath = Join-Path $section.Dir $section.FileName
			$sortedLines -join "`r`n" | Set-Content -Path $filePath -Encoding Default
			& $log "Exported $($section.Name) info to $filePath" "green"
		}

		# Publish programmatic map
		$mapOut = Get-Variable -Name $($section.ResultsVar) -ValueOnly
		if ($section.Name -eq 'Lanes') { $script:LaneHardwareInfo = $mapOut }
		elseif ($section.Name -eq 'Scales') { $script:ScaleHardwareInfo = $mapOut }
		elseif ($section.Name -eq 'BackOffices') { $script:BackofficeHardwareInfo = $mapOut }

		& $log "Completed processing $($section.Name).`r`n" "green"
	} # end sections

	& $log "==================== Get_Remote_Machine_Info Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Start_Quarterly_System_Health_Maintenance
# ---------------------------------------------------------------------------------------------------
# Description:
#   Runs DISM/SFC system health maintenance at most once per interval. Launches a detached
#   hidden PowerShell worker so the scan continues even if the main app closes, and persists
#   run state plus summary/run logs under the configured folders.
#
# Parameters:
#   - IntervalMonths        [int]: minimum months between runs (default 3)
#   - RetentionCount        [int]: number of run logs to keep (default 8)
#   - SummaryRetentionLines [int]: summary log lines to keep (default 250)
#
# Variables:
#   - $script:SystemHealthMaintenance*: state/lock/worker/summary log paths (set at script top)
#
# Returns:
#   @{ Started; Running; Due; Pid; RunLogPath } when a worker started, else $false.
#
# Writes:
#   - state JSON, summary log and run logs under Setup_Files / the script log folder
# ===================================================================================================

function Start_Quarterly_System_Health_Maintenance
{
	[CmdletBinding()]
	param (
		[int]$IntervalMonths = 3,
		[int]$RetentionCount = 8,
		[int]$SummaryRetentionLines = 250
	)

	$statePath = $script:SystemHealthMaintenanceStatePath
	$lockPath = $script:SystemHealthMaintenanceLockPath
	$workerPath = $script:SystemHealthMaintenanceWorkerPath
	$summaryLogPath = $script:SystemHealthMaintenanceSummaryLogPath
	$runLogPattern = $script:SystemHealthMaintenanceRunLogPattern
	$runLogPrefix = $script:SystemHealthMaintenanceRunLogPrefix
	$logFolder = $script:ScriptsLog
	$setupFolder = $script:SetupFiles
	$nowUtc = [DateTime]::UtcNow
	$state = $null

	# DISM and SFC refuse to run without elevation (exit 740 / 1). Without this check a
	# non-elevated launch (e.g. irm | iex from a normal console) recorded a 'completed' run that
	# did nothing and postponed the real one by a full interval.
	$isAdmin = $false
	try { $isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) }
	catch { }
	if (-not $isAdmin)
	{
		try { Write_Log "Quarterly system health maintenance skipped - not running as administrator." "gray" -FileOnly }
		catch { }
		return @{ Started = $false; Running = $false; Due = $null; Skipped = 'NotElevated' }
	}

	try
	{
		if (-not (Test-Path -LiteralPath $logFolder)) { New-Item -Path $logFolder -ItemType Directory -Force | Out-Null }
		if (-not (Test-Path -LiteralPath $setupFolder)) { New-Item -Path $setupFolder -ItemType Directory -Force | Out-Null }
	}
	catch
	{
		try { Write_Log "Quarterly system health maintenance: failed to ensure log/state folders. $_" "red" }
		catch { }
		return $false
	}

	try
	{
		if (Test-Path -LiteralPath $statePath)
		{
			$state = (Get-Content -LiteralPath $statePath -Raw -ErrorAction Stop) | ConvertFrom-Json -ErrorAction Stop
		}
	}
	catch
	{
		$state = $null
	}

	$workerScriptText = @'
# ---------------------------------------------------------------------------------------------------
# Quarterly system health worker - embedded at build time into Start_Quarterly_System_Health_Maintenance
#   and written to Scripts\Quarterly_System_Health_Maintenance_Worker.ps1, then run detached as
#   powershell.exe -File (elevated parent required: DISM / SFC need admin).
#   DISM RestoreHealth -> DISM StartComponentCleanup -> SFC /SCANNOW, with a lock file, a state JSON,
#   a per-run log (rotated to RetentionCount) and one summary line per run.
# ---------------------------------------------------------------------------------------------------
param (
	[string]$StatePath,
	[string]$LockPath,
	[string]$SummaryLogPath,
	[string]$RunLogPath,
	[string]$RunLogPattern,
	[int]$RetentionCount = 8,
	[int]$SummaryRetentionLines = 250,
	[string]$RunId
)

$ErrorActionPreference = 'Continue'
$runStartUtc = [DateTime]::UtcNow
$runStartLocal = Get-Date
$runLogFolder = Split-Path -Path $RunLogPath -Parent
$summaryFolder = Split-Path -Path $SummaryLogPath -Parent

if (-not (Test-Path -LiteralPath $runLogFolder)) { New-Item -Path $runLogFolder -ItemType Directory -Force | Out-Null }
if (-not (Test-Path -LiteralPath $summaryFolder)) { New-Item -Path $summaryFolder -ItemType Directory -Force | Out-Null }

$writeState = {
	param (
		[string]$Status,
		[Nullable[int]]$WorkerPid,
		[string]$LastStartedTimeUtc,
		[string]$LastCompletedTimeUtc,
		[string]$LastOutcome,
		[string]$LastSummary,
		[int]$RestoreHealthExitCode,
		[int]$StartComponentCleanupExitCode,
		[int]$SfcExitCode
	)

	$stateObj = [pscustomobject]@{
		Status						 = $Status
		Pid							 = $WorkerPid
		LastRunId					 = $RunId
		LastStartedTimeUtc			 = $LastStartedTimeUtc
		LastCompletedTimeUtc		 = $LastCompletedTimeUtc
		LastOutcome					 = $LastOutcome
		LastSummary					 = $LastSummary
		RestoreHealthExitCode		 = $RestoreHealthExitCode
		StartComponentCleanupExitCode = $StartComponentCleanupExitCode
		SfcExitCode					 = $SfcExitCode
		RunLogPath					 = $RunLogPath
	}

	($stateObj | ConvertTo-Json -Depth 6) | Set-Content -LiteralPath $StatePath -Encoding UTF8 -Force
}

$appendLog = {
	param ([string]$Text)
	Add-Content -LiteralPath $RunLogPath -Value $Text -Encoding UTF8
}

$restoreHealthExit = -1
$startCleanupExit = -1
$sfcExit = -1
$overall = 'Unknown'
$summaryLine = $null

try
{
	$lockObj = [pscustomobject]@{
		Pid		   = $PID
		RunId	   = $RunId
		StartedUtc = $runStartUtc.ToString('o')
		RunLogPath = $RunLogPath
	}
	($lockObj | ConvertTo-Json -Depth 4) | Set-Content -LiteralPath $LockPath -Encoding UTF8 -Force

	& $writeState 'Running' $PID $runStartUtc.ToString('o') $null $null $null $restoreHealthExit $startCleanupExit $sfcExit

	& $appendLog ('=' * 100)
	& $appendLog ('Quarterly system health maintenance started: {0}' -f $runStartLocal.ToString('yyyy-MM-dd HH:mm:ss'))
	& $appendLog ('RunId: {0}' -f $RunId)
	& $appendLog ('PID: {0}' -f $PID)
	& $appendLog ('=' * 100)
	& $appendLog ''

	& $appendLog '>>> DISM /Online /Cleanup-Image /RestoreHealth /Source:WindowsUpdate'
	& dism.exe /Online /Cleanup-Image /RestoreHealth /Source:WindowsUpdate *>&1 | Tee-Object -FilePath $RunLogPath -Append | Out-Null
	$restoreHealthExit = $LASTEXITCODE
	& $appendLog ('DISM RestoreHealth exit code: {0}' -f $restoreHealthExit)
	& $appendLog ''

	& $appendLog '>>> DISM /Online /Cleanup-Image /StartComponentCleanup'
	& dism.exe /Online /Cleanup-Image /StartComponentCleanup *>&1 | Tee-Object -FilePath $RunLogPath -Append | Out-Null
	$startCleanupExit = $LASTEXITCODE
	& $appendLog ('DISM StartComponentCleanup exit code: {0}' -f $startCleanupExit)
	& $appendLog ''

	& $appendLog '>>> SFC /SCANNOW'
	# SFC writes UTF-16 to a redirected stdout: drop the NULs so the run log is readable
	& sfc.exe /SCANNOW *>&1 | ForEach-Object { ([string]$_) -replace "`0", '' } | Where-Object { $_.Trim() } | Add-Content -LiteralPath $RunLogPath -Encoding UTF8
	$sfcExit = $LASTEXITCODE
	& $appendLog ('SFC exit code: {0}' -f $sfcExit)
	& $appendLog ''

	if ($restoreHealthExit -eq 0 -and $startCleanupExit -eq 0 -and $sfcExit -eq 0)
	{
		$overall = 'Success'
	}
	elseif ($restoreHealthExit -lt 0 -or $startCleanupExit -lt 0 -or $sfcExit -lt 0)
	{
		$overall = 'Failed'
	}
	else
	{
		$overall = 'CompletedWithIssues'
	}
}
catch
{
	$overall = 'Failed'
	& $appendLog ('Worker exception: {0}' -f $_.Exception.Message)
}
finally
{
	$runEndUtc = [DateTime]::UtcNow
	$duration = $runEndUtc - $runStartUtc
	$summaryLine = '[{0}] Overall={1}; RestoreHealth={2}; StartComponentCleanup={3}; SFC={4}; Duration={5:dd\.hh\:mm\:ss}; Log={6}' -f `
		$runEndUtc.ToLocalTime().ToString('yyyy-MM-dd HH:mm:ss'), `
		$overall, `
		$restoreHealthExit, `
		$startCleanupExit, `
		$sfcExit, `
		$duration, `
		$RunLogPath

	try
	{
		Add-Content -LiteralPath $SummaryLogPath -Value $summaryLine -Encoding UTF8
	}
	catch { }

	try
	{
		if (Test-Path -LiteralPath $SummaryLogPath)
		{
			$summaryLines = @(Get-Content -LiteralPath $SummaryLogPath -ErrorAction SilentlyContinue)
			if ($summaryLines.Count -gt $SummaryRetentionLines)
			{
				$summaryLines | Select-Object -Last $SummaryRetentionLines | Set-Content -LiteralPath $SummaryLogPath -Encoding UTF8 -Force
			}
		}
	}
	catch { }

	try
	{
		$oldLogs = @(Get-ChildItem -LiteralPath $runLogFolder -Filter $RunLogPattern -File -ErrorAction SilentlyContinue |
			Sort-Object LastWriteTime -Descending |
			Select-Object -Skip $RetentionCount)
		foreach ($oldLog in $oldLogs)
		{
			try { Remove-Item -LiteralPath $oldLog.FullName -Force -ErrorAction SilentlyContinue }
			catch { }
		}
	}
	catch { }

	try
	{
		& $writeState 'Idle' $null $runStartUtc.ToString('o') $runEndUtc.ToString('o') $overall $summaryLine $restoreHealthExit $startCleanupExit $sfcExit
	}
	catch { }

	try { Remove-Item -LiteralPath $LockPath -Force -ErrorAction SilentlyContinue }
	catch { }
}
'@

	try
	{
		Set-Content -LiteralPath $workerPath -Value $workerScriptText -Encoding UTF8 -Force
	}
	catch
	{
		try { Write_Log "Quarterly system health maintenance: failed to write worker script. $_" "red" }
		catch { }
		return $false
	}

	$existingWorkerPid = $null
	try
	{
		$escapedWorkerPath = [regex]::Escape($workerPath)
		$existingWorker = @(Get-CimInstance Win32_Process -Filter "Name = 'powershell.exe'" -ErrorAction SilentlyContinue |
			Where-Object { $_.CommandLine -and $_.CommandLine -match $escapedWorkerPath } |
			Select-Object -First 1)
		if ($existingWorker.Count -gt 0)
		{
			$existingWorkerPid = [int]$existingWorker[0].ProcessId
		}
	}
	catch { }

	if (-not $existingWorkerPid -and $state -and $state.Pid)
	{
		try
		{
			$null = Get-Process -Id ([int]$state.Pid) -ErrorAction Stop
			$existingWorkerPid = [int]$state.Pid
		}
		catch { }
	}

	if ($existingWorkerPid)
	{
		try
		{
			$runningState = [pscustomobject]@{
				Status    = 'Running'
				Pid	      = $existingWorkerPid
				LastRunId = if ($state -and $state.LastRunId) { [string]$state.LastRunId } else { $null }
				LastStartedTimeUtc = if ($state -and $state.LastStartedTimeUtc) { [string]$state.LastStartedTimeUtc } else { $nowUtc.ToString('o') }
				LastCompletedTimeUtc = if ($state -and $state.LastCompletedTimeUtc) { [string]$state.LastCompletedTimeUtc } else { $null }
				LastOutcome = if ($state -and $state.LastOutcome) { [string]$state.LastOutcome } else { $null }
				LastSummary = if ($state -and $state.LastSummary) { [string]$state.LastSummary } else { $null }
				RestoreHealthExitCode = if ($state -and $null -ne $state.RestoreHealthExitCode) { [int]$state.RestoreHealthExitCode } else { $null }
				StartComponentCleanupExitCode = if ($state -and $null -ne $state.StartComponentCleanupExitCode) { [int]$state.StartComponentCleanupExitCode } else { $null }
				SfcExitCode = if ($state -and $null -ne $state.SfcExitCode) { [int]$state.SfcExitCode } else { $null }
				RunLogPath = if ($state -and $state.RunLogPath) { [string]$state.RunLogPath } else { $null }
			}
			($runningState | ConvertTo-Json -Depth 6) | Set-Content -LiteralPath $statePath -Encoding UTF8 -Force
		}
		catch { }

		return @{ Started = $false; Running = $true; Due = $false }
	}

	$lastCompletedUtc = $null
	if ($state -and $state.LastCompletedTimeUtc)
	{
		try { $lastCompletedUtc = [DateTime]::Parse([string]$state.LastCompletedTimeUtc).ToUniversalTime() }
		catch { $lastCompletedUtc = $null }
	}

	if ($state -and $state.Status -eq 'Running')
	{
		try { Remove-Item -LiteralPath $lockPath -Force -ErrorAction SilentlyContinue }
		catch { }
	}

	if ($lastCompletedUtc)
	{
		$nextDueUtc = $lastCompletedUtc.AddMonths($IntervalMonths)
		if ($nextDueUtc -gt $nowUtc)
		{
			return @{ Started = $false; Running = $false; Due = $false; NextDueUtc = $nextDueUtc }
		}
	}

	$runId = [guid]::NewGuid().ToString()
	$runLogName = '{0}{1}.log' -f $runLogPrefix, (Get-Date -Format 'yyyyMMdd_HHmmss')
	$runLogPath = Join-Path $logFolder $runLogName
	# Always Windows PowerShell itself: for a packaged .exe launch the current process path is the
	# TBS exe, which would just start a second (hidden) copy of the app instead of the worker.
	$psExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
	if (-not (Test-Path -LiteralPath $psExe)) { $psExe = 'powershell.exe' }
	$q = { param ([string]$v) '"' + $v + '"' }   # Start-Process does not quote arguments

	$argList = @(
		'-NoProfile',
		'-ExecutionPolicy', 'Bypass',
		'-File', (& $q $workerPath),
		'-StatePath', (& $q $statePath),
		'-LockPath', (& $q $lockPath),
		'-SummaryLogPath', (& $q $summaryLogPath),
		'-RunLogPath', (& $q $runLogPath),
		'-RunLogPattern', (& $q $runLogPattern),
		'-RetentionCount', [string]$RetentionCount,
		'-SummaryRetentionLines', [string]$SummaryRetentionLines,
		'-RunId', $runId
	)

	try
	{
		$proc = Start-Process -FilePath $psExe -ArgumentList $argList -WindowStyle Hidden -PassThru -ErrorAction Stop

		$runningState = [pscustomobject]@{
			Status			     = 'Running'
			Pid				     = $proc.Id
			LastRunId		     = $runId
			LastStartedTimeUtc   = $nowUtc.ToString('o')
			LastCompletedTimeUtc = if ($lastCompletedUtc) { $lastCompletedUtc.ToString('o') } else { $null }
			LastOutcome		     = if ($state -and $state.LastOutcome) { [string]$state.LastOutcome } else { $null }
			LastSummary		     = if ($state -and $state.LastSummary) { [string]$state.LastSummary } else { $null }
			RestoreHealthExitCode = if ($state -and $null -ne $state.RestoreHealthExitCode) { [int]$state.RestoreHealthExitCode } else { $null }
			StartComponentCleanupExitCode = if ($state -and $null -ne $state.StartComponentCleanupExitCode) { [int]$state.StartComponentCleanupExitCode } else { $null }
			SfcExitCode		     = if ($state -and $null -ne $state.SfcExitCode) { [int]$state.SfcExitCode } else { $null }
			RunLogPath		     = $runLogPath
		}
		($runningState | ConvertTo-Json -Depth 6) | Set-Content -LiteralPath $statePath -Encoding UTF8 -Force
		return @{ Started = $true; Running = $true; Due = $true; Pid = $proc.Id; RunLogPath = $runLogPath }
	}
	catch
	{
		try { Write_Log "Quarterly system health maintenance: failed to start worker process. $_" "red" }
		catch { }
		return $false
	}
}

# ===================================================================================================
#                              FUNCTION: Show_CheckList_Form
# ---------------------------------------------------------------------------------------------------
# Description:
#   Generic modal check-list dialog: a prompt, a CheckedListBox of items, Select All /
#   Deselect All and OK / Cancel. The Select All button turns yellow when some items are
#   checked and green when all are. Used by Show_Table_Selection_Form and
#   Show_Section_Selection_Form.
#
# Parameters:
#   - Title   [string]: window title
#   - Prompt  [string]: line above the list
#   - Items   [string[]]: entries to list (in the given order, none checked)
#   - Width   [int]: list width in pixels (default 410)
#   - Height  [int]: list height in pixels (default 400)
#
# Returns:
#   Array of the checked items, or $null when cancelled.
# ===================================================================================================

function Show_CheckList_Form
{
	param (
		[string]$Title = 'Select',
		[string]$Prompt = '',
		[string[]]$Items = @(),
		[int]$Width = 410,
		[int]$Height = 400
	)
	Add-Type -AssemblyName System.Windows.Forms
	Add-Type -AssemblyName System.Drawing

	$form = New-Object System.Windows.Forms.Form
	$form.Text = $Title
	$form.ClientSize = New-Object System.Drawing.Size(($Width + 20), ($Height + 140))
	$form.StartPosition = "CenterScreen"
	$form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
	$form.MaximizeBox = $false
	$form.MinimizeBox = $false

	$label = New-Object System.Windows.Forms.Label
	$label.Text = $Prompt
	$label.Location = New-Object System.Drawing.Point(10, 10)
	$label.AutoSize = $true
	$form.Controls.Add($label)

	$checkedListBox = New-Object System.Windows.Forms.CheckedListBox
	$checkedListBox.Location = New-Object System.Drawing.Point(10, 40)
	$checkedListBox.Size = New-Object System.Drawing.Size($Width, $Height)
	$checkedListBox.CheckOnClick = $true
	foreach ($item in $Items) { [void]$checkedListBox.Items.Add($item, $false) }
	$form.Controls.Add($checkedListBox)

	# Two button rows, centred under the list
	$rowLeft = [int](($Width + 20 - 380) / 2)
	$newButton = {
		param ([string]$Text, [int]$X, [int]$Y, [int]$W)
		$b = New-Object System.Windows.Forms.Button
		$b.Text = $Text
		$b.Location = New-Object System.Drawing.Point($X, $Y)
		$b.Size = New-Object System.Drawing.Size($W, 32)
		$b.BackColor = [System.Drawing.SystemColors]::Control
		$form.Controls.Add($b)
		return $b
	}
	$btnSelectAll = & $newButton 'Select All' $rowLeft ($Height + 60) 180
	$btnDeselectAll = & $newButton 'Deselect All' ($rowLeft + 200) ($Height + 60) 180
	$btnOK = & $newButton 'OK' ($rowLeft + 40) ($Height + 100) 140
	$btnOK.DialogResult = [System.Windows.Forms.DialogResult]::OK
	$form.AcceptButton = $btnOK
	$btnCancel = & $newButton 'Cancel' ($rowLeft + 200) ($Height + 100) 140
	$btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
	$form.CancelButton = $btnCancel
	if ($Apply_Modern_Popup_Style) { & $Apply_Modern_Popup_Style $form }

	# Select All colour: control (none) / yellow (some) / green (all)
	$updateSelectAll = {
		$checked = $checkedListBox.CheckedItems.Count
		$btnSelectAll.BackColor = if ($checked -gt 0 -and $checked -eq $checkedListBox.Items.Count) { [System.Drawing.Color]::LightGreen }
		elseif ($checked -gt 0) { [System.Drawing.Color]::Yellow }
		else { [System.Drawing.SystemColors]::Control }
	}
	$setAll = {
		param ([bool]$State)
		for ($i = 0; $i -lt $checkedListBox.Items.Count; $i++) { $checkedListBox.SetItemChecked($i, $State) }
		& $updateSelectAll
	}

	$btnSelectAll.Add_Click({ & $setAll $true })
	$btnDeselectAll.Add_Click({ & $setAll $false })
	# (ItemCheck fires before the state changes - MouseUp / KeyUp see the new state)
	$checkedListBox.Add_MouseUp({ & $updateSelectAll })
	$checkedListBox.Add_KeyUp({ & $updateSelectAll })

	try
	{
		if ($form.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return $null }
		return @($checkedListBox.CheckedItems | ForEach-Object { [string]$_ })
	}
	finally { $form.Dispose() }
}

# ===================================================================================================
#                              FUNCTION: Show_Node_Selection_Form
# ---------------------------------------------------------------------------------------------------
# Description:
#   The shared node picker: tabbed WinForms dialog for Lanes, Scales, Backoffices, or any
#   combination. Returns a hashtable with keys matching the selected node types (Lanes,
#   Scales, Backoffices), or $null when the user cancels or selects nothing.
#
# Parameters:
#   - StoreNumber        [string] (required): store to look up
#   - NodeTypes          [string[]]: "Lane" / "Scale" / "Backoffice" (default: all three)
#   - OnlyBizerbaScales  [switch]: limit the Scales tab to Bizerba scales
#   - Title              [string]: dialog title (default "Select Nodes to Process")
#   - ExcludedNodes      [string[]]: machine names and/or 3-digit lane numbers to hide
#   - SingleLaneOnly     [switch]: cap lane selection at 1
#   - LaneSelectionLimit [int]: cap lane selection at N (0 = unlimited)
# ===================================================================================================

function Show_Node_Selection_Form
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[Parameter()]
		[ValidateSet("Lane", "Scale", "Backoffice")]
		[string[]]$NodeTypes = @("Lane", "Scale", "Backoffice"),
		[switch]$OnlyBizerbaScales,
		[string]$Title = "Select Nodes to Process",
		[string[]]$ExcludedNodes,
		[switch]$SingleLaneOnly,
		# NEW: cap lane selection at 1 (optional)
		[int]$LaneSelectionLimit = 0 # NEW: cap lane selection at N (0 = unlimited)
	)

	Add-Type -AssemblyName System.Windows.Forms
	Add-Type -AssemblyName System.Drawing

	# Normalize exclusions (names lowercased; lanes as 3-digit)
	$__ex_names = @()
	$__ex_lanes = @()
	if ($ExcludedNodes)
	{
		foreach ($e in $ExcludedNodes)
		{
			if ($null -ne $e -and "$e".Trim())
			{
				$s = "$e".Trim()
				if ($s -match '(\d{1,3})$')
				{
					try { $__ex_lanes += ('{0:D3}' -f ([int]$matches[1])) }
					catch { }
				}
				$__ex_names += $s.ToLower()
			}
		}
		$__ex_names = $__ex_names | Select-Object -Unique
		$__ex_lanes = $__ex_lanes | Select-Object -Unique
	}

	$form = New-Object System.Windows.Forms.Form
	$form.Text = $Title
	$form.Size = New-Object System.Drawing.Size(430, 450)
	$form.StartPosition = "CenterScreen"
	$form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
	$form.MaximizeBox = $false
	$form.MinimizeBox = $false

	$tabs = New-Object System.Windows.Forms.TabControl
	$tabs.Location = New-Object System.Drawing.Point(10, 10)
	$tabs.Size = New-Object System.Drawing.Size(390, 320)
	$form.Controls.Add($tabs)

	$tabControls = @{ }

	# ----- Lanes Tab -----
	if ("Lane" -in $NodeTypes)
	{
		$tabLanes = New-Object System.Windows.Forms.TabPage
		$tabLanes.Text = "Lanes"
		$clbLanes = New-Object System.Windows.Forms.CheckedListBox
		$clbLanes.Location = New-Object System.Drawing.Point(10, 10)
		$clbLanes.Size = New-Object System.Drawing.Size(350, 270)
		$clbLanes.CheckOnClick = $true
		$tabLanes.Controls.Add($clbLanes)
		$tabs.TabPages.Add($tabLanes)
		$tabControls["Lanes"] = $clbLanes

		# Load lane node data from FunctionResults
		$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
		$LaneMachineLabels = $script:FunctionResults['LaneMachineLabels']
		$LaneMachinePath = $script:FunctionResults['LaneMachinePath']
		$LaneMachineToServerPath = $script:FunctionResults['LaneMachineToServerPath']

		$allLanes = @()
		if ($script:FunctionResults.ContainsKey('LaneMachineNames') -and $script:FunctionResults['LaneMachineNames'].Count -gt 0)
		{
			$allLanes = $script:FunctionResults['LaneMachineNames']
		}
		elseif (Test-Path -Path $OfficePath)
		{
			$laneFolders = Get-ChildItem -Path $OfficePath -Directory -Filter "XF${StoreNumber}0*"
			if ($laneFolders) { $allLanes = $laneFolders | ForEach-Object { $_.Name.Substring($_.Name.Length - 3, 3) } }
		}

		# machine -> 3-digit lane number (first match, as before)
		$machineToLaneNum = @{ }
		if ($LaneNumToMachineName)
		{
			foreach ($key in @($LaneNumToMachineName.Keys | Sort-Object))
			{
				$m = [string]$LaneNumToMachineName[$key]
				if ($key -match '^\d{3}$' -and $m -and -not $machineToLaneNum.ContainsKey($m)) { $machineToLaneNum[$m] = $key }
			}
		}

		foreach ($laneMachine in ($allLanes | Sort-Object))
		{
			$laneNum = $machineToLaneNum[[string]$laneMachine]

			# Skip excluded by machine name or lane number
			$__skip = $false
			if ($laneMachine -and ($__ex_names -contains $laneMachine.ToLower())) { $__skip = $true }
			elseif ($laneNum -and ($__ex_lanes -contains $laneNum)) { $__skip = $true }
			if ($__skip) { continue }

			# Add item
			$obj = [PSCustomObject]@{
				LaneNumber  = $laneNum
				MachineName = $laneMachine
				Label	    = $LaneMachineLabels[$laneMachine]
				Path	    = $LaneMachinePath[$laneMachine]
				ServerPath  = $LaneMachineToServerPath[$laneMachine]
				DisplayName = if ($laneNum) { "$laneMachine ($laneNum)" } else { $laneMachine }
			}
			$obj | Add-Member -MemberType ScriptMethod -Name ToString -Value { $this.DisplayName } -Force
			$clbLanes.Items.Add($obj) | Out-Null
		}

		# --- Enforce optional selection cap for lanes (single or N) ---
		$__laneCap = if ($SingleLaneOnly) { 1 }
		elseif ($LaneSelectionLimit -gt 0) { [int]$LaneSelectionLimit }
		else { 0 }
		if ($__laneCap -gt 0)
		{
			$clbLanes.Add_ItemCheck({
					# If trying to check and it would exceed the cap, cancel the check.
					if ($_.NewValue -ne [System.Windows.Forms.CheckState]::Checked) { return }
					$idx = $_.Index
					$checkedCount = 0
					for ($i = 0; $i -lt $clbLanes.Items.Count; $i++)
					{
						if ($i -ne $idx -and $clbLanes.GetItemChecked($i)) { $checkedCount++ }
					}
					if (($checkedCount + 1) -gt $__laneCap)
					{
						$_.NewValue = [System.Windows.Forms.CheckState]::Unchecked
						if (-not $script:__laneLimitWarned)
						{
							[System.Windows.Forms.MessageBox]::Show("You can select at most $__laneCap lane(s).", "Selection limit",
								[System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
							$script:__laneLimitWarned = $true
						}
					}
				})
		}
	}

	# ----- Scales Tab -----
	if ("Scale" -in $NodeTypes)
	{
		$tabScales = New-Object System.Windows.Forms.TabPage
		$tabScales.Text = "Scales"
		$clbScales = New-Object System.Windows.Forms.CheckedListBox
		$clbScales.Location = New-Object System.Drawing.Point(10, 10)
		$clbScales.Size = New-Object System.Drawing.Size(350, 270)
		$clbScales.CheckOnClick = $true
		$tabScales.Controls.Add($clbScales)
		$tabs.TabPages.Add($tabScales)
		$tabControls["Scales"] = $clbScales

		$allScales = @()
		if ($script:FunctionResults.ContainsKey('ScaleCodeToIPInfo'))
		{
			$allScales = $script:FunctionResults['ScaleCodeToIPInfo'].Values
			if ($OnlyBizerbaScales) { $allScales = $allScales | Where-Object { $_.ScaleBrand -match 'bizerba' } }
		}
		# numeric order; non-numeric TBS codes (e.g. 801_TBS2) sort by their digits
		$sortedScales = $allScales | Sort-Object { [double](([string]$_.ScaleCode -replace '[^\d]', '0')) }, { [string]$_.ScaleCode }

		$uniqueScaleIPs = @{ }
		$dedupedScales = @()
		foreach ($scale in $sortedScales)
		{
			$ipKey = if ($scale.FullIP) { $scale.FullIP }
			elseif ($scale.IPNetwork -and $scale.IPDevice) { "$($scale.IPNetwork)$($scale.IPDevice)" }
			else { $null }
			if ($ipKey -and -not $uniqueScaleIPs.ContainsKey($ipKey))
			{
				$uniqueScaleIPs[$ipKey] = $true
				$dedupedScales += $scale
			}
		}

		foreach ($scale in $dedupedScales)
		{
			# Skip excluded by name/code
			$__skip = $false
			if ($scale.ScaleName -and ($__ex_names -contains ($scale.ScaleName.ToLower()))) { $__skip = $true }
			elseif ([string]$scale.ScaleCode -match '^\d+$' -and ($__ex_lanes -contains ('{0:D3}' -f ([int]$scale.ScaleCode)))) { $__skip = $true }
			if ($__skip) { continue }

			$ip = if ($scale.IPNetwork -and $scale.IPDevice) { "$($scale.IPNetwork)$($scale.IPDevice)" }
			else { "" }
			$displayName = "$($scale.ScaleName) [$ip]"
			$scaleObj = [PSCustomObject]@{
				ScaleCode   = $scale.ScaleCode
				ScaleName   = $scale.ScaleName
				IPAddress   = $ip
				Vendor	    = $scale.Vendor
				FullIP	    = $scale.FullIP
				IPNetwork   = $scale.IPNetwork
				IPDevice    = $scale.IPDevice
				ScaleBrand  = $scale.ScaleBrand
				DisplayName = $displayName
			}
			$scaleObj | Add-Member -MemberType ScriptMethod -Name ToString -Value { $this.DisplayName } -Force
			$clbScales.Items.Add($scaleObj) | Out-Null
		}
	}

	# ----- Backoffices Tab -----
	if ("Backoffice" -in $NodeTypes)
	{
		$tabBO = New-Object System.Windows.Forms.TabPage
		$tabBO.Text = "Backoffices"
		$clbBO = New-Object System.Windows.Forms.CheckedListBox
		$clbBO.Location = New-Object System.Drawing.Point(10, 10)
		$clbBO.Size = New-Object System.Drawing.Size(350, 270)
		$clbBO.CheckOnClick = $true
		$tabBO.Controls.Add($clbBO)
		$tabs.TabPages.Add($tabBO)
		$tabControls["Backoffices"] = $clbBO

		$boDict = if ($script:FunctionResults.ContainsKey('BackofficeNumToMachineName')) { $script:FunctionResults['BackofficeNumToMachineName'] }
		else { @{ } }
		$boLabels = $script:FunctionResults['BackofficeNumToLabel']
		$boPaths = $script:FunctionResults['BackofficeNumToPath']

		$seenBonumbers = @{ }
		foreach ($boNumKey in $boDict.Keys | Sort-Object)
		{
			if ($boNumKey -match '(\d{3})')
			{
				$bonum = $matches[1]

				# Skip excluded by machine name or BO number
				$__skip = $false
				$machineName = $boDict[$boNumKey]
				if ($machineName -and ($__ex_names -contains $machineName.ToLower())) { $__skip = $true }
				elseif ($__ex_lanes -contains $bonum) { $__skip = $true }
				if ($__skip) { continue }

				if (-not $seenBonumbers.ContainsKey($bonum))
				{
					$seenBonumbers[$bonum] = $true
					$label = $boLabels[$boNumKey]
					$path = $boPaths[$boNumKey]

					$obj = [PSCustomObject]@{
						BONumber    = $bonum
						MachineName = $machineName
						Label	    = $label
						Path	    = $path
						DisplayName = if ($machineName) { "$machineName ($bonum)" } else { "Unknown ($bonum)" }
					}
					$obj | Add-Member ScriptMethod ToString { $this.DisplayName } -Force
					$clbBO.Items.Add($obj) | Out-Null
				}
			}
		}
	}

	$btnSelectAll = New-Object System.Windows.Forms.Button
	$btnSelectAll.Location = New-Object System.Drawing.Point(20, 340)
	$btnSelectAll.Size = New-Object System.Drawing.Size(180, 32)
	$btnSelectAll.Text = "Select All"
	$btnSelectAll.BackColor = [System.Drawing.SystemColors]::Control

	$btnDeselectAll = New-Object System.Windows.Forms.Button
	$btnDeselectAll.Location = New-Object System.Drawing.Point(220, 340)
	$btnDeselectAll.Size = New-Object System.Drawing.Size(180, 32)
	$btnDeselectAll.Text = "Deselect All"
	$btnDeselectAll.BackColor = [System.Drawing.SystemColors]::Control

	$setBtnColor = {
		param ($btn,
			$state)
		switch ($state)
		{
			1 { $btn.BackColor = [System.Drawing.Color]::Yellow }
			2 { $btn.BackColor = [System.Drawing.Color]::LightGreen }
			Default { $btn.BackColor = [System.Drawing.SystemColors]::Control }
		}
	}
	&$setBtnColor $btnSelectAll 0
	&$setBtnColor $btnDeselectAll 0

	# --- SINGLE TAB SELECT ALL LOGIC ---
	if ($tabs.TabPages.Count -eq 1)
	{
		$clb = $tabControls[$tabs.TabPages[0].Text]
		$isAllChecked = {
			for ($i = 0; $i -lt $clb.Items.Count; $i++) { if (-not $clb.GetItemChecked($i)) { return $false } }
			return $clb.Items.Count -gt 0
		}
		$isAnyChecked = {
			for ($i = 0; $i -lt $clb.Items.Count; $i++) { if ($clb.GetItemChecked($i)) { return $true } }
			return $false
		}
		$btnSelectAll.Add_Click({
				$allChecked = & $isAllChecked
				if (-not $allChecked)
				{
					for ($i = 0; $i -lt $clb.Items.Count; $i++) { $clb.SetItemChecked($i, $true) }
					& $setBtnColor $btnSelectAll 2
				}
			})
		$btnDeselectAll.Add_Click({
				for ($i = 0; $i -lt $clb.Items.Count; $i++) { $clb.SetItemChecked($i, $false) }
				& $setBtnColor $btnSelectAll 0
				& $setBtnColor $btnDeselectAll 0
			})
		# (MouseUp / KeyUp only: ItemCheck fires before the state changes, and a sleep in it made
		#  Select All stall ~30 ms per item)
		foreach ($event in @("Add_MouseUp", "Add_KeyUp"))
		{
			$clb.$event.Invoke({
					$allChecked = & $isAllChecked
					$anyChecked = & $isAnyChecked
					if ($allChecked) { & $setBtnColor $btnSelectAll 2 }
					elseif ($anyChecked) { & $setBtnColor $btnSelectAll 1 }
					else { & $setBtnColor $btnSelectAll 0 }
				})
		}
	}
	else
	{
		# ---- NORMAL MULTI-TAB LOGIC ----
		$tabSelectState = @{ }
		$lastSelectTabIndex = $null
		$selectAllYellowTabIndex = $null

		$btnSelectAll.Add_Click({
				$tabName = $tabs.SelectedTab.Text
				$clb = $tabControls[$tabName]
				$tabIndex = $tabs.SelectedIndex
				$currentTabAllChecked = $true
				for ($i = 0; $i -lt $clb.Items.Count; $i++) { if (-not $clb.GetItemChecked($i)) { $currentTabAllChecked = $false; break } }
				$allTabsChecked = $true
				foreach ($clbTest in $tabControls.Values)
				{
					for ($i = 0; $i -lt $clbTest.Items.Count; $i++) { if (-not $clbTest.GetItemChecked($i)) { $allTabsChecked = $false; break } }
				}
				if ($allTabsChecked)
				{
					foreach ($k in $tabControls.Keys)
					{
						$tabIndex2 = -1
						for ($t = 0; $t -lt $tabs.TabPages.Count; $t++) { if ($tabs.TabPages[$t].Text -eq $k) { $tabIndex2 = $t; break } }
						if ($tabIndex2 -eq -1) { continue }
						$tabSelectState[$tabIndex2] = 0
					}
					$tabSelectState[$tabIndex] = 0
					$selectAllYellowTabIndex = $null
					&$setBtnColor $btnSelectAll 0
					return
				}
				if ($currentTabAllChecked -and -not $allTabsChecked)
				{
					foreach ($k in $tabControls.Keys)
					{
						$list = $tabControls[$k]
						for ($i = 0; $i -lt $list.Items.Count; $i++) { $list.SetItemChecked($i, $true) }
						$tabIndex2 = -1
						for ($t = 0; $t -lt $tabs.TabPages.Count; $t++) { if ($tabs.TabPages[$t].Text -eq $k) { $tabIndex2 = $t; break } }
						if ($tabIndex2 -eq -1) { continue }
						$tabSelectState[$tabIndex2] = 2
					}
					&$setBtnColor $btnSelectAll 2
					$selectAllYellowTabIndex = $null
					return
				}
				for ($i = 0; $i -lt $clb.Items.Count; $i++) { $clb.SetItemChecked($i, $true) }
				$tabSelectState[$tabIndex] = 1
				$lastSelectTabIndex = $tabIndex
				$selectAllYellowTabIndex = $tabIndex
				$allTabsChecked = $true
				foreach ($clbTest in $tabControls.Values)
				{
					for ($i = 0; $i -lt $clbTest.Items.Count; $i++) { if (-not $clbTest.GetItemChecked($i)) { $allTabsChecked = $false; break } }
				}
				if ($allTabsChecked) { & $setBtnColor $btnSelectAll 2; $selectAllYellowTabIndex = $null }
				else { & $setBtnColor $btnSelectAll 1 }
			})
		$btnDeselectAll.Add_Click({
				$tabName = $tabs.SelectedTab.Text
				$clb = $tabControls[$tabName]
				$tabIndex = $tabs.SelectedIndex
				$noneChecked = $true
				for ($i = 0; $i -lt $clb.Items.Count; $i++) { if ($clb.GetItemChecked($i)) { $noneChecked = $false; break } }
				if ($noneChecked)
				{
					$originalTab = $tabs.SelectedTab
					foreach ($k in $tabControls.Keys)
					{
						$tabIndex2 = -1
						for ($t = 0; $t -lt $tabs.TabPages.Count; $t++) { if ($tabs.TabPages[$t].Text -eq $k) { $tabIndex2 = $t; break } }
						if ($tabIndex2 -eq -1) { continue }
						$tabs.SelectedTab = $tabs.TabPages[$tabIndex2]
						$list = $tabControls[$k]
						for ($i = 0; $i -lt $list.Items.Count; $i++) { $list.SetItemChecked($i, $false) }
						$tabSelectState[$tabIndex2] = 0
						$list.Refresh()
					}
					$tabs.SelectedTab = $originalTab
				}
				else
				{
					for ($i = 0; $i -lt $clb.Items.Count; $i++) { $clb.SetItemChecked($i, $false) }
					$tabSelectState[$tabIndex] = 0
				}
				&$setBtnColor $btnDeselectAll 0
				&$setBtnColor $btnSelectAll 0
				$selectAllYellowTabIndex = $null
			})
		foreach ($clb in $tabControls.Values)
		{
			$clb.Add_MouseUp({
					$allTabsChecked = $true
					foreach ($clbTest in $tabControls.Values)
					{
						for ($i = 0; $i -lt $clbTest.Items.Count; $i++) { if (-not $clbTest.GetItemChecked($i)) { $allTabsChecked = $false; break } }
					}
					if ($allTabsChecked) { & $setBtnColor $btnSelectAll 2; $selectAllYellowTabIndex = $null }
					else
					{
						$tabIndex = $tabs.SelectedIndex
						$clbLocal = $tabControls[$tabs.SelectedTab.Text]
						$allChecked = $true
						for ($i = 0; $i -lt $clbLocal.Items.Count; $i++) { if (-not $clbLocal.GetItemChecked($i)) { $allChecked = $false; break } }
						if ($allChecked -and $clbLocal.Items.Count -gt 0) { & $setBtnColor $btnSelectAll 1; $selectAllYellowTabIndex = $tabIndex }
						else { & $setBtnColor $btnSelectAll 0; $selectAllYellowTabIndex = $null }
					}
				})
			$clb.Add_KeyUp({
					$allTabsChecked = $true
					foreach ($clbTest in $tabControls.Values)
					{
						for ($i = 0; $i -lt $clbTest.Items.Count; $i++) { if (-not $clbTest.GetItemChecked($i)) { $allTabsChecked = $false; break } }
					}
					if ($allTabsChecked) { & $setBtnColor $btnSelectAll 2; $selectAllYellowTabIndex = $null }
					else
					{
						$tabIndex = $tabs.SelectedIndex
						$clbLocal = $tabControls[$tabs.SelectedTab.Text]
						$allChecked = $true
						for ($i = 0; $i -lt $clbLocal.Items.Count; $i++) { if (-not $clbLocal.GetItemChecked($i)) { $allChecked = $false; break } }
						if ($allChecked -and $clbLocal.Items.Count -gt 0) { & $setBtnColor $btnSelectAll 1; $selectAllYellowTabIndex = $tabIndex }
						else { & $setBtnColor $btnSelectAll 0; $selectAllYellowTabIndex = $null }
					}
				})
		}
		$tabs.add_SelectedIndexChanged({
				$tabIndex = $tabs.SelectedIndex
				$clb = $tabControls[$tabs.SelectedTab.Text]
				$allTabsChecked = $true
				foreach ($clbTest in $tabControls.Values)
				{
					for ($i = 0; $i -lt $clbTest.Items.Count; $i++) { if (-not $clbTest.GetItemChecked($i)) { $allTabsChecked = $false; break } }
				}
				if ($allTabsChecked) { & $setBtnColor $btnSelectAll 2; $selectAllYellowTabIndex = $null }
				else
				{
					$allChecked = $true
					for ($i = 0; $i -lt $clb.Items.Count; $i++) { if (-not $clb.GetItemChecked($i)) { $allChecked = $false; break } }
					if ($allChecked -and $clb.Items.Count -gt 0) { & $setBtnColor $btnSelectAll 1; $selectAllYellowTabIndex = $tabIndex }
					else { & $setBtnColor $btnSelectAll 0; $selectAllYellowTabIndex = $null }
				}
				&$setBtnColor $btnDeselectAll 0
			})
	}

	$form.Controls.Add($btnSelectAll)
	$form.Controls.Add($btnDeselectAll)

	# OK Button
	$btnOK = New-Object System.Windows.Forms.Button
	$btnOK.Text = "OK"
	$btnOK.Location = New-Object System.Drawing.Point(60, 380)
	$btnOK.Size = New-Object System.Drawing.Size(140, 32)
	$btnOK.DialogResult = [System.Windows.Forms.DialogResult]::OK
	$form.AcceptButton = $btnOK
	$form.Controls.Add($btnOK)

	# Cancel Button
	$btnCancel = New-Object System.Windows.Forms.Button
	$btnCancel.Text = "Cancel"
	$btnCancel.Location = New-Object System.Drawing.Point(220, 380)
	$btnCancel.Size = New-Object System.Drawing.Size(140, 32)
	$btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
	$form.CancelButton = $btnCancel
	$form.Controls.Add($btnCancel)
	if ($Apply_Modern_Popup_Style) { & $Apply_Modern_Popup_Style $form }

	# ----- Show form & collect selections -----
	$dialogResult = $form.ShowDialog()
	if ($dialogResult -ne [System.Windows.Forms.DialogResult]::OK) { return $null }

	$result = @{ }
	if ("Lane" -in $NodeTypes)
	{
		$clb = $tabControls["Lanes"]
		$selectedLaneNums = @()
		for ($i = 0; $i -lt $clb.Items.Count; $i++)
		{
			if ($clb.GetItemChecked($i))
			{
				$item = $clb.Items[$i]
				if ($item.PSObject.Properties['LaneNumber'] -and $item.LaneNumber)
				{
					$selectedLaneNums += $item.LaneNumber
				}
			}
		}
		$result.Lanes = $selectedLaneNums
	}
	if ("Scale" -in $NodeTypes)
	{
		$clb = $tabControls["Scales"]
		$selectedScaleCodes = @()
		for ($i = 0; $i -lt $clb.Items.Count; $i++)
		{
			if ($clb.GetItemChecked($i))
			{
				$item = $clb.Items[$i]
				if ($item.PSObject.Properties['ScaleCode'] -and $item.ScaleCode)
				{
					$selectedScaleCodes += "$($item.ScaleCode)"
				}
			}
		}
		$result.Scales = $selectedScaleCodes
	}
	if ("Backoffice" -in $NodeTypes)
	{
		$clb = $tabControls["Backoffices"]
		$selectedBONums = @()
		for ($i = 0; $i -lt $clb.Items.Count; $i++)
		{
			if ($clb.GetItemChecked($i))
			{
				$item = $clb.Items[$i]
				if ($item.PSObject.Properties['BONumber'] -and $item.BONumber)
				{
					$selectedBONums += $item.BONumber
				}
			}
		}
		$result.Backoffices = $selectedBONums
	}

	# Basic validation
	if ($result.Keys.Count -eq 0 -or ($result.Values | ForEach-Object { $_.Count } | Measure-Object -Sum).Sum -eq 0)
	{
		# [void]: the MessageBox result ('OK') must not become this function's return value
		[void][System.Windows.Forms.MessageBox]::Show("No nodes selected.", "Information",
			[System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
		Remove-Variable -Name __laneLimitWarned -Scope Script -ErrorAction SilentlyContinue
		return $null
	}

	Remove-Variable -Name __laneLimitWarned -Scope Script -ErrorAction SilentlyContinue
	return $result
}

# ===================================================================================================
#                              FUNCTION: Show_Section_Selection_Form
# ---------------------------------------------------------------------------------------------------
# Description:
#   Dialog with a check list of SQL script sections (Process_Server / lane maintenance);
#   returns the checked section names. Thin wrapper over Show_CheckList_Form.
#
# Parameters:
#   - SectionNames  [string[]] (required): section names to list
#
# Returns:
#   Array of checked section names ($null when cancelled).
# ===================================================================================================

function Show_Section_Selection_Form
{
	param (
		[Parameter(Mandatory = $true)]
		[string[]]$SectionNames
	)

	return Show_CheckList_Form -Title 'Select SQL Sections' -Prompt 'Check the sections you want to run, then click OK.' -Items $SectionNames -Width 500 -Height 280
}

# ===================================================================================================
#                              FUNCTION: Show_Table_Selection_Form
# ---------------------------------------------------------------------------------------------------
# Description:
#   Dialog listing the distinct tables from Get_Table_Aliases rows (sorted) for Pump_Tables;
#   returns the checked table names (with _TAB). Thin wrapper over Show_CheckList_Form.
#
# Parameters:
#   - AliasResults  [System.Collections.ArrayList] (required): rows with a .Table property
#
# Returns:
#   Array of checked table names ($null when cancelled).
# ===================================================================================================

function Show_Table_Selection_Form
{
	param (
		[Parameter(Mandatory = $true)]
		[System.Collections.ArrayList]$AliasResults
	)

	$tables = @($AliasResults | Select-Object -ExpandProperty Table -Unique | Sort-Object)
	return Show_CheckList_Form -Title 'Select Tables to Process' -Prompt 'Please select the tables you want to pump:' -Items $tables -Width 410 -Height 400
}

# ===================================================================================================
#                              FUNCTION: Configure_System_Settings
# ---------------------------------------------------------------------------------------------------
# Description:
#   Tunes the local PC for POS use: High Performance power plan, sleep disabled, minimum
#   processor performance at 100%, monitor off after 15 minutes on AC, several services set
#   to Automatic and started, and visual settings (thumbnails, font smoothing, ClearType).
#   Restarts Explorer so the visual settings apply.
#
# Writes:
#   - local power plan, service startup types and visual settings
#
# Notes:
#   - Desktop organizing is a separate function: Organize_Desktop_Items.
# ===================================================================================================

function Configure_System_Settings
{
	[CmdletBinding()]
	param ()

	Write_Log "`r`n==================== Starting Configure_System_Settings ====================`r`n" "blue"

	try
	{
		# ===========================================
		# 1. Power settings
		# ===========================================
		Write_Log "`r`nConfiguring power plan and performance settings..." "blue"

		# powercfg is an external program: failures show up in the exit code, never as an
		# exception (before v2.7.0 every step here logged success regardless)
		$powercfg = {
			param ([string]$What, [string[]]$PcArgs)
			$out = & powercfg.exe @PcArgs 2>&1
			if ($LASTEXITCODE -eq 0) { Write_Log $What "green"; return $true }
			Write_Log ("Failed: {0} (powercfg {1}: {2})" -f $What, ($PcArgs -join ' '), (($out | Out-String).Trim())) "red"
			return $false
		}

		# High Performance plan; on systems where it is hidden, restore it from its template first
		$highPerfGUID = "8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c"
		$null = & powercfg.exe /query $highPerfGUID 2>&1
		if ($LASTEXITCODE -ne 0) { $null = & powercfg.exe -duplicatescheme $highPerfGUID $highPerfGUID 2>&1 }
		$null = & $powercfg "Power plan set to High Performance." @('/s', $highPerfGUID)

		$null = & $powercfg "System sleep disabled (AC)." @('/change', 'standby-timeout-ac', '0')
		$null = & $powercfg "System sleep disabled (DC)." @('/change', 'standby-timeout-dc', '0')

		# Minimum processor state 100% (SUB_PROCESSOR / PROCTHROTTLEMIN) on the High Performance plan
		$subProcessor = "54533251-82be-4824-96c1-47b60b740d00"
		$procThrottleMin = "893dee8e-2bef-41e0-89c6-b55d0929964c"
		$null = & $powercfg "Minimum processor performance 100% (AC)." @('/setacvalueindex', $highPerfGUID, $subProcessor, $procThrottleMin, '100')
		$null = & $powercfg "Minimum processor performance 100% (DC)." @('/setdcvalueindex', $highPerfGUID, $subProcessor, $procThrottleMin, '100')
		$null = & $powercfg "High Performance plan re-activated." @('/setactive', $highPerfGUID)

		$null = & $powercfg "Monitor timeout (AC) set to 15 minutes." @('/change', 'monitor-timeout-ac', '15')
		Write_Log "Power and performance settings complete." "green"

		# ===========================================
		# 2. Configure Services
		# ===========================================
		Write_Log "`r`nConfiguring services to start automatically..." "blue"

		$servicesToConfigure = @("fdPHost", "FDResPub", "SSDPSRV", "upnphost")
		foreach ($service in $servicesToConfigure)
		{
			try
			{
				Set-Service -Name $service -StartupType Automatic -ErrorAction Stop
				Write_Log "Set service '$service' to Automatic." "green"

				$svc = Get-Service -Name $service -ErrorAction Stop
				if ($svc.Status -ne 'Running')
				{
					Start-Service -Name $service -ErrorAction Stop
					Write_Log "Started service '$service'." "green"
				}
				else
				{
					Write_Log "Service '$service' is already running." "cyan"
				}
			}
			catch
			{
				Write_Log "Failed to configure service '$service'. Error: $_" "red"
			}
		}

		Write_Log "Service configuration complete." "green"

		# ===========================================
		# 3. Configure Visual Settings
		# ===========================================
		Write_Log "`r`nConfiguring visual settings..." "blue"

		try
		{
			# Show thumbnails (IconsOnly = 0)
			Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" `
							 -Name "IconsOnly" -Value 0 -Type DWord -ErrorAction Stop
			Write_Log "Enabled 'Show thumbnails instead of icons'." "green"
		}
		catch
		{
			Write_Log "Failed to enable thumbnails. Error: $_" "red"
		}

		try
		{
			# Font smoothing + ClearType
			Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "FontSmoothing" -Value "2" -Type String -ErrorAction Stop
			Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "FontSmoothingType" -Value 2 -Type DWord -ErrorAction Stop
			Write_Log "Enabled 'Smooth edges of screen fonts' (ClearType)." "green"
		}
		catch
		{
			Write_Log "Failed to enable font smoothing. Error: $_" "red"
		}

		# Restart Explorer to apply visual tweaks (kept here since it's visual-settings-related)
		Write_Log "Restarting Explorer to apply changes..." "yellow"
		try
		{
			Stop-Process -Name explorer -Force
			Write_Log "Explorer restarted." "green"
		}
		catch
		{
			Write_Log "Explorer restart may already be complete or not required. Info: $_" "cyan"
		}

		Write_Log "All system configurations have been applied." "green"
		Write_Log "`r`n==================== Configure_System_Settings Completed ====================`r`n" "blue"
	}
	catch
	{
		Write_Log "An unexpected error occurred in Configure_System_Settings: $_" "red"
	}
}

# ===================================================================================================
#                              FUNCTION: Manage_Sa_Account
# ---------------------------------------------------------------------------------------------------
# Description:
#   Form with Enable/Disable buttons for the 'sa' login on the store SQL Server. Enable also
#   sets the sa password to the standard support password ($script:BackupSqlPass). The button
#   for the current state is greyed out (read from sys.sql_logins); the form closes after a
#   successful change.
#
# Parameters:
#   (none)
#
# Variables:
#   - $script:FunctionResults: SqlModuleName, ConnectionString, DBSERVER
#   - $script:BackupSqlPass: the password set when enabling sa
#
# Notes:
#   - Needs sysadmin rights on the instance. Uses Invoke-Sqlcmd when a SQL module is
#     available, else the built-in SqlClient.
# ===================================================================================================

function Manage_Sa_Account
{
	[CmdletBinding()]
	param ()

	Write_Log "`r`n==================== Starting Manage_Sa_Account Function ====================`r`n" "blue"

	Add-Type -AssemblyName System.Windows.Forms
	Add-Type -AssemblyName System.Drawing

	$SqlModuleName = $script:FunctionResults['SqlModuleName']
	$ConnectionString = $script:FunctionResults['ConnectionString']
	$serverInstance = $script:FunctionResults['DBSERVER']
	if ((-not $ConnectionString -or $ConnectionString -eq 'N/A') -and (-not $serverInstance -or $serverInstance -eq 'N/A'))
	{
		Write_Log "No SQL server / connection string known for this store - cannot manage 'sa'." "red"
		return
	}

	$InvokeSqlCmd = $null
	if ($SqlModuleName -and $SqlModuleName -ne "None")
	{
		try
		{
			Import-Module $SqlModuleName -ErrorAction Stop
			$InvokeSqlCmd = Get-Command Invoke-Sqlcmd -Module $SqlModuleName -ErrorAction Stop
		}
		catch { $InvokeSqlCmd = $null }
	}
	$supportsConnectionString = ($InvokeSqlCmd -and $InvokeSqlCmd.Parameters.ContainsKey('ConnectionString'))

	# Run one statement against the instance; returns rows (Invoke-Sqlcmd or SqlClient)
	$runSql = {
		param ([string]$Query)
		if ($InvokeSqlCmd)
		{
			if ($supportsConnectionString) { return & $InvokeSqlCmd -ConnectionString $ConnectionString -Query $Query -ErrorAction Stop }
			return & $InvokeSqlCmd -ServerInstance $serverInstance -Database master -Query $Query -ErrorAction Stop
		}
		$cs = if ($ConnectionString -and $ConnectionString -ne 'N/A') { $ConnectionString } else { "Server=$serverInstance;Database=master;Integrated Security=True;TrustServerCertificate=True;" }
		$cn = New-Object System.Data.SqlClient.SqlConnection $cs
		try
		{
			$cn.Open()
			$cmd = $cn.CreateCommand()
			$cmd.CommandText = $Query
			$dt = New-Object System.Data.DataTable
			[void](New-Object System.Data.SqlClient.SqlDataAdapter $cmd).Fill($dt)
			return , $dt
		}
		finally { $cn.Dispose() }
	}
	$getSaEnabled = {
		$rows = @(& $runSql "SELECT is_disabled FROM sys.sql_logins WHERE name = 'sa'" | ForEach-Object { $_ })
		if ($rows.Count -eq 0) { return $null }
		return ([int]$rows[0].is_disabled -eq 0)
	}

	$form = New-Object System.Windows.Forms.Form
	$form.Text = "Manage SQL 'sa' Account"
	$form.Size = New-Object System.Drawing.Size(300, 150)
	$form.StartPosition = "CenterScreen"
	$form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
	$form.MaximizeBox = $false
	$form.MinimizeBox = $false

	$btnEnable = New-Object System.Windows.Forms.Button
	$btnEnable.Text = "Enable 'sa'"
	$btnEnable.Location = New-Object System.Drawing.Point(50, 30)
	$btnEnable.Size = New-Object System.Drawing.Size(200, 30)
	$form.Controls.Add($btnEnable)

	$btnDisable = New-Object System.Windows.Forms.Button
	$btnDisable.Text = "Disable 'sa'"
	$btnDisable.Location = New-Object System.Drawing.Point(50, 70)
	$btnDisable.Size = New-Object System.Drawing.Size(200, 30)
	$form.Controls.Add($btnDisable)

	# --- Current state ---
	$isEnabled = $false
	try
	{
		$state = & $getSaEnabled
		if ($null -eq $state) { Write_Log "'sa' account not found." "red" }
		else { $isEnabled = $state }
	}
	catch { Write_Log "Error checking 'sa' status: $_" "red" }
	$btnEnable.Enabled = -not $isEnabled
	$btnDisable.Enabled = $isEnabled
	if ($isEnabled) { Write_Log "'sa' is currently enabled. Enable button greyed out." "yellow" }
	else { Write_Log "'sa' is currently disabled. Disable button greyed out." "yellow" }

	# --- Enable / Disable ---
	$apply = {
		param ([bool]$Enable)
		$verb = if ($Enable) { 'enable' } else { 'disable' }
		Write_Log "$((Get-Culture).TextInfo.ToTitleCase($verb)) button clicked. Attempting to $verb 'sa'..." "blue"
		try
		{
			if ($Enable)
			{
				$saPassword = ([string]$script:BackupSqlPass).Replace("'", "''")
				$null = & $runSql "ALTER LOGIN sa ENABLE; ALTER LOGIN sa WITH PASSWORD = '$saPassword';"
				Write_Log "'sa' account enabled and password set successfully." "green"
			}
			else
			{
				$null = & $runSql "ALTER LOGIN sa DISABLE;"
				Write_Log "'sa' account disabled successfully." "green"
			}
			$form.Close()
		}
		catch { Write_Log "Error trying to $verb 'sa' account: $_" "red" }
	}
	$btnEnable.Add_Click({ & $apply $true })
	$btnDisable.Add_Click({ & $apply $false })

	[void]$form.ShowDialog()
	$form.Dispose()
	Write_Log "`r`n==================== Manage_Sa_Account Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Organize_Desktop_Items
# ---------------------------------------------------------------------------------------------------
# Description:
#   Moves non-system, non-excluded items from the current user's Desktop into a single
#   "Unorganized Items" folder. Keeps common system shortcuts, the TBS / MiniGhost launchers
#   (any version) and the Lanes / Scales / BackOffices folders; never overwrites an item that
#   is already in the target folder (the moved one gets a ' (2)' style suffix).
#
# Parameters:
#   - UnorganizedFolderName [string]: target folder on the Desktop (default "Unorganized Items")
#   - AdditionalExclusions  [string[]]: extra item names to leave on the Desktop
#
# Writes:
#   - moves files/folders under the user Desktop into the Unorganized folder
# ===================================================================================================

function Organize_Desktop_Items
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $false)]
		[string]$UnorganizedFolderName = "Unorganized Items",
		[Parameter(Mandatory = $false)]
		[string[]]$AdditionalExclusions
	)

	Write_Log "`r`n==================== Starting Organize_Desktop_Items ====================`r`n" "blue"

	try
	{
		# -- Resolve Desktop path
		$DesktopPath = [Environment]::GetFolderPath("Desktop")

		# -- Compute the destination folder path
		$UnorganizedFolder = Join-Path -Path $DesktopPath -ChildPath $UnorganizedFolderName

		# -- The running tool itself (.ps1 / .exe), when it lives on the Desktop
		$scriptName = if ($script:LaunchEntryPath) { [System.IO.Path]::GetFileName([string]$script:LaunchEntryPath) } else { "TBS_Maintenance_Script.exe" }
		# Launchers of any version (TBS_Maintenance_Script_V2.6.9.exe, MiniGhost_V38.ps1, ...)
		$keepPatterns = @('TBS_Maintenance_Script*', 'TBS_Maintenace_Script*', 'Execute(TBS*', 'MiniGhost*', 'Execute(MiniGhost*')

		# -- Known system/launcher items to preserve on Desktop (case-insensitive match by name)
		$systemIcons = @(
			"This PC.lnk", "Network.lnk", "Control Panel.lnk", "Recycle Bin.lnk", "User's Files.lnk",
			"Execute(TBS_Maintenance_Script).bat", "Execute(MiniGhost).bat",
			"TBS_Maintenance_Script.exe", "MiniGhost.exe",
			$scriptName,
			"desktop.ini"
		)

		# -- Default excluded folders that must remain on Desktop
		$defaultExcludedFolders = @("Lanes", "Scales", "BackOffices", $UnorganizedFolderName)

		# -- Merge additional exclusions if provided
		$excludedSet = New-Object System.Collections.Generic.HashSet[string] ([StringComparer]::OrdinalIgnoreCase)
		foreach ($n in $systemIcons) { [void]$excludedSet.Add($n) }
		foreach ($n in $defaultExcludedFolders) { [void]$excludedSet.Add($n) }
		if ($AdditionalExclusions)
		{
			foreach ($n in $AdditionalExclusions) { if ($n) { [void]$excludedSet.Add($n) } }
		}

		# -- Ensure the target "Unorganized" folder exists
		if (-not (Test-Path -LiteralPath $UnorganizedFolder))
		{
			New-Item -ItemType Directory -Path $UnorganizedFolder | Out-Null
			Write_Log "Created folder: $UnorganizedFolder" "green"
		}
		else
		{
			Write_Log "Folder already exists: $UnorganizedFolder" "cyan"
		}

		# -- Enumerate Desktop items; keep both files and folders.
		#    Move everything except explicit exclusions and Windows system-managed filesystem items.
		$desktopItems = @(Get-ChildItem -LiteralPath $DesktopPath -Force |
			Where-Object {
				$name = $_.Name
				# explicitly excluded names, launcher patterns, and System items (desktop.ini)
				-not $excludedSet.Contains($name) -and
				-not @($keepPatterns | Where-Object { $name -like $_ }).Count -and
				-not ($_.Attributes -band [System.IO.FileAttributes]::System)
			})

		# -- Move everything else into the Unorganized folder (never overwrite: "name (2).ext")
		foreach ($item in $desktopItems)
		{
			try
			{
				$target = Join-Path $UnorganizedFolder $item.Name
				$n = 2
				while (Test-Path -LiteralPath $target)
				{
					$base = if ($item.PSIsContainer) { $item.Name } else { [System.IO.Path]::GetFileNameWithoutExtension($item.Name) }
					$ext = if ($item.PSIsContainer) { '' } else { $item.Extension }
					$target = Join-Path $UnorganizedFolder ("{0} ({1}){2}" -f $base, $n, $ext)
					$n++
				}
				Move-Item -LiteralPath $item.FullName -Destination $target -ErrorAction Stop
				Write_Log "Moved item: $($item.Name)" "green"
			}
			catch
			{
				Write_Log "Failed to move item: $($item.Name). Error: $_" "red"
			}
		}

		Write_Log "Desktop organization complete." "green"
		Write_Log "`r`n==================== Organize_Desktop_Items Completed ====================" "blue"
	}
	catch
	{
		Write_Log "Unexpected error in Organize_Desktop_Items: $_" "red"
	}
}

# ===================================================================================================
#                              FUNCTION: Process_Server
# ---------------------------------------------------------------------------------------------------
# Description:
#   Runs the server (store) SQL maintenance: takes the script from $script:ServerSQLScript
#   (generated on demand) or a file, optionally lets the user pick sections, runs each section
#   once - Invoke-Sqlcmd when a SQL module is available, else SqlClient split on GO lines - and
#   logs which sections failed.
#
# Parameters:
#   - StoresqlFilePath  [string]: SQL file to run instead of the script variable
#   - PromptForSections [switch]: show the section selection dialog first
#
# Variables:
#   - $script:ServerSQLScript: default SQL script text
#   - $script:FunctionResults['DBNAME'] / ['DBSERVER']: target database/server
# ===================================================================================================

function Process_Server
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $false)]
		[string]$StoresqlFilePath,
		[Parameter(Mandatory = $false)]
		[switch]$PromptForSections
	)

	# ------------------------------------------------------------------------------------------------
	# Banner: Start
	# ------------------------------------------------------------------------------------------------
	Write_Log "`r`n==================== Starting Server Database Maintenance ====================`r`n" "blue"

	# ------------------------------------------------------------------------------------------------
	# Variables and settings
	# ------------------------------------------------------------------------------------------------
	$sqlScript = $script:ServerSQLScript
	$dbName = $script:FunctionResults['DBNAME']
	$server = $script:FunctionResults['DBSERVER']

	# ------------------------------------------------------------------------------------------------
	# Load SQL script content. Primary source is the in-memory $script:ServerSQLScript
	# variable, set by Generate_SQL_Scripts during warmup. If it is not ready yet (the
	# user acted before the 'Generating SQL scripts' warmup step ran), generate it on
	# demand - pure CPU (~2 ms) and needs only the already-resolved store/DB info. The
	# file fallback below is only for an explicitly provided standalone .sqi.
	# ------------------------------------------------------------------------------------------------
	if ([string]::IsNullOrWhiteSpace($sqlScript))
	{
		try { Generate_SQL_Scripts -StoreNumber $script:StoreNumber | Out-Null } catch { }
		$sqlScript = $script:ServerSQLScript
	}

	if (-not [string]::IsNullOrWhiteSpace($sqlScript))
	{
		Write_Log "Executing SQL script from variable..." "blue"
	}
	elseif ($StoresqlFilePath)
	{
		if (-not (Test-Path $StoresqlFilePath))
		{
			Write_Log "SQL file not found: $StoresqlFilePath" "red"
			return
		}
		Write_Log "Executing SQL file: $StoresqlFilePath" "blue"
		try
		{
			$sqlScript = Get-Content -Path $StoresqlFilePath -Raw -ErrorAction Stop
		}
		catch
		{
			Write_Log "Failed to read SQL file: $_" "red"
			return
		}
	}
	else
	{
		Write_Log "No SQL script content or file path provided." "red"
		return
	}

	# ------------------------------------------------------------------------------------------------
	# Parse SQL sections: each "/* Name */" comment starts a section
	# ------------------------------------------------------------------------------------------------
	$sectionPattern = '(?s)/\*\s*(?<SectionName>[^*/]+?)\s*\*/\s*(?<SQLCommands>(?:.(?!/\*)|.)*?)(?=(/\*|$))'
	$sectionMatches = [regex]::Matches($sqlScript, $sectionPattern)
	if ($sectionMatches.Count -eq 0)
	{
		Write_Log "No SQL sections found to execute." "red"
		return
	}

	$SectionsToRun = $null
	if ($PromptForSections)
	{
		$allSectionNames = @($sectionMatches | ForEach-Object { $_.Groups['SectionName'].Value.Trim() })
		$SectionsToRun = Show_Section_Selection_Form -SectionNames $allSectionNames
		if (-not $SectionsToRun -or @($SectionsToRun).Count -eq 0)
		{
			Write_Log "No sections selected or form was canceled. Aborting execution." "yellow"
			return
		}
	}
	$useSpecificSections = $SectionsToRun -and @($SectionsToRun).Count -gt 0

	# ------------------------------------------------------------------------------------------------
	# How to run SQL: Invoke-Sqlcmd from the detected module, else the built-in SqlClient
	# (which does not understand GO - the sections are split into batches on GO lines)
	# ------------------------------------------------------------------------------------------------
	$ConnectionString = $script:FunctionResults['ConnectionString']
	$SqlModuleName = $script:FunctionResults['SqlModuleName']
	if (-not $ConnectionString -or -not $server -or -not $dbName)
	{
		Write_Log "DB server, DB name, or connection string not found. Cannot execute SQL script." "red"
		return
	}

	$InvokeSqlCmd = $null
	if ($SqlModuleName -and $SqlModuleName -ne "None")
	{
		try
		{
			Import-Module $SqlModuleName -ErrorAction Stop
			$InvokeSqlCmd = Get-Command Invoke-Sqlcmd -Module $SqlModuleName -ErrorAction Stop
		}
		catch
		{
			Write_Log "SQL module '$SqlModuleName' could not be loaded ($($_.Exception.Message)) - using the built-in SQL client." "yellow"
			$InvokeSqlCmd = $null
		}
	}
	else
	{
		Write_Log "No SQL PowerShell module - using the built-in SQL client." "yellow"
	}
	$supportsConnectionString = ($InvokeSqlCmd -and $InvokeSqlCmd.Parameters.ContainsKey('ConnectionString'))

	$runSection = {
		param ([string]$Sql)
		if ($InvokeSqlCmd)
		{
			if ($supportsConnectionString) { $null = & $InvokeSqlCmd -ConnectionString $ConnectionString -Query $Sql -ErrorAction Stop -QueryTimeout 0 }
			else { $null = & $InvokeSqlCmd -ServerInstance $server -Database $dbName -Query $Sql -ErrorAction Stop -QueryTimeout 0 }
			return
		}
		$cn = New-Object System.Data.SqlClient.SqlConnection $ConnectionString
		try
		{
			$cn.Open()
			foreach ($batch in ([regex]::Split($Sql, '(?im)^\s*GO\s*$')))
			{
				if ([string]::IsNullOrWhiteSpace($batch)) { continue }
				$cmd = $cn.CreateCommand()
				$cmd.CommandText = $batch
				$cmd.CommandTimeout = 0
				$null = $cmd.ExecuteNonQuery()
			}
		}
		finally { $cn.Dispose() }
	}

	# ------------------------------------------------------------------------------------------------
	# Execute each section once, in order
	# ------------------------------------------------------------------------------------------------
	$failedSections = @()
	foreach ($match in $sectionMatches)
	{
		$sectionName = $match.Groups['SectionName'].Value.Trim()
		$sqlCommands = $match.Groups['SQLCommands'].Value.Trim()

		if ($useSpecificSections -and ($SectionsToRun -notcontains $sectionName)) { continue }
		if ([string]::IsNullOrWhiteSpace($sqlCommands))
		{
			Write_Log "Section '$sectionName' has no commands. Skipping..." "yellow"
			continue
		}

		Write_Log "`r`nExecuting section: '$sectionName'" "blue"
		Write_Log "--------------------------------------------------------------------------------"
		Write_Log "$sqlCommands" "orange"
		Write_Log "--------------------------------------------------------------------------------"

		try
		{
			& $runSection $sqlCommands
			Write_Log "Section '$sectionName' executed successfully." "green"
		}
		catch
		{
			Write_Log "Error executing section '$sectionName': $_" "red"
			$failedSections += $sectionName
		}
	}
	# ------------------------------------------------------------------------------------------------
	# Completion summary
	# ------------------------------------------------------------------------------------------------
	if ($failedSections.Count -eq 0)
	{
		Write_Log "`r`nAll SQL sections executed successfully." "green"
	}
	else
	{
		Write_Log "The following sections failed: $($failedSections -join ', ')" "red"
	}

	Write_Log "`r`n==================== Completed Server Database Maintenance ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Repair_Windows
# ---------------------------------------------------------------------------------------------------
# Description:
#   Local Windows repair suite with a confirmation prompt and a checkbox form to pick the
#   operations: Defender update + full scan, DISM, SFC, disk cleanup, drive optimization
#   (SSD trim / HDD defrag) and scheduled Check Disk. Logs progress after each step.
#
# Writes:
#   - local system state (Defender, DISM, SFC, cleanup, drive optimization, scheduled chkdsk)
# ===================================================================================================

function Repair_Windows
{
	[CmdletBinding()]
	param ()

	Write_Log "`r`n==================== Starting Repair_Windows Function ====================`r`n" "blue"

	# Import GUI assemblies if needed
	Add-Type -AssemblyName System.Windows.Forms
	Add-Type -AssemblyName System.Drawing

	# Confirm user intent
	$confirmationResult = [System.Windows.Forms.MessageBox]::Show(
		"The Windows repair process will take a long time and make significant changes to your system. Do you want to proceed?",
		"Confirmation Required",
		[System.Windows.Forms.MessageBoxButtons]::YesNo,
		[System.Windows.Forms.MessageBoxIcon]::Warning
	)
	if ($confirmationResult -ne [System.Windows.Forms.DialogResult]::Yes)
	{
		Write_Log "Windows repair process cancelled by the user." "yellow"
		return
	}

	Write_Log "Starting Windows repair process. This might take a while, please wait..." "blue"

	# Create the Repair Options Form
	$repairForm = New-Object System.Windows.Forms.Form
	$repairForm.Text = "Select Repair Operations"
	$repairForm.Size = New-Object System.Drawing.Size(400, 380)
	$repairForm.StartPosition = "CenterScreen"
	$repairForm.FormBorderStyle = 'FixedDialog'
	$repairForm.MaximizeBox = $false
	$repairForm.MinimizeBox = $false
	$repairForm.ShowInTaskbar = $false

	# Operation Checkboxes (with correct .Location and .Size types)
	$checkboxes = @()

	$cb1 = New-Object System.Windows.Forms.CheckBox
	$cb1.Text = "Windows Defender Update and Scan"
	$cb1.Location = [System.Drawing.Point]::new(20, 20)
	$cb1.Size = [System.Drawing.Size]::new(350, 25)
	$checkboxes += $cb1

	$cb2 = New-Object System.Windows.Forms.CheckBox
	$cb2.Text = "Run DISM Commands"
	$cb2.Location = [System.Drawing.Point]::new(20, 60)
	$cb2.Size = [System.Drawing.Size]::new(350, 25)
	$checkboxes += $cb2

	$cb3 = New-Object System.Windows.Forms.CheckBox
	$cb3.Text = "Run System File Checker (SFC)"
	$cb3.Location = [System.Drawing.Point]::new(20, 100)
	$cb3.Size = [System.Drawing.Size]::new(350, 25)
	$checkboxes += $cb3

	$cb4 = New-Object System.Windows.Forms.CheckBox
	$cb4.Text = "Disk Cleanup"
	$cb4.Location = [System.Drawing.Point]::new(20, 140)
	$cb4.Size = [System.Drawing.Size]::new(350, 25)
	$checkboxes += $cb4

	$cb5 = New-Object System.Windows.Forms.CheckBox
	$cb5.Text = "Optimize Drives"
	$cb5.Location = [System.Drawing.Point]::new(20, 180)
	$cb5.Size = [System.Drawing.Size]::new(350, 25)
	$checkboxes += $cb5

	$cb6 = New-Object System.Windows.Forms.CheckBox
	$cb6.Text = "Schedule Check Disk"
	$cb6.Location = [System.Drawing.Point]::new(20, 220)
	$cb6.Size = [System.Drawing.Size]::new(350, 25)
	$checkboxes += $cb6

	foreach ($cb in $checkboxes) { $repairForm.Controls.Add($cb) }

	# "Select All" checkbox
	$cbAll = New-Object System.Windows.Forms.CheckBox
	$cbAll.Text = "Select All"
	$cbAll.Location = [System.Drawing.Point]::new(20, 260)
	$cbAll.Size = [System.Drawing.Size]::new(350, 25)
	$cbAll.Add_CheckedChanged({
			foreach ($cb in $checkboxes) { $cb.Checked = $cbAll.Checked }
		})
	$repairForm.Controls.Add($cbAll)

	# Enable/Disable Run Button logic
	$runButton = New-Object System.Windows.Forms.Button
	$runButton.Text = "Run"
	$runButton.Location = [System.Drawing.Point]::new(150, 300)
	$runButton.Size = [System.Drawing.Size]::new(100, 30)
	$runButton.Enabled = $false
	$repairForm.Controls.Add($runButton)
	foreach ($cb in $checkboxes)
	{
		$cb.Add_CheckedChanged({ $runButton.Enabled = ($checkboxes | Where-Object { $_.Checked }).Count -gt 0 })
	}

	# Show form and get selections
	$selectedParams = @{ }
	$runButton.Add_Click({
			$selectedParams.Defender = $cb1.Checked
			$selectedParams.DISM = $cb2.Checked
			$selectedParams.SFC = $cb3.Checked
			$selectedParams.DiskCleanup = $cb4.Checked
			$selectedParams.OptimizeDrives = $cb5.Checked
			$selectedParams.CheckDisk = $cb6.Checked
			$repairForm.DialogResult = [System.Windows.Forms.DialogResult]::OK
			$repairForm.Close()
		})

	$dialogResult = $repairForm.ShowDialog()
	if ($dialogResult -ne [System.Windows.Forms.DialogResult]::OK)
	{
		Write_Log "Windows repair process cancelled by the user." "yellow"
		return
	}

	# -------------------- Operations Begin --------------------

	if ($selectedParams.Defender)
	{
		try
		{
			Write_Log "Updating Windows Defender signatures..." "blue"
			$updateOutput = & "$env:ProgramFiles\Windows Defender\MpCmdRun.exe" -SignatureUpdate 2>&1
			Write_Log "Windows Defender signatures update output: $updateOutput" "cyan"
			Write_Log "Windows Defender signatures updated successfully." "green"
			Write_Log "Running Windows Defender full scan..." "blue"
			$scanOutput = & "$env:ProgramFiles\Windows Defender\MpCmdRun.exe" -Scan -ScanType 2 2>&1
			Write_Log "Windows Defender full scan output: $scanOutput" "cyan"
			Write_Log "Windows Defender full scan completed." "green"
		}
		catch { Write_Log "Defender update/scan failed: $_" "red" }
	}
	else { Write_Log "Skipping Windows Defender update and scan as per user request." "yellow" }

	if ($selectedParams.DISM)
	{
		try
		{
			Write_Log "Running DISM RestoreHealth..." "blue"
			$dismRestoreOutput = DISM /Online /Cleanup-Image /RestoreHealth /Source:WindowsUpdate /NoRestart 2>&1
			Write_Log "DISM RestoreHealth output: $dismRestoreOutput" "cyan"
			Write_Log "DISM RestoreHealth completed." "green"
			Write_Log "Running DISM StartComponentCleanup..." "blue"
			$dismCleanupOutput = DISM /Online /Cleanup-Image /StartComponentCleanup /NoRestart 2>&1
			Write_Log "DISM StartComponentCleanup output: $dismCleanupOutput" "cyan"
			Write_Log "DISM StartComponentCleanup completed." "green"
		}
		catch { Write_Log "DISM failed: $_" "red" }
	}
	else { Write_Log "Skipping DISM operations as per user request." "yellow" }

	if ($selectedParams.SFC)
	{
		try
		{
			Write_Log "Running System File Checker (SFC)..." "blue"
			# SFC writes UTF-16 to a redirected stdout; drop the NULs so the text is readable
			$sfcOutput = ((SFC /scannow 2>&1) -join ' ') -replace "`0", ''
			Write_Log "System File Checker output: $sfcOutput" "cyan"
			Write_Log "System File Checker completed." "green"
		}
		catch { Write_Log "SFC failed: $_" "red" }
	}
	else { Write_Log "Skipping System File Checker as per user request." "yellow" }

	if ($selectedParams.DiskCleanup)
	{
		try
		{
			Write_Log "Running Disk Cleanup..." "blue"
			Start-Process "cleanmgr.exe" -ArgumentList "/sagerun:1" -Wait
			Write_Log "Disk Cleanup completed." "green"
		}
		catch { Write_Log "Disk Cleanup failed: $_" "red" }
	}
	else { Write_Log "Skipping Disk Cleanup as per user request." "yellow" }

	if ($selectedParams.OptimizeDrives)
	{
		try
		{
			Write_Log "Optimizing all fixed drives..." "blue"
			Get-Volume | Where-Object { $_.DriveType -eq 'Fixed' -and $_.DriveLetter } | ForEach-Object {
				Write_Log "Optimizing drive: $($_.DriveLetter)" "blue"
				$optimizeOutput = Optimize-Volume -DriveLetter $_.DriveLetter -Verbose 2>&1
				Write_Log "Optimize drive output: $optimizeOutput" "cyan"
			}
			Write_Log "Disk optimization completed." "green"
		}
		catch { Write_Log "Drive optimization failed: $_" "red" }
	}
	else { Write_Log "Skipping disk optimization as per user request." "yellow" }

	if ($selectedParams.CheckDisk)
	{
		try
		{
			Write_Log "Scheduling Check Disk on C: drive..." "blue"
			$checkDiskOutput = Start-Process "cmd.exe" -ArgumentList "/c echo Y|chkdsk C: /f /r" -Verb RunAs -Wait -PassThru
			Write_Log "Check Disk scheduling output: $checkDiskOutput" "cyan"
			Write_Log "Check Disk scheduled. Restart may be required." "green"
		}
		catch { Write_Log "Check Disk scheduling failed: $_" "red" }
	}
	else { Write_Log "Skipping Check Disk scheduling as per user request." "yellow" }

	Write_Log "`r`n==================== Repair_Windows Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Schedule_LocalDB_Backup
# ---------------------------------------------------------------------------------------------------
# Description:
#   GUI to configure, schedule, and maintain the automated backup of the local store SQL
#   database: prompts for time, frequency, and retention, then generates and schedules a
#   SYSTEM task running a PowerShell script that writes a dated .bak and deletes oldest
#   backups, keeping only the configured count.
#
# Parameters:
#   (none - uses $script:FunctionResults for database info)
#
# Variables:
#   - $script:FunctionResults: DBNAME, DBSERVER
#   - $script:BackupRoot: backup destination (per-host subfolder)
#   - $script:ScriptsFolder: where the backup script is written
# ===================================================================================================

function Schedule_LocalDB_Backup
{
	Write_Log "`r`n==================== Starting Schedule_LocalDB_Backup ====================`r`n" "blue"

	try
	{
		# --- Validate FunctionResults for DB and Paths
		$dbName = $script:FunctionResults['DBNAME']
		$dbServer = $script:FunctionResults['DBSERVER']
		$backupDir = $script:BackupRoot
		$scriptsDir = $script:ScriptsFolder
		$serverFolder = Join-Path $backupDir $LocalHost

		if (-not $dbName -or -not $dbServer)
		{
			Write_Log "DBNAME or DBSERVER not found in FunctionResults. Aborting." "red"
			return
		}
		# --- Prompt User: Backup Time, Freq, Retention
		Add-Type -AssemblyName System.Windows.Forms
		Add-Type -AssemblyName System.Drawing

		$form = New-Object System.Windows.Forms.Form
		$form.Text = "Configure Local DB Backup Scheduler"
		$form.Size = New-Object System.Drawing.Size(375, 280)
		$form.StartPosition = "CenterScreen"
		$form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
		$form.MaximizeBox = $false
		$form.MinimizeBox = $false

		$lblTime = New-Object System.Windows.Forms.Label
		$lblTime.Text = "Time to run backup (24h, HH:mm):"
		$lblTime.Location = New-Object System.Drawing.Point(10, 18)
		$lblTime.Size = New-Object System.Drawing.Size(210, 20)
		$form.Controls.Add($lblTime)

		$txtTime = New-Object System.Windows.Forms.MaskedTextBox
		$txtTime.Mask = "00:00"
		$txtTime.Text = "01:00"
		$txtTime.Location = New-Object System.Drawing.Point(220, 16)
		$txtTime.Size = New-Object System.Drawing.Size(60, 20)
		$form.Controls.Add($txtTime)

		$lblFreq = New-Object System.Windows.Forms.Label
		$lblFreq.Text = "Frequency (every X days):"
		$lblFreq.Location = New-Object System.Drawing.Point(10, 58)
		$lblFreq.Size = New-Object System.Drawing.Size(210, 20)
		$form.Controls.Add($lblFreq)

		$numFreq = New-Object System.Windows.Forms.NumericUpDown
		$numFreq.Minimum = 1
		$numFreq.Maximum = 31
		$numFreq.Value = 1
		$numFreq.Location = New-Object System.Drawing.Point(220, 56)
		$numFreq.Size = New-Object System.Drawing.Size(60, 20)
		$form.Controls.Add($numFreq)

		$lblKeep = New-Object System.Windows.Forms.Label
		$lblKeep.Text = "How many backups to keep:"
		$lblKeep.Location = New-Object System.Drawing.Point(10, 98)
		$lblKeep.Size = New-Object System.Drawing.Size(210, 20)
		$form.Controls.Add($lblKeep)

		$numKeep = New-Object System.Windows.Forms.NumericUpDown
		$numKeep.Minimum = 1
		$numKeep.Maximum = 99
		$numKeep.Value = 3
		$numKeep.Location = New-Object System.Drawing.Point(220, 96)
		$numKeep.Size = New-Object System.Drawing.Size(60, 20)
		$form.Controls.Add($numKeep)

		$lblDir = New-Object System.Windows.Forms.Label
		$lblDir.Text = "Backup folder:"
		$lblDir.Location = New-Object System.Drawing.Point(10, 138)
		$lblDir.Size = New-Object System.Drawing.Size(95, 20)
		$form.Controls.Add($lblDir)

		$txtDir = New-Object System.Windows.Forms.TextBox
		$txtDir.ReadOnly = $true
		$txtDir.Text = $backupDir.TrimEnd('\')
		$txtDir.Location = New-Object System.Drawing.Point(108, 136)
		$txtDir.Size = New-Object System.Drawing.Size(150, 20)
		$form.Controls.Add($txtDir)

		$btnBrowse = New-Object System.Windows.Forms.Button
		$btnBrowse.Text = "Browse..."
		$btnBrowse.Location = New-Object System.Drawing.Point(262, 134)
		$btnBrowse.Size = New-Object System.Drawing.Size(75, 24)
		$btnBrowse.Add_Click({
			$p = Select-FolderOrDefault -initialPath $txtDir.Text -description "Choose where to store the local DB backup (a <host> subfolder is created inside it)."
			if ($p) { $txtDir.Text = $p }
		})
		$form.Controls.Add($btnBrowse)

		$btnOK = New-Object System.Windows.Forms.Button
		$btnOK.Text = "OK"
		$btnOK.Location = New-Object System.Drawing.Point(70, 190)
		$btnOK.Size = New-Object System.Drawing.Size(90, 30)
		$btnOK.DialogResult = [System.Windows.Forms.DialogResult]::OK
		$form.AcceptButton = $btnOK
		$form.Controls.Add($btnOK)

		$btnCancel = New-Object System.Windows.Forms.Button
		$btnCancel.Text = "Cancel"
		$btnCancel.Location = New-Object System.Drawing.Point(185, 190)
		$btnCancel.Size = New-Object System.Drawing.Size(90, 30)
		$btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
		$form.CancelButton = $btnCancel
		$form.Controls.Add($btnCancel)

		$result = $form.ShowDialog()
		if ($result -ne [System.Windows.Forms.DialogResult]::OK)
		{
			Write_Log "Backup scheduling cancelled by user." "yellow"
			Write_Log "`r`n==================== Schedule_LocalDB_Backup Completed ====================" "blue"
			return
		}

		# Backup location: the folder the user picked (default if unchanged) + <host> subfolder
		$chosenParent = $txtDir.Text.Trim()
		if (-not $chosenParent) { $chosenParent = $backupDir.TrimEnd('\') }
		$serverFolder = Join-Path $chosenParent $LocalHost
		Write_Log "Local DB backup destination: $serverFolder" "gray"

		$timeInput = $txtTime.Text
		$freqInput = [int]$numFreq.Value
		$keepInput = [int]$numKeep.Value

		if ($timeInput -notmatch '^\d{2}:\d{2}$')
		{
			[void][System.Windows.Forms.MessageBox]::Show("Time must be in HH:mm (24h) format.", "Input Error", 0, 16)
			Write_Log "Invalid time format entered." "red"
			return
		}
		$hours, $minutes = $timeInput.Split(":")
		if ([int]$hours -gt 23 -or [int]$minutes -gt 59)
		{
			[void][System.Windows.Forms.MessageBox]::Show("Invalid time entered.", "Input Error", 0, 16)
			Write_Log "Invalid time (out of range)." "red"
			return
		}

		# --- Compose the backup script (no nested here-string)
		$backupScript = @"
# Auto-generated by Schedule_${LocalHost}_DB_Backup (Alex_C.T)
`$ErrorActionPreference = 'Stop'
`$BackupRoot = `"$serverFolder`"
`$Database = `"$dbName`"
`$SqlInstance = `"$dbServer`"
`$MaxBackups = $keepInput

# Compose backup file path with timestamp
`$timestamp = Get-Date -Format 'yyyyMMdd_HHmmss'
`$backupFile = Join-Path `$BackupRoot ("{0}_{1}.bak" -f `$Database, `$timestamp)

# Ensure folder exists
if (-not (Test-Path `$BackupRoot)) {
    New-Item -Path `$BackupRoot -ItemType Directory -Force | Out-Null
}

# Run the backup (old backups are only rotated out AFTER a successful one)
`$tsql = "BACKUP DATABASE [`$Database] TO DISK = N'`$backupFile' WITH NOFORMAT, NOINIT, NAME = N'`$Database-FullBackup-`$timestamp', SKIP, NOREWIND, NOUNLOAD, STATS = 10"
`$sqlOut = & sqlcmd -S `"$dbServer`" -Q `$tsql -b 2>&1
`$exitCode = `$LASTEXITCODE

if (`$exitCode -eq 0) {
    # Success log, then keep only the newest MaxBackups
    "[`$(Get-Date)] Backup complete: `$backupFile" | Out-File -FilePath (Join-Path `$BackupRoot `"backup.log`") -Append -Encoding utf8
    @(Get-ChildItem -Path `$BackupRoot -Filter "`$Database`_*.bak" | Sort-Object LastWriteTime -Descending | Select-Object -Skip `$MaxBackups) |
        ForEach-Object { Remove-Item -LiteralPath `$_.FullName -Force -ErrorAction SilentlyContinue }
}
else {
    # Failure log - capture the real sqlcmd error so it is diagnosable on the store
    `$errMsg = (`$sqlOut | Out-String).Trim()
    if (-not `$errMsg) { `$errMsg = "(sqlcmd produced no output)" }
    "[`$(Get-Date)] Backup FAILED for [`$Database] on [`$SqlInstance] (exit code: `$exitCode)" | Out-File -FilePath (Join-Path `$BackupRoot `"backup.log`") -Append -Encoding utf8
    "[`$(Get-Date)]   sqlcmd output: `$errMsg" | Out-File -FilePath (Join-Path `$BackupRoot `"backup.log`") -Append -Encoding utf8
    if (`$errMsg -match 'Msg 916|Msg 3013|Msg 3201|not able to access the database') {
        "[`$(Get-Date)]   ACCESS problem: backup ran as an account with no access to [`$Database]. Re-run 'Schedule DB Backup' (it now runs as the logged-in user) or set the task to an account that can open the database." | Out-File -FilePath (Join-Path `$BackupRoot `"backup.log`") -Append -Encoding utf8
    }
}
"@

		# --- Write the backup script to the scripts folder
		$scriptName = "Run_${LocalHost}_DB_Backup.ps1"
		$backupScriptPath = Join-Path $scriptsDir $scriptName
		if (-not (Test-Path $scriptsDir))
		{
			New-Item -Path $scriptsDir -ItemType Directory -Force | Out-Null
		}
		Set-Content -Path $backupScriptPath -Value $backupScript -Encoding UTF8

		# --- Build Task Scheduler arguments ---
		$hour = "{0:D2}" -f [int]$hours
		$min = "{0:D2}" -f [int]$minutes
		$startTime = "$hour`:$min"

		$freqArg = "/SC DAILY"
		if ($freqInput -gt 1)
		{
			$freqArg = "/SC DAILY /MO $freqInput"
		}
		$taskName = "${LocalHost}_DB_Backup_Schedule"
		$action = "powershell.exe -NoProfile -ExecutionPolicy Bypass -File `"`"$backupScriptPath`"`""

		# --- Remove existing task if present ---
		schtasks.exe /Delete /TN "$taskName" /F 2>$null | Out-Null


		# --- Create scheduled task ---
		# Run as the CURRENT (logged-in) user, not SYSTEM: on the store the SQL
		# login that can open the database is the interactive account, so the
		# backup must run under it (interactive, /IT). SYSTEM has no DB access.
		$backupTaskUser = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
		$cmd = "schtasks.exe /Create /RU `"$backupTaskUser`" /IT /RL HIGHEST /TN `"$taskName`" /TR `"$action`" $freqArg /ST $startTime /F"
		Write_Log "Creating backup task as '$backupTaskUser' (interactive /IT) with command:" "yellow"
		Write_Log $cmd "gray"
		Invoke-Expression $cmd

		if ($LASTEXITCODE -eq 0)
		{
			Write_Log "Backup task scheduled successfully (`"$taskName`") as '$backupTaskUser' at $startTime every $freqInput day(s)." "green"
			[void][System.Windows.Forms.MessageBox]::Show("Backup task scheduled successfully as '$backupTaskUser'.`nScript: $backupScriptPath", "Scheduled!", 0, 64)
		}
		else
		{
			Write_Log "Failed to schedule backup task. Check permissions or path." "red"
			[void][System.Windows.Forms.MessageBox]::Show("Failed to schedule backup task.`nCheck permissions or path.", "Error", 0, 16)
		}
	}
	catch
	{
		Write_Log "Fatal error in Schedule_LocalDB_Backup: $($_.Exception.Message)" "red"
		[void][System.Windows.Forms.MessageBox]::Show("Fatal error: $($_.Exception.Message)", "Error", 0, 16)
	}
	Write_Log "`r`n==================== Schedule_LocalDB_Backup Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Schedule_Server_DB_Maintenance
# ---------------------------------------------------------------------------------------------------
# Description:
#   Schedules the server (store) DB maintenance on the local server: writes the server SQL
#   script and the scheduler macro into the server XF folder for the chosen repeat interval.
#   Files are written as ANSI (Windows-1252), CRLF, no BOM; if the XF folder is missing the
#   operation is skipped and logged.
#
# Parameters:
#   - StoreNumber   [string]: store to process (required)
#   - ServerNumber  [string]: server number (default 901)
#
# Variables:
#   - $script:ScheduleServerScript: server maintenance SQL text (must be generated first)
#
# Writes:
#   - Server maintenance script + scheduler macro in the local XF folder
# ===================================================================================================

function Schedule_Server_DB_Maintenance
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[string]$ServerNumber = "901"
	)
	Write_Log "`r`n==================== Starting Schedule_Server_DB_Maintenance ====================`r`n" "blue"

	# Normally generated by the startup warmup; generate it now if the menu was used before that
	if (-not $script:ScheduleServerScript)
	{
		try { Generate_SQL_Scripts -StoreNumber $StoreNumber | Out-Null }
		catch { }
	}
	if (-not $script:ScheduleServerScript)
	{
		Write_Log "Server SQL script content variable (`\$script:ScheduleServerScript`) is empty or not defined." "red"
		return
	}

	# Prompt user for the repeat interval in days (once)
	Add-Type -AssemblyName System.Windows.Forms
	$daysPromptForm = New-Object System.Windows.Forms.Form
	$daysPromptForm.Text = "Server DB Maintenance - Schedule Interval"
	$daysPromptForm.Width = 350
	$daysPromptForm.Height = 160
	$daysPromptForm.StartPosition = "CenterScreen"

	$label = New-Object System.Windows.Forms.Label
	$label.Text = "How many days between each run (minimum 1):"
	$label.AutoSize = $true
	$label.Location = New-Object System.Drawing.Point(15, 20)
	$daysPromptForm.Controls.Add($label)

	$textBox = New-Object System.Windows.Forms.TextBox
	$textBox.Location = New-Object System.Drawing.Point(20, 50)
	$textBox.Width = 60
	$textBox.Text = "7"
	$daysPromptForm.Controls.Add($textBox)

	$okButton = New-Object System.Windows.Forms.Button
	$okButton.Text = "OK"
	$okButton.Location = New-Object System.Drawing.Point(90, 90)
	$okButton.Add_Click({ $daysPromptForm.DialogResult = [System.Windows.Forms.DialogResult]::OK })
	$daysPromptForm.Controls.Add($okButton)

	$cancelButton = New-Object System.Windows.Forms.Button
	$cancelButton.Text = "Cancel"
	$cancelButton.Location = New-Object System.Drawing.Point(170, 90)
	$cancelButton.Add_Click({ $daysPromptForm.DialogResult = [System.Windows.Forms.DialogResult]::Cancel })
	$daysPromptForm.Controls.Add($cancelButton)

	$daysPromptForm.AcceptButton = $okButton
	$daysPromptForm.CancelButton = $cancelButton

	if ($daysPromptForm.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK)
	{
		Write_Log "Operation cancelled by user in interval prompt." "yellow"
		return
	}

	[int]$UserDays = 0
	if ([int]::TryParse($textBox.Text, [ref]$UserDays) -and $UserDays -ge 1)
	{
		$RepeatDays = $UserDays
	}
	else
	{
		Write_Log "Invalid or no interval provided, using 7 days." "yellow"
		$RepeatDays = 7
	}

	# Paths: Office for the script, XF for the scheduler macro
	$OfficeFolder = $OfficePath
	$DestScriptPath = Join-Path $OfficeFolder "SERVER_DB_MAINTENANCE.SQI"
	$LocalXFPath = Join-Path $OfficePath "XF$StoreNumber$ServerNumber"
	$SchedulerMacroPath = Join-Path $LocalXFPath "Add_ServerDBMaintenance_to_RUN_TAB.sqi"

	if (-not (Test-Path $LocalXFPath))
	{
		Write_Log "Local XF folder not found: $LocalXFPath (repair script and scheduler not dropped)." "red"
		return
	}

	$ansiEncoding = [System.Text.Encoding]::GetEncoding(1252)
	$ServerSQLScriptContent = $script:ScheduleServerScript

	$TaskNumber = 750
	$HostTarget = "{0:D3}" -f [int]$ServerNumber
	$CommandToRun = 'sqi=SERVER_DB_MAINTENANCE'
	$ExecTarget = $HostTarget
	$TaskName = 'Server DB Maintenance'
	$ManualAllowed = 1
	$CatchupMissed = 1
	$WeeklyDays = $RepeatDays
	$Months = 0
	$Minutes = 0
	$LastRanDate = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff")
	$NextRunDate = (Get-Date).AddDays($RepeatDays).ToString("yyyy-MM-dd HH:mm:ss.fff")

	$SchedulerMacroContent = @"
 /* First delete the scheduled maintenance if it exists */
 DELETE FROM RUN_TAB WHERE F1103 = '$CommandToRun' AND F1000 = '$HostTarget';

 /* Insert the scheduled weekly maintenance */
 INSERT INTO RUN_TAB (F1102, F1000, F1103, F1104, F1105, F1107, F1108, F1109, F1111, F1114, F1115, F1117)
 VALUES ($TaskNumber, '$HostTarget', '$CommandToRun', '$ExecTarget', '$LastRanDate', '$NextRunDate', $ManualAllowed, '$TaskName', $CatchupMissed, $WeeklyDays, $Months, $Minutes);

 /* Activate the new task right away */
 @EXEC(SQL=ACTIVATE_ACCEPT_SYS);
"@ -replace "`r?`n", "`r`n"

	# Write the server repair script
	try
	{
		[System.IO.File]::WriteAllText($DestScriptPath, $ServerSQLScriptContent, $ansiEncoding)
		Set-ItemProperty -Path $DestScriptPath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
		Write_Log "Wrote server DB repair script to $DestScriptPath" "green"
	}
	catch
	{
		Write_Log "Failed to write server script: $_" "red"
		return
	}

	# Write the scheduler macro
	try
	{
		[System.IO.File]::WriteAllText($SchedulerMacroPath, $SchedulerMacroContent, $ansiEncoding)
		Set-ItemProperty -Path $SchedulerMacroPath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
		Write_Log "Scheduler SQL macro created at $SchedulerMacroPath" "green"
	}
	catch
	{
		Write_Log "Failed to write scheduler macro: $_" "red"
		return
	}

	# Remove archive bit if set (optional)
	try
	{
		if (Test-Path $DestScriptPath)
		{
			$file = Get-Item -Path $DestScriptPath
			if ($file.Attributes -band [System.IO.FileAttributes]::Archive)
			{
				$file.Attributes = $file.Attributes -bxor [System.IO.FileAttributes]::Archive
				Write_Log "Removed the archive bit from '$DestScriptPath'." "green"
			}
		}
	}
	catch
	{
		Write_Log "Failed to remove the archive bit from '$DestScriptPath'. Error: $_" "red"
	}

	Write_Log "`r`n==================== Schedule_Server_DB_Maintenance Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Schedule_Storeman_Zip_Backup
# ---------------------------------------------------------------------------------------------------
# Description:
#   GUI to configure, schedule, and maintain the automated ZIP backup of the Storeman folder
#   (weekly by default): prompts for time, frequency, and retention, writes
#   Run_<host>_Storeman_Zip_Backup.ps1, and schedules the <host>_Storeman_Zip_Backup SYSTEM
#   task; the script zips to a dated .zip and keeps only the configured number of backups.
#
# Parameters:
#   (none - uses $BasePath as the detected Storeman folder)
#
# Variables:
#   - $BasePath: detected Storeman folder
#   - $script:BackupRoot: backup destination (per-host subfolder)
#   - $script:ScriptsFolder: where the backup script is written
# ===================================================================================================

function Schedule_Storeman_Zip_Backup
{
	Write_Log "`r`n==================== Starting Schedule_Storeman_Zip_Backup ====================`r`n" "blue"

	try
	{
		# --- Use detected Storeman folder ---
		$storemanPath = $BasePath
		if (-not (Test-Path $storemanPath))
		{
			Write_Log "Storeman path ($storemanPath) not found. Aborting." "red"
			return
		}
		$LocalHost = $env:COMPUTERNAME
		$backupRoot = "${script:BackupRoot}${LocalHost}"
		$scriptsDir = $script:ScriptsFolder
		$backupScriptName = "Run_${LocalHost}_Storeman_Zip_Backup.ps1"
		$taskName = "${LocalHost}_Storeman_Zip_Backup"

		# --- Prompt User: Backup Time, Frequency, Retention (defaults set for weekly) ---
		Add-Type -AssemblyName System.Windows.Forms
		Add-Type -AssemblyName System.Drawing

		$form = New-Object System.Windows.Forms.Form
		$form.Text = "Configure Storeman ZIP Backup Scheduler"
		$form.Size = New-Object System.Drawing.Size(385, 280)
		$form.StartPosition = "CenterScreen"
		$form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
		$form.MaximizeBox = $false
		$form.MinimizeBox = $false

		$lblTime = New-Object System.Windows.Forms.Label
		$lblTime.Text = "Time to run backup (24h, HH:mm):"
		$lblTime.Location = New-Object System.Drawing.Point(10, 18)
		$lblTime.Size = New-Object System.Drawing.Size(210, 20)
		$form.Controls.Add($lblTime)

		$txtTime = New-Object System.Windows.Forms.MaskedTextBox
		$txtTime.Mask = "00:00"
		$txtTime.Text = "02:00"
		$txtTime.Location = New-Object System.Drawing.Point(220, 16)
		$txtTime.Size = New-Object System.Drawing.Size(60, 20)
		$form.Controls.Add($txtTime)

		$lblFreq = New-Object System.Windows.Forms.Label
		$lblFreq.Text = "Frequency (every X days):"
		$lblFreq.Location = New-Object System.Drawing.Point(10, 58)
		$lblFreq.Size = New-Object System.Drawing.Size(210, 20)
		$form.Controls.Add($lblFreq)

		$numFreq = New-Object System.Windows.Forms.NumericUpDown
		$numFreq.Minimum = 1
		$numFreq.Maximum = 31
		$numFreq.Value = 7 # Default = once a week
		$numFreq.Location = New-Object System.Drawing.Point(220, 56)
		$numFreq.Size = New-Object System.Drawing.Size(60, 20)
		$form.Controls.Add($numFreq)

		$lblKeep = New-Object System.Windows.Forms.Label
		$lblKeep.Text = "How many backups to keep:"
		$lblKeep.Location = New-Object System.Drawing.Point(10, 98)
		$lblKeep.Size = New-Object System.Drawing.Size(210, 20)
		$form.Controls.Add($lblKeep)

		$numKeep = New-Object System.Windows.Forms.NumericUpDown
		$numKeep.Minimum = 1
		$numKeep.Maximum = 99
		$numKeep.Value = 1
		$numKeep.Location = New-Object System.Drawing.Point(220, 96)
		$numKeep.Size = New-Object System.Drawing.Size(60, 20)
		$form.Controls.Add($numKeep)

		$lblDir = New-Object System.Windows.Forms.Label
		$lblDir.Text = "Backup folder:"
		$lblDir.Location = New-Object System.Drawing.Point(10, 138)
		$lblDir.Size = New-Object System.Drawing.Size(95, 20)
		$form.Controls.Add($lblDir)

		$txtDir = New-Object System.Windows.Forms.TextBox
		$txtDir.ReadOnly = $true
		$txtDir.Text = $script:BackupRoot.TrimEnd('\')
		$txtDir.Location = New-Object System.Drawing.Point(108, 136)
		$txtDir.Size = New-Object System.Drawing.Size(150, 20)
		$form.Controls.Add($txtDir)

		$btnBrowse = New-Object System.Windows.Forms.Button
		$btnBrowse.Text = "Browse..."
		$btnBrowse.Location = New-Object System.Drawing.Point(262, 134)
		$btnBrowse.Size = New-Object System.Drawing.Size(75, 24)
		$btnBrowse.Add_Click({
			$p = Select-FolderOrDefault -initialPath $txtDir.Text -description "Choose where to store the Storeman ZIP backup (a <host> subfolder is created inside it)."
			if ($p) { $txtDir.Text = $p }
		})
		$form.Controls.Add($btnBrowse)

		$btnOK = New-Object System.Windows.Forms.Button
		$btnOK.Text = "OK"
		$btnOK.Location = New-Object System.Drawing.Point(80, 190)
		$btnOK.Size = New-Object System.Drawing.Size(90, 30)
		$btnOK.DialogResult = [System.Windows.Forms.DialogResult]::OK
		$form.AcceptButton = $btnOK
		$form.Controls.Add($btnOK)

		$btnCancel = New-Object System.Windows.Forms.Button
		$btnCancel.Text = "Cancel"
		$btnCancel.Location = New-Object System.Drawing.Point(195, 190)
		$btnCancel.Size = New-Object System.Drawing.Size(90, 30)
		$btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
		$form.CancelButton = $btnCancel
		$form.Controls.Add($btnCancel)

		$result = $form.ShowDialog()
		if ($result -ne [System.Windows.Forms.DialogResult]::OK)
		{
			Write_Log "Storeman ZIP backup scheduling cancelled by user." "yellow"
			Write_Log "`r`n==================== Schedule_Storeman_Zip_Backup Completed ====================" "blue"
			return
		}

		# Backup location: the folder the user picked (default if unchanged) + <host> subfolder
		$chosenParent = $txtDir.Text.Trim()
		if (-not $chosenParent) { $chosenParent = $script:BackupRoot.TrimEnd('\') }
		$backupRoot = Join-Path $chosenParent $LocalHost
		Write_Log "Storeman ZIP backup destination: $backupRoot" "gray"

		$timeInput = $txtTime.Text
		$freqInput = [int]$numFreq.Value
		$keepInput = [int]$numKeep.Value

		if ($timeInput -notmatch '^\d{2}:\d{2}$')
		{
			[void][System.Windows.Forms.MessageBox]::Show("Time must be in HH:mm (24h) format.", "Input Error", 0, 16)
			Write_Log "Invalid time format entered." "red"
			return
		}
		$hours, $minutes = $timeInput.Split(":")
		if ([int]$hours -gt 23 -or [int]$minutes -gt 59)
		{
			[void][System.Windows.Forms.MessageBox]::Show("Invalid time entered.", "Input Error", 0, 16)
			Write_Log "Invalid time (out of range)." "red"
			return
		}

		# --- Compose the backup script ---
		$backupScript = @"
# Auto-generated by Schedule_${LocalHost}_Storeman_Zip_Backup (Alex_C.T)
`$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem

`$storemanPath = `"$storemanPath`"
`$backupRoot = `"$backupRoot`"
if (-not (Test-Path `$storemanPath)) {
    Write-Host "Storeman path (`$storemanPath) not found. Aborting." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path `$backupRoot)) {
    New-Item -Path `$backupRoot -ItemType Directory -Force | Out-Null
}

# Compose backup ZIP filename with timestamp
`$timestamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
`$backupZipPath = Join-Path `$backupRoot ("Storeman_Backup_`$timestamp.zip")

# Run the backup (old ZIPs are only rotated out AFTER a successful one)
try {
    `$zip = [System.IO.Compression.ZipFile]::Open(`$backupZipPath, 1)  # 1 = Create

    # Gather all root directories starting with "install" (case-insensitive)
    `$rootDirs = Get-ChildItem -Path `$storemanPath -Directory | Select-Object -ExpandProperty FullName
    `$installDirs = `$rootDirs | Where-Object { `$_ -match '(?i)\\install' }

    `$backupFullPathU = [System.IO.Path]::GetFullPath((Join-Path `$storemanPath "BACKUP"))
    `$backupFullPathL = [System.IO.Path]::GetFullPath((Join-Path `$storemanPath "backup"))
    `$logFullPath     = [System.IO.Path]::GetFullPath((Join-Path `$storemanPath "log"))

    `$files = Get-ChildItem -Path `$storemanPath -Recurse -File
    `$countAdded = 0

    foreach (`$file in `$files) {
        `$filePath = [System.IO.Path]::GetFullPath(`$file.FullName)

        # Skip files under any install* folder
        `$skipInstall = `$false
        foreach (`$dir in `$installDirs) {
            if (`$filePath -like "`$dir*") {
                `$skipInstall = `$true
                break
            }
        }
        if (`$skipInstall) {
            continue
        }

        # Skip other excluded folders and log files
        if (
            (`$filePath -like "`$backupFullPathU*") -or
            (`$filePath -like "`$backupFullPathL*") -or
            (`$filePath -like "`$logFullPath*") -or
            (`$file.Extension -eq ".log")
        ) {
            continue
        }

        `$relativePath = `$filePath.Substring(`$storemanPath.Length).TrimStart('\','/')
        try {
            [System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile(`$zip, `$file.FullName, `$relativePath) | Out-Null
            `$countAdded++
        }
        catch {
            continue
        }
    }
    `$zip.Dispose()
    "`$([DateTime]::Now) Backup complete: `$backupZipPath (`$countAdded files)" | Out-File -FilePath (Join-Path `$backupRoot "backup.log") -Append -Encoding utf8
    Write-Host "Backup complete: `$backupZipPath (`$countAdded files)" -ForegroundColor Green

    # Keep only the newest $keepInput ZIPs
    Get-ChildItem -Path `$backupRoot -Filter "Storeman_Backup_*.zip" | Sort-Object LastWriteTime -Descending | Select-Object -Skip $keepInput | ForEach-Object {
        try { Remove-Item -LiteralPath `$_.FullName -Force }
        catch { Write-Host "Failed to delete old backup: `$(`$_.FullName)" -ForegroundColor Yellow }
    }
}
catch {
    if (`$zip) { `$zip.Dispose() }
    "`$([DateTime]::Now) Backup FAILED for `$storemanPath - `$(`$_.Exception.Message)" | Out-File -FilePath (Join-Path `$backupRoot "backup.log") -Append -Encoding utf8
    Write-Host "Backup FAILED: `$(`$_.Exception.Message)" -ForegroundColor Red
}
"@

		# --- Write the backup script to the scripts folder
		$backupScriptPath = Join-Path $scriptsDir $backupScriptName
		if (-not (Test-Path $scriptsDir))
		{
			New-Item -Path $scriptsDir -ItemType Directory -Force | Out-Null
		}
		Set-Content -Path $backupScriptPath -Value $backupScript -Encoding UTF8

		# --- Build Task Scheduler arguments ---
		$hour = "{0:D2}" -f [int]$hours
		$min = "{0:D2}" -f [int]$minutes
		$startTime = "$hour`:$min"
		$freqArg = "/SC DAILY"
		if ($freqInput -gt 1)
		{
			$freqArg = "/SC DAILY /MO $freqInput"
		}
		$action = "powershell.exe -NoProfile -ExecutionPolicy Bypass -File `"`"$backupScriptPath`"`""

		# --- Remove existing task if present ---
		schtasks.exe /Delete /TN "$taskName" /F 2>$null | Out-Null

		# --- Create scheduled task ---
		$cmd = "schtasks.exe /Create /RU SYSTEM /RL HIGHEST /TN `"$taskName`" /TR `"$action`" $freqArg /ST $startTime /F"
		Write_Log "Creating scheduled task with command:" "yellow"
		Write_Log $cmd "gray"
		Invoke-Expression $cmd

		if ($LASTEXITCODE -eq 0)
		{
			Write_Log "Storeman ZIP backup task scheduled successfully (`"$taskName`") at $startTime every $freqInput day(s)." "green"
			[void][System.Windows.Forms.MessageBox]::Show("Storeman ZIP backup scheduled successfully.`nScript: $backupScriptPath", "Scheduled!", 0, 64)
		}
		else
		{
			Write_Log "Failed to schedule Storeman ZIP backup task. Check permissions or path." "red"
			[void][System.Windows.Forms.MessageBox]::Show("Failed to schedule Storeman ZIP backup task.`nCheck permissions or path.", "Error", 0, 16)
		}
	}
	catch
	{
		Write_Log "Fatal error in Schedule_Storeman_Zip_Backup: $($_.Exception.Message)" "red"
		[void][System.Windows.Forms.MessageBox]::Show("Fatal error: $($_.Exception.Message)", "Error", 0, 16)
	}
	Write_Log "`r`n==================== Schedule_Storeman_Zip_Backup Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Close_Open_Transactions
# ---------------------------------------------------------------------------------------------------
# Description:
#   Closes open POS transactions on the lanes referenced by recent XE error files: scans the
#   store XE folder for S*.*.* files (max 30 days old), extracts the lane number from each
#   file name, marks the lane's open SAL_HDR transactions as CLOSE via SQL (file fallback),
#   and can send a restart-all-programs command over the mailslot after deployment.
#
# Parameters:
#   - StoreNumber  [string]: store to process (required)
#
# Variables:
#   - $script:FunctionResults: SqlModuleName and the lane maps (input)
#   - $OfficePath: Storeman Office root (XE folder)
#
# Writes:
#   - lane databases (SAL_HDR F1067 = CLOSE) and Scripts_by_Alex_C.T\Closed_Transactions_LOG.txt
# ===================================================================================================

function Close_Open_Transactions
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber
	)

	# ==================== Start and validate XE path ====================
	Write_Log "`r`n==================== Starting Close_Open_Transactions ====================`r`n" "blue"

	$XEFolderPath = "$OfficePath\XE${StoreNumber}901"
	if (-not (Test-Path $XEFolderPath))
	{
		Write_Log "XE folder not found: $XEFolderPath" "red"
		return
	}

	# ==================== Validate SQL module availability ====================
	# Invoke-Sqlcmd for the direct close over the lane's protocol; without a SQL module the
	# close goes out as a Close_Transaction.sqi file drop instead
	$invokeSql = $null
	$supportsConnStr = $false
	$SqlModule = $script:FunctionResults['SqlModuleName']
	if ($SqlModule -and $SqlModule -ne "None")
	{
		try
		{
			Import-Module $SqlModule -ErrorAction Stop
			$invokeSql = Get-Command Invoke-Sqlcmd -ErrorAction Stop
			$supportsConnStr = $invokeSql.Parameters.ContainsKey('ConnectionString')
		}
		catch { $invokeSql = $null }
	}
	if (-not $invokeSql) { Write_Log "No SQL module available - transactions are closed through a file drop to the lane." "yellow" }

	# Close over the lane's SQL protocol (Named Pipes / TCP); $true when it worked
	$closeViaProtocol = {
		param ([string]$Lane, [string]$Protocol, $LaneInfo, [string]$Sql, [string]$What)
		if (-not $invokeSql -or $Protocol -notin @('Named Pipes', 'TCP') -or -not $LaneInfo) { return $false }
		$connStr = if ($Protocol -eq 'Named Pipes') { $LaneInfo['NamedPipesConnStr'] } else { $LaneInfo['TcpConnStr'] }
		try
		{
			if ($supportsConnStr) { $null = & $invokeSql -ConnectionString $connStr -Query $Sql -QueryTimeout 30 -ErrorAction Stop }
			else { $null = & $invokeSql -ServerInstance $LaneInfo['TcpServer'] -Database $LaneInfo['DBName'] -Query $Sql -QueryTimeout 30 -ErrorAction Stop }
			Write_Log "Closed $What via SQL protocol ($Protocol) on lane $Lane." "green"
			return $true
		}
		catch
		{
			Write_Log "$Protocol failed for lane $Lane." "yellow"
			return $false
		}
	}

	# SQL string for closing all open transactions (manual fallback)
	$CloseTransactionManual = "@dbEXEC(UPDATE SAL_HDR SET F1067 = 'CLOSE' WHERE F1067 <> 'CLOSE')"

	# Paths for logs (keep a persistent transaction log)
	$LogFolderPath = "$BasePath\Scripts_by_Alex_C.T"
	$LogFilePath = Join-Path -Path $LogFolderPath -ChildPath "Closed_Transactions_LOG.txt"
	if (-not (Test-Path $LogFolderPath))
	{
		try { New-Item -Path $LogFolderPath -ItemType Directory -Force | Out-Null }
		catch { Write_Log "Failed to create log directory '$LogFolderPath'. Error: $_" "red"; return }
	}

	$MatchedTransactions = $false

	try
	{
		$currentTime = Get-Date
		# Only process XE files less than 30 days old and starting with S (SMSStart)
		$files = @(Get-ChildItem -Path $XEFolderPath -Filter "S*.???" -ErrorAction SilentlyContinue | Where-Object {
			($currentTime - $_.LastWriteTime).TotalDays -le 30
		})

		# ==================== PROCESS EACH XE ERROR FILE FOUND ====================
		if ($files -and $files.Count -gt 0)
		{
			foreach ($file in $files)
			{
				try
				{
					# Attempt to extract the lane number from the filename
					if ($file.Name -match '^S.*\.(\d{3})$') { $LaneNumber = $Matches[1] }
					else { continue }

					# Read contents for parsing
					$content = Get-Content -Path $file.FullName
					$fromLine = $content | Where-Object { $_ -like 'From:*' }
					$subjectLine = $content | Where-Object { $_ -like 'Subject:*' }
					$msgLine = $content | Where-Object { $_ -like 'MSG:*' }
					$lastRecordedStatusLine = $content | Where-Object { $_ -like 'Last recorded status:*' }

					# Parse out store/lane numbers from the "From:" line
					if ($fromLine -match 'From:\s*(\d{3})(\d{3})')
					{
						$fileStoreNumber = $Matches[1]
						$fileLaneNumber = $Matches[2]
						if ($fileStoreNumber -eq $StoreNumber -and $fileLaneNumber -eq $LaneNumber)
						{
							# Get subject/MSG and check if it matches open transaction/health check
							if ($subjectLine -match 'Subject:\s*(.*)')
							{
								$subject = $Matches[1].Trim()
								if ($subject -eq 'Health' -and $msgLine -match 'MSG:\s*(.*)' -and $Matches[1].Trim() -eq 'This application is not running.')
								{
									# Get transaction number from status line
									if ($lastRecordedStatusLine -match 'Last recorded status:\s*[\d\s:,-]+TRANS,(\d+)')
									{
										$transactionNumber = $Matches[1]
										$laneKey = $LaneNumber.PadLeft(3, '0')
										$protocolType = if ($script:LaneProtocols -and $script:LaneProtocols.ContainsKey($laneKey)) { $script:LaneProtocols[$laneKey] }
										else { "File" }
										if ($protocolType -eq 'Offline')
										{
											Write_Log "Lane $LaneNumber is offline. Skipping transaction close." "yellow"
											continue
										}

										# Get full DB connection info for this lane
										$laneInfo = Get_All_Lanes_Database_Info -LaneNumber $LaneNumber
										$closeSQL = "UPDATE SAL_HDR SET F1067 = 'CLOSE' WHERE F1032 = $transactionNumber"
										$protocolWorked = & $closeViaProtocol $LaneNumber $protocolType $laneInfo $closeSQL "transaction $transactionNumber"

										# ----------- Fallback: File-based SQI if protocol failed -----------
										if (-not $protocolWorked)
										{
											$CloseTransactionAuto = "@dbEXEC(UPDATE SAL_HDR SET F1067 = 'CLOSE' WHERE F1032 = $transactionNumber)"
											$LaneDirectory = "$OfficePath\XF${StoreNumber}${LaneNumber}"
											if (Test-Path $LaneDirectory)
											{
												$CloseTransactionFilePath = Join-Path -Path $LaneDirectory -ChildPath "Close_Transaction.sqi"
												Set-Content -Path $CloseTransactionFilePath -Value $CloseTransactionAuto -Encoding ASCII
												Set-ItemProperty -Path $CloseTransactionFilePath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
												Write_Log "Wrote Close_Transaction.sqi file for lane $LaneNumber (file fallback)." "yellow"
											}
											else
											{
												Write_Log "Lane directory $LaneDirectory not found (file fallback)." "yellow"
											}
										}

										# Log the close action
										$logMessage = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') - Closed transaction $transactionNumber on lane $LaneNumber"
										Add-Content -Path $LogFilePath -Value $logMessage

										# Remove processed XE file
										Remove-Item -Path $file.FullName -Force

										Write_Log "Processed file $($file.Name) for lane $LaneNumber and closed transaction $transactionNumber" "green"
										$MatchedTransactions = $true

										# ----------- Optionally restart all programs on the lane -----------
										Start-Sleep -Seconds 3
										$laneMap = $script:FunctionResults['LaneNumToMachineName']
										if ($laneMap)
										{
											$machineName = $laneMap[$LaneNumber]
											if ($machineName)
											{
												$mailslotAddress = "\\$machineName\mailslot\SMSStart_${StoreNumber}${LaneNumber}"
												$commandMessage = "@exec(RESTART_ALL=PROGRAMS)."
												$result = [MailslotSender]::SendMailslotCommand($mailslotAddress, $commandMessage)
												if ($result) { Write_Log "Restart command sent to Machine $machineName (Store $StoreNumber, Lane $LaneNumber) after deployment." "green" }
												else { Write_Log "Failed to send restart command to Machine $machineName (Store $StoreNumber, Lane $LaneNumber)." "red" }
											}
										}
									}
									else
									{
										Write_Log "Could not extract transaction number from Last recorded status in file $($file.Name)" "red"
									}
								}
							}
						}
					}
				}
				catch
				{
					Write_Log "Error processing file $($file.Name): $_" "red"
				}
			}
		}

		# ==================== If no matching files: Manual prompt for lane ====================
		if (-not $MatchedTransactions)
		{
			Write_Log "No files or no matching transactions found. Prompting for lane number." "yellow"
			$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
			if (-not $selection -or -not $selection.Lanes -or $selection.Lanes.Count -eq 0)
			{
				Write_Log "Lane selection cancelled or returned no selection." "yellow"
				Write_Log "`r`n==================== Close_Open_Transactions Function Completed ====================" "blue"
				return
			}

			foreach ($LaneNumber in $selection.Lanes)
			{
				$LaneNumber = if ($LaneNumber -is [pscustomobject] -and $LaneNumber.LaneNumber) { $LaneNumber.LaneNumber }
				else { $LaneNumber }
				$LaneNumber = $LaneNumber.PadLeft(3, '0')
				$laneKey = $LaneNumber
				$protocolType = if ($script:LaneProtocols -and $script:LaneProtocols.ContainsKey($laneKey)) { $script:LaneProtocols[$laneKey] }
				else { "File" }
				if ($protocolType -eq 'Offline')
				{
					Write_Log "Lane $LaneNumber is offline. Skipping." "yellow"
					continue
				}
				$laneInfo = Get_All_Lanes_Database_Info -LaneNumber $LaneNumber
				$closeSQL = "UPDATE SAL_HDR SET F1067 = 'CLOSE' WHERE F1067 <> 'CLOSE'"
				$protocolWorked = & $closeViaProtocol $LaneNumber $protocolType $laneInfo $closeSQL "all open transactions"

				if (-not $protocolWorked)
				{
					$LaneDirectory = "$OfficePath\XF${StoreNumber}${LaneNumber}"
					if (Test-Path $LaneDirectory)
					{
						$CloseTransactionFilePath = Join-Path -Path $LaneDirectory -ChildPath "Close_Transaction.sqi"
						Set-Content -Path $CloseTransactionFilePath -Value $CloseTransactionManual -Encoding ASCII
						Set-ItemProperty -Path $CloseTransactionFilePath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
						Write_Log "Deployed Close_Transaction.sqi to lane $LaneNumber (fallback)." "yellow"
					}
					else
					{
						Write_Log "Lane directory $LaneDirectory not found" "yellow"
					}
				}
				$logMessage = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') - User deployed Close_Transaction to lane $LaneNumber"
				Add-Content -Path $LogFilePath -Value $logMessage
				$laneMap = $script:FunctionResults['LaneNumToMachineName']
				if ($laneMap)
				{
					$machineName = $laneMap[$LaneNumber]
					if ($machineName)
					{
						$mailslotAddress = "\\$machineName\mailslot\SMSStart_${StoreNumber}${LaneNumber}"
						$commandMessage = "@exec(RESTART_ALL=PROGRAMS)."
						$result = [MailslotSender]::SendMailslotCommand($mailslotAddress, $commandMessage)
						if ($result) { Write_Log "Restart All Programs sent to Machine $machineName (Store $StoreNumber, Lane $LaneNumber) after user deployment." "green" }
						else { Write_Log "Failed to send restart command to Machine $machineName (Store $StoreNumber, Lane $LaneNumber)." "red" }
					}
				}
				Write_Log "Prompt deployment process completed." "yellow"
			}
			# Clean up the XE folder, except FATALs
			Get-ChildItem -Path $XEFolderPath -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -notlike "*FATAL*" } | Remove-Item -Force -ErrorAction SilentlyContinue
		}
	}
	catch
	{
		Write_Log "An error occurred during monitoring: $_" "red"
	}
	Write_Log "No further matching files were found after processing." "yellow"
	Write_Log "`r`n==================== Close_Open_Transactions Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Delete_DBS
# ---------------------------------------------------------------------------------------------------
# Description:
#   Deletes specific file types (.txt and .dwr) from the Dbs folders of selected lanes in a
#   store, with a prompt to also include .sus files. Lane machine paths come from the
#   Retrieve_Nodes results; the actual deletion is done by Delete_Files per lane.
#
# Parameters:
#   - StoreNumber  [string]: store whose lanes are processed (required)
#
# Variables:
#   - $script:FunctionResults: LaneMachineNames and LaneNumToMachineName (input)
#
# Notes:
#   - Retrieve_Nodes must have been run first.
# ===================================================================================================

function Delete_DBS
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber
	)

	Write_Log "`r`n==================== Starting Delete_DBS Function ====================`r`n" "blue"

	# Check if FunctionResults has the necessary data
	if (-not $script:FunctionResults.ContainsKey('LaneMachineNames') -or
		-not $script:FunctionResults.ContainsKey('LaneNumToMachineName'))
	{
		Write_Log "Lane information is not available. Please run Retrieve_Nodes first." "Red"
		return
	}

	# Retrieve lane information
	$LaneMachineNames = $script:FunctionResults['LaneMachineNames']
	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']

	if ($LaneMachineNames.Count -eq 0)
	{
		Write_Log "No lanes found for Store Number: $StoreNumber." "Yellow"
		return
	}

	# Prompt user to include .sus files in deletion
	Add-Type -AssemblyName System.Windows.Forms
	Add-Type -AssemblyName System.Drawing

	$form = New-Object System.Windows.Forms.Form
	$form.Text = "Delete_DBS Confirmation"
	$form.Size = New-Object System.Drawing.Size(400, 200)
	$form.StartPosition = "CenterScreen"
	$form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
	$form.MaximizeBox = $false
	$form.MinimizeBox = $false

	$label = New-Object System.Windows.Forms.Label
	$label.Text = "Do you want to include .sus files in the deletion?"
	$label.AutoSize = $true
	$label.Location = New-Object System.Drawing.Point(20, 30)
	$form.Controls.Add($label)

	$checkboxSus = New-Object System.Windows.Forms.CheckBox
	$checkboxSus.Text = "Include .sus files"
	$checkboxSus.AutoSize = $true
	$checkboxSus.Location = New-Object System.Drawing.Point(20, 60)
	$form.Controls.Add($checkboxSus)

	$buttonOK = New-Object System.Windows.Forms.Button
	$buttonOK.Text = "OK"
	$buttonOK.Location = New-Object System.Drawing.Point(100, 120)
	$buttonOK.Size = New-Object System.Drawing.Size(80, 30)
	$buttonOK.DialogResult = [System.Windows.Forms.DialogResult]::OK
	$form.Controls.Add($buttonOK)

	$buttonCancel = New-Object System.Windows.Forms.Button
	$buttonCancel.Text = "Cancel"
	$buttonCancel.Location = New-Object System.Drawing.Point(200, 120)
	$buttonCancel.Size = New-Object System.Drawing.Size(80, 30)
	$buttonCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
	$form.Controls.Add($buttonCancel)

	$form.AcceptButton = $buttonOK
	$form.CancelButton = $buttonCancel

	$dialogResult = $form.ShowDialog()

	if ($dialogResult -ne [System.Windows.Forms.DialogResult]::OK)
	{
		Write_Log "User canceled the deletion process." "Yellow"
		return
	}

	$includeSus = $checkboxSus.Checked

	# Define file types to delete
	$fileExtensions = @("*.txt", "*.dwr")
	if ($includeSus)
	{
		$fileExtensions += "*.sus"
	}

	Write_Log "Starting deletion of file types: $($fileExtensions -join ', ') for Store Number: $StoreNumber." "Green"

	# Show the selection dialog to choose lanes
	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"

	if (-not $selection)
	{
		# User canceled the dialog
		Write_Log "User canceled the lane selection." "Yellow"
		return
	}

	# Lane numbers (the picker returns 3-digit strings; lane objects are accepted too), mapped lanes only
	$selectedLanes = @($selection.Lanes | ForEach-Object {
			if ($_ -is [pscustomobject] -and $_.LaneNumber) { $_.LaneNumber } else { [string]$_ }
		} | Where-Object { $LaneNumToMachineName.ContainsKey($_) })

	if (-not $selectedLanes -or $selectedLanes.Count -eq 0)
	{
		Write_Log "No valid lanes selected for processing." "Yellow"
		return
	}

	# Initialize counters
	$totalDeleted = 0
	$totalFailed = 0

	foreach ($lane in $selectedLanes)
	{
		if ($LaneNumToMachineName.ContainsKey($lane))
		{
			$machineName = $LaneNumToMachineName[$lane]

			if ([string]::IsNullOrWhiteSpace($machineName) -or $machineName -eq "Unknown")
			{
				Write_Log "Lane #${lane}: Machine name is invalid or unknown. Skipping deletion." "Yellow"
				continue
			}

			# Construct the target path (modify this path as per your environment)
			$targetPath = "\\$machineName\Storeman\Office\DBS\"

			if (-not (Test-Path -Path $targetPath))
			{
				Write_Log "Lane #${lane}: Target path '$targetPath' does not exist. Skipping." "Yellow"
				continue
			}

			Write_Log "Processing Lane #$lane at '$targetPath', please wait..." "Blue"

			try
			{
				# Delete_Files function is now expected to return an integer count
				$deletionCount = Delete_Files -Path $targetPath -SpecifiedFiles $fileExtensions -Exclusions @() -AsJob:$false

				if ($deletionCount -is [int])
				{
					$totalDeleted += $deletionCount
				}
				else
				{
					Write_Log "Lane #${lane}: Unexpected response from Delete_Files." "Red"
					$totalFailed++
				}
			}
			catch
			{
				Write_Log "Lane #${lane}: An error occurred while deleting files. Error: $_" "Red"
				$totalFailed++
			}
		}
		else
		{
			Write_Log "Lane #${lane}: Machine information not found. Skipping." "Yellow"
			continue
		}
	}

	# Summary of deletion results
	Write_Log "Deletion Summary for Store Number: $StoreNumber - Total Files Deleted: $totalDeleted, Total Failures: $totalFailed." "Blue"
	Write_Log "`r`n==================== Delete_DBS Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Drawer_Control
# ---------------------------------------------------------------------------------------------------
# Description:
#   Deploys a drawer control command to the selected lanes: pick Enable/Disable in a dialog,
#   select lanes, then for each lane write DrawerControl.sqi (ANSI, CRLF) with the chosen
#   state into the lane XF folder; the SQI activates the change itself (exe_activate_accept_sys).
#
# Parameters:
#   - StoreNumber  [string]: store to process (required)
#
# Variables:
#   - $script:FunctionResults: LaneNumToMachineName (input)
#   - $OfficePath: Storeman Office root (XF lane folders)
#
# Writes:
#   - DrawerControl.sqi in each selected lane XF folder
# ===================================================================================================

function Drawer_Control
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber
	)

	Write_Log "`r`n==================== Starting Drawer_Control ====================`r`n" "blue"

	# --------------------------------------------------
	# STEP 1: Prompt for Drawer State using Enable/Disable radio buttons
	# --------------------------------------------------
	Add-Type -AssemblyName System.Windows.Forms
	Add-Type -AssemblyName System.Drawing

	$stateForm = New-Object System.Windows.Forms.Form
	$stateForm.Text = "Select Drawer State"
	$stateForm.Size = New-Object System.Drawing.Size(400, 200)
	$stateForm.StartPosition = "CenterScreen"

	$stateLabel = New-Object System.Windows.Forms.Label
	$stateLabel.Text = "Select Drawer State:"
	$stateLabel.Location = New-Object System.Drawing.Point(10, 20)
	$stateLabel.AutoSize = $true
	$stateForm.Controls.Add($stateLabel)

	# Radio button for Enable (value = 1)
	$radioEnable = New-Object System.Windows.Forms.RadioButton
	$radioEnable.Text = "Enable"
	$radioEnable.Location = New-Object System.Drawing.Point(10, 50)
	$radioEnable.AutoSize = $true
	$radioEnable.Checked = $true # default selection
	$stateForm.Controls.Add($radioEnable)

	# Radio button for Disable (value = 0)
	$radioDisable = New-Object System.Windows.Forms.RadioButton
	$radioDisable.Text = "Disable"
	$radioDisable.Location = New-Object System.Drawing.Point(10, 80)
	$radioDisable.AutoSize = $true
	$stateForm.Controls.Add($radioDisable)

	# OK Button
	$okButton = New-Object System.Windows.Forms.Button
	$okButton.Text = "OK"
	$okButton.Location = New-Object System.Drawing.Point(80, 120)
	$okButton.Add_Click({
			if ($radioEnable.Checked)
			{
				$stateForm.Tag = "1"
			}
			elseif ($radioDisable.Checked)
			{
				$stateForm.Tag = "0"
			}
			$stateForm.DialogResult = [System.Windows.Forms.DialogResult]::OK
			$stateForm.Close()
		})
	$stateForm.Controls.Add($okButton)

	# Cancel Button
	$cancelButton = New-Object System.Windows.Forms.Button
	$cancelButton.Text = "Cancel"
	$cancelButton.Location = New-Object System.Drawing.Point(180, 120)
	$cancelButton.Add_Click({
			$stateForm.Tag = "Cancelled"
			$stateForm.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
			$stateForm.Close()
		})
	$stateForm.Controls.Add($cancelButton)

	$stateForm.AcceptButton = $okButton
	$stateForm.CancelButton = $cancelButton

	$resultState = $stateForm.ShowDialog()
	if ($stateForm.Tag -eq "Cancelled" -or $resultState -eq [System.Windows.Forms.DialogResult]::Cancel)
	{
		Write_Log "User cancelled the operation at drawer state selection." "yellow"
		Write_Log "`r`n==================== Drawer_Control Function Completed ====================" "blue"
		return
	}
	$DrawerState = $stateForm.Tag
	Write_Log "Drawer state selected: $DrawerState" "green"

	# --------------------------------------------------
	# STEP 2: Use Show_Lane_Selection_Form to select lanes (Store mode)
	# --------------------------------------------------
	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
	if (-not $selection -or -not $selection.Lanes -or $selection.Lanes.Count -eq 0)
	{
		Write_Log "No lanes selected or selection cancelled." "yellow"
		Write_Log "`r`n==================== Drawer_Control Function Completed ====================" "blue"
		return
	}
	# Normalize to 3-digit lane numbers (always as strings)
	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	$lanesToProcess = $selection.Lanes | ForEach-Object {
		if ($_ -is [pscustomobject] -and $_.LaneNumber) { $_.LaneNumber }
		elseif ($_ -match '^\d{3}$') { $_ }
		elseif ($LaneNumToMachineName.ContainsKey($_)) { $_ }
		else { $_ }
	}
	$lanesToProcess = $lanesToProcess | Where-Object { $LaneNumToMachineName.ContainsKey($_) }
	if (-not $lanesToProcess -or $lanesToProcess.Count -eq 0)
	{
		Write_Log "No valid lanes selected for processing." "yellow"
		return
	}

	# --------------------------------------------------
	# STEP 3: For each selected lane, deploy the SQI command file in ANSI (PC) format and send restart command.
	# --------------------------------------------------
	foreach ($lane in $lanesToProcess)
	{
		# Construct the lane directory path (assumes folder naming: XF<StoreNumber><Lane>)
		$LaneDirectory = "$OfficePath\XF${StoreNumber}${lane}"
		if (-not (Test-Path $LaneDirectory))
		{
			Write_Log "Lane directory $LaneDirectory not found. Skipping lane $lane." "yellow"
			continue
		}

		# Define the SQI content with the chosen drawer state
		$SQIContent = @"
CREATE VIEW Fct_Load AS SELECT F1063,F1000,F81,F85,F96,F97,F98,F99,F100,F101,F102,F125,F172,F239,F240,F241,F242,F1042,F1043,F1044,F1045,F1046,F1047,F1050,F1051,F1052,F1053,F1054,F1055,F1064,F1081,F1082,F1083,F1084,F1085,F1086,F1088,F1089,F1090,F1091,F1092,F1147,F1817,F1818,F1895,F1897,F1965,F1966 FROM FCT_TAB;

INSERT INTO Fct_Load VALUES
(10010,'PAL',,,,,,,,,,,,,,,,1,1,1,1,1,9,'F3','TRS','Log',1,1,1,'Login operator','DRAWEROPEN=$DrawerState',,,,,,,,,,,,,,'',,,),

@UPDATE_BATCH(JOB=ADDRPL,TAR=FCT_TAB,
KEY=F1063=:F1063 AND F1000=:F1000,
SRC=SELECT * FROM Fct_Load);

DROP TABLE Fct_Load;

@WIZSET(TARGET=@TER);
@EXEC(SQM=exe_activate_accept_sys);
"@

		# Ensure the SQI content uses CRLF line endings (ANSI PC format)
		$SQIContent = $SQIContent -replace "`r?`n", "`r`n"

		# Define the full path to the SQI file (named "DrawerControl.sqi")
		$SQIFilePath = Join-Path -Path $LaneDirectory -ChildPath "DrawerControl.sqi"

		# Write the SQI file using ASCII encoding (ANSI PC)
		Set-Content -Path $SQIFilePath -Value $SQIContent -Encoding ASCII

		# Remove the Archive attribute (set file attributes to Normal)
		Set-ItemProperty -Path $SQIFilePath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
		Write_Log "Deployed DrawerControl.sqi command to lane $lane with state '$DrawerState' in directory $LaneDirectory." "green"
	}
	Write_Log "`r`n==================== Drawer_Control Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Enable_SQL_Protocols_On_Selected_Lanes
# ---------------------------------------------------------------------------------------------------
# Description:
#   Enables TCP/IP, Named Pipes and Shared Memory protocols on the SQL Server instances of
#   the selected lanes: sets a static TCP port (default 1433), disables dynamic ports,
#   restarts the SQL service when needed, and optionally live-tests a Linked Server to pick
#   the working transport. Runs in parallel through a runspace pool (not background jobs)
#   and restarts the programs on lanes that needed a service restart.
#
# Parameters:
#   - StoreNumber         [string]: store to process (required)
#   - tcpPort             [string]: static TCP port (default "1433")
#   - CreateLinkedServers [switch]: on by default; pass :$false to skip
#
# Variables:
#   - $script:FunctionResults: LaneNumToMachineName, DBSERVER (input)
#
# Writes:
#   - SQL Server protocol registry settings + Linked Servers on the selected lanes
# ===================================================================================================

function Enable_SQL_Protocols_On_Selected_Lanes
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[Parameter(Mandatory = $false)]
		[string]$tcpPort = "1433",
		[Parameter(Mandatory = $false)]
		[switch]$CreateLinkedServers
	)

	# ---- Default CreateLinkedServers to $true if omitted -------------------------------------------
	if (-not $PSBoundParameters.ContainsKey('CreateLinkedServers')) { $CreateLinkedServers = $true }

	Write_Log "`r`n==================== Starting Enable_SQL_Protocols_On_Selected_Lanes ====================`r`n" "blue"

	# ---- Resolve lane -> machine -------------------------------------------------------------------
	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	if (-not $LaneNumToMachineName -or $LaneNumToMachineName.Count -eq 0)
	{
		Write_Log "No lanes available. Please retrieve nodes first." "red"
		Write_Log "`r`n==================== Enable_SQL_Protocols_On_Selected_Lanes Completed ====================" "blue"
		return
	}

	# ---- Local SQL instance for linked-server operations -------------------------------------------
	$localInstance = $script:FunctionResults['DBSERVER']
	if ([string]::IsNullOrWhiteSpace($localInstance) -or $localInstance -eq 'N/A') { $localInstance = 'localhost' }

	# ---- Lane selection UI -------------------------------------------------------------------------
	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
	if (-not $selection -or -not $selection.Lanes -or $selection.Lanes.Count -eq 0)
	{
		Write_Log "No lanes selected or selection cancelled. Exiting." "yellow"
		Write_Log "`r`n==================== Enable_SQL_Protocols_On_Selected_Lanes Completed ====================" "blue"
		return
	}

	# ---- Normalize lane list (ensure 3-digit strings) ----------------------------------------------
	$lanes =
	$selection.Lanes |
	ForEach-Object {
		if ($_ -is [pscustomobject] -and $_.LaneNumber) { $_.LaneNumber }
		else { $_ }
	} |
	ForEach-Object { $_.ToString().PadLeft(3, '0') } |
	Sort-Object -Unique

	Write_Log "Selected lanes: $($lanes -join ', ')" "green"

	# ---- Prepare caches used elsewhere in your script ----------------------------------------------
	if (-not $script:LaneProtocols) { $script:LaneProtocols = @{ } }
	if (-not $script:ProtocolResults) { $script:ProtocolResults = @() }

	# ---- Create a runspace pool (MTA). Throttle to a reasonable degree of parallelism --------------
	$maxThreads = [Math]::Min($lanes.Count, [Math]::Max(2, [Environment]::ProcessorCount))
	$pool = [RunspaceFactory]::CreateRunspacePool(1, $maxThreads)
	$pool.ApartmentState = 'MTA'
	$pool.Open()

	# ---- Script that each runspace will execute (NO nested functions; just inline code) ------------
	$laneWork = @'
param($machine,$lane,$StoreNumber,$tcpPort,$createLinks,$localInstance)

# Per-lane output buffer; we send it back as a single PSCustomObject
$out = @()
$laneNeedsRestart = $false
$protocol = "File"           # default; changed after probe/DMV
$creationTransport = $null   # remember which transport we CREATE with (TCP/NP)
$createdAndTested = $false   # becomes true if linked server SELECT works

try {
    # --- Opening banner ---------------------------------------------------------------------------
    $out += [pscustomobject]@{ Text = "`r`n--- Processing Machine: $machine (Store $StoreNumber, Lane $lane) ---"; Color = "blue" }
    $out += [pscustomobject]@{ Text = "Ensuring RemoteRegistry is running on $machine..."; Color = "gray" }

    # Start RemoteRegistry on-demand; ignore console noise
    sc.exe "\\$machine" config RemoteRegistry start= demand | Out-Null
    sc.exe "\\$machine" start RemoteRegistry | Out-Null

    # --- Open remote HKLM -------------------------------------------------------------------------
    $reg = [Microsoft.Win32.RegistryKey]::OpenRemoteBaseKey('LocalMachine', $machine)

    # --- Enumerate SQL instances from both 64/32-bit locations -----------------------------------
    $instances = @{}
    foreach ($root in @(
        "SOFTWARE\\Microsoft\\Microsoft SQL Server\\Instance Names\\SQL",
        "SOFTWARE\\Wow6432Node\\Microsoft\\Microsoft SQL Server\\Instance Names\\SQL"
    )) {
        $k = $reg.OpenSubKey($root)
        if ($k) {
            foreach ($n in $k.GetValueNames()) {
                $id = $k.GetValue($n)
                if ($id -and -not $instances.ContainsKey($n)) { $instances[$n] = $id }
            }
            $k.Close()
        }
    }

    if ($instances.Count -eq 0) {
        $out += [pscustomobject]@{ Text = "No SQL instances found on $machine."; Color = "yellow" }
        $reg.Close()
    }
    else {
        foreach ($instanceName in $instances.Keys) {
            $instanceID = $instances[$instanceName]
            $out += [pscustomobject]@{ Text = "Processing SQL Instance: $instanceName (ID: $instanceID)"; Color = "blue" }
            $needsRestart = $false

            # ---- Enable Mixed Mode (LoginMode=2) -------------------------------------------------
            foreach ($authPath in @(
                "SOFTWARE\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer",
                "SOFTWARE\\Wow6432Node\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer"
            )) {
                $k = $reg.OpenSubKey($authPath, $true)
                if ($k) {
                    if ($k.GetValue("LoginMode", 1) -ne 2) {
                        $k.SetValue("LoginMode", 2, [Microsoft.Win32.RegistryValueKind]::DWord)
                        $out += [pscustomobject]@{ Text = "Mixed Mode Authentication enabled at $authPath."; Color = "green" }
                        $needsRestart = $true
                    } else {
                        $out += [pscustomobject]@{ Text = "Mixed Mode Authentication already enabled at $authPath."; Color = "gray" }
                    }
                    $k.Close(); break
                }
            }

            # ---- Enable TCP ----------------------------------------------------------------------
            foreach ($p in @(
                "SOFTWARE\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer\\SuperSocketNetLib\\Tcp",
                "SOFTWARE\\Wow6432Node\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer\\SuperSocketNetLib\\Tcp"
            )) {
                $k = $reg.OpenSubKey($p, $true)
                if ($k) {
                    if ($k.GetValue('Enabled', 0) -ne 1) {
                        $k.SetValue('Enabled', 1, [Microsoft.Win32.RegistryValueKind]::DWord)
                        $out += [pscustomobject]@{ Text = "TCP/IP protocol enabled at $p."; Color = "green" }
                        $needsRestart = $true
                    } else {
                        $out += [pscustomobject]@{ Text = "TCP/IP already enabled at $p."; Color = "gray" }
                    }
                    $k.Close(); break
                }
            }

            # ---- Set static port and clear dynamic -----------------------------------------------
            foreach ($p in @(
                "SOFTWARE\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer\\SuperSocketNetLib\\Tcp\\IPAll",
                "SOFTWARE\\Wow6432Node\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer\\SuperSocketNetLib\\Tcp\\IPAll"
            )) {
                $k = $reg.OpenSubKey($p, $true)
                if ($k) {
                    $curPort = $k.GetValue('TcpPort', "")
                    $curDyn  = $k.GetValue('TcpDynamicPorts', "")
                    if ($curPort -ne $tcpPort -or $curDyn -ne "") {
                        $k.SetValue('TcpPort', $tcpPort, [Microsoft.Win32.RegistryValueKind]::String)
                        $k.SetValue('TcpDynamicPorts', '', [Microsoft.Win32.RegistryValueKind]::String)
                        $out += [pscustomobject]@{ Text = "Registry port set to $tcpPort at $p."; Color = "green" }
                        $needsRestart = $true
                    } else {
                        $out += [pscustomobject]@{ Text = "TCP port already set to $tcpPort at $p."; Color = "gray" }
                    }
                    $k.Close(); break
                }
            }

            # ---- Enable Named Pipes --------------------------------------------------------------
            foreach ($p in @(
                "SOFTWARE\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer\\SuperSocketNetLib\\Np",
                "SOFTWARE\\Wow6432Node\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer\\SuperSocketNetLib\\Np"
            )) {
                $k = $reg.OpenSubKey($p, $true)
                if ($k) {
                    if ($k.GetValue('Enabled', 0) -ne 1) {
                        $k.SetValue('Enabled', 1, [Microsoft.Win32.RegistryValueKind]::DWord)
                        $out += [pscustomobject]@{ Text = "Named Pipes protocol enabled at $p."; Color = "green" }
                        $needsRestart = $true
                    } else {
                        $out += [pscustomobject]@{ Text = "Named Pipes already enabled at $p."; Color = "gray" }
                    }
                    $k.Close(); break
                }
            }

            # ---- Enable Shared Memory ------------------------------------------------------------
            foreach ($p in @(
                "SOFTWARE\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer\\SuperSocketNetLib\\Sm",
                "SOFTWARE\\Wow6432Node\\Microsoft\\Microsoft SQL Server\\$instanceID\\MSSQLServer\\SuperSocketNetLib\\Sm"
            )) {
                $k = $reg.OpenSubKey($p, $true)
                if ($k) {
                    if ($k.GetValue('Enabled', 0) -ne 1) {
                        $k.SetValue('Enabled', 1, [Microsoft.Win32.RegistryValueKind]::DWord)
                        $out += [pscustomobject]@{ Text = "Shared Memory protocol enabled at $p."; Color = "green" }
                        $needsRestart = $true
                    } else {
                        $out += [pscustomobject]@{ Text = "Shared Memory already enabled at $p."; Color = "gray" }
                    }
                    $k.Close(); break
                }
            }

            # ---- Restart SQL service if any change ----------------------------------------------
            if ($needsRestart) {
                $svcName = if ($instanceName -eq 'MSSQLSERVER') { 'MSSQLSERVER' } else { "MSSQL`$$instanceName" }
                $out += [pscustomobject]@{ Text = "Restarting SQL Service $svcName on $machine..."; Color = "gray" }
                # sc.exe returns at once; wait for STOPPED (1) / RUNNING (4), 60 s each at most
                sc.exe "\\$machine" stop $svcName | Out-Null
                for ($i = 0; $i -lt 60; $i++) {
                    if ((sc.exe "\\$machine" query $svcName | Out-String) -match 'STATE\s+:\s+1\s') { break }
                    Start-Sleep -Seconds 1
                }
                sc.exe "\\$machine" start $svcName | Out-Null
                $running = $false
                for ($i = 0; $i -lt 60; $i++) {
                    if ((sc.exe "\\$machine" query $svcName | Out-String) -match 'STATE\s+:\s+4\s') { $running = $true; break }
                    Start-Sleep -Seconds 1
                }
                if ($running) { $out += [pscustomobject]@{ Text = "SQL Service $svcName restarted successfully on $machine."; Color = "green" } }
                else { $out += [pscustomobject]@{ Text = "SQL Service $svcName on $machine did not report RUNNING within 60 seconds - check it on the lane."; Color = "red" } }
                $laneNeedsRestart = $true
            } else {
                $out += [pscustomobject]@{ Text = "No protocol/auth changes for $instanceName on $machine. No restart needed."; Color = "green" }
            }
        } # foreach instance

        $reg.Close()
    }

    # --- Quick transport probe: TCP then NP --------------------------------------------------------
    try {
        $tcpClient = New-Object System.Net.Sockets.TcpClient
        $task = $tcpClient.ConnectAsync($machine, [int]$tcpPort)
        if ($task.Wait(1500) -and $tcpClient.Connected) {
            $tcpClient.Close()
            $protocol = "TCP"
        }
        else {
            $npCs = "Server=np:\\$machine\pipe\sql\query;Database=master;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;Connection Timeout=5"
            $cn = New-Object System.Data.SqlClient.SqlConnection $npCs
            try {
                $cn.Open()
                $cmd = $cn.CreateCommand(); $cmd.CommandText = "SELECT 1"; $cmd.CommandTimeout = 2
                [void]$cmd.ExecuteScalar()
                $protocol = "Named Pipes"
            } catch { } finally { $cn.Close() }
        }
    } catch { }

    if ($protocol -eq 'File') {
        $out += [pscustomobject]@{ Text = "Pre-probe did not confirm TCP or NP (likely timeouts). Will use Linked Server live test to confirm."; Color = "yellow" }
    }

    # --- Linked server creation and live test (optional) -------------------------------------------
    if ($createLinks) {
        # Provider preference; try to filter by installed list (best effort).
        $pref = @('SQLOLEDB','MSOLEDBSQL','SQLNCLI11','SQLNCLI','MSDASQL')
        try {
            $cs = "Server=$localInstance;Database=master;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;Connection Timeout=8"
            $cn = New-Object System.Data.SqlClient.SqlConnection $cs
            $cn.Open()
            try {
                $cmd = $cn.CreateCommand(); $cmd.CommandTimeout = 8; $cmd.CommandText = "EXEC master.sys.sp_enum_oledb_providers;"
                $rdr = $cmd.ExecuteReader()
                $dt = New-Object System.Data.DataTable
                $dt.Load($rdr)
                $installed = @()
                foreach ($row in $dt.Rows) {
                    $col = if ($dt.Columns.Contains('name')) { 'name' } elseif ($dt.Columns.Contains('PROGID')) { 'PROGID' } else { $dt.Columns[0].ColumnName }
                    $installed += [string]$row[$col]
                }
                if ($installed.Count -gt 0) {
                    $pref2 = @()
                    foreach ($p in $pref) { if ($installed -contains $p) { $pref2 += $p } }
                    if ($pref2.Count -gt 0) { $pref = $pref2 }
                }
            } finally { $cn.Close() }
        } catch { }

        $tcpDataSource = "tcp:$machine,$tcpPort"
        $linkName = $machine
        $firstCreatedProv = $null
        $firstCreatedTsql = $null

        foreach ($prov in $pref) {
            try {
                $optTsql = "BEGIN TRY EXEC master.dbo.sp_MSset_oledb_prop N'$prov', N'AllowInProcess', 1; END TRY BEGIN CATCH END CATCH;
BEGIN TRY EXEC master.dbo.sp_MSset_oledb_prop N'$prov', N'DynamicParameters', 1; END TRY BEGIN CATCH END CATCH;"

                if ($prov -ne 'MSDASQL') {
                    if ($protocol -eq 'TCP') {
                        $creationTransport = 'TCP'
                        $createTsql = @"
IF EXISTS(SELECT 1 FROM sys.servers WHERE name=N'$linkName')
    EXEC master.dbo.sp_dropserver @server=N'$linkName', @droplogins='droplogins';
$optTsql
EXEC master.dbo.sp_addlinkedserver @server=N'$linkName', @srvproduct=N'', @provider=N'$prov', @datasrc=N'$tcpDataSource';
EXEC master.dbo.sp_serveroption N'$linkName', N'data access', N'true';
EXEC master.dbo.sp_serveroption N'$linkName', N'use remote collation', N'true';
EXEC master.dbo.sp_serveroption N'$linkName', N'rpc out', N'true';
IF NOT EXISTS (SELECT 1 FROM sys.linked_logins ll JOIN sys.servers s ON s.server_id=ll.server_id WHERE s.name=N'$linkName')
    EXEC master.dbo.sp_addlinkedsrvlogin @rmtsrvname=N'$linkName', @useself='TRUE';
"@
                    }
                    else {
                        $creationTransport = 'Named Pipes'
                        $createTsql = @"
IF EXISTS(SELECT 1 FROM sys.servers WHERE name=N'$linkName')
    EXEC master.dbo.sp_dropserver @server=N'$linkName', @droplogins='droplogins';
$optTsql
EXEC master.dbo.sp_addlinkedserver
    @server=N'$linkName', @srvproduct=N'', @provider=N'$prov',
    @datasrc=N'\\$machine\pipe\sql\query', @provstr=N'Network Library=dbnmpntw';
EXEC master.dbo.sp_serveroption N'$linkName', N'data access', N'true';
EXEC master.dbo.sp_serveroption N'$linkName', N'use remote collation', N'true';
EXEC master.dbo.sp_serveroption N'$linkName', N'rpc out', N'true';
IF NOT EXISTS (SELECT 1 FROM sys.linked_logins ll JOIN sys.servers s ON s.server_id=ll.server_id WHERE s.name=N'$linkName')
    EXEC master.dbo.sp_addlinkedsrvlogin @rmtsrvname=N'$linkName', @useself='TRUE';
"@
                    }
                }
                else {
                    if ($protocol -eq 'TCP') {
                        $creationTransport = 'TCP'
                        $provstr18 = "Driver={ODBC Driver 18 for SQL Server};Server=$machine,$tcpPort;Trusted_Connection=Yes;TrustServerCertificate=Yes;"
                        $provstr17 = "Driver={ODBC Driver 17 for SQL Server};Server=$machine,$tcpPort;Trusted_Connection=Yes;TrustServerCertificate=Yes;"
                    }
                    else {
                        $creationTransport = 'Named Pipes'
                        $npServer = "np:\\$machine\pipe\sql\query"
                        $provstr18 = "Driver={ODBC Driver 18 for SQL Server};Server=$npServer;Trusted_Connection=Yes;TrustServerCertificate=Yes;"
                        $provstr17 = "Driver={ODBC Driver 17 for SQL Server};Server=$npServer;Trusted_Connection=Yes;TrustServerCertificate=Yes;"
                    }
                    $createTsql = @"
IF EXISTS(SELECT 1 FROM sys.servers WHERE name=N'$linkName')
    EXEC master.dbo.sp_dropserver @server=N'$linkName', @droplogins='droplogins';
$optTsql
DECLARE @ok bit = 0;
BEGIN TRY
    EXEC master.dbo.sp_addlinkedserver @server=N'$linkName', @srvproduct=N'', @provider=N'MSDASQL', @provstr=N'$provstr18';
    SET @ok = 1;
END TRY BEGIN CATCH END CATCH;
IF (@ok = 0)
BEGIN TRY
    EXEC master.dbo.sp_addlinkedserver @server=N'$linkName', @srvproduct=N'', @provider=N'MSDASQL', @provstr=N'$provstr17';
    SET @ok = 1;
END TRY BEGIN CATCH END CATCH;
IF (@ok = 1)
BEGIN
    EXEC master.dbo.sp_serveroption N'$linkName', N'data access', N'true';
    EXEC master.dbo.sp_serveroption N'$linkName', N'use remote collation', N'true';
    EXEC master.dbo.sp_serveroption N'$linkName', N'rpc out', N'true';
    IF NOT EXISTS (SELECT 1 FROM sys.linked_logins ll JOIN sys.servers s ON s.server_id=ll.server_id WHERE s.name=N'$linkName')
        EXEC master.dbo.sp_addlinkedsrvlogin @rmtsrvname=N'$linkName', @useself='TRUE';
END
ELSE
BEGIN
    RAISERROR('MSDASQL addlinkedserver failed for both ODBC 18 and 17', 11, 1);
END
"@
                }

                # -- Execute the CREATE script
                $cs = "Server=$localInstance;Database=master;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;Connection Timeout=30"
                $cn = New-Object System.Data.SqlClient.SqlConnection $cs
                $cn.Open()
                try {
                    $cmd = $cn.CreateCommand()
                    $cmd.CommandTimeout = 30
                    $cmd.CommandText = $createTsql
                    [void]$cmd.ExecuteNonQuery()
                } finally { $cn.Close() }

                if (-not $firstCreatedProv) { $firstCreatedProv = $prov; $firstCreatedTsql = $createTsql }

                # -- Live test (no MSDTC): query remote master via linked server
                $testOk = $false
                $cs = "Server=$localInstance;Database=master;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;Connection Timeout=8"
                $cn = New-Object System.Data.SqlClient.SqlConnection $cs
                $cn.Open()
                try {
                    $cmd = $cn.CreateCommand()
                    $cmd.CommandTimeout = 8
                    $cmd.CommandText = "SELECT TOP 1 name FROM [$linkName].master.sys.databases"
                    $rdr = $cmd.ExecuteReader()
                    $dt = New-Object System.Data.DataTable
                    $dt.Load($rdr)
                    $testOk = ($dt -ne $null)
                } catch {
                    $testOk = $false
                } finally { $cn.Close() }

                if ($testOk) {
                    $createdAndTested = $true
                    # Try to detect the actual transport on the remote side via DMV
                    $normalized = $false
                    try {
                        $cs = "Server=$localInstance;Database=master;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;Connection Timeout=8"
                        $cn = New-Object System.Data.SqlClient.SqlConnection $cs
                        $cn.Open()
                        try {
                            $cmd = $cn.CreateCommand()
                            $cmd.CommandTimeout = 8
                            $cmd.CommandText = "EXEC ('SELECT TOP 1 net_transport FROM sys.dm_exec_connections WHERE session_id = @@SPID') AT [$linkName]"
                            $rdr = $cmd.ExecuteReader()
                            $dt = New-Object System.Data.DataTable
                            $dt.Load($rdr)
                            if ($dt -and $dt.Rows.Count -gt 0) {
                                $rt = [string]$dt.Rows[0][0]
                                if ($rt -match 'TCP')    { $protocol = 'TCP';          $normalized = $true }
                                elseif ($rt -match 'Named') { $protocol = 'Named Pipes'; $normalized = $true }
                                elseif ($rt -match 'Shared') { $protocol = 'Shared Memory'; $normalized = $true }
                                $out += [pscustomobject]@{ Text = "Remote net_transport via [$linkName]: $rt" + ($(if ($normalized) { " (persisting as '$protocol')" } else { "" })); Color = "gray" }
                            }
                        } finally { $cn.Close() }
                    } catch { }

                    if (-not $normalized -or [string]::IsNullOrWhiteSpace($protocol) -or $protocol -eq 'File') { $protocol = $creationTransport }
                    $out += [pscustomobject]@{ Text = "Linked Server [$linkName] created via provider '$prov' over $protocol - **LIVE TEST PASSED**."; Color = "green" }
                    break
                }
                else {
                    # Drop and try next provider
                    try {
                        $cs = "Server=$localInstance;Database=master;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;Connection Timeout=15"
                        $cn = New-Object System.Data.SqlClient.SqlConnection $cs
                        $cn.Open()
                        try {
                            $cmd = $cn.CreateCommand()
                            $cmd.CommandTimeout = 15
                            $cmd.CommandText = "EXEC master.dbo.sp_dropserver @server=N'$linkName', @droplogins='droplogins';"
                            [void]$cmd.ExecuteNonQuery()
                        } finally { $cn.Close() }
                    } catch { }
                    $out += [pscustomobject]@{ Text = "Provider '$prov' created [$linkName] over $creationTransport but live test FAILED - trying next provider..."; Color = "yellow" }
                }
            }
            catch {
                $out += [pscustomobject]@{ Text = "Provider '$prov' failed to create Linked Server [$linkName] - trying next provider..."; Color = "gray" }
            }
        } # foreach provider

        if (-not $createdAndTested -and $firstCreatedProv) {
            # Leave a creatable provider so admin can map a SQL login later
            try {
                $cs = "Server=$localInstance;Database=master;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;Connection Timeout=30"
                $cn = New-Object System.Data.SqlClient.SqlConnection $cs
                $cn.Open()
                try {
                    $cmd = $cn.CreateCommand()
                    $cmd.CommandTimeout = 30
                    $cmd.CommandText = $firstCreatedTsql
                    [void]$cmd.ExecuteNonQuery()
                } finally { $cn.Close() }
            } catch { }
            if ($protocol -eq 'File' -or [string]::IsNullOrWhiteSpace($protocol)) { $protocol = $creationTransport }
            $out += [pscustomobject]@{ Text = "No provider passed live test. Re-created [$linkName] using '$firstCreatedProv' over $protocol so you can map a SQL login if needed."; Color = "yellow" }
        }
        elseif (-not $createdAndTested -and -not $firstCreatedProv) {
            $out += [pscustomobject]@{ Text = "All provider attempts failed creating Linked Server [$linkName]."; Color = "red" }
        }
    }
    else {
        $out += [pscustomobject]@{ Text = "CreateLinkedServers disabled; skipped Linked Server creation."; Color = "gray" }
    }
}
catch {
    $out += [pscustomobject]@{ Text = "Failed to process [$machine]: $_"; Color = "red" }
    $protocol = "File"
}

# Final guard to avoid returning 'File' on success
if ($createdAndTested -and ($protocol -eq 'File' -or [string]::IsNullOrWhiteSpace($protocol))) {
    $protocol = $creationTransport
}

# Return structured result (parent thread will log and persist)
[pscustomobject]@{
    Output    = $out
    Protocol  = $protocol
    Lane      = $lane
    Machine   = $machine
    Restarted = $laneNeedsRestart
}
'@

	# ---- Launch all lanes in parallel via runspaces -----------------------------------------------
	$tasks = @()
	foreach ($lane in $lanes)
	{
		$machine = $LaneNumToMachineName[$lane]
		if (-not $machine)
		{
			Write_Log "Machine name not found for lane $lane. Skipping." "yellow"
			continue
		}

		# Create PowerShell instance bound to the runspace pool
		$ps = [PowerShell]::Create()
		$ps.RunspacePool = $pool
		# IMPORTANT: pass a pure boolean for $createLinks
		$ps.AddScript($laneWork).AddArgument($machine).AddArgument($lane).AddArgument($StoreNumber).AddArgument($tcpPort).AddArgument([bool]$CreateLinkedServers.IsPresent).AddArgument($localInstance) | Out-Null

		$handle = $ps.BeginInvoke()
		$tasks += [pscustomobject]@{ Lane = $lane; Machine = $machine; PS = $ps; Handle = $handle; Done = $false }
	}

	# ---- Collect results as lanes complete (quasi-live) -------------------------------------------
	$restarted = @()
	while ($true)
	{
		$allDone = $true
		foreach ($t in $tasks)
		{
			if (-not $t.Done)
			{
				if ($t.Handle.IsCompleted)
				{
					# Finish and dispose
					$res = $t.PS.EndInvoke($t.Handle)
					$t.PS.Dispose()
					$t.Done = $true

					# Emit buffered logs for this lane
					foreach ($line in $res.Output) { Write_Log $line.Text $line.Color }

					# Persist in-memory protocol maps
					$script:LaneProtocols[$res.Lane] = $res.Protocol
					$script:ProtocolResults = @($script:ProtocolResults | Where-Object { $_.Lane -ne $res.Lane })
					$script:ProtocolResults += [PSCustomObject]@{ Lane = $res.Lane; Protocol = $res.Protocol }

					# Persist to file (dedup by lane)
					$protocolResultsFile = $script:ProtocolResultsFile
					$laneStr = $res.Lane.ToString().PadLeft(3, '0')
					$proto = $res.Protocol
					$dir = [System.IO.Path]::GetDirectoryName($protocolResultsFile)
					if (-not (Test-Path $dir)) { New-Item -Path $dir -ItemType Directory -Force | Out-Null }
					if (-not (Test-Path $protocolResultsFile)) { New-Item -Path $protocolResultsFile -ItemType File -Force | Out-Null }
					# Keep every other lane's line, replace this lane's (arrays stay arrays: a single
					# remaining line used to collapse to a string and += glued two lines together)
					$all = @(Get-Content -LiteralPath $protocolResultsFile -ErrorAction SilentlyContinue | Where-Object { $_ -match '\S' -and $_ -notmatch "^\s*0*${laneStr}\s*," })
					$all += "$laneStr,$proto"
					$sorted = [string[]]@($all | Sort-Object { ($_ -split ',')[0] -as [int] })
					[System.IO.File]::WriteAllLines($protocolResultsFile, $sorted, [System.Text.Encoding]::UTF8)

					if ($proto -eq 'File' -and -not [string]::IsNullOrWhiteSpace($res.Machine))
					{
						# Menu action: report the scheduling outcome in the log box.
						# (Failures log their own red line from inside the function.)
						$schedOk = $false
						try
						{
							$schedOk = [bool](Ensure_SQL_Enable_Scheduled_Task_For_File_Lane -LaneNumber $laneStr -MachineName $res.Machine)
						}
						catch { }
						if ($schedOk)
						{
							$schedState = $null
							try { $schedState = $script:LaneSqlProtocolEnableTaskState[$laneStr] } catch { }
							$whenText = if ($schedState -and $schedState.ScheduledFor) { [string]$schedState.ScheduledFor.ToString('MM/dd/yyyy HH:mm') } else { 'next 4:15 AM' }
							Write_Log ("Scheduled SQL enable for {0} (Lane {1}) for {2}" -f $res.Machine, $laneStr, $whenText) 'green'
						}
					}
					elseif ($script:LaneSqlProtocolEnableTaskState -and $script:LaneSqlProtocolEnableTaskState.ContainsKey($laneStr))
					{
						$script:LaneSqlProtocolEnableTaskState[$laneStr] = [pscustomobject]@{
							TaskPresent  = $false
							LastChecked  = Get-Date
							ScheduledFor = $null
							MachineName  = $res.Machine
						}
					}

					if ($res.Restarted) { $restarted += $res.Lane }

					# Final per-lane summary line
					Write_Log "Protocol detected for $($res.Machine) (Lane $($res.Lane)): $proto" "magenta"
				}
				else
				{
					$allDone = $false
				}
			}
		}
		if ($allDone) { break }
		Start-Sleep -Milliseconds 150
	}

	# ---- Cleanup pool -----------------------------------------------------------------------------
	$pool.Close()
	$pool.Dispose()

	# ---- Post-actions for lanes that needed restart -----------------------------------------------
	if ($restarted.Count -gt 0)
	{
		Send_Restart_All_Programs -StoreNumber $StoreNumber -LaneNumbers $restarted -Silent
		Write_Log "Restart All Programs sent to restarted lanes: $($restarted -join ', ')" "green"
	}

	Write_Log "`r`n==================== Enable_SQL_Protocols_On_Selected_Lanes Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Ensure_SQL_Enable_Scheduled_Task_For_File_Lane
# ---------------------------------------------------------------------------------------------------
# Description:
#   For a lane stuck on the SQL File protocol, writes a self-deleting one-shot PowerShell
#   worker to the lane's Storeman Temp share and schedules it for 4:15 AM (next occurrence).
#   The worker enables TCP (static port), Named Pipes and Shared Memory, restarts SQL when
#   changed, then deletes its scheduled task and itself. Every failure path (no writable
#   Temp share, worker write error, schtasks /Create error) is logged red with the detail.
#
# Parameters:
#   - LaneNumber  [string]: lane to schedule (required)
#   - MachineName [string]: lane machine name (required)
#   - TcpPort     [string]: static TCP port to enable (default '1433')
#   - StartTime   [string]: task start time (default '04:15')
#
# Variables:
#   - $script:LaneSqlProtocolEnableTaskState: per-lane scheduling state
#
# Returns:
#   $true when the task was (re)scheduled successfully, $false otherwise.
#
# Writes:
#   - Enable_SQL_Protocols_Lane_<n>.ps1 on the lane Storeman Temp share + one-shot task
# ===================================================================================================

function Ensure_SQL_Enable_Scheduled_Task_For_File_Lane
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$LaneNumber,
		[Parameter(Mandatory = $true)]
		[string]$MachineName,
		[string]$TcpPort = '1433',
		[string]$StartTime = '04:15'
	)

	if ([string]::IsNullOrWhiteSpace($LaneNumber) -or [string]::IsNullOrWhiteSpace($MachineName)) { return $false }
	if (-not $script:LaneSqlProtocolEnableTaskState) { $script:LaneSqlProtocolEnableTaskState = @{ } }

	$laneKey = $LaneNumber.ToString().PadLeft(3, '0')
	$taskName = "Enable_SQL_Protocols_Lane_$laneKey"
	$scriptName = "${taskName}.ps1"
	$remoteScriptSharePath = $null
	$localScriptPath = $null
	$remoteTempCandidates = @(
		[pscustomobject]@{ Share = "\\$MachineName\Storeman\Temp"; Local = "C:\Storeman\Temp" },
		[pscustomobject]@{ Share = "\\$MachineName\c$\Storeman\Temp"; Local = "C:\Storeman\Temp" },
		[pscustomobject]@{ Share = "\\$MachineName\d$\Storeman\Temp"; Local = "D:\Storeman\Temp" },
		[pscustomobject]@{ Share = "\\$MachineName\e$\Storeman\Temp"; Local = "E:\Storeman\Temp" }
	)

	# Next occurrence of StartTime (HH:mm, default 04:15) - the /SD date must match /ST
	$startSpan = [TimeSpan]::FromMinutes(255)
	$parsedSpan = [TimeSpan]::Zero
	if ([TimeSpan]::TryParse($StartTime, [ref]$parsedSpan)) { $startSpan = $parsedSpan }
	$scheduledDate = (Get-Date).Date.Add($startSpan)
	if ((Get-Date) -ge $scheduledDate) { $scheduledDate = $scheduledDate.AddDays(1) }
	$scheduledDateText = $scheduledDate.ToString('MM/dd/yyyy')

	$workerScript = @'
param(
    [string]$TaskName,
    [string]$TcpPort = '1433'
)

$ErrorActionPreference = 'Continue'

try { Add-Type -AssemblyName System.Core | Out-Null } catch { }

$instanceRoots = @(
    'SOFTWARE\Microsoft\Microsoft SQL Server\Instance Names\SQL',
    'SOFTWARE\Wow6432Node\Microsoft\Microsoft SQL Server\Instance Names\SQL'
)

$instanceMap = @{}
foreach ($root in $instanceRoots)
{
    try
    {
        $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($root)
        if ($k)
        {
            foreach ($name in $k.GetValueNames())
            {
                $id = $k.GetValue($name)
                if ($id -and -not $instanceMap.ContainsKey($name)) { $instanceMap[$name] = $id }
            }
            $k.Close()
        }
    }
    catch { }
}

$servicesToRestart = New-Object System.Collections.Generic.List[string]

foreach ($instanceName in $instanceMap.Keys)
{
    $instanceId = $instanceMap[$instanceName]
    $needsRestart = $false

    foreach ($authPath in @(
        "SOFTWARE\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer",
        "SOFTWARE\Wow6432Node\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer"
    ))
    {
        try
        {
            $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($authPath, $true)
            if ($k)
            {
                if ($k.GetValue('LoginMode', 1) -ne 2)
                {
                    $k.SetValue('LoginMode', 2, [Microsoft.Win32.RegistryValueKind]::DWord)
                    $needsRestart = $true
                }
                $k.Close()
                break
            }
        }
        catch { }
    }

    foreach ($tcpPath in @(
        "SOFTWARE\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer\SuperSocketNetLib\Tcp",
        "SOFTWARE\Wow6432Node\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer\SuperSocketNetLib\Tcp"
    ))
    {
        try
        {
            $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($tcpPath, $true)
            if ($k)
            {
                if ($k.GetValue('Enabled', 0) -ne 1)
                {
                    $k.SetValue('Enabled', 1, [Microsoft.Win32.RegistryValueKind]::DWord)
                    $needsRestart = $true
                }
                $k.Close()
                break
            }
        }
        catch { }
    }

    foreach ($ipAllPath in @(
        "SOFTWARE\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer\SuperSocketNetLib\Tcp\IPAll",
        "SOFTWARE\Wow6432Node\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer\SuperSocketNetLib\Tcp\IPAll"
    ))
    {
        try
        {
            $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($ipAllPath, $true)
            if ($k)
            {
                $curPort = [string]$k.GetValue('TcpPort', '')
                $curDyn = [string]$k.GetValue('TcpDynamicPorts', '')
                if ($curPort -ne $TcpPort -or $curDyn -ne '')
                {
                    $k.SetValue('TcpPort', $TcpPort, [Microsoft.Win32.RegistryValueKind]::String)
                    $k.SetValue('TcpDynamicPorts', '', [Microsoft.Win32.RegistryValueKind]::String)
                    $needsRestart = $true
                }
                $k.Close()
                break
            }
        }
        catch { }
    }

    foreach ($npPath in @(
        "SOFTWARE\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer\SuperSocketNetLib\Np",
        "SOFTWARE\Wow6432Node\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer\SuperSocketNetLib\Np"
    ))
    {
        try
        {
            $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($npPath, $true)
            if ($k)
            {
                if ($k.GetValue('Enabled', 0) -ne 1)
                {
                    $k.SetValue('Enabled', 1, [Microsoft.Win32.RegistryValueKind]::DWord)
                    $needsRestart = $true
                }
                $k.Close()
                break
            }
        }
        catch { }
    }

    foreach ($smPath in @(
        "SOFTWARE\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer\SuperSocketNetLib\Sm",
        "SOFTWARE\Wow6432Node\Microsoft\Microsoft SQL Server\$instanceId\MSSQLServer\SuperSocketNetLib\Sm"
    ))
    {
        try
        {
            $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($smPath, $true)
            if ($k)
            {
                if ($k.GetValue('Enabled', 0) -ne 1)
                {
                    $k.SetValue('Enabled', 1, [Microsoft.Win32.RegistryValueKind]::DWord)
                    $needsRestart = $true
                }
                $k.Close()
                break
            }
        }
        catch { }
    }

    if ($needsRestart)
    {
        $svcName = if ($instanceName -eq 'MSSQLSERVER') { 'MSSQLSERVER' } else { "MSSQL`$$instanceName" }
        if (-not $servicesToRestart.Contains($svcName)) { [void]$servicesToRestart.Add($svcName) }
    }
}

foreach ($svcName in $servicesToRestart)
{
    try
    {
        Restart-Service -Name $svcName -Force -ErrorAction Stop
    }
    catch
    {
        try { sc.exe stop $svcName | Out-Null } catch { }
        Start-Sleep -Seconds 8
        try { sc.exe start $svcName | Out-Null } catch { }
        Start-Sleep -Seconds 5
    }
}

try { schtasks.exe /Delete /TN $TaskName /F | Out-Null } catch { }
try { Start-Process -FilePath 'cmd.exe' -ArgumentList '/c', "ping 127.0.0.1 -n 3 >nul & del /f /q `"$PSCommandPath`"" -WindowStyle Hidden } catch { }
'@

	try
	{
		foreach ($candidate in $remoteTempCandidates)
		{
			try
			{
				if (-not (Test-Path -LiteralPath $candidate.Share))
				{
					New-Item -Path $candidate.Share -ItemType Directory -Force -ErrorAction Stop | Out-Null
				}
				$probeFile = Join-Path $candidate.Share ("_tbs_probe_{0}.tmp" -f $laneKey)
				Set-Content -LiteralPath $probeFile -Value "probe" -Encoding ASCII -Force -ErrorAction Stop
				Remove-Item -LiteralPath $probeFile -Force -ErrorAction SilentlyContinue
				$remoteScriptSharePath = Join-Path $candidate.Share $scriptName
				$localScriptPath = [System.IO.Path]::Combine($candidate.Local, $scriptName)
				break
			}
			catch
			{
			}
		}
	}
	catch
	{
	}

	if ([string]::IsNullOrWhiteSpace($remoteScriptSharePath) -or [string]::IsNullOrWhiteSpace($localScriptPath))
	{
		try { Write_Log ("Could not schedule SQL enable task for lane {0}: no writable Storeman Temp share found on {1}" -f $laneKey, $MachineName) 'red' | Out-Null } catch { }
		$script:LaneSqlProtocolEnableTaskState[$laneKey] = [pscustomobject]@{
			TaskPresent  = $false
			LastChecked  = Get-Date
			ScheduledFor = $scheduledDate
			MachineName  = $MachineName
		}
		return $false
	}

	$null = & schtasks.exe /Query /S $MachineName /TN $taskName 2>$null
	$taskExists = ($LASTEXITCODE -eq 0)
	$scriptExists = $false
	try { $scriptExists = Test-Path -LiteralPath $remoteScriptSharePath }
	catch { $scriptExists = $false }
	if ($taskExists -and $scriptExists)
	{
		$script:LaneSqlProtocolEnableTaskState[$laneKey] = [pscustomobject]@{
			TaskPresent  = $true
			LastChecked  = Get-Date
			ScheduledFor = $scheduledDate
			MachineName  = $MachineName
		}
		return $true
	}
	elseif ($taskExists -and -not $scriptExists)
	{
		try { & schtasks.exe /Delete /S $MachineName /TN $taskName /F 2>$null | Out-Null }
		catch { }
	}

	try
	{
		Set-Content -LiteralPath $remoteScriptSharePath -Value $workerScript -Encoding UTF8 -Force -ErrorAction Stop
	}
	catch
	{
		try { Write_Log ("Could not schedule SQL enable task for lane {0}: failed to write worker script to {1}" -f $laneKey, $remoteScriptSharePath) 'red' | Out-Null } catch { }
		$script:LaneSqlProtocolEnableTaskState[$laneKey] = [pscustomobject]@{
			TaskPresent  = $false
			LastChecked  = Get-Date
			ScheduledFor = $scheduledDate
			MachineName  = $MachineName
		}
		return $false
	}

	$taskAction = "powershell.exe -NoProfile -ExecutionPolicy Bypass -File `"$localScriptPath`" -TaskName `"$taskName`" -TcpPort `"$TcpPort`""
	$createOutput = & schtasks.exe /Create /S $MachineName /RU SYSTEM /RL HIGHEST /SC ONCE /TN $taskName /TR $taskAction /ST $StartTime /SD $scheduledDateText /F 2>&1
	if ($LASTEXITCODE -eq 0)
	{
		$script:LaneSqlProtocolEnableTaskState[$laneKey] = [pscustomobject]@{
			TaskPresent  = $true
			LastChecked  = Get-Date
			ScheduledFor = $scheduledDate
			MachineName  = $MachineName
		}
		return $true
	}

	try { Remove-Item -LiteralPath $remoteScriptSharePath -Force -ErrorAction SilentlyContinue }
	catch { }
	$createOutputText = [string]($createOutput | Out-String)
	$createOutputText = $createOutputText.Trim()
	# Previously this output was computed and silently dropped - the failure was invisible.
	try { Write_Log ("Could not schedule SQL enable task for lane {0} on {1}: {2}" -f $laneKey, $MachineName, $createOutputText) 'red' | Out-Null } catch { }
	$script:LaneSqlProtocolEnableTaskState[$laneKey] = [pscustomobject]@{
		TaskPresent  = $false
		LastChecked  = Get-Date
		ScheduledFor = $scheduledDate
		MachineName  = $MachineName
	}
	return $false
}

# ===================================================================================================
#                              FUNCTION: Process_Lanes
# ---------------------------------------------------------------------------------------------------
# Description:
#   Runs the lane SQL maintenance (sections of the generated lane script) on the lanes the user
#   picks. Several lanes: the selected sections are dropped as Lane_Database_Maintenance.sqi
#   into each lane's XF folder. One lane: runs the sections directly over the lane's detected
#   SQL protocol (TCP / Named Pipes; on 'Login failed' it maps the current Windows login as
#   db_owner and retries once), falling back to the file drop when the lane is on File, the
#   protocol is not known yet, no SQL module is installed, or the direct run fails.
#
# Parameters:
#   - StoreNumber     [string]: store to process
#   - ProcessAllLanes [switch]: (not used - the lane picker decides)
#
# Variables:
#   - $script:FunctionResults: LaneNumToMachineName, MachineNameToLaneNum, SqlModuleName
#   - $script:LaneSQLScript / $script:LaneSQLFiltered: generated by Generate_SQL_Scripts
#   - $script:LaneProtocols: per-lane protocol from Start_Lane_Protocol_Jobs
#   - $script:ProcessedLanes: every lane processed this session (output)
#   - $OfficePath: Storeman Office root (XF lane folders)
# ===================================================================================================

function Process_Lanes
{
	param (
		[string]$StoreNumber,
		[switch]$ProcessAllLanes
	)

	Write_Log "`r`n==================== Starting Process_Lanes Function ====================`r`n" "blue"
	$done = { Write_Log "`r`n==================== Process_Lanes Function Completed ====================" "blue" }

	if (-not (Test-Path -LiteralPath $OfficePath))
	{
		Write_Log "XF Base Path not found: $OfficePath" "yellow"
		& $done
		return
	}
	if (-not $script:ProcessedLanes) { $script:ProcessedLanes = @() }

	# Invoke-Sqlcmd is only needed for the direct (single-lane) run; without it every lane
	# gets the file drop
	$InvokeSqlCmd = $null
	$SqlModuleName = $script:FunctionResults['SqlModuleName']
	if ($SqlModuleName -and $SqlModuleName -ne "None")
	{
		try
		{
			Import-Module $SqlModuleName -ErrorAction Stop
			$InvokeSqlCmd = Get-Command Invoke-Sqlcmd -Module $SqlModuleName -ErrorAction Stop
		}
		catch { Write_Log "SQL module '$SqlModuleName' could not be loaded ($($_.Exception.Message)) - lanes get the file drop." "yellow" }
	}
	else
	{
		Write_Log "No SQL PowerShell module - lanes get the file drop." "yellow"
	}

	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	if (-not $LaneNumToMachineName -or $LaneNumToMachineName.Count -eq 0)
	{
		Write_Log "No lanes available. Please retrieve nodes first." "red"
		& $done
		return
	}
	$MachineNameToLaneNum = $script:FunctionResults['MachineNameToLaneNum']
	if (-not $MachineNameToLaneNum) { $MachineNameToLaneNum = @{ } }

	# ----------------------------------------
	# Lanes
	# ----------------------------------------
	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
	if ($null -eq $selection)
	{
		Write_Log "Lane processing canceled by user." "yellow"
		& $done
		return
	}
	$Lanes = @($selection.Lanes | ForEach-Object { if ($_ -is [pscustomobject] -and $_.LaneNumber) { $_.LaneNumber } else { $_ } })
	if ($Lanes.Count -eq 0)
	{
		Write_Log "No lanes selected." "yellow"
		& $done
		return
	}

	# ----------------------------------------
	# Sections (the long-timeout wrapper sections are always added)
	# ----------------------------------------
	if (-not $script:LaneSQLScript)
	{
		try { Generate_SQL_Scripts -StoreNumber $StoreNumber | Out-Null }
		catch { }
	}
	$sectionPattern = '(?s)/\*\s*(?<SectionName>[^*/]+?)\s*\*/\s*(?<SQLCommands>(?:.(?!/\*)|.)*?)(?=(/\*|$))'
	$sectionMatches = @([regex]::Matches([string]$script:LaneSQLScript, $sectionPattern))
	if ($sectionMatches.Count -eq 0)
	{
		Write_Log "No sections found in Lane SQL script." "red"
		& $done
		return
	}

	$fixedSections = @("Set a long timeout so the entire script runs", "Clear the long database timeout")
	$allSectionNames = @($sectionMatches | ForEach-Object { $_.Groups['SectionName'].Value.Trim() } | Where-Object { $fixedSections -notcontains $_ })
	$SectionsToSend = Show_Section_Selection_Form -SectionNames $allSectionNames
	if (-not $SectionsToSend -or @($SectionsToSend).Count -eq 0)
	{
		Write_Log "No sections selected for lanes." "yellow"
		& $done
		return
	}

	# File-drop script (same for all lanes)
	$middleBlock = ($sectionMatches | Where-Object { $SectionsToSend -contains $_.Groups['SectionName'].Value.Trim() } | ForEach-Object {
			"/* $($_.Groups['SectionName'].Value.Trim()) */`r`n$($_.Groups['SQLCommands'].Value.Trim())"
		}) | Out-String
	$finalScript = "/* Set a long timeout so the entire script runs */`r`n@WIZRPL(DBASE_TIMEOUT=E);`r`n" +
	"--------------------------------------------------------------------------------`r`n" +
	$middleBlock +
	"--------------------------------------------------------------------------------`r`n" +
	"/* Clear the long database timeout */`r`n@WIZCLR(DBASE_TIMEOUT);"

	$processedThisRun = New-Object System.Collections.Generic.List[string]
	$markProcessed = {
		param ([string]$Lane)
		if (-not $processedThisRun.Contains($Lane)) { $processedThisRun.Add($Lane) }
		if ($script:ProcessedLanes -notcontains $Lane) { $script:ProcessedLanes += $Lane }
	}

	# Drop the SQI into the lane's XF folder
	$dropFile = {
		param ([string]$Lane, [string]$Machine, [string]$How)
		$laneLocalPath = Join-Path $OfficePath ("XF" + $StoreNumber + $Lane)
		if (-not (Test-Path -LiteralPath $laneLocalPath))
		{
			Write_Log "Lane #$Lane not found at path: $laneLocalPath" "yellow"
			return
		}
		Write_Log "Writing Lane_Database_Maintenance.sqi to Lane $Lane ($Machine)$How..." "blue"
		try
		{
			$sqiPath = Join-Path $laneLocalPath "Lane_Database_Maintenance.sqi"
			Set-Content -Path $sqiPath -Value $finalScript -Encoding Ascii
			Set-ItemProperty -Path $sqiPath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
			Write_Log "Created and wrote to file at Lane #$Lane ($Machine) successfully. (file copy)" "green"
			& $markProcessed $Lane
		}
		catch { Write_Log "Failed to write to [$Machine]: $_" "red" }
	}

	$multipleLanes = ($Lanes.Count -gt 1)
	if ($multipleLanes) { Write_Log "Multiple lanes selected, using file-based fallback for all lanes." "yellow" }

	foreach ($LaneNumber in $Lanes)
	{
		# "001", "1" or a machine name -> 3-digit lane number
		$laneNumCandidate = [string]$LaneNumber
		if ($MachineNameToLaneNum.ContainsKey($laneNumCandidate)) { $laneNumCandidate = [string]$MachineNameToLaneNum[$laneNumCandidate] }
		elseif ($laneNumCandidate -match '(\d{1,3})$') { $laneNumCandidate = $Matches[1] }
		$laneNum = if ($laneNumCandidate -match '^\d+$') { $laneNumCandidate.PadLeft(3, '0') } else { [string]$LaneNumber }

		$laneInfo = Get_All_Lanes_Database_Info -LaneNumber $laneNum
		if (-not $laneInfo)
		{
			Write_Log "Could not get DB info for lane $laneNum. Skipping." "yellow"
			continue
		}
		# PSCustomObject (JSON cache) -> hashtable
		if ($laneInfo -isnot [System.Collections.IDictionary])
		{
			$tmp = @{ }
			foreach ($p in $laneInfo.PSObject.Properties) { $tmp[$p.Name] = $p.Value }
			$laneInfo = $tmp
		}
		$machineName = $laneInfo['MachineName']
		if (-not $machineName) { $machineName = $LaneNumToMachineName[$laneNum] }

		if ($multipleLanes)
		{
			& $dropFile $laneNum $machineName ''
			continue
		}

		# ---------------- single lane: direct run over the lane's protocol ----------------
		$protocolType = $null
		if ($script:LaneProtocols) { $protocolType = $script:LaneProtocols[$laneNum] }
		$workingConnStr = $null
		if ($protocolType -eq "Named Pipes") { $workingConnStr = $laneInfo['NamedPipesConnStr'] }
		elseif ($protocolType -eq "TCP") { $workingConnStr = $laneInfo['TcpConnStr'] }
		$workingConnStrIsValid = (-not [string]::IsNullOrWhiteSpace($workingConnStr)) -and ($workingConnStr -match '^\s*Server\s*=') -and ($workingConnStr -match 'Database\s*=')

		Write_Log "Lane $laneNum uses protocol: $(if ([string]::IsNullOrWhiteSpace($protocolType)) { 'File' } else { $protocolType })" "gray"
		Write_Log "Lane $laneNum connection string: $(if ($workingConnStrIsValid) { $workingConnStr } else { '<file>' })" "gray"

		if ($protocolType -eq 'Offline')
		{
			Write_Log "Lane $laneNum ($machineName) is offline. Skipping." "yellow"
			continue
		}
		if (-not $InvokeSqlCmd -or -not $protocolType -or $protocolType -eq "File" -or -not $workingConnStrIsValid)
		{
			Write_Log "Protocol not ready/unavailable for $machineName. Skipping protocol and using file copy." "yellow"
			& $dropFile $laneNum $machineName ' using file fallback'
			continue
		}

		# For the -ServerInstance fallback and the login mapping
		$server = $laneInfo['TcpServer']
		$database = $laneInfo['DBName']
		if ([string]::IsNullOrWhiteSpace($database)) { $database = "LANESQL" }
		if ([string]::IsNullOrWhiteSpace($server) -and $workingConnStr -match 'Server\s*=\s*([^;]+)') { $server = $Matches[1].Trim() }
		$currentLogin = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name

		$protocolWorked = $false
		try
		{
			$filteredMatches = @([regex]::Matches([string]$script:LaneSQLFiltered, $sectionPattern) | Where-Object { $SectionsToSend -contains $_.Groups['SectionName'].Value.Trim() })
			foreach ($match in $filteredMatches)
			{
				$sectionName = $match.Groups['SectionName'].Value.Trim()
				$sqlCommands = $match.Groups['SQLCommands'].Value.Trim()

				Write_Log "Executing section: '$sectionName' on $machineName" "blue"
				Write_Log "--------------------------------------------------------------------------------"
				Write_Log "$sqlCommands" "orange"
				Write_Log "--------------------------------------------------------------------------------"

				$querySucceeded = $false
				$retriedForMapping = $false
				for ($try = 1; $try -le 2; $try++)
				{
					try
					{
						$null = & $InvokeSqlCmd -ConnectionString $workingConnStr -Query $sqlCommands -QueryTimeout 0 -ErrorAction Stop
						Write_Log "Section '$sectionName' executed successfully on $machineName using ($protocolType)." "green"
						$protocolWorked = $true
						$querySucceeded = $true
						break
					}
					catch
					{
						$errorMsg = $_.Exception.Message
						if ($errorMsg -match 'Login failed for user' -and -not $retriedForMapping)
						{
							# Map the current Windows login as db_owner, then retry once
							Write_Log "Login failed for $currentLogin on $machineName. Attempting to map user and retry..." "yellow"
							$userExists = 0
							try { $userExists = (& $InvokeSqlCmd -ServerInstance $server -Database $database -Query "SELECT COUNT(*) AS UserExists FROM sys.database_principals WHERE name = '$currentLogin'" -ErrorAction Stop).UserExists }
							catch { $userExists = 0 }
							if ($userExists -eq 0)
							{
								try
								{
									$null = & $InvokeSqlCmd -ServerInstance $server -Database $database -Query "USE [$database];`r`nCREATE USER [$currentLogin] FOR LOGIN [$currentLogin];`r`nALTER ROLE db_owner ADD MEMBER [$currentLogin];" -ErrorAction Stop
									Write_Log "Mapped and granted db_owner to $currentLogin in [$database]." "blue"
								}
								catch { Write_Log "Failed to map $currentLogin in [$database]: $_" "yellow" }
							}
							else
							{
								try { $null = & $InvokeSqlCmd -ServerInstance $server -Database $database -Query "ALTER ROLE db_owner ADD MEMBER [$currentLogin];" -ErrorAction SilentlyContinue }
								catch { }
								Write_Log "$currentLogin already mapped in [$database]." "gray"
							}
							$retriedForMapping = $true
							continue
						}
						elseif ($errorMsg -match 'Login failed for user')
						{
							Write_Log "Login failed for $currentLogin on $machineName. ServerInstance fallback will NOT be attempted (would repeat login failure)..." "yellow"
							$protocolWorked = $false
							break
						}
						else
						{
							Write_Log "ConnectionString method failed for section '$sectionName' on [$machineName]: $_. Trying ServerInstance fallback..." "yellow"
							try
							{
								$null = & $InvokeSqlCmd -ServerInstance $server -Database $database -Query $sqlCommands -QueryTimeout 0 -ErrorAction Stop
								Write_Log "Section '$sectionName' executed successfully on $machineName using ($protocolType, ServerInstance fallback)." "green"
								$protocolWorked = $true
								$querySucceeded = $true
							}
							catch
							{
								Write_Log "ServerInstance method also failed for section '$sectionName' on [$machineName]: $_" "red"
								$protocolWorked = $false
							}
							break
						}
					}
				}
				if (-not $querySucceeded) { break }
			}
		}
		catch
		{
			Write_Log "Failed to execute a section on $machineName via protocol: $_. Falling back to file." "yellow"
			$protocolWorked = $false
		}

		if ($protocolWorked) { & $markProcessed $laneNum }
		else { & $dropFile $laneNum $machineName ' using file copy' }
	}

	Write_Log "`r`nTotal Lanes processed: $($processedThisRun.Count)" "green"
	if ($processedThisRun.Count -gt 0) { Write_Log "Processed Lanes: $($processedThisRun -join ', ')" "green" }
	& $done
}

# ===================================================================================================
#                              FUNCTION: Pump_Tables
# ---------------------------------------------------------------------------------------------------
# Description:
#   Extracts selected tables (from Get_Table_Aliases) from the store SQL Server and copies
#   the generated .sql files to the selected lanes. Uses the cached per-lane protocol
#   ($script:LaneProtocols) to push lanes over SQL where possible and falls back to a file
#   copy for the rest. Each selected table is generated once, then copied to many lanes.
#
# Parameters:
#   - StoreNumber  [string]: store to process (required)
#
# Variables:
#   - $script:FunctionResults: LaneNumToMachineName / MachineNameToLaneNum (input)
#   - $script:LaneProtocols: cached per-lane protocol (TCP / Named Pipes / File)
#   - $OfficePath: Storeman Office root (XF lane folders)
# ===================================================================================================

function Pump_Tables
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber
	)

	# Log function start
	Write_Log "`r`n==================== Starting Pump_Tables Function ====================`r`n" "blue"

	# ------------------------------------------------------------------------------------------------
	# FIX: Initialize tracking arrays locally (prevents null/type issues)
	# ------------------------------------------------------------------------------------------------
	$protocolLanes = @()
	$fileCopyLanes = @()
	$ProcessedLanes = @()

	# ------------------------------------------------------------------------------------------------
	# FIX: Per-run file generation cache (generate each selected table ONCE, then copy to many lanes)
	#      Key: table name -> temp file path
	# ------------------------------------------------------------------------------------------------
	$generatedSqlFiles = @{ }

	# Ensure OfficePath is present and valid
	if (-not (Test-Path $OfficePath))
	{
		Write_Log "Office path not found (cannot locate XF folders): $OfficePath" "yellow"
		return
	}

	# ------------------------------------------------------------------------------------------------
	# STEP 1: Load and validate lane mappings from Retrieve_Nodes (and allow for all flexible lookups)
	# ------------------------------------------------------------------------------------------------
	if (-not ($script:FunctionResults.ContainsKey('LaneNumToMachineName')))
	{
		Write_Log "Lane mappings not found. Please run Retrieve_Nodes first." "red"
		return
	}
	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	$MachineNameToLaneNum = $script:FunctionResults['MachineNameToLaneNum']
	if (-not $MachineNameToLaneNum) { $MachineNameToLaneNum = @{ } }

	# ------------------------------------------------------------------------------------------------
	# STEP 2: Prompt user for lane selection via GUI
	# ------------------------------------------------------------------------------------------------
	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
	if ($null -eq $selection -or -not $selection.Lanes -or $selection.Lanes.Count -eq 0)
	{
		Write_Log "Lane processing canceled by user." "yellow"
		Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
		return
	}

	# Accept all supported forms (lane number, machine name, POSxxx, etc)
	$Lanes = $selection.Lanes

	# FIX: Normalize selection to 3-digit lane numbers using Retrieve_Nodes mappings
	$Lanes = $Lanes | ForEach-Object {
		if ($_ -is [pscustomobject] -and $_.LaneNumber) { $_.LaneNumber }
		elseif ($_ -match '^\d{3}$') { $_ }
		elseif ($MachineNameToLaneNum.ContainsKey($_)) { $MachineNameToLaneNum[$_] }
		elseif ($_ -match '(\d{1,3})$') { $Matches[1].PadLeft(3, '0') }
		else { $_ }
	}
	$Lanes = @($Lanes | Where-Object { $LaneNumToMachineName.ContainsKey($_) } | Select-Object -Unique)

	if (-not $Lanes -or $Lanes.Count -eq 0)
	{
		Write_Log "No valid lanes to process. Exiting Pump_Tables." "yellow"
		Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
		return
	}

	# ------------------------------------------------------------------------------------------------
	# STEP 3: Retrieve table aliases and prompt for tables to process
	# ------------------------------------------------------------------------------------------------
	if ($script:FunctionResults.ContainsKey('Get_Table_Aliases'))
	{
		$aliasData = $script:FunctionResults['Get_Table_Aliases']
		$aliasResults = $aliasData.Aliases
		$aliasHash = $aliasData.AliasHash

		if (($aliasHash -isnot [System.Collections.IDictionary]) -and $aliasHash -and $aliasHash.PSObject -and $aliasHash.PSObject.Properties)
		{
			$tmpAliasHash = @{ }
			foreach ($p in $aliasHash.PSObject.Properties) { $tmpAliasHash[$p.Name] = [string]$p.Value }
			$aliasHash = $tmpAliasHash
		}

		if ((-not $aliasResults -or $aliasResults.Count -eq 0) -and ($aliasHash -is [System.Collections.IDictionary]) -and $aliasHash.Count -gt 0)
		{
			$aliasResults = New-Object System.Collections.ArrayList
			foreach ($tableName in ($aliasHash.Values | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Sort-Object -Unique))
			{
				$matchingAliases = @($aliasHash.GetEnumerator() | Where-Object { $_.Value -eq $tableName } | Select-Object -ExpandProperty Key)
				$aliasLabel = if ($matchingAliases.Count -gt 0) { ($matchingAliases | Sort-Object)[0] }
				else { $null }
				$null = $aliasResults.Add([pscustomobject]@{
						Table = [string]$tableName
						Alias = [string]$aliasLabel
					})
			}
		}
	}
	else
	{
		Write_Log "Alias data not found. Ensure Get_Table_Aliases has been run." "red"
		Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
		return
	}
	if (-not $aliasResults -or $aliasResults.Count -eq 0)
	{
		Write_Log "No tables found to process. Exiting Pump_Tables." "red"
		Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
		return
	}

	# Prompt user to select which tables to pump (Show_Table_Selection_Form returns TABLE NAMES)
	$selectedTables = Show_Table_Selection_Form -AliasResults $aliasResults
	if (-not $selectedTables -or $selectedTables.Count -eq 0)
	{
		Write_Log "No tables were selected. Exiting Pump_Tables." "yellow"
		Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
		return
	}

	# FIX: Build the actual alias entries to loop (was missing in previous version)
	$selectedTables = @($selectedTables | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
	$filteredAliasEntries = @($aliasResults | Where-Object { $selectedTables -contains $_.Table })
	if (-not $filteredAliasEntries -or $filteredAliasEntries.Count -eq 0)
	{
		Write_Log "Selected tables did not match alias list. Nothing to pump." "yellow"
		Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
		return
	}

	# ------------------------------------------------------------------------------------------------
	# STEP 4: Resolve LOCAL source ConnectionString (where we read tables FROM)
	# ------------------------------------------------------------------------------------------------
	$ConnectionString = $null

	# 1) Preferred: already in FunctionResults
	if ($script:FunctionResults.ContainsKey('ConnectionString'))
	{
		$ConnectionString = $script:FunctionResults['ConnectionString']
	}

	# 2) Fallback: pull from cached JSON in SetupFiles (Get_All_Lanes_Database_Info.txt)
	if ([string]::IsNullOrWhiteSpace($ConnectionString))
	{
		try
		{
			$cachePath = Join-Path $script:SetupFiles "Get_All_Lanes_Database_Info.txt"
			if (Test-Path $cachePath)
			{
				$cacheObj = (Get-Content -Path $cachePath -Raw -ErrorAction Stop) | ConvertFrom-Json -ErrorAction Stop
				if ($cacheObj -and $cacheObj.LaneDatabaseInfo)
				{
					$laneDbInfo = $cacheObj.LaneDatabaseInfo
					$localMachine = ($env:COMPUTERNAME).ToUpper()
					$match = $null
					foreach ($p in $laneDbInfo.PSObject.Properties)
					{
						if ($p.Value -and $p.Value.MachineName -and ($p.Value.MachineName.ToString().ToUpper() -eq $localMachine))
						{
							$match = $p.Value
							break
						}
					}
					# If ONLY ONE lane selected, use that lane's cached connstr as last resort
					if (-not $match -and $Lanes -and $Lanes.Count -eq 1)
					{
						$laneKey = [string]$Lanes[0]
						$prop = $laneDbInfo.PSObject.Properties | Where-Object { $_.Name -eq $laneKey } | Select-Object -First 1
						if ($prop) { $match = $prop.Value }
					}
					if ($match)
					{
						if (-not [string]::IsNullOrWhiteSpace([string]$match.ConnectionString))
						{
							$ConnectionString = [string]$match.ConnectionString
						}
						elseif (-not [string]::IsNullOrWhiteSpace([string]$match.TcpConnStr))
						{
							$ConnectionString = [string]$match.TcpConnStr
						}
					}
				}
			}
		}
		catch
		{
			# Silent here; we handle final failure below
		}
	}

	# Final: must have source connection
	if ([string]::IsNullOrWhiteSpace($ConnectionString))
	{
		Write_Log "Connection string not found (FunctionResults + ${script:SetupFiles}\Get_All_Lanes_Database_Info.txt). Cannot proceed with Pump_Tables." "red"
		Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
		return
	}

	# Normalize + cache it so nothing else needs to change
	$ConnectionString = $ConnectionString.Trim().Trim('"')
	$script:FunctionResults['ConnectionString'] = $ConnectionString

	# ------------------------------------------------------------------------------------------------
	# STEP 4b: Open SOURCE SQL connection ONCE (was missing before)
	# ------------------------------------------------------------------------------------------------
	$srcSqlConnection = New-Object System.Data.SqlClient.SqlConnection $ConnectionString
	try
	{
		$srcSqlConnection.Open()
		if ($srcSqlConnection.State -ne 'Open')
		{
			Write_Log "Source SQL connection did not open. Cannot proceed." "red"
			Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
			return
		}
	}
	catch
	{
		Write_Log "Source SQL connection failed: $_" "red"
		Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
		return
	}

	# ------------------------------------------------------------------------------------------------
	# FIX: Pre-calc row counts ONCE (used for file-lane 1000-row rule + better logging)
	# ------------------------------------------------------------------------------------------------
	$tableRowCounts = @{ }
	foreach ($aliasEntry in $filteredAliasEntries)
	{
		$tableName = [string]$aliasEntry.Table
		if ([string]::IsNullOrWhiteSpace($tableName)) { continue }
		if ($tableRowCounts.ContainsKey($tableName)) { continue }

		# Table-name sanity (prevents weird alias entries from breaking queries)
		if ($tableName -notmatch '^[A-Za-z0-9_]+$')
		{
			Write_Log "Skipping invalid table name (bad characters): '$tableName'" "yellow"
			continue
		}

		try
		{
			$cntCmd = $srcSqlConnection.CreateCommand()
			$cntCmd.CommandTimeout = 60
			$cntCmd.CommandText = "SELECT COUNT(1) FROM [dbo].[$tableName]"
			$tableRowCounts[$tableName] = [int]$cntCmd.ExecuteScalar()
		}
		catch
		{
			Write_Log "Could not read rowcount for table '$tableName' from SOURCE. Skipping table. Error: $_" "yellow"
			$tableRowCounts[$tableName] = $null
		}
	}

	# ------------------------------------------------------------------------------------------------
	# STEP 5: Process each lane: Try protocol (Named Pipes or TCP), else fall back to file copy
	# RULE: File-only lanes must ONLY pump tables <= 1000 rows
	# ------------------------------------------------------------------------------------------------
	$MaxFileRows = 1000

	foreach ($laneNum in $Lanes)
	{
		$laneNum = [string]$laneNum
		if ($laneNum -match '^\d+$') { $laneNum = $laneNum.PadLeft(3, '0') }

		$machineName = $LaneNumToMachineName[$laneNum]
		if ([string]::IsNullOrWhiteSpace($machineName) -or $machineName -eq "Unknown")
		{
			Write_Log "Lane #${laneNum}: Machine name is invalid or unknown. Skipping." "yellow"
			continue
		}

		# Retrieve DB connection info for the lane
		$laneInfo = Get_All_Lanes_Database_Info -LaneNumber $laneNum
		if (-not $laneInfo)
		{
			Write_Log "Could not get DB info for lane $laneNum. Skipping." "yellow"
			continue
		}

		# FIX: Convert PSCustomObject -> hashtable for consistent indexing (matches your Process_Lanes fix)
		if ($laneInfo -and ($laneInfo -isnot [System.Collections.IDictionary]))
		{
			$tmp = @{ }
			foreach ($p in $laneInfo.PSObject.Properties) { $tmp[$p.Name] = $p.Value }
			$laneInfo = $tmp
		}

		$namedPipesConnStr = [string]$laneInfo['NamedPipesConnStr']
		$tcpConnStr = [string]$laneInfo['TcpConnStr']

		# Always use numeric lane number for folder path
		$LaneLocalPath = Join-Path $OfficePath "XF${StoreNumber}${laneNum}"

		# FIX: Robust protocol lookup (Start_Lane_Protocol_Jobs stores several keys)
		$protocolType = $null
		if ($script:LaneProtocols)
		{
			if ($script:LaneProtocols.ContainsKey($laneNum)) { $protocolType = $script:LaneProtocols[$laneNum] }
			elseif ($script:LaneProtocols.ContainsKey($laneNum.PadLeft(3, '0'))) { $protocolType = $script:LaneProtocols[$laneNum.PadLeft(3, '0')] }
			elseif ($script:LaneProtocols.ContainsKey($machineName)) { $protocolType = $script:LaneProtocols[$machineName] }
			elseif ($script:LaneProtocols.ContainsKey($machineName.ToLower())) { $protocolType = $script:LaneProtocols[$machineName.ToLower()] }
		}
		if ([string]::IsNullOrWhiteSpace($protocolType)) { $protocolType = 'File' }

		$laneSqlConn = $null
		$protocolWorked = $false

		# ----------------------------------------------------------------------------------------
		# Try direct SQL protocol copy (Named Pipes/TCP) using FAST SqlBulkCopy
		# ----------------------------------------------------------------------------------------
		if ($protocolType -eq "Named Pipes" -or $protocolType -eq "TCP")
		{
			$workingConnStr = $null
			if ($protocolType -eq 'Named Pipes') { $workingConnStr = $namedPipesConnStr }
			elseif ($protocolType -eq 'TCP') { $workingConnStr = $tcpConnStr }

			$workingConnStrIsValid =
			(-not [string]::IsNullOrWhiteSpace($workingConnStr)) -and
			($workingConnStr -match '^\s*Server\s*=') -and
			($workingConnStr -match 'Database\s*=')

			if ($workingConnStrIsValid)
			{
				try
				{
					$laneSqlConn = New-Object System.Data.SqlClient.SqlConnection $workingConnStr
					$laneSqlConn.Open()
					if ($laneSqlConn.State -eq 'Open')
					{
						Write_Log "`r`nCopying data to Lane $laneNum ($machineName) via SQL protocol [$protocolType]..." "blue"

						foreach ($aliasEntry in $filteredAliasEntries)
						{
							$table = [string]$aliasEntry.Table
							if ([string]::IsNullOrWhiteSpace($table)) { continue }

							# Skip tables that we could not count / validate
							if (-not $tableRowCounts.ContainsKey($table) -or $null -eq $tableRowCounts[$table])
							{
								Write_Log "Skipping table '$table' (rowcount/validation failed on SOURCE)." "yellow"
								continue
							}

							Write_Log "Pumping table '$table' to lane $laneNum ($machineName) via SQL (SqlBulkCopy)..." "blue"
							$laneTx = $null

							try
							{
								# -----------------------------
								# 1) Get SOURCE column metadata (sys.columns) so we can:
								#    - create table if missing
								#    - identify identity/computed/rowversion columns
								# -----------------------------
								$metaCmd = $srcSqlConnection.CreateCommand()
								$metaCmd.CommandTimeout = 60
								$metaCmd.CommandText = @"
SELECT
	c.name AS ColumnName,
	t.name AS DataType,
	c.max_length AS MaxLength,
	c.precision AS [Precision],
	c.scale AS [Scale],
	c.is_nullable AS IsNullable,
	c.is_identity AS IsIdentity,
	c.is_computed AS IsComputed,
	ic.seed_value AS IdentitySeed,
	ic.increment_value AS IdentityIncrement
FROM sys.columns c
JOIN sys.types t
	ON c.user_type_id = t.user_type_id
LEFT JOIN sys.identity_columns ic
	ON c.object_id = ic.object_id
	AND c.column_id = ic.column_id
WHERE c.object_id = OBJECT_ID(@obj)
ORDER BY c.column_id;
"@
								$null = $metaCmd.Parameters.Clear()
								$param = $metaCmd.Parameters.Add("@obj", [System.Data.SqlDbType]::NVarChar, 256)
								$param.Value = "dbo.$table"
								$metaRows = @()
								$metaReader = $metaCmd.ExecuteReader()
								while ($metaReader.Read())
								{
									$metaRows += [pscustomobject]@{
										ColumnName = [string]$metaReader['ColumnName']
										DataType   = [string]$metaReader['DataType']
										MaxLength  = [int]$metaReader['MaxLength']
										Precision  = [int]$metaReader['Precision']
										Scale	   = [int]$metaReader['Scale']
										IsNullable = [bool]$metaReader['IsNullable']
										IsIdentity = [bool]$metaReader['IsIdentity']
										IsComputed = [bool]$metaReader['IsComputed']
										IdentitySeed = $metaReader['IdentitySeed']
										IdentityIncrement = $metaReader['IdentityIncrement']
									}
								}
								$metaReader.Close()

								if (-not $metaRows -or $metaRows.Count -eq 0)
								{
									throw "Source table metadata not found (OBJECT_ID failed)."
								}

								# Identify special columns
								$computedCols = @($metaRows | Where-Object { $_.IsComputed })
								$identityCols = @($metaRows | Where-Object { $_.IsIdentity })

								# Copy columns: exclude computed + rowversion/timestamp (SQL Server won't allow explicit insert)
								$copyCols = @($metaRows | Where-Object { -not $_.IsComputed -and $_.DataType -notin @('timestamp', 'rowversion') })

								# -----------------------------
								# 2) Ensure destination table exists and is empty
								#    - If exists: TRUNCATE (fallback to DELETE)
								#    - If missing: CREATE from source columns (computed columns cannot be created here -> fail)
								# -----------------------------
								# Empty + reload in ONE lane transaction: a failed copy rolls back and the
								# lane keeps its old rows instead of an empty / half-filled table
								$laneTx = $laneSqlConn.BeginTransaction()
								$existsCmd = $laneSqlConn.CreateCommand()
								$existsCmd.Transaction = $laneTx
								$existsCmd.CommandTimeout = 30
								$existsCmd.CommandText = "SELECT OBJECT_ID(N'[dbo].[$table]', N'U')"
								$destObjId = $existsCmd.ExecuteScalar()
								$destExists = ($destObjId -ne $null -and $destObjId -ne [DBNull]::Value)

								if ($destExists)
								{
									# Empty the table
									try
									{
										$emptyCmd = $laneSqlConn.CreateCommand()
										$emptyCmd.Transaction = $laneTx
										$emptyCmd.CommandTimeout = 60
										$emptyCmd.CommandText = "TRUNCATE TABLE [dbo].[$table]"
										$emptyCmd.ExecuteNonQuery() | Out-Null
									}
									catch
									{
										# TRUNCATE can fail (FKs). Fallback to DELETE.
										$emptyCmd2 = $laneSqlConn.CreateCommand()
										$emptyCmd2.Transaction = $laneTx
										$emptyCmd2.CommandTimeout = 120
										$emptyCmd2.CommandText = "DELETE FROM [dbo].[$table]"
										$emptyCmd2.ExecuteNonQuery() | Out-Null
									}
								}
								else
								{
									# Cannot recreate computed columns without expressions; fail fast if source has them
									if ($computedCols.Count -gt 0)
									{
										throw "Destination table missing and source has computed columns. Cannot safely CREATE."
									}

									# Build CREATE TABLE from source metadata
									$colDefs = @()
									foreach ($c in $metaRows)
									{
										$colName = $c.ColumnName
										$dataType = $c.DataType
										$maxLen = [int]$c.MaxLength
										$prec = [int]$c.Precision
										$scale = [int]$c.Scale
										$isNull = [bool]$c.IsNullable
										$isIdent = [bool]$c.IsIdentity

										# Skip computed + rowversion for CREATE when destination is missing
										if ($c.IsComputed -or $dataType -in @('timestamp', 'rowversion')) { continue }

										# Type formatting
										$typeText = $dataType
										switch ($dataType)
										{
											'nvarchar' {
												if ($maxLen -eq -1) { $typeText = 'nvarchar(max)' }
												else { $typeText = "nvarchar($([int]($maxLen/2)))" }
											}
											'varchar'  {
												if ($maxLen -eq -1) { $typeText = 'varchar(max)' }
												else { $typeText = "varchar($maxLen)" }
											}
											'nchar'    { $typeText = "nchar($([int]($maxLen/2)))" }
											'char'     { $typeText = "char($maxLen)" }
											'varbinary' {
												if ($maxLen -eq -1) { $typeText = 'varbinary(max)' }
												else { $typeText = "varbinary($maxLen)" }
											}
											'binary'   { $typeText = "binary($maxLen)" }
											'decimal'  { $typeText = "decimal($prec,$scale)" }
											'numeric'  { $typeText = "numeric($prec,$scale)" }
											'datetime2' {
												$typeText = if ($scale -ge 0) { "datetime2($scale)" }
												else { 'datetime2' }
											}
											'time' {
												$typeText = if ($scale -ge 0) { "time($scale)" }
												else { 'time' }
											}
											'datetimeoffset' {
												$typeText = if ($scale -ge 0) { "datetimeoffset($scale)" }
												else { 'datetimeoffset' }
											}
											'float' {
												$typeText = if ($prec -and $prec -ne 53) { "float($prec)" }
												else { 'float' }
											}
										}

										# Identity
										$identityText = ''
										if ($isIdent)
										{
											$seed = $c.IdentitySeed
											$inc = $c.IdentityIncrement
											if ($seed -ne $null -and $seed -ne [DBNull]::Value -and $inc -ne $null -and $inc -ne [DBNull]::Value)
											{
												$identityText = " IDENTITY($seed,$inc)"
											}
											else
											{
												$identityText = " IDENTITY(1,1)"
											}
										}

										$nullText = if ($isNull) { 'NULL' }
										else { 'NOT NULL' }
										$colDefs += "[$colName] $typeText$identityText $nullText"
									}

									if (-not $colDefs -or $colDefs.Count -eq 0)
									{
										throw "No creatable columns discovered for '$table'."
									}

									$createSql = "CREATE TABLE [dbo].[$table] (" + ($colDefs -join ', ') + ")"
									$createCmd = $laneSqlConn.CreateCommand()
									$createCmd.Transaction = $laneTx
									$createCmd.CommandTimeout = 120
									$createCmd.CommandText = "IF OBJECT_ID(N'[dbo].[$table]', N'U') IS NOT NULL DROP TABLE [dbo].[$table]; $createSql;"
									$createCmd.ExecuteNonQuery() | Out-Null
									Write_Log "Created table '$table' on $machineName" "green"
								}

								# -----------------------------
								# 3) Bulk copy data
								# -----------------------------
								$identityInsertEnabled = $false
								if ($identityCols.Count -gt 0)
								{
									try
									{
										$identOn = $laneSqlConn.CreateCommand()
										$identOn.Transaction = $laneTx
										$identOn.CommandTimeout = 30
										$identOn.CommandText = "SET IDENTITY_INSERT [dbo].[$table] ON"
										$identOn.ExecuteNonQuery() | Out-Null
										$identityInsertEnabled = $true
									}
									catch
									{
										Write_Log "Could not enable IDENTITY_INSERT for '$table' on $machineName. Will copy without identity columns. Error: $_" "yellow"
										$copyCols = @($copyCols | Where-Object { -not $_.IsIdentity })
									}
								}

								if (-not $copyCols -or $copyCols.Count -eq 0)
								{
									throw "No columns available to copy (computed/rowversion filtered everything)."
								}

								$colListSql = ($copyCols | ForEach-Object { "[" + $_.ColumnName + "]" }) -join ','
								$srcCmd = $srcSqlConnection.CreateCommand()
								$srcCmd.CommandTimeout = 0
								$srcCmd.CommandText = "SELECT $colListSql FROM [dbo].[$table]"
								$srcReader = $srcCmd.ExecuteReader()

								try
								{
									$bulkOptions = [System.Data.SqlClient.SqlBulkCopyOptions]::TableLock
									if ($identityInsertEnabled) { $bulkOptions = $bulkOptions -bor [System.Data.SqlClient.SqlBulkCopyOptions]::KeepIdentity }

									$bulk = New-Object System.Data.SqlClient.SqlBulkCopy($laneSqlConn, $bulkOptions, $laneTx)
									$bulk.DestinationTableName = "[dbo].[$table]"
									$bulk.BatchSize = 5000
									$bulk.BulkCopyTimeout = 0

									foreach ($c in $copyCols)
									{
										$bulk.ColumnMappings.Add($c.ColumnName, $c.ColumnName) | Out-Null
									}

									$bulk.WriteToServer($srcReader)
								}
								finally
								{
									try { $srcReader.Close() }
									catch { }
									try { $bulk.Close() }
									catch { }
								}

								if ($identityInsertEnabled)
								{
									try
									{
										$identOff = $laneSqlConn.CreateCommand()
										$identOff.Transaction = $laneTx
										$identOff.CommandTimeout = 30
										$identOff.CommandText = "SET IDENTITY_INSERT [dbo].[$table] OFF"
										$identOff.ExecuteNonQuery() | Out-Null
									}
									catch { }
								}

								$laneTx.Commit()
								$laneTx = $null
								$rowCountCopied = $tableRowCounts[$table]
								Write_Log "Copied $rowCountCopied rows to '$table' on lane $laneNum ($machineName) (SQL protocol)." "green"
							}
							catch
							{
								if ($laneTx)
								{
									try { $laneTx.Rollback() }
									catch { }
									$laneTx = $null
									Write_Log "Failed to copy table '$table' to lane $laneNum ($machineName) via SQL - lane table left unchanged: $_" "red"
								}
								else { Write_Log "Failed to copy table '$table' to lane $laneNum ($machineName) via SQL: $_" "red" }
							}
						}

						$protocolWorked = $true
						$protocolLanes += $laneNum
						$ProcessedLanes += $laneNum
					}
				}
				catch
				{
					Write_Log "SQL protocol copy failed for lane [$laneNum] ($machineName) ($protocolType): $_" "yellow"
					$protocolWorked = $false
				}
				finally
				{
					try { if ($laneSqlConn) { $laneSqlConn.Close() } }
					catch { }
					try { if ($laneSqlConn) { $laneSqlConn.Dispose() } }
					catch { }
				}
			}
			else
			{
				Write_Log "Lane $laneNum ($machineName) protocol cached as '$protocolType' but connection string is invalid. Using file fallback." "yellow"
			}
		}

		# --------------------------------------------------------------------------------------------
		# File fallback (if protocol copy not possible)
		# RULE: File-only lanes must ONLY pump tables <= 1000 rows
		# --------------------------------------------------------------------------------------------
		if (-not $protocolWorked)
		{
			if (Test-Path $LaneLocalPath)
			{
				Write_Log "`r`nCopying via FILE fallback for Lane #$laneNum ($machineName)..." "blue"

				foreach ($aliasEntry in $filteredAliasEntries)
				{
					$table = [string]$aliasEntry.Table
					if ([string]::IsNullOrWhiteSpace($table)) { continue }

					$rowCount = $null
					if ($tableRowCounts.ContainsKey($table)) { $rowCount = $tableRowCounts[$table] }
					if ($null -eq $rowCount)
					{
						Write_Log "Skipping '$table' for FILE lane ${laneNum}: rowcount unknown." "yellow"
						continue
					}
					if ($rowCount -gt $MaxFileRows)
					{
						Write_Log "Skipping '$table' for FILE lane ${laneNum}: $rowCount rows (> $MaxFileRows rule)." "yellow"
						continue
					}

					$baseTable = $table -replace '_TAB$', ''
					$sqlFileName = "${baseTable}_Load.sql"

					if (-not $generatedSqlFiles.ContainsKey($table))
					{
						$localTempPath = Join-Path $env:TEMP ("${StoreNumber}_${sqlFileName}")

						try
						{
							$ansiPcEncoding = [System.Text.Encoding]::GetEncoding(1252)
							$streamWriter = New-Object System.IO.StreamWriter($localTempPath, $false, $ansiPcEncoding)
							$streamWriter.NewLine = "`r`n"

							$columnDataTypesQuery = @"
SELECT COLUMN_NAME, DATA_TYPE
FROM INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_NAME = '$table'
ORDER BY ORDINAL_POSITION
"@
							$cmdColumnTypes = $srcSqlConnection.CreateCommand()
							$cmdColumnTypes.CommandText = $columnDataTypesQuery
							$readerColumnTypes = $cmdColumnTypes.ExecuteReader()
							$columnDataTypes = [ordered]@{ }
							while ($readerColumnTypes.Read())
							{
								$colName = [string]$readerColumnTypes["COLUMN_NAME"]
								$dataType = [string]$readerColumnTypes["DATA_TYPE"]
								$columnDataTypes[$colName] = $dataType
							}
							$readerColumnTypes.Close()

							$filterCmd = $srcSqlConnection.CreateCommand()
							$filterCmd.CommandTimeout = 60
							$filterCmd.CommandText = @"
SELECT c.name AS ColumnName, t.name AS DataType, c.is_computed AS IsComputed
FROM sys.columns c
JOIN sys.types t ON c.user_type_id = t.user_type_id
WHERE c.object_id = OBJECT_ID(@obj)
"@
							$null = $filterCmd.Parameters.Clear()
							$p2 = $filterCmd.Parameters.Add("@obj", [System.Data.SqlDbType]::NVarChar, 256)
							$p2.Value = "dbo.$table"
							$filterReader = $filterCmd.ExecuteReader()
							$skipCols = @{ }
							while ($filterReader.Read())
							{
								$cn = [string]$filterReader['ColumnName']
								$dt = [string]$filterReader['DataType']
								$ic = [bool]$filterReader['IsComputed']
								if ($ic -or $dt -in @('timestamp', 'rowversion')) { $skipCols[$cn] = $true }
							}
							$filterReader.Close()

							foreach ($k in @($skipCols.Keys))
							{
								if ($columnDataTypes.Contains($k)) { $columnDataTypes.Remove($k) }
							}

							if ($columnDataTypes.Count -eq 0)
							{
								throw "No eligible columns to pump after filtering computed/rowversion."
							}

							$pkQuery = @"
SELECT c.COLUMN_NAME
FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc
JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE c
	ON c.CONSTRAINT_NAME = tc.CONSTRAINT_NAME
	AND c.TABLE_NAME = tc.TABLE_NAME
WHERE tc.TABLE_NAME = '$table' AND tc.CONSTRAINT_TYPE = 'PRIMARY KEY'
ORDER BY c.ORDINAL_POSITION
"@
							$cmdPK = $srcSqlConnection.CreateCommand()
							$cmdPK.CommandText = $pkQuery
							$readerPK = $cmdPK.ExecuteReader()
							$pkColumns = @()
							while ($readerPK.Read()) { $pkColumns += [string]$readerPK["COLUMN_NAME"] }
							$readerPK.Close()

							if ($pkColumns.Count -eq 0)
							{
								throw "File fallback requires a real PRIMARY KEY on '$table'."
							}
							else
							{
								$primaryKeyColumns = $pkColumns
							}

							$keyString = ($primaryKeyColumns | ForEach-Object { "$_=:$_" }) -join " AND "
							$viewName = $baseTable.Substring(0, 1).ToUpper() + $baseTable.Substring(1).ToLower() + '_Load'
							$columnList = ($columnDataTypes.Keys) -join ','

							$header = @"
@WIZRPL(DBASE_TIMEOUT=E);

CREATE VIEW $viewName AS SELECT $columnList FROM $table;

INSERT INTO $viewName VALUES
"@
							$header = $header -replace "(`r`n|`n|`r)", "`r`n"
							$streamWriter.WriteLine($header.TrimEnd())

							$dataQuery = "SELECT $columnList FROM [dbo].[$table]"
							$cmdData = $srcSqlConnection.CreateCommand()
							$cmdData.CommandText = $dataQuery
							$readerData = $cmdData.ExecuteReader()
							$firstRow = $true
							while ($readerData.Read())
							{
								if ($firstRow) { $firstRow = $false }
								else { $streamWriter.WriteLine(",") }
								$values = @()
								foreach ($col in $columnDataTypes.Keys)
								{
									$val = $readerData[$col]
									$dataType = $columnDataTypes[$col]
									if ($val -eq $null -or $val -is [System.DBNull])
									{
										$values += ""
										continue
									}
									switch -Wildcard ($dataType)
									{
										{ $_ -in @('char', 'nchar', 'varchar', 'nvarchar', 'text', 'ntext') } {
											$escapedVal = $val.ToString().Replace("'", "''")
											$escapedVal = $escapedVal -replace "(`r`n|`n|`r)", " "
											$values += "'$escapedVal'"
											break
										}
										{ $_ -in @('datetime', 'smalldatetime', 'date', 'datetime2') } {
											$dayOfYear = $val.DayOfYear.ToString("D3")
											$formattedDate = "'{0}{1} {2}'" -f $val.Year, $dayOfYear, $val.ToString("HH:mm:ss")
											$values += $formattedDate
											break
										}
										{ $_ -eq 'bit' } {
											$bitVal = if ($val) { "1" }
											else { "0" }
											$values += $bitVal
											break
										}
										{ $_ -in @('decimal', 'numeric', 'float', 'real', 'money', 'smallmoney') } {
											$values += ([string]::Format([System.Globalization.CultureInfo]::InvariantCulture, "{0}", $val))
											break
										}
										{ $_ -in @('tinyint', 'smallint', 'int', 'bigint') } {
											$values += $val.ToString()
											break
										}
										default {
											$escapedVal = $val.ToString().Replace("'", "''")
											$escapedVal = $escapedVal -replace "(`r`n|`n|`r)", " "
											$values += "'$escapedVal'"
											break
										}
									}
								}
								$insertStatement = "(" + ($values -join ",") + ")"
								$insertStatement = $insertStatement -replace "(`r`n|`n|`r)", " "
								$streamWriter.Write($insertStatement)
							}
							$readerData.Close()
							$streamWriter.WriteLine(";")
							$streamWriter.WriteLine()

							$footer = @"
@UPDATE_BATCH(JOB=ADDRPL,TAR=$table,
KEY=$keyString,
SRC=SELECT * FROM $viewName);

DROP VIEW $viewName;

@EXEC(INI=HOST_STORE[ACTIVATE_ACCEPT_ALL]);

@WIZCLR(DBASE_TIMEOUT);
"@
							$footer = $footer -replace "(`r`n|`n|`r)", "`r`n"
							$streamWriter.WriteLine($footer.TrimEnd())
							$streamWriter.WriteLine()
							$streamWriter.Flush()
							$streamWriter.Close()
							$streamWriter.Dispose()

							$generatedSqlFiles[$table] = $localTempPath
							Write_Log "Generated $sqlFileName (FILE mode) from SOURCE ($rowCount rows)." "green"
						}
						catch
						{
							try { if ($streamWriter) { $streamWriter.Close(); $streamWriter.Dispose() } }
							catch { }
							Write_Log "Error generating SQL for table '$table' (file fallback): $_" "red"
							continue
						}
					}

					try
					{
						$localTempPath = $generatedSqlFiles[$table]
						if (-not (Test-Path $localTempPath))
						{
							Write_Log "Temp SQL file missing for '$table' ($localTempPath). Skipping copy." "yellow"
							continue
						}

						$destinationPath = Join-Path $LaneLocalPath $sqlFileName
						Copy-Item -Path $localTempPath -Destination $destinationPath -Force -ErrorAction Stop

						try
						{
							$fileItem = Get-Item $destinationPath -ErrorAction Stop
							if ($fileItem.Attributes -band [System.IO.FileAttributes]::Archive)
							{
								$fileItem.Attributes -= [System.IO.FileAttributes]::Archive
							}
						}
						catch { }

						Write_Log "Copied $sqlFileName to Lane #$laneNum ($machineName) (file fallback)." "green"
						$fileCopyLanes += $laneNum
						$ProcessedLanes += $laneNum
					}
					catch
					{
						Write_Log "Error copying $sqlFileName to Lane #[$laneNum] ($machineName): $_" "red"
					}
				}
			}
			else
			{
				Write_Log "Lane #$laneNum ($machineName) not found at path: $LaneLocalPath (file fallback failed)" "yellow"
			}
		}
	}

	# ------------------------------------------------------------------------------------------------
	# STEP 6: Clean up and final logging
	# ------------------------------------------------------------------------------------------------
	try { if ($srcSqlConnection) { $srcSqlConnection.Close() } }
	catch { }
	try { if ($srcSqlConnection) { $srcSqlConnection.Dispose() } }
	catch { }

	$uniqueProcessedLanes = @($ProcessedLanes | Select-Object -Unique)
	Write_Log "`r`nTotal Lanes processed: $($uniqueProcessedLanes.Count)" "green"
	if ($protocolLanes.Count -gt 0)
	{
		Write_Log "Lanes processed via SQL protocol: $((($protocolLanes | Select-Object -Unique) -join ', '))" "green"
	}
	if ($fileCopyLanes.Count -gt 0)
	{
		Write_Log "Lanes processed via FILE fallback: $((($fileCopyLanes | Select-Object -Unique) -join ', '))" "yellow"
	}
	Write_Log "`r`n==================== Pump_Tables Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Refresh_Database
# ---------------------------------------------------------------------------------------------------
# Description:
#   Deploys a database refresh command to the selected registers: for each selected lane it
#   writes Refresh_Database.sqi (ANSI, CRLF) containing @WIZSET(TARGET=@TER) and
#   @EXEC(SQM=exe_activate_accept_sys) into the lane XF folder; the lane picks it up from
#   there (no restart is sent).
#
# Parameters:
#   - StoreNumber  [string]: store to process (required)
#
# Variables:
#   - $script:FunctionResults: LaneNumToMachineName (input)
#   - $OfficePath: Storeman Office root (XF lane folders)
#
# Writes:
#   - Refresh_Database.sqi in each selected lane XF folder
# ===================================================================================================

function Refresh_Database
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber
	)

	Write_Log "`r`n==================== Starting Refresh_Database ====================`r`n" "blue"

	# --------------------------------------------------
	# STEP 1: Use Show_Node_Selection_Form to select registers/lanes
	# --------------------------------------------------
	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
	if (-not $selection -or -not $selection.Lanes -or $selection.Lanes.Count -eq 0)
	{
		Write_Log "No registers selected or selection cancelled." "yellow"
		Write_Log "`r`n==================== Refresh_Database Function Completed ====================" "blue"
		return
	}

	# Normalize to 3-digit lane/register numbers (always as strings)
	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	$registersToProcess = $selection.Lanes | ForEach-Object {
		if ($_ -is [pscustomobject] -and $_.LaneNumber) { $_.LaneNumber }
		elseif ($_ -match '^\d{3}$') { $_ }
		elseif ($LaneNumToMachineName.ContainsKey($_)) { $_ }
		else { $_ }
	}
	$registersToProcess = $registersToProcess | Where-Object { $LaneNumToMachineName.ContainsKey($_) }
	if (-not $registersToProcess -or $registersToProcess.Count -eq 0)
	{
		Write_Log "No valid registers selected for processing." "yellow"
		return
	}

	# --------------------------------------------------
	# STEP 2: Define the SQI content to refresh the database
	# --------------------------------------------------
	$SQIContent = @"
@WIZSET(TARGET=@TER);
@EXEC(SQM=exe_activate_accept_sys);
"@
	# Ensure the SQI content uses CRLF line endings (ANSI PC format)
	$SQIContent = $SQIContent -replace "`r?`n", "`r`n"

	# --------------------------------------------------
	# STEP 3: For each selected register, deploy the SQI file
	# --------------------------------------------------
	foreach ($register in $registersToProcess)
	{
		# Construct the register directory path (assumes folder naming: XF<StoreNumber><Register>)
		$RegisterDirectory = "$OfficePath\XF${StoreNumber}${register}"
		if (-not (Test-Path $RegisterDirectory))
		{
			Write_Log "Register directory $RegisterDirectory not found. Skipping register $register." "yellow"
			continue
		}

		# Define the full path to the SQI file (named "Refresh_Database.sqi")
		$SQIFilePath = Join-Path -Path $RegisterDirectory -ChildPath "Refresh_Database.sqi"

		# Write the SQI file in ANSI (PC) format (using ASCII encoding)
		Set-Content -Path $SQIFilePath -Value $SQIContent -Encoding ASCII

		# Remove the Archive attribute (set file attributes to Normal)
		Set-ItemProperty -Path $SQIFilePath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
		Write_Log "Deployed Refresh_Database.sqi command to register $register in directory $RegisterDirectory." "green"
	}
	Write_Log "`r`n==================== Refresh_Database Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Refresh_PIN_Pad_Files
# ---------------------------------------------------------------------------------------------------
# Description:
#   Refreshes the EMV PIN pad configuration files (PreferredAIDs.ini, EMVCAPKey.ini,
#   EMVAID.ini) on selected lanes: each target file is touched (LastWriteTime updated) so
#   the lane sees it as modified and reloads it.
#
# Parameters:
#   - StoreNumber  [string]: store to process, 3 digits (required)
#
# Variables:
#   - $script:FunctionResults['LaneNumToMachineName']: lane map (input)
#   - $OfficePath: Storeman Office root (XF lane folders)
#
# Notes:
#   - Retrieve_Nodes must have been run first.
# ===================================================================================================

function Refresh_PIN_Pad_Files
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber
	)

	Write_Log "`r`n==================== Starting Refresh_PIN_Pad_Files Function ====================`r`n" "blue"

	# ============================= Validate Environment =============================
	# Validate OfficePath base directory
	if (-not (Test-Path $OfficePath))
	{
		Write_Log "XF Base Path not found: $OfficePath" "yellow"
		return
	}

	# Ensure required functions are loaded
	foreach ($func in @('Show_Node_Selection_Form', 'Write_Log', 'Retrieve_Nodes'))
	{
		if (-not (Get-Command -Name $func -ErrorAction SilentlyContinue))
		{
			Write-Error "Function '$func' is not available. Please ensure it is loaded."
			return
		}
	}

	# Ensure lane mapping is available from Retrieve_Nodes
	if (-not ($script:FunctionResults.ContainsKey('LaneNumToMachineName')))
	{
		Write_Log "No lane information found. Please ensure Retrieve_Nodes has been executed." "red"
		return
	}
	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']

	# ============================= Lane Selection UI =============================
	# Use the node selector form to allow the user to choose which lanes to refresh
	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
	if ($null -eq $selection)
	{
		Write_Log "Operation canceled by user." "yellow"
		return
	}
	$Lanes = $selection.Lanes
	if (-not $Lanes -or $Lanes.Count -eq 0)
	{
		Write_Log "No lanes selected for processing." "yellow"
		return
	}

	# ============================= File Types =============================
	# List of PIN pad config files that should be "touched" (refreshed)
	$fileExtensions = @("PreferredAIDs.ini", "EMVCAPKey.ini", "EMVAID.ini")
	Write_Log "Starting refresh of file types: $($fileExtensions -join ', ') for Store Number: $StoreNumber." "green"

	# ============================= Main Processing Loop =============================
	$totalRefreshed = 0
	$totalFailed = 0
	$refreshedLanes = New-Object System.Collections.Generic.List[string]

	foreach ($laneObj in $Lanes)
	{
		# Accept both plain lane number string or PSCustomObject with .LaneNumber property
		$laneNum = if ($laneObj -is [pscustomobject] -and $laneObj.LaneNumber) { $laneObj.LaneNumber }
		else { $laneObj }
		$laneNum = $laneNum.PadLeft(3, '0')

		# Ensure this lane exists in LaneNumToMachineName
		if ($LaneNumToMachineName.ContainsKey($laneNum))
		{
			$machineName = $LaneNumToMachineName[$laneNum]

			if ([string]::IsNullOrWhiteSpace($machineName) -or $machineName -eq "Unknown")
			{
				Write_Log "Lane #${laneNum}: Machine name is invalid or unknown. Skipping refresh." "yellow"
				continue
			}

			# Build UNC path to lane's EMV config directory
			$targetPath = "\\$machineName\Storeman\XchDev\EMVConfig\"

			if (-not (Test-Path -Path $targetPath))
			{
				Write_Log "Lane #${laneNum}: Target path '$targetPath' does not exist. Skipping." "yellow"
				continue
			}

			Write_Log "Processing Lane #$laneNum ($machineName) at '$targetPath'." "blue"

			foreach ($file in $fileExtensions)
			{
				$filePath = Join-Path -Path $targetPath -ChildPath $file
				if (Test-Path -Path $filePath)
				{
					try
					{
						# "Touch" the file (set LastWriteTime to current time)
						(Get-Item -Path $filePath).LastWriteTime = Get-Date
						Write_Log "Lane #${laneNum}: Refreshed file '$filePath'." "green"
						$totalRefreshed++
						if (-not $refreshedLanes.Contains($laneNum)) { $refreshedLanes.Add($laneNum) }
					}
					catch
					{
						Write_Log "Lane #${laneNum}: Failed to refresh file '$filePath'. Error: $_" "red"
						$totalFailed++
					}
				}
				else
				{
					Write_Log "Lane #${laneNum}: File '$filePath' does not exist. Skipping." "yellow"
				}
			}
		}
		else
		{
			Write_Log "Lane #${laneNum}: Machine information not found in LaneNumToMachineName. Skipping." "yellow"
			continue
		}
	}
	Write_Log "Refresh Summary for Store Number: $StoreNumber - Total Files Refreshed: $totalRefreshed, Total Failures: $totalFailed." "green"
	# ==== Prompt to Restart All Programs on successful lanes ====
	if ($totalRefreshed -gt 0)
	{
		# ($refreshedLanes is collected in the loop above - lanes where at least one file was touched)
		if ($refreshedLanes.Count -gt 0)
		{
			Add-Type -AssemblyName System.Windows.Forms
			$laneListStr = ($refreshedLanes | Sort-Object) -join ", "
			$msg = "Do you want to send 'Restart All Programs' to the following lanes?`nStore $StoreNumber Lanes: $laneListStr"
			$result = [System.Windows.Forms.MessageBox]::Show($msg, "Restart All Programs?", [System.Windows.Forms.MessageBoxButtons]::YesNo, [System.Windows.Forms.MessageBoxIcon]::Question)
			if ($result -eq [System.Windows.Forms.DialogResult]::Yes)
			{
				Write_Log "User chose to send 'Restart All Programs' to lanes: $laneListStr" "cyan"
				Send_Restart_All_Programs -StoreNumber $StoreNumber -LaneNumbers $refreshedLanes
			}
			else
			{
				Write_Log "User cancelled 'Restart All Programs' action." "yellow"
			}
		}
	}
	Write_Log "`r`n==================== Refresh_PIN_Pad_Files Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Repair_LOC_Databases_On_Lanes
# ---------------------------------------------------------------------------------------------------
# Description:
#   Interactive database repair for lane (LOC) databases: pick lane(s) and a repair level
#   (Audit / Quick / Deep) in a dialog, then run DBCC repair with safety gates. Uses
#   Protocol_Results.txt as the protocol source of truth (File-protocol lanes are skipped),
#   refuses system DB names and restores MULTI_USER state in finally blocks.
#
# Parameters:
#   - StoreNumber    [string]: store number (required)
#   - CommandTimeout [int]: per-statement SQL timeout in seconds (default 900)
#
# Variables:
#   - $script:FunctionResults['LaneNumToMachineName']: required input (lane map)
#
# Notes:
#   - All SQL goes through System.Data.SqlClient (no SQL module needed); a Quick / Deep repair
#     runs SINGLE_USER, DBCC and MULTI_USER on one connection.
#   - If tempdb is not ONLINE it offers to restart the lane SQL service, then re-checks.
# ===================================================================================================

function Repair_LOC_Databases_On_Lanes
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[int]$CommandTimeout = 900 # per-statement timeout (seconds)
	)

	# ----------------------------------------
	# Banner: Start
	# ----------------------------------------
	Write_Log "`r`n==================== Starting Repair_LOC_Databases_On_Lanes Function ====================`r`n" "blue"

	# ----------------------------------------
	# Normalize store (3 digits) for any labels/logs
	# ----------------------------------------
	$StoreNumber = "$StoreNumber".PadLeft(3, '0')

	# ----------------------------------------
	# Validate required caches
	# ----------------------------------------
	if (-not $script:FunctionResults) { $script:FunctionResults = @{ } }

	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	if (-not $LaneNumToMachineName -or $LaneNumToMachineName.Count -eq 0)
	{
		Write_Log "No lanes available. Please retrieve nodes first (LaneNumToMachineName missing/empty)." "red"
		Write_Log "`r`n==================== Repair_LOC_Databases_On_Lanes Function Completed ====================" "blue"
		return
	}

	# ----------------------------------------
	# SQL helpers: System.Data.SqlClient only (always present, so no SQL module is needed;
	# DBCC errors surface as exceptions the same way Invoke-Sqlcmd -ErrorAction Stop did)
	# ----------------------------------------
	$invokeSqlTable = {
		param (
			[string]$ConnectionString,
			[string]$Query,
			[int]$Timeout = 30
		)

		$dt = New-Object System.Data.DataTable
		$cn = New-Object System.Data.SqlClient.SqlConnection $ConnectionString
		try
		{
			$cn.Open()
			$cmd = $cn.CreateCommand()
			$cmd.CommandText = $Query
			$cmd.CommandTimeout = $Timeout
			[void](New-Object System.Data.SqlClient.SqlDataAdapter $cmd).Fill($dt)
		}
		finally { $cn.Dispose() }

		# PowerShell unrolls a returned DataTable: callers get DataRow(s) or $null and handle both
		return $dt
	}

	$invokeSqlNonQuery = {
		param (
			[string]$ConnectionString,
			[string]$Query,
			[int]$Timeout = 30
		)

		$cn = New-Object System.Data.SqlClient.SqlConnection $ConnectionString
		try
		{
			$cn.Open()
			$cmd = $cn.CreateCommand()
			$cmd.CommandText = $Query
			$cmd.CommandTimeout = $Timeout
			[void]$cmd.ExecuteNonQuery()
		}
		finally { $cn.Dispose() }
	}
	$getRowCount = {
		param ($Rows)

		if ($Rows -is [System.Data.DataTable]) { return $Rows.Rows.Count }
		if ($null -eq $Rows) { return 0 }
		return @($Rows).Count
	}

	$getDatabaseState = {
		param (
			[string]$ConnectionString,
			[string]$DatabaseName
		)

		if ([string]::IsNullOrWhiteSpace($DatabaseName)) { return $null }

		$dbLiteral = $DatabaseName.Replace("'", "''")
		$rows = & $invokeSqlTable $ConnectionString "SELECT state_desc FROM sys.databases WHERE name = N'$dbLiteral';" 10

		if ($rows -is [System.Data.DataTable])
		{
			if ($rows.Rows.Count -gt 0) { return [string]$rows.Rows[0]['state_desc'] }
		}
		elseif ((& $getRowCount $rows) -gt 0)
		{
			return [string]($rows | Select-Object -First 1 -ExpandProperty state_desc)
		}

		return $null
	}

	$getSystemDbProblems = {
		param ([string]$ConnectionString)

		$rows = & $invokeSqlTable $ConnectionString "SELECT name, state_desc FROM sys.databases WHERE name IN ('master','model','msdb','tempdb');" 10
		$bad = New-Object System.Collections.Generic.List[pscustomobject]

		if ($rows -is [System.Data.DataTable])
		{
			foreach ($row in $rows.Rows)
			{
				$n = [string]$row['name']
				$s = [string]$row['state_desc']
				if ($s -and $s.ToUpper() -ne 'ONLINE')
				{
					$bad.Add([pscustomobject]@{ Name = $n; State = $s })
				}
			}
		}
		else
		{
			foreach ($r in @($rows))
			{
				if ($r -and $r.state_desc -and ($r.state_desc.ToString().ToUpper() -ne 'ONLINE'))
				{
					$bad.Add([pscustomobject]@{ Name = [string]$r.name; State = [string]$r.state_desc })
				}
			}
		}

		return @($bad)
	}

	$testSqlConnectivity = {
		param ([string]$ConnectionString)

		try
		{
			[void](& $invokeSqlTable $ConnectionString "SELECT 1 AS ok;" 5)
			return $true
		}
		catch
		{
			return $false
		}
	}

	$getCheckDbIssueCount = {
		param (
			[string]$ConnectionString,
			[string]$QuotedDbName,
			[int]$Timeout = 900
		)

		$rows = & $invokeSqlTable $ConnectionString "DBCC CHECKDB ($QuotedDbName) WITH NO_INFOMSGS, ALL_ERRORMSGS, TABLERESULTS;" $Timeout
		return (& $getRowCount $rows)
	}

	$detectLaneProtocol = {
		param ([string]$MachineName)

		if ([string]::IsNullOrWhiteSpace($MachineName)) { return $null }

		$candidates = @(
			@{ Label = 'TCP'; ConnectionString = "Data Source=tcp:$MachineName;Initial Catalog=master;Integrated Security=True;Connect Timeout=2;TrustServerCertificate=True;" },
			@{ Label = 'Named Pipes'; ConnectionString = "Data Source=np:$MachineName;Initial Catalog=master;Integrated Security=True;Connect Timeout=2;TrustServerCertificate=True;" }
		)

		foreach ($candidate in $candidates)
		{
			if (& $testSqlConnectivity $candidate.ConnectionString)
			{
				return $candidate.Label
			}
		}

		return $null
	}

	# ----------------------------------------
	# Load protocol results file (SOURCE OF TRUTH)
	# ----------------------------------------
	$protoFile = $script:ProtocolResultsFile

	$LaneProtocolsFromFile = @{ }
	if (Test-Path $protoFile)
	{
		try
		{
			$protoLines = Get-Content -LiteralPath $protoFile -ErrorAction SilentlyContinue
			foreach ($line in $protoLines)
			{
				# Format: LANE,PROTOCOL  (you wrote lane,protocol)
				if ($line -match '^\s*([^,]+)\s*,\s*([^,]+)\s*$')
				{
					$laneRaw = $matches[1].Trim()
					$proto = $matches[2].Trim()

					$laneDigits = ($laneRaw -replace '[^\d]', '')
					if (-not [string]::IsNullOrWhiteSpace($laneDigits))
					{
						$laneNum = $laneDigits.PadLeft(3, '0')
						$LaneProtocolsFromFile[$laneNum] = $proto
					}
				}
			}
			Write_Log "Loaded protocol results from: $protoFile" "gray"
		}
		catch
		{
			Write_Log "WARN: Failed reading ProtocolResultsFile '$protoFile'. Error: $_" "yellow"
		}
	}
	else
	{
		Write_Log "ProtocolResultsFile not found: $protoFile. Will fall back to in-memory/live protocol detection for this run." "yellow"
	}

	# ----------------------------------------
	# Lane selection (same UX pattern)
	# ----------------------------------------
	$selection = $null
	try
	{
		$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane" -Title "Select Lanes for DB Repair"
	}
	catch
	{
		Write_Log "Lane selection failed: $_" "red"
		Write_Log "`r`n==================== Repair_LOC_Databases_On_Lanes Function Completed ====================" "blue"
		return
	}

	if ($selection -eq $null)
	{
		Write_Log "Lane DB repair canceled by user." "yellow"
		Write_Log "`r`n==================== Repair_LOC_Databases_On_Lanes Function Completed ====================" "blue"
		return
	}
	if (-not $selection.Lanes -or $selection.Lanes.Count -eq 0)
	{
		Write_Log "No lanes selected." "yellow"
		Write_Log "`r`n==================== Repair_LOC_Databases_On_Lanes Function Completed ====================" "blue"
		return
	}

	# Normalize lane list from selection (handles PSCustomObject or strings/ints)
	$Lanes = @()
	if ($selection.Lanes[0] -is [PSCustomObject] -and $selection.Lanes[0].PSObject.Properties.Name -contains 'LaneNumber')
	{
		foreach ($item in $selection.Lanes)
		{
			$ln = "$($item.LaneNumber)" -replace '[^\d]', ''
			if ($ln) { $Lanes += $ln.PadLeft(3, '0') }
		}
	}
	else
	{
		foreach ($item in $selection.Lanes)
		{
			$ln = "$item" -replace '[^\d]', ''
			if ($ln) { $Lanes += $ln.PadLeft(3, '0') }
		}
	}
	$Lanes = @($Lanes | Where-Object { $_ } | Select-Object -Unique)

	# ----------------------------------------
	# In-function dialog to pick repair level
	# ----------------------------------------
	Add-Type -AssemblyName System.Windows.Forms
	Add-Type -AssemblyName System.Drawing

	$form = New-Object System.Windows.Forms.Form
	$form.Text = "Database Repair Level"
	$form.Size = New-Object System.Drawing.Size(520, 240)
	$form.StartPosition = "CenterScreen"
	$form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
	$form.MaximizeBox = $false
	$form.MinimizeBox = $false

	$lbl = New-Object System.Windows.Forms.Label
	$lbl.Text = "Choose how aggressive the repair should be:"
	$lbl.AutoSize = $true
	$lbl.Location = New-Object System.Drawing.Point(12, 12)
	$form.Controls.Add($lbl)

	$grp = New-Object System.Windows.Forms.GroupBox
	$grp.Text = "Repair Level"
	$grp.Location = New-Object System.Drawing.Point(12, 36)
	$grp.Size = New-Object System.Drawing.Size(490, 110)
	$form.Controls.Add($grp)

	$rbAudit = New-Object System.Windows.Forms.RadioButton
	$rbAudit.Text = "Audit only (DBCC CHECKDB, no changes)"
	$rbAudit.AutoSize = $true
	$rbAudit.Location = New-Object System.Drawing.Point(16, 24)
	$rbAudit.Checked = $true
	$grp.Controls.Add($rbAudit)

	$rbQuick = New-Object System.Windows.Forms.RadioButton
	$rbQuick.Text = "Quick repair (REPAIR_REBUILD)"
	$rbQuick.AutoSize = $true
	$rbQuick.Location = New-Object System.Drawing.Point(16, 48)
	$grp.Controls.Add($rbQuick)

	$rbDeep = New-Object System.Windows.Forms.RadioButton
	$rbDeep.Text = "Deep repair (REPAIR_ALLOW_DATA_LOSS)"
	$rbDeep.AutoSize = $true
	$rbDeep.Location = New-Object System.Drawing.Point(16, 72)
	$grp.Controls.Add($rbDeep)

	$chkConfirm = New-Object System.Windows.Forms.CheckBox
	$chkConfirm.Text = "I understand deep repair can cause data loss."
	$chkConfirm.AutoSize = $true
	$chkConfirm.Location = New-Object System.Drawing.Point(28, 152)
	$chkConfirm.Enabled = $false
	$form.Controls.Add($chkConfirm)

	[void]$rbDeep.Add_CheckedChanged({
			if ($rbDeep.Checked) { $chkConfirm.Enabled = $true }
			else { $chkConfirm.Enabled = $false; $chkConfirm.Checked = $false }
		})
	[void]$rbAudit.Add_CheckedChanged({ if ($rbAudit.Checked) { $chkConfirm.Enabled = $false; $chkConfirm.Checked = $false } })
	[void]$rbQuick.Add_CheckedChanged({ if ($rbQuick.Checked) { $chkConfirm.Enabled = $false; $chkConfirm.Checked = $false } })

	$btnOK = New-Object System.Windows.Forms.Button
	$btnOK.Text = "OK"
	$btnOK.Location = New-Object System.Drawing.Point(314, 172)
	$btnOK.Size = New-Object System.Drawing.Size(85, 28)
	$btnOK.DialogResult = [System.Windows.Forms.DialogResult]::OK
	$form.AcceptButton = $btnOK
	$form.Controls.Add($btnOK)

	$btnCancel = New-Object System.Windows.Forms.Button
	$btnCancel.Text = "Cancel"
	$btnCancel.Location = New-Object System.Drawing.Point(417, 172)
	$btnCancel.Size = New-Object System.Drawing.Size(85, 28)
	$btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
	$form.CancelButton = $btnCancel
	$form.Controls.Add($btnCancel)

	$dlg = $form.ShowDialog()
	if ($dlg -ne [System.Windows.Forms.DialogResult]::OK)
	{
		Write_Log "Repair level selection canceled." "yellow"
		Write_Log "`r`n==================== Repair_LOC_Databases_On_Lanes Function Completed ====================" "blue"
		return
	}

	$Level = 'Audit'
	if ($rbQuick.Checked) { $Level = 'Quick' }
	if ($rbDeep.Checked) { $Level = 'Deep' }

	if ($Level -eq 'Deep' -and -not $chkConfirm.Checked)
	{
		Write_Log "Deep repair selected but confirmation not checked. Aborting." "yellow"
		Write_Log "`r`n==================== Repair_LOC_Databases_On_Lanes Function Completed ====================" "blue"
		return
	}

	Write_Log ("Selected repair level: {0}" -f $Level) "gray"

	# ----------------------------------------
	# Summary container
	# ----------------------------------------
	$laneSummary = New-Object System.Collections.Generic.List[pscustomobject]

	# ----------------------------------------
	# Lane processing loop
	# ----------------------------------------
	foreach ($LaneNumber in ($Lanes | Sort-Object))
	{
		$laneKeyP = ("$LaneNumber" -replace '[^\d]', '').PadLeft(3, '0')

		# Resolve machine name
		$machineName = $null
		if ($LaneNumToMachineName.ContainsKey($laneKeyP)) { $machineName = $LaneNumToMachineName[$laneKeyP] }
		elseif ($LaneNumToMachineName.ContainsKey($LaneNumber)) { $machineName = $LaneNumToMachineName[$LaneNumber] }

		if (-not $machineName)
		{
			Write_Log ("Lane {0}: No machine mapping found. Skipping." -f $laneKeyP) "yellow"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = ''; Protocol = ''; DBServer = ''; DBName = ''; Level = $Level; Result = 'NoMachine' })
			continue
		}

		# Protocol from file, then in-memory cache, then live detection
		$proto = $null
		if ($LaneProtocolsFromFile.ContainsKey($laneKeyP)) { $proto = [string]$LaneProtocolsFromFile[$laneKeyP] }

		if ([string]::IsNullOrWhiteSpace($proto) -and $script:LaneProtocols)
		{
			$tryKeys = @($laneKeyP, $LaneNumber)
			if ($machineName) { $tryKeys += @($machineName, $machineName.ToLower()) }

			foreach ($k in $tryKeys)
			{
				if (-not [string]::IsNullOrWhiteSpace("$k") -and $script:LaneProtocols.ContainsKey($k))
				{
					$proto = [string]$script:LaneProtocols[$k]
					break
				}
			}
		}

		if ([string]::IsNullOrWhiteSpace($proto))
		{
			$proto = & $detectLaneProtocol $machineName
			if (-not [string]::IsNullOrWhiteSpace($proto))
			{
				Write_Log ("Lane {0} ({1}): Protocol detected live as '{2}'." -f $laneKeyP, $machineName, $proto) "gray"
				$LaneProtocolsFromFile[$laneKeyP] = $proto
				if (-not $script:LaneProtocols) { $script:LaneProtocols = @{ } }
				$script:LaneProtocols[$laneKeyP] = $proto
				$script:LaneProtocols[$LaneNumber] = $proto
				$script:LaneProtocols[$machineName] = $proto
				$script:LaneProtocols[$machineName.ToLower()] = $proto
			}
		}

		if ([string]::IsNullOrWhiteSpace($proto))
		{
			Write_Log ("Lane {0} ({1}): No usable protocol found in file, memory, or live detection. Skipping." -f $laneKeyP, $machineName) "yellow"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = ''; DBServer = ''; DBName = ''; Level = $Level; Result = 'NoProtocolDetected' })
			continue
		}

		if ($proto -ne 'TCP' -and $proto -ne 'Named Pipes')
		{
			# File / Unknown -> do not attempt DB operations
			Write_Log ("Lane {0} ({1}): Protocol is '{2}'. Skipping DB repair (not reachable)." -f $laneKeyP, $machineName, $proto) "yellow"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = ''; DBName = ''; Level = $Level; Result = 'ProtocolNotReachable' })
			continue
		}

		# Resolve lane DB info (Startup.ini parsing cached by your helper)
		$dbInfo = $null
		try { $dbInfo = Get_All_Lanes_Database_Info -LaneNumber $laneKeyP }
		catch { $dbInfo = $null }

		if ($dbInfo -and ($dbInfo -isnot [hashtable]))
		{
			$tmpDbInfo = @{ }
			foreach ($p in $dbInfo.PSObject.Properties) { $tmpDbInfo[$p.Name] = $p.Value }
			$dbInfo = $tmpDbInfo
		}

		if (-not $dbInfo)
		{
			Write_Log ("Lane {0} ({1}): Could not get DB info. Skipping." -f $laneKeyP, $machineName) "yellow"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = ''; DBName = ''; Level = $Level; Result = 'NoDbInfo' })
			continue
		}

		$dbName = $dbInfo['DBName']
		$dbServer = $dbInfo['DBServer']
		$instanceName = $dbInfo['InstanceName']
		$csNamedPipes = $dbInfo['NamedPipesConnStr']
		$csTcp = $dbInfo['TcpConnStr']

		Write_Log ("`r`n--- Lane {0} ({1}) | Protocol={2} | DB: {3} on {4} ---" -f $laneKeyP, $machineName, $proto, $dbName, $dbServer) "blue"

		if ([string]::IsNullOrWhiteSpace($dbName) -or [string]::IsNullOrWhiteSpace($dbServer))
		{
			Write_Log "Incomplete DB info (DBName or DBServer missing). Skipping lane." "yellow"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'IncompleteDbInfo' })
			continue
		}

		# Guardrail: refuse if the application DB name is a system DB (protects from bad Startup.ini)
		$sysDbNames = @('master', 'model', 'msdb', 'tempdb')
		if ($sysDbNames -contains $dbName.ToLower())
		{
			Write_Log ("REFUSING: Startup.ini DBName resolved to system DB '{0}'. Skipping lane." -f $dbName) "red"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'Refused_SystemDbName' })
			continue
		}

		# Choose the correct raw connection string based on protocol from file
		$rawCs = $null
		if ($proto -eq 'TCP') { $rawCs = $csTcp }
		if ($proto -eq 'Named Pipes') { $rawCs = $csNamedPipes }

		if ([string]::IsNullOrWhiteSpace($rawCs))
		{
			Write_Log ("Lane {0} ({1}): Missing {2} connection string in dbInfo. Skipping." -f $laneKeyP, $machineName, $proto) "yellow"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'NoConnStrForProtocol' })
			continue
		}

		# Build MASTER connection string for system checks + repairs (no fallbacks: we obey protocol file)
		$connStr = $rawCs
		if ($connStr -match '(?i)\bDatabase\s*=\s*[^;]+;')
		{
			$connStr = [regex]::Replace($connStr, '(?i)\bDatabase\s*=\s*[^;]+;', 'Database=master;')
		}
		else
		{
			if ($connStr.Trim().EndsWith(';')) { $connStr = $connStr + 'Database=master;' }
			else { $connStr = $connStr + ';Database=master;' }
		}

		# Add safe extras if not already present (do NOT override auth)
		if ($connStr -notmatch '(?i)\bTrustServerCertificate\s*=') { $connStr += 'TrustServerCertificate=True;' }
		if ($connStr -notmatch '(?i)\bApplication\s*Name\s*=') { $connStr += 'Application Name=TBS_DBRepair;' }
		if ($connStr -notmatch '(?i)\bIntegrated\s*Security\s*=' -and $connStr -notmatch '(?i)\bUser\s*ID\s*=') { $connStr += 'Integrated Security=True;' }

		# Quote db identifier safely for T-SQL
		$qDb = "[" + ($dbName -replace "]", "]]") + "]"
		$dbNameQuoted = $dbName.Replace("'", "''")

		# ----------------------------------------
		# Probe: connection + DB existence/state
		# ----------------------------------------
		$ExecError = $null
		$probeRows = $null
		$probeTsql = @"
SELECT name, state_desc
FROM sys.databases
WHERE name = N'$dbNameQuoted';
"@

		try { $probeRows = & $invokeSqlTable $connStr $probeTsql 8 }
		catch { $ExecError = $_ }
		if ($ExecError)
		{
			Write_Log ("Lane {0} ({1}): Probe failed using {2}. Skipping. Error: {3}" -f $laneKeyP, $machineName, $proto, $ExecError.Exception.Message) "yellow"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'ConnProbeFailed' })
			continue
		}

		# Normalize probe result handling for both object array and DataTable
		$targetDbFound = $false
		$targetDbState = $null

		if ($probeRows -is [System.Data.DataTable])
		{
			if ($probeRows.Rows.Count -gt 0)
			{
				$targetDbFound = $true
				$targetDbState = [string]$probeRows.Rows[0]['state_desc']
			}
		}
		else
		{
			if ($probeRows -and ($probeRows | Measure-Object).Count -gt 0)
			{
				$targetDbFound = $true
				$targetDbState = [string]($probeRows | Select-Object -First 1 -ExpandProperty state_desc)
			}
		}

		if (-not $targetDbFound)
		{
			Write_Log ("Lane {0} ({1}): Target DB '{2}' not found in sys.databases. Skipping." -f $laneKeyP, $machineName, $dbName) "yellow"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'DbMissing' })
			continue
		}

		if ([string]::IsNullOrWhiteSpace($targetDbState)) { $targetDbState = 'Unknown' }
		Write_Log ("Target DB state (pre): {0}" -f $targetDbState) "gray"

		# ----------------------------------------
		# System DB health gate (tempdb/model/msdb/master states)
		# ----------------------------------------
		try
		{
			$badSystemDbs = @(& $getSystemDbProblems $connStr)
		}
		catch
		{
			Write_Log ("Lane {0} ({1}): WARN: could not query system DB states: {2}" -f $laneKeyP, $machineName, $_.Exception.Message) "yellow"
			$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'SystemDbStateUnknown' })
			continue
		}

		if ($badSystemDbs.Count -gt 0)
		{
			Write_Log ("Lane {0} ({1}): System DBs not ONLINE detected." -f $laneKeyP, $machineName) "yellow"
			foreach ($b in $badSystemDbs) { Write_Log ("  - {0}: {1}" -f $b.Name, $b.State) "yellow" }

			# Determine SQL service name based on instance
			$svcName = "MSSQLSERVER"
			if ($instanceName -and ($instanceName.ToUpper() -ne "MSSQLSERVER"))
			{
				$svcName = "MSSQL`$$instanceName"
			}

			# tempdb handling: offer restart SQL service
			$hasTempdbIssue = $false
			foreach ($b in $badSystemDbs) { if ($b.Name -eq 'tempdb') { $hasTempdbIssue = $true } }

			if ($hasTempdbIssue)
			{
				$msg = "Lane $laneKeyP ($machineName): tempdb is not ONLINE.`r`n`r`n" +
				"Would you like to restart the SQL Server service ($svcName) on $machineName now?`r`n" +
				"This will drop connections and recreate tempdb."

				$resp = [System.Windows.Forms.MessageBox]::Show(
					$msg,
					"Restart SQL Service for tempdb",
					[System.Windows.Forms.MessageBoxButtons]::YesNo,
					[System.Windows.Forms.MessageBoxIcon]::Warning
				)

				if ($resp -eq [System.Windows.Forms.DialogResult]::Yes)
				{
					Write_Log ("Attempting to restart service {0} on {1}..." -f $svcName, $machineName) "gray"

					# Stop service
					try { & sc.exe "\\$machineName" stop $svcName | Out-Null }
					catch { }

					# Wait for stopped up to ~60s
					$stopped = $false
					for ($i = 0; $i -lt 30; $i++)
					{
						Start-Sleep -Milliseconds 2000
						try
						{
							$chk = sc.exe "\\$machineName" query $svcName 2>$null
							$txt = if ($chk) { $chk | Out-String }
							else { "" }
							if ($txt -match 'STATE\s*:\s*\d+\s*STOPPED') { $stopped = $true; break }
						}
						catch { }
					}
					if ($stopped) { Write_Log "Service stopped." "gray" }
					else { Write_Log "WARN: Service did not report STOPPED in time." "yellow" }

					# Start service
					try { & sc.exe "\\$machineName" start $svcName | Out-Null }
					catch { }

					# Wait for running up to ~90s
					$running = $false
					for ($i = 0; $i -lt 45; $i++)
					{
						Start-Sleep -Milliseconds 2000
						try
						{
							$chk = sc.exe "\\$machineName" query $svcName 2>$null
							$txt = if ($chk) { $chk | Out-String }
							else { "" }
							if ($txt -match 'STATE\s*:\s*\d+\s*RUNNING') { $running = $true; break }
						}
						catch { }
					}
					if ($running) { Write_Log "Service started." "green" }
					else { Write_Log "ERROR: Service did not report RUNNING in time." "red" }

					# Re-connect after the restart (up to ~2 minutes)
					$reprobeOK = $false
					for ($t = 1; $t -le 60; $t++)
					{
						if (& $testSqlConnectivity $connStr) { $reprobeOK = $true; break }
						Start-Sleep -Milliseconds 2000
					}
					if (-not $reprobeOK)
					{
						Write_Log "ERROR: Could not reconnect after service restart; skipping lane." "red"
						$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'ServiceRestartFailed' })
						continue
					}

					try
					{
						$badSystemDbs = @(& $getSystemDbProblems $connStr)
					}
					catch
					{
						Write_Log ("ERROR: Could not re-check system DB states after restart: {0}" -f $_.Exception.Message) "red"
						$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'SystemDbReprobeFailed' })
						continue
					}

					$tempdbStillBad = $false
					foreach ($b in $badSystemDbs)
					{
						if ($b.Name -eq 'tempdb') { $tempdbStillBad = $true; break }
					}

					if ($tempdbStillBad)
					{
						Write_Log "ERROR: tempdb is still not ONLINE after SQL service restart. Skipping lane." "red"
						$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'TempdbStillNotOnline' })
						continue
					}
				}
				else
				{
					Write_Log "User declined SQL service restart for tempdb. Skipping lane with guidance: restart SQL service to recreate tempdb." "yellow"
					$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'TempdbNotOnline_Skipped' })
					continue
				}
			}

			# If master is bad -> do not automate
			$hasMaster = $false
			$hasModel = $false
			$hasMsdb = $false
			foreach ($b in $badSystemDbs)
			{
				if ($b.Name -eq 'master') { $hasMaster = $true }
				if ($b.Name -eq 'model') { $hasModel = $true }
				if ($b.Name -eq 'msdb') { $hasMsdb = $true }
			}

			if ($hasMaster)
			{
				Write_Log "CRITICAL: master is not ONLINE. Automated repair is not supported here." "red"
				Write_Log "Action: Restore master from known-good backup OR rebuild system DBs (setup.exe /ACTION=REBUILDDATABASE), then restore." "gray"
				$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'MasterNotOnline' })
				continue
			}

			# model/msdb -> optional emergency deep repair prompt
			$targets = @()
			if ($hasModel) { $targets += 'model' }
			if ($hasMsdb) { $targets += 'msdb' }

			if ($targets.Count -gt 0)
			{
				$list = ($targets -join ', ')
				$warn = "Lane $laneKeyP ($machineName): $list is not ONLINE.`r`n`r`n" +
				"Attempt DEEP REPAIR (EMERGENCY + REPAIR_ALLOW_DATA_LOSS) for these system DB(s)?`r`n" +
				"This can cause data loss. Recommended alternative is RESTORE from backup."

				$resp2 = [System.Windows.Forms.MessageBox]::Show(
					$warn,
					"Deep Repair system DB(s)?",
					[System.Windows.Forms.MessageBoxButtons]::YesNo,
					[System.Windows.Forms.MessageBoxIcon]::Warning
				)

				if ($resp2 -ne [System.Windows.Forms.DialogResult]::Yes)
				{
					Write_Log ("User declined deep repair for system DB(s): {0}. Skipping lane with guidance to RESTORE." -f $list) "yellow"
					$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'SystemDbNotOnline_Skipped' })
					continue
				}

				foreach ($sysDb in $targets)
				{
					Write_Log ("Attempting deep repair on system DB: {0}" -f $sysDb) "yellow"
					$qSys = "[" + ($sysDb -replace "]", "]]") + "]"

					# Best-effort sequence
					try
					{
						& $invokeSqlNonQuery $connStr "ALTER DATABASE $qSys SET EMERGENCY;" 30
					}
					catch { Write_Log ("WARN: EMERGENCY failed on {0}: {1}" -f $sysDb, $_.Exception.Message) "yellow" }

					try
					{
						& $invokeSqlNonQuery $connStr "ALTER DATABASE $qSys SET SINGLE_USER WITH ROLLBACK IMMEDIATE;" 30
					}
					catch { Write_Log ("WARN: SINGLE_USER failed on {0}: {1}" -f $sysDb, $_.Exception.Message) "yellow" }

					try
					{
						$ts = "DBCC CHECKDB ($qSys, REPAIR_ALLOW_DATA_LOSS) WITH ALL_ERRORMSGS;"
						[void](& $invokeSqlTable $connStr $ts $CommandTimeout)
						Write_Log ("Deep repair completed on {0}." -f $sysDb) "green"
					}
					catch { Write_Log ("Deep repair failed on {0}: {1}" -f $sysDb, $_.Exception.Message) "red" }

					try
					{
						& $invokeSqlNonQuery $connStr "ALTER DATABASE $qSys SET ONLINE;" 30
					}
					catch { Write_Log ("WARN: ONLINE restore failed on {0}: {1}" -f $sysDb, $_.Exception.Message) "yellow" }

					try
					{
						& $invokeSqlNonQuery $connStr "ALTER DATABASE $qSys SET MULTI_USER;" 30
					}
					catch { Write_Log ("WARN: MULTI_USER restore failed on {0}: {1}" -f $sysDb, $_.Exception.Message) "yellow" }
				}

				try
				{
					$badSystemDbs = @(& $getSystemDbProblems $connStr)
				}
				catch
				{
					Write_Log ("ERROR: Could not re-check system DB states after system DB repair: {0}" -f $_.Exception.Message) "red"
					$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'SystemDbReprobeFailed' })
					continue
				}

				if ($badSystemDbs.Count -gt 0)
				{
					Write_Log "System DBs still not ONLINE after repair attempt. Skipping lane." "red"
					foreach ($b in $badSystemDbs) { Write_Log ("  - {0}: {1}" -f $b.Name, $b.State) "red" }
					$laneSummary.Add([pscustomobject]@{ Lane = $laneKeyP; Machine = $machineName; Protocol = $proto; DBServer = $dbServer; DBName = $dbName; Level = $Level; Result = 'SystemDbStillNotOnline' })
					continue
				}
			}
		}

		# ----------------------------------------
		# Snapshot DB state BEFORE repair (sys.databases)
		# ----------------------------------------
		$stateBefore = 'Unknown'
		try
		{
			$stateBefore = & $getDatabaseState $connStr $dbName
		}
		catch { }

		if ([string]::IsNullOrWhiteSpace($stateBefore)) { $stateBefore = 'Unknown' }
		Write_Log ("DB state before: {0}" -f $stateBefore) "gray"

		# ----------------------------------------
		# Repair execution (always try to restore DB to MULTI_USER in finally)
		# ----------------------------------------
		$ok = $false
		$usedQuick = $false
		$usedDeep = $false
		$auditIssueCount = $null

		# In all repair modes we may toggle SINGLE_USER / EMERGENCY
		$didSingleUser = $false
		$didEmergency = $false

		# Quick / Deep run on ONE connection: with separate connections the lane's POS app could
		# take the single-user slot between SINGLE_USER and DBCC, and the repair then failed
		$repairConn = $null

		try
		{
			if ($Level -eq 'Audit')
			{
				Write_Log ("{0}: Running DBCC CHECKDB (Audit)..." -f $dbName) "gray"
				$auditIssueCount = & $getCheckDbIssueCount $connStr $qDb $CommandTimeout
				if ($auditIssueCount -gt 0)
				{
					$ok = $false
					Write_Log ("Audit completed. DBCC reported {0} row(s)." -f $auditIssueCount) "yellow"
				}
				else
				{
					$ok = $true
					Write_Log "Audit completed. DBCC reported no issues." "green"
				}
			}
			else
			{
				$repairConn = New-Object System.Data.SqlClient.SqlConnection $connStr
				$repairConn.Open()
				$runRepair = {
					param ([string]$Sql, [int]$Timeout)
					$c = $repairConn.CreateCommand()
					$c.CommandText = $Sql
					$c.CommandTimeout = $Timeout
					[void]$c.ExecuteNonQuery()
				}

				if ($Level -eq 'Deep')
				{
					Write_Log ("{0}: Deep repair (EMERGENCY + REPAIR_ALLOW_DATA_LOSS)..." -f $dbName) "gray"
					try { & $runRepair "ALTER DATABASE $qDb SET EMERGENCY;" 60; $didEmergency = $true }
					catch { Write_Log ("WARN: EMERGENCY failed: {0}" -f $_.Exception.Message) "yellow" }
				}
				else
				{
					Write_Log ("{0}: Quick repair (REPAIR_REBUILD)..." -f $dbName) "gray"
				}

				try { & $runRepair "ALTER DATABASE $qDb SET SINGLE_USER WITH ROLLBACK IMMEDIATE;" 60; $didSingleUser = $true }
				catch { Write_Log ("WARN: SINGLE_USER failed: {0}" -f $_.Exception.Message) "yellow" }

				$repairOption = if ($Level -eq 'Deep') { 'REPAIR_ALLOW_DATA_LOSS' } else { 'REPAIR_REBUILD' }
				& $runRepair "DBCC CHECKDB ($qDb, $repairOption) WITH ALL_ERRORMSGS, TABLERESULTS;" $CommandTimeout

				$ok = $true
				if ($Level -eq 'Deep') { $usedDeep = $true; Write_Log "Deep repair completed." "green" }
				else { $usedQuick = $true; Write_Log "Quick repair completed." "green" }
			}
		}
		catch
		{
			$ok = $false
			if ($Level -eq 'Audit')
			{
				Write_Log ("Audit reported errors or failed: {0}" -f $_.Exception.Message) "yellow"
			}
			else
			{
				Write_Log ("Repair failed: {0}" -f $_.Exception.Message) "red"
			}
		}
		finally
		{
			# ALWAYS put the DB back: MULTI_USER if we took SINGLE_USER, ONLINE if we set EMERGENCY.
			# Same connection when it is still open, a fresh one otherwise.
			$restoreSteps = @()
			if ($didSingleUser) { $restoreSteps += , @("ALTER DATABASE $qDb SET MULTI_USER;", 'MULTI_USER restore') }
			if ($didEmergency) { $restoreSteps += , @("ALTER DATABASE $qDb SET ONLINE;", 'ONLINE restore after EMERGENCY') }
			foreach ($step in $restoreSteps)
			{
				try
				{
					if ($repairConn -and $repairConn.State -eq 'Open')
					{
						$c = $repairConn.CreateCommand()
						$c.CommandText = $step[0]
						$c.CommandTimeout = 60
						[void]$c.ExecuteNonQuery()
					}
					else { & $invokeSqlNonQuery $connStr $step[0] 60 }
				}
				catch { Write_Log ("WARN: {0} failed: {1}" -f $step[1], $_.Exception.Message) "yellow" }
			}
			if ($repairConn) { $repairConn.Dispose() }
		}
		# ----------------------------------------
		# Snapshot state AFTER repair
		# ----------------------------------------
		$stateAfter = 'Unknown'
		try
		{
			$stateAfter = & $getDatabaseState $connStr $dbName
		}
		catch { }

		if ([string]::IsNullOrWhiteSpace($stateAfter)) { $stateAfter = 'Unknown' }
		Write_Log ("DB state after:  {0}" -f $stateAfter) "gray"

		# ----------------------------------------
		# Summarize lane result
		# ----------------------------------------
		$result = 'OK'
		if (-not $ok -and $Level -eq 'Audit')
		{
			$result = 'AuditFoundErrorsOrFailed'
		}
		elseif (-not $ok)
		{
			$result = 'Failed'
		}
		elseif ([string]::IsNullOrWhiteSpace($stateAfter) -or $stateAfter.ToUpper() -ne 'ONLINE')
		{
			$ok = $false
			if ($Level -eq 'Audit') { $result = 'AuditFinishedButStateNotOnline' }
			else { $result = 'PostRepairStateNotOnline' }
		}

		$laneSummary.Add([pscustomobject]@{
				Lane	    = $laneKeyP
				Machine	    = $machineName
				Protocol    = $proto
				DBServer    = $dbServer
				DBName	    = $dbName
				Level	    = $Level
				QuickRepair = $usedQuick
				DeepRepair  = $usedDeep
				Result	    = $result
			})

		Write_Log ("Lane {0} | DB {1} -> Level={2}, Protocol={3}, Quick={4}, Deep={5}, Result={6}" -f $laneKeyP, $dbName, $Level, $proto, $usedQuick, $usedDeep, $result) "gray"
	}

	# ----------------------------------------
	# Summary table + finish banner
	# ----------------------------------------
	Write_Log "`r`n================ Lane DB Repair Summary ================" "blue"
	if ($laneSummary.Count -gt 0)
	{
		Write_Log ((
				$laneSummary |
				Sort-Object Lane |
				Format-Table -AutoSize Lane, Machine, Protocol, DBServer, DBName, Level, QuickRepair, DeepRepair, Result |
				Out-String
			)) "gray"
	}
	else
	{
		Write_Log "No lanes processed." "yellow"
	}

	Write_Log "==================== Repair_LOC_Databases_On_Lanes Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Retrive_Transactions
# ---------------------------------------------------------------------------------------------------
# Description:
#   PowerShell port of trs_clt_reprocess.sqi: rebuilds the per-lane transaction list table
#   (SAL_HDR_SUS@TER) from SAL_HDR for a chosen date range and transaction range. Connects
#   per the Start_Lane_Protocol_Jobs preference (TCP / Named Pipes / File); lanes on File
#   protocol or any SQL failure fall back to writing trs_clt_reprocess.sqi to the lane XF folder.
#
# Parameters:
#   - StoreNumber  [string]: store to process (required)
#   - ForceSQI     [switch]: skip SQL and write the .sqi file for every lane
#
# Variables:
#   - $script:OfficePath: Storeman office root (resolved and back-filled)
#   - $script:FunctionResults['SqlModuleName']: SQL module to import when Invoke-Sqlcmd is missing
#
# Writes:
#   - XF<Store><Lane>\trs_clt_reprocess.sqi on File-protocol / failed lanes
#
# Returns:
#   PSCustomObject with a per-lane Summary (method, deleted/inserted counts).
# ===================================================================================================

function Retrive_Transactions
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[Parameter(Mandatory = $false)]
		[switch]$ForceSQI
	)

	# -----------------------------
	# Logging fallback (PS 5.1 safe)
	# -----------------------------
	$hasWriteLog = [bool](Get-Command Write_Log -ErrorAction SilentlyContinue)
	$log = {
		param ([string]$Msg,
			[string]$Color = "white")
		if ($hasWriteLog) { Write_Log $Msg $Color }
		else { Write-Host $Msg }
	}

	& $log "`r`n==================== Starting Retrive_Transactions ====================`r`n" "blue"

	# -----------------------------
	# Resolve OfficePath
	# -----------------------------
	$office = $null
	if ($script:OfficePath -and (Test-Path $script:OfficePath)) { $office = $script:OfficePath }
	elseif ($global:OfficePath -and (Test-Path $global:OfficePath)) { $office = $global:OfficePath }
	elseif ($OfficePath -and (Test-Path $OfficePath)) { $office = $OfficePath }
	else
	{
		$office = $script:StoremanOfficeRoots | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -First 1
		if (-not $office) { $office = $script:PrimaryStoremanOfficePath }
	}

	if (-not $script:OfficePath -or -not (Test-Path $script:OfficePath)) { $script:OfficePath = $office }
	$OfficePath = $script:OfficePath

	$st = $StoreNumber.Trim()
	if ($st -match '^\d+$') { $st = $st.PadLeft(3, '0') }

	# -----------------------------
	# Ensure Invoke-Sqlcmd exists
	#   If unavailable, continue in SQI-only mode
	# -----------------------------
	$canUseSql = $true
	if (-not (Get-Command Invoke-Sqlcmd -ErrorAction SilentlyContinue))
	{
		$modName = $null
		if ($script:FunctionResults -and $script:FunctionResults.ContainsKey('SqlModuleName'))
		{
			$modName = $script:FunctionResults['SqlModuleName']
		}
		foreach ($m in @($modName, "SqlServer", "SQLPS") | Where-Object { $_ })
		{
			try { Import-Module $m -ErrorAction Stop; break }
			catch { }
		}
	}
	$invokeSql = Get-Command Invoke-Sqlcmd -ErrorAction SilentlyContinue
	if (-not $invokeSql)
	{
		$canUseSql = $false
		& $log "Invoke-Sqlcmd not available. SQI mode will be used for all selected lanes." "yellow"
	}
	# SqlServer 22+ encrypts by default; lanes use self-signed certificates
	$sqlExtra = @{ }
	if ($invokeSql -and $invokeSql.Parameters.ContainsKey('TrustServerCertificate')) { $sqlExtra['TrustServerCertificate'] = $true }

	if (-not (Get-Command Get_All_Lanes_Database_Info -ErrorAction SilentlyContinue))
	{
		& $log "Get_All_Lanes_Database_Info not found. Cannot guarantee correct DB connections." "red"
		return
	}

	# -----------------------------
	# UI: Date range + transaction range (FIL1/FIL2)
	# -----------------------------
	Add-Type -AssemblyName System.Windows.Forms
	Add-Type -AssemblyName System.Drawing

	$form = New-Object System.Windows.Forms.Form
	$form.Text = "TRS CLT Reprocess - Select Range"
	$form.Size = New-Object System.Drawing.Size(420, 240)
	$form.StartPosition = "CenterScreen"
	$form.MaximizeBox = $false
	$form.MinimizeBox = $false
	$form.FormBorderStyle = 'FixedDialog'

	$lblStart = New-Object System.Windows.Forms.Label
	$lblStart.Text = "Start Date:"
	$lblStart.Location = New-Object System.Drawing.Point(12, 20)
	$lblStart.AutoSize = $true
	$form.Controls.Add($lblStart)

	$dtStart = New-Object System.Windows.Forms.DateTimePicker
	$dtStart.Format = [System.Windows.Forms.DateTimePickerFormat]::Short
	$dtStart.Location = New-Object System.Drawing.Point(120, 16)
	$dtStart.Width = 120
	$form.Controls.Add($dtStart)

	$lblStop = New-Object System.Windows.Forms.Label
	$lblStop.Text = "Stop Date:"
	$lblStop.Location = New-Object System.Drawing.Point(12, 55)
	$lblStop.AutoSize = $true
	$form.Controls.Add($lblStop)

	$dtStop = New-Object System.Windows.Forms.DateTimePicker
	$dtStop.Format = [System.Windows.Forms.DateTimePickerFormat]::Short
	$dtStop.Location = New-Object System.Drawing.Point(120, 51)
	$dtStop.Width = 120
	$form.Controls.Add($dtStop)

	$lblFil1 = New-Object System.Windows.Forms.Label
	$lblFil1.Text = "Tran Start (FIL1):"
	$lblFil1.Location = New-Object System.Drawing.Point(12, 92)
	$lblFil1.AutoSize = $true
	$form.Controls.Add($lblFil1)

	$numFil1 = New-Object System.Windows.Forms.NumericUpDown
	$numFil1.Location = New-Object System.Drawing.Point(160, 88)
	$numFil1.Width = 140
	$numFil1.Minimum = 0
	$numFil1.Maximum = 99999999
	$numFil1.Value = 0
	$form.Controls.Add($numFil1)

	$lblFil2 = New-Object System.Windows.Forms.Label
	$lblFil2.Text = "Tran Stop (FIL2):"
	$lblFil2.Location = New-Object System.Drawing.Point(12, 127)
	$lblFil2.AutoSize = $true
	$form.Controls.Add($lblFil2)

	$numFil2 = New-Object System.Windows.Forms.NumericUpDown
	$numFil2.Location = New-Object System.Drawing.Point(160, 123)
	$numFil2.Width = 140
	$numFil2.Minimum = 0
	$numFil2.Maximum = 99999999
	$numFil2.Value = 99999999
	$form.Controls.Add($numFil2)

	$btnOk = New-Object System.Windows.Forms.Button
	$btnOk.Text = "OK"
	$btnOk.Location = New-Object System.Drawing.Point(95, 165)
	$btnOk.Add_Click({
			if ([int]$numFil1.Value -gt [int]$numFil2.Value)
			{
				[System.Windows.Forms.MessageBox]::Show(
					"FIL1 must be <= FIL2.",
					"Invalid Range",
					[System.Windows.Forms.MessageBoxButtons]::OK,
					[System.Windows.Forms.MessageBoxIcon]::Warning
				) | Out-Null
				return
			}

			$form.Tag = @{
				Start = $dtStart.Value
				Stop  = $dtStop.Value
				FIL1  = [int]$numFil1.Value
				FIL2  = [int]$numFil2.Value
			}
			$form.DialogResult = [System.Windows.Forms.DialogResult]::OK
			$form.Close()
		})
	$form.Controls.Add($btnOk)

	$btnCancel = New-Object System.Windows.Forms.Button
	$btnCancel.Text = "Cancel"
	$btnCancel.Location = New-Object System.Drawing.Point(210, 165)
	$btnCancel.Add_Click({
			$form.Tag = $null
			$form.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
			$form.Close()
		})
	$form.Controls.Add($btnCancel)

	$form.AcceptButton = $btnOk
	$form.CancelButton = $btnCancel

	$dlg = $form.ShowDialog()
	if ($dlg -ne [System.Windows.Forms.DialogResult]::OK -or -not $form.Tag)
	{
		& $log "User cancelled range selection." "yellow"
		& $log "==================== Retrive_Transactions Completed ====================" "blue"
		return
	}

	$startDate = $form.Tag.Start.Date
	$stopDate = $form.Tag.Stop.Date
	$startDT = $startDate
	$stopDT = $stopDate.AddDays(1).AddSeconds(-1)

	$fil1 = [int]$form.Tag.FIL1
	$fil2 = [int]$form.Tag.FIL2

	# ALWAYS clear (no duplicates allowed)
	$doClear = $true

	& $log ("Range: {0} 00:00:00  ->  {1} 23:59:59 | FIL1={2} FIL2={3} | ClearExisting=True (forced)" -f `
		$startDate.ToString("MM/dd/yyyy"), $stopDate.ToString("MM/dd/yyyy"), $fil1, $fil2) "green"

	# -----------------------------
	# Lane selection
	# -----------------------------
	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane" -Title "Select Lanes to Build Transaction List"
	if (-not $selection -or -not $selection.ContainsKey('Lanes') -or -not $selection.Lanes -or $selection.Lanes.Count -eq 0)
	{
		& $log "Lane selection cancelled / empty." "yellow"
		return
	}

	$lanes = @($selection.Lanes)
	& $log ("Target lanes: {0}" -f ($lanes -join ', ')) "yellow"

	# -----------------------------
	# Processing
	# -----------------------------
	$summary = New-Object System.Collections.Generic.List[object]

	foreach ($laneRaw in $lanes)
	{
		$l = $laneRaw.ToString().Trim()
		if ($l -match '^\d+$') { $l = ("{0:D3}" -f [int]$l) }
		$lane = $l

		$laneInfo = $null
		try { $laneInfo = Get_All_Lanes_Database_Info -LaneNumber $lane }
		catch { $laneInfo = $null }

		if ($laneInfo -and ($laneInfo -isnot [hashtable]))
		{
			$tmp = @{ }
			foreach ($p in $laneInfo.PSObject.Properties) { $tmp[$p.Name] = $p.Value }
			$laneInfo = $tmp
		}

		$dbName = $null
		if ($laneInfo -and $laneInfo.ContainsKey('DBName')) { $dbName = [string]$laneInfo['DBName'] }

		$machine = $null
		if ($laneInfo -and $laneInfo.ContainsKey('MachineName')) { $machine = [string]$laneInfo['MachineName'] }
		if ([string]::IsNullOrWhiteSpace($machine) -and $script:FunctionResults -and $script:FunctionResults.ContainsKey('LaneNumToMachineName'))
		{
			try { $machine = [string]$script:FunctionResults['LaneNumToMachineName'][$lane] }
			catch { }
		}

		$preferredProtocolRaw = $null
		if ($script:LaneProtocols)
		{
			$tryKeys = @($lane, $laneRaw)
			if ($machine) { $tryKeys += @($machine, $machine.ToLower()) }
			foreach ($k in $tryKeys)
			{
				if ($script:LaneProtocols.ContainsKey($k)) { $preferredProtocolRaw = [string]$script:LaneProtocols[$k]; break }
			}
		}
		$protoNorm = if ($preferredProtocolRaw) { $preferredProtocolRaw.Trim().ToLower() }
		else { $null }

		$useSql = $canUseSql
		if ($ForceSQI) { $useSql = $false }
		elseif ($protoNorm -in @('file', 'offline')) { $useSql = $false }
		elseif ([string]::IsNullOrWhiteSpace($dbName)) { $useSql = $false }

		$transListTable = "SAL_HDR_SUS$lane"
		$targetTbl = "dbo.$transListTable"

		$startIso = $startDT.ToString("yyyy-MM-ddTHH:mm:ss")
		$stopIso = $stopDT.ToString("yyyy-MM-ddTHH:mm:ss")

		$sql = @"
SET NOCOUNT ON;

DECLARE @StartDate datetime = CONVERT(datetime, '$startIso', 126);
DECLARE @StopDate  datetime = CONVERT(datetime, '$stopIso', 126);
DECLARE @Deleted int = 0;
DECLARE @Inserted int = 0;

IF OBJECT_ID('$targetTbl','U') IS NULL
BEGIN
    SELECT TOP 0 * INTO $targetTbl FROM dbo.SAL_HDR;
END

DELETE FROM $targetTbl;
SET @Deleted = @@ROWCOUNT;

INSERT INTO $targetTbl
SELECT *
FROM dbo.SAL_HDR
WHERE F1067 = 'CLOSE'
  AND F254 >= @StartDate
  AND F254 <= @StopDate
  AND F1032 >= $fil1
  AND F1032 <= $fil2;

SET @Inserted = @@ROWCOUNT;

SELECT @Deleted AS DeletedRows, @Inserted AS InsertedRows;
"@

		$method = $null
		$usedProtoDisplay = $preferredProtocolRaw
		$inserted = $null
		$deleted = $null
		$sqiPath = $null
		$errText = $null

		if ($useSql)
		{
			$npServer = if ($laneInfo -and $laneInfo.ContainsKey('NamedPipes')) { [string]$laneInfo['NamedPipes'] }
			else { $null }
			$tcpServer = if ($laneInfo -and $laneInfo.ContainsKey('TcpServer')) { [string]$laneInfo['TcpServer'] }
			else { $null }

			$attempts = @()
			if ($protoNorm -eq 'tcp')
			{
				$attempts += [pscustomobject]@{ Proto = 'TCP'; Server = $tcpServer }
				$attempts += [pscustomobject]@{ Proto = 'Named Pipes'; Server = $npServer }
			}
			elseif ($protoNorm -eq 'named pipes' -or $protoNorm -match 'pipe')
			{
				$attempts += [pscustomobject]@{ Proto = 'Named Pipes'; Server = $npServer }
				$attempts += [pscustomobject]@{ Proto = 'TCP'; Server = $tcpServer }
			}
			else
			{
				$attempts += [pscustomobject]@{ Proto = 'Named Pipes'; Server = $npServer }
				$attempts += [pscustomobject]@{ Proto = 'TCP'; Server = $tcpServer }
			}

			$connected = $false
			foreach ($a in $attempts)
			{
				if ([string]::IsNullOrWhiteSpace($a.Server)) { continue }

				try
				{
					$res = Invoke-Sqlcmd -ServerInstance $a.Server -Database $dbName -Query $sql -QueryTimeout 120 -ErrorAction Stop @sqlExtra

					# Robust parse
					$row = $null
					if ($res -is [System.Data.DataSet])
					{
						if ($res.Tables.Count -gt 0 -and $res.Tables[0].Rows.Count -gt 0) { $row = $res.Tables[0].Rows[0] }
					}
					elseif ($res -is [System.Data.DataTable])
					{
						if ($res.Rows.Count -gt 0) { $row = $res.Rows[0] }
					}
					elseif ($res -is [System.Array])
					{
						if ($res.Count -gt 0) { $row = $res[0] }
					}
					else { $row = $res }

					if ($row -is [System.Data.DataRow])
					{
						if ($row.Table.Columns.Contains('InsertedRows')) { $inserted = [int]$row['InsertedRows'] }
						if ($row.Table.Columns.Contains('DeletedRows')) { $deleted = [int]$row['DeletedRows'] }
					}
					elseif ($row)
					{
						try { if ($row.PSObject.Properties.Match('InsertedRows').Count -gt 0) { $inserted = [int]$row.InsertedRows } }
						catch { }
						try { if ($row.PSObject.Properties.Match('DeletedRows').Count -gt 0) { $deleted = [int]$row.DeletedRows } }
						catch { }
					}

					$connected = $true
					$method = "SQL"
					$usedProtoDisplay = $a.Proto
					break
				}
				catch
				{
					$errText = $_.Exception.Message
					$connected = $false
				}
			}

			if (-not $connected)
			{
				& $log ("SQL failed on lane {0} ({1}). Falling back to SQI. Error: {2}" -f $lane, $machine, $errText) "yellow"
				$useSql = $false
			}
		}

		if (-not $useSql)
		{
			$method = "SQI"

			$xfDir = Join-Path $office ("XF{0}{1}" -f $st, $lane)
			if (-not (Test-Path $xfDir))
			{
				try { New-Item -Path $xfDir -ItemType Directory -Force | Out-Null }
				catch { }
			}

			$sqiPath = Join-Path $xfDir "trs_clt_reprocess.sqi"

			$startFmt = $startDate.ToString("MM/dd/yyyy")
			$stopFmt = $stopDate.ToString("MM/dd/yyyy")

			$sqi = New-Object System.Text.StringBuilder
			[void]$sqi.AppendLine("@WIZSET(DETAIL=D);")
			[void]$sqi.AppendLine("@WIZINIT;")
			[void]$sqi.AppendLine("@WIZDATES(START=$startFmt,STOP=$stopFmt);")
			[void]$sqi.AppendLine("@WIZSET(FIL1=$fil1);")
			[void]$sqi.AppendLine("@WIZSET(FIL2=$fil2);")
			[void]$sqi.AppendLine("")
			[void]$sqi.AppendLine("@WIZRPL(TRANS_LIST=SAL_HDR_SUS@TER);")
			[void]$sqi.AppendLine("@CREATE(@WIZGET(TRANS_LIST),HDRSAL);")
			[void]$sqi.AppendLine("")
			# Always clear (forced)
			[void]$sqi.AppendLine("DELETE FROM @WIZGET(TRANS_LIST);")
			[void]$sqi.AppendLine("")
			[void]$sqi.AppendLine("INSERT INTO @WIZGET(TRANS_LIST) SELECT @DBFLD(@WIZGET(TRANS_LIST)) FROM SAL_HDR@WIZGET(TRANS_LOCAL)")
			[void]$sqi.AppendLine("WHERE F1067='CLOSE' and F254>='@WIZGET(START)' and F254<='@WIZGET(STOP)' AND")
			[void]$sqi.AppendLine("F1032>=@WIZGET(FIL1) and F1032<=@WIZGET(FIL2);")

			try
			{
				$sqi.ToString() | Out-File -FilePath $sqiPath -Encoding ASCII -Force
				try { [System.IO.File]::SetAttributes($sqiPath, [System.IO.FileAttributes]::Normal) }
				catch { }
				$usedProtoDisplay = "File"
				# We can't know the rowcount from SQI here
				$deleted = "N/A"
				& $log ("SQI deployed for lane {0} -> {1}" -f $lane, $sqiPath) "green"
			}
			catch
			{
				$errText = $_.Exception.Message
				& $log ("Failed to write SQI for lane {0} ({1}): {2}" -f $lane, $machine, $errText) "red"
			}
		}

		$protoOut = $usedProtoDisplay
		if ([string]::IsNullOrWhiteSpace($protoOut)) { $protoOut = $preferredProtocolRaw }
		if ([string]::IsNullOrWhiteSpace($protoOut)) { $protoOut = "Unknown" }

		$summary.Add([pscustomobject]@{
				Lane	 = $lane
				Machine  = $machine
				Protocol = $protoOut
				Method   = $method
				Deleted  = $deleted
				Inserted = $inserted
				SQIPath  = $sqiPath
				Error    = $errText
			})
	}

	& $log "`r`n----- Build Summary -----" "yellow"
	try { $summary | Sort-Object Lane | Format-Table -AutoSize | Out-String | ForEach-Object { & $log $_ "blue" } }
	catch { & $log ("Could not format summary table: {0}" -f $_.Exception.Message) "red" }

	$totInserted = ($summary | Where-Object { $_.Method -eq 'SQL' -and $_.Inserted -ne $null } | Measure-Object Inserted -Sum).Sum
	$totDeleted = ($summary | Where-Object { $_.Method -eq 'SQL' -and $_.Deleted -ne $null -and $_.Deleted -is [int] } | Measure-Object Deleted -Sum).Sum
	& $log ("Totals (SQL lanes): Deleted={0}  Inserted={1}" -f ($totDeleted -as [int]), ($totInserted -as [int])) "green"

	& $log "`r`n==================== Retrive_Transactions Completed ====================`r`n" "blue"

	return [pscustomobject]@{ Summary = $summary }
}

# ===================================================================================================
#                              FUNCTION: Schedule_Lane_DB_Maintenance
# ---------------------------------------------------------------------------------------------------
# Description:
#   Deploys the lane DB maintenance script to the selected lanes: writes the Lane SQL script
#   to each lane's Office folder and a scheduler macro in the local XF folder so the repair
#   runs on the chosen repeat interval. Files are written as ANSI (Windows-1252), CRLF, no BOM,
#   and the archive bit is cleared after writing.
#
# Parameters:
#   - StoreNumber  [string]: store to process (required)
#
# Variables:
#   - $LaneSQLScript: lane maintenance SQL text (must be generated first)
#   - $script:FunctionResults['LaneNumToMachineName']: lane map (input, auto-refreshed)
#
# Writes:
#   - Lane maintenance script + scheduler macro on the selected lanes and in the local XF folder
# ===================================================================================================

function Schedule_Lane_DB_Maintenance
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber
	)
	Write_Log "`r`n==================== Starting Schedule_Lane_DB_Maintenance ====================`r`n" "blue"

	# Normally generated by the startup warmup; generate it now if the menu was used before that
	if (-not $script:LaneSQLScript)
	{
		try { Generate_SQL_Scripts -StoreNumber $StoreNumber | Out-Null }
		catch { }
	}
	$LaneSQLScript = $script:LaneSQLScript
	if (-not $LaneSQLScript)
	{
		Write_Log "Lane SQL script content variable (`\$LaneSQLScript`) is empty or not defined." "red"
		return
	}

	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
	if (-not $selection -or -not $selection.Lanes)
	{
		Write_Log "No lanes selected. Cancelling operation." "yellow"
		return
	}
	# --- ENSURE NODE MAPPING IS PRESENT ---
	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	if (-not $LaneNumToMachineName)
	{
		$null = Retrieve_Nodes -StoreNumber $StoreNumber
		$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
		if (-not $LaneNumToMachineName)
		{
			Write_Log "Failed to retrieve lane-to-machine mapping for store $StoreNumber." "red"
			return
		}
	}
	$ansiEncoding = [System.Text.Encoding]::GetEncoding(1252)
	$LaneSQLScriptContent = $LaneSQLScript -replace "`r?`n", "`r`n"

	# Prompt user for the repeat interval in days
	Add-Type -AssemblyName System.Windows.Forms
	$daysPromptForm = New-Object System.Windows.Forms.Form
	$daysPromptForm.Text = "Lane DB Maintenance - Schedule Interval"
	$daysPromptForm.Width = 350
	$daysPromptForm.Height = 160
	$daysPromptForm.StartPosition = "CenterScreen"

	$label = New-Object System.Windows.Forms.Label
	$label.Text = "How many days between each run (minimum 1):"
	$label.AutoSize = $true
	$label.Location = New-Object System.Drawing.Point(15, 20)
	$daysPromptForm.Controls.Add($label)

	$textBox = New-Object System.Windows.Forms.TextBox
	$textBox.Location = New-Object System.Drawing.Point(20, 50)
	$textBox.Width = 60
	$textBox.Text = "7"
	$daysPromptForm.Controls.Add($textBox)

	$okButton = New-Object System.Windows.Forms.Button
	$okButton.Text = "OK"
	$okButton.Location = New-Object System.Drawing.Point(90, 90)
	$okButton.Add_Click({ $daysPromptForm.DialogResult = [System.Windows.Forms.DialogResult]::OK })
	$daysPromptForm.Controls.Add($okButton)

	$cancelButton = New-Object System.Windows.Forms.Button
	$cancelButton.Text = "Cancel"
	$cancelButton.Location = New-Object System.Drawing.Point(170, 90)
	$cancelButton.Add_Click({ $daysPromptForm.DialogResult = [System.Windows.Forms.DialogResult]::Cancel })
	$daysPromptForm.Controls.Add($cancelButton)

	$daysPromptForm.AcceptButton = $okButton
	$daysPromptForm.CancelButton = $cancelButton

	if ($daysPromptForm.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK)
	{
		Write_Log "Operation cancelled by user in interval prompt." "yellow"
		return
	}

	[int]$UserDays = 0
	if ([int]::TryParse($textBox.Text, [ref]$UserDays) -and $UserDays -ge 1)
	{
		$RepeatDays = $UserDays
	}
	else
	{
		Write_Log "Invalid or no interval provided, using 7 days." "yellow"
		$RepeatDays = 7
	}

	foreach ($LaneNumber in $selection.Lanes)
	{
		# ----------- USE MAPPING ----------
		$LaneMachineName = $LaneNumToMachineName[$LaneNumber]
		if (-not $LaneMachineName)
		{
			Write_Log "Could not resolve machine name for lane $LaneNumber. Skipping." "red"
			continue
		}
		$LaneOfficeFolder = "\\$LaneMachineName\storeman\office"
		$DestScriptPath = Join-Path $LaneOfficeFolder "LANE_DB_MAINTENANCE.SQI"
		$LocalXFPath = Join-Path $OfficePath "XF$StoreNumber$LaneNumber"
		$SchedulerMacroPath = Join-Path $LocalXFPath "Add_LaneDBMaintenance_to_RUN_TAB.sqi"

		# Prepare scheduler macro content (unique task number per lane if needed)
		$TaskNumber = 750
		$HostTarget = "{0:D3}" -f [int]$LaneNumber
		$CommandToRun = 'sqi=LANE_DB_MAINTENANCE'
		$ExecTarget = $HostTarget
		$TaskName = 'Lane DB Maintenance'
		$ManualAllowed = 1
		$CatchupMissed = 1
		$WeeklyDays = $RepeatDays
		$Months = 0
		$Minutes = 0
		$LastRanDate = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss.fff")
		$NextRunDate = (Get-Date).AddDays($RepeatDays).ToString("yyyy-MM-dd HH:mm:ss.fff")


		$SchedulerMacroContent = @"
 /* First delete the scheduled maintenance if it exists */
 DELETE FROM RUN_TAB WHERE F1103 = '$CommandToRun' AND F1000 = '$HostTarget';

 /* Insert the scheduled weekly maintenance */
 INSERT INTO RUN_TAB (F1102, F1000, F1103, F1104, F1105, F1107, F1108, F1109, F1111, F1114, F1115, F1117)
 VALUES ($TaskNumber, '$HostTarget', '$CommandToRun', '$ExecTarget', '$LastRanDate', '$NextRunDate', $ManualAllowed, '$TaskName', $CatchupMissed, $WeeklyDays, $Months, $Minutes);

 /* Activate the new task right away */
 @EXEC(SQL=ACTIVATE_ACCEPT_SYS);
"@ -replace "`r?`n", "`r`n"

		try
		{
			if (-not (Test-Path $LaneOfficeFolder))
			{
				Write_Log "Remote office folder not found: $LaneOfficeFolder (lane may be offline or not shared)." "red"
				continue
			}
			if (-not (Test-Path $LocalXFPath))
			{
				Write_Log "Local XF folder not found: $LocalXFPath (scheduler macro not dropped for this lane)." "red"
				continue
			}
		}
		catch
		{
			Write_Log "Failed to create required directories: $_" "red"
			continue
		}

		# Write the lane repair script
		try
		{
			[System.IO.File]::WriteAllText($DestScriptPath, $LaneSQLScriptContent, $ansiEncoding)
			Set-ItemProperty -Path $DestScriptPath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
			Write_Log "Wrote lane DB maintenance script to $DestScriptPath" "green"
		}
		catch
		{
			Write_Log "Failed to write script: $_" "red"
			continue
		}

		# Write the scheduler macro
		try
		{
			[System.IO.File]::WriteAllText($SchedulerMacroPath, $SchedulerMacroContent, $ansiEncoding)
			Set-ItemProperty -Path $SchedulerMacroPath -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
			Write_Log "Scheduler SQL macro created at $SchedulerMacroPath" "green"
		}
		catch
		{
			Write_Log "Failed to write scheduler macro: $_" "red"
			continue
		}

		# Remove archive bit if set (optional)
		try
		{
			if (Test-Path $DestScriptPath)
			{
				$file = Get-Item -Path $DestScriptPath
				if ($file.Attributes -band [System.IO.FileAttributes]::Archive)
				{
					$file.Attributes = $file.Attributes -bxor [System.IO.FileAttributes]::Archive
					Write_Log "Removed the archive bit from '$DestScriptPath'." "green"
				}
			}
		}
		catch
		{
			Write_Log "Failed to remove the archive bit from '$DestScriptPath'. Error: $_" "red"
		}
	}

	Write_Log "`r`n==================== Schedule_Lane_DB_Maintenance Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Schedule_LaneDB_Backup
# ---------------------------------------------------------------------------------------------------
# Description:
#   Lane DB backup wizard: pick lanes (only those with a valid TCP/Named Pipes protocol),
#   prompt for schedule details, then per lane create Run_<machine>DB_Backup.ps1 under the
#   per-machine scripts folder and schedule a task that backs up to
#   $BackupRoot\<machine>\STORESQL_<timestamp>.bak using the detected protocol.
#
# Parameters:
#   (none)
#
# Variables:
#   - $script:FunctionResults: StoreNumber, node mappings
#   - $script:LaneProtocols: per-lane protocol (TCP / Named Pipes / File)
#   - $ScriptsFolder / $BackupRoot: per-machine script and backup locations
# ===================================================================================================

function Schedule_LaneDB_Backup
{
	Write_Log "`r`n==================== Starting Schedule_LaneDB_Backup ====================`r`n" "blue"

	# 1. Node selection (lanes only)
	$StoreNumber = $script:FunctionResults['StoreNumber']
	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane" -Title "Select Lanes for DB Backup"
	if (-not $selection -or -not $selection.Lanes -or $selection.Lanes.Count -eq 0)
	{
		Write_Log "No lanes selected for backup." "yellow"
		return
	}

	# 2. Check ProtocolResults for connectivity
	$goodLanes = @()
	foreach ($lane in $selection.Lanes)
	{
		$protocol = if ($script:LaneProtocols) { $script:LaneProtocols[$lane] }
		if ($protocol -in @("TCP", "Named Pipes")) { $goodLanes += $lane }
		else { Write_Log "Lane $lane not available in ProtocolResults or protocol not valid. Skipping." "yellow" }
	}
	if (-not $goodLanes -or $goodLanes.Count -eq 0)
	{
		Write_Log "No selected lanes are available for DB backup." "red"
		return
	}

	# 3. Prompt for backup options, user and password (all in one form, more spacing)
	Add-Type -AssemblyName System.Windows.Forms
	Add-Type -AssemblyName System.Drawing

	$form = New-Object Windows.Forms.Form
	$form.Text = "Configure Lane DB Backup Scheduler"
	$form.Size = [Drawing.Size]::new(500, 425) # Larger form
	$form.StartPosition = "CenterScreen"
	$form.FormBorderStyle = 'FixedDialog'
	$form.MaximizeBox = $false
	$form.MinimizeBox = $false

	# -- Backup Settings GroupBox --
	$grpBackup = New-Object Windows.Forms.GroupBox
	$grpBackup.Text = "Backup Settings"
	$grpBackup.Location = [Drawing.Point]::new(20, 15)
	$grpBackup.Size = [Drawing.Size]::new(450, 180)
	$form.Controls.Add($grpBackup)

	# Time
	$lblTime = New-Object Windows.Forms.Label
	$lblTime.Text = "Time to run backup (24h, HH:mm):"
	$lblTime.Location = [Drawing.Point]::new(25, 35)
	$lblTime.Size = [Drawing.Size]::new(200, 20)
	$grpBackup.Controls.Add($lblTime)
	$txtTime = New-Object Windows.Forms.MaskedTextBox
	$txtTime.Mask = "00:00"
	$txtTime.Text = "01:00"
	$txtTime.Location = [Drawing.Point]::new(260, 33)
	$txtTime.Size = [Drawing.Size]::new(80, 24)
	$grpBackup.Controls.Add($txtTime)

	# Frequency
	$lblFreq = New-Object Windows.Forms.Label
	$lblFreq.Text = "Frequency (every X days):"
	$lblFreq.Location = [Drawing.Point]::new(25, 70)
	$lblFreq.Size = [Drawing.Size]::new(200, 20)
	$grpBackup.Controls.Add($lblFreq)
	$numFreq = New-Object Windows.Forms.NumericUpDown
	$numFreq.Minimum = 1
	$numFreq.Maximum = 31
	$numFreq.Value = 1
	$numFreq.Location = [Drawing.Point]::new(260, 68)
	$numFreq.Size = [Drawing.Size]::new(80, 24)
	$grpBackup.Controls.Add($numFreq)

	# Retention
	$lblKeep = New-Object Windows.Forms.Label
	$lblKeep.Text = "How many backups to keep:"
	$lblKeep.Location = [Drawing.Point]::new(25, 105)
	$lblKeep.Size = [Drawing.Size]::new(200, 20)
	$grpBackup.Controls.Add($lblKeep)
	$numKeep = New-Object Windows.Forms.NumericUpDown
	$numKeep.Minimum = 1
	$numKeep.Maximum = 99
	$numKeep.Value = 1
	$numKeep.Location = [Drawing.Point]::new(260, 103)
	$numKeep.Size = [Drawing.Size]::new(80, 24)
	$grpBackup.Controls.Add($numKeep)

	# Backup folder (local copy) - picker opens at the default; accept it or switch
	$lblDir = New-Object Windows.Forms.Label
	$lblDir.Text = "Backup folder (local copy):"
	$lblDir.Location = [Drawing.Point]::new(25, 140)
	$lblDir.Size = [Drawing.Size]::new(145, 18)
	$grpBackup.Controls.Add($lblDir)
	$txtDir = New-Object Windows.Forms.TextBox
	$txtDir.ReadOnly = $true
	$txtDir.Text = $script:BackupRoot.TrimEnd('\')
	$txtDir.Location = [Drawing.Point]::new(175, 138)
	$txtDir.Size = [Drawing.Size]::new(165, 22)
	$grpBackup.Controls.Add($txtDir)
	$btnBrowse = New-Object Windows.Forms.Button
	$btnBrowse.Text = "Browse..."
	$btnBrowse.Location = [Drawing.Point]::new(346, 136)
	$btnBrowse.Size = [Drawing.Size]::new(78, 24)
	$btnBrowse.Add_Click({
		$p = Select-FolderOrDefault -initialPath $txtDir.Text -description "Choose where to keep the LOCAL copy of the lane DB backup (a <machine> subfolder is created inside it)."
		if ($p) { $txtDir.Text = $p }
	})
	$grpBackup.Controls.Add($btnBrowse)

	# -- Task User/Password GroupBox --
	$grpUser = New-Object Windows.Forms.GroupBox
	$grpUser.Text = "Scheduled Task Credentials"
	$grpUser.Location = [Drawing.Point]::new(20, 205)
	$grpUser.Size = [Drawing.Size]::new(450, 100)
	$form.Controls.Add($grpUser)

	# Username (default Administrator)
	$lblUser = New-Object Windows.Forms.Label
	$lblUser.Text = "Task user (default: Administrator):"
	$lblUser.Location = [Drawing.Point]::new(25, 35)
	$lblUser.Size = [Drawing.Size]::new(200, 18)
	$grpUser.Controls.Add($lblUser)
	$txtUser = New-Object Windows.Forms.TextBox
	$txtUser.Text = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
	$txtUser.Location = [Drawing.Point]::new(260, 33)
	$txtUser.Size = [Drawing.Size]::new(130, 24)
	$grpUser.Controls.Add($txtUser)

	# Password (masked)
	$lblPwd = New-Object Windows.Forms.Label
	$lblPwd.Text = "Task password (blank = only when user logged in):"
	$lblPwd.Location = [Drawing.Point]::new(25, 65)
	$lblPwd.Size = [Drawing.Size]::new(270, 18)
	$grpUser.Controls.Add($lblPwd)
	$txtPwd = New-Object Windows.Forms.TextBox
	$txtPwd.Text = ""
	$txtPwd.Location = [Drawing.Point]::new(305, 63)
	$txtPwd.Size = [Drawing.Size]::new(120, 24)
	$txtPwd.UseSystemPasswordChar = $true
	$grpUser.Controls.Add($txtPwd)

	# OK/Cancel
	$btnOK = New-Object Windows.Forms.Button
	$btnOK.Text = "OK"
	$btnOK.Location = [Drawing.Point]::new(120, 325)
	$btnOK.Size = [Drawing.Size]::new(110, 38)
	$btnOK.Font = [System.Drawing.Font]::new("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
	$btnOK.DialogResult = [System.Windows.Forms.DialogResult]::OK
	$form.AcceptButton = $btnOK
	$form.Controls.Add($btnOK)

	$btnCancel = New-Object Windows.Forms.Button
	$btnCancel.Text = "Cancel"
	$btnCancel.Location = [Drawing.Point]::new(260, 325)
	$btnCancel.Size = [Drawing.Size]::new(110, 38)
	$btnCancel.Font = [System.Drawing.Font]::new("Segoe UI", 10, [System.Drawing.FontStyle]::Regular)
	$btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
	$form.CancelButton = $btnCancel
	$form.Controls.Add($btnCancel)

	# Show dialog and handle input
	$result = $form.ShowDialog()
	if ($result -ne [System.Windows.Forms.DialogResult]::OK)
	{
		Write_Log "Lane backup scheduling cancelled by user." "yellow"
		return
	}
	# Local-copy location: the folder the user picked (default if unchanged)
	$chosenParent = $txtDir.Text.Trim()
	if (-not $chosenParent) { $chosenParent = $script:BackupRoot.TrimEnd('\') }
	Write_Log "Lane DB local-copy destination root: $chosenParent" "gray"
	$timeInput = $txtTime.Text
	$freqInput = [int]$numFreq.Value
	$keepInput = [int]$numKeep.Value
	$taskUser = $txtUser.Text.Trim()
	if (-not $taskUser) { $taskUser = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name }
	$taskPwd = $txtPwd.Text

	# Validate time
	if ($timeInput -notmatch '^\d{2}:\d{2}$')
	{
		[void][System.Windows.Forms.MessageBox]::Show("Time must be in HH:mm (24h) format.", "Input Error", 0, 16)
		Write_Log "Invalid time format entered." "red"
		return
	}
	$hours, $minutes = $timeInput.Split(":")
	if ([int]$hours -gt 23 -or [int]$minutes -gt 59)
	{
		[void][System.Windows.Forms.MessageBox]::Show("Invalid time entered.", "Input Error", 0, 16)
		Write_Log "Invalid time (out of range)." "red"
		return
	}

	# 4. Loop over each lane and schedule backup
	foreach ($lane in $goodLanes)
	{
		# Memory first, then the cache file, then the lane itself
		$laneInfo = Get_All_Lanes_Database_Info -LaneNumber $lane
		if (-not $laneInfo)
		{
			Write_Log "Could not get DB info for lane $lane. Skipping." "yellow"
			continue
		}
		$machine = $laneInfo['MachineName']
		$dbName = $laneInfo['DBName']

		# sqlcmd -S string for the lane's protocol (only TCP / Named Pipes lanes got this far)
		$sqlcmdS = if ($script:LaneProtocols[$lane] -eq 'Named Pipes') { $laneInfo['NamedPipes'] } else { $laneInfo['TcpServer'] }

		# Set backup and script directories (per-lane); local-copy root from the user's choice
		$scriptsDir = $script:ScriptsFolder
		$machineFolder = Join-Path $chosenParent $machine

		# ----> KEY: name backup script exactly as Run_${MachineName}_DB_Backup.ps1
		$scriptName = "Run_${machine}_DB_Backup.ps1"
		$backupScriptPath = Join-Path $scriptsDir $scriptName

		# Compose the backup script for this lane (matches server style)
		$backupScript = @"
# Auto-generated by Schedule_${machine}_DB_Backup (Alex_C.T)
`$ErrorActionPreference = 'Stop'
`$BackupRoot = `"$machineFolder`"
`$Database = `"$dbName`"
`$SqlcmdS = `"$sqlcmdS`"
`$RemoteBackupFolder = "\\$machine\C$\Tecnica_Systems\Alex_C.T\Backups\$machine"
`$MaxBackups = $keepInput
`$MaxRemoteBackups = 3

# Compose backup file name
`$timestamp = Get-Date -Format 'yyyyMMdd_HHmmss'
`$bakName = ("{0}_{1}.bak" -f `$Database, `$timestamp)
`$remoteBakFile = Join-Path `$RemoteBackupFolder `$bakName
`$localBakFile  = Join-Path `$BackupRoot `$bakName

# Ensure backup root exists (server)
if (-not (Test-Path `$BackupRoot)) { New-Item -Path `$BackupRoot -ItemType Directory -Force | Out-Null }
# Ensure backup root exists (remote/lane)
if (-not (Test-Path `$RemoteBackupFolder)) { New-Item -Path `$RemoteBackupFolder -ItemType Directory -Force | Out-Null }

# Keep only the newest N backups in a folder (called only after a good backup)
function Remove-OldBackups([string]`$Folder, [int]`$Keep) {
    @(Get-ChildItem -Path `$Folder -Filter "`$Database`_*.bak" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -Skip `$Keep) |
        ForEach-Object { Remove-Item -LiteralPath `$_.FullName -Force -ErrorAction SilentlyContinue }
}

# Run the backup on the lane via UNC SQL backup path (old backups are only rotated out AFTER a good one)
`$tsql = "BACKUP DATABASE [`$Database] TO DISK = N'`$remoteBakFile' WITH NOFORMAT, NOINIT, NAME = N'`$Database-FullBackup-`$timestamp', SKIP, NOREWIND, NOUNLOAD, STATS = 10"
`$sqlOut = & sqlcmd -S `"$SqlcmdS`" -Q `$tsql -b 2>&1
`$exitCode = `$LASTEXITCODE

if (`$exitCode -eq 0) {
    # Wait for backup to finish (file to appear and not be locked)
    `$waitSec = 0
    while (-not (Test-Path `$remoteBakFile) -and `$waitSec -lt 120) {
        Start-Sleep -Seconds 1; `$waitSec++
    }
    # Optionally, wait until file is not locked (ready for copy)
    `$ready = `$false; `$tries = 0
    while (-not `$ready -and `$tries -lt 60) {
        try {
            `$s = [System.IO.File]::Open(`$remoteBakFile, 'Open', 'Read', 'None')
            `$s.Close(); `$ready = `$true
        } catch { Start-Sleep -Milliseconds 500; `$tries++ }
    }

    if ((Test-Path `$remoteBakFile) -and `$ready) {
        try {
            Copy-Item -Path `$remoteBakFile -Destination `$localBakFile -Force
            "[`$(Get-Date)] Backup complete: `$localBakFile" | Out-File -FilePath (Join-Path `$BackupRoot `"backup.log`") -Append -Encoding utf8
            Remove-OldBackups `$BackupRoot `$MaxBackups
        } catch {
            "[`$(Get-Date)] Backup succeeded but copy failed: `$(`$_.Exception.Message)" | Out-File -FilePath (Join-Path `$BackupRoot `"backup.log`") -Append -Encoding utf8
        }
        Remove-OldBackups `$RemoteBackupFolder `$MaxRemoteBackups
    } else {
        "[`$(Get-Date)] Backup file not found or not ready for copy after backup." | Out-File -FilePath (Join-Path `$BackupRoot `"backup.log`") -Append -Encoding utf8
    }
} else {
    # Remove failed/partial file from lane backup folder if exists
    if (Test-Path `$remoteBakFile) { Remove-Item -Path `$remoteBakFile -Force }
    `$errMsg = (`$sqlOut | Out-String).Trim()
    if (-not `$errMsg) { `$errMsg = "(sqlcmd produced no output)" }
    "[`$(Get-Date)] Backup FAILED for [`$Database] on [`$SqlcmdS] (exit code: `$exitCode)" | Out-File -FilePath (Join-Path `$BackupRoot `"backup.log`") -Append -Encoding utf8
    "[`$(Get-Date)]   sqlcmd output: `$errMsg" | Out-File -FilePath (Join-Path `$BackupRoot `"backup.log`") -Append -Encoding utf8
}
"@

		# Write the script to scripts folder under machine folder
		$parentDir = Split-Path $backupScriptPath -Parent
		if (-not (Test-Path $parentDir)) { New-Item -Path $parentDir -ItemType Directory -Force | Out-Null }
		Set-Content -Path $backupScriptPath -Value $backupScript -Encoding UTF8

		# Build Task Scheduler arguments
		$hour = "{0:D2}" -f [int]$hours
		$min = "{0:D2}" -f [int]$minutes
		$startTime = "$hour`:$min"
		$taskName = "${machine}_DB_Backup_Schedule"
		# \" survives 5.1's native argument passing, so a path with spaces stays one -File argument
		$action = "powershell.exe -NoProfile -ExecutionPolicy Bypass -File \`"$backupScriptPath\`""
		$createArgs = @('/Create', '/TN', $taskName, '/TR', $action, '/SC', 'DAILY', '/ST', $startTime, '/RL', 'HIGHEST', '/F')
		if ($freqInput -gt 1) { $createArgs += @('/MO', [string]$freqInput) }

		# SYSTEM; a user with no password runs interactive only (/IT, must be logged in);
		# with a password the task also runs when nobody is logged in
		if ($taskUser -eq "SYSTEM") { $createArgs += @('/RU', 'SYSTEM'); $runAs = 'SYSTEM' }
		elseif ($taskPwd -eq "") { $createArgs += @('/RU', $taskUser, '/IT'); $runAs = "$taskUser (interactive)" }
		else { $createArgs += @('/RU', $taskUser, '/RP', $taskPwd); $runAs = "$taskUser (with password)" }

		Write_Log "Scheduling lane $lane ($machine) as $runAs`: $action" "cyan"
		$schtasksOut = & schtasks.exe @createArgs 2>&1
		if ($LASTEXITCODE -eq 0)
		{
			Write_Log "Backup task scheduled for $machine ($dbName) at $startTime every $freqInput day(s)." "green"
		}
		else
		{
			Write_Log "Failed to schedule backup for $machine`: $(($schtasksOut | Out-String).Trim())" "red"
		}
	}

	Write_Log "`r`n==================== Schedule_LaneDB_Backup Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Send_Restart_All_Programs
# ---------------------------------------------------------------------------------------------------
# Description:
#   Sends a restart-all-programs command to the selected lanes of a store: uses the cached
#   lane-to-machine map (Retrieve_Nodes when it is missing), picks lanes (or uses the passed
#   list) and sends "@exec(RESTART_ALL=PROGRAMS)." to each lane's SMSStart mailslot.
#
# Parameters:
#   - StoreNumber  [string]: store to process, 3 digits (required)
#   - LaneNumbers  [array]: lanes to target (default: selection form)
#   - Silent       [switch]: suppress Write_Log output
#
# Variables:
#   - $script:FunctionResults: LaneNumToMachineName (input via Retrieve_Nodes)
# ===================================================================================================

function Send_Restart_All_Programs
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[array]$LaneNumbers,
		[Parameter(Mandatory = $false)]
		[switch]$Silent
	)

	if (-not $Silent)
	{
		Write_Log "`r`n==================== Starting Send_Restart_All_Programs Function ====================`r`n" "blue"
	}

	# Lane map from the startup Retrieve_Nodes run; only re-run it when the map is missing
	$laneMap = $script:FunctionResults['LaneNumToMachineName']
	if (-not $laneMap -or $laneMap.Count -eq 0)
	{
		$nodes = Retrieve_Nodes -StoreNumber $StoreNumber
		if ($nodes) { $laneMap = $nodes.LaneNumToMachineName }
	}
	if (-not $laneMap)
	{
		Write_Log "Failed to retrieve node information for store $StoreNumber." "red"
		return
	}

	# Lane selection: use passed-in list or picker
	$lanes =
	if ($LaneNumbers -and $LaneNumbers.Count -gt 0)
	{
		$LaneNumbers | ForEach-Object {
			if ($_ -is [pscustomobject] -and $_.LaneNumber) { $_.LaneNumber }
			elseif ($_ -is [int]) { "{0:D3}" -f $_ }
			elseif ($_.Length -lt 3) { $_.PadLeft(3, '0') }
			else { $_ }
		}
	}
	else
	{
		$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
		if (-not $selection -or -not $selection.Lanes -or $selection.Lanes.Count -eq 0)
		{
			Write_Log "No lanes selected or selection cancelled. Exiting." "yellow"
			return
		}
		$selection.Lanes | ForEach-Object {
			if ($_ -is [pscustomobject] -and $_.LaneNumber) { $_.LaneNumber }
			elseif ($_ -is [int]) { "{0:D3}" -f $_ }
			elseif ($_.Length -lt 3) { $_.PadLeft(3, '0') }
			else { $_ }
		}
	}

	foreach ($lane in $lanes)
	{
		$machineName = $laneMap[$lane]
		if (-not $machineName)
		{
			Write_Log "No machine found for lane $lane. Skipping." "yellow"
			continue
		}

		$mailslotAddress = "\\$machineName\Mailslot\SMSStart_${StoreNumber}${lane}"
		$commandMessage = "@exec(RESTART_ALL=PROGRAMS)."

		try
		{
			$result = [MailslotSender]::SendMailslotCommand($mailslotAddress, $commandMessage)
			if ($result)
			{
				if (-not $Silent)
				{
					Write_Log "Command sent successfully to Machine $machineName (Store $StoreNumber, Lane $lane)." "green"
				}
			}
			else
			{
				if (-not $Silent)
				{
					Write_Log "Failed to send command to Machine $machineName (Store $StoreNumber, Lane $lane)." "red"
				}
			}
		}
		catch
		{
			if (-not $Silent)
			{
				Write_Log "Exception sending to $machineName (Lane $lane): $_" "red"
			}
		}
	}

	if (-not $Silent)
	{
		Write_Log "`r`n==================== Send_Restart_All_Programs Function Completed ====================" "blue"
	}
}

# ===================================================================================================
#                              FUNCTION: Send_SERVER_time_to_Lanes
# ---------------------------------------------------------------------------------------------------
# Description:
#   Time-sync wizard: shows the lane selection form, then hands the per-lane work to
#   Send_TIME_Sync_Lanes_Worker, running it as a background job via
#   Start_Background_Function_Job (inline fallback if the job cannot start).
#
# Parameters:
#   - StoreNumber  [string]: store to process, 3 digits (required)
#   - Schedule     [switch]: prompt for an interval (minutes) for repeated syncs
#
# Variables:
#   - $script:PrimaryStoremanRoot: storeman root (seeded to the worker job)
#   - $OfficePath: office path (seeded to the worker job)
#
# Notes:
#   - Per-lane work lives in Send_TIME_Sync_Lanes_Worker (v2.6.9 split for background jobs).
# ===================================================================================================

function Send_SERVER_time_to_Lanes
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[switch]$Schedule # Optional: enables scheduling mode (prompt for interval)
	)

	Write_Log "`r`n==================== Starting Time Sync ====================`r`n" "blue"

	# 1. Unified Lane Picker
	$laneSelection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
	if (-not $laneSelection -or -not $laneSelection.Lanes -or $laneSelection.Lanes.Count -eq 0)
	{
		Write_Log "No lanes selected for time sync." "yellow"
		Write_Log "`r`n==================== Time Sync Aborted ====================`r`n" "blue"
		return
	}
	$selectedLanes = $laneSelection.Lanes

	# 2. Scheduling Mode Prompt (Optional)
	$isScheduling = $false
	$intervalMinutes = 0
	if ($Schedule)
	{
		Add-Type -AssemblyName System.Windows.Forms
		$formInterval = New-Object System.Windows.Forms.Form
		$formInterval.Text = "Set Sync Interval"
		$formInterval.Size = New-Object System.Drawing.Size(300, 150)
		$formInterval.StartPosition = "CenterScreen"
		$label = New-Object System.Windows.Forms.Label
		$label.Text = "Enter interval in minutes:"
		$label.Location = New-Object System.Drawing.Point(20, 20)
		$formInterval.Controls.Add($label)
		$textBox = New-Object System.Windows.Forms.TextBox
		$textBox.Location = New-Object System.Drawing.Point(20, 50)
		$textBox.Size = New-Object System.Drawing.Size(240, 20)
		$formInterval.Controls.Add($textBox)
		$okButton = New-Object System.Windows.Forms.Button
		$okButton.Text = "OK"
		$okButton.Location = New-Object System.Drawing.Point(100, 80)
		$okButton.DialogResult = [System.Windows.Forms.DialogResult]::OK
		$formInterval.Controls.Add($okButton)
		$result = $formInterval.ShowDialog()
		if ($result -ne [System.Windows.Forms.DialogResult]::OK)
		{
			Write_Log "Scheduling canceled." "yellow"
			return
		}
		if (-not [int]::TryParse($textBox.Text, [ref]$intervalMinutes) -or $intervalMinutes -le 0)
		{
			Write_Log "Invalid interval. Must be a positive integer." "red"
			return
		}
		$isScheduling = $true
	}

	# 3. (v2.6.9) the per-lane work runs as a BACKGROUND job so the
	#    UI thread never blocks. Per-lane details go to the file log as
	#    the job progresses; the shared job reaper logs the one-line
	#    completion notice to the log window.
	$bgJob = Start_Background_Function_Job `
		-FunctionName 'Send_TIME_Sync_Lanes_Worker' `
		-Label ('Time sync to ' + @($selectedLanes).Count + ' lane(s)') `
		-CallArgs @{ StoreNumber = $StoreNumber; SelectedLanes = $selectedLanes; IsScheduling = $isScheduling; IntervalMinutes = $intervalMinutes } `
		-SeedVars @{ OfficePath = $OfficePath; PrimaryStoremanRoot = $script:PrimaryStoremanRoot } `
		-DependentBodies @{ Ensure_MailslotSender_Type = (Get-Command Ensure_MailslotSender_Type -CommandType Function).ScriptBlock.ToString() } `
		-NotifyOnComplete
	if ($bgJob)
	{
		Write_Log ("Time sync to {0} lane(s) is running in the background - per-lane details go to the file log." -f @($selectedLanes).Count) "green"
	}
	else
	{
		Write_Log "Could not start the background time-sync job - running inline." "yellow"
		Send_TIME_Sync_Lanes_Worker -StoreNumber $StoreNumber -SelectedLanes $selectedLanes -IsScheduling:$isScheduling -IntervalMinutes $intervalMinutes
	}
}

# ===================================================================================================
#                              FUNCTION: Send_SMS_Key_to_Lanes
# ---------------------------------------------------------------------------------------------------
# Description:
#   Syncs the server SMS key to the lane databases. "Run now" uses the in-memory lane
#   protocols and tries Windows auth first, then SQL auth (Tecnica), then an SQI file
#   fallback; the scheduled task variant reads Protocol_Results.txt at runtime and uses
#   SQL auth for lane DB updates when the protocol is not File.
#
# Parameters:
#   - StoreNumber           [string]: store to process (required)
#   - LaneNumbers           [string[]]: lanes to target (default: all)
#   - NonInteractive        [switch]: run without prompts
#   - SqlTimeoutSeconds     [int]: SQL query timeout in seconds (default 30)
#   - ConnectTimeoutSeconds [int]: SQL connect timeout in seconds (default 1)
#
# Variables:
#   - $script:LaneProtocols: per-lane protocol cache used by "Run now"
#   - $script:FunctionResults: lane map and SQL module (input)
#
# Writes:
#   - lane databases (key sync) and a scheduled task for the recurring sync
# ===================================================================================================

function Send_SMS_Key_to_Lanes
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[Parameter(Mandatory = $false)]
		[string[]]$LaneNumbers = $null,
		[Parameter(Mandatory = $false)]
		[switch]$NonInteractive,
		[Parameter(Mandatory = $false)]
		[int]$SqlTimeoutSeconds = 30,
		[Parameter(Mandatory = $false)]
		[int]$ConnectTimeoutSeconds = 1
	)

	Write_Log "`r`n==================== Starting Send_SMS_Key_to_Lanes ====================`r`n" "blue"

	# Normalize store number (3 digits)
	$StoreNumber = "$StoreNumber".PadLeft(3, '0')

	# Ensure FunctionResults exists
	if (-not $script:FunctionResults) { $script:FunctionResults = @{ } }

	# SQL AUTH creds (used for scheduled; and as fallback for Run Now if WinAuth fails).
	# Was "TB$upp0rT" in double quotes: $upp0rT expanded to nothing and the password sent was "TB".
	$SqlAuthUser = $script:BackupSqlUser
	$SqlAuthPass = $script:BackupSqlPass

	# Everything here goes through System.Data.SqlClient, so no SQL module is needed

	# Ensure cached lane map exists (fallback only if missing)
	if (-not $script:FunctionResults['LaneNumToMachineName'])
	{
		Write_Log "LaneNumToMachineName missing; calling Retrieve_Nodes as fallback." "yellow"
		$null = Retrieve_Nodes -StoreNumber $StoreNumber
	}
	$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
	if (-not $LaneNumToMachineName)
	{
		Write_Log "LaneNumToMachineName still missing; cannot continue." "red"
		Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
		return
	}

	# OfficePath required for SQI fallback
	if (-not $OfficePath -or -not (Test-Path $OfficePath))
	{
		$guessOffice = $script:StoremanOfficeRoots | Where-Object { $_ -and (Test-Path -LiteralPath $_) } | Select-Object -First 1
		if (-not $guessOffice) { $guessOffice = $script:PrimaryStoremanOfficePath }
		if (Test-Path $guessOffice) { $OfficePath = $guessOffice }
	}
	if (-not $OfficePath -or -not (Test-Path $OfficePath))
	{
		Write_Log "OfficePath missing/invalid; SQI fallback would fail. OfficePath='$OfficePath'." "red"
		Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
		return
	}

	# IMPORTANT:
	# - RUN NOW uses ONLY this variable. DEFAULT = File unless explicitly TCP/Named Pipes.
	if (-not $script:LaneProtocols) { $script:LaneProtocols = @{ } }

	# Protocol results file path (Scheduled Task will read this at runtime)
	$protoFile = $script:ProtocolResultsFile

	# MODE selection (Interactive only): Run Now vs Schedule Only
	$mode = "run"
	if (-not $NonInteractive)
	{
		try { Add-Type -AssemblyName System.Windows.Forms | Out-Null }
		catch { }

		$script:__modePick = $null
		$formMode = New-Object System.Windows.Forms.Form
		$formMode.Text = "Server Key Sync"
		$formMode.Size = New-Object System.Drawing.Size(540, 230)
		$formMode.StartPosition = "CenterScreen"
		$formMode.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
		$formMode.MaximizeBox = $false
		$formMode.MinimizeBox = $false

		$lblMode = New-Object System.Windows.Forms.Label
		$lblMode.Text = "Choose what you want to do:"
		$lblMode.AutoSize = $true
		$lblMode.Location = New-Object System.Drawing.Point(18, 18)
		$formMode.Controls.Add($lblMode)

		$btnRunNow = New-Object System.Windows.Forms.Button
		$btnRunNow.Text = "Run Now"
		$btnRunNow.Size = New-Object System.Drawing.Size(150, 45)
		$btnRunNow.Location = New-Object System.Drawing.Point(25, 65)
		$btnRunNow.Add_Click({ $script:__modePick = "run"; $formMode.DialogResult = [System.Windows.Forms.DialogResult]::OK; $formMode.Close() })
		$formMode.Controls.Add($btnRunNow)

		$btnScheduleOnly = New-Object System.Windows.Forms.Button
		$btnScheduleOnly.Text = "Schedule Task Only"
		$btnScheduleOnly.Size = New-Object System.Drawing.Size(190, 45)
		$btnScheduleOnly.Location = New-Object System.Drawing.Point(190, 65)
		$btnScheduleOnly.Add_Click({ $script:__modePick = "schedule"; $formMode.DialogResult = [System.Windows.Forms.DialogResult]::OK; $formMode.Close() })
		$formMode.Controls.Add($btnScheduleOnly)

		$btnCancel = New-Object System.Windows.Forms.Button
		$btnCancel.Text = "Cancel"
		$btnCancel.Size = New-Object System.Drawing.Size(110, 45)
		$btnCancel.Location = New-Object System.Drawing.Point(395, 65)
		$btnCancel.Add_Click({ $script:__modePick = "cancel"; $formMode.DialogResult = [System.Windows.Forms.DialogResult]::Cancel; $formMode.Close() })
		$formMode.Controls.Add($btnCancel)

		[void]$formMode.ShowDialog()
		$mode = $script:__modePick
		Remove-Variable -Name __modePick -Scope Script -ErrorAction SilentlyContinue

		if ($mode -eq "cancel" -or [string]::IsNullOrWhiteSpace($mode))
		{
			Write_Log "User cancelled Server Key Sync." "yellow"
			Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
			return
		}
	}

	# Lane selection (interactive) or normalize lanes (noninteractive)
	if (-not $NonInteractive)
	{
		Write_Log "Opening lane selection..." "yellow"
		$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
		if (-not $selection -or -not $selection.Lanes -or $selection.Lanes.Count -eq 0)
		{
			Write_Log "Lane selection cancelled or returned no lanes." "yellow"
			Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
			return
		}

		$tmp = @()
		foreach ($ln in $selection.Lanes)
		{
			$raw = $null
			if ($ln -is [pscustomobject] -and $ln.LaneNumber) { $raw = "$($ln.LaneNumber)" }
			else { $raw = "$ln" }

			$n = ($raw -replace '[^\d]', '')
			if (-not [string]::IsNullOrWhiteSpace($n)) { $tmp += $n.PadLeft(3, '0') }
		}
		$LaneNumbers = @($tmp | Where-Object { $_ } | Select-Object -Unique)
	}
	else
	{
		if (-not $LaneNumbers -or $LaneNumbers.Count -eq 0)
		{
			Write_Log "NonInteractive run requires -LaneNumbers." "red"
			Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
			return
		}
		$tmp = @()
		foreach ($ln in $LaneNumbers)
		{
			$n = ("$ln" -replace '[^\d]', '')
			if (-not [string]::IsNullOrWhiteSpace($n)) { $tmp += $n.PadLeft(3, '0') }
		}
		$LaneNumbers = @($tmp | Where-Object { $_ } | Select-Object -Unique)
	}

	Write_Log ("Selected lanes: " + ($LaneNumbers -join ", ")) "cyan"

	# Decide whether to deploy now
	$doDeployNow = $true
	if (-not $NonInteractive -and $mode -eq "schedule") { $doDeployNow = $false }

	# Results containers
	$UpdatedViaSql = New-Object System.Collections.Generic.List[string]
	$UpdatedViaFile = New-Object System.Collections.Generic.List[string]
	$FailedLanes = New-Object System.Collections.Generic.List[string]

	# =================================================================================================
	# DEPLOY NOW
	#   - Uses ONLY $script:LaneProtocols (already populated)
	#   - DEFAULT = File unless explicitly TCP/Named Pipes
	#   - Tries WinAuth first, then SQL Auth, then SQI
	# =================================================================================================
	if ($doDeployNow)
	{
		try { Add-Type -AssemblyName System.Data 2>$null }
		catch { }

		# LOCAL key read
		$localConnStr = $script:FunctionResults['ConnectionString']
		if ([string]::IsNullOrWhiteSpace($localConnStr) -or $localConnStr -eq "N/A")
		{
			Write_Log "Local DB ConnectionString missing (FunctionResults['ConnectionString'])." "red"
			Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
			return
		}

		# Enforce connect timeout on LOCAL conn string
		$localConnStrEff = $localConnStr
		if ($localConnStrEff -notmatch '(?i)\bConnect\s*Timeout\s*=')
		{
			if ($localConnStrEff.Trim().EndsWith(';')) { $localConnStrEff += "Connect Timeout=$ConnectTimeoutSeconds;" }
			else { $localConnStrEff += ";Connect Timeout=$ConnectTimeoutSeconds;" }
		}
		else
		{
			$localConnStrEff = [regex]::Replace($localConnStrEff, '(?i)\bConnect\s*Timeout\s*=\s*\d+\s*', "Connect Timeout=$ConnectTimeoutSeconds")
		}

		Write_Log "Reading SYS_TAB.F1243 from LOCAL DB..." "yellow"

		$rawValues = @()
		try
		{
			$vals = New-Object System.Collections.Generic.List[string]
			$cn = New-Object System.Data.SqlClient.SqlConnection $localConnStrEff
			try
			{
				$cn.Open()
				$cmd = $cn.CreateCommand()
				$cmd.CommandText = "SELECT F1243 FROM SYS_TAB;"
				$cmd.CommandTimeout = $SqlTimeoutSeconds
				$rdr = $cmd.ExecuteReader()
				try
				{
					while ($rdr.Read())
					{
						if (-not $rdr.IsDBNull(0)) { $vals.Add([string]$rdr.GetValue(0)) | Out-Null }
					}
				}
				finally
				{
					try { $rdr.Close() }
					catch { }
					try { $rdr.Dispose() }
					catch { }
				}
			}
			finally
			{
				try { $cn.Close() }
				catch { }
				try { $cn.Dispose() }
				catch { }
			}
			$rawValues = @($vals)
		}
		catch { $rawValues = @() }

		$serverKey = $null
		$bestLen = -1
		foreach ($v in $rawValues)
		{
			if ($v -eq $null) { continue }
			$t = ([string]$v).Trim()
			$stripped = [regex]::Replace($t, '[\s\u00A0]+', '')
			if (-not [string]::IsNullOrWhiteSpace($t) -and -not [string]::IsNullOrWhiteSpace($stripped))
			{
				if ($t.Length -gt $bestLen) { $bestLen = $t.Length; $serverKey = $t }
			}
		}

		if ([string]::IsNullOrWhiteSpace($serverKey))
		{
			Write_Log "Server key (SYS_TAB.F1243) came back empty/null from LOCAL DB. Aborting." "red"
			Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
			return
		}

		Write_Log ("Server key retrieved (length {0})." -f $serverKey.Length) "green"

		$safeServerKey = $serverKey.Replace("'", "''")
		$updateSql = "UPDATE SYS_TAB SET F1243 = '$safeServerKey'"

		# SQI fallback file (ANSI 1252, no BOM)
		$SqiFileName = "UPDATE_SMS_KEY.SQI" # same name as the scheduled task, so a lane never queues two
		$SqiContent = "@dbEXEC($updateSql)`r`n"
		$ansiEncoding = [System.Text.Encoding]::GetEncoding(1252)
		$TempSqiPath = Join-Path ([System.IO.Path]::GetTempPath()) $SqiFileName

		try
		{
			[System.IO.File]::WriteAllText($TempSqiPath, $SqiContent, $ansiEncoding)
			try { attrib -a -r "$TempSqiPath" 2>$null | Out-Null }
			catch { }
			try { Set-ItemProperty -Path $TempSqiPath -Name Attributes -Value ([System.IO.FileAttributes]::Normal) -ErrorAction SilentlyContinue }
			catch { }
		}
		catch
		{
			Write_Log "Failed to create temp SQI '$TempSqiPath'. Error: $_" "red"
			Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
			return
		}

		foreach ($LaneNumber in $LaneNumbers)
		{
			Write_Log "`r`n--- Lane $LaneNumber ---" "magenta"

			$laneInfo = $null
			try { $laneInfo = Get_All_Lanes_Database_Info -LaneNumber $LaneNumber }
			catch { $laneInfo = $null }
			if (-not $laneInfo)
			{
				Write_Log "Could not retrieve cached DB info for lane $LaneNumber. Skipping." "red"
				$FailedLanes.Add($LaneNumber) | Out-Null
				continue
			}

			# Normalize PSCustomObject -> hashtable (so ['TcpConnStr'] works)
			if ($laneInfo -isnot [hashtable])
			{
				$h = @{ }
				foreach ($p in $laneInfo.PSObject.Properties) { $h[$p.Name] = $p.Value }
				$laneInfo = $h
			}

			$tcpConnStr = $laneInfo['TcpConnStr']
			$namedPipesConnStr = $laneInfo['NamedPipesConnStr']

			# RUN NOW: protocol comes ONLY from $script:LaneProtocols; DEFAULT = File
			$machineName = $LaneNumToMachineName[$LaneNumber]
			$protocolPref = $null
			if ($script:LaneProtocols.ContainsKey($LaneNumber)) { $protocolPref = [string]$script:LaneProtocols[$LaneNumber] }
			elseif ($machineName -and $script:LaneProtocols.ContainsKey($machineName)) { $protocolPref = [string]$script:LaneProtocols[$machineName] }
			elseif ($machineName -and $script:LaneProtocols.ContainsKey($machineName.ToLower())) { $protocolPref = [string]$script:LaneProtocols[$machineName.ToLower()] }

			$protocolPrefNorm = "File"
			if (-not [string]::IsNullOrWhiteSpace($protocolPref))
			{
				$t = $protocolPref.Trim()
				if ($t -match '(?i)^tcp$') { $protocolPrefNorm = "TCP" }
				elseif ($t -match '(?i)pipe') { $protocolPrefNorm = "Named Pipes" }
				elseif ($t -match '(?i)^offline$') { $protocolPrefNorm = "Offline" }
				else { $protocolPrefNorm = "File" }
			}

			if ($protocolPrefNorm -eq "Offline")
			{
				Write_Log "Lane $LaneNumber ($machineName) is offline. Skipping." "yellow"
				$FailedLanes.Add($LaneNumber) | Out-Null
				continue
			}

			$sqlWorked = $false

			# SQL attempts ONLY when protocol explicitly says TCP/Named Pipes
			if ($protocolPrefNorm -ne "File")
			{
				$tryOrder = @("TCP", "Named Pipes")
				if ($protocolPrefNorm -eq "Named Pipes") { $tryOrder = @("Named Pipes", "TCP") }

				foreach ($proto in $tryOrder)
				{
					$connToUse = if ($proto -eq "Named Pipes") { $namedPipesConnStr }
					else { $tcpConnStr }
					if ([string]::IsNullOrWhiteSpace($connToUse)) { continue }

					# -----------------------
					# Attempt 1: Windows Auth
					# -----------------------
					$connWin = $connToUse
					$connWin = [regex]::Replace($connWin, '(?i)\bUser\s*ID\s*=\s*[^;]*;?', '')
					$connWin = [regex]::Replace($connWin, '(?i)\bUID\s*=\s*[^;]*;?', '')
					$connWin = [regex]::Replace($connWin, '(?i)\bPassword\s*=\s*[^;]*;?', '')
					$connWin = [regex]::Replace($connWin, '(?i)\bPWD\s*=\s*[^;]*;?', '')
					$connWin = [regex]::Replace($connWin, '(?i)\bTrusted_Connection\s*=\s*Yes\s*;?', '')
					$connWin = [regex]::Replace($connWin, '(?i)\bIntegrated\s+Security\s*=\s*False\s*;?', '')

					if ($connWin -notmatch '(?i)\bIntegrated\s+Security\s*=')
					{
						if ($connWin.Trim().EndsWith(';')) { $connWin += "Integrated Security=True;" }
						else { $connWin += ";Integrated Security=True;" }
					}
					else
					{
						$connWin = [regex]::Replace($connWin, '(?i)\bIntegrated\s+Security\s*=\s*[^;]*', 'Integrated Security=True')
					}

					if ($connWin -notmatch '(?i)\bConnect\s*Timeout\s*=')
					{
						if ($connWin.Trim().EndsWith(';')) { $connWin += "Connect Timeout=$ConnectTimeoutSeconds;" }
						else { $connWin += ";Connect Timeout=$ConnectTimeoutSeconds;" }
					}
					else
					{
						$connWin = [regex]::Replace($connWin, '(?i)\bConnect\s*Timeout\s*=\s*\d+\s*', "Connect Timeout=$ConnectTimeoutSeconds")
					}

					try
					{
						$cn2 = New-Object System.Data.SqlClient.SqlConnection $connWin
						try
						{
							$cn2.Open()
							$cmd2 = $cn2.CreateCommand()
							$cmd2.CommandText = $updateSql
							$cmd2.CommandTimeout = $SqlTimeoutSeconds
							[void]$cmd2.ExecuteNonQuery()
							$sqlWorked = $true
							Write_Log "Updated via SQL ($proto) on lane $LaneNumber (Windows Auth)." "green"
							$UpdatedViaSql.Add($LaneNumber) | Out-Null
							break
						}
						finally
						{
							try { $cn2.Close() }
							catch { }
							try { $cn2.Dispose() }
							catch { }
						}
					}
					catch
					{
						$sqlWorked = $false
					}

					if ($sqlWorked) { break }

					# -----------------------
					# Attempt 2: SQL Auth
					# -----------------------
					$connSql = $connToUse
					$connSql = [regex]::Replace($connSql, '(?i)\bIntegrated\s+Security\s*=\s*True\s*;?', '')
					$connSql = [regex]::Replace($connSql, '(?i)\bTrusted_Connection\s*=\s*Yes\s*;?', '')

					if ($connSql -notmatch '(?i)\bUser\s*ID\s*=')
					{
						if ($connSql.Trim().EndsWith(';')) { $connSql += "User ID=$SqlAuthUser;" }
						else { $connSql += ";User ID=$SqlAuthUser;" }
					}
					if ($connSql -notmatch '(?i)\bPassword\s*=')
					{
						if ($connSql.Trim().EndsWith(';')) { $connSql += "Password=$SqlAuthPass;" }
						else { $connSql += ";Password=$SqlAuthPass;" }
					}

					if ($connSql -notmatch '(?i)\bConnect\s*Timeout\s*=')
					{
						if ($connSql.Trim().EndsWith(';')) { $connSql += "Connect Timeout=$ConnectTimeoutSeconds;" }
						else { $connSql += ";Connect Timeout=$ConnectTimeoutSeconds;" }
					}
					else
					{
						$connSql = [regex]::Replace($connSql, '(?i)\bConnect\s*Timeout\s*=\s*\d+\s*', "Connect Timeout=$ConnectTimeoutSeconds")
					}

					try
					{
						$cn3 = New-Object System.Data.SqlClient.SqlConnection $connSql
						try
						{
							$cn3.Open()
							$cmd3 = $cn3.CreateCommand()
							$cmd3.CommandText = $updateSql
							$cmd3.CommandTimeout = $SqlTimeoutSeconds
							[void]$cmd3.ExecuteNonQuery()
							$sqlWorked = $true
							Write_Log "Updated via SQL ($proto) on lane $LaneNumber (SQL Auth)." "green"
							$UpdatedViaSql.Add($LaneNumber) | Out-Null
							break
						}
						finally
						{
							try { $cn3.Close() }
							catch { }
							try { $cn3.Dispose() }
							catch { }
						}
					}
					catch
					{
						$sqlWorked = $false
					}

					if ($sqlWorked) { break }
				}
			}

			# SQI fallback (protocol File OR SQL failed)
			if (-not $sqlWorked)
			{
				$LaneXFDir = Join-Path $OfficePath ("XF{0}{1}" -f $StoreNumber, $LaneNumber)
				$DestSqiPath = Join-Path $LaneXFDir $SqiFileName

				if (-not (Test-Path $LaneXFDir))
				{
					Write_Log "Lane XF folder not found: $LaneXFDir" "red"
					$FailedLanes.Add($LaneNumber) | Out-Null
					continue
				}

				try
				{
					Copy-Item -Path $TempSqiPath -Destination $DestSqiPath -Force
					try { attrib -a -r "$DestSqiPath" 2>$null | Out-Null }
					catch { }
					try { Set-ItemProperty -Path $DestSqiPath -Name Attributes -Value ([System.IO.FileAttributes]::Normal) -ErrorAction SilentlyContinue }
					catch { }

					$UpdatedViaFile.Add($LaneNumber) | Out-Null
					Write_Log "Copied SQI to $DestSqiPath (archive cleared)" "green"
				}
				catch
				{
					Write_Log "Failed to copy SQI for lane $LaneNumber. Error: $_" "red"
					$FailedLanes.Add($LaneNumber) | Out-Null
				}
			}
		}

		if ($UpdatedViaSql.Count -gt 0) { Write_Log ("Updated via SQL: " + ($UpdatedViaSql -join ", ")) "green" }
		if ($UpdatedViaFile.Count -gt 0) { Write_Log ("Updated via SQI: " + ($UpdatedViaFile -join ", ")) "green" }
		if ($FailedLanes.Count -gt 0) { Write_Log ("Failed lanes: " + ($FailedLanes -join ", ")) "red" }
	}

	# Restart prompt (interactive Run Now only)
	if (-not $NonInteractive -and $mode -eq "run" -and $doDeployNow)
	{
		$successful = @(@($UpdatedViaSql) + @($UpdatedViaFile) | Where-Object { $_ } | Select-Object -Unique)
		if ($successful.Count -gt 0)
		{
			try { Add-Type -AssemblyName System.Windows.Forms | Out-Null }
			catch { }
			$ansRestart = [System.Windows.Forms.MessageBox]::Show(
				"Server key deployed successfully to: " + ($successful -join ", ") + "`r`n`r`nRestart ALL programs on these lanes now?",
				"Restart Programs?",
				[System.Windows.Forms.MessageBoxButtons]::YesNo,
				[System.Windows.Forms.MessageBoxIcon]::Question
			)

			if ($ansRestart -eq [System.Windows.Forms.DialogResult]::Yes)
			{
				foreach ($ln in $successful)
				{
					$machineName = $LaneNumToMachineName[$ln]
					if ([string]::IsNullOrWhiteSpace($machineName))
					{
						Write_Log "Could not resolve machine name for lane $ln (restart skipped)." "yellow"
						continue
					}

					try
					{
						$mailslotAddress = "\\$machineName\mailslot\SMSStart_${StoreNumber}${ln}"
						$sent = [MailslotSender]::SendMailslotCommand($mailslotAddress, "@exec(RESTART_ALL=PROGRAMS).")
						if ($sent) { Write_Log "Restart sent to $machineName (lane $ln)." "green" }
						else { Write_Log "Restart FAILED to $machineName (lane $ln)." "red" }
					}
					catch
					{
						Write_Log "Restart attempt failed for lane $ln. Error: $_" "red"
					}
				}
			}
			else
			{
				Write_Log "User chose NOT to restart programs after deploy." "yellow"
			}
		}
	}

	# =================================================================================================
	# SCHEDULE (interactive only) -> ONE self-sufficient PS1
	#   - Uses SQL AUTH for lane DB updates when protocol != File
	#   - Reads Protocol_Results.txt at runtime (DEFAULT File unless explicitly TCP/Named Pipes)
	# =================================================================================================
	if (-not $NonInteractive)
	{
		$doSchedule = $false
		if ($mode -eq "schedule") { $doSchedule = $true }
		else
		{
			try { Add-Type -AssemblyName System.Windows.Forms | Out-Null }
			catch { }
			$ansSchedule = [System.Windows.Forms.MessageBox]::Show(
				"Do you want to create/update a Scheduled Task for the selected lanes?",
				"Create Scheduled Task?",
				[System.Windows.Forms.MessageBoxButtons]::YesNo,
				[System.Windows.Forms.MessageBoxIcon]::Question
			)
			if ($ansSchedule -eq [System.Windows.Forms.DialogResult]::Yes) { $doSchedule = $true }
		}

		if ($doSchedule)
		{
			try { Add-Type -AssemblyName System.Windows.Forms | Out-Null }
			catch { }

			$formFreq = New-Object System.Windows.Forms.Form
			$formFreq.Text = "Server Key Sync Frequency"
			$formFreq.Width = 520
			$formFreq.Height = 240
			$formFreq.StartPosition = "CenterScreen"

			$lbl = New-Object System.Windows.Forms.Label
			$lbl.AutoSize = $true
			$lbl.Location = New-Object System.Drawing.Point(15, 20)
			$lbl.Text = "Run every how many minutes? (1 - 1439)"
			$formFreq.Controls.Add($lbl)

			$tb = New-Object System.Windows.Forms.TextBox
			$tb.Location = New-Object System.Drawing.Point(20, 50)
			$tb.Width = 100
			$tb.Text = "60"
			$formFreq.Controls.Add($tb)

			$lbl2 = New-Object System.Windows.Forms.Label
			$lbl2.AutoSize = $true
			$lbl2.Location = New-Object System.Drawing.Point(15, 95)
			$lbl2.Text = "Selected lanes: " + ($LaneNumbers -join ", ")
			$formFreq.Controls.Add($lbl2)

			$okBtn = New-Object System.Windows.Forms.Button
			$okBtn.Text = "OK"
			$okBtn.Location = New-Object System.Drawing.Point(300, 160)
			$okBtn.Add_Click({ $formFreq.DialogResult = [System.Windows.Forms.DialogResult]::OK })
			$formFreq.Controls.Add($okBtn)

			$cancelBtn = New-Object System.Windows.Forms.Button
			$cancelBtn.Text = "Cancel"
			$cancelBtn.Location = New-Object System.Drawing.Point(380, 160)
			$cancelBtn.Add_Click({ $formFreq.DialogResult = [System.Windows.Forms.DialogResult]::Cancel })
			$formFreq.Controls.Add($cancelBtn)

			$formFreq.AcceptButton = $okBtn
			$formFreq.CancelButton = $cancelBtn

			if ($formFreq.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK)
			{
				Write_Log "Scheduled Task setup cancelled by user." "yellow"
				Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
				return
			}

			[int]$freqMinutes = 0
			if (-not [int]::TryParse($tb.Text, [ref]$freqMinutes) -or $freqMinutes -lt 1 -or $freqMinutes -gt 1439)
			{
				Write_Log "Invalid frequency entered. Using 60 minutes." "yellow"
				$freqMinutes = 60
			}

			# Required cached data for self-sufficient script
			$localConnStr = $script:FunctionResults['ConnectionString']
			if ([string]::IsNullOrWhiteSpace($localConnStr) -or $localConnStr -eq "N/A")
			{
				Write_Log "Cannot schedule because local ConnectionString is missing in FunctionResults['ConnectionString']." "red"
				Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
				return
			}

			$laneConnMap = @{ }
			foreach ($ln in $LaneNumbers)
			{
				$li = $null
				try { $li = Get_All_Lanes_Database_Info -LaneNumber $ln }
				catch { $li = $null }
				if ($li)
				{
					if ($li -isnot [hashtable])
					{
						$h2 = @{ }
						foreach ($p in $li.PSObject.Properties) { $h2[$p.Name] = $p.Value }
						$li = $h2
					}

					$laneConnMap[$ln] = @{
						TcpConnStr	      = $li['TcpConnStr']
						NamedPipesConnStr = $li['NamedPipesConnStr']
					}
				}
			}

			$taskScriptPath = Join-Path $script:ScriptsFolder ("Send_SMS_Key_Task_Store{0}.ps1" -f $StoreNumber)
			$latestLogPath = Join-Path $script:ScriptsLog    ("Send_SMS_Key_LATEST_Store{0}.txt" -f $StoreNumber)

			$enc = [System.Text.Encoding]::UTF8
			$localConnB64 = [Convert]::ToBase64String($enc.GetBytes($localConnStr))
			$laneConnB64 = [Convert]::ToBase64String($enc.GetBytes(($laneConnMap | ConvertTo-Json -Depth 6)))

			$laneListLiteral = ($LaneNumbers | ForEach-Object { "'$_'" }) -join ", "

			$sb = New-Object System.Text.StringBuilder
			[void]$sb.AppendLine("# AUTO-GENERATED Send_SMS_Key task (self-sufficient, one file)")
			[void]$sb.AppendLine("`$ErrorActionPreference = 'Stop'")
			[void]$sb.AppendLine("try { Add-Type -AssemblyName System.Data 2>`$null } catch { }")
			[void]$sb.AppendLine("`$SqlUser = '" + $SqlAuthUser.Replace("'", "''") + "'")
			[void]$sb.AppendLine("`$SqlPass = '" + $SqlAuthPass.Replace("'", "''") + "'")
			[void]$sb.AppendLine("`$StoreNumber = '$StoreNumber'")
			[void]$sb.AppendLine("`$OfficePath  = '$OfficePath'")
			[void]$sb.AppendLine("`$SqlTimeoutSeconds = $SqlTimeoutSeconds")
			[void]$sb.AppendLine("`$ConnectTimeoutSeconds = $ConnectTimeoutSeconds")
			[void]$sb.AppendLine("`$LatestLogPath = '$latestLogPath'")
			[void]$sb.AppendLine("`$ProtocolFile = '$protoFile'")
			[void]$sb.AppendLine("`$enc = [System.Text.Encoding]::UTF8")
			[void]$sb.AppendLine("`$LocalConnStr = `$enc.GetString([Convert]::FromBase64String('$localConnB64'))")
			[void]$sb.AppendLine("`$LaneConnMap  = ConvertFrom-Json (`$enc.GetString([Convert]::FromBase64String('$laneConnB64')))")
			[void]$sb.AppendLine("`$LaneNumbers = @($laneListLiteral)")
			[void]$sb.AppendLine("`$UpdatedViaSql  = New-Object System.Collections.Generic.List[string]")
			[void]$sb.AppendLine("`$UpdatedViaFile = New-Object System.Collections.Generic.List[string]")
			[void]$sb.AppendLine("`$FailedLanes    = New-Object System.Collections.Generic.List[string]")
			[void]$sb.AppendLine("")
			[void]$sb.AppendLine("# Load protocol map from txt (DEFAULT = File unless explicitly TCP/Named Pipes)")
			[void]$sb.AppendLine("`$ProtoMap = @{}")
			[void]$sb.AppendLine("if (Test-Path `$ProtocolFile) {")
			[void]$sb.AppendLine("  try {")
			[void]$sb.AppendLine("    foreach (`$line in (Get-Content -LiteralPath `$ProtocolFile -ErrorAction SilentlyContinue)) {")
			[void]$sb.AppendLine("      if (`$line -match '^\s*([^,]+),\s*([^,]+)\s*$') {")
			[void]$sb.AppendLine("        `$laneRaw = `$matches[1].Trim()")
			[void]$sb.AppendLine("        `$protoRaw = `$matches[2].Trim()")
			[void]$sb.AppendLine("        `$num = (`$laneRaw -replace '[^\d]','').PadLeft(3,'0')")
			[void]$sb.AppendLine("        if (-not [string]::IsNullOrWhiteSpace(`$num)) { `$ProtoMap[`$num] = `$protoRaw }")
			[void]$sb.AppendLine("      }")
			[void]$sb.AppendLine("    }")
			[void]$sb.AppendLine("  } catch { }")
			[void]$sb.AppendLine("}")
			[void]$sb.AppendLine("")
			[void]$sb.AppendLine("# Enforce connect timeout on LOCAL conn string")
			[void]$sb.AppendLine("`$localEff = `$LocalConnStr")
			[void]$sb.AppendLine("if (`$localEff -notmatch '(?i)\bConnect\s*Timeout\s*=') { if (`$localEff.Trim().EndsWith(';')) { `$localEff += ""Connect Timeout=`$ConnectTimeoutSeconds;"" } else { `$localEff += "";Connect Timeout=`$ConnectTimeoutSeconds;"" } }")
			[void]$sb.AppendLine("else { `$localEff = [regex]::Replace(`$localEff, '(?i)\bConnect\s*Timeout\s*=\s*\d+\s*', ""Connect Timeout=`$ConnectTimeoutSeconds"") }")
			[void]$sb.AppendLine("")
			[void]$sb.AppendLine("# Read key")
			[void]$sb.AppendLine("`$rawValues = @()")
			[void]$sb.AppendLine("try {")
			[void]$sb.AppendLine("  `$vals = New-Object System.Collections.Generic.List[string]")
			[void]$sb.AppendLine("  `$cn = New-Object System.Data.SqlClient.SqlConnection `$localEff")
			[void]$sb.AppendLine("  try { `$cn.Open(); `$cmd = `$cn.CreateCommand(); `$cmd.CommandText = ""SELECT F1243 FROM SYS_TAB;""; `$cmd.CommandTimeout = `$SqlTimeoutSeconds; `$rdr = `$cmd.ExecuteReader();")
			[void]$sb.AppendLine("    try { while (`$rdr.Read()) { if (-not `$rdr.IsDBNull(0)) { `$vals.Add([string]`$rdr.GetValue(0)) | Out-Null } } } finally { try { `$rdr.Close() } catch { } try { `$rdr.Dispose() } catch { } }")
			[void]$sb.AppendLine("  } finally { try { `$cn.Close() } catch { } try { `$cn.Dispose() } catch { } }")
			[void]$sb.AppendLine("  `$rawValues = @(`$vals)")
			[void]$sb.AppendLine("} catch { `$rawValues = @() }")
			[void]$sb.AppendLine("`$serverKey = `$null; `$bestLen = -1")
			[void]$sb.AppendLine("foreach (`$v in `$rawValues) { if (`$v -eq `$null) { continue }; `$t = ([string]`$v).Trim(); `$stripped = [regex]::Replace(`$t,'[\s\u00A0]+',''); if (-not [string]::IsNullOrWhiteSpace(`$t) -and -not [string]::IsNullOrWhiteSpace(`$stripped)) { if (`$t.Length -gt `$bestLen) { `$bestLen = `$t.Length; `$serverKey = `$t } } }")
			[void]$sb.AppendLine("# SYSTEM usually has no Windows login on the store DB: retry the read with SQL auth")
			[void]$sb.AppendLine("if ([string]::IsNullOrWhiteSpace(`$serverKey)) {")
			[void]$sb.AppendLine("  `$sqlEff = [regex]::Replace(`$localEff, '(?i)\b(Integrated\s+Security|Trusted_Connection)\s*=\s*[^;]*;?', '')")
			[void]$sb.AppendLine("  `$sqlEff = `$sqlEff.TrimEnd(';') + "";User ID=`$SqlUser;Password=`$SqlPass;""")
			[void]$sb.AppendLine("  try { `$cn = New-Object System.Data.SqlClient.SqlConnection `$sqlEff; try { `$cn.Open(); `$cmd = `$cn.CreateCommand(); `$cmd.CommandText = ""SELECT TOP 1 F1243 FROM SYS_TAB WHERE LEN(LTRIM(RTRIM(F1243))) > 0 ORDER BY LEN(F1243) DESC;""; `$cmd.CommandTimeout = `$SqlTimeoutSeconds; `$v = `$cmd.ExecuteScalar(); if (`$v -ne `$null -and `$v -isnot [DBNull]) { `$serverKey = ([string]`$v).Trim() } } finally { `$cn.Dispose() } } catch { }")
			[void]$sb.AppendLine("}")
			[void]$sb.AppendLine("if ([string]::IsNullOrWhiteSpace(`$serverKey)) {")
			[void]$sb.AppendLine("  `$logDir = [System.IO.Path]::GetDirectoryName(`$LatestLogPath); if (-not (Test-Path `$logDir)) { New-Item -Path `$logDir -ItemType Directory -Force | Out-Null }")
			[void]$sb.AppendLine("  @((""Timestamp : {0}"" -f (Get-Date -Format ""yyyy-MM-dd HH:mm:ss"")), ""Status    : FAILED"", ""Reason    : server key (SYS_TAB.F1243) could not be read from the local DB"") | Set-Content -Path `$LatestLogPath -Encoding UTF8")
			[void]$sb.AppendLine("  exit 1")
			[void]$sb.AppendLine("}")
			[void]$sb.AppendLine("`$safeServerKey = `$serverKey.Replace(""'"",""''"")")
			[void]$sb.AppendLine("`$updateSql = ""UPDATE SYS_TAB SET F1243 = '"" + `$safeServerKey + ""'""")
			[void]$sb.AppendLine("")
			[void]$sb.AppendLine("# SQI (ANSI/1252)")
			[void]$sb.AppendLine("`$SqiFileName = ""UPDATE_SMS_KEY.SQI""")
			[void]$sb.AppendLine("`$SqiContent  = ""@dbEXEC("" + `$updateSql + "")`r`n""")
			[void]$sb.AppendLine("`$ansi = [System.Text.Encoding]::GetEncoding(1252)")
			[void]$sb.AppendLine("`$TempSqiPath = Join-Path ([System.IO.Path]::GetTempPath()) `$SqiFileName")
			[void]$sb.AppendLine("[System.IO.File]::WriteAllText(`$TempSqiPath, `$SqiContent, `$ansi)")
			[void]$sb.AppendLine("try { attrib -a -r `"`$TempSqiPath`" 2>`$null | Out-Null } catch { }")
			[void]$sb.AppendLine("")
			[void]$sb.AppendLine("foreach (`$ln in `$LaneNumbers) {")
			[void]$sb.AppendLine("  `$pref = 'File'")
			[void]$sb.AppendLine("  if (`$ProtoMap.ContainsKey(`$ln)) { `$pref = [string]`$ProtoMap[`$ln] }")
			[void]$sb.AppendLine("  `$prefNorm = 'File'")
			[void]$sb.AppendLine("  if (-not [string]::IsNullOrWhiteSpace(`$pref)) { if (`$pref -match '(?i)^tcp$') { `$prefNorm='TCP' } elseif (`$pref -match '(?i)pipe') { `$prefNorm='Named Pipes' } }")
			[void]$sb.AppendLine("")
			[void]$sb.AppendLine("  `$laneProp = `$LaneConnMap.PSObject.Properties[`$ln]")
			[void]$sb.AppendLine("  `$laneObj  = if (`$laneProp) { `$laneProp.Value } else { `$null }")
			[void]$sb.AppendLine("  `$tcpConn  = if (`$laneObj) { [string]`$laneObj.TcpConnStr } else { `$null }")
			[void]$sb.AppendLine("  `$npConn   = if (`$laneObj) { [string]`$laneObj.NamedPipesConnStr } else { `$null }")
			[void]$sb.AppendLine("")
			[void]$sb.AppendLine("  `$sqlWorked = `$false")
			[void]$sb.AppendLine("  if (`$prefNorm -ne 'File') {")
			[void]$sb.AppendLine("    `$tryOrder = @('TCP','Named Pipes'); if (`$prefNorm -eq 'Named Pipes') { `$tryOrder=@('Named Pipes','TCP') }")
			[void]$sb.AppendLine("    foreach (`$proto in `$tryOrder) {")
			[void]$sb.AppendLine("      `$connToUse = if (`$proto -eq 'Named Pipes') { `$npConn } else { `$tcpConn }")
			[void]$sb.AppendLine("      if ([string]::IsNullOrWhiteSpace(`$connToUse)) { continue }")
			[void]$sb.AppendLine("      `$connEff = `$connToUse")
			[void]$sb.AppendLine("      `$connEff = [regex]::Replace(`$connEff, '(?i)\bIntegrated\s+Security\s*=\s*True\s*;?', '')")
			[void]$sb.AppendLine("      `$connEff = [regex]::Replace(`$connEff, '(?i)\bTrusted_Connection\s*=\s*Yes\s*;?', '')")
			[void]$sb.AppendLine("      if (`$connEff -notmatch '(?i)\bUser\s*ID\s*=') { if (`$connEff.Trim().EndsWith(';')) { `$connEff += ""User ID=`$SqlUser;"" } else { `$connEff += "";User ID=`$SqlUser;"" } }")
			[void]$sb.AppendLine("      if (`$connEff -notmatch '(?i)\bPassword\s*=') { if (`$connEff.Trim().EndsWith(';')) { `$connEff += ""Password=`$SqlPass;"" } else { `$connEff += "";Password=`$SqlPass;"" } }")
			[void]$sb.AppendLine("      if (`$connEff -notmatch '(?i)\bConnect\s*Timeout\s*=') { if (`$connEff.Trim().EndsWith(';')) { `$connEff += ""Connect Timeout=`$ConnectTimeoutSeconds;"" } else { `$connEff += "";Connect Timeout=`$ConnectTimeoutSeconds;"" } }")
			[void]$sb.AppendLine("      else { `$connEff = [regex]::Replace(`$connEff, '(?i)\bConnect\s*Timeout\s*=\s*\d+\s*', ""Connect Timeout=`$ConnectTimeoutSeconds"") }")
			[void]$sb.AppendLine("      try { `$cn2 = New-Object System.Data.SqlClient.SqlConnection `$connEff; try { `$cn2.Open(); `$cmd2 = `$cn2.CreateCommand(); `$cmd2.CommandText = `$updateSql; `$cmd2.CommandTimeout = `$SqlTimeoutSeconds; [void]`$cmd2.ExecuteNonQuery(); `$sqlWorked = `$true } finally { try { `$cn2.Close() } catch { } try { `$cn2.Dispose() } catch { } } } catch { `$sqlWorked = `$false }")
			[void]$sb.AppendLine("      if (`$sqlWorked) { `$UpdatedViaSql.Add(`$ln) | Out-Null; break }")
			[void]$sb.AppendLine("    }")
			[void]$sb.AppendLine("  }")
			[void]$sb.AppendLine("  if (-not `$sqlWorked) {")
			[void]$sb.AppendLine("    `$laneXF = Join-Path `$OfficePath (""XF{0}{1}"" -f `$StoreNumber, `$ln)")
			[void]$sb.AppendLine("    `$dest = Join-Path `$laneXF `$SqiFileName")
			[void]$sb.AppendLine("    if (-not (Test-Path `$laneXF)) { `$FailedLanes.Add(`$ln) | Out-Null }")
			[void]$sb.AppendLine("    else { try { Copy-Item -Path `$TempSqiPath -Destination `$dest -Force; try { attrib -a -r `"`$dest`" 2>`$null | Out-Null } catch { }; `$UpdatedViaFile.Add(`$ln) | Out-Null } catch { `$FailedLanes.Add(`$ln) | Out-Null } }")
			[void]$sb.AppendLine("  }")
			[void]$sb.AppendLine("}")
			[void]$sb.AppendLine("")
			[void]$sb.AppendLine("`$okAll = @(@(`$UpdatedViaSql) + @(`$UpdatedViaFile) | Where-Object { `$_ } | Select-Object -Unique)")
			[void]$sb.AppendLine("`$status = ""FAILED""; if (`$okAll.Count -gt 0) { `$status = ""OK""; if (`$FailedLanes.Count -gt 0) { `$status = ""PARTIAL"" } }")
			[void]$sb.AppendLine("`$okAllText = ""(none)""; if (`$okAll.Count -gt 0) { `$okAllText = (`$okAll -join "", "") }")
			[void]$sb.AppendLine("`$sqlText = ""(none)""; if (`$UpdatedViaSql.Count -gt 0) { `$sqlText = (@(`$UpdatedViaSql) -join "", "") }")
			[void]$sb.AppendLine("`$sqiText = ""(none)""; if (`$UpdatedViaFile.Count -gt 0) { `$sqiText = (@(`$UpdatedViaFile) -join "", "") }")
			[void]$sb.AppendLine("`$failedText = ""(none)""; if (`$FailedLanes.Count -gt 0) { `$failedText = (@(`$FailedLanes) -join "", "") }")
			[void]$sb.AppendLine("`$lines = New-Object System.Collections.Generic.List[string]")
			[void]$sb.AppendLine("`$lines.Add((""Timestamp : {0}"" -f (Get-Date -Format ""yyyy-MM-dd HH:mm:ss""))) | Out-Null")
			[void]$sb.AppendLine("`$lines.Add((""Computer  : {0}"" -f `$env:COMPUTERNAME)) | Out-Null")
			[void]$sb.AppendLine("`$lines.Add((""Store     : {0}"" -f `$StoreNumber)) | Out-Null")
			[void]$sb.AppendLine("`$lines.Add((""ProtocolFile : {0}"" -f `$ProtocolFile)) | Out-Null")
			[void]$sb.AppendLine("`$lines.Add((""Status    : {0}"" -f `$status)) | Out-Null")
			[void]$sb.AppendLine("`$lines.Add((""Selected  : {0}"" -f (`$LaneNumbers -join "", ""))) | Out-Null")
			[void]$sb.AppendLine("`$lines.Add((""OK (ALL)  : {0}"" -f `$okAllText)) | Out-Null")
			[void]$sb.AppendLine("`$lines.Add((""OK (SQL)  : {0}"" -f `$sqlText)) | Out-Null")
			[void]$sb.AppendLine("`$lines.Add((""OK (SQI)  : {0}"" -f `$sqiText)) | Out-Null")
			[void]$sb.AppendLine("`$lines.Add((""Failed    : {0}"" -f `$failedText)) | Out-Null")
			[void]$sb.AppendLine("`$logDir = [System.IO.Path]::GetDirectoryName(`$LatestLogPath)")
			[void]$sb.AppendLine("if (-not (Test-Path `$logDir)) { New-Item -Path `$logDir -ItemType Directory -Force | Out-Null }")
			[void]$sb.AppendLine("`$lines | Set-Content -Path `$LatestLogPath -Encoding UTF8")

			try
			{
				Set-Content -Path $taskScriptPath -Value ($sb.ToString() -replace "`r?`n", "`r`n") -Encoding UTF8
				Write_Log "Task script written/updated (single file): $taskScriptPath" "green"
				Write_Log "Latest results log (overwrites each run): $latestLogPath" "cyan"
			}
			catch
			{
				Write_Log "Failed to write task script '$taskScriptPath'. Error: $_" "red"
				Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
				return
			}

			try
			{
				$taskName = "Send_SMS_Key - Store $StoreNumber"
				$psExe = Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe"
				# \" survives 5.1's native argument passing (plain quotes were stripped, so a path with spaces broke)
				$tr = "\`"$psExe\`" -NoProfile -ExecutionPolicy Bypass -File \`"$taskScriptPath\`""

				$null = schtasks /Delete /TN "$taskName" /F 2>$null
				$out = schtasks /Create /TN "$taskName" /TR $tr /SC MINUTE /MO $freqMinutes /RL HIGHEST /F /RU "SYSTEM" 2>&1

				if ($LASTEXITCODE -eq 0)
				{
					Write_Log "Scheduled Task created/updated: $taskName (every $freqMinutes minutes, SYSTEM)." "green"
				}
				else
				{
					Write_Log "Failed to create scheduled task '$taskName'. schtasks said: $out" "red"
					Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
					return
				}
			}
			catch
			{
				Write_Log "Failed to create/update Scheduled Task. Error: $_" "red"
				Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
				return
			}
		}
	}

	Write_Log "`r`n==================== Send_SMS_Key_to_Lanes Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Send_TIME_Sync_Lanes_Worker
# ---------------------------------------------------------------------------------------------------
# Description:
#   The per-lane time-sync work behind Send_SERVER_time_to_Lanes (v2.6.9): builds a fresh
#   WIZRPL date/time string at start and pushes a time sync (remote schtasks net time task)
#   to each selected lane. Split out of the wizard so it can run in a background job via
#   Start_Background_Function_Job; running it inline is still supported as a fallback.
#
# Parameters:
#   - StoreNumber     [string]: store to process (required)
#   - SelectedLanes   [any]: lanes to sync, numbers or lane objects (required)
#   - IsScheduling    [switch]: create a recurring task instead of a one-shot sync
#   - IntervalMinutes [int]: schedule interval when -IsScheduling (default 0)
#
# Variables:
#   - $script:FunctionResults['LaneNumToMachineName']: lane map (input)
#
# Writes:
#   - remote scheduled time-sync tasks on the selected lanes
# ===================================================================================================

function Send_TIME_Sync_Lanes_Worker
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber,
		[Parameter(Mandatory = $true)]
		$SelectedLanes,
		[switch]$IsScheduling,
		[int]$IntervalMinutes = 0
	)

	# The mailslot type does not exist in a job runspace; this is a
	# no-op where it is already loaded.
	try { Ensure_MailslotSender_Type } catch { }

	# 3. Build Time String
	$now = Get-Date
	$dateStr = $now.ToString("MM/dd/yyyy")
	$timeStr = $now.ToString("HHmmss")
	$wizCommand = "@WIZRPL(DATE=$dateStr)@WIZRPL(TIME=$timeStr)"

	# This server's IP for 'net time' (resolved once, not per lane)
	$serverIP = $env:COMPUTERNAME
	try { $serverIP = (Test-Connection -ComputerName $env:COMPUTERNAME -Count 1 -ErrorAction Stop).IPv4Address.IPAddressToString }
	catch { }
	$netTimeCommand = "net time \\$serverIP /set /yes"

	foreach ($lane in $SelectedLanes)
	{
		# Lane number normalization
		$laneNum = if ($lane -is [pscustomobject] -and $lane.LaneNumber) { $lane.LaneNumber }
		elseif ($lane -is [int]) { "{0:D3}" -f $lane }
		elseif ($lane.Length -lt 3) { $lane.PadLeft(3, '0') }
		else { $lane }

		$machine = $script:FunctionResults['LaneNumToMachineName'][$laneNum]
		if (-not $machine)
		{
			Write_Log "No machine name found for lane $laneNum." "red"
			continue
		}

		$success = $false

		# -------- PRIMARY: REMOTE SCHTASKS (SYSTEM task running net time against this server) --------
		try
		{
			$taskName = if ($IsScheduling) { "ScheduledTimeSync" } else { "SyncTime" }
			$createArgs = @('/create', '/s', $machine, '/tn', $taskName, '/tr', $netTimeCommand, '/ru', 'SYSTEM', '/f', '/rl', 'HIGHEST')
			if ($IsScheduling) { $createArgs += @('/sc', 'minute', '/mo', [string]$IntervalMinutes) }
			else
			{
				# /ST is mandatory for /SC ONCE (without it the create always failed before v2.7.0);
				# the task is started right away with /run, the time only satisfies schtasks
				$createArgs += @('/sc', 'once', '/st', (Get-Date).AddMinutes(1).ToString('HH:mm'))
			}
			$createOutput = & schtasks.exe @createArgs 2>&1
			if ($LASTEXITCODE -eq 0)
			{
				if ($IsScheduling)
				{
					Write_Log "Scheduled time sync every $IntervalMinutes minutes on lane $laneNum." "green"
					$success = $true
				}
				else
				{
					$runOutput = & schtasks.exe /run /s $machine /tn $taskName 2>&1
					if ($LASTEXITCODE -eq 0)
					{
						Write_Log "Executed time sync on lane $laneNum." "green"
						$success = $true
						# one-shot: remove the task once it had time to run
						Start-Sleep -Seconds 5
						$deleteOutput = & schtasks.exe /delete /s $machine /tn $taskName /f 2>&1
						if ($LASTEXITCODE -ne 0) { Write_Log "Delete output for [$machine]: $deleteOutput" "yellow" }
					}
					else { Write_Log "Run output for [$machine]: $runOutput" "yellow" }
				}
			}
			else { Write_Log "Create output for [$machine]: $createOutput" "yellow" }
		}
		catch
		{
			Write_Log "Exception during schtasks create/run: $_" "yellow"
		}
		# -------- SECONDARY: FILE-DROP WITH @EXEC --------
		if (-not $success)
		{
			try
			{
				$TempDir = $env:TEMP
				$xfFolder = Join-Path $OfficePath ("XF{0}{1}" -f $StoreNumber, $laneNum)

				if (-not (Test-Path $xfFolder))
				{
					Write_Log "XF folder for lane $laneNum does not exist: $xfFolder" "red"
					continue
				}

				# Always-available lane path
				$remoteShareRoot = "\\$machine\Storeman\Temp"
				if (-not (Test-Path $remoteShareRoot))
				{
					Write_Log "Lane share not reachable: $remoteShareRoot" "yellow"
					throw "Storeman\Temp not reachable"
				}

				$remoteBatPath = Join-Path $remoteShareRoot "sync_time.bat"

				# Create local BAT (ASCII)
				$batContent = "@echo off`r`nnet time \\$serverIP /set /yes"
				$localBatPath = Join-Path $TempDir ("sync_time_{0}.bat" -f $laneNum)
				Set-Content -Path $localBatPath -Value $batContent -Encoding Ascii

				# Copy to lane
				Copy-Item -Path $localBatPath -Destination $remoteBatPath -Force -ErrorAction Stop
				Remove-Item -Path $localBatPath -Force -ErrorAction SilentlyContinue
				Write_Log "Copied sync_time.bat to \\$machine\Storeman\Temp for lane $laneNum." "green"

				# Drop exec trigger in XF (ASCII)
				$execFilePath = Join-Path $xfFolder "exec_time_sync.txt"
				$execContent = "@EXEC(Run='" + (Join-Path $script:PrimaryStoremanRoot 'Temp\sync_time.bat') + "')"
				Set-Content -Path $execFilePath -Value $execContent -Encoding Ascii -ErrorAction Stop

				# Clear archive bit on exec trigger (so SMS processes it cleanly)
				try { attrib -a -r "$execFilePath" 2>$null | Out-Null }
				catch { }

				Write_Log "Created @EXEC trigger in XF folder for lane $laneNum (Storeman\Temp path)." "green"

				# Optional: cleanup remote bat after a bit
				Start-Sleep -Seconds 10
				Remove-Item -Path $remoteBatPath -Force -ErrorAction SilentlyContinue

				$success = $true
			}
			catch
			{
				Write_Log "File/@EXEC fallback failed for lane ${laneNum}: $_" "red"
			}
		}

		# -------- TERTIARY: MAILSLOT --------
		if (-not $success)
		{
			try
			{
				$mailslot = "\\$machine\mailslot\SMSStart_${StoreNumber}${laneNum}"
				$result = [MailslotSender]::SendMailslotCommand($mailslot, $wizCommand)
				if ($result)
				{
					Write_Log "Time sync sent to $machine (Lane $laneNum) via mailslot (final fallback)." "green"
					$success = $true
				}
				else
				{
					Write_Log "Mailslot failed for $machine (Lane $laneNum) [final fallback]." "yellow"
				}
			}
			catch
			{
				Write_Log "Exception during mailslot send (final fallback): $_" "yellow"
			}
		}

		if (-not $success)
		{
			Write_Log "All methods failed for lane $laneNum!" "red"
		}
	}

	Write_Log "`r`n==================== Ending Time Sync ====================`r`n" "blue"
}

# ===================================================================================================
#                              FUNCTION: Show_Lane_SQL_VNC_Service_Statuses
# ---------------------------------------------------------------------------------------------------
# Description:
#   Opens a styled popup that checks the SQL and VNC services on all lanes of the store in
#   the background (runspace pool, up to 8 lanes at a time) and fills a grid as results
#   arrive. Right-click a lane to refresh it or start / stop / restart its SQL or VNC
#   service. Shows a message box when no usable lanes are found.
#
# Variables:
#   - $script:FunctionResults['StoreNumber']: store header text
#   - $script:FunctionResults['LaneNumToMachineName']: lane map (input)
# ===================================================================================================

function Show_Lane_SQL_VNC_Service_Statuses
{
	$storeNumber = $script:FunctionResults['StoreNumber']
	$laneMap = $script:FunctionResults['LaneNumToMachineName']

	if (-not $laneMap -or $laneMap.Count -eq 0)
	{
		[System.Windows.Forms.MessageBox]::Show(
			"No lanes were found for this store.",
			"Lane Services",
			[System.Windows.Forms.MessageBoxButtons]::OK,
			[System.Windows.Forms.MessageBoxIcon]::Information
		) | Out-Null
		return
	}

	$selectedLanes = @($laneMap.Keys | Where-Object { $_ -and $laneMap.ContainsKey([string]$_) } | Sort-Object { [int]$_ })
	if (-not $selectedLanes -or $selectedLanes.Count -eq 0)
	{
		[System.Windows.Forms.MessageBox]::Show(
			"No usable lanes were found.",
			"Lane Services",
			[System.Windows.Forms.MessageBoxButtons]::OK,
			[System.Windows.Forms.MessageBoxIcon]::Information
		) | Out-Null
		return
	}

	$formSvc = New-Object System.Windows.Forms.Form
	$formSvc.Text = "Lane SQL / VNC Services"
	$formSvc.StartPosition = 'CenterParent'
	$formSvc.Size = New-Object System.Drawing.Size(980, 520)
	$formSvc.MinimumSize = New-Object System.Drawing.Size(860, 420)
	$formSvc.MaximizeBox = $true
	$formSvc.MinimizeBox = $false

	$layoutSvc = New-Object System.Windows.Forms.TableLayoutPanel
	$layoutSvc.Dock = 'Fill'
	$layoutSvc.ColumnCount = 1
	$layoutSvc.RowCount = 3
	[void]$layoutSvc.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::AutoSize)))
	[void]$layoutSvc.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Percent, 100)))
	[void]$layoutSvc.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::AutoSize)))
	$formSvc.Controls.Add($layoutSvc)

	$lblSvcHeader = New-Object System.Windows.Forms.Label
	$lblSvcHeader.Text = ("Store {0} - SQL and VNC service status for all {1} lane(s)" -f $storeNumber, $selectedLanes.Count)
	$lblSvcHeader.AutoSize = $true
	$lblSvcHeader.Margin = New-Object System.Windows.Forms.Padding(12, 12, 12, 6)
	$layoutSvc.Controls.Add($lblSvcHeader, 0, 0)

	$gridSvc = New-Object System.Windows.Forms.DataGridView
	$gridSvc.Dock = 'Fill'
	$gridSvc.AllowUserToAddRows = $false
	$gridSvc.AllowUserToDeleteRows = $false
	$gridSvc.AllowUserToResizeRows = $false
	$gridSvc.ReadOnly = $true
	$gridSvc.MultiSelect = $false
	$gridSvc.RowHeadersVisible = $false
	$gridSvc.SelectionMode = 'FullRowSelect'
	$gridSvc.AutoSizeColumnsMode = 'Fill'
	$gridSvc.Margin = New-Object System.Windows.Forms.Padding(12, 0, 12, 8)
	[void]$gridSvc.Columns.Add("Lane", "Lane")
	[void]$gridSvc.Columns.Add("Machine", "Machine")
	[void]$gridSvc.Columns.Add("SqlService", "SQL Service")
	[void]$gridSvc.Columns.Add("SqlStatus", "SQL Status")
	[void]$gridSvc.Columns.Add("VncService", "VNC Service")
	[void]$gridSvc.Columns.Add("VncStatus", "VNC Status")
	$gridSvc.Columns["Lane"].FillWeight = 55
	$gridSvc.Columns["Machine"].FillWeight = 95
	$gridSvc.Columns["SqlService"].FillWeight = 120
	$gridSvc.Columns["SqlStatus"].FillWeight = 85
	$gridSvc.Columns["VncService"].FillWeight = 120
	$gridSvc.Columns["VncStatus"].FillWeight = 85
	$layoutSvc.Controls.Add($gridSvc, 0, 1)

	$pnlSvcBottom = New-Object System.Windows.Forms.TableLayoutPanel
	$pnlSvcBottom.Dock = 'Fill'
	$pnlSvcBottom.ColumnCount = 1
	$pnlSvcBottom.RowCount = 2
	$pnlSvcBottom.Margin = New-Object System.Windows.Forms.Padding(12, 0, 12, 12)
	[void]$pnlSvcBottom.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent, 100)))
	[void]$pnlSvcBottom.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::AutoSize)))
	[void]$pnlSvcBottom.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::AutoSize)))
	$layoutSvc.Controls.Add($pnlSvcBottom, 0, 2)

	$lblSvcStatus = New-Object System.Windows.Forms.Label
	$lblSvcStatus.Text = "Checking all lanes..."
	$lblSvcStatus.AutoSize = $true
	$lblSvcStatus.Anchor = 'Left'
	$lblSvcStatus.Margin = New-Object System.Windows.Forms.Padding(0, 8, 12, 0)
	$pnlSvcBottom.Controls.Add($lblSvcStatus, 0, 0)

	$pnlSvcActions = New-Object System.Windows.Forms.FlowLayoutPanel
	$pnlSvcActions.AutoSize = $true
	$pnlSvcActions.WrapContents = $false
	$pnlSvcActions.AutoScroll = $true
	$pnlSvcActions.FlowDirection = 'LeftToRight'
	$pnlSvcActions.Dock = 'Fill'
	$pnlSvcActions.Margin = New-Object System.Windows.Forms.Padding(0, 4, 0, 0)
	$pnlSvcBottom.Controls.Add($pnlSvcActions, 0, 1)

	$btnSvcRefresh = New-Object System.Windows.Forms.Button
	$btnSvcRefresh.Text = "Refresh All"
	$btnSvcRefresh.Size = New-Object System.Drawing.Size(110, 32)
	$pnlSvcActions.Controls.Add($btnSvcRefresh)

	$btnSvcClose = New-Object System.Windows.Forms.Button
	$btnSvcClose.Text = "Close"
	$btnSvcClose.Size = New-Object System.Drawing.Size(110, 32)
	$btnSvcClose.Add_Click({ $formSvc.Close() })
	$pnlSvcActions.Controls.Add($btnSvcClose)
	$formSvc.AcceptButton = $btnSvcClose
	$formSvc.CancelButton = $btnSvcClose

	if ($Apply_Modern_Popup_Style) { & $Apply_Modern_Popup_Style $formSvc }

	# ---- Background work: one runspace pool (Start-Job spawned a powershell.exe per lane) ----------
	$svcPool = [RunspaceFactory]::CreateRunspacePool(1, [Math]::Min(8, [Math]::Max(2, $selectedLanes.Count)))
	$svcPool.Open()
	$svcJobs = @{ }
	$svcActionJobs = @{ }
	$rowMap = @{ }
	$totalRows = $selectedLanes.Count

	# Lane status: reachability (ping, then SMB 445), then the SQL and VNC services.
	# Text, not a scriptblock: the action script rebuilds it to re-read the status.
	$statusCheckText = @'
param ([string]$Lane, [string]$Machine, [string]$ExpectedSqlService)

$result = [pscustomobject][ordered]@{
	Lane          = $Lane
	Machine       = $Machine
	SqlService    = if ([string]::IsNullOrWhiteSpace($ExpectedSqlService)) { 'MSSQLSERVER' } else { $ExpectedSqlService }
	SqlStatus     = 'Not Found'
	VncService    = 'Not Found'
	VncStatus     = 'Not Found'
	ActionSummary = $null
}

$reachable = $false
try { $reachable = ((New-Object System.Net.NetworkInformation.Ping).Send($Machine, 700).Status -eq 'Success') }
catch { }
if (-not $reachable)
{
	$tcp = New-Object System.Net.Sockets.TcpClient
	try
	{
		$async = $tcp.BeginConnect($Machine, 445, $null, $null)
		if ($async.AsyncWaitHandle.WaitOne(700, $false) -and $tcp.Connected) { $reachable = $true }
	}
	catch { }
	finally { $tcp.Close() }
}
if (-not $reachable)
{
	$result.SqlStatus = 'Offline'
	$result.VncService = 'Offline'
	$result.VncStatus = 'Offline'
	return $result
}

$services = $null
$serviceFetchError = $null
try { $services = Get-Service -ComputerName $Machine -ErrorAction Stop | Select-Object Name, DisplayName, Status }
catch { $serviceFetchError = $_.Exception.Message }
if (-not $services)
{
	try
	{
		$services = Get-CimInstance -ClassName Win32_Service -ComputerName $Machine -ErrorAction Stop |
		Select-Object Name, DisplayName, @{ Name = 'Status'; Expression = { $_.State } }
		$serviceFetchError = $null
	}
	catch { $serviceFetchError = $_.Exception.Message }
}
if (-not $services)
{
	$errorText = if ([string]::IsNullOrWhiteSpace($serviceFetchError)) { 'Error' } else { "Error: $serviceFetchError" }
	$result.SqlStatus = $errorText
	$result.VncStatus = $errorText
	$result.VncService = 'Unavailable'
	return $result
}

$sqlService = $services | Where-Object { $_.Name -ieq $result.SqlService } | Select-Object -First 1
if (-not $sqlService)
{
	$sqlService = $services | Where-Object { $_.Name -like 'MSSQL*' -or $_.DisplayName -match '(?i)^SQL Server' } | Sort-Object Name | Select-Object -First 1
}
if ($sqlService)
{
	$result.SqlService = [string]$sqlService.Name
	$result.SqlStatus = [string]$sqlService.Status
}

$vncService = $services | Where-Object {
	([string]$_.Name -match '(?i)^(uvnc_service|winvnc.*|tvnserver|vncserver|tigervnc.*|tightvnc.*)$') -or
	([string]$_.DisplayName -match '(?i)ultravnc|tightvnc|tigervnc|vnc')
} | Sort-Object Name | Select-Object -First 1
if ($vncService)
{
	$result.VncService = [string]$vncService.Name
	$result.VncStatus = [string]$vncService.Status
}

$result
'@

	# Start / Stop / Restart one service, then poll the status until it settles (~14 s max)
	$serviceActionText = @'
param ([string]$Lane, [string]$Machine, [string]$ExpectedSqlService, [string]$ServiceKind, [string]$ServiceName, [string]$RequestedAction, [string]$StatusCheckText)

$getSnapshot = [scriptblock]::Create($StatusCheckText)
$actionSummary = "$RequestedAction $ServiceKind on lane $Lane."
try
{
	$filter = "Name='{0}'" -f $ServiceName.Replace("'", "''")
	if ($RequestedAction -in @('Stop', 'Restart'))
	{
		$svcObject = Get-CimInstance -ClassName Win32_Service -ComputerName $Machine -Filter $filter -ErrorAction Stop
		$null = Invoke-CimMethod -InputObject $svcObject -MethodName StopService -ErrorAction Stop
	}
	if ($RequestedAction -eq 'Restart') { Start-Sleep -Seconds 2 }
	if ($RequestedAction -in @('Start', 'Restart'))
	{
		$svcObject = Get-CimInstance -ClassName Win32_Service -ComputerName $Machine -Filter $filter -ErrorAction Stop
		$null = Invoke-CimMethod -InputObject $svcObject -MethodName StartService -ErrorAction Stop
	}
}
catch
{
	# CIM blocked (firewall / WinRM): the Service Control Manager over SMB usually still works
	try
	{
		if ($RequestedAction -in @('Stop', 'Restart')) { $null = & sc.exe "\\$Machine" stop $ServiceName 2>$null }
		if ($RequestedAction -eq 'Restart') { Start-Sleep -Seconds 2 }
		if ($RequestedAction -in @('Start', 'Restart')) { $null = & sc.exe "\\$Machine" start $ServiceName 2>$null }
		# sc.exe never throws; 1056 = already running, 1062 = not started (already stopped)
		if ($LASTEXITCODE -notin @(0, 1056, 1062)) { $actionSummary = "Failed to $RequestedAction $ServiceKind on lane $Lane (sc.exe error $LASTEXITCODE)." }
	}
	catch { $actionSummary = "Failed to $RequestedAction $ServiceKind on lane ${Lane}: $($_.Exception.Message)" }
}

$targetStatus = if ($RequestedAction -eq 'Stop') { 'Stopped' } else { 'Running' }
for ($i = 0; $i -lt 18; $i++)
{
	Start-Sleep -Milliseconds 750
	$snapshot = & $getSnapshot $Lane $Machine $ExpectedSqlService
	$currentStatus = if ($ServiceKind -eq 'SQL') { [string]$snapshot.SqlStatus } else { [string]$snapshot.VncStatus }
	if ($currentStatus -eq $targetStatus -or $currentStatus -like 'Error*' -or $currentStatus -in @('Not Found', 'Offline')) { break }
}
$snapshot.ActionSummary = $actionSummary
$snapshot
'@

	$startPoolWork = {
		param ([string]$ScriptText, [object[]]$Arguments)
		$ps = [PowerShell]::Create()
		$ps.RunspacePool = $svcPool
		[void]$ps.AddScript($ScriptText)
		foreach ($a in $Arguments) { [void]$ps.AddArgument($a) }
		@{ PS = $ps; Handle = $ps.BeginInvoke() }
	}

	# Finished work item -> its result object (or $null), and the PowerShell instance disposed
	$collectPoolWork = {
		param ($Entry)
		$res = $null
		try { $res = @($Entry.PS.EndInvoke($Entry.Handle)) | Select-Object -Last 1 }
		catch { }
		try { $Entry.PS.Dispose() }
		catch { }
		$res
	}

	$stopPoolWork = {
		param ($Entry)
		try { [void]$Entry.PS.BeginStop($null, $null) }
		catch { }
	}

	# Service name the lane's SQL instance should have (MSSQLSERVER or MSSQL$<instance>)
	$getExpectedSqlService = {
		param ([string]$LaneKey)
		try
		{
			$dbInfo = Get_All_Lanes_Database_Info -LaneNumber $LaneKey
			$instanceName = if ($dbInfo) { [string]$dbInfo['InstanceName'] }
			if (-not [string]::IsNullOrWhiteSpace($instanceName) -and $instanceName.ToUpper() -ne 'MSSQLSERVER') { return "MSSQL`$$instanceName" }
		}
		catch { }
		'MSSQLSERVER'
	}

	$applyResultToRow = {
		param ([int]$RowIndex, $Result)
		if ($RowIndex -lt 0 -or $RowIndex -ge $gridSvc.Rows.Count) { return }
		$row = $gridSvc.Rows[$RowIndex]
		if (-not $Result)
		{
			$row.Cells["SqlStatus"].Value = 'Error'
			$row.Cells["VncStatus"].Value = 'Error'
			return
		}
		$row.Cells["SqlService"].Value = [string]$Result.SqlService
		$row.Cells["SqlStatus"].Value = [string]$Result.SqlStatus
		$row.Cells["VncService"].Value = [string]$Result.VncService
		$row.Cells["VncStatus"].Value = [string]$Result.VncStatus
	}

	$startActionJobForSelectedRow = {
		param (
			[string]$ServiceKind,
			[string]$RequestedAction
		)

		if (-not $gridSvc.SelectedRows -or $gridSvc.SelectedRows.Count -eq 0)
		{
			[void][System.Windows.Forms.MessageBox]::Show("Select a lane first.", "Lane Services", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
			return
		}

		$row = $gridSvc.SelectedRows[0]
		$laneKey = [string]$row.Cells["Lane"].Value
		$machineName = [string]$row.Cells["Machine"].Value
		$expectedSqlService = [string]$row.Cells["SqlService"].Value
		$serviceName = if ($ServiceKind -eq 'SQL') { $expectedSqlService } else { [string]$row.Cells["VncService"].Value }
		$statusColumn = if ($ServiceKind -eq 'SQL') { 'SqlStatus' } else { 'VncStatus' }

		if ([string]::IsNullOrWhiteSpace($laneKey) -or [string]::IsNullOrWhiteSpace($machineName)) { return }
		if ($svcActionJobs.ContainsKey($laneKey))
		{
			[void][System.Windows.Forms.MessageBox]::Show("A service action is already running for lane $laneKey.", "Lane Services", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
			return
		}
		if ([string]::IsNullOrWhiteSpace($serviceName) -or $serviceName -in @('Checking...', 'Not Found', 'Unavailable', 'Offline'))
		{
			[void][System.Windows.Forms.MessageBox]::Show("$ServiceKind service was not found for lane $laneKey.", "Lane Services", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information)
			return
		}

		$row.Cells[$statusColumn].Value = "$RequestedAction..."
		$lblSvcStatus.Text = ("{0} {1} on lane {2}..." -f $RequestedAction, $ServiceKind, $laneKey)

		$work = & $startPoolWork $serviceActionText @($laneKey, $machineName, $expectedSqlService, $ServiceKind, $serviceName, $RequestedAction, $statusCheckText)
		$work.Row = $row.Index
		$svcActionJobs[$laneKey] = $work
	}

	$refreshSvcLanes = {
		param (
			[string[]]$LaneKeysToRefresh
		)

		foreach ($laneKey in @($LaneKeysToRefresh))
		{
			if (-not $laneMap.ContainsKey($laneKey) -or -not $rowMap.ContainsKey($laneKey)) { continue }

			# A refresh replaces a check still in flight for the lane
			if ($svcJobs.ContainsKey($laneKey))
			{
				& $stopPoolWork $svcJobs[$laneKey]
				[void]$svcJobs.Remove($laneKey)
			}

			$machineName = [string]$laneMap[$laneKey]
			$expectedSqlService = & $getExpectedSqlService $laneKey
			$rowIndex = [int]$rowMap[$laneKey]
			$gridSvc.Rows[$rowIndex].Cells["SqlService"].Value = $expectedSqlService
			$gridSvc.Rows[$rowIndex].Cells["SqlStatus"].Value = 'Checking...'
			$gridSvc.Rows[$rowIndex].Cells["VncService"].Value = 'Checking...'
			$gridSvc.Rows[$rowIndex].Cells["VncStatus"].Value = 'Checking...'

			$work = & $startPoolWork $statusCheckText @($laneKey, $machineName, $expectedSqlService)
			$work.Row = $rowIndex
			$svcJobs[$laneKey] = $work
		}
	}

	$svcRowMenu = New-Object System.Windows.Forms.ContextMenuStrip
	if ($Apply_Modern_Menu_Style) { & $Apply_Modern_Menu_Style $svcRowMenu }
	$miSvcRefreshLane = New-Object System.Windows.Forms.ToolStripMenuItem("Refresh This Lane")
	$miSvcRefreshLane.Add_Click({
			$script:LastActivity = Get-Date
			if ($gridSvc.SelectedRows -and $gridSvc.SelectedRows.Count -gt 0)
			{
				$laneKey = [string]$gridSvc.SelectedRows[0].Cells["Lane"].Value
				if (-not [string]::IsNullOrWhiteSpace($laneKey))
				{
					& $refreshSvcLanes @($laneKey)
					$lblSvcStatus.Text = ("Refreshing lane {0}..." -f $laneKey)
				}
			}
		})
	[void]$svcRowMenu.Items.Add($miSvcRefreshLane)

	# Start / Stop / Restart for SQL and VNC; the menu item's Tag carries kind + action
	foreach ($kind in @('SQL', 'VNC'))
	{
		[void]$svcRowMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
		foreach ($action in @('Start', 'Stop', 'Restart'))
		{
			$mi = New-Object System.Windows.Forms.ToolStripMenuItem("$action $kind")
			$mi.Tag = @($kind, $action)
			$mi.Add_Click({
					param ($sender, $e)
					$script:LastActivity = Get-Date
					& $startActionJobForSelectedRow $sender.Tag[0] $sender.Tag[1]
				})
			[void]$svcRowMenu.Items.Add($mi)
		}
	}
	$gridSvc.ContextMenuStrip = $svcRowMenu
	$gridSvc.Add_MouseDown({
			param ($sender,
				$e)
			if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Right) { return }
			$hit = $gridSvc.HitTest($e.X, $e.Y)
			if ($hit.RowIndex -lt 0) { return }
			try
			{
				$gridSvc.ClearSelection()
				$gridSvc.Rows[$hit.RowIndex].Selected = $true
				$gridSvc.CurrentCell = $gridSvc.Rows[$hit.RowIndex].Cells[0]
			}
			catch { }
		})

	# One row per lane, then the first check for all of them
	foreach ($lane in $selectedLanes)
	{
		$laneKey = [string]$lane
		$rowMap[$laneKey] = $gridSvc.Rows.Add($laneKey, [string]$laneMap[$laneKey], 'MSSQLSERVER', 'Checking...', 'Checking...', 'Checking...')
	}
	& $refreshSvcLanes @($selectedLanes | ForEach-Object { [string]$_ })

	$btnSvcRefresh.Add_Click({
			$script:LastActivity = Get-Date
			& $refreshSvcLanes @($selectedLanes | ForEach-Object { [string]$_ })
			$lblSvcStatus.Text = "Refreshing all lanes..."
		})

	$svcTimer = New-Object System.Windows.Forms.Timer
	$svcTimer.Interval = 700
	$svcTimer.Add_Tick({
			foreach ($laneKey in @($svcJobs.Keys))
			{
				$entry = $svcJobs[$laneKey]
				if (-not $entry.Handle.IsCompleted) { continue }
				& $applyResultToRow ([int]$entry.Row) (& $collectPoolWork $entry)
				[void]$svcJobs.Remove($laneKey)
			}

			foreach ($laneKey in @($svcActionJobs.Keys))
			{
				$entry = $svcActionJobs[$laneKey]
				if (-not $entry.Handle.IsCompleted) { continue }
				$result = & $collectPoolWork $entry
				if ($result) { & $applyResultToRow ([int]$entry.Row) $result }
				if ($result -and -not [string]::IsNullOrWhiteSpace([string]$result.ActionSummary)) { $lblSvcStatus.Text = [string]$result.ActionSummary }
				[void]$svcActionJobs.Remove($laneKey)
			}

			$pendingStatusCount = $svcJobs.Count
			$pendingActionCount = $svcActionJobs.Count
			if ($pendingActionCount -gt 0)
			{
				$lblSvcStatus.Text = ("Working... {0} action(s), {1} refresh check(s) pending" -f $pendingActionCount, $pendingStatusCount)
			}
			elseif ($pendingStatusCount -gt 0)
			{
				$lblSvcStatus.Text = ("Checking all lanes... {0}/{1} complete" -f ($totalRows - $pendingStatusCount), $totalRows)
			}
			elseif ($lblSvcStatus.Text -match '^(Checking|Refreshing|Working)')
			{
				$lblSvcStatus.Text = ("Ready. Checked {0} lane(s)." -f $totalRows)
			}
		})
	$svcTimer.Start()

	$formSvc.Add_FormClosing({
			try { $svcTimer.Stop(); $svcTimer.Dispose() }
			catch { }
			# Ask running checks to stop and close the pool without waiting on slow remote calls
			foreach ($entry in @($svcJobs.Values) + @($svcActionJobs.Values)) { & $stopPoolWork $entry }
			$svcJobs.Clear()
			$svcActionJobs.Clear()
			try { [void]$svcPool.BeginClose($null, $null) }
			catch { }
		})

	[void]$formSvc.ShowDialog()
}

# ===================================================================================================
#                              FUNCTION: Update_Lane_Config
# ---------------------------------------------------------------------------------------------------
# Description:
#   Loads the standard lane configuration (RUN_TAB, LNK_TAB, STO_TAB, TER_TAB rows) on the
#   selected lanes. Each table is written straight into the lane database over its SQL
#   protocol (keyed delete + insert in one transaction, the same add/replace the load file
#   does); tables that cannot go over SQL are dropped as run_load.sql / lnk_load.sql /
#   sto_load.sql / ter_load.sql in the lane's XF folder, ANSI (Windows-1252), CRLF, no BOM.
#
# Parameters:
#   - StoreNumber  [string]: store to process (required)
#
# Variables:
#   - $LoadPath: Office\Load directory (must exist)
#   - $script:LaneProtocols: per-lane protocol (TCP / Named Pipes / File / Offline)
#   - $script:ProcessedLanes: lanes processed so far
#
# Writes:
#   - lane RUN_TAB / LNK_TAB / STO_TAB / TER_TAB, or the matching *_load.sql in each XF lane folder
# ===================================================================================================

function Update_Lane_Config
{
	param (
		[Parameter(Mandatory = $true)]
		[string]$StoreNumber
	)

	Write_Log "`r`n==================== Starting Update_Lane_Config Function ====================" "blue"

	if (-not (Test-Path $LoadPath))
	{
		Write_Log "`r`nLoad Base Path not found: $LoadPath" "yellow"
		return
	}

	$selection = Show_Node_Selection_Form -StoreNumber $StoreNumber -NodeTypes "Lane"
	if (-not $selection -or -not $selection.Lanes)
	{
		Write_Log "`r`nLane processing canceled by user." "yellow"
		return
	}

	$ansiPcEncoding = [System.Text.Encoding]::GetEncoding(1252)

	# Rows per table, with the lane values filled in. One definition feeds both the SQL load
	# and the load file, so the two paths always write the same data.
	$getTableJobs = {
		param ([string]$Lane, [string]$Machine)
		@(
			@{
				Table    = 'RUN_TAB'; Alias = 'RUN'; View = 'Run_Load'; Filename = 'run_load.sql'
				Columns  = @('F1102', 'F1000', 'F1103', 'F1104', 'F1105', 'F1106', 'F1107', 'F1108', 'F1109', 'F1110', 'F1111', 'F1112', 'F1113', 'F1114', 'F1115', 'F1116', 'F1117')
				Keys     = @('F1102', 'F1000')
				Rows     = @(
					"(60,'@TER','sql=BACKUP_ALL','@TER','@DSSF',,'@DSS+001',1,'Backup programs',,0,,'',1,,,)",
					"(62,'@TER','sql=BACKUP_DEVICE','@TER',,,,1,'Backup programs on device',,0,,'',1,,,)",
					"(68,'@TER','sqi=BACKUP_RESELLER','@TER',,,,1,'Backup for reseller',,0,,'',1,,,)",
					"(70,'@TER','sql=DBASE_MAINTENANCE','@TER',,,,1,'Database maintenance',,0,,'',1,,,)",
					"(90,'@TER','sql=PURGE_ALL','@TER','@DSW-008',,'@DSW-001',0,'Purge all report data',,0,,'',7,,,)",
					"(95,'@TER','sqi=PURGE_CLIENT','@TER',,,,0,'Purge customer sensitive data',,0,,'',1,,,)",
					"(120,'@TER','sql=UPDATE_DOWNLOAD','@TER',,,,1,'Automatic update download',,0,,'',1,,,)",
					"(125,'@TER','sql=UPDATE_AUTOMATIC','@TER',,,,1,'Automatic update execution',,0,,'',1,,,)",
					"(250,'SMS','sqi=TRS_POS_BANK_EOS_PUP OUTPUT=RECEIPT','901',,,,1,'Automatic bank close',,,,,1,,,)"
				)
			}
			@{
				Table    = 'LNK_TAB'; Alias = 'LNK'; View = 'Lnk_Load'; Filename = 'lnk_load.sql'
				Columns  = @('F1000', 'F1056', 'F1057')
				Keys     = @('F1000', 'F1056', 'F1057')
				Rows     = @(
					"('$Lane','$StoreNumber','$Lane')",
					"('DSM','$StoreNumber','$Lane')",
					"('PAL','$StoreNumber','$Lane')",
					"('RAL','$StoreNumber','$Lane')",
					"('XAL','$StoreNumber','$Lane')"
				)
			}
			@{
				Table    = 'STO_TAB'; Alias = 'STO'; View = 'Sto_Load'; Filename = 'sto_load.sql'
				Columns  = @('F1000', 'F1018', 'F1180', 'F1181', 'F1182', 'F1937', 'F1965', 'F1966', 'F2691')
				Keys     = @('F1000')
				Rows     = @(
					"('$Lane','Terminal $Lane',1,1,1,,,,)",
					"('DSM','Deploy SMS',1,1,1,,,,)",
					"('PAL','Program all',0,0,1,1,,,)",
					"('RAL','Report all',1,0,0,,,,)",
					"('XAL','Exchange all',0,1,0,,,,)"
				)
			}
			@{
				Table    = 'TER_TAB'; Alias = 'TER'; View = 'Ter_Load'; Filename = 'ter_load.sql'
				Columns  = @('F1056', 'F1057', 'F1058', 'F1125', 'F1169')
				Keys     = @('F1056', 'F1057')
				Rows     = @(
					"('$StoreNumber','$Lane','Terminal $Lane','\\$Machine\storeman\office\XF$StoreNumber$Lane\','\\$Machine\storeman\office\XF${StoreNumber}901\')",
					"('$StoreNumber','901','Server','','')"
				)
			}
		)
	}

	# Load file in the SMS format (@CREATE / view / INSERT / @UPDATE_BATCH ADDRPL / DROP)
	$buildLoadFile = {
		param ($Job)
		$keyText = ($Job.Keys | ForEach-Object { "$_=:$_" }) -join ' AND '
		$lines = @(
			"@CREATE($($Job.Table),$($Job.Alias));"
			"CREATE VIEW $($Job.View) AS SELECT $($Job.Columns -join ',') FROM $($Job.Table);"
			""
			"INSERT INTO $($Job.View) VALUES"
			(($Job.Rows -join ",`r`n") + ";")
			""
			"@UPDATE_BATCH(JOB=ADDRPL,TAR=$($Job.Table),"
			"KEY=$keyText,"
			"SRC=SELECT * FROM $($Job.View));"
			""
			"DROP TABLE $($Job.View);"
		)
		($lines -join "`r`n") + "`r`n"
	}

	# One load row -> SQL literals, with the SMS macros the lane would expand resolved here
	$splitRegex = ',(?=(?:[^'']*''[^'']*'')*[^'']*$)'
	$rowToSqlValues = {
		param ([string]$Row, [string]$Lane)
		$inner = $Row.Trim()
		if ($inner.StartsWith('(') -and $inner.EndsWith(')')) { $inner = $inner.Substring(1, $inner.Length - 2) }
		$now = Get-Date
		foreach ($v in [regex]::Split($inner, $splitRegex))
		{
			$v = $v.Trim()
			if ($v -eq '') { 'NULL'; continue }
			if (-not ($v.StartsWith("'") -and $v.EndsWith("'"))) { $v; continue }
			$res = $v.Substring(1, $v.Length - 2)
			$res = $res -replace '@STORE', $StoreNumber.PadLeft(3, '0')
			$res = $res -replace '@TER', $Lane
			$res = $res -replace '@USERNAME', $env:USERNAME
			$res = $res -replace '@USER', $env:USERNAME
			$res = $res -replace '@RUN', $script:BasePath
			$res = $res -replace '@OFFICE', $script:OfficePath
			$res = $res -replace '@TIME', $now.ToString('HHmm')
			$res = $res -replace '@NOW', $now.ToString('HHmmss')
			$res = $res -replace '@DSSF', $now.ToString('yyyyMMdd')
			$res = $res -replace '@DSW-001', $now.AddDays(-1).ToString('yyyyMMdd')
			$res = $res -replace '@DSW-008', $now.AddDays(-8).ToString('yyyyMMdd')
			$res = $res -replace '@DSS\+001', $now.AddDays(1).ToString('yyyyMMdd')
			$res = $res -replace '@DSS', $now.ToString('yyyyMMdd')
			"'" + $res.Replace("'", "''") + "'"
		}
	}

	# Add/replace a table's rows by key in one transaction; returns the row count
	$loadTableViaSql = {
		param ([string]$ConnStr, $Job, [string]$Lane)
		$sb = New-Object System.Text.StringBuilder
		[void]$sb.AppendLine('SET XACT_ABORT ON; BEGIN TRAN;')
		$colList = '[' + ($Job.Columns -join '],[') + ']'
		foreach ($row in $Job.Rows)
		{
			$values = @(& $rowToSqlValues $row $Lane)
			if ($values.Count -ne $Job.Columns.Count) { throw "$($Job.Table): row has $($values.Count) values for $($Job.Columns.Count) columns: $row" }
			$where = ($Job.Keys | ForEach-Object { "[$_] = " + $values[[array]::IndexOf($Job.Columns, $_)] }) -join ' AND '
			[void]$sb.AppendLine("DELETE FROM [$($Job.Table)] WHERE $where;")
			[void]$sb.AppendLine("INSERT INTO [$($Job.Table)] ($colList) VALUES ($($values -join ', '));")
		}
		[void]$sb.AppendLine('COMMIT;')

		$conn = New-Object System.Data.SqlClient.SqlConnection($ConnStr)
		try
		{
			$conn.Open()
			$cmd = $conn.CreateCommand()
			$cmd.CommandText = $sb.ToString()
			$cmd.CommandTimeout = 30
			[void]$cmd.ExecuteNonQuery()
		}
		finally { $conn.Dispose() }
		$Job.Rows.Count
	}

	foreach ($laneNumber in @($selection.Lanes))
	{
		$laneNumber = ([string]$laneNumber).PadLeft(3, '0')
		$laneFolderPath = Join-Path -Path $OfficePath -ChildPath "XF${StoreNumber}${laneNumber}"
		if (-not (Test-Path $laneFolderPath))
		{
			Write_Log "`r`nLane #$laneNumber not found at path: $laneFolderPath" "yellow"
			continue
		}
		Write_Log "`r`nProcessing Lane #$laneNumber" "blue"

		$laneInfo = Get_All_Lanes_Database_Info -LaneNumber $laneNumber
		$MachineName = if ($laneInfo) { $laneInfo['MachineName'] } else { $script:FunctionResults['LaneNumToMachineName'][$laneNumber] }
		if (-not $MachineName) { $MachineName = "POS${laneNumber}" }

		# Lane connection for its protocol; unknown protocol tries Named Pipes (as before)
		$protocol = if ($script:LaneProtocols) { $script:LaneProtocols[$laneNumber] }
		$connStr = $null
		if ($laneInfo -and $protocol -notin @('File', 'Offline'))
		{
			$raw = if ($protocol -eq 'TCP') { $laneInfo['TcpConnStr'] } else { $laneInfo['NamedPipesConnStr'] }
			$connStr = Normalize_Sql_ConnectionString -RawConnectionString $raw
		}

		$actionSummaries = @()
		foreach ($job in (& $getTableJobs $laneNumber $MachineName))
		{
			if ($connStr)
			{
				try
				{
					$rowCount = & $loadTableViaSql $connStr $job $laneNumber
					Write_Log "Loaded $rowCount rows into $($job.Table) on lane $laneNumber over SQL." "green"
					$actionSummaries += "SQL loaded $($job.Table)"
					continue
				}
				catch
				{
					Write_Log "SQL load of $($job.Table) failed on lane $laneNumber, dropping $($job.Filename) instead: $($_.Exception.Message)" "yellow"
				}
			}

			try
			{
				$dest = Join-Path -Path $laneFolderPath -ChildPath $job.Filename
				[System.IO.File]::WriteAllText($dest, (& $buildLoadFile $job), $ansiPcEncoding)
				Set-ItemProperty -Path $dest -Name Attributes -Value ([System.IO.FileAttributes]::Normal)
				$actionSummaries += "Copied $($job.Filename)"
			}
			catch
			{
				$actionSummaries += "Failed to copy $($job.Filename)"
			}
		}

		Write_Log ("Lane ${laneNumber} (Machine: ${MachineName}): " + ($actionSummaries -join "; ")) "green"
		if ($script:ProcessedLanes -notcontains $laneNumber) { $script:ProcessedLanes += $laneNumber }
	}

	Write_Log "`r`n==================== Update_Lane_Config Function Completed ====================" "blue"
}

# ===================================================================================================
#                              FUNCTION: Add_Scale_Credentials
# ---------------------------------------------------------------------------------------------------
# Description:
#   Pre-seeds Windows credentials for every scale IP so \\<scaleIP>\c$ is accessible later.
#   For each unique scale IP (in parallel runspaces): skips if the share is already
#   accessible or TCP 445 is unreachable, otherwise tries the stored credentials in order
#   with "net use" and persists the working one with cmdkey. Silent - no logging.
#
# Parameters:
#   - ScaleCodeToIPInfo [hashtable]: scale code -> info with FullIP / IPNetwork+IPDevice (required)
#   - MaxParallel       [int]: max parallel credential tasks (default 16)
#
# Variables:
#   - $script:credBizerba / $script:credBiyerba: PSCredential objects tried in order
#   - $script:ScaleCredTasks: running task handles (kept so they are not GC'd)
#
# Writes:
#   - stored Windows credentials (cmdkey) for the working scale login
# ===================================================================================================

function Add_Scale_Credentials
{
	[CmdletBinding()]
	param (
		[Parameter(Mandatory = $true)]
		[hashtable]$ScaleCodeToIPInfo,
		[int]$MaxParallel = 16
	)

	if (-not $script:ScaleCredTasks -or -not ($script:ScaleCredTasks -is [hashtable])) { $script:ScaleCredTasks = @{ } }
	if ($MaxParallel -lt 1) { $MaxParallel = 1 }

	# Reap any completed tasks from prior calls before queuing more work.
	foreach ($k in @($script:ScaleCredTasks.Keys))
	{
		$st = $script:ScaleCredTasks[$k]
		$completed = $true
		try { $completed = (-not $st.Handle) -or $st.Handle.IsCompleted }
		catch { $completed = $true }

		if ($completed)
		{
			try { if ($st.Handle -and $st.PS) { $null = $st.PS.EndInvoke($st.Handle) } }
			catch { }
			try { if ($st.PS) { $st.PS.Dispose() } }
			catch { }
			[void]$script:ScaleCredTasks.Remove($k)
		}
	}

	# Build candidate credential list once so we don't duplicate literals in the worker.
	$credentialAttempts = @()
	$seenCreds = @{ }
	foreach ($cred in @($script:credBizerba, $script:credBiyerba))
	{
		if ($cred -is [System.Management.Automation.PSCredential])
		{
			$user = $null
			$pass = $null
			try { $user = [string]$cred.UserName }
			catch { $user = $null }
			try { $pass = [string]$cred.GetNetworkCredential().Password }
			catch { $pass = $null }

			if (-not [string]::IsNullOrWhiteSpace($user) -and -not [string]::IsNullOrEmpty($pass))
			{
				$key = "$user`n$pass"
				if (-not $seenCreds.ContainsKey($key))
				{
					$seenCreds[$key] = $true
					$credentialAttempts += [pscustomobject]@{
						User = $user
						Pass = $pass
					}
				}
			}
		}
	}

	# Safety fallback: preserve previous behavior even if the script-scoped credentials were not initialized.
	if (-not $credentialAttempts -or $credentialAttempts.Count -eq 0)
	{
		$credentialAttempts = @(
			[pscustomobject]@{ User = 'bizuser'; Pass = 'bizerba' },
			[pscustomobject]@{ User = 'bizuser'; Pass = 'biyerba' }
		)
	}

	# Collect unique, valid IPs only.
	$scaleIPs = @(
		$ScaleCodeToIPInfo.Values | ForEach-Object {
			$candidate = $null
			if ($_.FullIP) { $candidate = [string]$_.FullIP }
			elseif ($_.IPNetwork -and $_.IPDevice)
			{
				# "192.168.1" + "50" must not become "192.168.150" (TryParse reads that as 192.168.0.150)
				$candidate = ([string]$_.IPNetwork).Trim().TrimEnd('.') + '.' + ([string]$_.IPDevice).Trim()
			}

			if (-not [string]::IsNullOrWhiteSpace($candidate))
			{
				$candidate = $candidate.Trim()
				$parsedIp = $null
				if ([System.Net.IPAddress]::TryParse($candidate, [ref]$parsedIp))
				{
					$parsedIp.IPAddressToString
				}
			}
		} | Select-Object -Unique
	)

	if ($scaleIPs.Count -eq 0) { return }

	# Shared pool: reuse while active, recreate when idle and the requested width changed.
	$needNewPool = $false
	$hasOpenPool = $false
	try
	{
		if ($script:ScaleCredPool -and $script:ScaleCredPool.RunspacePoolStateInfo.State -eq 'Opened')
		{
			$hasOpenPool = $true
		}
	}
	catch
	{
		$hasOpenPool = $false
	}

	if (-not $hasOpenPool)
	{
		$needNewPool = $true
	}
	elseif (($script:ScaleCredPoolMaxParallel -ne $MaxParallel) -and $script:ScaleCredTasks.Count -eq 0)
	{
		try { $script:ScaleCredPool.Close() }
		catch { }
		try { $script:ScaleCredPool.Dispose() }
		catch { }
		$script:ScaleCredPool = $null
		$needNewPool = $true
	}

	if ($needNewPool)
	{
		$script:ScaleCredPool = [runspacefactory]::CreateRunspacePool(1, $MaxParallel)
		$script:ScaleCredPool.ApartmentState = 'MTA'
		$script:ScaleCredPool.Open()
		$script:ScaleCredPoolMaxParallel = $MaxParallel
	}

	# Auto-reap completed tasks so PS objects/pool get cleaned up even if this function is only called once.
	if (-not $script:ScaleCredReaper)
	{
		$script:ScaleCredReaper = New-Object System.Windows.Forms.Timer
		$script:ScaleCredReaper.Interval = 2000
		$script:ScaleCredReaper.Add_Tick({
				try
				{
					if ($script:ScaleCredTasks)
					{
						foreach ($key in @($script:ScaleCredTasks.Keys))
						{
							$task = $script:ScaleCredTasks[$key]
							$done = $true
							try { $done = (-not $task.Handle) -or $task.Handle.IsCompleted }
							catch { $done = $true }

							if ($done)
							{
								try { if ($task.Handle -and $task.PS) { $null = $task.PS.EndInvoke($task.Handle) } }
								catch { }
								try { if ($task.PS) { $task.PS.Dispose() } }
								catch { }
								[void]$script:ScaleCredTasks.Remove($key)
							}
						}
					}

					if ((-not $script:ScaleCredTasks) -or $script:ScaleCredTasks.Count -eq 0)
					{
						try
						{
							if ($script:ScaleCredPool)
							{
								$script:ScaleCredPool.Close()
								$script:ScaleCredPool.Dispose()
							}
						}
						catch { }
						$script:ScaleCredPool = $null
						$script:ScaleCredPoolMaxParallel = $null
						if ($script:ScaleCredReaper) { $script:ScaleCredReaper.Stop() }
					}
				}
				catch { }
			})
	}
	if ($script:ScaleCredReaper -and -not $script:ScaleCredReaper.Enabled) { $script:ScaleCredReaper.Start() }

	$worker = {
		param (
			[string]$ip,
			[object[]]$CredentialAttempts
		)

		$sharePath = "\\$ip\c$"

		# ---- quick SMB reachability (port 445) ----
		$smbOk = $false
		$client = $null
		$waitHandle = $null
		try
		{
			$client = New-Object System.Net.Sockets.TcpClient
			$ar = $client.BeginConnect($ip, 445, $null, $null)
			$waitHandle = $ar.AsyncWaitHandle
			if ($waitHandle.WaitOne(400))
			{
				try { $client.EndConnect($ar) }
				catch { }
				if ($client.Connected) { $smbOk = $true }
			}
		}
		catch { }
		finally
		{
			try { if ($waitHandle) { $waitHandle.Close() } }
			catch { }
			try { if ($client) { $client.Close() } }
			catch { }
		}

		if (-not $smbOk) { return }

		# ---- already accessible without creds? ----
		try
		{
			if (Test-Path -LiteralPath $sharePath) { return }
		}
		catch { }

		# ---- try credentials quickly via NET USE (no persistence) ----
		foreach ($c in $CredentialAttempts)
		{
			$user = $null
			$pass = $null
			try { $user = [string]$c.User }
			catch { $user = $null }
			try { $pass = [string]$c.Pass }
			catch { $pass = $null }

			if ([string]::IsNullOrWhiteSpace($user) -or [string]::IsNullOrEmpty($pass)) { continue }

			# Clear any lingering connection before each attempt so we don't inherit a stale state.
			try { $null = & net.exe use $sharePath '/delete' '/y' 2>$null }
			catch { }

			$mapRc = -1
			try
			{
				$null = & net.exe use $sharePath "/user:$user" $pass '/persistent:no' 2>$null
				$mapRc = $LASTEXITCODE
			}
			catch { $mapRc = -1 }

			if ($mapRc -eq 0)
			{
				try { $null = & net.exe use $sharePath '/delete' '/y' 2>$null }
				catch { }

				$cmdKeyRc = -1
				try
				{
					$null = & cmdkey.exe "/add:$ip" "/user:$user" "/pass:$pass" 2>$null
					$cmdKeyRc = $LASTEXITCODE
				}
				catch { $cmdKeyRc = -1 }

				if ($cmdKeyRc -eq 0)
				{
					# Best-effort verification; even if Windows does not immediately reuse the credential,
					# a successful CMDKEY add is enough to stop retrying.
					try { $null = Test-Path -LiteralPath $sharePath }
					catch { }
					return
				}
			}

			try { $null = & net.exe use $sharePath '/delete' '/y' 2>$null }
			catch { }
		}
	}

	foreach ($ip in $scaleIPs)
	{
		$existingTask = $script:ScaleCredTasks[$ip]
		if ($existingTask)
		{
			$inFlight = $false
			try { $inFlight = $existingTask.Handle -and -not $existingTask.Handle.IsCompleted }
			catch { $inFlight = $false }

			if ($inFlight) { continue }

			try { if ($existingTask.Handle -and $existingTask.PS) { $null = $existingTask.PS.EndInvoke($existingTask.Handle) } }
			catch { }
			try { if ($existingTask.PS) { $existingTask.PS.Dispose() } }
			catch { }
			[void]$script:ScaleCredTasks.Remove($ip)
		}

		$ps = [powershell]::Create()
		$null = $ps.AddScript($worker.ToString()).AddArgument($ip).AddArgument($credentialAttempts)

		$ps.RunspacePool = $script:ScaleCredPool
		try
		{
			$handle = $ps.BeginInvoke()

			# Stash to prevent GC and allow cleanup/busy tracking.
			$script:ScaleCredTasks[$ip] = @{
				PS	    = $ps
				Handle  = $handle
				Started = Get-Date
			}
		}
		catch
		{
			try { $ps.Dispose() }
			catch { }
		}
	}

	# Note: We do not wait. This function returns immediately while tasks run in background.
}

# ===================================================================================================
#                              FUNCTION: Configure_Scale_Sub-Departments
# ---------------------------------------------------------------------------------------------------
# Description:
#   WinForms dialog to configure scale sub-department tables: auto-picks the first EMPTY table
#   in order FAM_TAB > RPC_TAB > CAT_TAB (shows which was used), individual choices prompt to
#   Back Out or Overwrite (exact 7 rows), and SdpDefault is updated to OBJ.F16 / OBJ.F18 /
#   OBJ.F17 or restored to "1" (no DB change).
#
# Parameters:
#   - ServerInstance  [string]: SQL server (fallback: FunctionResults, else localhost\SQLEXPRESS)
#   - Database        [string]: database (fallback: FunctionResults, else STORESQL)
#   - ConfigFolder    [string]: ScaleComm config folder (default $script:PrimaryScaleCommRoot)
#
# Notes:
#   - Schema-aware, transactional SQL through SqlClient (no SQL module needed); PS 5.1 safe.
#   - Start and completion banners are written at all exits.
# ===================================================================================================

function Configure_Scale_Sub-Departments
{
	[CmdletBinding()]
	param (
		[string]$ServerInstance,
		[string]$Database,
		[string]$ConfigFolder = $script:PrimaryScaleCommRoot
	)

	Write_Log "`r`n==================== Starting Configure_Scale_Sub-Departments ====================`r`n" "blue"

	# -------------------- Resolve Server/DB (params > cache > defaults) --------------------
	try
	{
		if (-not $ServerInstance -or $ServerInstance.Trim() -eq '')
		{
			if ($script:FunctionResults -and $script:FunctionResults.ContainsKey('DBSERVER') -and $script:FunctionResults['DBSERVER'])
			{
				$ServerInstance = $script:FunctionResults['DBSERVER']
			}
			else
			{
				$ServerInstance = 'localhost\SQLEXPRESS'
			}
		}
		if (-not $Database -or $Database.Trim() -eq '')
		{
			if ($script:FunctionResults -and $script:FunctionResults.ContainsKey('DBNAME') -and $script:FunctionResults['DBNAME'])
			{
				$Database = $script:FunctionResults['DBNAME']
			}
			else
			{
				$Database = 'STORESQL'
			}
		}
		Write_Log ("Target SQL: " + $ServerInstance + " | DB: " + $Database) "cyan"
	}
	catch
	{
		Write_Log ("Failed resolving server/database: " + $_.Exception.Message) "red"
		Write_Log "`r`n==================== Configure_Scale_Sub-Departments Completed ====================`r`n" "blue"
		return
	}

	# -------------------- SQL through SqlClient (no SQL module needed) --------------------
	# Windows auth, like the Invoke-Sqlcmd -ServerInstance calls this replaces
	$sqlConnStr = Normalize_Sql_ConnectionString -Server $ServerInstance -Database $Database

	# First row as an object; DBNull -> $null (a DBNull is truthy and [int64]DBNull throws,
	# so a missing table used to look present and then crash the row count)
	$runSqlRow = {
		param ([string]$Query)
		$cn = New-Object System.Data.SqlClient.SqlConnection $sqlConnStr
		try
		{
			$cn.Open()
			$cmd = $cn.CreateCommand()
			$cmd.CommandText = $Query
			$cmd.CommandTimeout = 60
			$rdr = $cmd.ExecuteReader()
			$row = $null
			if ($rdr.Read())
			{
				$row = [ordered]@{ }
				for ($i = 0; $i -lt $rdr.FieldCount; $i++) { $row[$rdr.GetName($i)] = if ($rdr.IsDBNull($i)) { $null } else { $rdr.GetValue($i) } }
				$row = [pscustomobject]$row
			}
			$rdr.Close()
			$row
		}
		finally { $cn.Dispose() }
	}

	$runSqlNonQuery = {
		param ([string]$Query, [int]$Timeout = 120)
		$cn = New-Object System.Data.SqlClient.SqlConnection $sqlConnStr
		try
		{
			$cn.Open()
			$cmd = $cn.CreateCommand()
			$cmd.CommandText = $Query
			$cmd.CommandTimeout = $Timeout
			[void]$cmd.ExecuteNonQuery()
		}
		finally { $cn.Dispose() }
	}
	# ==============================
	# SQL templates (literal strings)
	# ==============================
	$Tsql_Check_For = @"
SET NOCOUNT ON;
DECLARE @Schema sysname = NULL, @Cnt bigint = NULL, @Tbl sysname = N'%TABLE%';
SELECT TOP (1) @Schema = s.name
FROM sys.tables AS t
JOIN sys.schemas AS s ON s.schema_id = t.schema_id
WHERE t.name = @Tbl;
IF @Schema IS NOT NULL
BEGIN
    DECLARE @sql nvarchar(max) =
        N'SELECT @c = COUNT_BIG(1) FROM ' + QUOTENAME(@Schema) + N'.' + QUOTENAME(@Tbl) + N';';
    EXEC sp_executesql @sql, N'@c bigint OUTPUT', @c = @Cnt OUTPUT;
END
SELECT @Schema AS SchemaName, @Cnt AS RowCnt;
"@

	$Tsql_Merge_FAM_Keep = @"
SET NOCOUNT ON; SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRAN;
WITH src AS (SELECT vID, vName FROM (VALUES
 (1,N'Produce'),(2,N'Deli'),(3,N'Meat'),(4,N'Seafood'),(5,N'Cafeteria'),(6,N'Hot Foods'),(7,N'Bakery')
) AS x(vID,vName))
MERGE /*+ HOLDLOCK */ %SCHEMA%.FAM_TAB AS T
USING src S ON T.F16 = S.vID
WHEN MATCHED THEN UPDATE SET
 T.F49=NULL, T.F1040=S.vName, T.F1123=NULL, T.F1124=NULL, T.F1168=NULL, T.F1965=NULL, T.F1966=NULL, T.F1967=NULL
WHEN NOT MATCHED BY TARGET THEN
 INSERT (F16,F49,F1040,F1123,F1124,F1168,F1965,F1966,F1967)
 VALUES (S.vID,NULL,S.vName,NULL,NULL,NULL,NULL,NULL,NULL);
COMMIT;
END TRY
BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
"@

	$Tsql_Merge_FAM_Overwrite = @"
