WHEN MATCHED THEN UPDATE SET
 T.F49=NULL, T.F1024=S.vName, T.F1123=NULL, T.F1124=NULL, T.F1168=NULL, T.F1965=NULL, T.F1966=NULL, T.F1967=NULL
WHEN NOT MATCHED BY TARGET THEN
