# Startup summary (v2.6.8+): one calm, scannable overview of the environment - which storeman
# source is in use and what that means - written to the FILE LOG when the window first shows
# (the log box opens clean; the banner badge and status bar show the mode on screen).
$form.add_Shown({
		try
		{
			$rule = '--------------------------------------------------'
			$modeTag = if ($script:StoremanKeyStale) { '[ KEY  ]' } elseif ($script:IsTestEnvironment) { '[ TEST ]' } else { '[ LIVE ]' }

			$storeNum = ''
			$storeName = ''
			$smsVer = ''
			try
			{
				if ($script:FunctionResults)
				{
					$storeNum  = [string]$script:FunctionResults['StoreNumber']
					$storeName = [string]$script:FunctionResults['StoreName']
					$smsVer    = [string]$script:FunctionResults['SMSVersionFull']
				}
			}
			catch { }

			Write_Log $rule -FileOnly -IncludeTimestamp:$false -Raw
			Write_Log (" TBS MAINTENANCE SCRIPT   v{0} ({1})   {2}" -f $VersionNumber, $VersionDate, $modeTag) -FileOnly -IncludeTimestamp:$false -Raw
			Write_Log $rule -FileOnly -IncludeTimestamp:$false -Raw

			if ($script:StoremanKeyStale)
			{
				$staleKeyDate = if ($script:StoremanKeyDate) { $script:StoremanKeyDate.ToString('MM/dd/yyyy') } else { 'unknown' }
				$storeDataUsable = $false
				try { $storeDataUsable = Test-Path (Join-Path $BasePath 'Office\Dbs') } catch { }
				Write_Log ("[WARN] KEY EXPIRED - storeman key is older than 14 days (KeyValidDate: {0}). Re-key required." -f $staleKeyDate) "orange" -FileOnly -IncludeTimestamp:$false -Raw
				if ($storeDataUsable)
				{
					Write_Log "       Store data (storeman folder + store database) IS available and in use: $BasePath" "orange" -FileOnly -IncludeTimestamp:$false -Raw
					Write_Log "       Only the key needs refreshing - every other task works normally." "orange" -FileOnly -IncludeTimestamp:$false -Raw
				}
				else
				{
					Write_Log "       Tasks that need the storeman folder or the store database are unavailable." "orange" -FileOnly -IncludeTimestamp:$false -Raw
					Write_Log ("       To enable them: run on a store PC, or create the local test folder ({0}\Office\Dbs)." -f $BasePath) -FileOnly -IncludeTimestamp:$false -Raw
				}
			}
			elseif ($script:IsTestEnvironment)
			{
				Write_Log "[WARN] TEST ENVIRONMENT - $($script:StoremanSourceReason)" "orange" -FileOnly -IncludeTimestamp:$false -Raw
				Write_Log "       Tasks that need the storeman folder or the store database are unavailable." -FileOnly -IncludeTimestamp:$false -Raw
				Write_Log "       Everything else works normally." -FileOnly -IncludeTimestamp:$false -Raw
				Write_Log ("       To enable them: run on a store PC, or create the local test folder ({0}\Office\Dbs)." -f $BasePath) -FileOnly -IncludeTimestamp:$false -Raw
			}
			else
			{
				Write_Log "[ OK ] PRODUCTION - storeman share 'storeman' in use" "green" -FileOnly -IncludeTimestamp:$false -Raw
				Write_Log "       Path: $BasePath" -FileOnly -IncludeTimestamp:$false -Raw
				if ($storeNum -and $storeNum -ne 'N/A')
				{
					$storeLine = "       Store: $storeNum"
					if ($storeName -and $storeName -ne 'N/A') { $storeLine += " `"$storeName`"" }
					if ($smsVer -and $smsVer -ne 'N/A') { $storeLine += "   (SMS $smsVer)" }
					Write_Log $storeLine -FileOnly -IncludeTimestamp:$false -Raw
				}
			}

			Write_Log $rule -FileOnly -IncludeTimestamp:$false -Raw
		}
		catch { }
	})

$toolTip.SetToolTip($logBox, "Log output. Right-click to clear.")
$logBox.Add_MouseUp({
		param ($sender, $eventArgs)
		if ($eventArgs.Button -eq [System.Windows.Forms.MouseButtons]::Right)
		{
			$logBox.Clear()
			if (Get-Command Write_Log -ErrorAction SilentlyContinue) { Write_Log "Log Cleared" }
		}
	})

# Layout that also positions the log frame + log box
$layoutLogArea = {
	if (-not $form -or $form.IsDisposed) { return }

	try
	{
		# Width aligned to top strip card
		$rowW = [math]::Max(200, $form.ClientSize.Width - (2 * $padSide))

		# Log top starts just below the top strip card
		$logTop = $topStripCard.Bottom + $gapCards

		# Bottom bound uses status strip height
		$bottomReserve = 0
		if ($statusStrip -and -not $statusStrip.IsDisposed) { $bottomReserve = $statusStrip.Height }

		# Compute available height for the log area
		$availH = $form.ClientSize.Height - $logTop - $bottomReserve - $gapCards
		$logH = [math]::Max($minLogH, $availH)

		# Frame
		$logFrame.Left = $padSide
		$logFrame.Top = $logTop
		$logFrame.Width = $rowW
		$logFrame.Height = $logH

		# Log box inset (padding inside frame) - account for header
		$logBox.Left = $logFrame.Left + $logInnerPad
		$logBox.Top = 28 + $logInnerPad # Account for header height
		$logBox.Width = [math]::Max(50, $logFrame.Width - (2 * $logInnerPad))
		$logBox.Height = [math]::Max(50, $logFrame.Height - 28 - (2 * $logInnerPad))

		# Keep top strip aligned
		& $layoutTopStrip
	}
	catch { }
}

# Run once + re-run on resize
& $layoutLogArea
$form.add_Resize({ & $layoutLogArea })

# ------------------------------------------------------------------------------------------------
# --- Busy scanner (UI thread) -------------------------------------------------------------
#   (kept logic; additionally updates status strip for a modern "app" feel)
# ------------------------------------------------------------------------------------------------
$BusyTimer = New-Object System.Windows.Forms.Timer
$BusyTimer.Interval = 1500
$BusyTimer.add_Tick({
		# Reset busy flags each tick
		$script:IsBusy = $false
		$script:BusyReason = $null

		# 1) Lane protocol runspace tasks?
		try
		{
			if ($script:LaneProtocolJobs)
			{
				foreach ($kv in @($script:LaneProtocolJobs.GetEnumerator()))
				{
					$st = $kv.Value
					if ($st -and $st.Handle -and -not $st.Handle.IsCompleted)
					{
						$script:IsBusy = $true
						$script:BusyReason = "LaneProtocol runspace ($($kv.Key))"
						break
					}
				}
			}
		}
		catch { }

		# 2) Lane protocol pool in-flight work?
		if (-not $script:IsBusy)
		{
			try
			{
				if ($script:LaneProtocolPool)
				{
					$avail = $script:LaneProtocolPool.GetAvailableRunspaces()
					$max = $script:LaneProtocolPool.MaxRunspaces
					if ($avail -lt $max)
					{
						$script:IsBusy = $true
						$script:BusyReason = "LaneProtocol pool busy ($avail/$max available)"
					}
				}
			}
			catch { }
		}

		# 3) Scale credential helper tasks?
		if (-not $script:IsBusy)
		{
			try
			{
				if ($script:ScaleCredTasks)
				{
					foreach ($k in @($script:ScaleCredTasks.Keys))
					{
						$st = $script:ScaleCredTasks[$k]
						if ($st -and $st.Handle -and -not $st.Handle.IsCompleted)
						{
							$script:IsBusy = $true
							$script:BusyReason = "ScaleCred task ($k)"
							break
						}
					}
				}
			}
			catch { }
		}

		# 4) Known launch background jobs?
		if (-not $script:IsBusy)
		{
			try
			{
				if (
					$script:VncExportTask -and
					$script:VncExportTask.Job -and
					$script:VncExportTask.Job.State -in @('Running', 'NotStarted')
				)
				{
					$script:IsBusy = $true
					$script:BusyReason = "Exporting VNC files"
				}
			}
			catch { }
		}

		if (-not $script:IsBusy)
		{
			try
			{
				if (
					$script:RemoteMachineInfoTask -and
					$script:RemoteMachineInfoTask.Job -and
					$script:RemoteMachineInfoTask.Job.State -in @('Running', 'NotStarted')
				)
				{
					$script:IsBusy = $true
					$script:BusyReason = "Collecting remote machine info"
				}
			}
			catch { }
		}

		if (-not $script:IsBusy)
		{
			try
			{
				# (-Name and -State cannot be combined on Get-Job - filter the state instead)
				$insertTestJob = Get-Job | Where-Object { $_.Name -eq 'InsertTestItemJob' } | Where-Object { $_.State -eq 'Running' } | Select-Object -First 1
				if ($insertTestJob)
				{
					$script:IsBusy = $true
					$script:BusyReason = "Loading test item"
				}
			}
			catch { }
		}

		if (-not $script:IsBusy)
		{
			try
			{
				$laneSqlEnableJob = $null
				if ($script:LaneSqlProtocolEnableJobs)
				{
					$laneSqlEnableJob = @($script:LaneSqlProtocolEnableJobs.GetEnumerator() | Where-Object {
						$_.Value -and $_.Value.Process -and (-not $_.Value.Process.HasExited)
					} | Select-Object -First 1)
				}
				if ($laneSqlEnableJob)
				{
					$script:IsBusy = $true
					$laneBusyText = [string]$laneSqlEnableJob.Key
					$script:BusyReason = "Scheduling SQL enable ($laneBusyText)"
				}
			}
			catch { }
		}

		# 5) Any other background jobs (EXCEPT ignored names/patterns)
		if (-not $script:IsBusy)
		{
			try
			{
				$jobs = Get-Job -State Running -ErrorAction SilentlyContinue | Where-Object {
					$nm = $_.Name
					$ignore = $false
					foreach ($pat in $script:IdleIgnoreJobNames)
					{
						if ($nm -like $pat) { $ignore = $true; break }
					}
					-not $ignore
				}

				if ($jobs)
				{
					$script:IsBusy = $true
					$script:BusyReason = "Job: $($jobs[0].Name)"
				}
			}
			catch { }
		}

		# ---- Status strip update (modern) ----
		try
		{
			# Use the status helper function
			if (-not [string]::IsNullOrWhiteSpace($script:StartupWarmupStatus))
			{
				& $updateStatusBar -Status "Warmup" -StatusColor $uiStatusInfo -Operation $script:StartupWarmupStatus
			}
			elseif ($script:IsBusy)
			{
				& $updateStatusBar -Status "Running" -StatusColor $uiStatusWarning -Operation $script:BusyReason -BusyInfo "Working..."
			}
			else
			{
				& $updateStatusBar -Status "Ready" -StatusColor $uiStatusSuccess -Operation "Waiting for action..."
			}
		}
		catch { }
	})
$BusyTimer.Start()

# ------------------------------------------------------------------------------------------------
# --- Idle watchdog (UI thread) ------------------------------------------------------------
#   (kept logic; additionally shows countdown in status strip)
# ------------------------------------------------------------------------------------------------
$script:IdleTimer = New-Object System.Windows.Forms.Timer
$script:IdleTimer.Interval = 30000 # 30s
$script:IdleTimer.add_Tick({
		if ($script:IdleMinutesAllowed -le 0)
		{
			try { $stIdle.Text = "" }
			catch { }
			return
		}

		try
		{
			$minsIdle = (New-TimeSpan -Start $script:LastActivity -End (Get-Date)).TotalMinutes
			$hardCloseReady = ($script:IdleHardCloseAfterMinutes -gt 0 -and $minsIdle -ge $script:IdleHardCloseAfterMinutes)

			# Status strip idle countdown
			try
			{
				$left = [math]::Max(0, $script:IdleMinutesAllowed - $minsIdle)
				$stIdle.Text = ("Idle close in: {0:n1} min" -f $left)
			}
			catch { }

			if ($minsIdle -ge $script:IdleMinutesAllowed)
			{
				if (-not $script:IsBusy -or $hardCloseReady)
				{
					try
					{
						if ($hardCloseReady -and $script:IsBusy -and $script:BusyReason)
						{
							Write_Log "Idle $([math]::Round($minsIdle, 1)) min; overriding busy ($script:BusyReason) due to hard-close window." "yellow"
						}
						else
						{
							Write_Log "Idle for $([math]::Round($minsIdle, 1)) minute(s) - closing." "yellow"
						}
					}
					catch { }

					if ($form -and -not $form.IsDisposed) { $form.Close() }
				}
				else
				{
					# Busy detected at idle threshold; log once then reset window
					try
					{
						if ($script:BusyReason)
						{
							Write_Log "Idle $([math]::Round($minsIdle, 1)) min, but busy: $script:BusyReason (not closing)." "gray"
						}
						else
						{
							Write_Log "Idle $([math]::Round($minsIdle, 1)) min, but busy: <unknown> (not closing)." "gray"
						}
					}
					catch { }

					# Reset so we don't spam + so user gets another full idle window
					$script:LastActivity = Get-Date
				}
			}
		}
		catch { }
	})
$script:IdleTimer.Start()

# ------------------------------------------------------------------------------------------------
# --- Activity hooks (form + all existing child controls) ---------------------------------
#   (kept logic; plus hooks future-added controls to avoid "dead" activity areas)
# ------------------------------------------------------------------------------------------------
try { $form.add_KeyDown({ $script:LastActivity = Get-Date }) }
catch { }
try { $form.add_MouseMove({ $script:LastActivity = Get-Date }) }
catch { }

# Hook existing controls (your original stack approach)
try
{
	$stack = New-Object System.Collections.Stack
	$stack.Push($form)

	while ($stack.Count -gt 0)
	{
		$parent = [System.Windows.Forms.Control]$stack.Pop()
		foreach ($ctrl in @($parent.Controls))
		{
			try { $ctrl.add_KeyDown({ $script:LastActivity = Get-Date }) }
			catch { }
			try { $ctrl.add_Click({ $script:LastActivity = Get-Date }) }
			catch { }
			try { $ctrl.add_MouseMove({ $script:LastActivity = Get-Date }) }
			catch { }
			if ($ctrl -and $ctrl.HasChildren) { $stack.Push($ctrl) }
		}
	}
}
catch { }

# NEW: Hook controls added later (so new controls also reset idle timer)
try
{
	$form.add_ControlAdded({
			param ($s,
				$e)
			try
			{
				$c = $e.Control
				if (-not $c) { return }

				$stack2 = New-Object System.Collections.Stack
				$stack2.Push($c)

				while ($stack2.Count -gt 0)
				{
					$p = [System.Windows.Forms.Control]$stack2.Pop()
					try { $p.add_KeyDown({ $script:LastActivity = Get-Date }) }
					catch { }
					try { $p.add_Click({ $script:LastActivity = Get-Date }) }
					catch { }
					try { $p.add_MouseMove({ $script:LastActivity = Get-Date }) }
					catch { }
					if ($p.HasChildren) { foreach ($cc in @($p.Controls)) { $stack2.Push($cc) } }
				}
			}
			catch { }
		})
}
catch { }

# ------------------------------------------------------------------------------------------------
# ========================= Protocol Table Popup (kept; slightly modern styling) ==================
# ------------------------------------------------------------------------------------------------
$rowHeight = 19
$rowCount = 25
$gridHeight = ($rowCount * $rowHeight) + 28

if (-not $script:LaneDbSizeMap) { $script:LaneDbSizeMap = @{ } }
if (-not $script:LaneDbSizeJobs) { $script:LaneDbSizeJobs = @{ } }
if (-not $script:LaneDbSizeRefreshSeconds -or $script:LaneDbSizeRefreshSeconds -lt 5) { $script:LaneDbSizeRefreshSeconds = 5 }
if (-not $script:LaneDbSizePool)
{
	$minThreads = 1
	$maxThreads = [Math]::Max(8, [Environment]::ProcessorCount * 2)
	$iss = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
	$pool = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspacePool($minThreads, $maxThreads, $iss, $Host)
	try { $pool.ApartmentState = 'MTA' }
	catch { }
	$pool.Open()
	$script:LaneDbSizePool = $pool
}
if (-not $script:LaneDbSizeWorker)
{
	$script:LaneDbSizeWorker = @'
param(
	[string]$lane,
	[string]$protocol,
	[string]$connectionString,
	[string]$machineName,
	[string]$dbName,
	[string]$smsStartIniPath
)

Add-Type -AssemblyName System.Data 2>$null
Add-Type -AssemblyName System 2>$null

$result = [ordered]@{
	Lane      = $lane
	DataText  = 'N/A'
	LogText   = 'N/A'
	Status    = 'Unavailable'
	OpenPath  = $null
	UpdatedAt = [DateTime]::Now
}

$machineNameNorm = [string]$machineName
$isLocalMachine = $false
try
{
	if ([string]::IsNullOrWhiteSpace($machineNameNorm) -or $machineNameNorm -match '^(?i)(localhost|\.|\(local\))$' -or $machineNameNorm -ieq $env:COMPUTERNAME)
	{
		$isLocalMachine = $true
	}
}
catch { }

if (-not $isLocalMachine)
{
	$reachable = $false
	try
	{
		$ping = New-Object System.Net.NetworkInformation.Ping
		$reply = $ping.Send($machineNameNorm, 700)
		if ($reply -and $reply.Status -eq [System.Net.NetworkInformation.IPStatus]::Success) { $reachable = $true }
	}
	catch { }

	if (-not $reachable)
	{
		$tcp = $null
		$async = $null
		try
		{
			$tcp = New-Object System.Net.Sockets.TcpClient
			$async = $tcp.BeginConnect($machineNameNorm, 445, $null, $null)
			if ($async.AsyncWaitHandle.WaitOne(700, $false) -and $tcp.Connected)
			{
				try { $tcp.EndConnect($async) } catch { }
				$reachable = $true
			}
		}
		catch { }
		finally
		{
			try { if ($async) { $async.AsyncWaitHandle.Close() } } catch { }
			try { if ($tcp) { $tcp.Close() } } catch { }
		}
	}

	if (-not $reachable)
	{
		$result.DataText = 'Offline'
		$result.LogText = 'Offline'
		$result.Status = 'Offline'
		[pscustomobject]$result
		return
	}
}

if ($protocol -eq 'File')
{
	if (-not [string]::IsNullOrWhiteSpace($machineName) -and -not [string]::IsNullOrWhiteSpace($dbName))
	{
		$candidateDirs = New-Object System.Collections.ArrayList

		foreach ($driveShare in @('c$', 'd$', 'e$', 'f$'))
		{
			foreach ($sqlBaseRoot in @(
				("\\{0}\{1}\Program Files\Microsoft SQL Server" -f $machineName, $driveShare),
				("\\{0}\{1}\Program Files (x86)\Microsoft SQL Server" -f $machineName, $driveShare)
			))
			{
				if (-not (Test-Path -LiteralPath $sqlBaseRoot)) { continue }

				try
				{
					$instanceDirs = Get-ChildItem -LiteralPath $sqlBaseRoot -Directory -ErrorAction Stop
					foreach ($instanceDir in $instanceDirs)
					{
						foreach ($dataDir in @(
							([System.IO.Path]::Combine($instanceDir.FullName, 'MSSQL', 'DATA')),
							([System.IO.Path]::Combine($instanceDir.FullName, 'MSSQL', 'Data'))
						))
						{
							if (Test-Path -LiteralPath $dataDir)
							{
								[void]$candidateDirs.Add($dataDir)
							}
						}
					}
				}
				catch { }
			}
		}

		$candidateDirs = @($candidateDirs | Select-Object -Unique)

		$dataFile = $null
		$logFile = $null

		foreach ($dir in $candidateDirs)
		{
			if ([string]::IsNullOrWhiteSpace($dir)) { continue }
			if (-not (Test-Path -LiteralPath $dir)) { continue }

			$dataExactPath = [System.IO.Path]::Combine($dir, ($dbName + '.mdf'))
			if ((-not $dataFile) -and (Test-Path -LiteralPath $dataExactPath))
			{
				try { $dataFile = Get-Item -LiteralPath $dataExactPath -ErrorAction Stop }
				catch { $dataFile = $null }
			}

			if (-not $dataFile)
			{
				try
				{
					$dataFile = Get-ChildItem -LiteralPath $dir -Filter ($dbName + '*.mdf') -File -ErrorAction Stop |
						Sort-Object Length -Descending |
						Select-Object -First 1
				}
				catch { $dataFile = $null }
			}

			foreach ($logName in @(($dbName + '_Log.ldf'), ($dbName + '_log.ldf'), ($dbName + '.ldf')))
			{
				if ($logFile) { break }
				$logExactPath = [System.IO.Path]::Combine($dir, $logName)
				if (Test-Path -LiteralPath $logExactPath)
				{
					try { $logFile = Get-Item -LiteralPath $logExactPath -ErrorAction Stop }
					catch { $logFile = $null }
				}
			}

			if (-not $logFile)
			{
				try
				{
					$logFile = Get-ChildItem -LiteralPath $dir -Filter ($dbName + '*.ldf') -File -ErrorAction Stop |
						Sort-Object Length -Descending |
						Select-Object -First 1
				}
				catch { $logFile = $null }
			}

			if ($dataFile -or $logFile) { break }
		}

		if ($dataFile)
		{
			$dataMb = [double]($dataFile.Length / 1MB)
			if ($dataMb -ge 1024) { $result.DataText = ('{0:N2} GB' -f ($dataMb / 1024.0)) }
			else { $result.DataText = ('{0:N0} MB' -f $dataMb) }
		}

		if ($logFile)
		{
			$logMb = [double]($logFile.Length / 1MB)
			if ($logMb -ge 1024) { $result.LogText = ('{0:N2} GB' -f ($logMb / 1024.0)) }
			else { $result.LogText = ('{0:N0} MB' -f $logMb) }
		}

		if ($dataFile)
		{
			try { $result.OpenPath = [string]$dataFile.DirectoryName } catch { }
		}
		elseif ($logFile)
		{
			try { $result.OpenPath = [string]$logFile.DirectoryName } catch { }
		}

		if ($dataFile -or $logFile) { $result.Status = 'FileReady' }
		else { $result.Status = 'FileMissing' }
	}
	else
	{
		$result.Status = 'FileMissing'
	}
}

if (($result.Status -ne 'Ready') -and ($result.Status -ne 'FileReady') -and
	(-not [string]::IsNullOrWhiteSpace($smsStartIniPath)) -and (Test-Path -LiteralPath $smsStartIniPath))
{
	try
	{
		$iniLines = Get-Content -LiteralPath $smsStartIniPath -ErrorAction Stop
		$inDatabaseSection = $false
		$dbSizeMb = $null
		$dbLogSizeMb = $null

		foreach ($line in $iniLines)
		{
			$text = [string]$line
			if ($text -match '^\s*\[(.+?)\]\s*$')
			{
				$inDatabaseSection = ($matches[1] -eq 'Database')
				continue
			}
			if (-not $inDatabaseSection) { continue }
			if ($text -match '^\s*DBSIZE\s*=\s*([0-9]+(?:\.[0-9]+)?)\s*$') { $dbSizeMb = [double]$matches[1]; continue }
			if ($text -match '^\s*DBLOGSIZE\s*=\s*([0-9]+(?:\.[0-9]+)?)\s*$') { $dbLogSizeMb = [double]$matches[1]; continue }
		}

		if ($null -ne $dbSizeMb)
		{
			if ($dbSizeMb -ge 1024) { $result.DataText = ('{0:N2} GB' -f ($dbSizeMb / 1024.0)) }
			else { $result.DataText = ('{0:N0} MB' -f $dbSizeMb) }
		}

		if ($null -ne $dbLogSizeMb)
		{
			if ($dbLogSizeMb -ge 1024) { $result.LogText = ('{0:N2} GB' -f ($dbLogSizeMb / 1024.0)) }
			else { $result.LogText = ('{0:N0} MB' -f $dbLogSizeMb) }
		}

		if (($null -ne $dbSizeMb) -or ($null -ne $dbLogSizeMb))
		{
			$result.Status = 'SmsStartFallback'
		}
	}
	catch { }
}

if ($protocol -eq 'File')
{
	[pscustomobject]$result
	return
}

if ([string]::IsNullOrWhiteSpace($connectionString))
{
	[pscustomobject]$result
	return
}

$cn = $null
try
{
	$cn = New-Object System.Data.SqlClient.SqlConnection $connectionString
	$cn.Open()

	$cmd = $cn.CreateCommand()
	$cmd.CommandTimeout = 5
	$cmd.CommandText = @"
SET NOCOUNT ON;
SELECT
	type_desc,
	size,
	physical_name
FROM sys.database_files;
"@

	$rdr = $cmd.ExecuteReader()
	$dataMb = 0.0
	$logMb = 0.0
	$dataPhysicalPath = $null
	$logPhysicalPath = $null
	while ($rdr.Read())
	{
		$typeDesc = $null
		$sizePages = $null
		$physicalName = $null
		if (-not $rdr.IsDBNull(0)) { $typeDesc = [string]$rdr.GetValue(0) }
		if (-not $rdr.IsDBNull(1)) { $sizePages = [double]$rdr.GetValue(1) }
		if (-not $rdr.IsDBNull(2)) { $physicalName = [string]$rdr.GetValue(2) }

		if ($typeDesc -eq 'ROWS')
		{
			if ($null -ne $sizePages) { $dataMb += ($sizePages * 8.0 / 1024.0) }
			if (-not $dataPhysicalPath -and -not [string]::IsNullOrWhiteSpace($physicalName)) { $dataPhysicalPath = $physicalName }
		}
		elseif ($typeDesc -eq 'LOG')
		{
			if ($null -ne $sizePages) { $logMb += ($sizePages * 8.0 / 1024.0) }
			if (-not $logPhysicalPath -and -not [string]::IsNullOrWhiteSpace($physicalName)) { $logPhysicalPath = $physicalName }
		}
	}

	if ($dataMb -gt 0)
	{
		if ($dataMb -ge 1024) { $result.DataText = ('{0:N2} GB' -f ($dataMb / 1024.0)) }
		else { $result.DataText = ('{0:N0} MB' -f $dataMb) }
	}

	if ($logMb -gt 0)
	{
		if ($logMb -ge 1024) { $result.LogText = ('{0:N2} GB' -f ($logMb / 1024.0)) }
		else { $result.LogText = ('{0:N0} MB' -f $logMb) }
	}

	$rawOpenPath = $null
	if (-not [string]::IsNullOrWhiteSpace($dataPhysicalPath))
	{
		try { $rawOpenPath = [System.IO.Path]::GetDirectoryName($dataPhysicalPath) } catch { $rawOpenPath = $null }
	}
	elseif (-not [string]::IsNullOrWhiteSpace($logPhysicalPath))
	{
		try { $rawOpenPath = [System.IO.Path]::GetDirectoryName($logPhysicalPath) } catch { $rawOpenPath = $null }
	}

	if (-not [string]::IsNullOrWhiteSpace($rawOpenPath))
	{
		$machineNameNorm = [string]$machineName
		if ([string]::IsNullOrWhiteSpace($machineNameNorm) -or $machineNameNorm -match '^(?i)(localhost|\.|\(local\))$' -or $machineNameNorm -ieq $env:COMPUTERNAME)
		{
			$result.OpenPath = $rawOpenPath
		}
		elseif ($rawOpenPath -match '^(?<drive>[A-Za-z]):\\(?<rest>.*)$')
		{
			$driveShare = ($matches['drive'].ToLowerInvariant() + '$')
			$pathRest = $matches['rest']
			if ([string]::IsNullOrWhiteSpace($pathRest)) { $result.OpenPath = ('\\{0}\{1}' -f $machineNameNorm, $driveShare) }
			else { $result.OpenPath = ('\\{0}\{1}\{2}' -f $machineNameNorm, $driveShare, $pathRest) }
		}
		else
		{
			$result.OpenPath = $rawOpenPath
		}
	}

	if (($dataMb -gt 0) -or ($logMb -gt 0) -or (-not [string]::IsNullOrWhiteSpace([string]$result.OpenPath)))
	{
		$result.Status = 'Ready'
	}
	try { $rdr.Close() } catch { }
	try { $rdr.Dispose() } catch { }
}
catch
{
	$result.DataText = 'N/A'
	$result.LogText = 'N/A'
	$result.Status = 'Error'
}
finally
{
	try { if ($cn) { $cn.Close() } } catch { }
	try { if ($cn) { $cn.Dispose() } } catch { }
}

if (($result.Status -ne 'Ready') -and
	(-not [string]::IsNullOrWhiteSpace($smsStartIniPath)) -and (Test-Path -LiteralPath $smsStartIniPath))
{
	try
	{
		$iniLines = Get-Content -LiteralPath $smsStartIniPath -ErrorAction Stop
		$inDatabaseSection = $false
		$dbSizeMb = $null
		$dbLogSizeMb = $null

		foreach ($line in $iniLines)
		{
			$text = [string]$line
			if ($text -match '^\s*\[(.+?)\]\s*$')
			{
				$inDatabaseSection = ($matches[1] -eq 'Database')
				continue
			}
			if (-not $inDatabaseSection) { continue }
			if ($text -match '^\s*DBSIZE\s*=\s*([0-9]+(?:\.[0-9]+)?)\s*$') { $dbSizeMb = [double]$matches[1]; continue }
			if ($text -match '^\s*DBLOGSIZE\s*=\s*([0-9]+(?:\.[0-9]+)?)\s*$') { $dbLogSizeMb = [double]$matches[1]; continue }
		}

		if ($null -ne $dbSizeMb)
		{
			if ($dbSizeMb -ge 1024) { $result.DataText = ('{0:N2} GB' -f ($dbSizeMb / 1024.0)) }
			else { $result.DataText = ('{0:N0} MB' -f $dbSizeMb) }
		}

		if ($null -ne $dbLogSizeMb)
		{
			if ($dbLogSizeMb -ge 1024) { $result.LogText = ('{0:N2} GB' -f ($dbLogSizeMb / 1024.0)) }
			else { $result.LogText = ('{0:N0} MB' -f $dbLogSizeMb) }
		}

		if (($null -ne $dbSizeMb) -or ($null -ne $dbLogSizeMb))
		{
			$result.Status = 'SmsStartFallback'
		}
	}
	catch { }
}

[pscustomobject]$result
'@
}

if (-not $global:ProtocolForm)
{
	$global:ProtocolForm = New-Object System.Windows.Forms.Form
	$global:ProtocolForm.Text = "Lane Protocols / DB Sizes"
	$global:ProtocolForm.Size = New-Object System.Drawing.Size(500, 520)
	$global:ProtocolForm.StartPosition = "CenterScreen"
	$global:ProtocolForm.Topmost = $true
	$global:ProtocolForm.BackColor = $uiBg
	$global:ProtocolForm.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
	if ($script:TbsAppIcon) { try { $global:ProtocolForm.Icon = $script:TbsAppIcon } catch { } }

	# No minimize/maximize
	$global:ProtocolForm.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
	$global:ProtocolForm.MaximizeBox = $false
	$global:ProtocolForm.MinimizeBox = $false

	# Hide when focus leaves
	$global:ProtocolForm.add_Deactivate({ $global:ProtocolForm.Hide() })

	$global:ProtocolGrid = New-Object System.Windows.Forms.DataGridView
	$global:ProtocolGrid.Location = New-Object System.Drawing.Point(12, 12)
	$global:ProtocolGrid.Size = New-Object System.Drawing.Size(460, 396)
	$global:ProtocolGrid.RowTemplate.Height = 22
	$global:ProtocolGrid.ColumnCount = 4
	$global:ProtocolGrid.Columns[0].Name = "Lane"
	$global:ProtocolGrid.Columns[1].Name = "Protocol"
	$global:ProtocolGrid.Columns[2].Name = "DB"
	$global:ProtocolGrid.Columns[3].Name = "Log"
	$global:ProtocolGrid.ReadOnly = $true
	$global:ProtocolGrid.RowHeadersVisible = $false
	$global:ProtocolGrid.AllowUserToAddRows = $false
	$global:ProtocolGrid.AllowUserToDeleteRows = $false
	$global:ProtocolGrid.AllowUserToResizeRows = $false
	$global:ProtocolGrid.AllowUserToResizeColumns = $false
	$global:ProtocolGrid.SelectionMode = "FullRowSelect"
	$global:ProtocolGrid.Font = New-Object System.Drawing.Font("Consolas", 10)
	$global:ProtocolGrid.Add_CellDoubleClick({
			param ($sender,
				$e)
			if ($e.RowIndex -lt 0) { return }
			try
			{
				$row = $sender.Rows[$e.RowIndex]
				if (-not $row) { return }
				$targetPath = [string]$row.Tag
				if ([string]::IsNullOrWhiteSpace($targetPath)) { return }
				Start-Process -FilePath 'explorer.exe' -ArgumentList @($targetPath) | Out-Null
			}
			catch { }
		})

	# Modern-ish grid styling (safe/light)
	try
	{
		$global:ProtocolGrid.BackgroundColor = $uiCardBg
		$global:ProtocolGrid.BorderStyle = 'FixedSingle'
		$global:ProtocolGrid.CellBorderStyle = 'SingleHorizontal'
		$global:ProtocolGrid.EnableHeadersVisualStyles = $false
		$global:ProtocolGrid.ColumnHeadersDefaultCellStyle.BackColor = [System.Drawing.Color]::FromArgb(238, 242, 247)
		$global:ProtocolGrid.ColumnHeadersDefaultCellStyle.ForeColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
		$global:ProtocolGrid.ColumnHeadersDefaultCellStyle.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
		$global:ProtocolGrid.DefaultCellStyle.BackColor = $uiCardBg
		$global:ProtocolGrid.DefaultCellStyle.ForeColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
		$global:ProtocolGrid.GridColor = [System.Drawing.Color]::FromArgb(235, 238, 242)
		$global:ProtocolGrid.AlternatingRowsDefaultCellStyle.BackColor = [System.Drawing.Color]::FromArgb(248, 250, 253)
		$global:ProtocolGrid.AlternatingRowsDefaultCellStyle.ForeColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
		$global:ProtocolGrid.DefaultCellStyle.SelectionBackColor = [System.Drawing.Color]::FromArgb(216, 236, 255)
		$global:ProtocolGrid.DefaultCellStyle.SelectionForeColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
	}
	catch { }

	$global:ProtocolForm.Controls.Add($global:ProtocolGrid)

	# Hint line under the grid
	$protocolHint = New-Object System.Windows.Forms.Label
	$protocolHint.Text = "Double-click a row to open its database folder."
	$protocolHint.Font = New-Object System.Drawing.Font("Segoe UI", 8.5)
	$protocolHint.ForeColor = [System.Drawing.Color]::FromArgb(120, 120, 125)
	$protocolHint.AutoSize = $true
	$protocolHint.Location = New-Object System.Drawing.Point(14, 412)
	$global:ProtocolForm.Controls.Add($protocolHint)

	$closeBtn = New-Object System.Windows.Forms.Button
	$closeBtn.Text = "Hide"
	$closeBtn.Location = New-Object System.Drawing.Point(176, 438)
	$closeBtn.Size = New-Object System.Drawing.Size(120, 32)
	$closeBtn.FlatStyle = 'Flat'
	$closeBtn.UseVisualStyleBackColor = $false
	$closeBtn.BackColor = [System.Drawing.Color]::White
	$closeBtn.ForeColor = [System.Drawing.Color]::FromArgb(32, 32, 32)
	$closeBtn.Cursor = [System.Windows.Forms.Cursors]::Hand
	$closeBtn.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(200, 205, 212)
	$closeBtn.FlatAppearance.BorderSize = 1
	$closeBtn.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(245, 248, 252)
	$closeBtn.FlatAppearance.MouseDownBackColor = [System.Drawing.Color]::FromArgb(235, 242, 252)
	$closeBtn.Add_Click({ $global:ProtocolForm.Hide() })
	$global:ProtocolForm.Controls.Add($closeBtn)

	# Prevent disposal on X; just hide
	$global:ProtocolForm.add_FormClosing({
			$_.Cancel = $true
			$global:ProtocolForm.Hide()
		})
}

if (-not $global:ProtocolFormTimer)
{
	$global:ProtocolFormTimer = New-Object System.Windows.Forms.Timer
	$global:ProtocolFormTimer.Interval = 500
	$global:ProtocolFormTimer.add_Tick({
			if ($script:LaneDbSizeJobs -and $script:LaneDbSizeJobs.Count -gt 0)
			{
				foreach ($laneKey in @($script:LaneDbSizeJobs.Keys))
				{
					$st = $script:LaneDbSizeJobs[$laneKey]
					if (-not $st) { continue }

					$handle = $st.Handle
					if ($handle -and $handle.IsCompleted)
					{
						$ps = $st.PS
						$resultList = $null
						try { $resultList = $ps.EndInvoke($handle) }
						catch { $resultList = $null }
						try { if ($ps) { $ps.Dispose() } }
						catch { }

						[void]$script:LaneDbSizeJobs.Remove($laneKey)

						$result = $null
						if ($resultList -and $resultList.Count -ge 1) { $result = $resultList[0] }

						if ($result)
						{
							$script:LaneDbSizeMap[$laneKey] = [pscustomobject]@{
								DataText = [string]$result.DataText
								LogText  = [string]$result.LogText
								Status   = [string]$result.Status
								OpenPath = [string]$result.OpenPath
								LastUpdate = Get-Date
							}
						}
						else
						{
							$script:LaneDbSizeMap[$laneKey] = [pscustomobject]@{
								DataText   = 'N/A'
								LogText    = 'N/A'
								Status	   = 'Error'
								OpenPath   = $null
								LastUpdate = Get-Date
							}
						}
					}
				}
			}

			if (-not $global:ProtocolForm.Visible) { return }

			# Save scroll & selection BEFORE clearing rows
			$prevRowCount = $global:ProtocolGrid.Rows.Count
			$scrollIndex = 0
			if ($prevRowCount -gt 0)
			{
				try { $scrollIndex = $global:ProtocolGrid.FirstDisplayedScrollingRowIndex }
				catch { $scrollIndex = 0 }
			}
			$selIndex = $null
			if ($global:ProtocolGrid.SelectedRows.Count -gt 0)
			{
				try { $selIndex = $global:ProtocolGrid.SelectedRows[0].Index }
				catch { $selIndex = $null }
			}

			# Refresh grid
			$global:ProtocolGrid.Rows.Clear()

			$LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
			$storeNumberForPopup = [string]$script:FunctionResults['StoreNumber']
			if ($storeNumberForPopup) { $storeNumberForPopup = ($storeNumberForPopup -replace '[^\d]', '').PadLeft(3, '0') }
			$dbsRootForPopup = $null
			try { $dbsRootForPopup = [string]$script:DbsPath }
			catch { $dbsRootForPopup = $null }
			if ([string]::IsNullOrWhiteSpace($dbsRootForPopup))
			{
				try { $dbsRootForPopup = [string]$DbsPath }
				catch { $dbsRootForPopup = $null }
			}
			if ([string]::IsNullOrWhiteSpace($dbsRootForPopup))
			{
				try { $dbsRootForPopup = [System.IO.Path]::Combine($OfficePath, 'Dbs') }
				catch { $dbsRootForPopup = $null }
			}

			$popupMode = [string]$script:ProtocolPopupMode
			if ([string]::IsNullOrWhiteSpace($popupMode)) { $popupMode = 'Lane' }

			if ($popupMode -eq 'Server')
			{
				$global:ProtocolForm.Text = "Server DB / Log Sizes"
				$global:ProtocolGrid.Columns[0].Name = "Server"

				$now = Get-Date
				$serverKey = '__SERVER__'
				$serverDisplay = [string]$script:FunctionResults['DBSERVER']
				if ([string]::IsNullOrWhiteSpace($serverDisplay) -or $serverDisplay -eq 'N/A') { $serverDisplay = $env:COMPUTERNAME }

				$dbName = [string]$script:FunctionResults['DBNAME']
				if ($dbName -eq 'N/A') { $dbName = $null }

				$connStr = [string]$script:FunctionResults['ConnectionString']
				if ($connStr -eq 'N/A') { $connStr = $null }

				$smsStartFallbackPath = $null
				if (-not [string]::IsNullOrWhiteSpace($dbsRootForPopup) -and -not [string]::IsNullOrWhiteSpace($storeNumberForPopup))
				{
					try { $smsStartFallbackPath = [System.IO.Path]::Combine($dbsRootForPopup, ("INFO_{0}901_SMSStart.ini" -f $storeNumberForPopup)) }
					catch { $smsStartFallbackPath = $null }
				}

				$proto = 'Local'
				try
				{
					if ($connStr -match '(?i)(?:Data Source|Server)\s*=\s*np:') { $proto = 'Named Pipes' }
					elseif ($connStr -match '(?i)(?:Data Source|Server)\s*=\s*tcp:') { $proto = 'TCP' }
					elseif ($serverDisplay -match '^(?i)(localhost|\(local\)|\.)(\\|$)') { $proto = 'Local' }
					elseif ($serverDisplay -match '\\') { $proto = 'Instance' }
					else { $proto = 'Server' }
				}
				catch { }

				if (-not ($script:LaneDbSizeJobs.ContainsKey($serverKey)))
				{
					$sizeEntry = $script:LaneDbSizeMap[$serverKey]
					$lastUpdate = $null
					try { $lastUpdate = $sizeEntry.LastUpdate }
					catch { $lastUpdate = $null }

					$needsRefresh = $false
					if (-not $sizeEntry) { $needsRefresh = $true }
					elseif (-not ($lastUpdate -is [datetime])) { $needsRefresh = $true }
					elseif ((($now) - $lastUpdate).TotalSeconds -ge $script:LaneDbSizeRefreshSeconds) { $needsRefresh = $true }

					if ($needsRefresh -and $script:LaneDbSizePool)
					{
						$workerProtocol = if ([string]::IsNullOrWhiteSpace($connStr)) { 'File' }
						else { 'SQL' }
						$canRunWorker = $false
						if ($workerProtocol -eq 'File')
						{
							$canRunWorker = -not [string]::IsNullOrWhiteSpace($serverDisplay) -and -not [string]::IsNullOrWhiteSpace($dbName)
						}
						else
						{
							$canRunWorker = -not [string]::IsNullOrWhiteSpace($connStr)
						}

						if (-not $canRunWorker)
						{
							$script:LaneDbSizeMap[$serverKey] = [pscustomobject]@{
								DataText   = 'N/A'
								LogText    = 'N/A'
								Status	   = 'NoConn'
								OpenPath   = $null
								LastUpdate = $now
							}
						}
						else
						{
							$script:LaneDbSizeMap[$serverKey] = [pscustomobject]@{
								DataText = if ($workerProtocol -eq 'File') { 'Scan...' } else { '...' }
								LogText  = if ($workerProtocol -eq 'File') { 'Scan...' } else { '...' }
								Status   = 'Pending'
								OpenPath = $null
								LastUpdate = $lastUpdate
							}

							$ps = [System.Management.Automation.PowerShell]::Create()
							$ps.RunspacePool = $script:LaneDbSizePool
							$null = $ps.AddScript($script:LaneDbSizeWorker).
							AddArgument([string]$serverKey).
							AddArgument([string]$workerProtocol).
							AddArgument([string]$connStr).
							AddArgument([string]$env:COMPUTERNAME).
							AddArgument([string]$dbName).
							AddArgument([string]$smsStartFallbackPath)
							$handle = $ps.BeginInvoke()

							$script:LaneDbSizeJobs[$serverKey] = @{ PS = $ps; Handle = $handle }
						}
					}
				}

				$sizeEntry = $script:LaneDbSizeMap[$serverKey]
				$dataText = '...'
				$logText = '...'
				if ($sizeEntry)
				{
					try
					{
						if (-not [string]::IsNullOrWhiteSpace([string]$sizeEntry.DataText)) { $dataText = [string]$sizeEntry.DataText }
						if (-not [string]::IsNullOrWhiteSpace([string]$sizeEntry.LogText)) { $logText = [string]$sizeEntry.LogText }
					}
					catch { }
				}

				$r = $global:ProtocolGrid.Rows.Add()
				$global:ProtocolGrid.Rows[$r].Cells[0].Value = $serverDisplay
				$global:ProtocolGrid.Rows[$r].Cells[1].Value = $proto
				$global:ProtocolGrid.Rows[$r].Cells[2].Value = $dataText
				$global:ProtocolGrid.Rows[$r].Cells[3].Value = $logText
				try { $global:ProtocolGrid.Rows[$r].Tag = [string]$sizeEntry.OpenPath }
				catch { }
			}
			else
			{
				$global:ProtocolForm.Text = "Lane Protocols / DB Sizes"
				$global:ProtocolGrid.Columns[0].Name = "Lane"

				# Prefer the new map (best), else fall back to LaneProtocols
				$map = $script:ProtocolResultsMap
				if (-not $map) { $map = $script:LaneProtocols }

				if ($map -and $map.Count -gt 0)
				{
					# Only numeric 3-digit lanes (LaneProtocols can also contain machine-name keys)
					$laneKeys = @($map.Keys | Where-Object { "$_" -match '^\d{3}$' } | Sort-Object { [int]$_ })

					$laneDbInfoMap = $script:FunctionResults['LaneDatabaseInfo']
					$now = Get-Date

					foreach ($ln in $laneKeys)
					{
						$proto = [string]$map[$ln]
						if ([string]::IsNullOrWhiteSpace($proto)) { $proto = "File" }

						$machineName = $ln
						if ($LaneNumToMachineName)
						{
							try
							{
								$mn = $LaneNumToMachineName[$ln]
								if (-not [string]::IsNullOrWhiteSpace($mn)) { $machineName = $mn }
							}
							catch { }
						}

						$dbInfo = $null
						try
						{
							if ($laneDbInfoMap -and $laneDbInfoMap.ContainsKey($ln))
							{
								$dbInfo = $laneDbInfoMap[$ln]
							}
						}
						catch { }

						if (-not $dbInfo)
						{
							try { $dbInfo = Get_All_Lanes_Database_Info -LaneNumber $ln }
							catch { $dbInfo = $null }
						}

						$dbName = $null
						$connStr = $null
						$smsStartFallbackPath = $null
						if ($dbInfo)
						{
							try
							{
								if ($dbInfo -is [hashtable])
								{
									$dbName = [string]$dbInfo['DBName']
									if ($proto -eq 'Named Pipes') { $connStr = [string]$dbInfo['NamedPipesConnStr'] }
									else { $connStr = [string]$dbInfo['TcpConnStr'] }
								}
								else
								{
									$dbName = [string]$dbInfo.DBName
									if ($proto -eq 'Named Pipes') { $connStr = [string]$dbInfo.NamedPipesConnStr }
									else { $connStr = [string]$dbInfo.TcpConnStr }
								}
							}
							catch
							{
								$dbName = $null
								$connStr = $null
							}
						}
						if (-not [string]::IsNullOrWhiteSpace($machineName) -and -not [string]::IsNullOrWhiteSpace($storeNumberForPopup))
						{
							try { $smsStartFallbackPath = ("\\{0}\storeman\office\dbs\INFO_{1}{2}_SMSStart.ini" -f $machineName, $storeNumberForPopup, $ln) }
							catch { $smsStartFallbackPath = $null }
						}

						if (-not ($script:LaneDbSizeJobs.ContainsKey($ln)))
						{
							$sizeEntry = $script:LaneDbSizeMap[$ln]
							$lastUpdate = $null
							try { $lastUpdate = $sizeEntry.LastUpdate }
							catch { $lastUpdate = $null }

							$needsRefresh = $false
							if (-not $sizeEntry) { $needsRefresh = $true }
							elseif (-not ($lastUpdate -is [datetime])) { $needsRefresh = $true }
							elseif ((($now) - $lastUpdate).TotalSeconds -ge $script:LaneDbSizeRefreshSeconds) { $needsRefresh = $true }

							if ($proto -eq 'Offline')
							{
								$script:LaneDbSizeMap[$ln] = [pscustomobject]@{
									DataText   = 'Offline'
									LogText    = 'Offline'
									Status	   = 'Offline'
									OpenPath   = $null
									LastUpdate = $now
								}
							}
							elseif ($needsRefresh -and $script:LaneDbSizePool)
							{
								$canRunWorker = $false
								if ($proto -eq 'File')
								{
									$canRunWorker = -not [string]::IsNullOrWhiteSpace($machineName) -and -not [string]::IsNullOrWhiteSpace($dbName)
								}
								else
								{
									$canRunWorker = -not [string]::IsNullOrWhiteSpace($connStr)
								}

								if (-not $canRunWorker)
								{
									$script:LaneDbSizeMap[$ln] = [pscustomobject]@{
										DataText   = 'N/A'
										LogText    = 'N/A'
										Status	   = 'NoConn'
										OpenPath   = $null
										LastUpdate = $now
									}
								}
								else
								{
									$script:LaneDbSizeMap[$ln] = [pscustomobject]@{
										DataText = if ($proto -eq 'File') { 'Scan...' } else { '...' }
										LogText  = if ($proto -eq 'File') { 'Scan...' } else { '...' }
										Status   = 'Pending'
										OpenPath = $null
										LastUpdate = $lastUpdate
									}

									$ps = [System.Management.Automation.PowerShell]::Create()
									$ps.RunspacePool = $script:LaneDbSizePool
									$null = $ps.AddScript($script:LaneDbSizeWorker).
									AddArgument([string]$ln).
									AddArgument([string]$proto).
									AddArgument([string]$connStr).
									AddArgument([string]$machineName).
									AddArgument([string]$dbName).
									AddArgument([string]$smsStartFallbackPath)
									$handle = $ps.BeginInvoke()

									$script:LaneDbSizeJobs[$ln] = @{ PS = $ps; Handle = $handle }
								}
							}
						}

						$sizeEntry = $script:LaneDbSizeMap[$ln]
						$dataText = '...'
						$logText = '...'
						if ($sizeEntry)
						{
							try
							{
								if (-not [string]::IsNullOrWhiteSpace([string]$sizeEntry.DataText)) { $dataText = [string]$sizeEntry.DataText }
								if (-not [string]::IsNullOrWhiteSpace([string]$sizeEntry.LogText)) { $logText = [string]$sizeEntry.LogText }
							}
							catch { }
						}

						$r = $global:ProtocolGrid.Rows.Add()
						$global:ProtocolGrid.Rows[$r].Cells[0].Value = $machineName
						$global:ProtocolGrid.Rows[$r].Cells[1].Value = $proto
						$global:ProtocolGrid.Rows[$r].Cells[2].Value = $dataText
						$global:ProtocolGrid.Rows[$r].Cells[3].Value = $logText
						try { $global:ProtocolGrid.Rows[$r].Tag = [string]$sizeEntry.OpenPath }
						catch { }
					}

					# Optional: rebuild $script:ProtocolResults so any other old code keeps working
					$script:ProtocolResults = @(
						foreach ($ln in $laneKeys)
						{
							[pscustomobject]@{ Lane = $ln; Protocol = [string]$map[$ln] }
						}
					)
				}
			}

			# Column widths (Lane/Protocol fixed, DB/Log fill; account for scrollbar)
			$col0Width = if ($popupMode -eq 'Server') { 180 }
			else { 130 }
			$col1Width = 90
			$global:ProtocolGrid.Columns[0].Width = $col0Width
			$global:ProtocolGrid.Columns[1].Width = $col1Width
			$visibleRowCount = [math]::Floor($global:ProtocolGrid.DisplayRectangle.Height / $global:ProtocolGrid.RowTemplate.Height)
			$scrollBarVisible = $global:ProtocolGrid.Rows.Count -gt $visibleRowCount
			$remainingWidth = $global:ProtocolGrid.Width - $col0Width - $col1Width - 4
			if ($scrollBarVisible)
			{
				$remainingWidth -= [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth
			}
			if ($remainingWidth -lt 180) { $remainingWidth = 180 }
			$dbWidth = [math]::Floor($remainingWidth / 2)
			$logWidth = $remainingWidth - $dbWidth
			if ($dbWidth -lt 90) { $dbWidth = 90 }
			if ($logWidth -lt 90) { $logWidth = 90 }
			$global:ProtocolGrid.Columns[2].Width = $dbWidth
			$global:ProtocolGrid.Columns[3].Width = $logWidth

			if ($global:ProtocolGrid.Columns[2].Width + $global:ProtocolGrid.Columns[3].Width -gt $remainingWidth)
			{
				$global:ProtocolGrid.Columns[3].Width = [math]::Max(90, $remainingWidth - $global:ProtocolGrid.Columns[2].Width)
			}

			# Restore scroll & selection safely
			$rowCount = $global:ProtocolGrid.Rows.Count
			if ($rowCount -gt 0)
			{
				if ($scrollIndex -lt 0) { $scrollIndex = 0 }
				if ($scrollIndex -ge $rowCount) { $scrollIndex = $rowCount - 1 }
				try { $global:ProtocolGrid.FirstDisplayedScrollingRowIndex = $scrollIndex }
				catch { }
			}
			if ($selIndex -ne $null -and $rowCount -gt $selIndex -and $selIndex -ge 0)
			{
				try { $global:ProtocolGrid.Rows[$selIndex].Selected = $true }
				catch { }
			}
		})
	$global:ProtocolFormTimer.Start()
}

# ===================================================================================================
#                                  SECTION: GUI - Form Closing
# ---------------------------------------------------------------------------------------------------
# Description:
#   Closing the main window (X button or idle close) closes immediately: timers are stopped,
#   the protocol popup is disposed, background loops are told to stop, and the temporary
#   *.sqi / *.sql files in %TEMP% are deleted. Background runspaces, jobs and pools are NOT
#   torn down one by one - the host process exits right after ShowDialog returns, which ends
#   them anyway, and an orderly teardown only made the X button slow.
#   Also runs the initial layout pass for the top strip and the log area.
# ===================================================================================================

$form.add_FormClosing({
		# ---- Timers ----
		foreach ($timerName in 'IdleTimer', 'VncExportReaper', 'RemoteMachineInfoReaper', 'StartupWarmupTimer', 'PopupThemeTimer', 'protocolTimer')
		{
			try
			{
				$t = Get-Variable -Name $timerName -Scope Script -ValueOnly -ErrorAction SilentlyContinue
				if ($t) { $t.Stop(); $t.Dispose(); Set-Variable -Name $timerName -Scope Script -Value $null }
			}
			catch { }
		}
		try { if ($BusyTimer) { $BusyTimer.Stop(); $BusyTimer.Dispose() } }
		catch { }
		try
		{
			if ($global:ProtocolFormTimer)
			{
				$global:ProtocolFormTimer.Stop()
				$global:ProtocolFormTimer.Dispose()
				$global:ProtocolFormTimer = $null
			}
		}
		catch { }

		# ---- Protocol popup ----
		try
		{
			if ($global:ProtocolForm)
			{
				try { $global:ProtocolForm.Hide() }
				catch { }
				try { $global:ProtocolForm.Dispose() }
				catch { }
				$global:ProtocolForm = $null
			}
		}
		catch { }

		# ---- Background loops: stop scheduling new work ----
		$script:LaneProtocolStop = $true
		$script:VncExportTask = $null
		$script:RemoteMachineInfoTask = $null
		$script:ScaleCredTasks = @{ }

		try { Write_Log "Form is closing. Performing cleanup." "green" }
		catch { }

		# ---- Temporary SQL files written by the maintenance tasks ----
		try
		{
			Get-ChildItem -LiteralPath $TempDir -File -ErrorAction SilentlyContinue |
			Where-Object { $_.Name -like '*.sqi' -or $_.Name -like '*.sql' } |
			ForEach-Object {
				try { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue }
				catch { }
			}
		}
		catch { }
	})

# Initial layout pass so everything starts aligned (the bottom layout runs in 14)
& $layoutTopStrip
& $layoutLogArea

# ===================================================================================================
#                                 SECTION: GUI - Styling Helpers
# ---------------------------------------------------------------------------------------------------
# Description:
#   Shared look for menus and popup dialogs (scriptblocks, PS 5.1 friendly):
#     $Apply_Modern_Menu_Style   style a ContextMenuStrip (the four tool menus, grid menus)
#     $Style_SubMenu             style a submenu's dropdown the same way
#     $Apply_Modern_Popup_Style  restyle a popup Form and all of its controls
#   plus the popup theme timer, which applies $Apply_Modern_Popup_Style automatically to every
#   new window the script opens (dialogs inside the functions need no styling code of their own).
#
# Notes:
#   - The menu renderer (src\Resources\CSharp\ModernToolStripRenderer.cs) is compiled once here.
#     Before v2.7.0 it never compiled (an unused class raised a warning-as-error and the WinForms
#     references were missing) and an invalid ItemMargin assignment aborted the styling first,
#     so the menus always fell back to the default renderer.
# ===================================================================================================

# Fallback colours (the palette in 01 defines these; same variables, script scope)
if (-not $script:UiAccent) { $script:UiAccent = [System.Drawing.Color]::DodgerBlue }
if (-not $script:UiCardBorder) { $script:UiCardBorder = [System.Drawing.Color]::FromArgb(220, 225, 232) }
if (-not $script:UiCardBg) { $script:UiCardBg = [System.Drawing.Color]::White }
if (-not $script:UiTextDark) { $script:UiTextDark = [System.Drawing.Color]::FromArgb(28, 28, 30) }

# ----------------------------------------------------------------------------
# Menu renderer (compiled once per process)
# ----------------------------------------------------------------------------
if (-not ('ModernToolStripRenderer' -as [type]))
{
	try
	{
		Add-Type -ReferencedAssemblies System.Windows.Forms, System.Drawing -ErrorAction Stop -TypeDefinition @'
// Menu renderer for the four tool menus and their submenus (GUI\09_Styling_Helpers).
// Embedded at build time and compiled once with Add-Type (references System.Windows.Forms and
// System.Drawing). Light-blue hover with a 1 px accent bar on the left, thin light separators,
// light borders, no image margin.
using System;
using System.Drawing;
using System.Windows.Forms;

public class ModernColorTable : ProfessionalColorTable
{
    public override Color MenuBorder { get { return Color.FromArgb(229, 229, 229); } }
    public override Color MenuItemBorder { get { return Color.Transparent; } }
    public override Color ToolStripBorder { get { return Color.FromArgb(229, 229, 229); } }
}

public class ModernToolStripRenderer : ToolStripProfessionalRenderer
{
    public ModernToolStripRenderer() : base(new ModernColorTable()) { }

    protected override void OnRenderItemBackground(ToolStripItemRenderEventArgs e)
    {
        if (e.Item.Selected)
        {
            using (var brush = new SolidBrush(Color.FromArgb(230, 243, 255)))
            {
                e.Graphics.FillRectangle(brush, new Rectangle(0, 0, e.Item.Width - 1, e.Item.Height - 1));
            }
        }
        else
        {
            base.OnRenderItemBackground(e);
        }
    }

    protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e)
    {
        if (e.Item.Selected && e.Item.Enabled)
        {
            using (var brush = new SolidBrush(Color.FromArgb(230, 243, 255)))
            {
                e.Graphics.FillRectangle(brush, new Rectangle(0, 0, e.Item.Width - 1, e.Item.Height - 1));
            }
            using (var pen = new Pen(Color.FromArgb(0, 122, 204), 1))
            {
                e.Graphics.DrawLine(pen, 0, 0, 0, e.Item.Height - 1);
            }
        }
        else
        {
            base.OnRenderMenuItemBackground(e);
        }
    }

    protected override void OnRenderImageMargin(ToolStripRenderEventArgs e) { }

    protected override void OnRenderSeparator(ToolStripSeparatorRenderEventArgs e)
    {
        using (var pen = new Pen(Color.FromArgb(229, 229, 229)))
        {
            e.Graphics.DrawLine(pen, 0, e.Item.Height / 2, e.Item.Width, e.Item.Height / 2);
        }
    }
}
'@
	}
	catch
	{
		try { Write_Log ("Menu renderer could not be compiled - using the default menu look: " + $_.Exception.Message) 'gray' -FileOnly }
		catch { }
	}
}

# ----------------------------------------------------------------------------
# Context menu styling
# ----------------------------------------------------------------------------
$Apply_Modern_Menu_Style = {
	param ([System.Windows.Forms.ContextMenuStrip]$Menu)

	if (-not $Menu) { return }
	try
	{
		$Menu.ShowImageMargin = $false
		$Menu.ShowCheckMargin = $false
		$Menu.Font = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)
		$Menu.BackColor = [System.Drawing.Color]::White
		$Menu.ForeColor = [System.Drawing.Color]::FromArgb(32, 32, 32)
		$Menu.Padding = New-Object System.Windows.Forms.Padding(2)
		$Menu.GripMargin = New-Object System.Windows.Forms.Padding(0)
		if ('ModernToolStripRenderer' -as [type]) { $Menu.Renderer = New-Object ModernToolStripRenderer }
		else { $Menu.RenderMode = [System.Windows.Forms.ToolStripRenderMode]::Professional }
	}
	catch { }
}

# Submenu dropdowns (a ToolStripMenuItem's DropDown, not a ContextMenuStrip)
$Style_SubMenu = {
	param ($Sub)
	try
	{
		$dd = $Sub.DropDown
		$dd.BackColor = [System.Drawing.Color]::White
		$dd.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
		$dd.Padding = New-Object System.Windows.Forms.Padding(2)
		$dd.ShowImageMargin = $false
		$dd.ShowCheckMargin = $false
		$dd.GripMargin = New-Object System.Windows.Forms.Padding(0)
		if ('ModernToolStripRenderer' -as [type]) { $dd.Renderer = New-Object ModernToolStripRenderer }
	}
	catch { }
}

# ----------------------------------------------------------------------------
# Popup forms: restyle the form and every control in it so older dialogs match the main app
# ----------------------------------------------------------------------------
$Apply_Modern_Popup_Style = {
	param ([System.Windows.Forms.Form]$PopupForm)

	if (-not $PopupForm -or $PopupForm.IsDisposed) { return }

	$stylePopupControls = $null
	$stylePopupControls = {
		param ($Control)

		if (-not $Control) { return }

		try
		{
			if ($Control -is [System.Windows.Forms.Button])
			{
				$measured = [System.Windows.Forms.TextRenderer]::MeasureText($Control.Text, (New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)))
				$minWidth = [Math]::Max([int]$Control.Width, [int]($measured.Width + 22))
				$minHeight = [Math]::Max([int]$Control.Height, [int]($measured.Height + 12), 32)
				$preserveAccentBack = ($Control.BackColor -eq [System.Drawing.Color]::Yellow -or $Control.BackColor -eq [System.Drawing.Color]::LightGreen)

				$Control.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
				$Control.UseVisualStyleBackColor = $false
				if (-not $preserveAccentBack)
				{
					$Control.BackColor = $script:UiCardBg
				}
				$Control.ForeColor = $script:UiTextDark
				$Control.Font = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)
				$Control.Cursor = [System.Windows.Forms.Cursors]::Hand
				$Control.FlatAppearance.BorderSize = 1
				$Control.FlatAppearance.BorderColor = $script:UiCardBorder
				$Control.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(245, 248, 252)
				$Control.FlatAppearance.MouseDownBackColor = [System.Drawing.Color]::FromArgb(235, 242, 252)
				if ($Control.Width -lt $minWidth) { $Control.Width = $minWidth }
				if ($Control.Height -lt $minHeight) { $Control.Height = $minHeight }
			}
			elseif ($Control -is [System.Windows.Forms.Label] -or
				$Control -is [System.Windows.Forms.CheckBox] -or
				$Control -is [System.Windows.Forms.RadioButton])
			{
				$Control.ForeColor = $script:UiTextDark
				$Control.BackColor = [System.Drawing.Color]::Transparent
				$Control.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
			}
			elseif ($Control -is [System.Windows.Forms.TextBox] -or
				$Control -is [System.Windows.Forms.RichTextBox] -or
				$Control -is [System.Windows.Forms.MaskedTextBox])
			{
				$Control.BackColor = [System.Drawing.Color]::White
				$Control.ForeColor = $script:UiTextDark
				$Control.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
				try { $Control.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle }
				catch { }
			}
			elseif ($Control -is [System.Windows.Forms.ComboBox])
			{
				$Control.BackColor = [System.Drawing.Color]::White
				$Control.ForeColor = $script:UiTextDark
				$Control.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
				try { $Control.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat }
				catch { }
			}
			elseif ($Control -is [System.Windows.Forms.NumericUpDown] -or
				$Control -is [System.Windows.Forms.DateTimePicker])
			{
				$Control.BackColor = [System.Drawing.Color]::White
				$Control.ForeColor = $script:UiTextDark
				$Control.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
			}
			elseif ($Control -is [System.Windows.Forms.ListBox] -or
				$Control -is [System.Windows.Forms.ListView] -or
				$Control -is [System.Windows.Forms.CheckedListBox])
			{
				$Control.BackColor = [System.Drawing.Color]::White
				$Control.ForeColor = $script:UiTextDark
				$Control.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
			}
			elseif ($Control -is [System.Windows.Forms.GroupBox])
			{
				$Control.ForeColor = $script:UiTextDark
				$Control.BackColor = $script:UiCardBg
				$Control.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
			}
			elseif ($Control -is [System.Windows.Forms.Panel] -or
				$Control -is [System.Windows.Forms.TabPage] -or
				$Control -is [System.Windows.Forms.FlowLayoutPanel] -or
				$Control -is [System.Windows.Forms.TableLayoutPanel])
			{
				if ($Control.BackColor -eq [System.Drawing.Color]::Empty -or $Control.BackColor.A -eq 0)
				{
					$Control.BackColor = [System.Drawing.Color]::Transparent
				}
				elseif ($Control.BackColor -ne $script:UiCardBg)
				{
					$Control.BackColor = $script:UiCardBg
				}
			}
			elseif ($Control -is [System.Windows.Forms.TabControl])
			{
				$Control.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
			}
			elseif ($Control -is [System.Windows.Forms.DataGridView])
			{
				$Control.BackgroundColor = $script:UiCardBg
				$Control.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
				$Control.GridColor = $script:UiCardBorder
				$Control.EnableHeadersVisualStyles = $false
				$Control.ColumnHeadersDefaultCellStyle.BackColor = [System.Drawing.Color]::FromArgb(245, 247, 250)
				$Control.ColumnHeadersDefaultCellStyle.ForeColor = $script:UiTextDark
				$Control.ColumnHeadersDefaultCellStyle.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
				$Control.DefaultCellStyle.BackColor = [System.Drawing.Color]::White
				$Control.DefaultCellStyle.ForeColor = $script:UiTextDark
				$Control.DefaultCellStyle.SelectionBackColor = [System.Drawing.Color]::FromArgb(221, 235, 255)
				$Control.DefaultCellStyle.SelectionForeColor = $script:UiTextDark
				$Control.AlternatingRowsDefaultCellStyle.BackColor = [System.Drawing.Color]::FromArgb(250, 251, 253)
			}

			if ($Control.ContextMenuStrip)
			{
				& $Apply_Modern_Menu_Style $Control.ContextMenuStrip
			}
		}
		catch { }

		try
		{
			foreach ($child in @($Control.Controls))
			{
				& $stylePopupControls $child
			}
		}
		catch { }
	}

	try
	{
		$PopupForm.BackColor = $uiBg
		$PopupForm.ForeColor = $script:UiTextDark
		$PopupForm.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
		$PopupForm.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::Dpi
		try
		{
			$prop = $PopupForm.GetType().GetProperty("DoubleBuffered", [System.Reflection.BindingFlags] "Instance,NonPublic")
			if ($prop) { $prop.SetValue($PopupForm, $true, $null) }
		}
		catch { }

		if ($PopupForm.MainMenuStrip)
		{
			$PopupForm.MainMenuStrip.BackColor = $script:UiCardBg
			$PopupForm.MainMenuStrip.ForeColor = $script:UiTextDark
			$PopupForm.MainMenuStrip.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
		}

		& $stylePopupControls $PopupForm
	}
	catch { }
}

if (-not $script:PopupThemeTimer)
{
	$script:PopupThemeTimer = New-Object System.Windows.Forms.Timer
	$script:PopupThemeTimer.Interval = 300
	$script:PopupThemeTimer.Add_Tick({
			try
			{
				if ([System.Windows.Forms.Application]::OpenForms.Count -le 1 -and $script:StyledPopupForms.Count -eq 0) { return }

				$activeHashes = @{ }
				foreach ($openForm in [System.Windows.Forms.Application]::OpenForms)
				{
					if (-not $openForm -or $openForm.IsDisposed) { continue }
					if ($form -and [object]::ReferenceEquals($openForm, $form)) { continue }

					$formHash = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($openForm)
					$activeHashes[$formHash] = $true

					if (-not $script:StyledPopupForms.ContainsKey($formHash))
					{
						& $Apply_Modern_Popup_Style $openForm
						$script:StyledPopupForms[$formHash] = $true
					}
				}

				foreach ($staleHash in @($script:StyledPopupForms.Keys))
				{
					if (-not $activeHashes.ContainsKey($staleHash))
					{
						[void]$script:StyledPopupForms.Remove($staleHash)
					}
				}
			}
			catch { }
		})
	$script:PopupThemeTimer.Start()
}

# ----------------------------------------------------------------------------
# Category button (Server / Lane / Scale / General): white flat button with a
# colored bottom bar. Click opens its menu; right-click opens the protocol
# window when ProtocolMode is set. Handlers read everything from .Tag (no
# closures - see CLAUDE.md), so one definition serves all four buttons.
# ----------------------------------------------------------------------------
$New_Category_Button = {
	param (
		[string]$Name,
		[string]$Text,
		[int]$X,
		[System.Drawing.Color]$Accent,
		[System.Drawing.Color]$HoverBack,
		[System.Drawing.Color]$DownBack,
		[System.Drawing.Color]$HoverFore,
		[System.Windows.Forms.ContextMenuStrip]$Menu,
		[string]$ProtocolMode,
		[string]$ToolTipText
	)

	$b = New-Object System.Windows.Forms.Button
	$b.Name = $Name
	$b.Text = $Text
	$b.Location = New-Object System.Drawing.Point($X, 475)
	$b.Size = New-Object System.Drawing.Size(200, 52)
	$b.Font = New-Object System.Drawing.Font("Segoe UI", 10.5, [System.Drawing.FontStyle]::Regular)
	$b.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
	$b.UseVisualStyleBackColor = $false
	$b.BackColor = [System.Drawing.Color]::White
	$b.ForeColor = [System.Drawing.Color]::FromArgb(32, 32, 32)
	$b.Cursor = [System.Windows.Forms.Cursors]::Hand
	$b.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
	$b.FlatAppearance.BorderSize = 0
	$b.FlatAppearance.MouseOverBackColor = $HoverBack
	$b.FlatAppearance.MouseDownBackColor = $DownBack
	$b.Tag = [pscustomobject]@{
		CategoryColor = $Accent
		HoverBack	  = $HoverBack
		HoverFore	  = $HoverFore
		Menu		  = $Menu
		ProtocolMode  = $ProtocolMode
	}

	# Bottom accent bar
	$b.add_Paint({
			param ($s, $e)
			try
			{
				$pen = New-Object System.Drawing.Pen($s.Tag.CategoryColor, 3)
				$e.Graphics.DrawLine($pen, 4, $s.Height - 4, $s.Width - 4, $s.Height - 4)
				$pen.Dispose()
			}
			catch { }
		})
	$b.add_MouseEnter({
			param ($s, $e)
			try { $s.BackColor = $s.Tag.HoverBack; $s.ForeColor = $s.Tag.HoverFore }
			catch { }
		})
	$b.add_MouseLeave({
			param ($s, $e)
			try { $s.BackColor = [System.Drawing.Color]::White; $s.ForeColor = [System.Drawing.Color]::FromArgb(32, 32, 32) }
			catch { }
		})
	$b.add_Click({
			param ($s, $e)
			$script:LastActivity = Get-Date
			$s.Tag.Menu.Show($s, 0, $s.Height)
		})
	if ($ProtocolMode)
	{
		$b.add_MouseDown({
				param ($s, $e)
				if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Right)
				{
					$script:ProtocolPopupMode = $s.Tag.ProtocolMode
					$global:ProtocolForm.Show()
					$global:ProtocolForm.BringToFront()
				}
			})
	}
	$toolTip.SetToolTip($b, $ToolTipText)
	$form.Controls.Add($b)
	$b
}

