######################################################################################################################
#
# Bottom buttons + logbox layout  (FIXED for StatusStrip + modern top strip)
#
######################################################################################################################

# -------- Bottom buttons + logbox layout (expand buttons, tight gap) --------
$padSide = 50 # left/right margin for logbox & button row
$padBottom = 10 # distance from buttons to bottom edge (ABOVE status strip)
$gapAboveButtons = 10 # vertical gap between logbox and buttons
$btnH = 48 # button height (slightly shorter = more modern)
$btnMinW = 180 # minimum button width so labels never wrap
$gapHPreferred = 18 # preferred horizontal gap between buttons
$gapHMin = 10 # absolute minimum horizontal gap
$minLogH = 140 # don't let the logbox collapse
$logInnerPad = 10 # if you use a log frame panel, this pads the inner log box

# keep WinForms from fighting our math
$ServerToolsButton.Anchor = 'Bottom,Left'
$LaneToolsButton.Anchor = 'Bottom,Left'
$ScaleToolsButton.Anchor = 'Bottom,Left'
$GeneralToolsButton.Anchor = 'Bottom,Left'

# Log frame resizes with window
if ($logFrame) { $logFrame.Anchor = 'Top,Left,Right,Bottom' }

# If you have a log frame panel in your newer UI, it will be resized too.
# If not, we will just resize $logBox directly.
if ($logBox) { $logBox.Anchor = 'Top,Left,Right,Bottom' }

$layoutBottom = {
	if (-not $form -or $form.IsDisposed) { return }

	# --- Compute shared row width (log + button row align) ---------------------
	$rowW = [math]::Max(200, $form.ClientSize.Width - (2 * $padSide))

	# --- Account for StatusStrip (THIS fixes the "buttons cut off" issue) -----
	$bottomReserve = 0
	try
	{
		if ($statusStrip -and -not $statusStrip.IsDisposed) { $bottomReserve = $statusStrip.Height }
	}
	catch { $bottomReserve = 0 }

	# --- Determine log top dynamically (banner + card + margin) -------------
	$logTop = $bannerPanel.Bottom + $topStripCard.Height + 10
	try
	{
		if ($topStripCard -and -not $topStripCard.IsDisposed)
		{
			$logTop = $topStripCard.Bottom + 10
		}
	}
	catch { }

	# --- Button row Y (above status strip) ------------------------------------
	$btnY = $form.ClientSize.Height - $bottomReserve - $btnH - $padBottom

	# --- Lay out log area (with header) ---------------------------------------
	$hasLogFrame = $false
	try { $hasLogFrame = ($logFrame -and -not $logFrame.IsDisposed) }
	catch { $hasLogFrame = $false }

	# Header height
	$lgHeaderH = 28
	$lgPadding = 10

	if ($hasLogFrame)
	{
		# Frame uses the full row width
		$logFrame.Left = $padSide
		$logFrame.Top = $logTop
		$logFrame.Width = $rowW

		# Height ensures a constant gap above buttons (accounting for header)
		$logFrame.Height = [math]::Max($minLogH, $btnY - $logFrame.Top - $gapAboveButtons)

		# Inner logBox inset for clean "card" look (accounting for header + padding)
		$logBox.Left = $lgPadding
		$logBox.Top = $lgHeaderH + $lgPadding
		$logBox.Width = [math]::Max(50, $logFrame.Width - (2 * $lgPadding))
		$logBox.Height = [math]::Max(50, $logFrame.Height - $lgHeaderH - (2 * $lgPadding))
	}
	else
	{
		# Plain logBox layout
		$logBox.Left = $padSide
		$logBox.Top = $logTop
		$logBox.Width = $rowW
		$logBox.Height = [math]::Max($minLogH, $btnY - $logBox.Top - $gapAboveButtons)
	}

	# --- Compute dynamic button width so the four buttons fill the row --------
	$gapH = $gapHPreferred
	$btnW = [math]::Floor(($rowW - (3 * $gapH)) / 4)

	# If too small, clamp width and reduce gaps (not below gapHMin)
	if ($btnW -lt $btnMinW)
	{
		$btnW = $btnMinW
		$gapH = [math]::Floor(($rowW - (4 * $btnW)) / 3)
		if ($gapH -lt $gapHMin) { $gapH = $gapHMin }
	}
	else
	{
		# Distribute leftover pixels (from integer math) into gaps
		$used = (4 * $btnW) + (3 * $gapH)
		$extra = $rowW - $used
		if ($extra -gt 0) { $gapH += [math]::Floor($extra / 3) }
	}

	# --- Position buttons left->right; group width == logbox width ------------
	$x = $padSide
	$ServerToolsButton.SetBounds($x, $btnY, $btnW, $btnH); $x += $btnW + $gapH
	$LaneToolsButton.SetBounds($x, $btnY, $btnW, $btnH); $x += $btnW + $gapH
	$ScaleToolsButton.SetBounds($x, $btnY, $btnW, $btnH); $x += $btnW + $gapH
	$GeneralToolsButton.SetBounds($x, $btnY, $btnW, $btnH)

	# Keep right-side labels aligned with the logbox edge
	& $layoutTopStrip

	# Ensure status strip stays visible
	try { if ($statusStrip -and -not $statusStrip.IsDisposed) { $statusStrip.BringToFront() } }
	catch { }
}

# prevent shrinking so far that 4*minW + 3*minGap won't fit
$minW = (2 * $padSide) + (4 * $btnMinW) + (3 * $gapHMin)
if ($form.MinimumSize.Width -lt $minW)
{
	$form.MinimumSize = New-Object System.Drawing.Size($minW, [math]::Max($form.MinimumSize.Height, 560))
}

# run now + on resize
& $layoutBottom
$form.add_Resize({ & $layoutBottom })

######################################################################################################################
#
# Activity hooks for controls OUTSIDE the main form
#   06_Busy_Idle_Activity already hooks the form, every child control and any control added to
#   the form later (ControlAdded). The menus and the protocol window are separate top-level
#   windows, so they get their own hooks here (the form, log box and buttons used to be hooked
#   a second and third time from this list).
#
######################################################################################################################
foreach ($__c in @($ContextMenuServer, $ContextMenuLane, $ContextMenuScale, $ContextMenuGeneral, $global:ProtocolForm, $global:ProtocolGrid))
{
	if ($__c -isnot [System.Windows.Forms.Control]) { continue }
	try
	{
		$__c.Add_MouseMove({ $script:LastActivity = Get-Date })
		$__c.Add_KeyDown({ $script:LastActivity = Get-Date })
		$__c.Add_Click({ $script:LastActivity = Get-Date })
	}
	catch { }
}

# ===================================================================================================
#                                 SECTION: Main - Load Store Data
# ---------------------------------------------------------------------------------------------------
# Description:
#   Pre-window data load. Everything here reads the local cache files in Setup_Files, so the
#   window can appear fast; the network refreshes run after Show as warmup steps (02).
#     - starts the NSSM download in the background (returns immediately)
#     - store + database info (a first run with no cache does its full fetch here)
#     - store number normalisation (1 -> 001; 4+ digits keep 4+)
#     - node discovery (lanes, scales, backoffices) from cache
#
# Notes:
#   - tests\TBS_Maintenance_SelfTest.ps1 runs the store-number block verbatim, from the
#     '$script:StoreNumber = [string]...' line to the line before '$script:StoreName = ...'.
#   - At script scope $StoreNumber and $script:StoreNumber are the same variable; the menus
#     pass $StoreNumber to the functions.
# ===================================================================================================

Download_NSSM -Background | Out-Null

Get_Store_And_Database_Info -WinIniPath $WinIniPath -SmsStartIniPath $SmsStartIniPath -StartupIniPath $StartupIniPath -SystemIniPath $SystemIniPath
Get_Store_And_Database_Info -WinIniPath $WinIniPath -SmsStartIniPath $SmsStartIniPath -StartupIniPath $StartupIniPath -SystemIniPath $SystemIniPath
$script:StoreNumber = [string]$script:FunctionResults['StoreNumber']
if ($script:StoreNumber)
{
	$storeDigits = ($script:StoreNumber -replace '[^\d]', '')
	if ($storeDigits)
	{
		if ($storeDigits.Length -le 3) { $script:StoreNumber = ([int]$storeDigits).ToString('000') }
		else { $script:StoreNumber = ([int]$storeDigits).ToString('0000') }
	}
}
$script:StoreName = $script:FunctionResults['StoreName']
$script:SqlModuleName = $script:FunctionResults['SqlModuleName']

# Nodes from cache (the fresh discovery is the second warmup step, which also starts the
# lane protocol loop against the fresh node list)
$null = Retrieve_Nodes -StoreNumber $StoreNumber
$script:Nodes = $script:FunctionResults['Nodes']
$script:LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']

try { Write_Log ("Startup: pre-window data ready in {0:N1}s - store '{1}', {2} node(s)" -f ((Get-Date) - $script:StartupT0).TotalSeconds, $StoreNumber, @($Nodes).Count) 'blue' -FileOnly } catch { }

$form.Add_Shown({
		if ($script:StartupWarmupStarted) { return }
		$script:StartupWarmupStarted = $true
		$script:StartupWarmupIndex = 0
		$script:StartupWarmupSteps = @()
		$script:StartupScaleCredStarted = $false

		# Startup milestone (file log): the moment the window first appears
		try { Write_Log ("Startup: window shown {0:N1}s after script start" -f ((Get-Date) - $script:StartupT0).TotalSeconds) 'green' -FileOnly } catch { }

		try
		{
			if ($script:StartupScaleCredTimer)
			{
				$script:StartupScaleCredTimer.Stop()
				$script:StartupScaleCredTimer.Dispose()
				$script:StartupScaleCredTimer = $null
			}
		}
		catch { }

		$script:StartupScaleCredTimer = New-Object System.Windows.Forms.Timer
		$script:StartupScaleCredTimer.Interval = 250
		$script:StartupScaleCredTimer.Add_Tick({
				try
				{
					if ($script:StartupScaleCredTimer)
					{
						$script:StartupScaleCredTimer.Stop()
						$script:StartupScaleCredTimer.Dispose()
						$script:StartupScaleCredTimer = $null
					}
				}
				catch { }

				if ($script:StartupScaleCredStarted) { return }

				try
				{
					$windowsScales = $script:FunctionResults['WindowsScales']
					if ($windowsScales -and $windowsScales.Count -gt 0)
					{
						Add_Scale_Credentials -ScaleCodeToIPInfo $windowsScales
					}
					$script:StartupScaleCredStarted = $true
				}
				catch { }
			})
		try { $script:StartupScaleCredTimer.Start() }
		catch { }

		# v2.6.9: these steps run as BACKGROUND JOBS (Mode = 'Job'). The tick
		# handler below starts each one and polls it, so no step can freeze the
		# UI thread. Every job refreshes the function's FILE cache; OnComplete
		# then re-runs the same call WITHOUT -RefreshCache on the UI thread,
		# which reads the warm cache, hydrates FunctionResults and updates the
		# GUI labels (a few ms of local work). 'Installing SMS functions' writes
		# no shared cache and returns nothing, so it just runs in the job.
		# EXCEPTION: 'Generating SQL scripts' is INLINE (Action), not a job -
		# it is pure CPU (5 here-strings + 2 regex passes, no I/O, ~2 ms) so it
		# is safe on the UI thread, and running it inline sets the $script: SQL
		# variables directly (no job-scope handoff / ReturnVarNames wait).
		# NOTE: CallArgs on 'Job' steps is a SCRIPTBLOCK evaluated at start time,
		# so every job receives the current values of the variables it depends on.
		$script:StartupWarmupSteps += [pscustomobject]@{
			Label        = 'Refreshing store info...'
			Mode         = 'Job'
			FunctionName = 'Get_Store_And_Database_Info'
			CallArgs     = { @{ WinIniPath = $WinIniPath; SmsStartIniPath = $SmsStartIniPath; StartupIniPath = $StartupIniPath; SystemIniPath = $SystemIniPath; RefreshCache = $true } }
			SeedVars     = @{ SetupFiles = $script:SetupFiles; StoremanOfficeDbsFallbacks = $script:StoremanOfficeDbsFallbacks }
			OnComplete   = {
				try
				{
					Get_Store_And_Database_Info -WinIniPath $WinIniPath -SmsStartIniPath $SmsStartIniPath -StartupIniPath $StartupIniPath -SystemIniPath $SystemIniPath
					$script:StoreNumber = $script:FunctionResults['StoreNumber']
					$script:StoreName = $script:FunctionResults['StoreName']
					$script:SqlModuleName = $script:FunctionResults['SqlModuleName']
				}
				catch { }
			}
		}
		$script:StartupWarmupSteps += [pscustomobject]@{
			Label        = 'Refreshing node discovery...'
			Mode         = 'Job'
			FunctionName = 'Retrieve_Nodes'
			CallArgs     = { @{ StoreNumber = $script:StoreNumber; RefreshCache = $true } }
			SeedVars     = @{ SetupFiles = $script:SetupFiles; BasePath = $script:BasePath }
			DependentBodies = @{ Normalize_Sql_ConnectionString = ${function:Normalize_Sql_ConnectionString}.ToString() }
			OnComplete   = {
				try
				{
					Retrieve_Nodes -StoreNumber $script:StoreNumber | Out-Null
					$script:Nodes = $script:FunctionResults['Nodes']
					$script:LaneNumToMachineName = $script:FunctionResults['LaneNumToMachineName']
					Start_Lane_Protocol_Jobs -LaneNumToMachineName $script:LaneNumToMachineName -SqlModuleName $script:SqlModuleName
				}
				catch { }
			}
		}
		$script:StartupWarmupSteps += @(
			[pscustomobject]@{
				Label        = 'Loading lane DB cache...'
				Mode         = 'Job'
				FunctionName = 'Get_All_Lanes_Database_Info'
				CallArgs     = @{ RefreshCache = $true }
				SeedVars     = @{ SetupFiles = $script:SetupFiles }
				OnComplete   = { try { Get_All_Lanes_Database_Info | Out-Null } catch { } }
			},
			[pscustomobject]@{
				Label        = 'Loading table aliases...'
				Mode         = 'Job'
				FunctionName = 'Get_Table_Aliases'
				CallArgs     = @{ RefreshCache = $true }
				SeedVars     = @{ SetupFiles = $script:SetupFiles }
				OnComplete   = { try { $script:AliasToTable = Get_Table_Aliases } catch { } }
			},
			[pscustomobject]@{
				Label  = 'Generating SQL scripts...'
				Action = { try { Generate_SQL_Scripts -StoreNumber $script:StoreNumber | Out-Null } catch { } }
			},
			[pscustomobject]@{
				Label        = 'Installing SMS functions...'
				Mode         = 'Job'
				FunctionName = 'Install_FUNCTIONS_Into_SMS'
				CallArgs     = { @{ StoreNumber = $script:StoreNumber; OfficePath = $OfficePath; Silent = $true } }
				SeedVars     = @{ BasePath = $script:BasePath }
			},
			[pscustomobject]@{
				Label  = 'Starting test item job...'
				Action = {
					try
					{
						Get-Job | Where-Object { $_.Name -eq 'InsertTestItemJob' } |
						Where-Object { $_.State -in @('Completed', 'Failed', 'Stopped') } |
						Remove-Job -Force -ErrorAction SilentlyContinue

						# (-Name and -State cannot be combined on Get-Job: that threw before v2.7.0,
						#  so the test item job never started - filter the state instead)
						$runningInsertJob = Get-Job | Where-Object { $_.Name -eq 'InsertTestItemJob' } | Where-Object { $_.State -eq 'Running' } | Select-Object -First 1
						if (-not $runningInsertJob)
						{
							$fnBody = ${function:Insert_Test_Item}.ToString()
							$cs = $script:FunctionResults['ConnectionString']
							$dbs = $script:FunctionResults['DBSERVER']
							$dbn = $script:FunctionResults['DBNAME']
							$sqlModule = $script:FunctionResults['SqlModuleName']

							Start-Job -Name 'InsertTestItemJob' -ArgumentList $fnBody, $cs, $dbs, $dbn, $sqlModule -ScriptBlock {
								param (
									[string]$InsertTestItemBody,
									[string]$ConnectionString,
									[string]$DbServer,
									[string]$DbName,
									[string]$SqlModule
								)

								$script:FunctionResults = @{
									ConnectionString = $ConnectionString
									DBSERVER		 = $DbServer
									DBNAME		     = $DbName
									SqlModuleName    = $SqlModule
								}

								Set-Item -Path Function:\Insert_Test_Item -Value ([scriptblock]::Create($InsertTestItemBody))
								Insert_Test_Item -ConnectionString $ConnectionString -Silent | Out-Null
							} | Out-Null
						}
					}
					catch { }
				}
			},
			[pscustomobject]@{
				Label  = 'Adding scale credentials...'
				Action = {
					try
					{
						if (-not $script:StartupScaleCredStarted)
						{
							Add_Scale_Credentials -ScaleCodeToIPInfo $script:FunctionResults['WindowsScales']
							$script:StartupScaleCredStarted = $true
						}
					}
					catch { }
				}
			},
			[pscustomobject]@{
				Label  = 'Cleaning XE folder...'
				Action = { try { $script:ClearXEJob = Clear_XE_Folder }
					catch { } }
			},
			[pscustomobject]@{
				Label  = 'Preparing VNC exports...'
				Action = {
					if ($script:AutoExportVncOnLaunch)
					{
						try
						{
							Export_VNC_Files_For_All_Nodes `
														   -LaneNumToMachineName $script:FunctionResults['LaneNumToMachineName'] `
														   -ScaleCodeToIPInfo $script:FunctionResults['ScaleCodeToIPInfo'] `
														   -BackofficeNumToMachineName $script:FunctionResults['BackofficeNumToMachineName'] `
														   -AllVNCPasswords $script:FunctionResults['AllVNCPasswords'] `
														   -RunInBackground `
														   -SilentBackground
						}
						catch { }
					}
				}
			},
			[pscustomobject]@{
				Label  = 'Preparing hardware exports...'
				Action = {
					if ($script:AutoExportRemoteMachineInfoOnLaunch)
					{
						try
						{
							Get_Remote_Machine_Info `
													-RunInBackground `
													-SilentBackground `
													-UseAllAvailableNodes | Out-Null
						}
						catch { }
					}
				}
			},
			[pscustomobject]@{
				Label  = 'Checking quarterly maintenance...'
				Action = {
					if ($script:AutoQuarterlySystemHealthMaintenanceOnLaunch)
					{
						try
						{
							Start_Quarterly_System_Health_Maintenance `
																	  -IntervalMonths $script:SystemHealthMaintenanceIntervalMonths `
																	  -RetentionCount $script:SystemHealthMaintenanceRetentionCount `
																	  -SummaryRetentionLines $script:SystemHealthMaintenanceSummaryRetentionLines | Out-Null
						}
						catch { }
					}
				}
			}
		)
		$script:StartupWarmupTimer = New-Object System.Windows.Forms.Timer
		$script:StartupWarmupTimer.Interval = 450
		$script:StartupWarmupTimer.Add_Tick({
				if (-not $script:StartupWarmupSteps -or $script:StartupWarmupIndex -ge $script:StartupWarmupSteps.Count)
				{
					$script:StartupWarmupStatus = $null

					try
					{
						if ($script:StartupWarmupTimer)
						{
							$script:StartupWarmupTimer.Stop()
							$script:StartupWarmupTimer.Dispose()
							$script:StartupWarmupTimer = $null
						}
					}
					catch { }

					$script:StartupWarmupSteps = @()
					$script:StartupWarmupIndex = 0
					return
				}

				$step = $script:StartupWarmupSteps[$script:StartupWarmupIndex]

				try { $script:StartupWarmupStatus = if ($step -and $step.Label) { [string]$step.Label }
					else { $null } }
				catch { $script:StartupWarmupStatus = $null }

				# v2.6.9: 'Job' steps run in a background job - this tick only
				# starts or polls them, so the UI thread never waits on them.
				if ($step -and $step.Mode -eq 'Job')
				{
				if (-not $step.Job)
				{
						# CallArgs is a scriptblock that is evaluated at START time,
						# so the job always receives the current values (e.g. a
						# StoreNumber that step 1 just refreshed).
						$callArgs = @{}
						try
						{
							if ($step.CallArgs -is [scriptblock]) { $callArgs = & $step.CallArgs }
							elseif ($step.CallArgs) { $callArgs = $step.CallArgs }
						}
						catch { }
						$newJob = Start_Background_Function_Job -FunctionName $step.FunctionName -Label $step.Label -CallArgs $callArgs -SeedVars $step.SeedVars -ReturnVarNames $step.ReturnVarNames -DependentBodies $step.DependentBodies -OnComplete $step.OnComplete
						if ($newJob)
						{
							$step | Add-Member -NotePropertyName 'Job' -NotePropertyValue $newJob -Force
						}
						else
						{
							Write_Log ("Startup: warmup step '{0}' could not be started as a job" -f $step.Label) 'red'
							$script:StartupWarmupIndex++
						}
					}
					elseif ($script:BgfJobs -and $script:BgfJobs.ContainsKey($step.Job.Id))
					{
						# Job still registered: still running. The shared reaper
						# will merge the result and fire OnComplete for us.
					}
					else
					{
						# Job completed (reaper handled merge + OnComplete) - advance.
						$script:StartupWarmupIndex++
					}
					return
				}

				# Sync steps run inline - each one takes a few hundred ms at most.
				try
				{
					if ($step -and $step.Action)
					{
						$__warmupSw = [System.Diagnostics.Stopwatch]::StartNew()
						& $step.Action
						$__warmupSw.Stop()
						Write_Log ("Startup: warmup step '{0}' finished in {1:N1}s" -f $step.Label, $__warmupSw.Elapsed.TotalSeconds) 'blue' -FileOnly
					}
				}
				catch { }
				$script:StartupWarmupIndex++
			})
		$script:StartupWarmupTimer.Start()
	})

# ===================================================================================================
#                                   SECTION: Main - Show the Window
# ---------------------------------------------------------------------------------------------------
# Description:
#   Shows the main window (modal - the script waits here until it closes), then exits.
#   Unless -ShowConsole was given, the console window is hidden 400 ms after the main window
#   appears (so the "Script started" line is visible for a moment while it loads).
#
# Notes:
#   - 'exit' also ends the PowerShell session for irm | iex launches - intentional, the console
#     is hidden by then and would otherwise stay open invisibly.
#   - tests\Smoke.ps1 replaces the LAST '[void]$form.ShowDialog()' in the built file - keep it.
# ===================================================================================================

Write-Host "Script started" -ForegroundColor Green

if (-not $script:ShowConsole -and [Environment]::UserInteractive)
{
	try
	{
		$script:PostOpenConsoleHideTimer = New-Object System.Windows.Forms.Timer
		$script:PostOpenConsoleHideTimer.Interval = 400
		$script:PostOpenConsoleHideTimer.Add_Tick({
				try
				{
					$script:PostOpenConsoleHideTimer.Stop()
					$script:PostOpenConsoleHideTimer.Dispose()
					$script:PostOpenConsoleHideTimer = $null
				}
				catch { }
				try
				{
					$__consoleHandle = [ConsoleWindowHelper]::GetConsoleWindow()
					if ($__consoleHandle -ne [IntPtr]::Zero) { [void][ConsoleWindowHelper]::ShowWindow($__consoleHandle, 0) }
				}
				catch { }
			})
		$form.Add_Shown({
				try { if ($script:PostOpenConsoleHideTimer) { $script:PostOpenConsoleHideTimer.Start() } }
				catch { }
			})
	}
	catch { }
}

[void]$form.ShowDialog()

if ($script:ShowConsole) { Write-Host "Script closing..." -ForegroundColor Yellow }

exit

